INSERT INTO `aktifitas` VALUES (1, 91, 'Bali Startup Summit 2022', '2021-12-02', 'Inbis Unmas dan juga Tenant Unmas ikut berpartisipasi dalam kegiatan Bali Startup Summit sebagai ajang pertemuan tenant yng bergerak dalam bidang digital.', NULL, '2023-02-16 11:01:25', '2023-02-16 11:01:25');
INSERT INTO `aktifitas` VALUES (2, 91, 'Tenant Inbis terlibat dalam Expo bersama Hipmi Kota Denpasar', '2022-07-21', 'Tenant Inbis Unmas terpilih utk ikut berpartisipasi dalm kegiatan Expo yang digelar oleh HIPMI Kota Denpasar. Kesempatan ini dipakai untuk memasarkan produk mahasiswa yang adalah tenant Inbis.', '[\"public\\/foto-aktivitas\\/63edab4f579e6.jpg\"]', '2023-02-16 11:04:31', '2023-02-16 11:04:31');
INSERT INTO `aktifitas` VALUES (4, 40, 'Incubator\'s Day 2022 IBT Universitas Tanjungpura', '2022-11-22', 'NCUBATOR\'S DAY dirancang agar bisa memberikan dampak kebaikan serta berkelanjutan untuk tumbuh-kembang usaha lokal baik yang berasal dari ide kreatif maupun yang berbasis riset inovasi dalam rangka hilirisasi produk unggulan UNTAN.', '[\"public\\/foto-aktivitas\\/63f43c047ec1a.jpg\"]', '2023-02-21 10:35:32', '2023-02-21 10:37:26');
INSERT INTO `aktifitas` VALUES (5, 40, 'Incubate 2022', '2022-10-17', 'Workshop Intensif Manajemen Bisnis bertajuk INCUBATE, dihelat oleh IBT UNTAN sebagai bagian penting dalam program inkubasi bisnis tenant tahun 2022. INCUBATE dilaksanakan selama 2 hari, pada tanggal 15-16 Oktober 2022 bertempat di Ruang Ramin, Mercure Hotel Pontianak. Kegiatan ini diikuti oleh 6 startup yang akan masuk dalam tahap inkubasi bisnis, yaitu: Pinawaste, Sampah Market, Serpi, Sekat Kanal, Bio-Greenfil dan Sajada Digital.', '[\"public\\/foto-aktivitas\\/63f43c5da0dc3.jpg\"]', '2023-02-21 10:37:01', '2023-02-21 10:37:01');
INSERT INTO `aktifitas` VALUES (6, 200, 'Pelatihan Barista dan Usaha Warung Kopi', '2022-10-03', 'Pelatihan ini diberikan bagi tenant - tenant IBTI yang fokus mengolah produk kopi untuk meningkatkan skill/kompetensi yang lebih terukur', '[\"public\\/foto-aktivitas\\/63f43c8a3cb01.jpeg\",\"public\\/foto-aktivitas\\/63f43c8a3cf41.jpeg\"]', '2023-02-21 10:37:46', '2023-02-21 11:13:12');
INSERT INTO `aktifitas` VALUES (7, 40, 'Untan Start Up Bootcamp', '2022-09-17', 'Seluruh rangkaian kegiatan UNTAN STARTUP BOOTCAMP (USB) 2022 telah selesai dilaksanakan. 10 Finalis mengikuti beberapa tahapan yang telah diprogramkan. Dimulai dari INTENSIVE BUSINESS WORKSHOP yang dilaksanakan pada 17-18 September 2022 di Ruang Teater 2 Gedung Konferensi UNTAN. Workshop ini berisi beragam materi manajemen bisnis komprehensif. Para finalis diajak untuk merasakan pengalaman baru dalam workshop dengan LEARNING JOURNEY yang di desain tim IBT UNTAN. Selanjutnya, brainstorming lebih dalam tentang bisnis hadir dalam sesi EPIC BUSINESS MINDSET dan THE POWER OF VALIDATION.', '[\"public\\/foto-aktivitas\\/63f5c458de126.jpg\"]', '2023-02-22 14:29:28', '2023-02-22 14:29:28');
INSERT INTO `aktifitas` VALUES (8, 158, 'Penandatanganan dan Serah Terima Gedung', '2022-12-01', 'Penandatanganan dan serah terima Gedung eks Gapensi atau KADIN yang beralamat di Jl. Mayjend Sungkono No. 26B Selabaya, Kalimanah, Purbalingga antara Ketua KADIN Purbalingga dengan Pengelola Inkubator Bisnis Tuka Tuku Purbalingga.', '[\"public\\/foto-aktivitas\\/63fc1c67acefc.jpeg\",\"public\\/foto-aktivitas\\/63fc1c67ad1c5.jpeg\",\"public\\/foto-aktivitas\\/63fc1c67ad362.jpeg\"]', '2023-02-27 09:58:47', '2023-02-27 09:58:47');
INSERT INTO `aktifitas` VALUES (9, 158, 'Perlombaan Inovasi Produk Olahan Nanas dan Makaroni Keju Tahapan Wawancara', '2022-12-23', 'Dalam Rangka Hari Jadi Kabupaten Purbalingga, Pemerintah Daerah mengadakan serangkaian acara. Tak luput Inkubator Bisnis Tuka Tuku Purbalingga yang didukung oleh Dinas Koperasi dan UMKM ikut memeriahkan dengan mengadakan Perlombaan Olahan Nanas dan Makaroni Keju guna menyaring tenant unggulan. Melalui beberapa aspek yang menjadi bahan penilaian, terpilihlah 6 pemenang yang kemudian di tindaklanjuti dengan tahapan wawancara dan kemudian penandatanganan perjanjian kerjasama tenant.', '[\"public\\/foto-aktivitas\\/63fc26d2943f7.jpeg\"]', '2023-02-27 10:06:42', '2023-02-27 10:43:14');
INSERT INTO `aktifitas` VALUES (10, 158, 'Rapat Kordinasi Penentuan Arah dan Goal Inkubator Bisnis Tuka Tuku Purbalingga', '2022-11-04', 'Rapat kordinasi penentuan arah dan goal Inkubator Bisnis Tuka Tuku Purbalingga bersama tim pengelola, setelah sebelumnya didahului dengan studi tiru ke Inkubstor UNY Yogyakarta, UII Yogyakarta, Inwinov Bapelitbangda Prov. Jateng dan Inkubator Sekolah Tinggi Teknologi Kulit Yogyakarta.\r\nDalam rakor tersebut Ibu Sari menjelasakan hasil kunjungan ke Yogyakarta minggu lalu. Adapun hasil rapat adalah arah inkubator fokus pada pengembangan produk dan pemasaran produk unggulan Purbalingga.', '[\"public\\/foto-aktivitas\\/63fc26f18fd55.jpeg\"]', '2023-02-27 10:36:33', '2023-02-27 10:43:45');
INSERT INTO `aktifitas` VALUES (11, 158, 'Rekrutmen Awal untuk Tenant Inkubator Bisnis Tuka Tuku Purbalingga', '2022-11-11', 'Rapat perdana perekrutan tenant Inkubator Bisnis Tuka-Tuku Purbalingga, dalam rapat perdana dengan tenant tersebut adapun beberapa hal yang disampaikan yaitu sosialisasi dan arah tujuan diadakannya Inkubator Bisnis Tuka-Tuku Purbalingga serta perekrutan awal untuk tenant.', '[\"public\\/foto-aktivitas\\/63fc2670828bb.jpeg\"]', '2023-02-27 10:41:36', '2023-02-27 10:41:36');
INSERT INTO `aktifitas` VALUES (12, 40, 'Workhsop & Kick Off Klinik Inovasi Bersama', '2022-10-06', 'Badan Perencanaan Pembangunan Daerah (BAPPEDA) Kota Pontianak melalui bidang Penelitian dan Pengembangan (Litbang) menjalin kerja sama peningkatan inovasi daerah dengan Pusat Pengembangan Inovasi dan Inkubator Bisnis Teknologi Universitas Tanjungpura (PPIIBT UNTAN) melalui hadirnya Klinik Inovasi Tematik Bersame \"KITE BISE\". Klinik Inovasi ini akan jadi ruang kolaborasi dan pemantapan inovasi perangkat daerah Kota Pontianak dalam meningkatkan pelayanan kepada masyarakat.', '[\"public\\/foto-aktivitas\\/63fc2900238e8.jpg\"]', '2023-02-27 10:52:32', '2023-02-27 10:52:32');
INSERT INTO `aktifitas` VALUES (13, 40, 'IBT Untan Raih Top Challenger Asia Pacific 2021 - 2022', '2023-01-24', 'GHENT, BELGIA, 24 Januari 2023 - IBT UNTAN diakui sebagai Top Challenger Asia Pacific oleh \"UBI GLOBAL - The Innovation Intelligence Company and Community\" yang berbasis di Stockholm, yang terkenal sebagai lembaga penilaian serta pemetaan inkubator dan akselerator bisnis dunia. Rilis TOP Challenger ini adalah hasil dari penilaian World Benchmark Study 2021-2022 yang diikuti oleh IBT UNTAN.\r\n\r\nPencapaian Top Challenger Asia Pacific yang dinilai oleh UBI Global ini bermakna bahwa IBT UNTAN menunjukkan nilai luar biasa bagi perkembangan startup binaan, nilai untuk ekosistem lokal, dan daya tarik keseluruhan sebagai sebuah organisasi. \"Mengikuti pendekatan berbasis data yang ketat, kami menilai dan membandingkan organisasi inkubasi di seluruh dunia,\" kata Joshuah Sowah, Kepala Riset di UBI Global. \"Studi kami selaras dengan berbagai aspek ekosistem inkubasi internasional dan menggambarkan tantangan dan peluang kritis yang dihadapi oleh organisasi yang berpartisipasi.\"', '[\"public\\/foto-aktivitas\\/63fc295f727e7.png\"]', '2023-02-27 10:54:07', '2023-06-20 13:28:06');
INSERT INTO `aktifitas` VALUES (14, 158, 'Peresmian Gedung Inkubator Bisnis Tuka Tuku Purbalingga', '2023-01-16', 'Persis di sebelah Kantor Dinas Koperasi dan UKM Kabupaten Purbalingga, yang dulunya Gedung Gapensi sekarang sudah menjadi kantor pelayanan Inkubator Bisnis Tuka-Tuku Purbalingga, alhamdulilah pada tanggal 16 Agustus 2023telah dilaksanakan peresmian gedung, semoga dengan adanya Inkubator Bisnis Tuka-Tuku dapat lebih mengembangkan UMKM Kabupaten Purbalingga ke arah yang lebih baik lagi.', '[\"public\\/foto-aktivitas\\/63fc29bb228b3.jpg\",\"public\\/foto-aktivitas\\/63fc29bb2311b.jpg\",\"public\\/foto-aktivitas\\/63fc29bb2398b.jpg\"]', '2023-02-27 10:55:39', '2023-02-27 10:55:39');
INSERT INTO `aktifitas` VALUES (15, 158, 'Narasumber Sosialisasi NON PERDA \"Peluang dan Tantangan UMKM Menyongsong Resesi Ekonomi 2023\"', '2023-01-17', 'Debut pertama Pengelola dan Manajer Inkubator Bisnis Tuka Tuku Purbalingga sebagai salah satu narasumber di acara Sosialisasi NON PERDA \"Peluang dan Tantangan UMKM Menyongsong Resesi Ekonomi 2023\" yang di adakan oleh Dewan Perwakilan Rakyat Daerah Provinsi Jawa Tengah pada tanggal 17 Januari 2023 di Purbalingga', '[\"public\\/foto-aktivitas\\/63fc2da583987.jpeg\"]', '2023-02-27 11:12:21', '2023-02-27 11:12:21');
INSERT INTO `aktifitas` VALUES (16, 158, 'Tim Verifikasi Dinas Koperasi dan UKM Provinsi Jawa Tengah', '2023-01-18', 'Kunjungan dari Tim Verifikasi Diskop Provinsi Jawa Tengah, terkait program fasilitasi inkubator dan tenant. Pada tanggal 18 Januari 2023 TIM Verifikasi mengecek bagaimana perkembangan dan persiapan Inkubator Bisnis Tuka Tuku Purbalingga sejauh ini. Kemudian dilanjutkan berkunjung ke Koperasi Mitra Lira Perwira yang merupakan salah satu tenant yang beralamat di Jl. raya Kajongan - Bojongsari RT 02 RW 06, Purbalingga', '[\"public\\/foto-aktivitas\\/63fc3ade9cfd6.jpeg\",\"public\\/foto-aktivitas\\/63fc3ade9d287.jpeg\"]', '2023-02-27 12:08:46', '2023-02-27 12:08:46');
INSERT INTO `aktifitas` VALUES (17, 158, 'Koperasi Mitra Lira Perwira', '2023-01-17', 'Koperasi di Inkubasi?\r\nInkubasi bisnis adalah suatu program yang di tawarkan oleh berbagai lembaga yang tujuannya untuk mendukung usaha pemula. Dukungan tersebut biasanya berupa bimbingan dan penyediaan ruang untuk mengembangkan ide yang akan berjalan selama satu sampai dua tahun.\r\nSelasa, 17 Januari 2023 Tenaga Pendamping Koperasi melaksanakan pendampingan terkait inkubasi bisnis yang salah satu calon tenannya adalah Koperasi Produsen Mitra Lira Perwira yang memiliki nomor badan hukum AHU-0005664.AH.01.29.TAHUN 2022. Koperasi tersebut beralamat di Jl. raya Kajongan - Bojongsari RT 02 RW 06, Purbalingga. Pada kesempatan ini Tenaga Pendamping Koperasi bertemu dengan Bapak Anwar Faizal selalu ketua koperasi, beserta pengurus koperasi lainnya.\r\nAdapun pendampingan yang dilakukan oleh Tenaga Pendamping Koperasi seperti pembuatan NPWP koperasi, melengkapi kelengkapan administrasi koperasi dan pembuatan neraca.\r\nDengan adanya inkubasi bisnis ini koperasi diharapkan dapat mengembangkan usahanya agar lebih maju dan lebih mandiri.', '[\"public\\/foto-aktivitas\\/63fd525546299.jpg\",\"public\\/foto-aktivitas\\/63fd525546567.jpg\"]', '2023-02-27 13:39:16', '2023-02-28 08:01:09');
INSERT INTO `aktifitas` VALUES (18, 158, 'Ngelapak di Purbalingga Expo', '2022-12-15', 'Inkubator Bisnis Tuka Tuku melihat peluang besar pada acara Hari Jadi Purbalingga dengan di selenggarakannya Purbalingga Expo mulai tanggal 15 Desember sampai dengan 18 Desember 2023. Peluang tersebut dimanfaatkan untuk sosialisasi pengenalan tentang Inkubator Bisnis Tuka Tuku sembari memasarkan produk olahan nanas dan makaroni keju milik tenant-tenant Inkubator Bisnis.', '[\"public\\/foto-aktivitas\\/63fc54fe2cbbc.jpeg\",\"public\\/foto-aktivitas\\/63fc54fe2ceb9.jpeg\",\"public\\/foto-aktivitas\\/63fc54fe2d021.jpeg\",\"public\\/foto-aktivitas\\/63fc54fe2d145.jpeg\",\"public\\/foto-aktivitas\\/63fc54fe2d2a3.jpeg\"]', '2023-02-27 14:00:14', '2023-02-27 14:00:14');
INSERT INTO `aktifitas` VALUES (19, 158, 'Launching Inkubator Bisnis Tuka Tuku dan Penandatanganan Perjanjian Kerjasama', '2023-02-20', '\"YOU NEVER WALK ALONE\" itu kira-kira gambarannya Inkubator Bisnis Tuka Tuku yang belum bisas melangkah sendiri. Alhamdulillah banyak yang menemani untuk bekerjasama,  dan akhirnya tertuang dalam Perjanjian Kerja Sama (PKS) antara Inkubator Bisnis Tuka Tuku Purbalingga dengan rekan-rekan. Perjanjian Kerjasama Tahap 1 dengan  Fak. Pertanian Unsoed, Fak. Ekonomi Bisnis Unsoed, AMIKOM Purwokerta, KADIN Purbalingga, PLUT Purbalingga, BPR BKK Purbalingga dan Rumah BUMN Purbalingga. Hadir juga 14 tenant, yang terdiri dari 7 tenant kurasi, 6 tenant dari hasil lomba inovasi dan 1 tenant koperasi produksi sapu glagah.', '[\"public\\/foto-aktivitas\\/63fc59fa33016.jpeg\",\"public\\/foto-aktivitas\\/63fc59fa332ee.jpeg\",\"public\\/foto-aktivitas\\/63fc59fa33409.jpeg\",\"public\\/foto-aktivitas\\/63fc59fa334eb.jpeg\",\"public\\/foto-aktivitas\\/63fc59fa33607.jpeg\"]', '2023-02-27 14:21:30', '2023-02-27 14:21:30');
INSERT INTO `aktifitas` VALUES (20, 158, 'Peningkatan Kapasitas Produksi', '2023-02-25', 'Berawal dari FGD perekrutan tenant pada bulan November 2022, Inkubator Bisnis Tuka Tuku Purbalingga diberi masukan agar tenant kami tidak hanya perorangan tapi juga koperasi. Karena misi inkubator kami adalah mengemban amanat pengembangan produk unggulan, salah satunya sapu glagah, maka kami membidik kelompok pelaku usaha sapu glagah Lira Perwira. Dalam FGD pendampingan, mereka butuh pembentukan koperasi, pelatihan untuk meningkatkan kapasitas produksi, pendampingan ekspor dan pembiayaan. Alhamdilillah, berkat kerja sama dengan Pendamping Koperasi, pertengahan Januari 2023 terbentuklah Koperasi Mitra Lira Perwira dan sampe saat ini terus dilakukan pendampingan koperasi. Dengan didukung dana DAK 2023 yang sudah disusun pada bulan Desember 2022, akhirnya kami dapat melaksanakan pelatihan peningkatan kapasitas produksi sapu glagah. Kegiatan berlangsung selama 3 hari mulai dari tanggal 25 Februari sampai dengan 27 Februari 2023. Tak luput Manager Inkubator Tuka Tuka Purbalingga yaitu bapak Sugeng Rianto, SH., M.Si turut serta memberikan materi Kewirausahaan.', '[\"public\\/foto-aktivitas\\/63fd5b4d5240c.jpeg\",\"public\\/foto-aktivitas\\/63fd5b4d5269a.jpeg\",\"public\\/foto-aktivitas\\/63fd5b4d527d6.jpeg\",\"public\\/foto-aktivitas\\/63fd5b4d52bf0.jpeg\",\"public\\/foto-aktivitas\\/63fd5b4d52e79.jpeg\"]', '2023-02-28 08:39:25', '2023-02-28 08:39:25');
INSERT INTO `aktifitas` VALUES (21, 158, 'Roadshow Calon Stakeholder', '2022-12-01', 'Bulan Desember ini kami melaksanakan Roadshow ke Stakeholder calon-calon mitra Inkubator Bisnis Tuka Tuku Purbalingga seperti perbankan, perguruan tinggi, lembaga bisnis, instansi pemerintah dan swasta. Hari ini tanggal 1 Desember 2022 Tim Inkubator Bisnis Tuka Tuku akan bertemu dg Ketua KADIN Purbalingga Bapak Doni yang juga seorang pengusaha,  Kedua belah Pihak sepakat untuk bekerja sama dalam hal  pemasaran, akses pasar dan pengembangan SDM untuk tenant. Selain itu, Tim Inkubator Bisnis Tuka Tuku Purbalingga bertemu dengan mas Yuli Rusnanto pemilik Cafe Van Bothor sebelah timur SMP Negeri 2 Purbalingga, sekaligus praktisi kuliner kreatif Purbalingga.  Dari pertemuan ini membuka peluang kerja sama pemasaran produk- produk para tenant di cafe mas Yuli Rusnanto sekaligus meminta yang bersangkutan untuk menjadi juri Lomba Inovasi dan Kreasi  Pangan yang akan diselenggarakan Dinas Koperasi dan UKM Kabupaten Purbalingga selaku pemilik anggaran dan Inkubator Bisnis Tuka Tuku selaku pelaksana. Ajang perlombaan ini juga merupakan tahapan seleksi tenant-tenant tambahan untuk Inkubator Bisnis Tuka Tuku Purbalingga', '[\"public\\/foto-aktivitas\\/63fd6dd6afec0.jpeg\"]', '2023-02-28 09:58:30', '2023-02-28 09:58:30');
INSERT INTO `aktifitas` VALUES (22, 109, 'Pendampingan Tenant  Branding dan Packaging', '2019-07-13', 'Sabtu tanggal 13 juli 2019, coaching branding dan packaging oleh Bapak Wandah Wibawanto S.sn., M.Ds dari UNNES untuk Tenant Smartlight dan TSC di Kantor IKITAS.', '[\"public\\/foto-aktivitas\\/63fd750c65fa9.jpg\"]', '2023-02-28 10:29:16', '2023-02-28 10:29:16');
INSERT INTO `aktifitas` VALUES (23, 109, 'Mentoring dan Pendampingan Tenant TSC', '2019-07-12', 'Hasil yang di capai :\r\n1. Laporan Keuangan\r\n2. Pembuatan Billing & Pajak \r\n3. Packaging \r\n4. Nota penjualan', '[\"public\\/foto-aktivitas\\/63fd76a16a40f.jpg\"]', '2023-02-28 10:36:01', '2023-02-28 10:36:01');
INSERT INTO `aktifitas` VALUES (24, 109, 'Mentoring dan Pendampingan Tenant Smartlight', '2019-05-16', 'Hasil yang dicapai :\r\n1. Desain Kemasan\r\n2. Laporan Keuangan\r\n3. Pendampingan Produksi\r\n4. Pembuatan nota', '[\"public\\/foto-aktivitas\\/63fd77995486f.jpg\"]', '2023-02-28 10:40:09', '2023-02-28 10:40:09');
INSERT INTO `aktifitas` VALUES (25, 158, 'Studi Banding TIM Inkubator Bisnis Tuka Tuku ke UII dan UNY', '2022-10-09', 'Kunjungan Tim 1 Inkubator Bisnis Tuka Tuku ke Inkubator UII dan UNY bertujuan untuk studi komparatif agar meningkatkan kesiapan dalam pembentukan Inkubator Bisnis Tuka Tuku Purbalingga. tujuan lainnya adalah eskalasi referensi karena ini merupakan hal baru dan semoga pembaruan yang dilakukan dapat meningkatkan mutu kualitas UMKM di Kabupaten Purbalingga', '[\"public\\/foto-aktivitas\\/63febb5c3a973.jpeg\",\"public\\/foto-aktivitas\\/63febb5c3abc6.jpeg\",\"public\\/foto-aktivitas\\/63febb5c3ad10.jpeg\",\"public\\/foto-aktivitas\\/63febb5c3ae26.jpeg\"]', '2023-03-01 09:37:42', '2023-03-01 09:41:32');
INSERT INTO `aktifitas` VALUES (26, 158, 'Supervisi dan Monitoring Perkembangan Inkubator Area Purbalingga dan Banyumas', '2022-09-28', 'Tim Inkubator Bisnis Tuka Tuku Purbalingga melakukan supervisi dan monitoring perkembangan Inkubator area Purbalingga dan Banyumas oleh Mentor Inkubator Bisnis Kementerian Koperasi dan UKM bapak Wisono, Pertemuan dilaksanakan di Universitas Muhammadiyah Purwokerto. Dari kegiatan tersebut TIM Inkubator Bisnis Tuka Tuku Purbalingga banyak mendapat masukan terkait dokumen-dokumen pendirian Inkubator Bisnis', '[\"public\\/foto-aktivitas\\/63fec0682b399.jpg\",\"public\\/foto-aktivitas\\/63fec0682b59e.jpg\"]', '2023-03-01 10:03:04', '2023-03-01 10:03:04');
INSERT INTO `aktifitas` VALUES (27, 158, 'Kunjungan TIM II Inkubator Bisnis Tuka Tuku ke Inkubator Bisnis INWINOV BAPPEDA Provinsi Jawa Tengah', '2022-10-20', 'Ibarat bayi yg baru lahir dan mulai belajar berjalan, TIM kami terus bergerak mencari referensi kemana arah tujuan inkubator kami.\r\nSetelah Tim 1 mengunjungi UII dan UNY, hari ini Tim 2 bergerak ke Inwinov Inkubator Wirausaha Inovasi dibawah pengelolaan Bapelitbangda Prov. Jateng. Pokoke nekad gawe inkubator demi UMKM Kabupaten Purbalingga!!', '[\"public\\/foto-aktivitas\\/63fec20c2eee6.jpg\"]', '2023-03-01 10:10:04', '2023-03-01 10:10:04');
INSERT INTO `aktifitas` VALUES (28, 158, 'Kunjungan Tim Monev dari Kementerian Koperasi dan UKM terkait Kesiapan Program Inkubator', '2022-10-21', 'Jumat, 21 Oktober 2022 Monitoring dari KemenkopUkm yg dipimpin Bpk. Luarentius ke calon lokasi gedung Inkubator Bisnis Tuka Tuku.', '[\"public\\/foto-aktivitas\\/63fec3baa8219.jpg\",\"public\\/foto-aktivitas\\/63fec3baa8917.jpg\",\"public\\/foto-aktivitas\\/63fec3baa8c43.jpg\",\"public\\/foto-aktivitas\\/63fec3baa8edd.jpeg\"]', '2023-03-01 10:17:14', '2023-03-02 08:36:25');
INSERT INTO `aktifitas` VALUES (29, 158, 'Studi Komparatif terkait Inkubator Bisnis di Kementerian Politeknik ATK Yogyakarta', '2022-10-28', 'TIM III bersama Dinas Koperasi dan UKM melaksanakan Studi Komparatif terkait Inkubasi Bisnis di Kementerian Politekhnik ATK yogyakarta. Dalam kegiatan ini kami menemui Direktur Politekhnik ATK yang di wakilan oleh Pembantu Direktur, Bapak Dr. Ir R Lukas Martindo Satrio Ari Wibowo, S.Pt, MP, IPU, ASEAN. Harapannya dengan adanya kunjungan ini Inkubator Bisnis Tuka Tuku dan Dinas Koperasi dan UKM Purbalingga bisa mengadopsi ilmu dalam mengembangkan bisnis terutama untuk program inkubasi bisnis yang akan di laksanakan DINKOPUKM yang ada di Purbalingga.', '[\"public\\/foto-aktivitas\\/63fec5e82dfbe.jpg\"]', '2023-03-01 10:26:32', '2023-03-01 10:26:32');
INSERT INTO `aktifitas` VALUES (30, 158, 'Monitoring Tenant Produksi Nanas', '2022-11-15', 'setelah di lakukannya FGD terkait kemana arah dan tujuan Inkubator Bisnis Tuka Tuku Purbalingga, tahap selanjutnya Tim mulai bergerak dengan Penandatanganan PKS dan di lanjut monitoring produksi tenant olahan nanas di kecamatan Karangreja lebih tepatnya desa Siwarak.', '[\"public\\/foto-aktivitas\\/63fec7f417306.jpeg\",\"public\\/foto-aktivitas\\/63fec7f417789.jpeg\",\"public\\/foto-aktivitas\\/63fec7f417a16.jpeg\",\"public\\/foto-aktivitas\\/63fec7f417c31.jpeg\",\"public\\/foto-aktivitas\\/63fec7f417d50.jpeg\"]', '2023-03-01 10:35:16', '2023-03-01 10:35:16');
INSERT INTO `aktifitas` VALUES (31, 7, 'Demoday Investasi StartUp Inovatif', '2022-12-06', 'Gelaran acara yang berlangsung secara hybrid di Hotel Swiss-Belinn Manyar ini dihadiri langsung oleh Wakil Rektor IV Bidang Riset, Inovasi, Kerjasama, dan Kealumnian ITS Bambang Pramujati ST MSc Eng PhD, Direktur Inovasi dan Kawasan Sains Teknologi (DIKST) ITS Agus Muhammad Hatta PhD, Manager Senior Inkubator dan Layanan Bisnis Inovatif (ILBI) ITS Baroto Tavip Indrojarwo MSi, Manager Senior Akses Permodalan ITS Dr Machsus MT, serta jajaran pimpinan ITS terkait.\r\n\r\nAcara tersebut mempertemukan startup inovatif buatan mahaiswa ITS dengan calon investor. Sebelas startup terpilih dari ILBI ITS akan mempromosikan berbagai produk dan jasa inovatifnya. Gelaran ini merupakan rangkaian acara dari program Calon Perusahaan Pemula Berbasis Teknologi (CPPBT) oleh Direktorat Jenderal Pendidikan Tinggi, Riset, dan Teknologi (Ditjen Diktiristek).\r\nPendiri startup CoFilm, Royyan Wafi Pujianto, presentasi produk inovatifnya berupa pelapis antivirus sebagai disinfektan permanen di hadapan para calon investor dalam Demoday Startup\r\n\r\nDalam hal ini, Baroto menjelaskan, Demoday adalah ajang presentasi bagi para startup untuk memperkenalkan produk maupun jasanya, sekaligus untuk mempertemukan para startup dengan para calon investor. “Acara ini biasanya diadakan pada tiap akhir masa inkubasi startup,” imbuhnya.\r\n\r\nLebih lanjut Baroto menegaskan, Demoday ini merupakan kesempatan emas bagi para pendiri startup untuk mengenalkan produknya dan bertemu dengan para calon investor. “Dalam ajang demoday ini diharapkan terjalin business matching di antara startup dengan investor, terkait akses permodalan, pemasaran, dan potensi sinergi bisnis lainnya,” ujarnya.\r\n\r\nAdapun tiga startup dari ITS yang mendapat pendanaan dari CPPBT antara lain adalah SFPS, Tridiku, dan Lobstion. Tidak hanya itu, kesempatan juga terbuka bagi startup lainnya seperti CoFilm, CastForm, Tradeco, Cekka Studio, Kebon.ID, HOMEi, WeListen, dan Manufaktur Energi Nusantara (MEN). “Para startup ini nantinya akan mempresentasikan pitch deck mereka dan memamerkan prototipenya di hadapan para juri dan calon investor,” papar Baroto.\r\nPendiri startup Lobstion, Wahyu Febianto, saat presentasi produk inovatifnya di bidang teknologi berbasis Internet of Things (IoT) guna memenuhi kebutuhan budidaya udang lobster\r\n\r\nSFPS merupakan startup yang menghasilkan produk inovatif berupa lampu morse cerdas otomatis dan terenkripsi untuk kapal perang berbasis image processing. Kemudian, Tridiku dengan produk inovatifnya berupa 3D Printer sebagai penyokong industri kreatif. Lobstion (Crustea) dengan produk inovatifnya di bidang teknologi berbasis Internet of Things (IoT) guna memenuhi kebutuhan budidaya udang lobster.\r\n\r\nAdapun CoFilm merupakan startup yang menciptakan produk inovatif pelapis antivirus sebagai disinfektan permanen. CastForm dengan produk inovatifnya berupa gips ortopedi (castform) yang siap pakai dengan pola lipat unik. Sedangkan Tradeco dengan produk inovatifnya berupa aplikasi transaksi perdagangan internasional yang mudah dan aman untuk UKM dan importer.\r\n\r\nSelanjutnya, Cekka Studio merupakan startup yang menciptakan produk inovatif di bidang inovasi desain produk kriya yang mengedepankan konsep sustainability. Sedang Kebon.ID dengan produk inovatifnya di bidang industri agrikultur urban, dan HOMEi dengan produk inovatif yang berfokus pada pekerjaan hunian dengan sistem manajemen kontruksi.\r\nJajaran pimpinan ITS bersama para calon investor dan para pelaku bisnis besar usai gelaran Demoday Startup\r\n\r\nSedangkan WeListen adalah startup yang menciptakan produk inovatif berupa aplikasi untuk menjadi wadah bagi klien yang sedang mengalami depresi untuk berbagi cerita dengan psikolog dan pendengar aktif dalam upaya mengurangi rasa depresi. Terakhir, MEN dengan produk inovatifnya berupa in wheel hub motor yang akan digunakan sebagai power train kendaraan listrik.\r\n\r\nBerbagai pengusaha, asosiasi, instansi kedinasan, komunitas inkubator, dan industri terkait telah diundang untuk memeriahkan acara tersebut. Seperti Founder Quarto Group, Direktur Utama Teluk Lamong, Direktur Utama PT Sarana Jatim Ventura, CEO Cak Eko Group, Pengusaha Tambak Udang Sidoarjo, Direktur Utama PDAM Surabaya, Kamar Dagang dan Industri (Kadin) Jatim, Himpunan Pengusaha Muda Indonesia (HIPMI) Jatim, dan masih banyak lagi.\r\n\r\nSelain Demoday, terdapat pula talkshow bertajuk Investasi Startup Inovatif yang mendapuk para pelaku bisnis besar sebagai narasumber. Di antaranya, CEO Cak Eko Group Henky Eko Sriyantono ST MT, Direktur Utama PT Terminal Teluk Lamong Faruq Hidayat ST MMT, Direktur Utama PT Sarana Jatim Ventura Tri Agus Darmawan SE, dan Direktur Utama PDAM Surabaya Ir Arief Wisnu Cahyono. Beberapa di antaranya merupakan alumni ITS yang sukses mengembangkan usahanya.', NULL, '2023-03-01 11:29:17', '2023-03-01 11:29:17');
INSERT INTO `aktifitas` VALUES (32, 158, 'Tindak lanjut Perjanjian Kerja dengan Fakultas Ekonomi dan Bisnis UNSOED', '2023-02-28', 'Selasa 28 Februari 2023, Pengelola Inkubator Bisnis Tuka Tuku Purbalingga berkunjung kembali ke Universitas Jenderal Soedirman khususnya Fakultas Ekonomi dan Bisnis untuk menindaklanjuti Perjanjian Kerja Sama. Tim FEB UNSOED meminta beberapa berkas untuk dipersiapkan guna meninjau lebih lanjut perkembangan Inkubator Bisnis Tuka Tuku', '[\"public\\/foto-aktivitas\\/640023685d4d2.jpeg\"]', '2023-03-02 11:17:44', '2023-03-02 11:17:44');
INSERT INTO `aktifitas` VALUES (33, 158, 'Bicang Hangat Bersama Bapak Wisono', '2023-02-26', 'Minggu, 26 Februari 2023, di tengah padatnya sebagai narasumber Sosialisasi Pendirian Lembaga Inkubator Kabupaten/Kota, Bapak Wisono, selaku mentor yang mewakili Kementrian Koperasi dan UKM meluangkan waktunya untuk berdiskusi tentang pendampingan sekaligus memonitoring sudah sejauh mana persiapan Lembaga Inkubator Batch Bali yang di hadiri oleh Inkubator Tuka Tuku Purbalingga, PIB Amikom, PIB Univ. Peradaban. Acara tersebut merupakan acara nonformal di luar jadwal monitoring yang dilaksanakan di lobi Hotel COR Purwokerto.', '[\"public\\/foto-aktivitas\\/64005e2587288.jpeg\",\"public\\/foto-aktivitas\\/64005e2587562.jpeg\"]', '2023-03-02 15:28:21', '2023-03-02 15:28:21');
INSERT INTO `aktifitas` VALUES (34, 158, 'Kunjungan dari Bea Cukai Purwokerto', '2023-02-28', 'Menindaklanjuti FGD kami dengan kelompok sapu Lira Perwira beberapa waktu yang lalu, salah satu kebutuhan tenant kami adalah pengetahuan tentang prosedur ekspor. Saat ini mereka sudah bisa ekspor tetapi masih dengan pihak ke 3. Keinginan mereka untuk bisa ekspor sendiri. Hari ini kami kedatangan Tim Bea Cukai Purwokerto untuk membicarakan bentuk kerja sama dengan Inkubator Tuka Tuku terkait chaneling dan pendampingan ekspor. Semoga awal bulan ini sudah bisa tanda tangan Perjanjian Kerja Sama, karena tenant sudah membutuhkan pendampingan', '[\"public\\/foto-aktivitas\\/6400624037aca.jpeg\",\"public\\/foto-aktivitas\\/6400624037d4c.jpeg\"]', '2023-03-02 15:45:52', '2023-03-02 15:45:52');
INSERT INTO `aktifitas` VALUES (35, 228, 'Open Recruitment Tenant Inkubator Bisnis Tahun 2023', '2023-02-02', 'Pengumuman recruitment tenan Inkubator Bisnis Politeknik AKA Bogor Tahun 2023', '[\"public\\/foto-aktivitas\\/6407e2be66f82.jpg\"]', '2023-03-08 08:19:58', '2023-03-08 08:19:58');
INSERT INTO `aktifitas` VALUES (36, 228, 'Penandatanganan MoU Inkubator Bisnis Poltek AKA dengan Tenant Terpilih Tahun 2022', '2023-03-06', 'Penandatanganan MoU Politeknik AKA Bogor dengan tenant terpilih Tahun 2022', '[\"public\\/foto-aktivitas\\/6407e3c11ed7b.jpg\"]', '2023-03-08 08:24:17', '2023-03-08 08:24:17');
INSERT INTO `aktifitas` VALUES (37, 228, 'Kunjungan Ke Dinas Koperasi UMKM Perdagangan Perindustrian Kota Bogor', '2023-03-02', 'Silaturahmi ke Dinas Koperasi UMKM Perdagangan dan perindustrian Kota Bogor terkait rencana kegiatan Inkubis Poltek AKA Bogor Th 2023', '[\"public\\/foto-aktivitas\\/6407e50912005.jpg\"]', '2023-03-08 08:29:45', '2023-03-08 08:29:45');
INSERT INTO `aktifitas` VALUES (38, 158, 'Kunjungan Kerja Ke Heterospace', '2023-03-07', 'Selasa, 7 Maret 2023, Tim Inkubator Bisnis Tuka Tuku Purbalingga melakukan kunjungan kerja ke Heterospace Semarang.', '[\"public\\/foto-aktivitas\\/64094b849a1db.jpeg\",\"public\\/foto-aktivitas\\/64094b849a40b.jpeg\",\"public\\/foto-aktivitas\\/64094b849a4cb.jpeg\"]', '2023-03-09 09:59:16', '2023-03-09 10:43:51');
INSERT INTO `aktifitas` VALUES (39, 14, 'Bootcamp KalselPreneurship 2022', '2022-10-20', 'Program Inkubasi Hybrid terus dilaksanakan kepada 40 tenant hasil kurasi dengan Kementerian Koperasi dan UKM tahun 2021 sebagai bentuk Roadmap Fasilitasi Pengembangan Tenant di era digital diharapkan mampu menjadi Super Smart Society, yang menyeimbangkan layanan melalui teknologi yang mampu mengintegrasikan dunia maya dan ruang fisik. Hal ini dibutuhkan mengingat disrupsi digital masih belum mencapai puncaknya dan akan terus terjadi.\r\n\r\nada 5 materi yang akan menjadi landasan dasar bagi UMKM menuju arah digital :\r\n🔥E-Payment\r\n🔥Digital Marketing\r\n🔥UMKM goes to MBIZ-Market\r\n🔥Packaging Design\r\n🔥Financial Statements', '[\"public\\/foto-aktivitas\\/640fc4482b1c2.jpg\",\"public\\/foto-aktivitas\\/640fc4482b596.jpg\",\"public\\/foto-aktivitas\\/640fc4482b6bb.jpg\",\"public\\/foto-aktivitas\\/640fc4482b7bb.jpg\"]', '2023-03-14 07:48:08', '2023-03-14 07:48:08');
INSERT INTO `aktifitas` VALUES (40, 14, 'Bootcamp KalselPreneurship 2022', '2022-10-21', 'Program Inkubasi Hybrid terus dilaksanakan kepada 40 tenant hasil kurasi dengan Kementerian Koperasi dan UKM tahun 2021 sebagai bentuk Roadmap Fasilitasi Pengembangan Tenant di era digital diharapkan mampu menjadi Super Smart Society, yang menyeimbangkan layanan melalui teknologi yang mampu mengintegrasikan dunia maya dan ruang fisik. Hal ini dibutuhkan mengingat disrupsi digital masih belum mencapai puncaknya dan akan terus terjadi. ada 5 materi yang akan menjadi landasan dasar bagi UMKM menuju arah digital : 🔥E-Payment 🔥Digital Marketing 🔥UMKM goes to MBIZ-Market 🔥Packaging Design 🔥Financial Statements', '[\"public\\/foto-aktivitas\\/640fc48da5cdc.png\",\"public\\/foto-aktivitas\\/640fc48da63d1.png\",\"public\\/foto-aktivitas\\/640fc48da69c0.png\",\"public\\/foto-aktivitas\\/640fc48da6f88.jpg\"]', '2023-03-14 07:49:17', '2023-03-14 07:49:17');
INSERT INTO `aktifitas` VALUES (41, 14, 'Workshop \"Akselerasi Izin Edar Produk UKM Banua\"', '2022-03-17', 'Inkubator Bisnis dan Teknologi (Inbitek) Borneo melaksanakan kegiatan Workshop dengan Tema \"AKSELERASI IZIN EDAR PRODUK UMKM BANUA\" yang dihadiri langsung oleh Ibu Ary Yustantiningsih, S.Si,. Apt. selaku Koordinator Kelompok Substansi Pemeriksaan dari Balai Besar BPOM Banjarmasin.', '[\"public\\/foto-aktivitas\\/640fc68a6652f.jpg\"]', '2023-03-14 07:57:46', '2023-03-14 07:57:46');
INSERT INTO `aktifitas` VALUES (42, 14, 'Promosi Produk Tenant Inkubator Bisnis dan Teknologi Borneo dalam Gelaran OPOP Kalsel 2022', '2022-08-11', 'Inkubator Bisnis dan Teknologi Borneo berkesempatan mengikuti gelaran OPOP Kalsel 2022, sebagai lembaga intermediasi bisnis milik Pemerintah Daerah, dengan menampilkan produk tenant inkubasi pilihan, dengan tujuan membuka pangsa pasar lebih luas, melihat kunjungan konsumen bukan hanya dari regional saja, namun juga dari luar regional Kalimantan.', '[\"public\\/foto-aktivitas\\/640fc886d030f.jpg\"]', '2023-03-14 08:06:14', '2023-03-14 08:06:14');
INSERT INTO `aktifitas` VALUES (43, 14, 'Temu Ramah dengan Asosiasi Inkubator Bisnis Indonesia', '2022-11-16', 'Sharing serta diskusi dengan Prof. Dr. Ir. Hadi Karia Purwadaria, M. Sc dilaksanakan dengan tujuan Penguatan Kelembagaan Inkubator Bisnis dan Teknologi Borneo sebagai Inkubator milik Pemerintah Daerah serta model inkubasi yang tepat untuk pembentukan kawasan hilirisasi industri dan inkubasi', '[\"public\\/foto-aktivitas\\/640fc9b123817.jpg\"]', '2023-03-14 08:11:13', '2023-03-14 08:11:13');
INSERT INTO `aktifitas` VALUES (44, 14, 'Kalsel Innovation Award 2022', '2022-09-09', 'Kalsel Innovation Award, merupakan Ekosistem Inovasi Daerah di Kalimantan Selatan, wadah bagi seluruh Innovator Inovasi Daerah untuk melaporkan hasil inovasinya, Inbitek Borneo merupakan bagian tidak terpisahkan dari hilir Kalsel Innovation Award sebagai wadah inkubasi yang memiliki tupoksi inkubasi dan scale-up Inovasi Daerah', '[\"public\\/foto-aktivitas\\/640fcb5206772.jpg\"]', '2023-03-14 08:18:10', '2023-03-14 08:18:10');
INSERT INTO `aktifitas` VALUES (45, 14, 'Rakornas Transformasi Digital Kementerian Koperasi dan UKM', '2022-03-28', '-', '[\"public\\/foto-aktivitas\\/640fcc3fea1de.png\"]', '2023-03-14 08:22:07', '2023-03-14 08:22:07');
INSERT INTO `aktifitas` VALUES (46, 14, 'Forum Nasional AIBI 2023', '2023-02-04', 'Forum Nasional Asosiasi Inkubator Bisnis Indonesia (AIBI) 2023', '[\"public\\/foto-aktivitas\\/640fcdb5680ec.jpg\"]', '2023-03-14 08:28:21', '2023-03-14 08:28:21');
INSERT INTO `aktifitas` VALUES (47, 14, 'Kalsel Innovation Award 2023', '2023-03-01', 'Wadah Inkubasi Ekosistem Inovasi Daerah', '[\"public\\/foto-aktivitas\\/640fce84d5249.png\"]', '2023-03-14 08:31:48', '2023-03-14 08:32:49');
INSERT INTO `aktifitas` VALUES (48, 36, 'Sosialisasi Program Pendanaan Calon Startup, Pra Startup, Startup Dan Workshop Pendaftaran Nomor Induk Berusaha (NIB)', '2023-03-10', 'Kegiatan ini bertujuan mendorong wirausaha - wirausaha muda untuk dapat mengembangkan bisnisnya. Diantaranya melalui kegiatan pendaftaran Nomor Induk Berusaha (NIB) yang mana NIB merupakan tanda pengenal bagi pelaku usaha yang dapat digunakan untuk mengajukan izin usaha dan izin komersial atau operasional.', '[\"public\\/foto-aktivitas\\/641175c1bddd4.JPG\"]', '2023-03-15 10:47:54', '2023-03-16 11:00:06');
INSERT INTO `aktifitas` VALUES (49, 36, 'Demoday Get Ready Growth Up Your Startup', '2022-11-08', 'Kegiatan Demoday merupakan ajang bagi para startup/bisnis rintisan untuk memperkenalkan produk maupun jasanya, sekaligus untuk mempertemukan para startup dengan mitra potensial yang akan mendukung dan mempercepat perkembangan para startup bisnis rintisan', '[\"public\\/foto-aktivitas\\/641177d25320f.JPG\"]', '2023-03-15 14:46:26', '2023-03-15 14:46:26');
INSERT INTO `aktifitas` VALUES (50, 36, 'Bootcamp Dalam Rangka Peningkatan Kapasitas Startup', '2022-10-08', 'Kegiatan Bootcamp Dalam Rangka Peningkatan Kapasitas Startup ini Bertujuan untuk meberikan pemahaman kepada Startup atau tenant Business Lean Startup, Etika Bisnis, Corporate Social Responsibility (CSR), Strategi Pemasaran, Digital Marketing, Core Branding, Added Value, dan Market Segemn', '[\"public\\/foto-aktivitas\\/64117d26dfb6d.jpg\"]', '2023-03-15 15:09:10', '2023-03-15 15:09:10');
INSERT INTO `aktifitas` VALUES (51, 36, 'Coaching Clinic Perlindungan Kekayaan Intelektual', '2022-08-31', 'Kegiatan ini dilaksanakan bertujuan memberikan pemahaman kepada startup atau tenant tentang petingnya perlindungan inovasinya mulai dari kekayaan intelektual mulai dari Paten,Merk,Design Industri dan Hak Cipta. Selain itu kegiatan ini juga memberikan pemahaman mengenai dokumen-dokumen untuk pengurusan  dan alur pendaftaran Kekayaan intelektual', '[\"public\\/foto-aktivitas\\/641183a4483f4.jpeg\"]', '2023-03-15 15:36:52', '2023-03-15 15:36:52');
INSERT INTO `aktifitas` VALUES (52, 36, 'Workshop Technopreneur In The Digital Era 4.0 And Society 5.0', '2022-10-27', 'Kegiatan ini merupakan kegiatan pembelajaran untuk mengasah kemampuan dan menambah pengetahuan praktikal para startup yang terlibat dalam diskusi intensif dan aktivitas pada subjek atau proyek tertentu.', '[\"public\\/foto-aktivitas\\/641293d603ea9.JPG\"]', '2023-03-16 10:58:14', '2023-03-16 10:58:14');
INSERT INTO `aktifitas` VALUES (53, 36, 'Workshop Pembuatan SOP (Standar Operasional Prosedur) Program CPPBT', '2022-03-09', 'Pendampingan SOP ini dilakukan dengan memberikan pelatihan mengenai pembuatan SOP dan mendampingi Tenant dalalam pembuatan SOP. Pendampingan ini bertujuan agar tenant dapat mengetahui tujuan dari pembuatan SOP, Ruang Lingkup SOP, sehingga tenant dapat memastikan kegiatan opersional  perusahaan tenant dapat berjalan dengan lancar dan benar sesuai standar yang dibuat.', '[\"public\\/foto-aktivitas\\/64129e74cc478.jpg\"]', '2023-03-16 11:43:32', '2023-03-16 11:43:32');
INSERT INTO `aktifitas` VALUES (54, 36, 'Workshop Pembuatan BMC (Business Model Canvas) dan Pembuatan BP (Business Plan) Tahun 2022', '2022-07-01', 'Kegiatan ini merupakan workshop pembuatan BMC yang mana BMC sendiri merupakan strategi manajemen yang digunakan untuk membantu merancang sebuah perencanaan bisnis perusahaan dan keuangan. serta pembuatan BP yang mana BP sendiri merupakan strategi penjualan dan pemasaran dan kondisi keuangan seperti perkiraan pengeluaran dan pendapatan', '[\"public\\/foto-aktivitas\\/6412c3e3265ad.JPG\"]', '2023-03-16 14:23:15', '2023-03-16 14:23:37');
INSERT INTO `aktifitas` VALUES (55, 158, 'Inkubator Bisnis Tuka Tuku Purbalingga bersama Universitas AMIKOM Purwokerto', '2023-02-20', 'Pada Tanggal 20 Februari 2023, Inkubator Bisnis Tuka Tuku Purbalingga menjalin kerja sama dengan Universitas AMIKOM Purwokerto khususnya Fakultas Bisnis dan Ilmu Sosial. Hal ini merupakan salah satu progres bagi kami untuk langkah kedepannya bisa bersama-sama mengembangkan produksi para tenant', '[\"public\\/foto-aktivitas\\/6413d0de73368.jpg\",\"public\\/foto-aktivitas\\/6413d0de73752.jpg\",\"public\\/foto-aktivitas\\/6413d0de73a58.jpg\",\"public\\/foto-aktivitas\\/6413d0de73d42.jpg\",\"public\\/foto-aktivitas\\/6413d0de74078.jpg\"]', '2023-03-17 09:30:54', '2023-03-17 09:30:54');
INSERT INTO `aktifitas` VALUES (56, 158, 'Inkubator Bisnis Tuka Tuku Purbalingga bersama Pusat Inkubator Bisnis Universitas AMIKOM Purwokerto', '2023-02-20', 'Selain menjalin kerjasama dengan Universitas AMIKOM Purwokerto, Inkubator Bisnis Tuka Tuku Purbalingga melakukan kerjasama dengan Pusat Inkubator Bisnis AMIKOM Purwokerto. Di hari yang sama yaitu pada Senin, 20 Februari 2023 kami melakukan tanda tangan PKS.', '[\"public\\/foto-aktivitas\\/6413e02612e62.jpg\",\"public\\/foto-aktivitas\\/6413e02613916.jpg\",\"public\\/foto-aktivitas\\/6413e02613cf8.jpg\",\"public\\/foto-aktivitas\\/6413e02614063.jpg\",\"public\\/foto-aktivitas\\/6413e02614437.jpg\"]', '2023-03-17 10:36:06', '2023-03-17 10:36:36');
INSERT INTO `aktifitas` VALUES (57, 158, 'INBIS Tuka Tuku Purbalingga bersama Fakultas Ekonomi dan Bisnis UNSOED', '2023-02-20', 'Selain menjalin kerjasama dengan Universitas AMIKOM Purwokerto, dan Pusat Inkubator Bisnis Amikom, Inkubator Bisnis Tuka Tuku Purbalingga melakukan kerjasama dengan Fakultas Ekonomi dan Bisnis Universitas Jenderal Soedirman Purwokerto. Di hari yang sama yaitu pada Senin, 20 Februari 2023 kami melakukan tanda tangan PKS.', '[\"public\\/foto-aktivitas\\/641cfbc5ce733.jpeg\",\"public\\/foto-aktivitas\\/641cfbc5ceaeb.jpeg\",\"public\\/foto-aktivitas\\/641cfbc5cec9e.jpeg\",\"public\\/foto-aktivitas\\/641cfbc5cee53.jpeg\",\"public\\/foto-aktivitas\\/641cfbc5cef60.jpeg\"]', '2023-03-24 08:24:21', '2023-03-24 08:24:21');
INSERT INTO `aktifitas` VALUES (60, 43, 'Academy Link Industry', '2023-03-09', 'Sebagai bagian dari kerangka kebijakan Merdeka Belajar – Kampus Merdeka, Kementerian Pendidikan, Kebudayaan, Riset dan Teknologi mengimplementasikan\r\nberbagai program untuk membangun ekosistem yang mendorong peningkatan mutu dan relevansi pendidikan tinggi di Indonesia. Termasuk diantaranya adalah penawaran berbagai program pendanaan berbasis kompetisi.\r\nBerbagai data dan informasi di lapangan menunjukkan bahwa sejumlah penelitian yang diselenggarakan di perguruan tinggi telah menghasilkan luaran yang memiliki potensi untuk diterapkan sebagai solusi dari berbagai persoalan di masyarakat atau dikembangkan untuk komersialisasi yang dapat meningkatkan produktivitas dan daya saing nasional. Selain itu, sejumlah perguruan tinggi juga memiliki kepakaran yang mumpuni untuk menjawab berbagai persoalan yang dihadapi sector industri yang pada gilirannya akan mendorong peningkatan kinerja dan daya saing industri nasional.\r\nUpaya menjembatani dan mendorong terciptanya sinergi antar akademisi pelaku Perguruan Tinggi dengan Pelaku Industri, maka KUBINOV UNRAM menyediakan \r\nprogram “Workshop Academy Link Industry”. Program yang ditujukan untuk mampu menjadi ruang yang mampu menghubungkan tenant binaan KUBINOV UNRAM dengan\r\ndunia industri baik skala nasional ataupun regional NTB. Tidak hanya itu, pada workshop ini tenant juga akan diperkenalkan dengan komunitas industri yang mampu menjadi ruang kolaborasi produk ataupun usaha. \r\nMendukung keterlaksanaan, workshop ini mengundang pemateri yang terdiri atas pelaku industry tingkat nasional, regional dan komunitas industri di NTB. Kehadiran antar narasumber ini tentunya akan mampu mendukung terciptanya sinergi antar tenant binaan dengan sektori ndustri yang mampu meningkatkan kapasitas tenant menuju industri yang berdayasaing.', '[\"public\\/foto-aktivitas\\/6434cf956dc29.JPG\"]', '2023-04-03 08:47:03', '2023-04-11 10:10:13');
INSERT INTO `aktifitas` VALUES (61, 158, 'RAKOR KELEMBAGAAN INKUBATOR', '2023-03-30', 'Rapat Koordinasi Kelembagaan Inkubator se-Jawa Tengah dengan tema : Peningkatan Perekonomian Daerah melalui Lembaga Inkubator dan didukung dengan Sumberdaya Manusia yang Berkualitas\r\n\r\nDilaksanakan hybrid di Ungaran Semarang, 30 Maret 2023\r\n\r\nPemateri oleh :\r\n-Kepala BAPPEDA Prov. Jateng\r\n- Deputi Bid. Kewirausahaan KemenkopUKM\r\n- Ketua Asosiasi Inkubator Bisnis\r\n- Kepala DiskopUKM Prov. Jateng', '[\"public\\/foto-aktivitas\\/642b7b74df4bb.jpeg\",\"public\\/foto-aktivitas\\/642b7b74df787.jpeg\",\"public\\/foto-aktivitas\\/642b7b74df8d9.jpeg\",\"public\\/foto-aktivitas\\/642b7b74dfa15.jpeg\"]', '2023-04-04 08:20:52', '2023-04-04 08:20:52');
INSERT INTO `aktifitas` VALUES (62, 158, 'SURVEY LOKASI UNTUK PROGRAM PEMASARAN', '2023-03-28', 'Pemasaran merupakan program utama yang dijalankan oleh Inkubator Bisnis Tuka Tuku Purbalingga untuk mengembangkan usaha para tenant. Salah satunya adalah pemasaran produk tenant di obyek wisata andalan Kab. Purbalingga yaitu  D\'Las di Desa Serang dan Golaga di Desa Siwarak Kec. Karangreja. Tim Inkubator Bisnis Tuka Tuka Purbalingga melakukan survai  beberapa outlet yang potensial untuk pemasaran produk tenant agar pada saat libur Lebaran sudah siap.', '[\"public\\/foto-aktivitas\\/642b827b47eec.jpeg\",\"public\\/foto-aktivitas\\/642b827b4817a.jpeg\",\"public\\/foto-aktivitas\\/642b827b482af.jpeg\",\"public\\/foto-aktivitas\\/642b827b483be.jpeg\",\"public\\/foto-aktivitas\\/642b827b48544.jpeg\"]', '2023-04-04 08:50:51', '2023-04-04 08:50:51');
