INSERT INTO `aktifitas` VALUES (97, 13, 'Inkubasi Tenant Inkubator Bisnis Universitas Hindu Indonesia pada Kegiatan Fasilitasi Inkubator Wirausaha LPDB-KUMKM Tahun 2023', '2023-03-13', 'Pelatihan/Pendampingan Sesi IV Production \"Production Quality Control (QC) and Quality Assurance (QA), Build Productive Team, Production Flow & Plan, Build Good Products\"', '[\"public\\/foto-aktivitas\\/6476b9b893006.jpg\"]', '2023-05-23 12:58:20', '2023-05-31 10:06:32');
