INSERT INTO `aktifitas` VALUES (148, 158, 'Berpartner bersama PAXEL', '2023-06-26', 'Hari ini Senin 26 Juni 2023 bertempat di Ruang Meeting Bidang UMKM Dinkopukm, kehadiran Manajemen PAXEL Purwokerto, Pak Ferdi dan Pak Bagus. Paxel adalah perusahaan ekspedisi/pengiriman paket berbasis digital yang sangat tertarik dengan konsep Roadshow Digitalisasi UMKM yg diinisiasi oleh Inbis Tuka Tuku.', '[\"public\\/foto-aktivitas\\/64a227f3d77dc.jpeg\",\"public\\/foto-aktivitas\\/64a227f3d7ad8.jpeg\"]', '2023-07-03 08:44:19', '2023-07-03 08:44:19');
INSERT INTO `aktifitas` VALUES (149, 158, 'Bincang Hangat Bersama Bank Mandiri', '2023-06-15', 'Hari ini Kamis 15 Juni 2023 pk 16.00 bertempat di Resto Kopi Bathok, Tim Inbis Tuka Tuku  bertemu dengan Tim Bank Mandiri. Tim Bank Mandiri Purbalingga yang dihadir oleh Bapak Mono dan Bu Ratri dari Bank Mandiri Purwokerto. Dalam pertemuan kali ini, membicarakan tentang kerja sama mengenai Digitalisasi UMKM. Inbis Tuka Tuku bersepakat dengan Bank Mandiri untuk melaksanakan kegiatan bersama terkait digitalisasi UMKM dan peserta tidak hanya tenant Inbis Tuka Tuku tetapi pelaku UMKM yang bukan tenant.', '[\"public\\/foto-aktivitas\\/64a2294fa22ac.jpeg\",\"public\\/foto-aktivitas\\/64a2294fa2543.jpeg\"]', '2023-07-03 08:50:07', '2023-07-03 08:50:07');
