INSERT INTO `aktifitas` VALUES (186, 158, 'Wadah Orang Wirausaha', '2023-07-07', 'Halo Sobat Inkubator, kali ini kegiatan INBIS Tuka Tuku mengadakan rapat Finalisasi Program WOW (Wadah Orang Wirausaha) bersama Tim Bank Mandiri dan Paxel pada tanggal 7 Juli 2023. \r\nApa itu WOW?\r\nJadi Dinas Koperasi dan UKM beserta dengan INBIS Tuka Tuku dan PLUT berkolaborasi bersama Bank Mandiri & Paxel untuk menggelar pelatihan berkelanjutan untuk para pelaku UMKM. Kegiatan ini murni tanpa ada anggaran daerah, artinya bersifat independen dari dana CSR Bank Mandiri dan Paxel.', '[\"public\\/foto-aktivitas\\/64ab65376fb33.jpeg\",\"public\\/foto-aktivitas\\/64ab65376fdff.jpeg\",\"public\\/foto-aktivitas\\/64ab65376ff32.jpeg\",\"public\\/foto-aktivitas\\/64ab65377010b.jpeg\"]', '2023-07-10 08:56:07', '2023-07-10 08:56:07');
