INSERT INTO `aktifitas` VALUES (231, 418, 'PENDAMPINGAN & EDUKASI', '2022-07-21', 'Layanan yang diberikan untuk mendampingi dan mengedukasi masyarakat umum dan masyarakat akademis untuk memperoleh keterampilan khusus dan pengetahuan yang lebih mendalam dan mendetail dalam bidang pengabdian, penelitian dan edukasi', '[\"public\\/foto-aktivitas\\/64e5a0885f6e4.jpg\"]', '2023-08-23 13:00:40', '2023-08-23 13:00:40');
