INSERT INTO `aktifitas` VALUES (301, 234, 'boothcamp foto catalogue produk', '2023-09-08', 'Jumat 08 September 2023\r\n\r\nDukung Usaha Rintisan, BEC selenggarakan Kegiatan Foto Produk Gratis\r\n\r\nFoto produk adalah yang pertama dilihat oleh pelanggan ketika mereka mengunjungi situs web atau toko online. Foto produk yang berkualitas tinggi dapat meningkatkan kepercayaan pelanggan. Mereka merasa lebih yakin untuk membeli jika mereka dapat melihat produk dengan jelas. selain itu foto produk dapat membantu dalam komunikasi merek usaha. Tenant dapat menciptakan gaya visual yang khas yang mencerminkan merek usahanya.', '[\"public\\/foto-aktivitas\\/650120ef3ef8c.jpeg\"]', '2023-09-13 09:39:43', '2023-09-13 09:39:43');
