INSERT INTO `aktifitas` VALUES (496, 484, 'Program Pemagangan Kementerian Tenaga Kerja', '2019-10-17', 'Pemerintah melalui Kementerian Tenaga Kerja mencanangkan program Pemagangan dalam rangka meningkatkan Kualitas Sumber Daya Manusia Dalam Rangka Meningkatkan Daya Saing. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655eeee77505a.png\"]', '2023-11-23 13:19:19', '2023-11-23 13:19:19');
INSERT INTO `aktifitas` VALUES (497, 484, 'Health Safety Environment (HSE) Training', '2019-10-20', 'Semangat  untuk bisa terus Link & Match dengan kebutuhan perusahaan pada Divisi Health, Safety & Environment (HSE). \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655eef6c96740.jpg\"]', '2023-11-23 13:21:32', '2023-11-23 13:21:32');
