INSERT INTO `aktifitas` VALUES (500, 484, 'Pelaksanaan Social Media Implementation for Business', '2020-01-26', 'Pelaksanaan detail penggunaan social media untuk bisnis sesuai dengan kebutuhan masing-masing UMKM atau perusahaan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef22566a84.png\"]', '2023-11-23 13:33:09', '2023-11-23 13:33:09');
