INSERT INTO `aktifitas` VALUES (502, 484, 'Maintenance Management Training', '2020-02-04', 'Pelaksanaan Maintenance Management Training @ UMKM Umakite Serang.\r\n\r\nPelatihan yang diadakan selalu Insya Alloh berkolaborasi dengan para pemateri langsung dari praktisi yang bekerja di suatu perusahaan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef35378c36.jpg\"]', '2023-11-23 13:38:11', '2023-11-23 13:38:11');
INSERT INTO `aktifitas` VALUES (503, 484, 'Drafter Mechanical Training Grade 1', '2020-02-05', 'Pelaksanaan Training, berkolaborasi dengan UMKM Krebo Jantan Resto n Space. Terimkasih Bapak @erwin.yuswandi yang sudah mau berkolaborasi dan meluangkan waktunya untuk membantu teman2 Millennial untuk dapat Link & Match dengan Dunia Usaha dan Dunia Kerja. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef3b8ecacc.jpg\"]', '2023-11-23 13:39:52', '2023-11-23 13:39:52');
INSERT INTO `aktifitas` VALUES (504, 484, 'Computer Software Excel Training', '2020-02-09', 'Link Productive terus melaksanakan Pelatihan Berbasis Praktek yang sesuai dengan kebutuhan perusahaan di @umakite Serang Banten. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef44262c76.jpg\"]', '2023-11-23 13:42:10', '2023-11-23 13:42:10');
INSERT INTO `aktifitas` VALUES (505, 484, 'Intergrasi Audit ISO, OHSAS, SMK3', '2020-02-18', 'Internal Audit Terintegrasi perlu terus dilakukan untuk melakukan pengecekan terhadap proses bisnis perusahaan yang sesuai dengan SOP yang dilakukan. Hal ini penting bagi mahasiswa untuk dapat memberikan praktek langsung dalam meningkatkan skill. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef4c3dc8c6.jpg\"]', '2023-11-23 13:44:19', '2023-11-23 13:44:19');
INSERT INTO `aktifitas` VALUES (506, 484, 'Link Productive Bekerjasama dengan Universitas Serang Raya (UNSERA) Mengadakan Seminar Nasional', '2020-02-16', 'Kerjasama untuk meningkatkan Skill mahasiswa Universitas Serang Raya (UNSERA) dengan mengadakan Seminar Nasional.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef520ee69b.jpg\"]', '2023-11-23 13:45:52', '2023-11-23 13:45:52');
INSERT INTO `aktifitas` VALUES (507, 484, 'Link Productive Mendukung Program Kampus Merdeka', '2020-02-20', 'Pemerintah melalui Kementerian Pendidikan, Kebudayaan & Riset Teknologi membuat sebuah program Kampus Merdeka yang sangat bisa membantu mahasiswa untuk dapat menjadi lulusan yang sudah siap kerja atau siap usaha. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef566d1406.jpg\"]', '2023-11-23 13:47:02', '2023-11-23 13:47:02');
INSERT INTO `aktifitas` VALUES (508, 484, 'Praktek Penulisan CV Sesuai Dengan Keinginan HRD di Salah Satu Cafe di Serang', '2020-02-20', 'Terus dan terus Insya Allah berkomitmen untuk berkontribusi dalam peningkatan kompetensi mahasiswa sebagai komunitas pelatihan Link Productive untuk dapat Link & Match dengan dunia usaha dan dunia kerja. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef5d29e89b.jpg\"]', '2023-11-23 13:48:50', '2023-11-23 13:48:50');
INSERT INTO `aktifitas` VALUES (509, 484, 'Drafter Mechanical Training Grade 1', '2020-02-22', 'Training yang dilakukan berbasis praktek, dengan pemateri langsung dari praktisi yang berpengalaman di bidangnya. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef62fe9270.jpg\"]', '2023-11-23 13:50:23', '2023-11-23 13:50:23');
INSERT INTO `aktifitas` VALUES (510, 484, 'Implementation Lean Manufacturing in the Logistic Company Training', '2020-02-22', 'Training yang dilakukan berbasis praktek, dengan pemateri langsung dari praktisi yang berpengalaman di bidangnya. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef67bbd5d5.jpg\"]', '2023-11-23 13:51:39', '2023-11-23 13:51:39');
INSERT INTO `aktifitas` VALUES (511, 484, 'Seminar Persiapan Berkarir Menjadi HRD Profesional di Suatu Perusahaan', '2020-08-12', 'Pada saat pandemi Covid 19, maka seminar dilakukan secara online melalui zoom. Seminar ini sangat bermanfaat bagi para mahasiswa yang ingin setelah lulus berkarir menjadi HR & GA Supervisor.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef6dba69e7.jpg\"]', '2023-11-23 13:53:15', '2023-11-23 13:53:15');
INSERT INTO `aktifitas` VALUES (512, 484, 'Online Training Based On Project, How to Calculate a Salary?', '2020-08-14', 'Bagi mahasiswa yang ingin mempersiapkan diri sebagai seorang HR setelah lulus kuliah, maka diperlukan skill untuk menghitung gaji karyawan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef75977291.jpg\"]', '2023-11-23 13:55:21', '2023-11-23 13:55:21');
INSERT INTO `aktifitas` VALUES (513, 484, 'Online Training Based On Project, How to Make a Competency Design?', '2020-08-18', 'Bagi mahasiswa yang ingin mempersiapkan diri sebagai seorang HR setelah lulus kuliah, maka diperlukan skill untuk merancang skill / komptensi dari masing-masing jabatan yang dibutuhkan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef7b76c5b7.jpg\"]', '2023-11-23 13:56:55', '2023-11-23 13:56:55');
INSERT INTO `aktifitas` VALUES (514, 484, 'Online Training Based On Project, Training Need Analysis', '2020-08-25', 'Bagi mahasiswa yang ingin mempersiapkan diri sebagai seorang HR setelah lulus kuliah, maka diperlukan skill untuk melakukan perencanaan pelatihan dan pelaksanaan pelatihan dalam rangka peningkatan skill karyawan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef808ebc79.jpg\"]', '2023-11-23 13:58:16', '2023-11-23 13:58:16');
INSERT INTO `aktifitas` VALUES (515, 484, 'Online Training Based On Project, Employee Performance Management', '2020-08-29', 'Bagi mahasiswa yang ingin mempersiapkan diri sebagai seorang HR setelah lulus kuliah, maka diperlukan skill untuk melakukan penilaian kinerja karyawan dalam rangka pencapaian OKR & KPI masing-masing karyawan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef8644e895.jpg\"]', '2023-11-23 13:59:48', '2023-11-23 13:59:48');
INSERT INTO `aktifitas` VALUES (516, 484, 'Link Productive Bekerjasama dengan UNSERA Mengadakan Seminar Trik Menulis CV Yang Menarik', '2020-09-12', 'Tips menulis CV  yang menarik tidak hanya berkaitan dengan bagaimana cara membuat desain dalam CV tersebut menjadi lebih menarik, namun ada hal yang paling penting yang perlu diperhatikan yakni apa saja isi yang dituliskan didalam CV tersebut. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef90332cc9.png\"]', '2023-11-23 14:02:27', '2023-11-23 14:02:27');
INSERT INTO `aktifitas` VALUES (517, 484, 'Seminar Mengembangkan Potensi UMKM di Era Digital Dengan Adaptasi New Normal', '2020-09-18', 'Link Productive bekerjasama dengan tim KKM UNSERA untuk mengadakan seminar bagi para pengusaha yang terdampak penjualannya akibat dari adanya  pandemi dengan menerapkan proses bisnis digital dengan adaptasi new normal.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef9513bcc5.jpg\"]', '2023-11-23 14:03:45', '2023-11-23 14:03:45');
INSERT INTO `aktifitas` VALUES (518, 484, 'Online Training Based On Project, Effective Recruitment', '2020-09-23', 'Bagi mahasiswa yang ingin mempersiapkan diri sebagai seorang HR setelah lulus kuliah, maka diperlukan skill untuk melakukan perhitungan gaji yang sesuai dengan hak dan kewajiban karyawan serta aturan undang-undang yang berlaku. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef996d96d3.jpg\"]', '2023-11-23 14:04:54', '2023-11-23 14:04:54');
INSERT INTO `aktifitas` VALUES (519, 484, 'Seminar Tips & Trik Dalam Menghadapi Wawancara Kerja Bekerjasama dengan Fakultas Teknik UNSERA', '2020-10-03', 'Mahasiswa perlu mempersiapkan diri dalam menghadapi wawancara kerja sejak mahasiswa tersebut masih aktif dalam perkuliahan. Banyak hal yang perlu dipersiapkan dalam wawancara kerja. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655ef9e6705c5.jpg\"]', '2023-11-23 14:06:14', '2023-11-23 14:32:54');
INSERT INTO `aktifitas` VALUES (520, 484, 'Persiapan Memasuki Dunia Kerja di Era 4.0', '2020-10-06', 'Pada saat ini adalah era digital, dimana pemahaman tentang era digital ini sudah harus dimiliki oleh seluruh mahasiswa di semua jurusan. Karena perubahan proses digitalisasi ini sangat diperlukan di seluruh aspek bisnis dan kehidupan.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655efa3a8622b.jpg\"]', '2023-11-23 14:07:38', '2023-11-23 14:07:38');
INSERT INTO `aktifitas` VALUES (521, 484, 'Persiapan Berkarir Menjadi Tax Supervisor Untuk Dunia Kerja Dan Dunia Usaha', '2020-10-07', 'Posisi Tax Supervisor sudah pasti dibutuhkan oleh setiap perusahaan dalam menjalankan proses bisnisnya. Setiap transaksi yang perusahaan lakukan wajib dihitung dampak pajak yang bisa dihasilkan dan dilakukan pelaporan dan pembayaran kepada Pemerintah. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655efa7baee01.jpg\"]', '2023-11-23 14:08:43', '2023-11-23 14:08:43');
INSERT INTO `aktifitas` VALUES (522, 484, 'Membangun Mental & Karakter Sesuai Dengan Kebutuhan Dunia  Kerja', '2020-10-10', 'Mental dan Karakter adalah poin penting paling besar yang menentukan apakah karyawan tersebut ketika bekerja akan dapat melakukan pekerjaannya dengan baik atau tidak. Oleh karena itu, sebagai mahasiswa / siswa harus terus memperbaiki kualitas mental dan karakternya untuk menjadi lebih baik.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655efaea821f5.jpg\"]', '2023-11-23 14:10:34', '2023-11-23 14:10:34');
INSERT INTO `aktifitas` VALUES (523, 484, 'Tips & Trik Menghadapi Wawancara Kerja', '2020-10-10', 'Mahasiswa perlu mempersiapkan diri dalam menghadapi wawancara kerja sejak mahasiswa tersebut masih aktif dalam perkuliahan. Banyak hal yang perlu dipersiapkan dalam wawancara kerja. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/655efba88eddb.png\"]', '2023-11-23 14:13:44', '2023-11-23 14:13:44');
