INSERT INTO `aktifitas` VALUES (542, 484, 'Studi Independen / Internship Story @LinkProductive Divisi PPIC Analisa Detail  Process Flowchart Proses Produksi', '2022-05-31', 'Mahasiswa Magang Divisi PPIC namanya Rochyuli mahasiswa semester 6 dari Universitas Serang Raya sedang berdiskusi untuk mengerjakan tugas Job Description PPIC untuk melakukan analisa detail proses flowchart proses produksi, yang bertujuan untuk melakukan analisa efisiensi dalam setiap prosesnya.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview #ppic #magangppic #internppic', '[\"public\\/foto-aktivitas\\/655f0d21ed5cd.png\"]', '2023-11-23 15:28:17', '2023-11-23 15:28:17');
INSERT INTO `aktifitas` VALUES (543, 484, 'Studi Independen / Internship Story @LinkProductive Divisi HSE Melengkapi Dokumen Implementasi SMK3 Krteria 11 - 20', '2022-06-16', 'Mahasiswa Magang Divisi HSE namanya Ikram, Didik & Lukman mahasiswa dari Universitas Serang Raya masih terus secara continue mengerjakan kelengkapan dokumen kriteria 11 - 20 SMK3 untuk implementasi SMK3 di perusahaan. Tidak ada proses instant, terus berproses. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview #safety #magangsafety #internsafety #hse #maganghse #internhse', '[\"public\\/foto-aktivitas\\/655f0da3d6b4d.png\"]', '2023-11-23 15:30:27', '2023-11-23 15:30:27');
INSERT INTO `aktifitas` VALUES (544, 484, 'Studi Independen / Internship Story @LinkProductive Divisi HSE Konsisten Dalam Penerapan 5S di Perusahaan', '2022-06-17', 'Mahasiswa Magang Divisi HSE namanya Ikram, Akbar & Rohyuli, terus berkomitmen untuk melakukan implementasi 5S secara berkala dan terus berjuang untuk implementasi 5S sebagai budaya seluruh karyawan di perusahaan. Terus berporses secara continue, Skill tidak akan meningkat jika hanya dilakukan dalam 1 atau 2 hari praktek saja, tetapi harus minimal 6 bulan dan terus diulang secara berkelanjutan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview #safety #magangsafety #internsafety #hse #maganghse #internhse', '[\"public\\/foto-aktivitas\\/655f112b0566a.png\"]', '2023-11-23 15:41:12', '2023-11-23 15:45:31');
INSERT INTO `aktifitas` VALUES (545, 484, 'Studi Independen / Internship Story @LinkProductive Divisi Marketing untuk penentuan strategi marketing perusahaan.', '2022-06-24', 'Mahasiswa Magang Divisi Marketing namanya Ikram, Akbar & Lukman mahasiswa semester 6 dari Universitas Serang Raya sedang melakukan Meeting Strategi Marketing bisnis perusahaan untuk membentuk ekosistem digital terintegrasi Link Productive. \r\n\r\n#marketing #magang #internship #magangmarketing #kampusmerdeka #magangbersertifikat #studiindependenbersertifikat #internmarketing', '[\"public\\/foto-aktivitas\\/655f141c615c3.png\"]', '2023-11-23 15:58:04', '2023-11-23 15:58:04');
INSERT INTO `aktifitas` VALUES (546, 484, 'Studi Independen / Internship Story Update Progress Pekerjaan di Masing-Masing Divisi Menggunakan Agile Method', '2022-07-02', 'Update Progress Project Internship & Studi Independen @link.productive menggunakan metode Agile Scrum Software Trello. \r\n\r\n#kampusmerdeka #training #magangpurchasing #magangbersertifikat #magang #internship', '[\"public\\/foto-aktivitas\\/655ffec52f162.png\"]', '2023-11-24 08:39:17', '2023-11-24 08:39:17');
INSERT INTO `aktifitas` VALUES (547, 484, 'Studi Independen / Internship Story Divisi Marketing Membangun Ekosistem Digital Link Productive', '2022-07-03', 'Berusaha untuk membangun Kolaborasi Universitas di Serang dan Cilegon dengan @link.productive untuk menciptakan ekosistem digital Link Productive membantu meningkatkan skill mahasiswa untuk dapat siap kerja atau siap usaha. \r\n\r\n#kampusmerdeka #training #magangpurchasing #magangbersertifikat #magang #internship', '[\"public\\/foto-aktivitas\\/655fff6e42cc0.png\"]', '2023-11-24 08:42:06', '2023-11-24 08:42:06');
INSERT INTO `aktifitas` VALUES (548, 484, 'Studi Independen / Internship Story Meeting Rutin Menggunakan Software Trello', '2022-07-04', 'Rutin aktivitas untuk melakukan control progress pekerjaan dari masing-masing divisi dengan menggunakan software trello. \r\n\r\n#kampusmerdeka #training #magangpurchasing #magangbersertifikat #magang #internship', '[\"public\\/foto-aktivitas\\/6560003423782.png\"]', '2023-11-24 08:45:24', '2023-11-24 08:45:24');
INSERT INTO `aktifitas` VALUES (549, 484, 'Studi Independen / Internship Story Meeting dengan Praktisi Perusahaan', '2022-07-05', 'Studi Indepeden Internship Divisi PPIC untuk mempersiapkan program siap kerja Posisi HR GA Supervisor dengan pemateri Bapak @joeone_lesmana HR GA Manager @krakataueng (PT Krakatau Engineering). Banyak insight yang didapat dari para pemateri praktisi di perusahaan. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview #ppic #magangppic #internppic', '[\"public\\/foto-aktivitas\\/656000f53fa68.png\"]', '2023-11-24 08:48:37', '2023-11-24 08:48:37');
INSERT INTO `aktifitas` VALUES (550, 484, 'Studi Independen / Internship Story Divisi HSE Mahasiswa Semester 6 Jurusan Teknik Industri Universitas Serang Raya', '2022-07-06', 'Studi Independen / Internship Story @LinkProductive Divisi HSE melakukan kegiatan rutin daily meeting. \r\n\r\nUpdate progress meeting dengan melakukan tool box meeting setiap hari. Update dilakukan dengan melakukan update pekerjaan melalui trello. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview #safety #magangsafety #internsafety #hse #maganghse #internhse', '[\"public\\/foto-aktivitas\\/656001696181e.png\"]', '2023-11-24 08:50:33', '2023-11-24 08:50:33');
INSERT INTO `aktifitas` VALUES (551, 484, 'Studi Independen / Internship Story - Kunjungan LP3i Banten Dalam Rangka Kolaborasi Peningkatan Skill Mahasiswa', '2022-07-07', 'Terus berusaha untuk berkolaborasi dengan universitas untuk mewujudkan ekosistem digital terintegrasi Link Productive.\r\n\r\nTerimakasih @lp3i.banten LP3i College Banten untuk kunjungan kolaborasinya bersama Link Productive. \r\n\r\nStudi Independen / Internship Story @LinkProductive Divisi Marketing. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/656001b335747.png\"]', '2023-11-24 08:51:47', '2023-11-24 08:51:47');
INSERT INTO `aktifitas` VALUES (552, 484, 'Studi Independen & Magang Bersertifikat @link.productive Divisi HSE, Mahasiiswa Semester 6 Teknik Industri Universitas Serang Raya', '2022-07-09', 'Namanya Ikram @ikrmfrz_ Mahasiswa Semester 6 Jurusan Teknik Industri Universitas Serang Raya. \r\n\r\n@ft.unseraofficial\r\n\r\n@unserajawara\r\n\r\n@unseraeksis\r\n\r\nTerus rutin melalukan pekerjaan di Divisi HSE terkait dengan pemasangan jadwal safety talk setiap hari Kamis. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interview', '[\"public\\/foto-aktivitas\\/656004f0037cd.png\"]', '2023-11-24 09:05:36', '2023-11-24 09:05:36');
INSERT INTO `aktifitas` VALUES (553, 484, 'Studi Independen & Magang Bersertifikat @link.productive Divisi HR&GA, Akbar Nugraha Mahasiswa Semester 6 Teknik Industri Universitas Serang Raya', '2022-07-09', 'Studi Independen & Magang Bersertifikat @link.productive Divisi HR GA\r\n\r\nNamanya Akbar @bar__akbar Mahasiswa Semester 6 Jurusan Teknik Industri Universitas Serang Raya. \r\n\r\n@ft.unseraofficial\r\n\r\n@unserajawara\r\n\r\n@unseraeksis\r\n\r\nTerus rutin melalukan pekerjaan di Divisi HR & GA terkait dengan penentuan jam kerja di Link Productive. \r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja', '[\"public\\/foto-aktivitas\\/6560053df0175.png\"]', '2023-11-24 09:06:53', '2023-11-24 09:06:53');
INSERT INTO `aktifitas` VALUES (554, 484, 'Program Inkubasi Bisnis Link Productive Membantu Usaha Dari Mahasiswa Untuk Dapat Scale Up Bisnisnya', '2022-07-17', 'Banyak program Kolaborasi yang akan dilakukan untuk membantu banyak wirausaha mahasiswa.\r\n\r\nNamanya Udham Alumni mahasiswa dari Universitas Serang Raya sedang memberikan sharing pengalaman usaha Barbernya kepada Fahmi Mahasiswa Aktif Semester 8 Universitas Serang Raya untuk dapat saling berkolaborasi meningkatkan usaha barber sesama mahasiswa unsera. \r\n\r\nOfficial Universitas :\r\n\r\n@unseraeksis @unserajawara @wirausahamerdeka\r\n\r\nOfficial Business :\r\n\r\n@syambarbershop_ @udamvandam_pangkasrambut\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka', '[\"public\\/foto-aktivitas\\/65601b09d8b1c.png\"]', '2023-11-24 10:39:53', '2023-11-24 10:39:53');
INSERT INTO `aktifitas` VALUES (555, 484, 'Kerjasama Link Productive dengan Universitas Bina Bangsa Banten Untuk Peningkatan Skill Mahasiswa', '2022-07-17', 'Pada akhirnya ini yang ditunggu-tunggu, kolaborasi antara Universitas Bina Bangsa dengan Link Productive untuk dapat membantu meningkatkan skill mahasiswa Uniba untuk dapat siap kerja atau siap usaha. \r\n\r\nUntuk mahasiswa Uniba tunggu ya informasi resmi program kolaborasi ini as soon as posible.\r\n\r\nOfficial Universitas :\r\n\r\n@uniba_official\r\n\r\nOfficial Kemendikbudristek :\r\n\r\n@kampusmerdeka.ri @magangmerdeka @wirausahamerdeka\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka', '[\"public\\/foto-aktivitas\\/65601b477bf52.png\"]', '2023-11-24 10:40:55', '2023-11-24 13:48:42');
INSERT INTO `aktifitas` VALUES (556, 484, 'Psikotest Peserta Studi Independen Link Productive', '2022-07-18', 'Banyak banget keuntungan ikutan studi independen di Link Productive, salah satunya adalah peserta Studi Independen melakukan Psikotest secara langsung.\r\n\r\nKemudian mereka akan menerima hasil Psikotest dan akan diberikan feedback Psikotest sebagai bagian dari improvement diri.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka', '[\"public\\/foto-aktivitas\\/65601b9520c38.png\"]', '2023-11-24 10:42:13', '2023-11-24 10:42:13');
INSERT INTO `aktifitas` VALUES (557, 484, 'Diskusi Dalam Membangun Ekosistem Digital Terintegrasi Dengan Pihak Perusahaan', '2022-07-18', 'Proses membangun ekosistem digital terintegrasi Link Productive terus dilakukan untuk memperkuat seluruh stakeholder yang berkepentingan didalamnya termasuk salah satunya adalah perusahaan.\r\n\r\nPerusahaan PT Krakatau Engineering salah satu dari perusahaan yang akan berkolaborasi untuk proses peningkatan skill mahasiswa atau siswa.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka', '[\"public\\/foto-aktivitas\\/65601bd78952e.png\"]', '2023-11-24 10:43:19', '2023-11-24 10:43:19');
INSERT INTO `aktifitas` VALUES (558, 484, 'Perkuat Ekosistem Digital Terintegrasi Link Productive, Bekerjasama Dengan Politeknik Piksi Input Serang', '2022-07-19', 'Terimakasih Bapak Angga dari Politeknik Piksi Input Serang @official.poltek.piksi sudah mau berkunjung dan berdiskusi luar biasa hebatnya dengan semangat yang sama untuk peningkatan skill mahasiswa untuk dapat siap kerja atau siap usaha.\r\n\r\nMahasiswa Politeknik Piksi Input Serang, tunggu program Kolaborasi Kampus Merdeka Link Productive X @official.poltek.piksi\r\n\r\n@kampusmerdeka.ri @magangmerdeka @wirausahamerdeka\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka', '[\"public\\/foto-aktivitas\\/65601c1d284f5.png\"]', '2023-11-24 10:44:29', '2023-11-24 10:44:29');
INSERT INTO `aktifitas` VALUES (559, 484, 'Perkuat Ekosistem Digital Link Productive, Melakukan Kerjasama Dengan SMK Al Insan Cilegon', '2022-07-19', 'Kerjasama pertama Link Productive dengan SMK Al Insan @smk_alinsancilegon .\r\n\r\nProses kegiatan pada saat ini Siswa SMK Al Insan Jurusan Akuntansi sedang dan terus melakukan proses magang di Link Productive.\r\n\r\nBanyak pembelajaran dari proses magang terkait dengan pengembangan soft skill dan hard skill.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka #smk #smkbisa #smkbisasmkhebat #smkpusatkeunggulan', '[\"public\\/foto-aktivitas\\/65601c70380a6.png\"]', '2023-11-24 10:45:52', '2023-11-24 10:45:52');
INSERT INTO `aktifitas` VALUES (560, 484, 'Experience Peserta Studi Independen Link Productive, Menjadi Pembicara Pada Acara Seminar Universitas Serang Raya', '2022-07-19', 'Namanya Akbar, Ikram dan Rohyuli, Mahasiswa Semester 6 Jurusan Teknik Industri, Universitas Serang Raya, Studi Independen dari Link Productive sedang memberikan materi dalam acara Seminar & Workshop di Universitas Serang Raya.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka #smk #smkbisa #smkbisasmkhebat #smkpusatkeunggulan', '[\"public\\/foto-aktivitas\\/65601cba3e735.png\"]', '2023-11-24 10:47:06', '2023-11-24 10:47:06');
INSERT INTO `aktifitas` VALUES (561, 484, 'Experience Meeting Koordinasi Divisi PPIC & Production', '2022-07-23', 'Namanya Rohyuli dan Lukman mahasiswa Semester 6 dan 8 Teknik Industri Universitas Serang Raya sedang melakukan meeting terkait dengan PPIC Produk Minuman di Link Productive. Proses perencanaan ini penting untuk memastikan target produksi dapat tercapai.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka #smk #smkbisa #smkbisasmkhebat #smkpusatkeunggulan', '[\"public\\/foto-aktivitas\\/65601cf47ea6b.png\"]', '2023-11-24 10:48:04', '2023-11-24 10:48:04');
INSERT INTO `aktifitas` VALUES (562, 484, 'Seminar Siap Kerja, Untuk Siswa SMK Serang Cilegon', '2022-07-24', 'Link Productive berkolaborasi dengan Jurusan Teknik Industri Universitas Serang Raya untuk mengadakan Seminar & Workshop dalam rangka mempersiapkan para lulusan SMA SMK untuk dapat memahami tentang dunia kerja.\r\n\r\nHal ini juga bisa menjadi salah satu promosi dari Universitas untuk memperkenalkan Profil Universitas.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja #wirausahamerdeka #smk #smkbisa #smkbisasmkhebat #smkpusatkeunggulan', '[\"public\\/foto-aktivitas\\/65601d3472f63.png\"]', '2023-11-24 10:49:08', '2023-11-24 10:49:08');
INSERT INTO `aktifitas` VALUES (563, 484, 'Pengalaman Kerja Lukman di Bagian Safety, Tidak Akan Disamai Dengan Mahasiswa Yang Hanya Kuliah di Kampus', '2022-07-24', 'Banyak pengalaman magang mahasiswa di perusahaan yang tidak akan bisa didapatkan didalam kampus saja.\r\n\r\nTerus semangat ya Lukman @mubarroklukman Mahasiswa Semester 8 Teknik Industri Universitas Serang Raya @unserajawara untuk bisa terus belajar banyak dan semakin ahli dibidangnya.\r\n\r\nTidak ada yang instant dalam menjadi ahli sebagai Safety Supervisor.\r\n\r\n#kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja', '[\"public\\/foto-aktivitas\\/65601d6e0087b.png\"]', '2023-11-24 10:50:06', '2023-11-24 10:50:06');
INSERT INTO `aktifitas` VALUES (564, 484, 'Proses Studi Independen Bersertifikat Link Productive', '2022-08-19', 'Hari pertama banyak kesan baru dengan anggota baru semangat baru !!\r\n\r\nSelamat datang peserta magang bootcamp Training Based On Project\r\n\r\n#bootcamp\r\n\r\n#training #trainingday #trainingmotivation\r\n\r\n#magang #magangmerdeka #magangakuntansi #digitalmarketing #digitalmarketingtips #digitalmarketingstrategy #kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja', '[\"public\\/foto-aktivitas\\/65601dafc5341.png\"]', '2023-11-24 10:51:11', '2023-11-24 10:51:11');
INSERT INTO `aktifitas` VALUES (565, 484, 'Proses Studi Independen Bersertifikat Link Productive, Pengeraan Project-Project Sesuai Divisi', '2022-08-21', 'Hi Linkers!!!\r\n\r\nUdah D2 kegiatan hari ini seru banget loh, dari bimbingan CEO sampai mengerjakan tugas sesuai divisi masing-masing dan pastinya productive banget!\r\n\r\nFyi :\r\n\r\nSudah di buka pendaftaran Bootcamp Training Based On Project!!!\r\n\r\nMore :\r\n\r\nTiktok : @link.productive\r\n\r\nYouTube : Link Productive\r\n\r\nWebsite :www.linkproductive.com\r\n\r\n#Daily #bootcamp #training #infoBootcamp #LinkProductive #kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja', '[\"public\\/foto-aktivitas\\/65601dfc16c33.png\"]', '2023-11-24 10:52:28', '2023-11-24 10:52:28');
INSERT INTO `aktifitas` VALUES (566, 484, 'Proses Studi Independen Bersertifikat Link Productive, Pengerjaan Project HR & GA', '2022-08-22', 'Hi Linkers!!!\r\n\r\nDi D3 ini kita mendatangi kantor BPJS Cilegon untuk mendaftarkan BPJS ketenagakerjaan untuk Peserta Magang.\r\n\r\nFyi :\r\n\r\nSudah di buka pendaftaran Bootcamp Training Based On Project!!!\r\n\r\nMore :\r\n\r\nTiktok : @link.productive\r\n\r\nYouTube : Link Productive\r\n\r\nWebsite :www.linkproductive.com\r\n\r\n\r\n#Daily #bootcamp #training #infoBootcamp #LinkProductive #kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest #cv #interviewkerja', '[\"public\\/foto-aktivitas\\/65601e7426854.png\"]', '2023-11-24 10:54:28', '2023-11-24 10:54:28');
INSERT INTO `aktifitas` VALUES (567, 484, 'Proses Studi Independen Bersertifikat Link Productive, Meeting Progress Pekerjaan Project', '2022-08-24', 'Hi Linkers!!!\r\n\r\nDi D5 semua Divisi melakukan meeting harian dengan CEO Link Productive\r\n\r\nFyi :\r\n\r\nSudah di buka pendaftaran Bootcamp Training Based On Project!!!\r\n\r\nMore :\r\n\r\nTiktok : @link.productive\r\n\r\nYouTube : Link Productive\r\n\r\nWebsite :www.linkproductive.com\r\n\r\n#Daily #bootcamp #training #infoBootcamp #LinkProductive #kampusmerdeka #internship #magangbersertifikat #studiindependenbersertifikat #magang #training #seminar #siapkerja #siapusaha #bootcamp #projecttraining #psiktotest', '[\"public\\/foto-aktivitas\\/65601eb27c3b2.png\"]', '2023-11-24 10:55:30', '2023-11-24 10:55:30');
