INSERT INTO `aktifitas` VALUES (637, 484, 'Success Story Mahasiswa Aktif Peserta Studi Independen Bersertifikat Link Productive Siap Kerja', '2023-01-08', 'Lena Apriliyanti @lena.apriliyanti Mahasiswa Konversi 20 SKS @official.poltek.piksi . Sukses punya pengalaman kerja project sejak masih kuliah dengan ikutan Studi Independen Bersertifikat di Link Productive.\r\n\r\n\r\nLink Productive sudah berpengalaman mengadakan Program Studi Independen Bersertifikat Mandiri Program @magangmerdeka Mandiri sesuai target Mas Menteri @nadiemmakarim\r\n\r\n\r\nTarget 1 juta Mahasiswa 2024 ikut program Kampus Merdeka MANDIRI.\r\n\r\n\r\nLink Productive akan terus konsisten, mau dapat pendanaan dari pemerintah atau tidak akan terus jalan mendukung program Studi Independen Bersertifikat Konversi 20 SKS @magangmerdeka @kampusmerdeka.ri .\r\n\r\n\r\nKolaborasi @kedaireka_id @wirausahamerdeka @praktisimengajar.\r\n\r\n\r\nNext program kolaborasi dengan Universitas Muhammadiyah Yogyakarta, Universitas Bina Bangsa, Universitas Serang Raya dan masih banyak lagi.\r\n\r\n\r\nSaat nya siapkan lulusan dari sisi kualitas bukan hanya kuantitas. Dapat banyak mahasiswa tapi lulusan tidak punya skill siap kerja mental yang harus dirubah.\r\n\r\n\r\nSaatnya disrupsi pendidikan Indonesia Kolaborasi @magangmerdeka @kampusmerdeka.ri @nadiemmakarim @link.productive', '[\"public\\/foto-aktivitas\\/656043866774e.png\"]', '2023-11-24 13:32:38', '2023-11-24 13:32:38');
INSERT INTO `aktifitas` VALUES (638, 484, 'Success Story Mahasiswa Aktif Peserta Studi Independen Bersertifikat Link Productive Siap Kerja', '2023-01-08', 'Nikajid Sulaiman Mahasiswa Aktif Semester 7 Universitas Serang Raya selesai mengikuti Program Studi Independen Bersertifikat Mandiri Konversi 20 SKS Standar Program Kampus Merdeka MSIB @magangmerdeka\r\n\r\n\r\n@unserajawara\r\n\r\n\r\nNikajid punya pengalaman dibagian Health Safety Environment (HSE) implementasi di UMKM.\r\n\r\n\r\nSudah saatnya program kampus merdeka @magangmerdeka bisa berdampak tidak hanya peningkatan skill Mahasiswa Siap Kerja tapi juga peningkatan UMKM Naik Kelas.\r\n\r\n\r\n@kemenkopukm\r\n\r\n@kemenparekraf.ri\r\n\r\n@magangmerdeka\r\n\r\n@kampusmerdeka.ri\r\n\r\n@kampusmengajar\r\n\r\n@kedaireka_id\r\n\r\n@wirausahamerdeka', '[\"public\\/foto-aktivitas\\/656043e818aac.png\"]', '2023-11-24 13:34:16', '2023-11-24 13:34:16');
INSERT INTO `aktifitas` VALUES (639, 484, 'Success Story Mahasiswa Aktif Peserta Studi Independen Bersertifikat Link Productive Siap Kerja', '2023-01-08', 'Ikram Fairuz Mahasiswa Aktif Semester 7 Universitas Serang Raya selesai mengikuti Program Studi Independen Bersertifikat Mandiri Konversi 20 SKS Standar Program Kampus Merdeka MSIB @magangmerdeka\r\n\r\n\r\n@unserajawara\r\n\r\n\r\nIkram punya pengalaman dibagian Digitalisasi Marketing dengan bantu UMKM Naik Kelas.\r\n\r\n\r\nSudah saatnya program kampus merdeka @magangmerdeka bisa berdampak tidak hanya peningkatan skill Mahasiswa Siap Kerja tapi juga peningkatan UMKM Naik Kelas.\r\n\r\n\r\n@kemenkopukm\r\n\r\n@kemenparekraf.ri\r\n\r\n@magangmerdeka\r\n\r\n@kampusmerdeka.ri\r\n\r\n@kampusmengajar\r\n\r\n@kedaireka_id\r\n\r\n@wirausahamerdeka', '[\"public\\/foto-aktivitas\\/6560443863f50.png\"]', '2023-11-24 13:35:36', '2023-11-24 13:45:20');
INSERT INTO `aktifitas` VALUES (640, 484, 'Success Story Mahasiswa Aktif Peserta Studi Independen Bersertifikat Link Productive Siap Kerja', '2023-01-10', 'Ahmad Rohyuli Mahasiswa Konversi 20 SKS Universitas Serang Raya @unserajawara . Sukses punya pengalaman kerja project sejak masih kuliah dengan ikutan Studi Independen Bersertifikat di Link Productive di bagian PPIC Productions.\r\n\r\n\r\nLink Productive sudah berpengalaman mengadakan Program Studi Independen Bersertifikat Mandiri Program @magangmerdeka Mandiri sesuai target Mas Menteri @nadiemmakarim\r\n\r\n\r\nTarget 1 juta Mahasiswa 2024 ikut program Kampus Merdeka MANDIRI.\r\n\r\n\r\nLink Productive akan terus konsisten, mau dapat pendanaan dari pemerintah atau tidak akan terus jalan mendukung program Studi Independen Bersertifikat Konversi 20 SKS @magangmerdeka @kampusmerdeka.ri .\r\n\r\n\r\nKolaborasi @kedaireka_id @wirausahamerdeka @praktisimengajar.\r\n\r\n\r\nNext program kolaborasi dengan Universitas Muhammadiyah Yogyakarta, Universitas Bina Bangsa, Universitas Serang Raya dan masih banyak lagi.\r\n\r\n\r\nSaat nya siapkan lulusan dari sisi kualitas bukan hanya kuantitas. Dapat banyak mahasiswa tapi lulusan tidak punya skill siap kerja mental yang harus dirubah.\r\n\r\n\r\nSaatnya disrupsi pendidikan Indonesia Kolaborasi @magangmerdeka @kampusmerdeka.ri @nadiemmakarim @link.productive', '[\"public\\/foto-aktivitas\\/6560447eab88c.png\"]', '2023-11-24 13:36:46', '2023-11-24 13:36:46');
