INSERT INTO `aktifitas` VALUES (682, 484, 'Lanjutan Konsultasi CV peserta', '2023-04-01', 'Kegiatan Review CV berdampak terhadap peningkatan pemahaman para Pencari Kerja untuk lebih tau mengenai CV yang sesuai dengan keinginan HRD Perusahaan. CV menjadi penting untuk dapat lolos seleksi awal administrasi.\r\n\r\nCollaboration Program With @antarkerja.cilegon .\r\n@blkcilegon\r\n\r\n#siapkerja', '[\"public\\/foto-aktivitas\\/6564550303c97.jpg\"]', '2023-11-27 15:35:08', '2023-11-27 15:36:19');
