INSERT INTO `aktifitas` VALUES (761, 493, 'Open Recruitment Tenant 2020 Inkubator Bisnis Teknologi (Inbistek) Universitas Andalas', '2020-09-04', 'Inbistek Unand adalah inkubator bisnis resmi yang dimiliki oleh Universitas Andalas, secara berkala melakukan proses dukungan bisnis untuk mendukung percepatan pengembangan perusahaan pemula/tenant dengan menyediakan berbagai sumber daya dan layanan yang dibutuhkan.\r\n\r\nMari bergabung bersama kami menjadi tenant Inbistek Unand dengan mengisi form berikut:\r\n\r\nhttp://unand.net/inbistek20\r\n\r\nPendaftaran: 3-9 September 2020\r\nWawancara: 11 September 2020\r\n\r\nInstagram: inbistek_unand\r\nWA grup calon tenant: http://bit.ly/inbistek20', '[\"public\\/foto-aktivitas\\/6566ac7cdae1e.jpg\"]', '2023-11-29 10:14:04', '2023-11-29 10:14:04');
