INSERT INTO `aktifitas` VALUES (801, 493, 'Undangan', '2020-08-04', 'nBisTek Unand Webinar Nasional Series #6: \"Strategi Keuangan UMKM di Masa Pandemi COVID-19\"\r\n\r\nAssalamualaikum Wr. Wb.,\r\n\r\nLPPM Universitas Andalas, Inkubator Bisnis Teknologi (InBisTek) Universitas Andalas menyelenggarakan Webinar Nasional \"Strategi Keuangan UMKM di Masa Pandemi COVID-19.\r\n\r\nTerbuka untuk seluruh UMKM/IKM, akademisi, umum dan mahasiswa. Daftar melalui: http://unand.net/-diaq\r\nKepesertaan gratis & mendapatkan e-sertifikat.\r\n\r\n*TANGGAL dan WAKTU*\r\nHari/Tanggal : Kamis/ 6 Agustus 2020\r\nPukul 10.00 - 12.30 WIB\r\nMelalui Zoom meeting: http://unand.net/Vslev\r\n\r\n*PEMBICARA:*\r\nDr. Rida Rahim, SE., ME\r\nSekretaris Program Doktor Ilmu Manajemen Universitas Andalas\r\n\r\nDr. Fajri Adrianto, SE., M.Bus\r\nSekretaris Program Magister Manajemen Universitas Andalas\r\n\r\nMODERATOR:\r\nIndah Permata Suryani, S.E., M.Sc.\r\nDosen Jurusan Akuntansi Unand\r\n\r\nSUPPORTING Partner: *Andalas Management Review (AMAR)*\r\n\r\nSemoga dimudahkan pelaksanaannya dan dapat bermanfaat. Aamiin YRA.\r\n\r\nTerima kasih.\r\nSalam,\r\nLPPM - InBisTek Unand', '[\"public\\/foto-aktivitas\\/6567e97ee4ddc.jpg\"]', '2023-11-30 08:46:38', '2023-11-30 08:46:38');
