INSERT INTO `aktifitas` VALUES (811, 493, 'Undangan', '2020-07-20', 'InBisTek Unand Webinar Nasional Series #2: \"Youthpreneur vs COVID-19\"\r\n\r\nAssalamualaikum Wr. Wb.,\r\n\r\nLembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) Universitas Andalas, Inkubator Bisnis Teknologi (InBisTek) Universitas Andalas menyelenggarakan Webinar Nasional \"Youthpreneur vs COVID-19\" Solusi scientist untuk wirausahawan muda menghadapi masa pandemi COVID-19.\r\n\r\nTerbuka untuk seluruh UMKM/IKM, akademisi, peneliti, umum dan mahasiswa. Daftar sekarang melalui: http://unand.net/NCcwy\r\nKepesertaan gratis & mendapatkan e-sertifikat.\r\n\r\nTANGGAL dan WAKTU\r\nHari/Tanggal : Kamis/23 Juli 2020\r\nPukul 13.00 – 15.30 WIB\r\nPemaparan dan diskusi dilakukan secara online menggunakan Aplikasi Zoom meeting dengan Link: http://unand.net/zfmvp\r\n\r\nPEMBICARA:\r\nHafiz Rahman, S.E., M.S.B.S., Ph.D\r\nAssistant Professor Kewirusahaan dan Usaha Kecil Menengah Universitas Andalas/ Penulis buku Kewirausahaan + Wirausahawan\r\n\r\nLengga Pradipta, M.Sc.\r\nPeneliti Pusat Penelitian Kependudukan Lembaga Ilmu Pengetahuan Indonesia (LIPI)\r\n\r\nMODERATOR:\r\nYesi Puspita, S.Sos., M.Si.\r\nStaf Science Techno Park Unand/\r\nDosen Ilmu Komunikasi Unand\r\n\r\nSUPPORTING Partner: Andalas Management Review (AMAR)\r\n\r\n\r\nSemoga dimudahkan pelaksanaannya dan dapat bermanfaat. Aamiin YRA.\r\n\r\nTerima kasih.\r\nSalam,\r\nLPPM - InBisTek Unand', '[\"public\\/foto-aktivitas\\/6567eb01b4c32.jpg\"]', '2023-11-30 08:53:05', '2023-11-30 08:53:05');
