INSERT INTO `aktifitas` VALUES (844, 493, 'Open Rekrutmen Tenant Inkubator Unand 2019', '2019-03-22', 'Assalammualaikum wr wb\r\nInkubator Bisnis Teknologi Universitas Andalas mengadakan Open Rekrutmen bagi Calon Tenant Yang Siap Untuk diInkubasi/didampingi selama tahun 2019.\r\nUntuk Bapak, Ibu, Sdr/i yang berminat, bisa mengisi formulir di:\r\nhttps://goo.gl/forms/6SZEKbcARb439iPu2\r\n\r\nPendaftaran dibuka tgl 22 - 25 Maret 2019.\r\nWawancara akan dilaksanakan tgl 26 Maret 2019\r\nContacts:\r\nInbistekandalas@gmail.com\r\n085374713493 (Livi)\r\nSekretariat:\r\nRuang Co-Working Space InBisTek Gedung Rektorat Lt. 2 LPPM Universitas Andalas.', '[\"public\\/foto-aktivitas\\/6567f05e0775f.jpg\"]', '2023-11-30 09:15:58', '2023-11-30 09:15:58');
