INSERT INTO `aktifitas` VALUES (1020, 491, 'PLUZI ACADEMY UMKM', '2023-08-14', 'PLUZI ACADEMY UMKM adalah kegiatan pelatihan selama 3 bulan yag berfokus pada cara-cara pemasaran bagi UMKM, dimana pada kegiatan ini lebih mengutamakan praktek . kegiatan yang dilakukan yaitu ada pelatihan membuat vidio sederhana untuk social media , pelatihan public speaking,pelatihan pembuaan akun sosia media yaitu tiktok dan shoppee,praktek live tiktok untuk penjualan. di harapakan dari pelatihan ini UMKM yang telah didampingi selama 3 bulan dapat mengembangkan pemasarannya dan omser yang didapatkan bertambah. \r\nuntuk dokumentasi kegiatan yang lengkap  bisa kunjungi Instagram kami yaitu @ariziutama', '[\"public\\/foto-aktivitas\\/657bd5479ecb3.jpeg\"]', '2023-12-15 11:25:43', '2023-12-15 11:25:43');
INSERT INTO `aktifitas` VALUES (1021, 491, 'KURASI PRODUK BAGI UMKM SUMATERA BARAT', '2023-10-03', 'Kurasi produk bagi UMKM Sumatera Barat adalah kegiatan yang dilakukan untuk mengkurasi / menilai produk-produk UMKM baik makanan ataupun kerajinan apakah sudah sesuai Standar yang ada. pada kegiatan ini di ikuti 25 UMKM suamtera barat yang hampir 80 % persen di penuhi oleh UMKM makanan. kurasi yag dilakukan yaitu seperti rasa, kemasan, ketahanan produk dan legalitas UMKM. pada kegiatan ini kami bekerjasama dengan PLUT KUMKM untuk melasungkan kegiatan ini .', '[\"public\\/foto-aktivitas\\/657bd6e5a1071.jpeg\"]', '2023-12-15 11:32:37', '2023-12-15 11:32:37');
INSERT INTO `aktifitas` VALUES (1022, 491, 'KUNJUNGAN KE PABRIK AZIZAH DENGAN BUYER  ARIZI DARI MALAYSIA', '2023-10-17', 'Kunjungan ke Pabrik Kerupuk Azizah bersama buyer  arizi dari Malaysia untuk melihat tempat produksi keripik pisang yang diminati oleh buyer malaysia .', '[\"public\\/foto-aktivitas\\/657bd7a28a98c.jpeg\"]', '2023-12-15 11:35:46', '2023-12-15 11:36:21');
INSERT INTO `aktifitas` VALUES (1023, 491, 'PLUZI ACADEMY GOES TO CAMPUS', '2023-11-04', 'PLUZI Academy Goes To Campus adalah pelatihan selama 2 bulan yang diberikan kepada para mahasiswa yang ada di kota padang. pada pelatihan ini lebih berfokus kepada bagaimana menciptakan mahasiswa sebagai marketing dan menciptakan enterpreneur muda.', '[\"public\\/foto-aktivitas\\/657be22981eed.jpeg\"]', '2023-12-15 12:20:41', '2023-12-15 12:20:41');
INSERT INTO `aktifitas` VALUES (1024, 342, 'Sosialisasi Inkubator Bisnis \"METRIC\"', '2023-09-10', 'Sosialisasi Inkubator Bisnis Metric kepada Pelaku UMKM di Kelurahan Kayubulan Kecamatan Limboto Kabupaten Gorontalo', '[\"public\\/foto-aktivitas\\/657fad3870532.jpeg\"]', '2023-12-18 09:23:52', '2023-12-18 09:23:52');
INSERT INTO `aktifitas` VALUES (1025, 154, 'Webinar 4 Business Fest Vol.1 UNIBI', '2023-12-15', 'Pusat Inovasi dan Inkubator Bisnis telah selesai melaksanakan Webinar yang dilaksanakan pada hari Jumat, 15 Desember 2023 dengan tema \'EFFORT on SME\'s\' yang membahas tips dan trik menyusun dan mengatur keuangan sejak dini untuk calon - calon pengusaha muda.', '[\"public\\/foto-aktivitas\\/657fc1999df7c.jpg\"]', '2023-12-18 10:50:49', '2024-02-15 09:58:24');
INSERT INTO `aktifitas` VALUES (1026, 376, 'Rapat Antar Tenant', '2023-12-09', 'Melakukan Rapat dengan Tenant terkait Program inkubator Krui Jaya', '[\"public\\/foto-aktivitas\\/6580f574ef36c.jpeg\"]', '2023-12-19 08:44:20', '2023-12-19 08:44:20');
INSERT INTO `aktifitas` VALUES (1027, 376, 'Pekan Fest goes to Lemong', '2023-11-11', 'Pekan fest merupakan salah satu kegiatan untuk mendukung program Inkubator Krui Jaya dalam Pemberdayaan UMKM di Kabupaten Pesisir Barat', '[\"public\\/foto-aktivitas\\/6580f69323c84.jpeg\"]', '2023-12-19 08:49:07', '2023-12-19 08:49:07');
INSERT INTO `aktifitas` VALUES (1028, 376, 'Pelatihan Vocational Pengolahan Makanan Bagi Umk Bidang Kuliner', '2023-05-10', 'kegiatan pelatihan tentang Pelatihan Vocational Pengolahan Makanan Bagi Umk Bidang Kuliner Kegiatan Pendidikan Dan Latihan Perkoperasian Peningkatan Kapasitas Koperasi Dan Usaha Mikro Dan Kecil Program Pendidikan dan Latihan Perkoperasian pada Bidang Koperasi dan UKM Dinas Koperasi, UKM, dan Perdagangan Kabupaten Pesisir Barat Tahun Anggaran 2023 merupakan kegiatan untuk memdukung Program Inkubator Krui jaya', '[\"public\\/foto-aktivitas\\/6580f751de3b5.jpeg\"]', '2023-12-19 08:52:17', '2023-12-19 08:52:17');
INSERT INTO `aktifitas` VALUES (1029, 376, 'Pelatihan Teknis Peningkatan Keterampilan UMK Bidang Kriya', '2023-10-13', 'Pelatihan Teknis Peningkatan Keterampilan UMK Bidang Kriya Kegiatan Pendidikan Dan Latihan Perkoperasian Peningkatan Kapasitas Koperasi Dan Usaha Mikro Dan Kecil (Pk2umk) Program Pendidikan Dan Latihan Perkoperasian pada Bidang Koperasi dan UKM Dinas Koperasi, UKM, dan Perdagangan Kabupaten Pesisir Barat Tahun Anggaran 2023. merupakan salah satu kegiatan dalam memdukung Program Inkubator Krui jaya.', '[\"public\\/foto-aktivitas\\/6580f8637812b.jpeg\"]', '2023-12-19 08:56:51', '2023-12-19 08:56:51');
INSERT INTO `aktifitas` VALUES (1030, 376, 'Bazar UMKM setiap Kegiatan Kabupaten', '2023-09-25', 'pemberdayaan UMKM bidang kuliner dalam setiap even yang diadakan PEMDA Pesisir Barat dalam rangka mendukung Program Inkubator Krui Jaya', '[\"public\\/foto-aktivitas\\/6580f959720ca.jpeg\"]', '2023-12-19 09:00:57', '2023-12-19 09:01:33');
INSERT INTO `aktifitas` VALUES (1031, 484, 'Program Mini Temu Raya Kreasi Prakerja', '2023-11-03', 'Program Mini Temu Raya Kreasi Prakerja 2023.\r\n\r\nPada Program Kali ini yang diselenggarakan oleh Prakerja yang berkolaborasi dengan Link Productive dan STUDiLMU menghadirkan segenap jajaran manajemen pelaksana program Kartu Prakerja oleh Kementrian Perekonomian, Pemerintah Daerah Provinsi Banten seperti jajaran Gubernur/Walikota Tangerang Selatan, serta alumni inspiratif untuk berdialog dan bertukar pikiran tentang program kartu Prakerja.\r\n\r\nKegiatan ini dilaksanakan pada 3 November 2023, di United Grand Hall, Tangerang, Banten. Masyarakat provinsi Banten khususnya Tangerang memiliki potensi yang kuat untuk memberikan dampak positif bagi pembangunan ekonomi daerah sekitarnya. Dengan letak geografis yang memadai, sangat memungkinkan untuk masyarakat disekitar Tangerang dan Banten untuk dapat hadir. Cakupan kehadiran 150 orang.\r\n\r\nBersama Link Productive X Studi Ilmu X Prakerja', '[\"public\\/foto-aktivitas\\/65824b1d18288.jpg\"]', '2023-12-20 09:02:05', '2023-12-20 09:02:05');
INSERT INTO `aktifitas` VALUES (1032, 484, 'Link Productive Preneur Start Up Bussiness', '2023-12-11', 'Link Productive Preneur Start Up Business 2024\r\n\r\nHalo Para Start Up Business Provinsi Banten dan DI Yogyakarta, kamu adalah para Founder & CEO Business Start Up yang berfokus pada pertumbuhan dan juga keberlanjutan bisnis? \r\n\r\nLink Productive Prenuer Startup Business 2024 mengundang para Founder & CEO yang berdomisili di Provinsi Banten & D.I. Yogyakarta untuk meraih kesempatan melakukan akselerasi bisnis bersama Program Link Productive Preneur Start Up Business 2024.', '[\"public\\/foto-aktivitas\\/65824df424134.jpg\"]', '2023-12-20 09:14:12', '2023-12-20 09:14:12');
INSERT INTO `aktifitas` VALUES (1034, 154, 'Kunjungan dan Pembinaan Rutin Tenant Waroenk Overdosis', '2023-11-24', 'PIB UNIBI telah melakukan kunjungan dan pembinaan rutin kepada tenant outwall', '[\"public\\/foto-aktivitas\\/6583ea6f63e46.jpg\"]', '2023-12-21 14:34:07', '2023-12-21 14:34:07');
INSERT INTO `aktifitas` VALUES (1035, 154, 'Konsultasi Usaha Tenant Sukma Project November', '2023-11-27', 'PIB UNIBI secara rutin melakukan konsultasi dan pembinaan terhadap tenant terdaftar', '[\"public\\/foto-aktivitas\\/6583ed4304ecf.jpg\"]', '2023-12-21 14:46:11', '2023-12-21 14:46:11');
INSERT INTO `aktifitas` VALUES (1036, 154, 'Pembinaan dan Pelatihan Laporan Keuangan Revolusioner Store', '2023-11-28', 'PIB UNIBI secara khusus memfasilitasi pembinaan terkait penyusunan laporan keuangan untuk tenant terdaftar', '[\"public\\/foto-aktivitas\\/6583ed8e9465b.jpg\"]', '2023-12-21 14:47:26', '2023-12-21 14:47:26');
INSERT INTO `aktifitas` VALUES (1037, 154, 'Konsultasi Usaha Tenant Bitna Outfit November', '2023-11-28', 'PIB UNIBI secara rutin melakukan pembinaan dan konsultasi usaha bagi tenant terdaftar', '[\"public\\/foto-aktivitas\\/6583eddd11e83.jpg\"]', '2023-12-21 14:48:45', '2023-12-21 14:48:45');
INSERT INTO `aktifitas` VALUES (1038, 158, 'Narsum Kece dari Inkubator', '2023-12-07', 'Bapak Sugeng Rianto selaku Manajer InBis Tuka Tuku dipercaya untuk mengisi sesi motivasi dan narasumber dalam pelatihan Olahan Makanan Kering yang diselenggarakan di Perumda Owabong pada hari kamis-jumat 7-8 Desember 2023. di hadiri oleh 50 peserta yang tergabung dalam wirausaha pemula dan anggota GAPOKTAN output pelatihan ini mengincar skill baruuntuk para peserta. mulai dari pengolahan makaroni keju dsb', NULL, '2023-12-27 12:43:17', '2023-12-27 12:43:17');
INSERT INTO `aktifitas` VALUES (1039, 158, '193 Tahun', '2023-12-21', 'InBis Tuka Tuku ikut kembali dalam mengisi Stand EXPO Hari Jadi Kabupaten Purbalingga ke 193 Tahun. Acara berlangsung mulai dari 21 Desember sampai dengan 24 Desember 2023, tak kalah dengan tahun lalu InBis Tuka Tuku hadir dengan dekorasi yang berbeda. Inbis juga memberikan kesempatan kepada para Tenant untuk mengelola stand tersebut sebagai ajang promosi produknya.', '[\"public\\/foto-aktivitas\\/658e24420f13e.jpeg\",\"public\\/foto-aktivitas\\/658e24420f3b6.jpeg\",\"public\\/foto-aktivitas\\/658e24420f4b7.jpeg\",\"public\\/foto-aktivitas\\/658e24420f7fd.jpeg\"]', '2023-12-29 08:43:30', '2023-12-29 08:43:30');
INSERT INTO `aktifitas` VALUES (1040, 431, 'Jasa Pembuatan Website Gratis bersama ehub.kemenkopukm', '2023-11-23', 'Jasa pembuatan website gratis ini khusus dibuat untuk pelaku usaha dan ekonomi kreatif di seluruh Indonesia dimana hanya dengan membayar Rp. 249.000 per Tahun, anda sudah memiliki website yang keren.\r\n\r\nProgram ini sudah dimulai sejak tanggal 23 November 2023 sampai dengan terpenuhinya 1000 kuota website.', '[\"public\\/foto-aktivitas\\/6597719370b67.png\"]', '2024-01-05 10:03:47', '2024-01-05 10:03:47');
