INSERT INTO `aktifitas` VALUES (1091, 473, 'Pelatihan Digital Pembuatan Website untuk UKM dan Organisasi', '2023-12-23', 'Pelatihan pembuatan Website untuk UKM dan Organisasi merupakan pelatihan yang berkolaborasi dengan Mas Choirul Amri, konsultasn IT Google. Bertujuan untuk mengedukasi platform website sebaga salah satu akses pasar, mengenalkan bisnis dan branding kepada pasar. Pelatihan ini juga memberikan website gratis bagi peserta untuk dapat dimanfaatkan sebagai salah satu akses pasar.', '[\"public\\/foto-aktivitas\\/65d26d47c476f.JPG\",\"public\\/foto-aktivitas\\/65d26d47c4c90.JPG\",\"public\\/foto-aktivitas\\/65d26d47c5294.JPG\"]', '2024-02-19 03:49:11', '2024-02-19 03:49:11');
INSERT INTO `aktifitas` VALUES (1092, 473, 'Pendampingan Pembukaan Usaha Ritel baru, Toko Berasae Koperasi Produsen Ngawi Tani Mandiri', '2024-01-01', 'Pendampingan pembukaan usaha baru dari koperasi Ngawi Tani Mandiri yaitu Toko Ritel Berasae. Toko Ritel ini menjual berasa dan sembako dari anggota Koperasi NTM. Lokasi toko berada di  Mall Pelayanan Publik Kabupaten Ngawi Lantai 1.', '[\"public\\/foto-aktivitas\\/65e0052385ffc.jpeg\"]', '2024-02-19 04:01:01', '2024-02-29 11:16:35');
