INSERT INTO `aktifitas` VALUES (1100, 484, 'Kumpul Jasa Jember Prakerja 2023 - 2024', '2024-02-03', 'Link Productive sukses menjadi Konsultan Pendamping Peserta Alumni Prakerja mendapatkan Juara 1 & 2 untuk Pendampingan UMKM di Daerah Jember.\r\n\r\nKelompok 8 - Juara 1 sukses memberikan Social Impact Peningkatan Bisnis pada usaha UMKM Lalapan Bu Nul dan UMKM Bakso Trisno Jember.\r\n\r\nKelompok 16 - Juara 2 sukses memberikan Social Impact Peningkatan Bisnis pada Usaha Lele Super Jember.\r\n\r\nFokus peningkatan UMKM Naik Kelas Berkelanjutan.\r\n\r\n#UMKMNaikKelas', '[\"public\\/foto-aktivitas\\/65d40be562ac2.jpg\",\"public\\/foto-aktivitas\\/65d40be562d97.jpg\"]', '2024-02-20 09:18:13', '2024-08-09 10:17:36');
