INSERT INTO `aktifitas` VALUES (1201, 376, 'Bazar UMKM Ramadhan tahun 2024', '2024-03-08', 'Bazar UMKM Ramadhan tahun 2024 merupakan kegiatan dalam rangka mempasilitasi Promosi Produk UMKM yang dilakukan selama bulan Ramadhan', '[\"public\\/foto-aktivitas\\/65ea9620a3547.jpeg\",\"public\\/foto-aktivitas\\/65ea9620a375f.jpeg\",\"public\\/foto-aktivitas\\/65ea9620a383d.jpeg\",\"public\\/foto-aktivitas\\/65ea9620a38fe.jpeg\"]', '2024-03-08 11:37:52', '2024-03-08 11:37:52');
