INSERT INTO `aktifitas` VALUES (1247, 376, 'Rapat FGD Koordinator UMKM Kabupaten dan Kecamatan', '2024-03-26', 'Rapat FGD Koordinator UMKM Kabupaten dan Kecamatan dilakukan pada hari selasa tanggal 26 maret 2024 yang bertempat di OR.Sekda dipimpin langsung oleh Pembina UMKM yaitu ibu Hj. Sefti Istiqlal dan dibuka oleh Pj. Sekda Pss. Barat Bpk. Jon Edwar dalam rangka membentuk Organisasi UMKM dengan nama organisasi KURASI ( Komunitas UMKM Krui Generasi Emas Indonesia) yang diketuai oleh Ali Hafif tujuannya agar UMKM naik kelas perlu adanya pembagian wilayah UMKM dengan 4 Kluster.', '[\"public\\/foto-aktivitas\\/66027ec811ae0.jpeg\",\"public\\/foto-aktivitas\\/66027ec811d2e.jpeg\",\"public\\/foto-aktivitas\\/66027ec811e7b.jpeg\",\"public\\/foto-aktivitas\\/66027ec811f6d.jpeg\",\"public\\/foto-aktivitas\\/66027ec812038.jpeg\"]', '2024-03-26 14:52:40', '2024-03-26 14:52:40');
