INSERT INTO `aktifitas` VALUES (1283, 42, 'Inkubasi 5', '2024-04-23', 'Kegiatan Inkubasi 5 membahas mengenai \"Analisis Bisnis Koperasi\" yang dimentori oleh Ikhwan Ferdian Widiarto sebagai CEO Siger Innovation Hub, serta dihadiri oleh 21 orang dengan 16 tenants, membahas mengenai sebarap penting untuk melakukan analisis bisnis terlebih dahulu di koperasi agar bisnis yang akan dijalankan dapat berjalan dengan baik.', '[\"public\\/foto-aktivitas\\/662c87b0b91a7.png\"]', '2024-04-27 12:05:52', '2024-04-27 12:05:52');
