INSERT INTO `aktifitas` VALUES (1285, 42, 'Inkubasi 6', '2024-04-24', 'Kegiatan Inkubasi 6 membahas mengenai \"Bisnis dan Jejaring Koperasi\" yang dimentori oleh M Haniefan Muslim sebagai Pengawas KJMP Setara, serta dihadiri oleh 21 orang dengan 16 tenants, membahas mengenai pentingnya berjejaring sosial saat menjalankan bisnis di koperasi', '[\"public\\/foto-aktivitas\\/662c88cdab12e.jpg\"]', '2024-04-27 12:10:37', '2024-04-27 12:10:37');
INSERT INTO `aktifitas` VALUES (1286, 42, 'Inkubasi 6', '2024-04-24', 'Kegiatan Inkubasi 6 membahas mengenai \"Struktur dan Tata Kelola Koperasi\" yang dimentori oleh Andreas Muhi Pukai sebagai Ketua Pengurus Koperasi Mekar Sai, serta dihadiri oleh 20 orang dengan 16 tenants, membahas mengenai susunan tata kelola koperasi, pentingnya menyusun tata kelola yang baik dan memberikan gambaran mengenai struktur koperasi', '[\"public\\/foto-aktivitas\\/662c894d2c456.jpg\"]', '2024-04-27 12:12:45', '2024-04-27 12:12:45');
INSERT INTO `aktifitas` VALUES (1287, 42, 'Inkubasi 7', '2024-04-25', 'Kegiatan Inkubasi 7 membahas mengenai \"Rencana Kerja dan Restra Koperasi\" yang dimentori oleh Deo Widyastoko sebagai Sekretaris Pengurus Koperasi Mekar Sai, serta dihadiri oleh 20 orang dengan 16 tenants, membahas mengenai perencanaan strategis dalam koperasi, pentingnya perencanaan strategis koperasi dan proses perencanaan strategis', '[\"public\\/foto-aktivitas\\/662c8a14ec265.png\"]', '2024-04-27 12:16:04', '2024-04-27 12:16:04');
INSERT INTO `aktifitas` VALUES (1288, 42, 'Inkubasi 7', '2024-04-25', 'Kegiatan Inkubasi 7 membahas mengenai \"Penyusunan Dasar Kelembagaan Koperasi\" yang dimentori oleh Afriyadi sebagai Asesor LSP DEKOPIN, serta dihadiri oleh 20 orang dengan 16 tenants, membahas mengenai cara menyusun kelembagaan koperasi yang baik, cara mengelola kelembagaan koperasi dan bentuk bentuk kelembagaan koperasi', '[\"public\\/foto-aktivitas\\/662c8aaeb1ea5.png\"]', '2024-04-27 12:18:38', '2024-04-27 12:18:38');
