INSERT INTO `aktifitas` VALUES (1301, 154, 'Studi banding PIB UNIBI ke Skystar Ventures Universitas Multimedia Nusantara', '2024-04-26', 'Pada hari Jumat 26 April 2024, telah dilaksanakan Studi Banding PIB UNIBI Ke Skystar Ventures Universitas Multimedia Nusantara yang sudah menjalankan inkubasi bisnis lebih dari 10 tahun, PIB UNIBI sengaja melakukan studi banding dengan Skystar Ventures UMN dalam rangka mempelajari pengelolaan inkubator bisnis universitas demi tercapainya pelaksanaan inkubasi bisnis yang lebih baik.', '[\"public\\/foto-aktivitas\\/663079e3deb21.jpg\"]', '2024-04-30 11:56:03', '2024-04-30 11:56:03');
