INSERT INTO `aktifitas` VALUES (1308, 42, 'Inkubasi 1', '2024-03-23', 'Kegiatan Inkubasi 1 membahas mengenai \"Sosialisasi perkenalan sigerhub\" yang dimentori oleh Ikhwan Ferdian Widiarto sebagai CEO Siger Innovation Hub, serta dihadiri oleh 16 tenants, membahas mengenai apa itu siger hub, pencapaian sigerhub dan kurikulum inkubasi', '[\"public\\/foto-aktivitas\\/664057366f574.jpg\"]', '2024-05-12 12:44:22', '2024-05-12 12:44:22');
