INSERT INTO `aktifitas` VALUES (1310, 42, 'Inkubasi 2', '2024-03-26', 'Kegiatan Inkubasi 2 membahas mengenai \"Testimoni Koperasi dalam Program LPDB-KUMKM\" yang dimentori oleh Sugeng sebagai Bendahara Koperasi Produksi Ternak Maju Sejahtera, serta dihadiri oleh 16 tenants, membahas mengenai testimoni koperasi produksi ternak maju sejahtera saat mendapatkan pengajuan dana LPDB', '[\"public\\/foto-aktivitas\\/66405c0354bfc.jpg\"]', '2024-05-12 13:04:51', '2024-05-12 13:08:46');
INSERT INTO `aktifitas` VALUES (1311, 42, 'Inkubasi 2', '2024-03-26', 'Kegiatan Inkubasi 2 membahas mengenai \"LPJ Koperasi dan Teknis RAT\" yang dimentori oleh Afriyadi sebagai Asesor LSP Dekopin, serta dihadiri oleh 16 tenants, membahas mengenai pengertian lpj, fungsi lpj, dan format penulisan Lpj pengurus dan pengawas koperasi', '[\"public\\/foto-aktivitas\\/66405c9f62c54.jpg\"]', '2024-05-12 13:07:27', '2024-05-12 13:07:27');
INSERT INTO `aktifitas` VALUES (1312, 42, 'Inkubasi 3', '2024-03-27', 'Kegiatan Inkubasi 3 membahas mengenai \"Ekosistem Koperasi\" yang dimentori oleh Yohanes De Deo Widyastoko sebagai Sekretaris Pengurus Koperasi Mekar Sai, serta dihadiri oleh  17 tenants, membahas mengenai Ekosistem Koperasi, Koperasi multi pihak, bentuk dan pendirian serta jenis dan bentuk usaha', '[\"public\\/foto-aktivitas\\/66405ee169c1c.jpg\"]', '2024-05-12 13:17:05', '2024-05-12 13:17:05');
INSERT INTO `aktifitas` VALUES (1313, 42, 'Inkubasi 3', '2024-03-27', 'Kegiatan Inkubasi 3 membahas mengenai \"Legalitas Koperasi\" yang dimentori oleh M Haniefan Muslim sebagai Ketua Pengawas KJMP Setara, serta dihadiri oleh  17 tenants, membahas mengenai pemahaman legalitas koperasi, akta pendirian koperasi, badan hukum koperasi, sertifikat nomor induk koperasi, dan nomor induk berusaha serta izin usaha simpan pinjam', '[\"public\\/foto-aktivitas\\/66405f6268ff8.jpg\"]', '2024-05-12 13:19:14', '2024-05-12 13:19:14');
