INSERT INTO `aktifitas` VALUES (1316, 42, 'Inkubasi 8', '2024-05-02', 'Kegiatan Inkubasi 8 membahas mengenai \"Ekosistem Perkembangan Koperasi Indonesia dan Dunia\" yang dimentori oleh Novita Puspasari sebagai Dosen FEB Unsoed, serta dihadiri oleh 14 tenants, membahas mengenai Gambaran umum koperasi besar di dunia, perkembangan model koperasi di dunia, dan Perkembangan model koperasi di Indonesia.', '[\"public\\/foto-aktivitas\\/664067682bed4.png\"]', '2024-05-12 13:53:28', '2024-05-12 13:53:28');
INSERT INTO `aktifitas` VALUES (1317, 42, 'Inkubasi 8', '2024-05-02', 'Kegiatan Inkubasi 8 membahas mengenai \"Memaknai Pekerjaan\" yang dimentori oleh Ine Laynazka sebagai HR KJMP Setara, serta dihadiri oleh 14 tenants, membahas mengenai pengertian memaknai pekerjaan, aspek-aspek makna kerja, jenis makna bekerja, internal analysis, dan cara membangun work meaningfullness', '[\"public\\/foto-aktivitas\\/664068103ba13.png\"]', '2024-05-12 13:56:16', '2024-05-12 13:56:16');
