INSERT INTO `aktifitas` VALUES (1319, 42, 'Visitasi 2 ke Koperasi Produsen Agro Gelem Hijau', '2024-05-04', 'Kegiatan visitasi 2 ini mengunjungi rumah produksi koperasi Produsen Agro Gelem Hijau membahas mengenai \"Proses Bisnis Koperasi Produsen Agro Gelem Hijau\" yang dimentori oleh M Haniefan Muslim sebagai Ketua Pengawas KJMP Setara dan Amalia Rahma Putri sebagai Manager Siger Innovation Hub', '[\"public\\/foto-aktivitas\\/66406b694b512.jpg\"]', '2024-05-12 14:10:33', '2024-05-12 14:10:47');
