INSERT INTO `aktifitas` VALUES (1329, 376, 'INKUBATOR CAMP 2024', '2024-05-17', 'INKUBATOR CAMP 2024 Kegiatan yang diadakan oleh Asedep Pengembangan Teknologi dan Inkubasi Usaha Deputi Bidang Kewirausahaan Kemenkop dan UKM dari tgl 16 s.d 21 Mei 2024', '[\"public\\/foto-aktivitas\\/664827359cb46.jpeg\",\"public\\/foto-aktivitas\\/664827359cf5f.jpeg\"]', '2024-05-18 10:57:41', '2024-05-18 10:57:41');
INSERT INTO `aktifitas` VALUES (1330, 585, 'KULINARY CRAFT', '2024-01-15', 'Program Inkubasi Tenant merupakan sebuah program yang ditujukan bagi pelaku usaha potensial dengan memberikan pendampingan intensif serta memberikan akses perluasan pasar yang dapat menunjang pertumbuhan pelaku usaha meliputi pelatihan teknis, coaching, mentoring, konsultasi hingga akses permodalan.\r\n\r\nProgram inkubasi ini meliputi pendampingan berupa kelas Digital Marketing, Design Produk dan Kemasan, Manajemen Mutu, Manajemen keuangan dan Penguatan Legalitas Usaha.', '[\"public\\/foto-aktivitas\\/664e1098a929c.jpg\"]', '2024-05-22 22:34:48', '2024-05-22 22:34:48');
INSERT INTO `aktifitas` VALUES (1331, 585, 'CREATIVE BIZ', '2024-03-02', 'Program inkubasi pengembangan usaha adalah suatu program yang dirancang untuk mendukung dan memfasilitasi pertumbuhan pelaku usaha dalam mengembangkan bisnisnya menjadi entitas yang stabil dan berkelanjutan.\r\n\r\nSiap mengembangkan bisnis Anda? Bergabunglah dengan program Inkubasi Pengembangan Usaha kami dan dapatkan akses untuk pelatihan dan pendampingan intensif! Let’s turn your business dreams into reality.', '[\"public\\/foto-aktivitas\\/664e10e931dc7.jpg\"]', '2024-05-22 22:36:09', '2024-05-22 22:36:09');
INSERT INTO `aktifitas` VALUES (1332, 585, 'GROWTH', '2027-05-27', 'Growth adalah sebuah program yang bertujuan untuk menciptakan wirausaha baru pada bidang industri teknologi digital (Startup) yang dapat memecahkan permasalahan secara kreatif dan inovatif.', '[\"public\\/foto-aktivitas\\/664e1149b0003.jpg\"]', '2024-05-22 22:37:45', '2024-05-22 22:37:45');
INSERT INTO `aktifitas` VALUES (1333, 585, 'Sertifikasi Halal Gratis', '2024-01-01', 'SEHATI (Sertifikasi Halal Gratis) adalah program pendampingan fasilitasi halal untuk pelaku usaha kecil yang memiliki produk makanan/minuman.\r\nSyarat\r\n\r\n    Usaha bergerak dibidang kuliner dengan pengolahan (makanan/minuman).\r\n    Tidak memiliki bahan dari daging hewan sembelihan (ayam, sapi, kambing dsj).\r\n    Tidak tergolong rumah makan/restoran/kafe.\r\n    Bukan usaha Katering.', '[\"public\\/foto-aktivitas\\/664e11fcaa2c2.jpg\"]', '2024-05-22 22:40:44', '2024-05-22 22:40:44');
INSERT INTO `aktifitas` VALUES (1334, 588, 'Pelatihan Digital Marketing', '2023-09-26', 'Training Digital Marketing Praktis untuk UMKM', '[\"public\\/foto-aktivitas\\/664f4180c20d7.jpeg\"]', '2024-05-23 20:15:44', '2024-05-23 20:15:44');
