INSERT INTO `aktifitas` VALUES (1339, 584, 'Jagoan Bisnis 2021', '2021-07-14', 'Jagoan Bisnis Banyuwangi 2021 merupakan program inkubasi bisnis yang bertujuan untuk mengembangkan ekonomi kreatif di Kabupaten Banyuwangi dengan melibatkan wirausahawan muda di Banyuwangi dengan segmen bisnis umum dan digital.', '[\"public\\/foto-aktivitas\\/6656b210da788.jpg\",\"public\\/foto-aktivitas\\/6656b210dab2f.jpg\",\"public\\/foto-aktivitas\\/6656b210dac8e.jpg\"]', '2024-05-29 11:41:52', '2024-05-29 11:52:52');
INSERT INTO `aktifitas` VALUES (1340, 584, 'Jagoan Digital 2021', '2021-11-28', 'Jagoan Digital Banyuwangi 2021 berfokus pada pengembangan bisnis segmen digital yang mendorong generasi muda menuju eksplorasi digital dan literasi, pemasaran online, pengembangan UMKM, dan pembangunan desa berkelanjutan.', '[\"public\\/foto-aktivitas\\/6656b49390180.jpg\",\"public\\/foto-aktivitas\\/6656b49390464.jpg\",\"public\\/foto-aktivitas\\/6656b49390566.jpg\"]', '2024-05-29 11:52:35', '2024-05-29 11:52:35');
INSERT INTO `aktifitas` VALUES (1341, 584, 'Jagoan Bisnis 2022', '2022-07-04', 'Jagoan Bisnis Banyuwangi 2022 merupakan program inkubasi bisnis yang bertujuan untuk mengembangkan ekonomi kreatif di Kabupaten Banyuwangi yang melibatkan wirausahawan Banyuwangi dengan fokus pada bootcamp offline dengan segmen bisnis non digital.', '[\"public\\/foto-aktivitas\\/6656b6ebbe623.jpg\",\"public\\/foto-aktivitas\\/6656b6ebbe990.jpg\",\"public\\/foto-aktivitas\\/6656b6ebbeadf.jpg\",\"public\\/foto-aktivitas\\/6656b6ebbec43.jpg\"]', '2024-05-29 12:02:35', '2024-05-29 12:02:35');
INSERT INTO `aktifitas` VALUES (1342, 584, 'Jagoan Digital 2022', '2022-11-07', 'Jagoan Digital Banyuwangi 2022 mendorong generasi muda menuju eksplorasi digital dan literasi, fokus pada pemasaran online, dan pengembangan UMKM dengan fokus pada bootcamp pada masing-masing role hacker, hustler, dan hipster.', '[\"public\\/foto-aktivitas\\/6656baa980e7e.jpg\",\"public\\/foto-aktivitas\\/6656baa98117e.jpg\",\"public\\/foto-aktivitas\\/6656baa9812b7.jpg\",\"public\\/foto-aktivitas\\/6656baa981405.jpg\"]', '2024-05-29 12:18:33', '2024-05-29 12:18:33');
INSERT INTO `aktifitas` VALUES (1343, 584, 'Jagoan Tani 2023', '2023-06-11', 'Jagoan Tani Banyuwangi 2023 adalah sebuah program inkubasi tahunan yang diadakan oleh Pemerintah Kabupaten Banyuwangi dalam rangka  menumbuhkan semangat wirausaha di bidang agribisnis bagi generasi muda. Jagoan tani berfokus pada pengembangan bisnis pertanian oleh Anak muda.', '[\"public\\/foto-aktivitas\\/6656be7d92241.jpg\",\"public\\/foto-aktivitas\\/6656be7d92557.jpg\",\"public\\/foto-aktivitas\\/6656be7d92760.jpg\",\"public\\/foto-aktivitas\\/6656be7d92986.jpg\"]', '2024-05-29 12:34:53', '2024-05-29 12:34:53');
INSERT INTO `aktifitas` VALUES (1344, 584, 'Jagoan Digital 2023', '2023-08-16', 'Jagoan Digital Banyuwangi 2023 mendorong generasi muda menuju eksplorasi digital dan literasi, fokus pada pemasaran online, dan pengembangan UMKM dengan fokus pada bootcamp pada masing-masing role hacker, hustler, dan hipster.', '[\"public\\/foto-aktivitas\\/6656bfbd6d0d1.jpg\",\"public\\/foto-aktivitas\\/6656bfbd6d3e4.jpg\",\"public\\/foto-aktivitas\\/6656bfbd6d551.jpg\",\"public\\/foto-aktivitas\\/6656bfbd6d727.jpg\"]', '2024-05-29 12:40:13', '2024-05-29 12:40:13');
INSERT INTO `aktifitas` VALUES (1345, 584, 'Jagoan Bisnis 2023', '2023-08-15', 'Jagoan Bisnis Banyuwangi 2023 merupakan program inkubasi bisnis yang bertujuan untuk mengembangkan ekonomi kreatif di Kabupaten Banyuwangi yang melibatkan wirausahawan Banyuwangi dengan fokus pada bootcamp offline dengan segmen bisnis non digital.', '[\"public\\/foto-aktivitas\\/6656c13d818a2.jpg\",\"public\\/foto-aktivitas\\/6656c13d81bee.jpg\",\"public\\/foto-aktivitas\\/6656c13d81e00.jpg\",\"public\\/foto-aktivitas\\/6656c13d81f82.jpg\"]', '2024-05-29 12:46:37', '2024-05-29 12:46:37');
INSERT INTO `aktifitas` VALUES (1346, 584, 'Megilan Entrepreneur 2022', '2022-03-21', 'Megilan Entrepreneur 2022 adalah program inkubasi bisnis wirausaha muda yang diselenggarakan oleh Dinas Koperasi dan Usaha Mikro Kab. Lamongan. Program ini menjadi program unggulan dalam membina pebisnis muda.', '[\"public\\/foto-aktivitas\\/6656cdc4d0a0a.jpg\",\"public\\/foto-aktivitas\\/6656cdc4d0c4d.jpg\",\"public\\/foto-aktivitas\\/6656cdc4d0d39.jpg\",\"public\\/foto-aktivitas\\/6656cdc4d0e2e.jpg\"]', '2024-05-29 13:31:08', '2024-05-29 13:40:04');
INSERT INTO `aktifitas` VALUES (1347, 584, 'Megilan Entrepreneur 2023', '2023-06-06', 'Megpreneur merupakan rangkaian program inkubasi untuk mencetak para pebisnis sukses yang diinisiasi oleh pemerintah Kabupaten Lamongan. Rangkaian program megpreneur ini meliputi mentoring secara online, offline dan tinjauan langsung di lokasi.', '[\"public\\/foto-aktivitas\\/6656ce7fd6f3f.jpg\",\"public\\/foto-aktivitas\\/6656ce7fd7288.jpg\",\"public\\/foto-aktivitas\\/6656ce7fd73f5.jpg\",\"public\\/foto-aktivitas\\/6656ce7fd74fd.jpg\"]', '2024-05-29 13:43:11', '2024-05-29 13:43:11');
INSERT INTO `aktifitas` VALUES (1348, 584, 'Kediri Pehneur 2023', '2023-09-21', 'Kediri Pehneur 2023 merupakan rangkaian program inkubasi untuk mencetak para pebisnis sukses yang diinisiasi oleh Pemerintah Kota Kediri. Rangkaian program Kediri Pehneur ini meliputi mentoring secara online, offline dan pitching.', '[\"public\\/foto-aktivitas\\/6656d589f0d15.jpg\",\"public\\/foto-aktivitas\\/6656d589f1515.jpg\",\"public\\/foto-aktivitas\\/6656d589f1d2f.jpg\",\"public\\/foto-aktivitas\\/6656d589f226d.jpg\"]', '2024-05-29 13:56:18', '2024-05-29 14:13:13');
INSERT INTO `aktifitas` VALUES (1349, 584, 'Kita Tani Muda Semarang 2024', '2024-02-19', 'Progam Kita Tani Muda Semarang merupakan Program Inkubasi Bisnis untuk Wirausaha muda lokal kota Semarang. Dimentori oleh berbagai founder startup lokal hingga nasional, program ini akan mampu menciptakan embrio wirausaha muda baru yang berbasis inovasi pertanian untuk Kota Semarang.', '[\"public\\/foto-aktivitas\\/6656d333dfe5a.jpg\",\"public\\/foto-aktivitas\\/6656d333e061b.jpg\",\"public\\/foto-aktivitas\\/6656d333e0d9f.jpg\",\"public\\/foto-aktivitas\\/6656d333e1969.jpg\"]', '2024-05-29 14:03:15', '2024-05-29 14:03:15');
INSERT INTO `aktifitas` VALUES (1350, 42, 'Kegiatan Visitasi 3 ke Koperasi Ternak Maju Sejahtera', '2024-05-17', 'Kegiatan visitasi 3 ini mengunjungi Koperasi Ternak Maju Sejahtera membahas mengenai \"Persyaratan OTS Bisnis Koperasi\" yang dimentori oleh Amalia Rahma Putri sebagai Manager Siger Innovation Hub dan Dini Desita sebagai Staff Administrasi Siger Innovation Hub', '[\"public\\/foto-aktivitas\\/6659e30c05476.jpg\"]', '2024-05-31 21:47:40', '2024-05-31 21:47:40');
INSERT INTO `aktifitas` VALUES (1351, 42, 'Kegiatan Visitasi 4 ke Koperasi Ternak Maju Sejahtera', '2024-05-20', 'Kegiatan visitasi 4 ini mengunjungi Koperasi Ternak Maju Sejahtera membahas mengenai \"Proyeksi Keuangan Koperasi dan Kelengkapan Dokumen Pengajuan Kedua\" yang dimentori oleh Ikhwan Ferdian Widiarto sebagai CEO Siger Innovation Hub dan Amalia Rahma Putri sebagai Manager Siger Innovation Hub', '[\"public\\/foto-aktivitas\\/6659e3e598cc9.jpg\"]', '2024-05-31 21:51:17', '2024-05-31 21:51:17');
