INSERT INTO `aktifitas` VALUES (1357, 471, 'Pelatihan untuk tenant dan Penanda Tanganan Kontrak kerjasama dengan Inkubasi Bisnis Sumbar PLUT-In', '2024-03-01', 'Sasaran dari palaksanaan kegiatan pelatihan ini adalah UMKM yang siap berekmbang dengan Lembaga inkubasi Sumbar PLUT-In', '[\"public\\/foto-aktivitas\\/6661279467041.jpg\"]', '2024-06-06 10:05:56', '2024-06-06 10:05:56');
INSERT INTO `aktifitas` VALUES (1358, 471, 'Meningkatkan pengetahuan dan ketrampilan Pelaku usaha dalam pengembangan usahanya masing-masing', '2024-04-25', 'Peserta dapat menjelaskan usahanya sehingga dapat mengidentifikasi permasalahan dari masing-masing usahanya. Berubahnya pola pikir peserta kearah yang lebih baik. Peserta memiliki arah rencana dan tujuan untuk masa yang akan datang.', '[\"public\\/foto-aktivitas\\/666133975f547.png\"]', '2024-06-06 10:57:11', '2024-06-06 10:57:11');
INSERT INTO `aktifitas` VALUES (1359, 471, 'Meningkatkan pengetahuan dan keterampilan tenant tenant Inkubator Plut-In dalam menumbuhkan pasar yang tepat dan melihat peluang pasar', '2024-03-26', 'Peserta mengerti dan terampil dalam menumbuhkan pasar yang tepat. Berubahnya pola pikir peserta kearah yang lebih baik. Peserta mampu melihat peluang pasar dan memahami promosi yang benar', '[\"public\\/foto-aktivitas\\/666136387c439.png\"]', '2024-06-06 11:08:24', '2024-06-06 11:08:24');
