INSERT INTO `aktifitas` VALUES (1363, 200, 'pameran produk tenant di kegiatan Industrial Vocational Fair 2024', '2024-02-06', 'pameran produk tenant binaan pada kegiatan Industrial Vocational Fair regional Sulawesi Kementerian Perindustrian dirangkaikan dengan test uji pasar produk tenant binaan.', '[\"public\\/foto-aktivitas\\/66743fdfbef16.jpg\",\"public\\/foto-aktivitas\\/66743fdfbf1ee.jpeg\",\"public\\/foto-aktivitas\\/66743fdfbf36b.jpeg\",\"public\\/foto-aktivitas\\/66743fdfbf4a5.jpeg\"]', '2024-06-20 21:42:39', '2024-06-20 21:43:05');
INSERT INTO `aktifitas` VALUES (1364, 549, 'Kick Off dan Booth Camp Inkubasi Bisnis', '2024-06-20', 'Pembukaan kegiatan Inkubasi Bisnis LINK KITA di Kab. Pacitan yang diselenggarakan selama 2 hari mulai tanggal 20 - 21 Juni 2024 di Aula Gedung PLUT KUMKM Kab. Pacitan.\r\nKegiatan dibuka oleh Kepala DInas Koperasi Usaha Mikro dan Perindustrian Kab. Pacitan beserta Direktur LINK KITA. Kegiatan ini sekaligus seleksi bagi calon tenant dari 50 peserta ke 25 peserta dengan tim penilai dari Dinas, LINK KITA dan Eureka Mahardika', '[\"public\\/foto-aktivitas\\/66780437d279c.jpg\"]', '2024-06-23 18:17:11', '2024-06-23 18:17:11');
INSERT INTO `aktifitas` VALUES (1365, 613, 'peresmian konsorsium inkubator', '2023-12-03', 'Bersama bupati bengkalis, forkompinda dan Politeknik Negeri Bengkalis, meresmikan konsorsium inkubator bisnis dan teknologi polbeng. Dimana akan ada keterlibatan masyarakat untuk Kabupaten Bengkalis khususnya Pemuda Bengkalis dalam mendapatkan peran inkubasi nantinya dari inkubator bisnis dan teknologi polbeng', '[\"public\\/foto-aktivitas\\/66792de6981a7.JPG\"]', '2024-06-24 15:27:18', '2024-06-24 15:27:18');
