INSERT INTO `aktifitas` VALUES (1375, 376, 'FASILITASI UMKM PADA KEGIATAN KRUI PRO', '2024-05-28', 'Fasilitasi UMKM pada kegiatan Krui Pro yang dilaksanakan dari tanggal 28 mei s.d 4 juni 2024 merupakan upaya dalam upaya Perluasan Promosi dan Meningkatkan Pemasaran bagi UMKM yang ada dikabupaten Peisir Barat.', '[\"public\\/foto-aktivitas\\/668203bac5b3c.jpeg\",\"public\\/foto-aktivitas\\/668203bac5e64.jpeg\",\"public\\/foto-aktivitas\\/668203bac5fe2.jpeg\",\"public\\/foto-aktivitas\\/668203bac61b9.jpeg\",\"public\\/foto-aktivitas\\/668203bac633b.jpeg\"]', '2024-07-01 08:12:19', '2024-07-01 08:17:46');
INSERT INTO `aktifitas` VALUES (1376, 376, 'Pekan Fastival Road To Melasti', '2024-06-12', 'Kegiatan Pekan Fastival Road To Melasti (Pekan Fest) merupakan kegiatan kolaborasi baik OPD, Kecamatan, Pekon dan pihak lainnya dalam rangka membangiktkan UMKM dari segi Promosi dan Pemasaran Produk yang dilaksanakan selama 2 hari dari tanggal 12 juni s.d 13 juni 2024 di Pantai Melasti Kecamatan Pesisir Selatan Kabupaten Pesisir Barat Lampung.', '[\"public\\/foto-aktivitas\\/6682038c21fa8.jpeg\",\"public\\/foto-aktivitas\\/6682038c226a6.jpeg\",\"public\\/foto-aktivitas\\/6682038c228b8.jpeg\",\"public\\/foto-aktivitas\\/6682038c22a22.jpeg\",\"public\\/foto-aktivitas\\/6682038c22be9.jpeg\"]', '2024-07-01 08:17:00', '2024-07-01 08:17:00');
