INSERT INTO `aktifitas` VALUES (1591, 723, 'KUNJUNGAN MASYARAKAT, PEJABAT, PENGUSAHA DAN KEPALA DAERAH DI SENTRA MELON DIDROPONIK SWEET NET', '2024-03-23', 'Selain bidang Teknologi Komputer, kami juga mengembangkan segala bidang usaha di antaranya : Kebun Melon Sweet Net hidroponik, Jamur Jagung dan Peternakan', '[\"public\\/foto-aktivitas\\/66b6d501c3cb5.jpeg\",\"public\\/foto-aktivitas\\/66b6d501c3f42.jpeg\",\"public\\/foto-aktivitas\\/66b6d501c4033.jpeg\",\"public\\/foto-aktivitas\\/66b6d501c4189.jpeg\",\"public\\/foto-aktivitas\\/66b6d501c42bd.jpeg\"]', '2024-08-10 09:48:33', '2024-08-10 11:03:40');
INSERT INTO `aktifitas` VALUES (1592, 868, 'Pelatihan Digital Skill Basic Multimedia Talenthub Kemnaker RI', '2022-11-14', 'Talenthub memfasilitasi program pengembangan kewirausahaan dan pelatihan peningkatan skill sesuai dengan relevansi kebutuhan industri yang berubah dengan cepat saat ini. Selain itu Talenthub juga menghubungkan talenta potensial dengan kesempatan kerja melalui program-program match making.', '[\"public\\/foto-aktivitas\\/66b6d84eabb8e.jpg\"]', '2024-08-10 10:02:38', '2024-08-10 10:02:38');
INSERT INTO `aktifitas` VALUES (1593, 868, 'Pelatihan Editing News (Jurnalistik Televisi) bersama Kompas TV Pekalongan', '2022-11-23', 'Jurnalistik Televisi adalah pekerjaan memotong – motong dan merangkaikan atau menyambung potongan – potongan gambar sehingga menjadi film berita yang utuh dan dapat dimengerti. Proses editing merupakan serangkaian dari proses pasca – produksi dan merupakan tahapan yang penting agar materi dapat disampaikan dengan jelas dan menarik.', '[\"public\\/foto-aktivitas\\/66b6da6ada18c.jpg\"]', '2024-08-10 10:11:38', '2024-08-10 10:12:22');
