INSERT INTO `aktifitas` VALUES (1613, 154, 'Screening Tahap 1 Tenant Inwall Inkubasi PIB UNIBI 2024 - Nayyara / Nayyz Pattiserie', '2024-07-15', 'PIB UNIBI memiliki program pembinaan bisnis berkelanjutan yang dinamakan Inkubasi. Screening Tenant Inwall Inkubasi PIB UNIBI 2024 telah dimulai, pada tahap 1 ini para peserta melakukan screening dengan tim PIB UNIBI. Foto di atas adalah salah satu peserta screening tenant inwall atas nama Nayyara yang menawarkan produk F&B Nayyz Pattiserie', '[\"public\\/foto-aktivitas\\/66b9c4aa79dd1.jpg\"]', '2024-08-12 15:15:38', '2024-08-12 15:15:38');
