INSERT INTO `aktifitas` VALUES (1645, 785, 'Kolaborasi dengan Dinas Koperasi dan UKM Kab. Magetan', '2024-08-14', 'Kolaborasi dengan Dinkop dan UKM Kab. Magetan dalam rangka mensinergikan program-program Inkubator dengan stakeholder', '[\"public\\/foto-aktivitas\\/66bc95b81c310.jpg\"]', '2024-08-14 18:32:08', '2024-09-15 11:08:02');
