INSERT INTO `aktifitas` VALUES (1712, 42, 'Visitasi 34', '2024-08-11', 'Kegiatan visitasi 34 ini mengunjungi Koperasi Produksi Ternak Maju Sejahtera membahas mengenai \"Potensi Bisnis Koperasi\" yang dimentori oleh Amalia Rahma Putri sebagai Manager Siger Innovation Hub dan Dini Desita sebagai Staff Administrasi Siger Innovation Hub', '[\"public\\/foto-aktivitas\\/66c20849436d1.jpg\"]', '2024-08-18 11:01:19', '2024-08-18 21:42:17');
INSERT INTO `aktifitas` VALUES (1713, 42, 'Visitasi 35', '2024-08-12', 'Kegiatan visitasi 35 ini mengunjungi Rumah Produksi Koperasi Bina Sukses Jejama membahas mengenai \"Kelengkapan Berkas OKR Koperasi\" yang dimentori oleh Amalia Rahma Putri sebagai Manager Siger Innovation Hub dan Dini Desita sebagai Staff Administrasi Siger Innovation Hub', '[\"public\\/foto-aktivitas\\/66c208f1b5ac3.jpg\"]', '2024-08-18 19:42:28', '2024-08-18 21:45:05');
INSERT INTO `aktifitas` VALUES (1717, 461, 'Pelathan Eco Print Program Capacity Building', '2023-12-18', 'Pelathan Eco Print Program Capacity Building Kerjasama Dinas Koperasi dan UKM Kab. Jeneponto, PLN Peduli dan JIPO (Jejaring Inkubasi Jeneponto) dilaksanakan selama 3 (tiga) Hari tanggal 18 s/d 20 November 2023', '[\"public\\/foto-aktivitas\\/66c2c3dcdf688.jpeg\",\"public\\/foto-aktivitas\\/66c2c3dcdf8da.jpeg\",\"public\\/foto-aktivitas\\/66c2c3dcdfa06.jpeg\"]', '2024-08-19 11:02:36', '2024-08-19 11:14:01');
