INSERT INTO `aktifitas` VALUES (1720, 104, 'Bootcamp', '2023-06-05', 'Bootcamp dilaksanakan pada Kamis, 4 Juli 2024 bertempat di Ruang Damandiri Lt. 4 Universitas Trilogi. Acara bootcamp ini adalah kegiatan dimana tenant akan mendapatkan pelatihan intensif dari para Narasumber yang ahli dibidang terkait. Materi-materi yang disampaikan adalah mengenai Pondasi dan Model Bisnis yang disampaikan oleh Bapak Maulidian, S.Hut., M.M. seorang akademisi dan praktisi di bidang Agribisnis, Laporan Keuangan oleh Ibu Novita, S.E., Ak., M.Ak., CSRS., CA., CertIPSAS. seorang praktisi di bidang Akuntan, Pengembangan Produk oleh Ibu Mutiara Dewi Puspitawati, SP., M.Si. seorang praktisi di bidang Agroekoteknologi, dan yang terakhir adalah materi Digital Marketing oleh Bapak Mufti Utama, S.Kom. praktisi di bidang Digital Marketing.', '[\"public\\/foto-aktivitas\\/66c2ee2d19d43.JPG\"]', '2024-08-19 13:47:01', '2024-08-19 14:03:09');
