INSERT INTO `aktifitas` VALUES (1807, 376, 'PEKAN FEST NAYUH DI BANGKUNAT SEMARAK HUT-RI KE 79 BERSAMA UMKM', '2024-08-21', 'Kegiatan ini merupakan salah satu upaya Pemerintah Kabupaten Pesisir Barat untuk menghidupkan sektor ekonomi masyarakat melalui fasilitasi pemasaran dan promosi produk-produk UMKM dari para pelaku UMKM yang ada di Kabupaten Pesisir Barat dalam mengembangkan bisnisnya. Omset dari hasil kegiatan tersebut Rp. 84.260.000', '[\"public\\/foto-aktivitas\\/66cd467fb0d43.jpeg\",\"public\\/foto-aktivitas\\/66cd467fb1498.jpeg\",\"public\\/foto-aktivitas\\/66cd467fb1618.jpeg\",\"public\\/foto-aktivitas\\/66cd467fb17c2.jpeg\",\"public\\/foto-aktivitas\\/66cd467fb18c9.jpeg\"]', '2024-08-27 10:22:39', '2024-09-03 15:18:11');
