INSERT INTO `aktifitas` VALUES (1811, 167, 'Bincang-Bincang Koperasi dan Wirausaha Muda', '2022-06-09', 'Kegiatan diskusi dengan tenant Yayasan Sinar Tani Indonesia yang dihadiri oleh Bapak Menteri Koperasi dan UKM RI dan Bapak Walikota Medan', '[\"public\\/foto-aktivitas\\/66cf065daacc1.JPG\",\"public\\/foto-aktivitas\\/66cf065dab3e1.JPG\",\"public\\/foto-aktivitas\\/66cf065dab71e.JPG\"]', '2024-08-28 18:13:33', '2024-08-28 18:13:33');
