INSERT INTO `aktifitas` VALUES (1813, 918, 'RAPAT KOORDINASI INKUBASI KEWIRAUSAHAAN BAGI BLK KOMUNITAS', '2024-08-13', 'Membangun Sumber Daya Manusia Ketenagakerjaan Melalui Pelataihan Vokasi Berbasis Komunitas', '[\"public\\/foto-aktivitas\\/66cfcf415bf0a.jpeg\"]', '2024-08-29 08:30:41', '2024-08-29 08:30:41');
INSERT INTO `aktifitas` VALUES (1814, 918, 'PENGUATAN KOMPETENSI TENAGA PELATIHAN BLK KOMUNITAS INKUBATOR WIRAUSAHA', '2024-11-28', 'Mengingat\r\nmasih sangat terbatasnya kemampuan BLK-Komunitas untuk menyalurkan lulusannya masuk ke\r\nDUDI, maka perlu strategi bagi pengelola BLK-Komunitas untuk memfasilitasi lulusannya.', '[\"public\\/foto-aktivitas\\/66cfd1d38470f.jpeg\"]', '2024-08-29 08:41:39', '2024-08-29 08:41:39');
INSERT INTO `aktifitas` VALUES (1815, 918, 'PENINGKATAN KAPASITAS KELEMBAGAAN PELATIHAN VOKASI DAN PRODUKTIVITAS', '2024-03-04', 'Dalam rangka peningkatan kapasitas kelembagaan pelatihan vokasi dan produktivitas, Direktorat Bina Kelembagaan Pelatihan Vokasi telah melaksanakan kegiatan implementasi pemetaan mutu lembaga pelatihan kerja', '[\"public\\/foto-aktivitas\\/66cfd42e79a27.jpeg\"]', '2024-08-29 08:51:42', '2024-08-29 08:51:42');
INSERT INTO `aktifitas` VALUES (1816, 918, 'FOCUS GROUP DISCUSSION ( FGD )', '2024-03-02', 'Sosialisasi Peta Jalan Kemandirian BLK Komunitas', '[\"public\\/foto-aktivitas\\/66cfd8d3d584f.jpeg\"]', '2024-08-29 09:11:31', '2024-08-29 09:11:31');
INSERT INTO `aktifitas` VALUES (1817, 918, 'PERESMIAN BLKK DAN SANTRI FEST', '2023-10-23', 'Dalam rangka peringatan Hari Santri yang dirayakan setiap tanggal 22 Oktober, dengan tema Berdaya menjaga martabat kemanusiaan. Kementerian Ketenagakerjaan meresmikan BLK Komunitas dan menyelenggarakan Santri Fest 2022', '[\"public\\/foto-aktivitas\\/66cfe77018329.jpeg\"]', '2024-08-29 10:13:52', '2024-11-07 07:04:23');
INSERT INTO `aktifitas` VALUES (1818, 376, 'Kunjungan Bidang Kelembagaan Koperasi dari Dinas Koperasi dan UKM Prov. Lampung', '2024-08-29', 'menerima Kunjungan dari Bidang Kelembagaan Koperasi dari Dinas Koperasi dan UKM Prov. Lampung dalam rangka Koordinasi terkait Kegiatan-Kegiatan apa saja yang sudah dilakukan oleh Dinas Koperasi, UKM dan Perdagangan Kabupaten Pesisir Barat Lampung', '[\"public\\/foto-aktivitas\\/66cfe90fc4ea2.jpeg\",\"public\\/foto-aktivitas\\/66cfe90fc5486.jpeg\",\"public\\/foto-aktivitas\\/66cfe90fc5919.jpeg\",\"public\\/foto-aktivitas\\/66cfe90fc5d86.jpeg\"]', '2024-08-29 10:20:47', '2024-08-29 10:20:47');
INSERT INTO `aktifitas` VALUES (1819, 53, '“Malang Halal Culinary Festival UNISMA 2024” Pelaku UMKM se- Malang Raya', '2024-05-15', '“Malang Halal Culinary Festival UNISMA 2024” Pelaku UMKM se-Malang Raya ini merupakan upaya untuk mempertunjukan kompetensi hasil cipta produk usaha makanan (kuliner) khas daerah Malang sesuai kriteria yang telah ditentukan. Melalui kegiatan ini, hasil karya tersebut diharapkan memperoleh respon positif dan mampu meyakinkan masyarakat umum dan pengunjung pada khususnya untuk mengapresiasi wirausaha yang mengangkat potensial kedaerahan yang marketable. Peran UNISMA sebagai perguruan tinggi yang Unggul dan sebagai bagian dari masyarakat bersama seluruh stakeholder yang terkait akan memberikan gambaran visual kepada publik tentang iklim kewirausahaan akan diraih dan ditumbuhkembangkan di UNISMA dan lokal sekitarnya.', '[\"public\\/foto-aktivitas\\/66d02200ef0d7.jpg\"]', '2024-08-29 14:23:44', '2024-08-29 14:23:44');
INSERT INTO `aktifitas` VALUES (1820, 163, 'MOU dengan Maxim', '2024-02-12', 'MoU dalam Pemasaran digital Tenant Unbara Business Park', '[\"public\\/foto-aktivitas\\/66d028f131601.jpg\"]', '2024-08-29 14:53:21', '2024-08-29 14:53:21');
INSERT INTO `aktifitas` VALUES (1821, 163, 'MoU Dinas Koperasi dan UMKM OKU dengan UBP', '2024-02-12', 'MoU Mentor dan Resource Sharing', '[\"public\\/foto-aktivitas\\/66d0294ab2ef6.jpg\"]', '2024-08-29 14:54:50', '2024-08-29 14:54:50');
