INSERT INTO `aktifitas` VALUES (1823, 53, 'Pameran Karya Wirausaha dan Inovasi UNISMA 2023', '2023-12-29', '“Pameran Karya Wirausaha dan Inovasi ” Universitas Islam Malang ini akan mengangkat potensi dan pencapaian penyelenggaraan perkuliahan Kewirausahaan di Universitas Islam Malang meliputi karya mahasiswa, karya dosen (hasil pengajaran, penelitian dan pengabdian), dan karya karyawan civitas akademika.', '[\"public\\/foto-aktivitas\\/66d02b1455217.jpg\"]', '2024-08-29 15:02:28', '2024-08-29 15:02:28');
INSERT INTO `aktifitas` VALUES (1824, 53, 'Jalan Sehat dan Bazar Kuliner Khas Malang DIES ke-43 UNISMA 2024', '2024-06-23', 'Dalarn rangka Dies Natalis ke-43 Universitas Islam Malang menyelenggarakan Jalan Sehat dan Festival Bazar Kuliner Khas Malang bagi Civitas Akademika yang berwirausaha serta Pelaku UMKM se-Malang Raya', '[\"public\\/foto-aktivitas\\/66d02d8d07382.jpg\"]', '2024-08-29 15:13:01', '2024-08-29 15:13:01');
INSERT INTO `aktifitas` VALUES (1825, 53, 'FGD Pengembangan UMKM dan Bazar kolaborasi P2KIB Unisma dengan IPEMI Malang', '2024-06-23', 'Pusat Pengembangan Kewirausahaan dan Inkubator Bisnis Universitas Islam Malang (P2KIB Unisma) bersama Ikatan Pengusaha Muslimah Indonesia (IPEMI) Kota Malang menggelar Focus Group Discussion (FGD) pengembangan Usaha Mikro, Kecil dan Menengah (UMKM), Minggu', '[\"public\\/foto-aktivitas\\/66d02db8ef7ea.jpeg\"]', '2024-08-29 15:13:44', '2024-08-29 15:13:44');
