INSERT INTO `aktifitas` VALUES (1859, 152, 'Entrepreneur Hub, Solo Raya : Grow and Sustain', '2024-05-14', 'Kegiatan Entreprenuer Hub merupakan kegiatan yang diadakan oleh Kementrian Koperasi dan UKM Republik Indonesia untuk mewadahi dan memberikan pelatihan kepada pelaku UMKM sebagai bentuk fasilitas dari KEMENKOPUKM untuk mendukung peningkatan kualitas UKM di Inodonesia.', '[\"public\\/foto-aktivitas\\/66d52d18b6fb5.jpg\"]', '2024-09-02 10:12:24', '2024-09-02 10:12:24');
INSERT INTO `aktifitas` VALUES (1860, 152, 'Entrepreneur Hub, Yogyakarta : Grow and Sustain', '2024-03-28', 'Kegiatan Entreprenuer Hub merupakan kegiatan yang diadakan oleh Kementrian Koperasi dan UKM Republik Indonesia untuk mewadahi dan memberikan pelatihan kepada pelaku UMKM sebagai bentuk fasilitas dari KEMENKOPUKM untuk mendukung peningkatan kualitas UKM di Inodonesia.', '[\"public\\/foto-aktivitas\\/66d52d552e4c7.jpg\"]', '2024-09-02 10:13:25', '2024-09-02 10:13:25');
INSERT INTO `aktifitas` VALUES (1861, 154, 'Penyerahan Sertifikat Tenant Inwall 2024 Dan Diskusi Perdana Tenant Inwall Didampingi Oleh Tim PIB UNIBI', '2024-08-20', 'Penyerahan Sertifikat Tenant Inwall 2024 Dan Diskusi Perdana Tenant Inwall Didampingi Oleh Tim PIB UNIBI', '[\"public\\/foto-aktivitas\\/66d599868a582.jpg\"]', '2024-09-02 17:55:02', '2024-09-02 17:55:02');
INSERT INTO `aktifitas` VALUES (1862, 154, 'Sosialisasi Pedoman PIB UNIBI Kepada Perwakilan Sivitas Akademika UNIBI', '2024-08-20', 'Bandung, 20 Agustus 2024 - Telah dilaksanakannya kegiatan Sosialisasi Pedoman PIB UNIBI kepada Perwakilan Sivitas Akademika UNIBI agar terciptanya kesamaan pemahaman akan Pedoman Pusat Inovasi dan Inkubator Bisnis UNIBI dan semakin terciptanya sinergitas antara PIB UNIBI dengan Sivitas Akademika guna menumbuhkan dan mengembangkan jiwa-jiwa entrepreneurship di kalangan mahasiswa/i UNIBI, agar mahasiswa/i UNIBI memiliki bekal dalam berbisnis baik itu ilmu pengetahuan formal, informal dan praktis.', '[\"public\\/foto-aktivitas\\/66d599c1d583f.jpg\"]', '2024-09-02 17:56:01', '2024-09-02 17:56:01');
INSERT INTO `aktifitas` VALUES (1863, 152, 'Training of Facilitator Dosen Kewirausahaan', '2024-08-07', 'Training of Facilitator bagi Dosen Kewirausahaan yang diselenggarakan oleh KEMENPORA', '[\"public\\/foto-aktivitas\\/66d66171dfaa6.jpg\",\"public\\/foto-aktivitas\\/66d66171e0122.jpg\",\"public\\/foto-aktivitas\\/66d66171e02a6.jpg\",\"public\\/foto-aktivitas\\/66d66171e0432.jpg\",\"public\\/foto-aktivitas\\/66d66171e0612.jpg\"]', '2024-09-03 08:08:01', '2024-09-03 08:08:01');
