INSERT INTO `aktifitas` VALUES (1865, 376, 'Partisipasi UMKM dalam Kegiatan kemah Apel Besar Hari Pramuka ke  63 tahun 2024 Tk Daerah Lampung', '2024-08-29', 'Partisipasi UMKM dalam Kegiatan kemah Hari Pramuka ke  63 tahun 2024 Tk Daerah Lampung pada tgl 29 Agustus s/d 1 September 2024 di Lapangan Kijang Kec. Pss Tengah Kabupaten Pesisir Barat. Omset penjualan UMKM selama 4 hari kegiatan  sebesar Rp. 46.997.000', '[\"public\\/foto-aktivitas\\/66d6c52a982a0.jpeg\",\"public\\/foto-aktivitas\\/66d6c52a98dbe.jpeg\",\"public\\/foto-aktivitas\\/66d6c52a99274.jpeg\",\"public\\/foto-aktivitas\\/66d6c52a9b137.jpeg\"]', '2024-09-03 15:13:30', '2024-09-03 15:14:08');
