INSERT INTO `aktifitas` VALUES (1883, 659, 'Penerbitan Sertifikat Tanda Daftar Oleh Kemenkop dan Pendamping Inkubator', '2024-09-07', 'Sabtu, 07 September 2024 telah terbit sertifikat tanda daftar sipensi oleh kemenkop dan disampaikan oleh pendamping inkubator dalam hal ini kami Sentra Inovasi dan Inkubator Bisnis BLK Komunitas Al Mahrusiyah Lirboyo di dampingi Oleh LP2M UIN Sunan Ampel Surabaya, kami berharap pendampingan ini tidak berhenti dan akan terus berlanjut sehingga terbentuklah kerjasama maupun kolaborasi antara Kemenaker, Kemenkop, Pendamping Inkubator, dan Lembaga inkubator sehingga angka pengangguran di indonesia berkurang dan banyak UMKM yang sejahtera dan maju dengan mengikuti Inkubasi dalam Inkubator binaan Lembaga Inkubator BLKK,\r\n\r\nKediri, 07 September 2024\r\nManajer Inkubator\r\n(Ahmad Sholihuddin)', '[\"public\\/foto-aktivitas\\/66dbd67ea2f52.jpeg\"]', '2024-09-07 11:28:46', '2024-09-07 11:28:46');
