INSERT INTO `aktifitas` VALUES (1905, 189, 'In House Training \"Strategi Pengembangan Ide Usaha dan Inovasi Produk\"', '2024-06-21', 'Tujuan pelaksanaan bimbingan teknis “Strategi Pengembangan Ide Usaha dan Inovasi Produk” adalah untuk memberikan pendampingan terhadap pelaku IKM dalam mengembangkan ide usahanya dan menganalisis rencana bisnis dalam perencanaan produksi.', '[\"public\\/foto-aktivitas\\/66f12294dcd39.jpg\"]', '2024-09-23 15:11:00', '2024-09-23 15:11:00');
INSERT INTO `aktifitas` VALUES (1906, 189, 'In House Training \"Penguatan Branding dan Strategi Pemasaran Omni Channel\"', '2024-07-30', 'Tujuan penyelenggaraan kegiatan in house training “Penguatan Branding dan Strategi Pemasaran Omni Channel” tahun 2024, diperuntukkan bagi tenant tahun 2024 sehingga para peserta dapat menganalisa strategi pemasaran dan menyiapkan diri dalam menghadapi pesaing pasar.', '[\"public\\/foto-aktivitas\\/674fda5211fe0.JPG\"]', '2024-09-23 15:18:51', '2024-12-04 11:29:11');
