INSERT INTO `aktifitas` VALUES (1966, 523, 'Rapat Pembentukan Tim Pengelola INBIS Pusaka Collab', '2024-02-06', 'Rapat pembentukan tim pengelola Inbis Pusaka CoLab 2024 yang dihadiri oleh Kepala Dinas Koperasi dan UMK Kota Denpasar, Praktisi Dr. Ketut Sayu Sutrisna Dewi, SE, Ak selaku Dewan Pakar Inbis , beserta jajaran dan staf Dinas Koperasi dan UKM Kota Denpasar.  \r\n\r\nRapat ini memutuskan susunan SK Pengurus (SK Terlampir dalam sistem/ sudah terupload).', '[\"public\\/foto-aktivitas\\/6704b221836e7.png\"]', '2024-10-08 11:16:33', '2024-10-08 11:21:26');
INSERT INTO `aktifitas` VALUES (1967, 523, 'Diskusi Program INBIS Pusaka Collab', '2024-02-16', 'Kegiatan diskusi Kepala Bidang Kewirausahaan bersama dengan Ibu Cok Widyawaty dan I Putu Arya Finkayana,  pertemuan tersebut untuk membahas penyelenggaraan seleksi calon tenant Inbis dan mekanisme penjurian.', '[\"public\\/foto-aktivitas\\/6704b32f14ab3.jpeg\"]', '2024-10-08 11:21:03', '2024-10-08 11:21:03');
INSERT INTO `aktifitas` VALUES (1968, 523, 'Diskusi Penangan Media sosial Inbis Denpasar Pusaka Collabs', '2024-04-04', 'Kepala Bidang Kewirausahaan bersama dengan Ibu Cok Widyawaty dan staff saudari Apni berdiskui tentang pengelolaan media sosial INBIS Denpasar Pusaka Collabs', '[\"public\\/foto-aktivitas\\/6704b42a3b9c9.jpeg\"]', '2024-10-08 11:25:14', '2024-10-08 11:25:14');
INSERT INTO `aktifitas` VALUES (1969, 523, 'Sosialiasi Inkubator Camp dari Kementrian Koperasi da UKM RI', '2024-03-19', 'Kepala Dinas Koperasi da UKM Kota Denpasar, Kepala Bidang Kewirausahaan dan tim pengelola inkubator bisnis denpasar pusaka collab mendengarkan arahan sosialisasi bersama untuk kegiatan Inkubator Camp yang akan di lakukan pada bulan Mei 2024.', '[\"public\\/foto-aktivitas\\/6704b55111c90.jpeg\"]', '2024-10-08 11:30:09', '2024-10-08 11:30:09');
INSERT INTO `aktifitas` VALUES (1970, 523, 'Rapat Pemantapan Seleksi Tenant Inbis Denpasar Pusaka Collab', '2024-04-07', 'Kepala Dinas Koperasi da UKM Kota Denpasar beserta Ketua Inbis dan tim pengelola mengadakan pertemuan pemantapan proses seleksi, mekanisme penjurian, media promosi dan publikasi.', '[\"public\\/foto-aktivitas\\/6704b7c01afae.jpeg\"]', '2024-10-08 11:40:32', '2024-10-08 11:40:32');
INSERT INTO `aktifitas` VALUES (1971, 523, 'Rapat II Pemantapan Seleksi Tenant Inbis Denpasar Pusaka Collab', '2024-05-20', 'Rapat ke-2 Persiapan seleksi membahas tanggal dan publikasi pendaftaran seleksi calon tenant Inbis Denpasar Pusaka Collab', '[\"public\\/foto-aktivitas\\/6704bb49bc500.jpeg\"]', '2024-10-08 11:55:37', '2024-10-08 11:55:37');
INSERT INTO `aktifitas` VALUES (1972, 523, 'Studi Komparatif Tim Inkubator Bisnis Denpasar Pusaka Collab dengan BDI  Denpasar', '2024-05-28', 'Tim Inkubator Bisnis Denpasar Pusaka Collab melakukan kunjungan ke BDI Denpasar untuk saling bertukar informasi, wawasan dan studi terkait pengembangan bisnis tenant di Kota Denpasar. Kegiatan ini melibatkan jajaran Tim Inbis Denpasar Pusaka Collab dengan pengurus BDI, selain diskusi tim Inbis juga berkesempatan untuk berkunjung dan melihat langsung ruang tenant yang ada di BLI Denpasar.', '[\"public\\/foto-aktivitas\\/6704beb12139f.jpeg\"]', '2024-10-08 12:10:09', '2024-10-08 12:10:09');
INSERT INTO `aktifitas` VALUES (1973, 885, 'Inkubasi Bisnis Batch IV', '2024-09-20', 'Pelaksanaan Inkubasi Bisnis RUBIK Batch IV', '[\"public\\/foto-aktivitas\\/6704cc49be51c.png\"]', '2024-10-08 13:08:09', '2024-10-08 15:06:37');
INSERT INTO `aktifitas` VALUES (1974, 989, 'Training, Asistensi, Konsultasi, Pendampingan dan Sertifikasi', '2024-01-03', 'Peningkatan Kapasitas SDM Koperasi dan UKM melalui Pendidikan dan Pelatihan, Asistensi, Pendampingan dan sertifikasi kompetensi', '[\"public\\/foto-aktivitas\\/67088b2a9c95f.jpeg\",\"public\\/foto-aktivitas\\/67088b2a9cc52.jpeg\",\"public\\/foto-aktivitas\\/67088b2a9d0d7.jpeg\",\"public\\/foto-aktivitas\\/67088b2a9d26c.jpeg\",\"public\\/foto-aktivitas\\/67088b2a9d86b.jpeg\"]', '2024-10-11 09:19:22', '2024-10-11 09:19:22');
INSERT INTO `aktifitas` VALUES (1975, 989, 'Sertifikasi Kompetensi SDM Koperasi dan UKM', '2024-08-31', 'Sertifikasi Pengelola Koperasi, UKM dan Trainer', '[\"public\\/foto-aktivitas\\/67088ba34ee6f.jpeg\",\"public\\/foto-aktivitas\\/67088ba34f551.jpeg\",\"public\\/foto-aktivitas\\/67088ba34fb62.jpeg\",\"public\\/foto-aktivitas\\/67088ba34fc3d.jpeg\",\"public\\/foto-aktivitas\\/67088ba352a13.jpeg\"]', '2024-10-11 09:21:23', '2024-10-11 10:01:42');
INSERT INTO `aktifitas` VALUES (1976, 363, 'Perayaan Puncak Hari UMKM Nasional di Provinsi Sumatera Selatan', '2024-09-05', 'Acara Puncak Hari Nasional UMKM 2024 telah resmi dibuka oleh Menteri Koperasi & UKM RI, Bapak Teten Masduki. Dalam acara ini, Kepala Dinas Koperasi dan UKM Provinsi Sumatera Selatan, Ir. H. Amiruddin, M.Si, menyampaikan laporan pelaksana, sementara Pj. Gubernur Sumatera Selatan, Bapak Elen Setiadi, turut memberikan sambutan.\r\n\r\nAcara ini dihadiri oleh berbagai pejabat dari Kementerian Koperasi dan UKM RI, Kepala OPD Pemprov Sumsel, tokoh publik dari berbagai provinsi, serta seluruh Kepala Dinas Koperasi dan UKM di Indonesia.\r\n\r\nDalam kesempatan ini, Presiden Republik Indonesia Joko Widodo melalui Menteri Koperasi dan UKM RI juga menganugerahkan Tanda Kehormatan Satyalencana Wira Karya kepada beberapa pejabat publik Indonesia sebagai bentuk apresiasi atas dedikasi dalam mendukung pengembangan UMKM di tanah air.', '[\"public\\/foto-aktivitas\\/67088fb9bfb45.png\"]', '2024-10-11 09:38:49', '2024-10-11 09:38:49');
INSERT INTO `aktifitas` VALUES (1977, 989, 'Konsultasi dan Pendampingan Kementerian Koperasi Timor Leste', '2022-03-27', 'Pengembangan Modul Pelatihan Koperasi Timor Leste', '[\"public\\/foto-aktivitas\\/670894efb24a2.png\",\"public\\/foto-aktivitas\\/670894efb2c7c.jpeg\",\"public\\/foto-aktivitas\\/670894efb2e6d.jpeg\",\"public\\/foto-aktivitas\\/670894efb2fdd.jpeg\"]', '2024-10-11 10:01:03', '2024-10-11 10:01:03');
INSERT INTO `aktifitas` VALUES (1978, 790, 'Pendampingan Tenant dalam pembuatan NIB (Nomor Induk Berusaha) secara online', '2024-10-12', 'Membuat NIB tenant secara online', '[\"public\\/foto-aktivitas\\/6709fa26b4e50.jpeg\"]', '2024-10-12 10:39:19', '2024-10-12 11:25:10');
INSERT INTO `aktifitas` VALUES (1979, 911, 'Rekrutmen Tenant', '2024-09-20', 'Rekrutmen Tenant tahan ke 1', NULL, '2024-10-13 12:29:21', '2024-10-13 12:29:21');
INSERT INTO `aktifitas` VALUES (1980, 86, 'Pembukaan Galeri Wirausaha Periode 2024-2025', '2024-10-04', 'Kegiatan Pembukaan Galeri Wirausaha yang diselenggarakan setiap tahun. Kami memberikan kesempatan bagi para wirausaha dilingkungan Universitas untuk mendapatkan bantuan dana bergulir dan kesempatan untuk berjualan di Galeri Wirausaha tanpa dipungut biaya. Program ini hanya berlangsung setiap satu tahun untuk setiap usaha dan akan berganti setiap tahun nya.', '[\"public\\/foto-aktivitas\\/670c7ca2d4023.jpg\"]', '2024-10-14 09:06:26', '2024-10-14 09:06:26');
INSERT INTO `aktifitas` VALUES (1981, 86, 'Visitasi PPK Ormawa oleh Belmawa Dikti', '2024-10-10', 'Kegiatan Visitiasi ini berlangsung selama 3 hari. Universitas Kuningan terpilih menjadi Tuan Rumah (Host) untuk pelaksanaan Visitasi tersebut. Terdiri dari 3 (tiga) Universitas yaitu Universitas Kuningan, Universitas Padjadjaran, Universitas Muhammadiyah Sukabumi. Pelaksanaan diawali dengan pengecekan berkas dari setiap Universitas dan dilanjutkan visitasi ke Desa binaan masing-masing kelompok. Universitas Kuningan terpilih 2 Kelompok dari 7 Kelompok yang lolos PPK Ormawa untuk melanjutkan ke Abdidaya 2024.', '[\"public\\/foto-aktivitas\\/670c7db79dd1d.jpeg\"]', '2024-10-14 09:11:03', '2024-10-14 09:11:03');
INSERT INTO `aktifitas` VALUES (1982, 376, 'Sosialisasi sertifikat Halal Reguler dan Self Declare', '2024-09-23', 'Sosialisasi sertifikat Halal Reguler dan Self Declare oleh Pusat kajian dan Layanan Halal Universitas Islam Negeri Raden Intan Lampung', '[\"public\\/foto-aktivitas\\/670c7f82a86ab.jpeg\",\"public\\/foto-aktivitas\\/670c7f82a8ba1.jpeg\",\"public\\/foto-aktivitas\\/670c7f82a8d73.jpeg\",\"public\\/foto-aktivitas\\/670c7f82a8f63.jpeg\"]', '2024-10-14 09:18:42', '2024-10-14 09:18:42');
INSERT INTO `aktifitas` VALUES (1983, 86, 'Monitoring PPK Ormawa', '2024-09-13', 'Tim Universitas Kuningan bersama Tim IBK Uniku melaksanakan Monitoring kegiatan PPK Ormawa 2024 ke beberapa Desa.', '[\"public\\/foto-aktivitas\\/670c8d09470a0.jpeg\"]', '2024-10-14 10:16:25', '2024-10-14 10:16:25');
INSERT INTO `aktifitas` VALUES (1984, 911, 'Rekrutmen Tenant', '2024-09-20', 'Rekrutmen Tenant tahan ke 1', '[\"public\\/foto-aktivitas\\/670cb8032b8ef.jpg\",\"public\\/foto-aktivitas\\/670cb8032c416.jpg\",\"public\\/foto-aktivitas\\/670cb8032c889.jpg\"]', '2024-10-14 13:19:47', '2024-10-14 13:19:47');
INSERT INTO `aktifitas` VALUES (1985, 154, 'Kunjungan Tim PIB Ke Tempat Usaha Sukma Project - Maulida, Mahasiswi Program Studi Psikologi UNIBI', '2024-07-20', 'Kunjungan Tim PIB UNIBI kepada tenant inwall binaan PIB UNIBI untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/670cc0ff933e1.jpeg\"]', '2024-10-14 13:58:07', '2024-10-14 13:58:07');
INSERT INTO `aktifitas` VALUES (1986, 154, 'Kunjungan Tempat Usaha Berka Java - Fellysca Novaramansyah Mahasiswi UNIBI Program Studi Manajemen 2023', '2024-09-18', 'Kunjungan Tim PIB UNIBI kepada tenant inwall Berka Java milik Fellysca Novaramansyah mahasiswi UNIBI Program Studi Manajemen 2023 yang merupakan binaan PIB UNIBI yang bergerak di bidang F&B yakni Chilli Oil, kunjungan ini dimaksudkan untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/670cc1a1f379a.jpeg\"]', '2024-10-14 14:00:49', '2024-10-14 14:00:49');
INSERT INTO `aktifitas` VALUES (1987, 154, 'Open House, Konsultasi Bisnis Dengan Rully Mahasiswa Program Studi Manajemen 2022', '2024-09-26', 'Open House, merupakan kegiatan konsultasi bisnis gratis yang diselenggarakan oleh PIB UNIBI untuk seluruh mahasiswa/i UNIBI yang sudah memiliki bisnis maupun yang baru memiliki ketertarikan bisnis. Rully memiliki usaha yang bergerak pada bidang F&B.', '[\"public\\/foto-aktivitas\\/670cc1e7c1375.jpeg\"]', '2024-10-14 14:01:59', '2024-10-14 14:01:59');
INSERT INTO `aktifitas` VALUES (1988, 154, 'Open House, Konsultasi Bisnis Dengan Michael Mahasiswa Program Studi Psikologi 2021', '2024-09-26', 'Open House, merupakan kegiatan konsultasi bisnis gratis yang diselenggarakan oleh PIB UNIBI untuk seluruh mahasiswa/i UNIBI yang sudah memiliki bisnis maupun yang baru memiliki ketertarikan bisnis.', '[\"public\\/foto-aktivitas\\/670cc2398e694.jpeg\"]', '2024-10-14 14:03:21', '2024-10-14 14:03:21');
INSERT INTO `aktifitas` VALUES (1989, 154, 'Open House, Konsultasi Bisnis Dengan Indri Mahasiswi Program Studi Manajemen 2022', '2024-09-27', 'Open House, merupakan kegiatan konsultasi bisnis gratis yang diselenggarakan oleh PIB UNIBI untuk seluruh mahasiswa/i UNIBI yang sudah memiliki bisnis maupun yang baru memiliki ketertarikan bisnis. Indri memiliki usaha yang bergerak pada bidang Baju Anak.', '[\"public\\/foto-aktivitas\\/670cc2aef1511.jpg\"]', '2024-10-14 14:05:18', '2024-10-14 14:05:18');
INSERT INTO `aktifitas` VALUES (1990, 154, 'Penyampaian Materi Entrepreneurship Oleh Bapak Ir. Johnson Sinaga, M.M. Pada PKKMB UNIBI 2024', '2024-09-23', 'Sebagai Wakil Rektor Bidang Komunikasi Publik dan Entrepreneurship, Bapak Ir. Johnson Sinaga, M.M. memberikan materi \'Entrepreneurship\' pada PKKMB UNIBI 2024 untuk menumbuhkan jiwa-jiwa dan semangat menjadi Pengusaha Muda.', '[\"public\\/foto-aktivitas\\/670cc2f828c41.jpg\"]', '2024-10-14 14:06:32', '2024-10-14 14:06:32');
INSERT INTO `aktifitas` VALUES (1991, 154, 'Pengenalan Bagian PIB UNIBI Oleh Bapak Antonius Bimo Rentor Luntungan, S.E., M.Ak. Sebagai Kepala Bagian PIB UNIBI Di Acara PKKMB UNIBI 2024', '2024-09-24', 'Pada Acara PKKMB 2024 dalam rangka menyambut mahasiswa/i baru UNIBI di tahun 2024, PIB UNIBI memperkenalkan apa itu PIB dan program apa saja yang dimiliki oleh PIB. Pada kesempatan tersebut PIB diwakili oleh Bapak Antonius Bimo Rentor Luntungan, S.E., M.Ak. selaku Kepala Bagian PIB UNIBI memaparkan beberapa informasi termasuk diantaranya mengenai program Open House, dimana program ini merupakan fasilitas konsultasi bisnis secara gratis yang disediakan untuk seluruh mahasiswa/i UNIBI untuk mereka yang ingin berkonsultasi mengenai bisnis yang mereka miliki ataupun untuk mereka yang baru saja ingin memulai bisnis.', '[\"public\\/foto-aktivitas\\/670cc31fb5f96.jpg\"]', '2024-10-14 14:07:11', '2024-10-14 14:07:11');
INSERT INTO `aktifitas` VALUES (1992, 154, 'Kunjungan Tim PIB Dan WR KPE Ke Tenant Binaan Sukma Project', '2024-10-03', 'Kunjungan Tim PIB UNIBI bersama Wakil Rektor Bidang Komunikasi Publik dan Entrepreneurship Bapak Ir. Johnson Sinaga, M.M. kepada tenant inwall Sukma Project milik Maulidia Sukmayanti Alumni UNIBI Program Studi Psikologi 2018 yang merupakan binaan PIB UNIBI yang bergerak di bidang Jasa Sanggar Tari, kunjungan ini dimaksudkan untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/670cc41f1aa7f.jpeg\"]', '2024-10-14 14:11:27', '2024-10-14 14:11:50');
INSERT INTO `aktifitas` VALUES (1993, 154, 'Open House, Konsultasi Bisnis Dengan Mei Mahasiswi Program Studi Ilmu Komunikasi 2024', '2024-10-04', 'Open House, merupakan kegiatan konsultasi bisnis gratis yang diselenggarakan oleh PIB UNIBI untuk seluruh mahasiswa/i UNIBI yang sudah memiliki bisnis maupun yang baru memiliki ketertarikan bisnis.', '[\"public\\/foto-aktivitas\\/670cc4931bd67.jpg\"]', '2024-10-14 14:13:23', '2024-10-14 14:13:23');
INSERT INTO `aktifitas` VALUES (1994, 146, 'Penentuan telaah dan Perbaikan Proposal Tenant Salelang dan UNAIC Health Care', '2023-04-07', 'UPT memproses proposal yang lolos seleksi-penentuan telaah-penelaah-perbaikan- kembali ke UPT : 20 hari kerja. Tenant : Salelang dan UNAIC Health Care', NULL, '2024-10-14 14:14:50', '2024-10-14 14:22:02');
