INSERT INTO `aktifitas` VALUES (1996, 146, 'Pasca Inkubasi dan Diseminasi Produk Salelang dan UNAIC Health Care', '2024-04-05', 'Tenant mengikuti pasca inkubasi 90 hari pasca tahap inkubasi dan Desiminasi produk dalam 10 hari kerja pasca inkubasi', '[\"public\\/foto-aktivitas\\/670cc6655c281.jpeg\",\"public\\/foto-aktivitas\\/670cc6655c681.jpeg\",\"public\\/foto-aktivitas\\/670cc6655c89b.jpeg\"]', '2024-10-14 14:21:09', '2024-10-14 14:22:13');
