INSERT INTO `aktifitas` VALUES (1999, 146, 'Pelaksanaan program inkubasi 3 tenant', '2024-09-17', 'Pelaksanaan program materi dan praktik untuk 3 tenant, dengan pembicara dosen-dosen dari Fakultas Ekonomi dan Bisnis.', '[\"public\\/foto-aktivitas\\/670cc8769cab4.jpeg\",\"public\\/foto-aktivitas\\/670cc8769cda1.jpeg\",\"public\\/foto-aktivitas\\/670cc8769cea7.jpeg\",\"public\\/foto-aktivitas\\/670cc8769cfe6.jpeg\"]', '2024-10-14 14:29:58', '2024-10-14 14:29:58');
INSERT INTO `aktifitas` VALUES (2000, 523, 'Penjurian Tenat INBIS', '2024-06-01', 'Kegiatan Penjurian di laksanakan di Dinas Koperasi dan UKM Kota Denpasar dengan menghadirkan dewan 3 Dewan juri yaitu: Ibu Sutrisna Dewi selaku Dosen dan akademisi Universitas Udayana,  Bapak Agus Swastawa selaku Manager Inbis Pusaka Denpasar CoLab dan Dewa Adis selaku Praktisi Bisnis. Dari 29 Tenant yang lolos tahap pertama disaring menjadi 19 Tenant final yang memenuhi kriteria penilaian dari Tim Juri dan Internal Inbis.', '[\"public\\/foto-aktivitas\\/670cd15117476.jpg\"]', '2024-10-14 15:07:45', '2024-10-14 15:07:45');
INSERT INTO `aktifitas` VALUES (2001, 523, 'Penjurian Tahap 1 ( Penjurian Administrasi dan Proposal Bisnis)', '2024-05-24', 'Penjuria tahap satu dilaksanakan secara internal untuk menjaring calon tenant berdasarkan kriteria administrasi yang telah ditentukan pada pedoman kegiatan. Hasil dari penjurian ini, dari 40 yang mendaftar 29 diantaranya lolos kurasi.', '[\"public\\/foto-aktivitas\\/670e029c1b63b.png\"]', '2024-10-15 12:50:20', '2024-10-15 12:50:20');
