INSERT INTO `aktifitas` VALUES (2029, 554, 'Coaching Clinic 3', '2024-09-25', 'Coaching clinic untuk perluasan pasar, branding dan marketing\r\ndi Gedung eks. DPRD Kabupaten Tangerang, didampingi oleh tim PI2B ITI.', '[\"public\\/foto-aktivitas\\/671cc3bdf2ba7.jpg\"]', '2024-10-26 17:26:05', '2024-10-26 17:26:05');
INSERT INTO `aktifitas` VALUES (2030, 476, 'SELEKSI DAN REKRUTMEN TENANT DI UNIVERSITAS ABULYATAMA', '2023-12-16', 'Seleksi tenant melalui presentasi ide bisnis bekerjasama dengan Universitas Abulyatama Aceh Besar, adapun sasaran peserta inkubasi dalam kegiatan ini adalah mahasiswa aktif dan alumni Universitas Abulyatama.', '[\"public\\/foto-aktivitas\\/671fb7d80c2e3.jpg\"]', '2024-10-28 23:12:08', '2024-10-28 23:12:08');
