INSERT INTO `aktifitas` VALUES (2035, 954, 'PELATIHAN MENJAHIT', '2024-06-11', 'Pelatihan menjagit di alhadad sudah terlaksana dimana ada 16 peserta yang lolos dalam tahap pelatihan ini, pelatihan ini bukan hanya softskill yang diberikan tetapi pemerataan sdm unggul supaya para peserta bisa bersaing di dunia kerja yang lebih luas', '[\"public\\/foto-aktivitas\\/6720ab086ffc8.jfif\"]', '2024-10-29 16:29:44', '2024-10-29 16:29:44');
