INSERT INTO `aktifitas` VALUES (2095, 363, 'Kunjungan Ke Kopi Sriwijaya', '2024-11-26', 'Kepala Dinas Koperasi & UKM Provinsi Sumatera Selatan, Ir. H. Amiruddin, M.Si., didampingi oleh Direktur Inkubator SIBICE, dan Kepala Bidang Pemberdayaan Usaha Kecil,  melakukan kunjungan bersama tim MCA Indonesia ke Kopi Sriwijaya. Kunjungan ini merupakan bagian dari Program Pengembangan UMKM Compact 2, yang bertujuan untuk mendukung pengembangan usaha kecil dan menengah di wilayah Sumatera Selatan.', '[\"public\\/foto-aktivitas\\/675b7d6ce6672.png\"]', '2024-12-13 07:18:52', '2024-12-13 07:18:52');
INSERT INTO `aktifitas` VALUES (2096, 363, 'Audiensi ke Fakultas Ekonomi dan Bisnis Universitas PGRI Palembang terkait pelaksanaan UMKM GOES TO CAMPUS.', '2024-12-04', 'Direktur Inkubator Sriwijaya Bisnis Center bersama Tim Dinas Koperasi dan UKM Sumsel melaksanakan audiensi ke Fakultas Ekonomi dan Bisnis Universitas PGRI Palembang terkait pelaksanaan UMKM GOES TO CAMPUS.', '[\"public\\/foto-aktivitas\\/675b7eca6ec95.png\"]', '2024-12-13 07:24:42', '2024-12-13 07:24:42');
INSERT INTO `aktifitas` VALUES (2097, 363, 'Rapat Lanjutan dalam persiapan UMKM Goes To Campus bersama mitra', '2024-12-11', 'Kepala Bidang Pemberdayaan Usaha Kecil memimpin rapat persiapan pelaksanaan program Entrepreneur Goes to Campus dan UMKM Goes to School. Program ini bertujuan untuk mendorong semangat kewirausahaan di kalangan mahasiswa dan pelajar, sekaligus memperkuat kolaborasi antara dunia pendidikan dan pelaku usaha.\r\n\r\nRapat ini dihadiri oleh berbagai pihak terkait, antara lain perwakilan Fakultas Ekonomi dan Bisnis Universitas PGRI Palembang, Direktur Inkubator Bisnis Sibicek, tim ahli Rumah Cindo, perwakilan Pegadaian, Grab Palembang, dan PT. Tunas Jaya Lautan Dipo Palembang.', '[\"public\\/foto-aktivitas\\/675b7fc854afe.png\"]', '2024-12-13 07:28:56', '2024-12-13 07:28:56');
INSERT INTO `aktifitas` VALUES (2098, 622, 'Proses Pembuatan Roti', '2024-11-14', 'Pembuatan Roti oleh Tenant', '[\"public\\/foto-aktivitas\\/675d1bd26a814.jpg\"]', '2024-12-14 12:45:42', '2024-12-14 12:46:58');
INSERT INTO `aktifitas` VALUES (2099, 51, 'Pendampingan pembuatan Akta Koperasi Kelompok Subsisten BI KPW Jakarta', '2024-12-12', 'Pendirian Koperasi merupakan salah satu dari target pendampingan pada program pengembangan ekonomi kelompok subsisten 2024. Kegiatan ini adalah program dari Kpw BI DKJ Jakarta.', '[\"public\\/foto-aktivitas\\/675d4cf781d5f.jpg\",\"public\\/foto-aktivitas\\/675d4cf782195.jpg\",\"public\\/foto-aktivitas\\/675d4cf78252e.jpg\",\"public\\/foto-aktivitas\\/675d4cf782793.jpg\"]', '2024-12-14 16:16:39', '2024-12-14 16:16:39');
INSERT INTO `aktifitas` VALUES (2100, 90, 'Bazaar CareerBizXpo 2024', '2024-11-14', 'Pada tanggal 14-15 November 2024, Tajeer Inkubator Bisnis mengadakan kegiatan Bazaar dalam rangkaian acara CareerBizXpo, kegiatan bazaar ini dieselnggarakan dalam dua hari dan di ikuti oleh tenant yang berasal dari tenant binaan tajeer langsung, mahasiswa dan alumni UAI, serta masyarakat umum. Pada kegiatan bazaar ini dikolaborasikan dengan Jakpreneur (Sudin PPKUKM Jakarta Selatan).', '[\"public\\/foto-aktivitas\\/67627e08a3a9f.jpg\"]', '2024-12-18 14:47:20', '2024-12-18 14:47:20');
INSERT INTO `aktifitas` VALUES (2101, 90, 'Bazaar CareerBizXpo 2024', '2024-11-15', 'Pada tanggal 14-15 November 2024, Tajeer Inkubator Bisnis mengadakan kegiatan Bazaar dalam rangkaian acara CareerBizXpo, kegiatan bazaar ini dieselnggarakan dalam dua hari dan di ikuti oleh tenant yang berasal dari tenant binaan tajeer langsung, mahasiswa dan alumni UAI, serta masyarakat umum. Pada kegiatan bazaar ini dikolaborasikan dengan Jakpreneur (Sudin PPKUKM Jakarta Selatan).', '[\"public\\/foto-aktivitas\\/67627e455f018.jpg\"]', '2024-12-18 14:48:21', '2024-12-18 14:48:21');
INSERT INTO `aktifitas` VALUES (2102, 742, 'seleksi tenant', '2024-12-18', 'Kami mengundang pelaku usaha kuliner yang ingin menjadi bagian dari keluarga RZ untuk menjual kerupuk melinjo yang lezat dan unik. Kami mencari tenant yang memiliki semangat yang sama dalam menghadirkan produk berkualitas dan pengalaman kuliner yang tak terlupakan.', '[\"public\\/foto-aktivitas\\/6762949a9e23c.jpeg\"]', '2024-12-18 16:23:38', '2024-12-18 16:23:38');
