INSERT INTO `aktifitas` VALUES (2111, 154, 'Seminar Business Fest Vol.2', '2024-12-16', 'PIB UNIBI menggelar Seminar Bisnis pada acara Business Fest Vol.2 yang bertajuk FORWARD \"Focus on Exploring New Businesses and Development for Futurepreneurs\" yang diadakan di Harris Hotel & Conventions Ciumbuleuit Bandung, seminar ini merupakan rangkaian dari Business Fest Vol.2 yang akan dilanjutkan dengan Bazaar Bisnis di Kampus UNIBI pada tahun 2025 mendatang. Seminar ini diisi oleh pembicara-pembicara yang luar biasa dan peserta dari berbagai elemen mulai dari Inkubator di Kota Bandung hingga berbagai Sekolah Menengah di Kota Bandung', '[\"public\\/foto-aktivitas\\/6763d4c1d0b24.jpg\"]', '2024-12-19 15:09:37', '2024-12-19 15:09:37');
