INSERT INTO `aktifitas` VALUES (2243, 973, 'Pendampingan Mahasiswa ke perkebunan kopi Arabika', '2024-12-18', 'Pendampingan mahasiswa ke kebun kopi Arabika yang berada di desa sajang kec. sembalun kab. lombok timur merupakan bagian dari pembelajaran mahasiswa dalam menemukan ide bisnis potensial dibidang agribisnis secara umum.', '[\"public\\/foto-aktivitas\\/678891e11e3f6.jpeg\"]', '2025-01-16 11:58:09', '2025-01-16 11:58:09');
