INSERT INTO `aktifitas` VALUES (2286, 1174, 'Sosialisasi Pembiayaan UMKM dan Pendampingan Pengisian SPT untuk Pelaku Usaha dilingkungan UNIROW dan di Kab. Tuban', '2025-02-19', 'Kegiatan ini bertujuan untuk membantu pelaku usaha yang ada dilingkungan kampus dan pelaku usaha di Kab. Tuban dalam pendampingan pengisian SPT dan sosialisasi pembiayaan untuk usaha', '[\"public\\/foto-aktivitas\\/67abe93a2e1b5.jpeg\"]', '2025-02-12 07:20:10', '2025-02-12 07:20:10');
