INSERT INTO `aktifitas` VALUES (2297, 1234, 'INKUBATOR BISNIS UMKM NAIK KELAS 2024', '2024-04-01', '🎉[JOIN INKUBATOR BISNIS UMKM NAIK KELAS 2024]🤩\r\n\r\n📊Telah dibuka pendaftaran Inkubator Bisnis UMKM Naik Kelas 2024📈\r\n\r\nAyo! ikuti program Inkubator UMKM Naik Kelas 2024 Dinas Koperasi dan UMKM DIY\r\n\r\nPelaksanaan:\r\nApril - Agustus 2024\r\n\r\nLink pendaftaran:\r\nhttps://s.id/inbis2024\r\n\r\natau di BIO @plutjogja @ibisma_uii\r\n\r\nPendaftaran ditutup pada:\r\n🗓️ Sabtu, 30 April 2024\r\n⏰ Pukul 23.59 WIB\r\n\r\nYukk segera mendaftar dan dapatkan berbagai\r\nreward dan pembinaan !!!\r\n\r\nInformasi lebih lanjut hubungi:\r\n📲 IBISMA UII\r\n(+62 811-2646-608)\r\n\r\n#diskopukmdiy #plutjogja #ibismauii #inbis2024', '[\"public\\/foto-aktivitas\\/67b5f2a312a9b.jpg\",\"public\\/foto-aktivitas\\/67b5f2a312db7.jpg\"]', '2025-02-19 22:02:59', '2025-02-19 22:02:59');
