INSERT INTO `aktifitas` VALUES (2300, 363, 'Talk Show RRI dengan tema \"Dynamic Strategy UMKM Sumsel melalui Inkubator SiBiCe', '2025-02-05', 'Direktur Inkubator Sibice\' bersama Kepala Dinas Koperasi dan UKM Sumsel menjadi Narasumber dalam Talk Show RRI Rabu 05 Feb 2025 dengan tema \"Dynamic Strategy UMKM Sumsel melalui Inkubator SiBiCe: Tantangan dan Peluang Digitalisasi 5.0\"', '[\"public\\/foto-aktivitas\\/67b9d9feed3ed.png\"]', '2025-02-22 21:06:54', '2025-02-22 21:06:54');
INSERT INTO `aktifitas` VALUES (2301, 363, 'Kegiatan Diskusi Sibice\' bersama UMKM Exportir Indonesia', '2025-02-21', 'Kegiatan Diskusi Sibice\' bersama UMKM Exportir Indonesia, berlokasi di Jembatan Ampera dan dihadiri oleh direktur Inkubator Sibice dan Kabid UMKM Dinas Koperasi dan UMKM Serta tamu UMKM Exportir Indonesia', '[\"public\\/foto-aktivitas\\/67b9db5b59b03.png\"]', '2025-02-22 21:12:43', '2025-02-22 21:12:43');
