INSERT INTO `aktifitas` VALUES (2311, 523, 'Menerima kunjungan LPK Akubank', '2025-01-17', 'Tim Inkubator bisnis Pusaka Denpasar Collab bersama dengan Bapak Kepala Dinas dan Ibu Kabid Kewirausahaan menerima kunjungan balasan dari manajemen LPK Akubank sebagai tindak lanjut kerjasama serta merekomendasikan mahasiswa yang mulai merintis wirausaha untuk ikut dalam proses seleksi calon tenant 2025 Inbis Pusaka Denpasar Collab', '[\"public\\/foto-aktivitas\\/67c7c5a092d81.jpg\",\"public\\/foto-aktivitas\\/67c7c5a09309e.jpg\"]', '2025-03-05 10:31:44', '2025-03-12 09:55:56');
