INSERT INTO `aktifitas` VALUES (2364, 473, 'Sosialisasi Pendampingan Koperasi Desa Merah Putih', '2025-04-09', 'Sosialisasi pendampingan koperasi Desa Merah Putih dilaksanakan di Kantor Kecamatan Rengel, Kabupaten Tuban oleh Tim Inkubator Cah Angon, Luni Nanda. \r\nKegiatan ini bertujuan untuk memberikan wawasan tentang Koperasi Desa Merah Putih', '[\"public\\/foto-aktivitas\\/67f862d738fd0.jpg\"]', '2025-04-11 07:31:19', '2025-04-11 07:31:19');
INSERT INTO `aktifitas` VALUES (2365, 376, 'Bazar Ramadan 1446 H / 2025', '2025-03-01', 'Bazar yang dilakukan pada bulan Ramadhan dalam rangka meningkatakan Pemasaran Produk dan pendapatan UMKM pada tahun 2025', '[\"public\\/foto-aktivitas\\/67f87d4fc8566.jpeg\",\"public\\/foto-aktivitas\\/67f87d4fc8cc8.jpeg\",\"public\\/foto-aktivitas\\/67f87d4fc90a0.jpeg\",\"public\\/foto-aktivitas\\/67f87d4fc944a.jpeg\",\"public\\/foto-aktivitas\\/67f87d4fc98f6.jpeg\"]', '2025-04-11 09:24:15', '2025-04-11 09:24:15');
