INSERT INTO `aktifitas` VALUES (2367, 154, 'Open House Mahasiswa Ilmu Komunikasi 2021', '2025-04-01', 'Open House, merupakan kegiatan konsultasi bisnis gratis yang diselenggarakan oleh PIB UNIBI untuk seluruh mahasiswa/i UNIBI yang sudah memiliki bisnis maupun yang baru memiliki ketertarikan bisnis. Kali ini Sascia berdiskusi dengan Tim PIB untuk membahas mengenai pengembangan bisnis yang akan dimulainya.', '[\"public\\/foto-aktivitas\\/67fe26b867df0.JPG\"]', '2025-04-15 16:28:24', '2025-04-15 16:28:24');
INSERT INTO `aktifitas` VALUES (2368, 154, 'Studi Banding Inkubator Bisnis Politeknik Al-Islam Bandung', '2025-04-15', 'Pusat Inovasi dan Inkubator Bisnis berkesempatan untuk menjadi tuan rumah dalam kegiatan studi banding Inkubator Bisnis Politeknik Al-Islam Bandung yang dilaksanakan dengan tujuan untuk berdiskusi dan bertukar informasi terkait proses pembentukan legalitas lembaga inkubator serta pengembangannya dalam hal program kerja serta teknis sumber daya manusianya. PIB UNIBI berharap studi banding yang telah dilakukan dapat menjadi langkah awal kolaborasi yang baik antara kedua institusi.', '[\"public\\/foto-aktivitas\\/67fe27d58c0ae.JPG\"]', '2025-04-15 16:33:09', '2025-04-15 16:33:09');
INSERT INTO `aktifitas` VALUES (2369, 85, 'Startup Klinik on RBTV', '2025-04-16', 'Penguatan ekosistem startup di wilayah Yogyakarta melalui media RBTV Jogja, SC#235', '[\"public\\/foto-aktivitas\\/67ff0ba612438.jpg\"]', '2025-04-16 08:45:10', '2025-04-16 08:45:25');
INSERT INTO `aktifitas` VALUES (2370, 85, 'Kick Off Program Inkubasi Koperasi LPDB 2025', '2025-04-17', 'Pembukaan Program Inkubasi Koperasi Periode Maret - Oktober 2025, kerjasama dengan LPDB', '[\"public\\/foto-aktivitas\\/6805ac22689b5.jpg\"]', '2025-04-21 09:23:30', '2025-04-21 09:23:30');
INSERT INTO `aktifitas` VALUES (2371, 473, 'Kick Off Inkubasi Koperasi Terpilih, Menjadi Koperasi yang Kuat dan Mandiri', '2025-04-15', 'siap menjemput masa depan koperasi yang lebih kuat dan mandiri? ✨\r\nYuk, hadir di acara Kickoff Inkubasi Koperasi Terpilih bersama Inkubator Cah Angon!\r\n\r\nKami juga mengadakan Diskusi Bersama Para Ahli dengan tema:\r\n“Menjadi Koperasi yang Kuat dan Mandiri”\r\n\r\nBersama narasumber inspiratif:\r\n\r\n1. Bapak Pendi Yusup (Supervisor Inkubator LPDB-KUMKM)\r\nStrategi Menyusun Tata Kelola Koperasi bersama Inkubator Bisnis\r\n\r\n2. Bapak Galih Wiranegara (Direktur Utama KPMP Ngawi Tani Mandiri)\r\nStrategi Membangun Bisnis Koperasi yang Abadi dan Berkelanjutan\r\n\r\nDipandu oleh moderator:\r\nLuni Nanda Rohmawatii\r\n\r\n*Catat Tanggalnya!*\r\n📅 Selasa, 15 April 2025\r\n🕣 08.30 WIB - Selesai\r\n\r\nBersama kita wujudkan koperasi yang inovatif, berkelanjutan, dan berdaya saing tinggi!\r\nStay tuned dan jangan lewatkan momen bersejarah ini.\r\ndihadiri oleh 10 koperasi terpilih dan 4 koperasi undangan dan Dinas Koperasi dan UKM Provinsi Jawa Timur sebagai sambutan dan pembuka agenda.', '[\"public\\/foto-aktivitas\\/6805b50bd5943.jpeg\"]', '2025-04-21 10:01:31', '2025-04-21 10:01:31');
