INSERT INTO `aktifitas` VALUES (2420, 523, 'Sosialiasi AKUBANK Motivasi Kewirausahaan', '2025-01-31', 'Ibu Kepala Bidang Kewirausahaan bersama pengelola Inkubator Bisnis beserta salah satu UMKM Alumni tenant 2024, diundang oleh AKUBANK menindaklanjuti audensi sebelumnya dalam Kuliah Umum pada mahasiswa dengan memberikan motivasi  dan sharing session kewirausahaan kepada mahasiswa AKUBANK.', '[\"public\\/foto-aktivitas\\/682746b999542.jpg\"]', '2025-05-16 21:07:53', '2025-05-16 21:07:53');
INSERT INTO `aktifitas` VALUES (2421, 523, 'PROSES SELEKSI TENANT 2025', '2025-02-19', 'Proses seleksi Tahap II dilakukan dengan memilih 25 tenant untuk ikut presentasi dan penjurian. Dari 25 tenant tersebut terpilih 20 tenant yang lolos untuk proses inkubasi selanjutnya', NULL, '2025-05-16 21:20:32', '2025-05-16 21:20:32');
