INSERT INTO `aktifitas` VALUES (2427, 523, 'Menerima Kunjungan Ketua ABDSI Jawa Timur', '2025-03-30', 'Koordinator Program saat bertugas pada hari Kemis, 30 Maret 2025 menerima kunjungan Ketua ABDSI Jawa Timur yang kebetulan sedang ada kegiatan kunjungan ke BI Bali, diperkenalkan tentang lembaga Inkubator Bisnis Pusaka Colab Kota Denpasar dan mendukung penuh kegiatan ini agar berjalan sukses ke depannya. ABDSI merupakan asosiasi BDS Indonesia yang sudah lebih dari 20 tahun merupakan perkumpulan lembaga dan konsultan pengembangan bisnis Koperasi dan UMKM.', '[\"public\\/foto-aktivitas\\/68274d5d95701.jpg\"]', '2025-05-16 21:36:13', '2025-05-16 21:36:13');
INSERT INTO `aktifitas` VALUES (2428, 523, 'WORKSHOP 1 FUNDAMENTAL BISNIS', '2025-04-11', 'Workshop pertama bagi UMKM Tenant 2025 diadakan pada tanggal 11 April 2025 mengambil tema Fundamental bisnis dengan kegiatan menghadirkan narasumber tentang bagaimana mengurus Haki terkhusus HAK MEREK dan materi Business Model Canvas', '[\"public\\/foto-aktivitas\\/682751be9fce6.jpg\"]', '2025-05-16 21:54:54', '2025-05-16 21:54:54');
INSERT INTO `aktifitas` VALUES (2429, 523, 'Kegiatan sosialisasi INBIS bersama dengan  WMD Goes To Campus (Elizabet International School)', '2025-04-17', 'Manager Inkubator Bisnis Pusaka Denpasar Colab turut serta untuk bersosialiasi tentang inbis di Kampus Elizabeth International bersama dengan sosialiasi Wira Usaha Muda Denpasar', NULL, '2025-05-16 21:56:58', '2025-05-16 21:56:58');
