INSERT INTO `aktifitas` VALUES (2431, 523, 'Sosialiasi di PRO 1 RRI Denpasar', '2025-04-30', 'Manager Inkubator Bisnis Pusaka Denpasar Colab mendapat undangan untuk sharing session sekaligus sosialiasi tentang Inkubator bisnis Pusaka Denpasar Colab di Radio Pro 1 RRI Denpasar', '[\"public\\/foto-aktivitas\\/68275496e0cc8.jpg\"]', '2025-05-16 22:07:02', '2025-05-16 22:07:02');
