INSERT INTO `aktifitas` VALUES (2537, 90, 'Dreampreneur Action Day', '2025-07-03', 'Dreampreneur action day merupakan sebuah program kegiatan yang dirancang oleh salah satu himpunan mahasiswa dari program studi bahasa arab yang dikolaborasikan dengan Tajeer Inkubator Bisnis. kegiatan ini terdiri dari dua rangkain acara dalam waktu yang bersamaan, yang mana kegiatannya di isi dengan acara bazaar  dan talkshow dengan mengangkat dua tema yang berbeda, yang satu mengangkat tema tentang entrepreneur, dengan mendatangkan narasumber yang juga merupakan alumni dari Universitas Al - Azhar Indonesia, dan alumni ini juga merupakan publik figur yang juga selaku pelaku usaha, dan satu lagi mengangkat tema dari bidang karir profesional (kantoran). Kegiatan ini berlangsung selama dua hari dari tanggak 3 hingga 4 juli 2025.', '[\"public\\/foto-aktivitas\\/686c8c41c1beb.jpeg\"]', '2025-07-08 10:10:57', '2025-07-08 10:10:57');
