INSERT INTO `aktifitas` VALUES (2541, 154, 'Workshop dan Sosialisasi Inkubasi Bisnis PIB 2025', '2025-05-07', 'PIB UNIBI telah menyelenggarakan Workshop berkolaborasi dengan Fellysca Novaramansyah selaku pemilik Berka Java tenant binaan PIB UNIBI Tahun 2024. Selain itu dilakukan sosialisasi program inkubasi bisnis tahun 2025 kepada mahasiswa/i UNIBI.', '[\"public\\/foto-aktivitas\\/687603d0a67bd.jpg\"]', '2025-07-15 14:31:28', '2025-07-15 14:31:47');
INSERT INTO `aktifitas` VALUES (2542, 154, 'Screening Calon Tenant PIB UNIBI 2025', '2025-05-28', 'Tim PIB UNIBI telah melaksanakan seleksi screening calon tenant secara daring melalui zoom meeting. Tahapan ini merupakan tahapan awal sebagai konfirmasi business plan yang telah dikirimkan sebelumnya', '[\"public\\/foto-aktivitas\\/687604589b844.png\"]', '2025-07-15 14:33:44', '2025-07-15 14:33:44');
INSERT INTO `aktifitas` VALUES (2543, 154, 'Interview Akhir Calon Tenant Bersama Wakil Rektor UNIBI', '2025-06-02', 'Terdapat 6 usaha mahasiswa yang lolos tahap screening dan berkesempatan melakukan interview akhir bersama dengan Wakil Rektor Bidang Komunikasi Publik dan Entrepreneurship dan Kepala Bagian PIB UNIBI.', '[\"public\\/foto-aktivitas\\/6876053d8ad8e.png\"]', '2025-07-15 14:37:33', '2025-07-15 14:37:33');
