INSERT INTO `aktifitas` VALUES (2563, 182, 'Bootcamp Wiramuda', '2025-01-23', 'Pelaksanaan Bootcamp Wiramuda, merupakan program yang diikuti oleh mahasiswa/mahasiswi politeknik APP Jakarta yang memiliki minat wirausaha dilaksanakan di Hotel Savero Depok, dihadiri oleh perwakilan dari Asdep kewirausahaan pemuda KEMENPORA R.I\r\nKegiatan ini dilaksanakan dengan bantuan hibah dana dari Asisten Deputi Kewirausahaan Pemuda Kementerian Pemuda, dan Olahraga Republik Indonesia, sebagai reward Politeknik APP Jakarta sebagai 3 besar Kampus layak wiramuda tingkat Nasional Tahun 2024', '[\"public\\/foto-aktivitas\\/688ae4f99677f.jpg\"]', '2025-07-31 10:37:29', '2025-07-31 10:39:22');
INSERT INTO `aktifitas` VALUES (2564, 1134, 'Bimtek Motivasi Bisnis Inkubtor DOPAT', '2025-07-28', 'Bimtek Motivasi Bisnis ini adalah Meningkatkan semangat kewirausahaan dan pola pikir bisnis,  Memberikan pemahaman mendalam tentang pentingnya motivasi dalam membangun dan mengembangkan usaha dan Membekali peserta dengan pengetahuan dan keterampilan dasar dalam dunia bisnis.', '[\"public\\/foto-aktivitas\\/68902cc53b6ef.jpeg\",\"public\\/foto-aktivitas\\/68902cc53bf3a.jpeg\",\"public\\/foto-aktivitas\\/68902cc53c5b7.jpeg\",\"public\\/foto-aktivitas\\/68902cc53cc31.jpeg\",\"public\\/foto-aktivitas\\/68902cc53d077.jpeg\"]', '2025-08-04 10:37:46', '2025-08-04 10:45:09');
