INSERT INTO `aktifitas` VALUES (2583, 448, 'Fashion Incubator 2024', '2024-01-30', 'Merupakan Program Kolaborasi antara Inkubator Bisnis IDB Bali dengan Program Studi Desain Mode IDB Bali yang diadakan pada tanggal 30 Januari - 2 Februari 2024.\r\n\r\nProgram Fashion Incubator ini wajib diikuti oleh mahasiswa-mahasiswi prodi Desain Mode yang akan menempuh Tugas Akhir dengan materi seputar membangun bisnis dan brand bagi para mahasiswa, kegiatan ini juga menghadirkan narasumber dalam sesi talkshow yang diikuti oleh para peserta dari seluruh prodi di IDB Bali.', '[\"public\\/foto-aktivitas\\/689ae6dd7a85d.JPG\"]', '2025-08-12 14:01:49', '2025-08-12 14:01:49');
