INSERT INTO `aktifitas` VALUES (2585, 448, 'Business Development Fundamental Workshop', '2024-06-14', 'Workshop untuk memperkenalkan ilmu dan tips dasar dalam berbisnis dengan menghadirkan 2 narasumber berkompeten.', '[\"public\\/foto-aktivitas\\/689ae8fd85066.JPG\"]', '2025-08-12 14:10:53', '2025-08-12 14:10:53');
INSERT INTO `aktifitas` VALUES (2586, 448, 'Seminar Kewirausahaan “Unlocking the Entrepreneurial Mindset: Turning Ideas into Impact”', '2024-11-02', 'Seminar Kewirausahaan “Unlocking the Entrepreneurial Mindset: Turning Ideas into Impact” persembahan Inkubator Bisnis IDB Bali untuk menambah wawasan terkait bisnis.', '[\"public\\/foto-aktivitas\\/689aebc2920f1.JPG\"]', '2025-08-12 14:22:42', '2025-08-12 14:22:42');
INSERT INTO `aktifitas` VALUES (2587, 448, 'Awarding Wirausaha Berprestasi', '2024-11-17', 'Awarding wirausahawan berprestasi bagi tenant yang telah lolos inkubasi dan melaksanakan wisuda', '[\"public\\/foto-aktivitas\\/689aec540554b.JPG\"]', '2025-08-12 14:25:08', '2025-08-12 14:25:08');
INSERT INTO `aktifitas` VALUES (2588, 448, 'Fashion Incubator 2025', '2025-02-10', 'Fashion Business Incubator dengan tema \"Building an Entrepreneurial Mindset: The Key to Success in Fashion Business\". Acara ini bertujuan untuk memperkuat pengembangan bisnis bagi mahasiswa Desain Mode IDB Bali yang sedang menempuh Tugas Akhir. Di sini, mereka akan menyusun rancangan brand dan business plan yang solid sebagai bekal sukses di industri fashion.', '[\"public\\/foto-aktivitas\\/689b0270c404f.JPG\"]', '2025-08-12 15:59:28', '2025-08-12 15:59:28');
INSERT INTO `aktifitas` VALUES (2589, 448, 'Workshop Scale-Up Bisnis', '2025-02-18', 'Pada Workshop ini para tenant mendalami penerapan Business Model Canvas, mempelajari Financial Planning dalam bisnis dan juga mengembangkan ilmu Branding & Marketing Bisnis dengan informasi dari narasumber berkompeten', '[\"public\\/foto-aktivitas\\/689b033e13e04.JPG\"]', '2025-08-12 16:02:54', '2025-08-12 16:02:54');
INSERT INTO `aktifitas` VALUES (2590, 448, 'IDB Bali Business Challenge', '2025-03-22', 'Lomba bagi mahasiswa internal IDB Bali untuk menunjukkan ide bisnis kreatif dan pemenang memperoleh pendanaan.', '[\"public\\/foto-aktivitas\\/689b03d21aa8e.JPG\"]', '2025-08-12 16:05:22', '2025-08-12 16:05:22');
