INSERT INTO `aktifitas` VALUES (2592, 1349, 'Penyusunan Rencana Strategis Inbis Karangasem Agung', '2025-01-02', 'Pengelola Melaksanakan Rapat Penyusunan Rencana Strategis Inbis Karangasem Agung Tahun Anggaran 2026', '[\"public\\/foto-aktivitas\\/68b54b782f65d.jpg\",\"public\\/foto-aktivitas\\/68b54b7832422.jpg\"]', '2025-09-01 14:30:00', '2025-09-01 14:30:00');
INSERT INTO `aktifitas` VALUES (2593, 1349, 'Pendaftaran akun inbis pada laman SIPENSI', '2025-09-01', 'Sebagai wadah baru untuk mendukung pertumbuhan UMKM, startup, dan wirausaha muda, kami memulai perjalanan ini dengan beberapa langkah penting:\r\n✅ Mendaftarkan akun inbis pada laman SIPENSI Kementerian UMKM Republik Indonesia .\r\n✅ Menyusun program tahap awal.\r\n✅ Menghubungkan jejaring mentor, mitra, dan komunitas bisnis.', '[\"public\\/foto-aktivitas\\/68b81bd5a81d7.jfif\"]', '2025-09-03 17:43:33', '2025-09-03 17:43:33');
