INSERT INTO `aktifitas` VALUES (2639, 352, 'Bussiness matching inkubator bisnis', '2025-07-29', 'Mempertemukan antara pelaku ekspor dengan 25 tenan inkubator bisnis', '[\"public\\/foto-aktivitas\\/68ca4588aca13.jpg\"]', '2025-09-17 12:22:16', '2025-09-17 12:22:16');
INSERT INTO `aktifitas` VALUES (2640, 90, 'Entrepreneur Award UAI 2025', '2025-08-01', 'Entrepreneur award merupakan sebuah program kegiatan yang dirancang oleh Tajeer Inkubator Bisnis berupa pemberian award bagi mahasiswa dan alumni terbaik yang sudah menjalankan usaha, kegiatan ini berawal dengan pembukaan pendaftaran bagi seluruh mahasiswa dan alumni yang merupakan pelaku usaha, setelah pendaftaran, akan diadakan sesi pitching usaha dengan melibatkan dosen - dosen sebagai juri dalam kegiatan tersebut, setelah sesi pitching tersebut, akan dipilih satu yang terbaik dari kategori alumni, dan dua orang yang terbaik dari kategori mahasiswa. Para pemenang tersebut akan menerima penghargaan berupa plakat Entrepreneur Award dan uang tunai sebagai bentuk reward yang akan mereka terima. Dan dalam kesempatan lain, para pemenang award ini  akan dilibatkan dalam kegiatan - kegiatan Tajeer Inkubator, bisa berupa menjadi narasumber. tempat kunjungan usaha, hingga menjadi mentor.', '[\"public\\/foto-aktivitas\\/68cb84a07d336.jpeg\"]', '2025-09-18 11:03:44', '2025-09-18 11:03:44');
INSERT INTO `aktifitas` VALUES (2641, 189, 'Bootcamp I', '2025-07-09', 'Kegiatan bootcamp I dengan tema “Bussiness Upgrade : Perumusan Ide & Pengembangan Usaha, Analisa Pasar, dan Pendampingan”', '[\"public\\/foto-aktivitas\\/68d0ee488e930.jpeg\"]', '2025-09-22 13:35:52', '2025-09-22 13:35:52');
INSERT INTO `aktifitas` VALUES (2642, 189, 'Bootcamp II', '2025-08-13', 'Kegiatan Bootcamp II dengan tema  \"“Legalitas dan Perizinan Usaha\r\nserta Manajemen SDM”', '[\"public\\/foto-aktivitas\\/68d0eec26376b.jpeg\"]', '2025-09-22 13:37:54', '2025-09-22 13:37:54');
INSERT INTO `aktifitas` VALUES (2643, 251, 'Diversifikasi Penguatan Usaha KUKM Manajerial / IT Entrepreneur Inkubasi Bisnis 2025 (Tahap 3)', '2025-09-16', 'Pemerintah Provinsi Jawa Timur melalui Dinas Koperasi & UKM menggelar Diversifikasi Penguatan Usaha KUKM Manajerial / IT Entrepreneur dengan tema “Strategi Pitching dan Inovasi untuk Tata Kelola Startup”. Acara tingkat provinsi ini diikuti oleh 50 peserta UMKM yang datang dari lima daerah: Kabupaten Banyuwangi, Situbondo, Kota Batu, Kota Malang, dan Kota Probolinggo. Rangkaian sesi kemudian menghadirkan para narasumber dari ekosistem inkubasi bisnis, seperti Baroto Tavip (Kepala Inkubator ITS), Edi Mulyadi (Kepala IBT Technopark UPNVJT), Arief Budiono (mentor ITS), dan Alfiandi Imam (mentor UPNVJT). Mereka memaparkan teknik pitching yang menarik, penyusunan value proposition, validasi masalah dan pasar, serta desain inovasi agar startup tumbuh berkelanjutan.', '[\"public\\/foto-aktivitas\\/68d3634f66ae1.jpeg\"]', '2025-09-24 10:19:43', '2025-09-24 10:19:43');
INSERT INTO `aktifitas` VALUES (2644, 251, 'Diversifikasi Penguatan Usaha KUKM Manajerial / IT Entrepreneur Inkubasi Bisnis 2025 (Tahap 4)', '2025-09-17', 'Rangkaian kegiatan oleh Pemerintah Provinsi Jawa Timur melalui Dinas Koperasi & UKM kembali menggelar Diversifikasi Penguatan Usaha KUKM Manajerial /IT Entrepreneur bertajuk \"Penguatan Branding dan Strategi Pasar untuk Pertumbuhan Usaha\". Kegiatan ini menghadirkan Baroto Tavip, seorang Startup Ecosystem Builder, yang memberikan pembekalan komprehensif tentang strategi membawa produk ke pasar secara efektif. Dalam pemaparannya, Baroto menegaskan pentingnya validasi masalah dan kebutuhan pasar sebelum meluncurkan produk. “Startup sering kali gagal bukan karena produk jelek, tetapi karena tidak menyelesaikan masalah nyata yang dirasakan konsumen,” ujarnya.', '[\"public\\/foto-aktivitas\\/68d363f248f30.jpeg\"]', '2025-09-24 10:22:26', '2025-09-24 10:22:26');
INSERT INTO `aktifitas` VALUES (2645, 85, 'Startup Klinik on RBTV', '2025-09-24', 'Penguatan ekosistem startup di wilayah Yogyakarta melalui media RBTV Jogja, SC#255', '[\"public\\/foto-aktivitas\\/68d394fc1fcc9.jpg\"]', '2025-09-24 13:51:40', '2025-09-24 13:51:40');
INSERT INTO `aktifitas` VALUES (2646, 85, 'Startup Klinik on RBTV', '2025-09-10', 'Penguatan ekosistem startup di wilayah Yogyakarta melalui media RBTV Jogja, SC#253', '[\"public\\/foto-aktivitas\\/68d3951c063e2.jpg\"]', '2025-09-24 13:52:12', '2025-09-24 13:52:12');
INSERT INTO `aktifitas` VALUES (2647, 85, 'Startup Klinik on RBTV', '2025-09-17', 'Penguatan ekosistem startup di wilayah Yogyakarta melalui media RBTV Jogja, SC#254', '[\"public\\/foto-aktivitas\\/68d39539f2b5d.jpg\"]', '2025-09-24 13:52:41', '2025-09-24 13:52:41');
INSERT INTO `aktifitas` VALUES (2648, 1134, 'MONITORING TENAN INKUBATOR BULAN SEPTEMBER 2025', '2025-09-18', NULL, '[\"public\\/foto-aktivitas\\/68db906aab659.jpg\",\"public\\/foto-aktivitas\\/68db906aab942.jpg\",\"public\\/foto-aktivitas\\/68db906aaba5e.jpg\",\"public\\/foto-aktivitas\\/68db906aabc1a.jpg\"]', '2025-09-30 15:10:18', '2025-09-30 15:10:18');
