INSERT INTO `aktifitas` VALUES (2651, 417, 'LAUNCHING KULINER UMKM', '2025-09-09', 'DALAM RANGKA MEWUJUDKAN PEREKONOMIAN YANG LEBIH DAN PENGEMBANGAN KEGIATAN EKONOMI BERBASIS KEARIFAN LOKAL DAN KEUNGGULAN WILAYAH', '[\"public\\/foto-aktivitas\\/68dcaa26c54ab.jpeg\"]', '2025-10-01 11:02:41', '2025-10-01 11:12:22');
INSERT INTO `aktifitas` VALUES (2652, 482, 'PRA INKUBASI', '2025-09-29', 'Kurasi UMKM dalam kegiatan Pra Inkubasi Bisnis yang di selenggarakan oleh Dinas Koperasi Usaha Kecil dan Menengah Provinsi Banten, Lembaga Inkubator PLUT Banten dan Lembaga Inkubator Pro Link Tanggal 29 - 30 September 2025.', '[\"public\\/foto-aktivitas\\/68df36ea3642d.jpg\",\"public\\/foto-aktivitas\\/68df36ea36785.jpg\",\"public\\/foto-aktivitas\\/68df36ea36904.jpg\",\"public\\/foto-aktivitas\\/68df36ea36a4d.jpeg\"]', '2025-10-03 09:37:30', '2025-10-03 10:05:03');
INSERT INTO `aktifitas` VALUES (2653, 90, 'Temu Usaha CareerBizXpo 2024', '2024-11-15', 'Pada tanggal 15 November 2024 lalu, Tajeer Inkubator Bisnis dan Pusat Karir Universitas Al-Azhar Indonesia, berhasil mengadakan kegiatan CareerBizXpo pertama, pada kesempatan tersebut juga sekaligus dilakukan peresmian kegiatan CBX, yang akan dijadikan program rutin antara inkubator dan pusat karir UAI, ada pun pada kegiatan tersebut di isi dengan beberapa rangkaian acara didalamnya, ada bazaar, talkshow tentang entrepreneur dan karir, seminar, job fair secara online, konsultasi usaha dan karir.', '[\"public\\/foto-aktivitas\\/68df49cd94005.jpeg\"]', '2025-10-03 10:58:05', '2025-10-03 10:58:05');
INSERT INTO `aktifitas` VALUES (2654, 90, 'AIBI SUMMIT 2023', '2023-12-10', 'Tajeer Inkubator Universitas Al Azhar Indonesia menghadiri meeting dan seminar yang diadakan oleh AIBI dengan tema \"Sustainability Sparks: Igniting Innovation & Entrepreneurship\". Acara ini diadakan pada tanggal 10 Desember 2023, Solo Techno Park, Surakarta, Jawa Tengah. Acara ini juga dihadiri oleh 120 inkubator bisnis seluruh Indonesia.', '[\"public\\/foto-aktivitas\\/68df7466e777f.jpeg\"]', '2025-10-03 13:59:50', '2025-10-03 13:59:50');
INSERT INTO `aktifitas` VALUES (2655, 523, 'Sosialiasi Koperasi Desa Merah Putih  Kelurahan Pemecutan', '2025-06-03', 'Turut hadir dalam MUSDES Kelurahan Pemecutan dalam rangka pembentukan Koperasi Desa Merah Putih\r\n\r\nMembangun Ekonomi Kerakyatan dari Desa\r\nMelalui kegiatan sosialisasi ini, Koperasi Desa Merah Putih hadir untuk memperkenalkan manfaat koperasi sebagai wadah pemberdayaan masyarakat dan penggerak ekonomi lokal.\r\n\r\nBersama kita kuat, Bersama Koperasi kita sejahtera', '[\"public\\/foto-aktivitas\\/690fb6066d419.jpg\"]', '2025-10-08 08:04:22', '2025-11-09 04:28:38');
INSERT INTO `aktifitas` VALUES (2656, 523, 'Rapat Koordinasi terkait Koperasi Desa Merah Putih Desa Tegal HArum', '2025-06-04', 'Hadir bersama Kepala Dinas Koperasi dan UKM Kota Denpasar rapat koordinasi dengan Pengurus dan Pengawas Koperasi Desa Merah Putih Tegal Harum', '[\"public\\/foto-aktivitas\\/690fb9b25e6dd.jpg\"]', '2025-10-08 08:06:09', '2025-11-09 04:44:18');
INSERT INTO `aktifitas` VALUES (2657, 1358, 'Peningkatan Kapasitas Koperasi Merah Putih Se Kota Makassar', '2025-08-11', 'Kegiatan ini merupakan kegiatan pelatihan yang diperuntukkan oleh para pengurus koperasi merah putih di kota Makassar, dengan agenda materi, diantaranya adalah : materi tata kelola, materi kewirausahaan dan materi kemitraan usaha', '[\"public\\/foto-aktivitas\\/68edc1dd59e51.png\",\"public\\/foto-aktivitas\\/68edc1dd5a311.png\",\"public\\/foto-aktivitas\\/68edc1dd5a5cd.png\",\"public\\/foto-aktivitas\\/68edc1dd5a959.png\",\"public\\/foto-aktivitas\\/68edc1dd5ac91.png\"]', '2025-10-14 10:22:05', '2025-10-14 10:22:05');
INSERT INTO `aktifitas` VALUES (2658, 1358, 'Kegiataan Peningkatan Kapasitas Pengelola IKM Dinas Perdagangan dan Perindustrian Kota Makassar', '2024-10-22', 'Peningkatan kapasitas ini meliputi Pelatihan Penyusunan SOP dalam Penjangkauan IKM Kota Makassar', '[\"public\\/foto-aktivitas\\/68edc27a2e0c5.jpeg\"]', '2025-10-14 10:24:42', '2025-10-14 10:24:42');
INSERT INTO `aktifitas` VALUES (2659, 154, 'Kunjungan Tempat Usana Tenant Momongor', '2025-07-25', 'Kunjungan Tim PIB UNIBI kepada tenant inwall Momongor milik Dika Ratu mahasiswi UNIBI Program Studi Informatika 2023 yang merupakan binaan PIB UNIBI yang bergerak di bidang retail yakni toko kosmetik, kunjungan ini dimaksudkan untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/690815e577ae6.png\"]', '2025-10-20 16:21:13', '2025-11-03 09:39:33');
INSERT INTO `aktifitas` VALUES (2660, 1359, 'Inkubasi Bisnis Lestari Siak', '2024-07-02', 'Inkubasi Bisnis Lestari Siak (KUBISA) adalah sebuah proses pendampingan dan pengembangan usaha yang dirancang untuk melahirkan pelaku wirausaha di Kabupaten Siak yang memahami prinsip ekonomi lestari. Melalui program ini, masyarakat diberikan ruang untuk mengolah potensi lokal menjadi ide bisnis yang tidak hanya berorientasi pada keuntungan ekonomi, tetapi juga memperhatikan aspek sosial dan lingkungan.\r\n\r\nKUBISA menjadi wadah bagi masyarakat Siak untuk belajar, berinovasi, dan mengembangkan model bisnis yang berkelanjutan sejalan dengan visi Siak Kabupaten Hijau sebagaimana tertuang dalam Peraturan Daerah No. 4 Tahun 2022. Melalui tahapan pelatihan, pendampingan, dan pengujian ide bisnis, KUBISA mendorong lahirnya produk dan jasa yang ramah lingkungan, berbasis potensi lokal, serta mampu memberikan kontribusi nyata bagi kesejahteraan masyarakat dan kelestarian lingkungan di Siak.', '[\"public\\/foto-aktivitas\\/68f707f3525b8.jpeg\"]', '2025-10-21 11:11:31', '2025-10-21 11:11:31');
INSERT INTO `aktifitas` VALUES (2661, 1359, 'Inkubasi Bisnis Alternatif', '2025-12-15', 'Inkubasi Usaha Alternatif (INKLUSIF) merupakan sebuah inkubasi untuk para kelompok petani sawit yang bertujuan untuk peningkatan produksi sawit dan meingkatkan kesejahteraaan kommunitas melalui pemberdayaan ekonomi serta memperkuat usaha alternatif yang berkelanjutan (Alternative Livelihood).\r\n\r\nFokus utama INKLUSIF adalah pemberdayaan perempuan dan pemuda dalam komunitas perkebun sawit melalui unit-unit bisnis alternatif yang bagsis pada pemanfaatan sumberdaya alam setempat.  Kegiatan INKLUSIF ini berkerjasama dengan World Research Institute (WRI). Terdapat 8 materi yang diberikan diantaranya Penguatan tim dan kelompok, Design Kemasan, Visioning, Tata Kelola, BMC,  Literasi Keuangan, Jejaring Mitra, dan Marketing Sosial Media. Dan terdapat sesi sharing dengan ahli yang ada di bidangnya untuk memperdalam usaha yang akan dibuat.', '[\"public\\/foto-aktivitas\\/68f71da968e58.JPG\"]', '2025-10-21 12:44:09', '2025-10-21 12:44:09');
INSERT INTO `aktifitas` VALUES (2663, 101, 'kegiatan Pemasyarakatan Kewirausahaan', '2018-03-18', 'Setelah melalui proses seleksi, maka terpilihlah 27 orang mahasiswa dari Universitas Muhammadiyah Sumatera Utara untuk mengikuti pelatihan kewirausahaan dalam rangkaian kegiatan Pamasyarakatan Kewirausahaan.  Bersama dengan mahasiswa Universitas Islam Sumatera Utara dan Universitas Pembangunan Panca Budi, mahasiswa UMSU mengikuti pelatihan selama 3 hari di Hotel Putra Mulia, mulai tanggal 8 Maret 2018 sampai dengan tanggal 10 Maret 2018.\r\n\r\nPada pelatihan yang diadakan selama 3 hari, mahasiswa dilatih untuk memmbuat rencana bisnis, penyusunan laporan keuangan, pemasaran dan hal terkait lainnya untuk pengembangan usaha. Untuk efektifitas pelatihan, mahasiswa peserta diminta untuk membuat proposal bisnis sebagai luaran dari kegiatan ini dan mempresentasikan kelayakan usahanya.  Hal ini dimaksudkan untuk menseleksi mahasiswa peserta yang layak diberikan hibah pengembangan usaha.\r\n\r\nSetelah melalui proses seleksi, dewan juri memutuskan 20 orang peserta yang layak untuk diberikan hibah pengembangan usaha, sebesar Rp 13.000.000 per orang.  Dari 20 peserta, 8 mahasiswa Universitas Muhammadiyah Sumatera Utara berhasil memperoleh jumlah totah hibah sebesar Rp 104.000.000.  Disusul oleh Universitas Islam Sumatera Utara sebanyak 7 mahasiswa dengan total Rp 91.000.000, serta Universitas Pembangunan Panca Budi sebanyak 5 mahasiswa dengan total Rp 65.000.000\r\n\r\nHal ini merupakan sebuah pencapaian yang patut diberi apresiasi, mengingat tekanan yang dihadapi mahasiswa peserta, yaitu di awal menyisihkan 70 peserta lainnya (dari 150 mahasiswa menjadi 80 mahasiswa), kemudian mengerucut menjadi 20 pemenang.  Terlebih hal ini dilakukan dalam waktu yang relatif singkat, yaitu 2 hari.', '[\"public\\/foto-aktivitas\\/68f9a4695b7f0.jpg\"]', '2025-10-23 10:43:37', '2025-10-23 10:43:55');
INSERT INTO `aktifitas` VALUES (2664, 101, 'Workshop Kewirausahaan Mahasiswa Indonesia di Padang', '2018-03-31', 'Dalam rangka pengembangan usaha yang telah dilakukan oleh mahasiswa, Kemristekdikti Dirjen Belmawa menyelenggarakan kegiatan Kompetisi Bisnis Mahasiswa Indonesia (KBMI).  Dan untuk meningkatkan kualitas proposal KBMI, maka Kemristekdikti Dirjen Belmawa mengadakan Workshop Kewirausahaan.  Kegiatan ini bertujuan agar mahasiswa mampu membuat proposal pengembangan bisnis yang baik dan mampu menganalisis serta mengimplementasikan elemen-elemen penting dalam pengembangan bisnis.', '[\"public\\/foto-aktivitas\\/68f9a5c13ea72.jpg\"]', '2025-10-23 10:49:21', '2025-10-23 10:49:21');
INSERT INTO `aktifitas` VALUES (2665, 101, 'SOSIALISASI GERAKAN MAHASISWA PENGUSAHA', '2018-03-06', 'Kegiatan ini bermaksud memberikan pelatihan kepada mahasiswa pengusaha untuk selanjutnya diberikan hibah pendanaan kepada mahasiswa yang telah mengikuti sosialisasi dan lolos dalam tahap seleksi.  UMSU mengirimkan 50 orang mahasiswa, sebagaimana kuota yang disediakan penyelenggara.  Dalam kegiatan ini mahasiswa akan diberikan pelat ihan kewirausahaan, meliputi perencanaan bisnis, laporan keuangan, dan hal-hal untuk mengembangkan usaha.  Pada akhirnya program akan melakukan seleksi terhadap seluruh peserta sehingga di akhir program akan dipilih 20 mahasiswa pengusaha yang akan diberikan modal untuk mengembangkan usahanya.  Kegiatan ini akan dipantau oleh tim yang ditunjuk oleh Dinas Koperasi dan UKM, untuk keberhasilannya.', '[\"public\\/foto-aktivitas\\/68f9a6f70127e.jpg\"]', '2025-10-23 10:54:31', '2025-10-23 10:54:31');
INSERT INTO `aktifitas` VALUES (2666, 101, 'REKRUTMEN MAHASISWA WIRAUSAHA UNTUK MENGIKUTI SOSIALISASI GERAKAN MAHASISWA PENGUSAHA DAN KOMPETISI BISNIS MAHASISWA INDONESIA', '2018-03-23', 'Kegiatan ini bermaksud memberikan pelatihan kepada mahasiswa pengusaha untuk selanjutnya diberikan hibah pendanaan kepada mahasiswa yang telah mengikuti sosialisasi dan lolos dalam tahap seleksi.  UMSU mengirimkan 50 orang mahasiswa, sebagaimana kuota yang disediakan penyelenggara.  Dalam kegiatan ini mahasiswa akan diberikan pelatihan kewirausahaan, meliputi perencanaan bisnis, laporan keuangan, dan hal-hal untuk mengembangkan usaha.  Pada akhirnya program akan melakukan seleksi terhadap seluruh peserta sehingga di akhir program akan dipilih 20 mahasiswa pengusaha yang akan diberikan modal untuk mengembangkan usahanya.  Kegiatan ini akan dipantau oleh tim yang ditunjuk oleh Dinas Koperasi dan UKM, untuk keberhasilannya.', '[\"public\\/foto-aktivitas\\/68f9a790e48ab.jpg\"]', '2025-10-23 10:57:04', '2025-10-23 10:57:04');
INSERT INTO `aktifitas` VALUES (2667, 101, 'STUDENT ENTREPRENEUR CHAMPIONSHIP', '2018-02-25', 'Pusat Pengembangan Kewirausahaan (PKw) selalu berupaya untuk mengembangkan kewirausahaan mahasiswa, untuk itu  mengadakan beberapa kompetisi yang ditujukan bagi mahasiswa di lingkungan UMSU, dalam ajang Student Entrepreneur Championship.  Adapun kompetisi dalam Student Entrepreneur Championship tersebut adalah sebagai berikut:\r\n\r\nBisnis Plan\r\nProduk Inovatif', '[\"public\\/foto-aktivitas\\/68f9a85409699.jpg\"]', '2025-10-23 11:00:20', '2025-10-23 11:00:45');
INSERT INTO `aktifitas` VALUES (2668, 101, 'SOSIALISASI PROGRAM KERJA PKW UMSU DAN PENYAMAAN PERSEPSI DOSEN KEWIRAUSAHAAN UMSU', '2018-02-10', 'Sehubungan dengan program kerja Pusat Pengembangan Kewirausahaan (PKw) di tahun 2018, Kemristekdikti (Kompetisi Bisnis Mahasiswa Indonesia dan Expo KMI 2018), serta berbagai kompetisi kewirausahaan lainnya, maka PKw memandang perlu untuk mensosialisasikan program-program PKw tersebut kepada dosen pengampu mata kuliah kewirausahaan di lingkungan Universitas Muhammadiyah Sumatara Utara.', '[\"public\\/foto-aktivitas\\/68f9a97e10623.jpg\"]', '2025-10-23 11:05:18', '2025-10-23 11:05:18');
INSERT INTO `aktifitas` VALUES (2669, 101, 'PROGRAM BELAJAR BEKERJA TERPADU (PBBT) 2017 UMSU', '2017-09-19', 'Pusat Pengembangan Kewirausahaan (PKw) Universitas Muhammadiyah Sumatera Utara pada tahun 2017 memperoleh dana hibah Program Belajar Bekerja Terpadu (PBBT) dari Direktorat Kemahasiswaan (Belmawa) Kemenristekdikti, sesuai dengan Surat Perjanjian Pelaksaan Pekerjaan (Kontrak) No: 572.34/B3.2/SPK-PBBT/2017 Tanggal 25 Juli 2017. Kegiatan ini dilakukan selama lebih kkurang 3 bulan (mulai  Agustus s/d Oktober 2017), dan diikuti oleh mahasiswa dari beberapa fakultas yang ada di lingkungan UMSU', '[\"public\\/foto-aktivitas\\/68f9abde676a0.jpg\"]', '2025-10-23 11:15:26', '2025-10-23 11:15:26');
INSERT INTO `aktifitas` VALUES (2670, 101, 'PKw UMSU Selenggaarakan Sosialisasi UTU AWARDS dan PKM-K', '2017-08-21', 'Pusat Pengembangan Kewirausahaan (PKw) memberikan perhatian yang serius pada kompetisi kewirausahaan yang diselenggarakan berbagai pihak, baik lokal, nasional maupun internasional.  Pada tingkat nasional, dalam waktu yang hampir bersamaan, akan digelar UTU Awards Ke-3 2017 (diselenggarakan oleh Universitas Teuku Umar, Meulaboh, NAD) dan Program Kreatifitas Mahasiswa Kewirausahaan/ PKMK (diselenggarakan oleh Kemenristekdikti)\r\n\r\nDalam UTU Awards 2017 kompetisi yang diadakan meliputi: Perencanaan Bisnis, Desain Toko Online, Karya Inovatif Berbasis Agro dan Riset Berbasis Entrepreneurship, sedangkan dalam PKMK adalah pembuatan Bisnis Plan.  Kegiatan ini berdekatan jadwalnya, yang dimulai dari bulan Agustus sampai dengan September akhir.\r\n\r\nUntuk mengoptimalkan kemampuan mahasiswa dalam mengikuti kegiatan tersebut, maka Pusat Pengembangan Kewirausahaan (PKw) bermaksud untuk mengadakan pelatihan bagi mahasiswa.  Pelatihan ini dimaksudkan untuk memberikan pembekalan bagi mahasiswa agar mampu mempersiapkan proposal dan segala hal yang diperlukan dalam kompetisi tersebut.', '[\"public\\/foto-aktivitas\\/68f9ac9526727.jpg\"]', '2025-10-23 11:18:29', '2025-10-23 11:18:29');
INSERT INTO `aktifitas` VALUES (2671, 101, 'PELATIHAN DIGITAL MARKETING BERSAMA PT. TELKOM INDONESIA', '2017-04-29', 'erkembangan teknologi informasi yang semakin canggih telah merubah sistem pemasaran konvensional menjadi sistem pemasaran berbasis teknologi informasi.  Sistem pemasaran ini dikenal sebagai sistem pemasaran online.  Pemasaran berbasis teknologi informasi atau pemasaran online sekarang ini telah menjadi bagian penting dalam kewirausahaan,  sehingga Pusat Pengembangan Kewirausahaan kami merasa penting  untuk mengadakan pelatihan pemasaran online bagi mahasiswa.\r\n\r\nKegiatan ini diselenggarakan pada hari Sabtu tanggal 29 April 2017.  Kegiatan ini akan sangat bermanfaat karena dapat langsung diaplikasikan mahasiswa untuk memasarkan produknya secara online.\r\n\r\nKegiatan ini diadakan di Ruang Penjamin Mutu Gd F Lt 2 kampus 3 UMSU', '[\"public\\/foto-aktivitas\\/68f9ad5e5a3ee.jpg\"]', '2025-10-23 11:21:50', '2025-10-23 11:21:50');
INSERT INTO `aktifitas` VALUES (2672, 101, 'MAHASISWA UMSU MENGIKUTI KOMPETISI BISNIS PLAN SUMATERA UTARA', '2017-04-23', 'Dalam kompetisi bisnis plan yang diadakan oleh Universitas Prima Indonesia, dua kelompok mahasiswa yang dibimbing oleh Pusat Pengembangan Kewirausahaan (PKw) berhasil menjadi Finalis\r\n\r\nAdapun babak final kompetisi Bisnis Plan tersebut diadakan pada hari Minggu, tanggal 23 April 2017 di Focal Point.  Adapun produk yang dikompetisikan adalah celengan berbahan limbah bumbu dapur dan scrapbook.', '[\"public\\/foto-aktivitas\\/68f9ae4035f28.jpg\"]', '2025-10-23 11:25:36', '2025-10-23 11:25:36');
INSERT INTO `aktifitas` VALUES (2673, 101, 'Pelatihan Pembuatan Kerajinan Bunga Berbahan Flanel', '2017-04-08', 'Pusat Pengembangan Kewirausahaan (PKW) Universitas Muhammadiyah Sumatera Utara, selalu berupaya menciptakan mahasiswa wirausaha, menjadi alasan  untuk mengadakan pelatihan pembuatan kerajinan bunga berbahan flanel bagi mahasiswa serta strategi pemasaran.\r\n\r\nKegiatan ini diselenggarakan pada hari Sabtu tanggal 8 April 2017.  Kegiatan ini sangat bermanfaat mengingat pada saat sidang meja hijau mahasiswa memiliki kesempatan untuk mempromosikan dan memasarkan produk hasil pelatihannya tersebut.\r\n\r\nKegiatan ini dilakukan dalam kelas kecil, dengan    mahasiswa sebagai peserta pelatihan.', '[\"public\\/foto-aktivitas\\/68f9aee206c6c.jpg\"]', '2025-10-23 11:28:18', '2025-10-23 11:28:18');
INSERT INTO `aktifitas` VALUES (2674, 101, 'Expo Kewirausahaan Fakultas Ekonomi UMSU 2017', '2017-03-29', 'Program studi Manajemen pada 29 Maret 2017 melaksanakan Expo dengan tema One Day Entrepreneur, dengan difasilitasi oleh Pusat Pengembangan Kewirausahaan (PKW) Universitas Muhammadiyah Sumatera Utara.  Kegiatan ini bertujuan untuk mempromosikan produk kreatif karya mahasiswa, sebagai luaran dari mata kuliah Workshop Kewirausahaan.  Dalam kegiatan ini, juga dilakukan lomba bisnis plan dan produk kreatif.  Luaran mata kuliah adalah mahasiswa dituntut untuk memproduksi produk kreatif dan melakukan pemasaran, sehingga dapat diketahui bagaimana implementasi kewirausahaan oleh mahasiswa-mahasiswa tersebut.\r\n\r\nPada saat yang sama dilakukan peresmian Kampung Digital Pusat Pengembangan Kewirausahaan (PKW) Universitas Muhammadiyah Sumatera Utara, sebagai luaran dari kerja sama yang dilakukan oleh PKw dan PT. Telkom Indonesia.  Kampung Digital ini sebagai wadah untuk mempromosikan produk mahasiswa secara lebih luas.', '[\"public\\/foto-aktivitas\\/68f9af88adb7b.jpg\"]', '2025-10-23 11:31:04', '2025-10-23 11:31:04');
INSERT INTO `aktifitas` VALUES (2675, 101, 'Student Entrepreneur Championship 2017 MILAD UMSU 69 Tahun', '2017-02-20', 'Kewirausahaan dimulai dengan minat, motivasi dan intensi. Minat, motivasi dan intensi terhadap kewirausahaan dapat menggiring mahasiswa untuk melakukan kegiatan kewirausahaan.  Minat, motivasi dan intensi dapat ditumbuhkan melalui berbagai cara.  Salah satunya adalah kompetisi.  Kompetisi melatih mahasiswa sebagai calon wirausaha untuk mengembangkan kemampuannya, mengasah kreativitasnya sehingga dapat memenangkan persaingan. Pusat Pengembangan Kewirausahaan (PKw) memandang perlu untuk menumbuhkan kompetisi di antara mahasiswa dalam bidang kewirausahaan.\r\n\r\nSehubungan dengan program kerja Pusat Pengembangan Kewirausahaan (PKw) di tahun 2017, yaitu mengembangkan kewirausahaan mahasiswa, maka dengan ini Pusat Pengembangan Kewirausahaan (PKw)  mengadakan beberapa kompetisi yang ditujukan bagi mahasiswa di lingkungan UMSU, dalam ajang Student Entrepreneur Championship.  Adapun kompetisi tersebut adalah sebagai berikut:\r\n\r\nCerdas Cermat, diadakan tanggal 20-21 Februari 2017\r\nBisnis Plan, diadakan tanggal 22-23 Februari 2017\r\nProduk Inovatif, diadakan tanggal 25 Februari 2017\r\nExpo Produk Inovatif, diadakan tanggal 18-19 Maret 2017', '[\"public\\/foto-aktivitas\\/68f9b5136b005.jpg\"]', '2025-10-23 11:39:22', '2025-10-23 11:54:43');
INSERT INTO `aktifitas` VALUES (2676, 101, 'Mengembangkan Kewirausahaan Desa Bagan Serdang Kecamatan Pantai Labu, Kabupaten Deli Serdang', '2017-01-11', 'Pusat Pengembangan Kewirausahaan (PKw)  memberikan perhatian pada kewirausahaan yang dilakukan oleh masyarakat sama besarnya dengan yang dilakukan oleh mahasiswa.  Bentuk perhatian kewirausahaan tersebut ditunjukkan oleh diadakannya pelatihan kewirausahaan dalam mengembangkan usaha masyarakat di kawasan Desa Bagan Serdang Kecamatan Pantai Labu, Kabupaten Deli Serdang Propinsi Sumatera Utara.  Adapun usaha yang menjadi prioritas Desa Bagan Serdang tersebut adalah pembuatan kerupuk berbahan tumbuhan jeruju.  Tumbuhan jeruju ini memiliki nilai, baik dari segi kesehatan maupun dari segi ekonomi.  Dari segi kesehatan tumbuhan jeruju ini dapat menyembuhkan radang hati, kanker hati, hepatitis, beberapa  radang terkait bisul untuk mempercepat matang dan meledaknya bisul, radang tenggorokan pada batuk.  Masyarakat telah memanfaatkan tumbuhan jeruju ini sebagai bahan dasar pembuatan kerupuk.  Sebagaimana masyarakat tradisional, pengolahan kerupuk ini masih dikerjakan secara tradisional dan sederhana. Masyarakat belum mengenal inovasi produk serta sistem pemasaran yang baik untuk produk tersebut, padahal produk tersebut sangat berpotensi untuk dikembangkan, mengingat manfaat untuk kesehatan yang dimilikinya.\r\n\r\nAtas inisiatif Ikatan Mahasiswa Muhammadiyah Fakultas Ekonomi, Universitas Muhammadiyah Sumatera Utara, IMM mengundang  Pusat Pengembangan Kewirausahaan (PKw) untuk memberikan pelatihan kewirausahaan kepada masyarakat Desa Bagan Serdang sebagai desa binaannya, dalam hal inovasi produk jeruju serta sistem pemasaran sehingga produk dapat dikenal lebih luas.  Kegiatan dilakukan pada hari Rabu, 11 Januari 2017, yang dilakukan mulai pukul 13.00 sampai dengan selesai.\r\n\r\nAdapun pemateri adalah tim PKw yaitu Dewi Andriany, S.E, M.M; Ir. Gustina Siregar, M.Si; Henny Zurika Lubis, S.E, M.Si; Yusrita, S.E, M.M; serta Efry Kurnia, S.E, M.Si\r\n\r\nSebagai kelanjutan dari kegiatan ini, PKw akan menjadikan Desa Bagan Serdang sebagai desa binaan, melalui program Iptek bagi Desa Mitra, dengan beberapa program kerja, yang bertujuan menjadikan Desa Bagan Serdang sebagai desa yang sejahtera.', '[\"public\\/foto-aktivitas\\/68f9b59e1fad9.jpg\"]', '2025-10-23 11:57:02', '2025-10-23 11:57:02');
INSERT INTO `aktifitas` VALUES (2677, 101, 'Sosialiasi Tenan PUSKIIBI UMSU Ke Paluh Gelombang-Deli Serdang', '2019-09-17', 'sosialisasi yang dilakukan oleh salah satu Tenan yang berhasil mendapatkan dana Hibah KEMENRISTEKDIKTI 2018 dalam ajang Perusahaan Pemula Berbasis Teknologi (PPBT) atas nama Muhammad Rizky  yang didampingi oleh Tim PUSKIIBI berkunjung ke Paluh Gelombang untuk memperkenalkan produk yang dihasilkan berupa pakan ikan lele dengan merek MY CATFISH. Sosialisasi ini bertujuan agar peternak lele yang ada di daerah tersebut mau untuk bermitra dengan tenan dan menjadi reseller secara berkelanjutan dalam pembelian serta penjualan pakan ikan lele yang mereka usahakan. Selain itu sosialiasi ini juga untuk berdiskusi mengenai evaluasi produk yang ditawarkan kepada pengguna langsung demi pengembangan produk menjadi lebih baik. Hasil kegiatan ini telah didapatkan mitra yang tetap, kesiapan tenan tentang kondisi pasar pakan ikan dan evaluasi agar lebih sempurna lagi.\r\n\r\nSosialisasi ini dilakukan sebagai tindak lanjut dari  Business Matching tenant (My Catfish) dengan pembeli beberapa waktu yang lalu.\r\n\r\nSosialisasi tenant ke desa Paluh Gelombang dilakukan dalam rangka memperkenalkan produk pakan ikan air tawar kepada para komunitas petani tambak di daerah tersebut. Produk pakan ikan alumni UMSU ini merupakan pakan ikan air tawar khususnya ikan lele yang memiliki kandungan protein yang lebih tinggi dibandingkan pakan ikan air tawar lainnya.\r\n\r\nPakan ikan yang diperkenalkan kepada komunitas petani tambak memiliki merek my catfish yang dihasilkan oleh PT. Mandiri Pakan Bersinar milik M. Rizki Siswanto pemenang PPBT (Perusahaan Pemula Berbasis Teknologi) dari KemeristekDikti.', '[\"public\\/foto-aktivitas\\/68f9b67116151.jpeg\"]', '2025-10-23 12:00:33', '2025-10-23 12:00:33');
INSERT INTO `aktifitas` VALUES (2678, 101, 'PELATIHAN MANAJEMEN KEUANGAN UNTUK PEMENANG KBMI 2019', '0019-09-09', 'Pelatihan ini merupakan rangkaian aktivitas yang diprogramkan oleh PUSKIIBI UMSU untuk membantu para pemenang KBMI untuk dapat menyusun laporan keuangan secara sederhana, mengingat pemenang KBMI merupakan mahasiswa yang bukan berasal dari Fakultas ekonomi yang mempelajari sistem keuangan secara baik dan benar. Selain itu kegiatan ini juga membantu mahasiswa dalam penyusunan anggaran yang dianggap susah oleh mahasiswa karena ada beberapa istilah keuangan yang membingungkan ketika proses kegiatan KBMI berlangsung. Kegiatan ini dilakukan pada saat proses KBMI berlangsung sampai proses produksi ketika bahan dan alat sudah dibeli, sehingga mahasiswa sudah memiliki berbagai bukti pembelian bahan dan alat tersebut dalam bentuk kwitansi', '[\"public\\/foto-aktivitas\\/68f9b6dd38948.jpeg\"]', '2025-10-23 12:02:21', '2025-10-23 12:02:21');
INSERT INTO `aktifitas` VALUES (2679, 101, 'Pelatihan Dosen Kewirausahaan UMSU', '2019-02-10', 'Pelatihan dosen kewirausahaan merupakan kegiatan rutin yang dilakukan Pusat Kewirausahaan, Inkubator, dan Inovasi Bisnis (PUSKIIBI) untuk selalu berkoordinasi dalam penyusunan dan pengembangan materi mata kuliah Kewirausahaan di Lingkungan Universitas Muhammadiyah Sumatera Utara (UMSU) sesui dengan perkembangan ilmu pengetahuan dan teknologi. Dalam pelatihan ini diikuti dosen kewirausahaan di 8 fakultas yang ada di UMSU yaitu Fakultas Ekonomi dan Bisnis (FEB), Fakultas Keguruan dan ilmu Pendidikan (FKIP), Fakultas kedokteran (FK), Fakultas Pertanian (FAPERTA), Fakultas Ilmu Sosial dan Ilmu Politik (FISIP), Fakultas Hukum (FAHUM), Fakultas Teknik (FATEK), dan Fakultas Agama Islam (FAI). Dalam kegiatan ini PUSKIIBI juga selalu menghadirkan pemateri yang sangat ahli dibidang Kewirasuhaan sehingga para dosen dapat langsung berdiskusi mengenai jenis kewirausahaan sesuai dengan Fakultas masing-masing, seperti Bisnis Plan dan Bisnis Model Canvas (BMC)', '[\"public\\/foto-aktivitas\\/68fadcff46cc4.jpeg\"]', '2025-10-24 08:57:19', '2025-10-24 08:57:19');
INSERT INTO `aktifitas` VALUES (2680, 101, 'ajang Pekan Ilmiah Kreativitas Mahasiswa Nasional (PIKMN) dan Pameran Teknologi Tepat Guna Nasional 2018', '2018-10-28', 'Pengembangan Kewirausahaan (PKW) mengikuti ajang Ekspo Kewirausahaan dan Pameran Teknologi Tepat Guna Nasional 2018.\r\n\r\nDalam kegiatan ini UMSU menampilkan berbagai karya terbaik dari mahasiswa yakni poster ilmiah, poster promosi dan teknologi tepat guna serta produk-produk kewirausahaan Mahasiswa yang diselenggarakan selama 2 hari 26-27 November 2018 di Universitas Sumatera Utara.', '[\"public\\/foto-aktivitas\\/68fadd70ac2ff.jpeg\"]', '2025-10-24 08:59:12', '2025-10-24 08:59:12');
INSERT INTO `aktifitas` VALUES (2681, 101, 'Ekspo KMI 2018 Nasional di IPB Jawa Barat', '2018-10-15', 'UMSU mengikuti Ekspo KMI 2018 Nasional yang di ikuti sebanyak 124 Universitas se-Indonesia, 5 Mahasiswa UMSU yang di bina oleh PKw UMSU berhasil lolos untuk memamerkan Produk Wirausaha Mahasiswa di Ekspo KMI 2018 yang dilaksanakan di IPB Bogor- Jawa Barat.\r\nKegiatan Ekspo dilaksanakan pada tanggal 9-12 Nopember 2018.', '[\"public\\/foto-aktivitas\\/68faddd3ad2ad.jpeg\"]', '2025-10-24 09:00:51', '2025-10-24 09:00:51');
INSERT INTO `aktifitas` VALUES (2682, 101, 'FGD dan Business Matching Untuk IBT(Inkubator Bisnis Teknologi) UMSU', '2018-10-30', 'Focus group discussion Inkubator Bisnis Teknologi Pusat Pengembangan Kewirausahaan  Universitas Muhammadiyah Sumatera Utara kerjasama PKW UMSU dan Dirjen Kelembagaan Iptek dan Dikti  Kemenristekdikti di Hotel Emerald Garden Medan, Senin (29/10).\r\n.\r\nWakil Rektor III Dr. Rudianto M.Si dalam sambutannya mengatakan  UMSU berkomitmen membangun generasi yang tangguh mengikuti perkembangan zaman untuk menghasilkan pengusaha muda yang siap menghadapi era disrupsi industri 4.0.\r\n\r\nHadir dalam acara ini Tim Pendamping Kemenristekdikti  Ir. Gopa Kusworo M.Eng dan Deva Primadia Almada M.Si, Kepala Inkubator PKW UMSU Hj. Dewi andriany, SE MM, serta para stakeholder dari Dinas Koperasi dan UKM Pemprov Sumut, Dinas Pertanian dan Kelautan Kota Medan, BpOM Kota Medan, BRISyariah, Pusat Penelitian Kelapa Sawit.', '[\"public\\/foto-aktivitas\\/68fade5405663.jpg\"]', '2025-10-24 09:03:00', '2025-10-24 09:03:00');
INSERT INTO `aktifitas` VALUES (2683, 101, 'UMSU Menjadi Tuan Rumah Monev Eksternal KBMI 2018', '2018-10-18', 'dalam rangka pengembangan usaha yang telah dilakukan oleh mahasiswa,\r\nKemristekdikti Dirjen Belmawa menyelenggarakan kegiatan Kompetisi Bisnis\r\nMahasiswa Indonesia (KBMI).\r\nUniversitas Muhammadiyah Sumatera Utara ditunjuk oleh Kementerian Riset,\r\nTeknologi dan Pendidikan Tinggi sebagai Host pelaksanaan Monitoring dan Evaluasi\r\n(Monev) Eksternal Kompetisi Bisnis Mahasiswa Indonesia (KBMI) 2018, yang\r\ndilaksanakan pada\r\nHari/ tanggal : Rabu. 17 Oktober 2018\r\nTempat          : Gedung Pascasarjana Universitas Muhammadiyah Sumatera Utara Jl. Denai No 217 Medan\r\nWaktu            : 08  .00 WIB s/d selesai\r\nMonev External KBMI 2018 ini dihadiri oleh 5 perguruan tinggi yaitu Universitas\r\nMuhammadiyah Sumatera Utara (4 tim), Universitas Medan Area (6 tim), Universitas Negeri\r\nMedan (3 tim), Universitas Sumatera Utara (1 tim) dan Universitas Samudra Langsa (6 tim).\r\nAcara ini dibuka oleh Wakil Rektor 3 Universitas Muhammadiyah Sumatera Utara. Dalam\r\nsambutannya, WR 3 menyatakan bahwa program KBMI sangat berperan dalam\r\nmengembangkan usaha mahasiswa, sehingga mereka menjadi mandiri dan dapat\r\nmenciptakan lapangan kerja. Beliau berharap akan banyak wirausaha di Sumatera Utara\r\nterus muncul dan mampu bersaing, tidak hanya di pasar lokal, namun menembus pasar\r\nyang lebih luas.', '[\"public\\/foto-aktivitas\\/68fadecb7c4f8.jpg\"]', '2025-10-24 09:04:59', '2025-10-24 09:04:59');
INSERT INTO `aktifitas` VALUES (2684, 101, 'Monitoring dan Evaluasi Internal KBMI 2018 UMSU', '2018-09-03', 'Berdasarkan surat nomor: 1775 /B3.2/KM/2018, tanggal  6 Juni 2018 dari KEMENTERIAN RISET, TEKNOLOGI DAN PENDIDIKAN TINGGI DIREKTORAT JENDERAL PEMBELAJARAN DAN KEMAHASISWAAN, perihal Pengumuman Kompetisi Bisnis Mahasiswa Indonesia (KBMI) Yang Didanai Tahun 2018.', '[\"public\\/foto-aktivitas\\/68fadf56516ae.jpeg\"]', '2025-10-24 09:07:18', '2025-10-24 09:07:18');
INSERT INTO `aktifitas` VALUES (2685, 101, 'PENGEMBANGAN KELEMBAGAAN INKUBATOR BISNIS TEKNOLOGI TAHUN 2018', '2018-07-26', 'Berdasarkan surat No 352/C3/KL/2018 dari Kemenristekdikti Dirjen Kelembagaan Ilmu Pengetahuan, Teknologi dan Pendidikan Tinggi, Pusat Pengembangan Kewirausahaan dinyatakan LULUS dalam seleksi administrasi dan substansi, dan memperoleh Bantuan Pengembangan Kelembagaan Inkubator Bisnis Teknologi  Tahun 2018 senilai Rp 200.000.000.\r\n\r\nDalam Bantuan Pengembangan Kelembagaan Inkubator Bisnis Teknologi  Tahun 2018 ini, Kemristekdikti hanya memfasilitasi 12 Inkubator, termasuk Pusat Pengembangan Kewirausahaan UMSU.\r\nDalam pelatihan dipaparkan pentingnya incubator bisnis teknologi dalam mengembangkan kewirausahaan.  PKw sebagai incubator tentunya memiliki inovasi yang dilahirkan oleh dosen, mahasiswa, alumni maupun masyarakat luas yang dapat dimanfaatkan untuk mengembangkan usaha rintisan.  Sehingga pada akhirnya akan mampu melahirkan perusahaan pemula berbasis teknologi yang memiliki daya saing, baik di tingkat regional, nasional maupun internasional.\r\n\r\nBantuan Pengembangan Kelembagaan Inkubator Bisnis Teknologi  Tahun 2018 dalam rangka capacity building pengelola incubator akan menyelenggarakan beberapa workshop, yang akan diadakan di Belitung, Bogor, dan Bali.', '[\"public\\/foto-aktivitas\\/68fae083789d3.jpg\"]', '2025-10-24 09:12:19', '2025-10-24 09:12:19');
INSERT INTO `aktifitas` VALUES (2686, 101, 'Mahasiswa Binaan PKw UMSU berhasil memenangkan Kompetisi Bisnis Mahasiswa Indonesia (KBMI)  dari Kemenristekdikti', '2018-06-07', 'Dalam rangka pengembangan usaha yang telah dilakukan oleh mahasiswa, Kemristekdikti Dirjen Belmawa menyelenggarakan kegiatan Kompetisi Bisnis Mahasiswa Indonesia (KBMI).  Pusat Pengembangan Kewirausahaan Universitas Muhammadiyah Sumatera Utara berkomitmen untuk mengembangkan kewirausahaan mahasiswa dan turut ambil bagian dalam Kompetisi Bisnis Mahasiswa Indonesia yang diadakan Kemristekdikti Dirjen Belmawa tersebut. Dalam KBMI tersebut, UMSU mengirimkan 21 proposal yang layak untuk dikompetisikan.', '[\"public\\/foto-aktivitas\\/68fae0ea2489a.jpg\"]', '2025-10-24 09:14:02', '2025-10-24 09:14:02');
INSERT INTO `aktifitas` VALUES (2687, 101, 'PUSKIIBI UMSU raih Penghargaan di Ajang Nasional', '2025-10-16', 'Kabar membanggakan datang dari Pusat Kewirausahaan, Inovasi, dan Inkubator Bisnis (PUSKIIBI) Universitas Muhammadiyah Sumatera Utara 🎉\r\n\r\nPada kegiatan The 2025 International Conference on Sustainable Innovation and Environment (ICSIE) serta AAIBI–AIBI Summit yang berlangsung di Surakarta, 15–16 Oktober 2025, PUSKIIBI UMSU berhasil meraih penghargaan dalam kategori Inkubator Berkembang yang diikuti oleh Inkbator bisnis dari seluruh Indonesia dan 26 Negara di Asia. Selain itu sebanyak 2 startup berkembang yaitu @osarupetrecycle_ dan @cacajamur serta 4 startup pemula yaitu KJA NAULI, @mital_plameps, @mafazagift dan @scylla.serrata juga mendapat Penghargaan pada kategori masing-masing.', '[\"public\\/foto-aktivitas\\/68fae15a6e365.jpg\"]', '2025-10-24 09:15:54', '2025-10-24 09:15:54');
INSERT INTO `aktifitas` VALUES (2688, 101, 'Mahasiswa UMSU Lolos Ke Semifinal KBMK 2025', '2025-09-24', 'Mahasiswa UMSU terpilih menjadi bagian dari 53 tim semifinalis nasional KBMK 2025 dari 203 perguruan tinggi se-Indonesia.', '[\"public\\/foto-aktivitas\\/68fae1a9afa66.jpg\"]', '2025-10-24 09:17:13', '2025-10-24 09:17:13');
INSERT INTO `aktifitas` VALUES (2689, 101, 'Business Matching P2MW 2025', '2025-09-23', 'Sebagai bagian dari Program Pembinaan Wirausaha Mahasiswa (P2MW) 2025, digelar kegiatan Business Matching yang menghadirkan wirausaha muda dengan mitra potensial, investor, hingga praktisi bisnis.', '[\"public\\/foto-aktivitas\\/68fae202714e4.jpeg\"]', '2025-10-24 09:18:42', '2025-10-24 09:18:42');
INSERT INTO `aktifitas` VALUES (2690, 101, 'Bimtek Kemajuan P2MW “Optimalisasi Bisnis Inovasi Mahasiswa”', '2025-09-10', 'PUSKIIBI UMSU mengadakan Bimbingan Teknis Kemajuan P2MW 2025 bagi adik-adik mahasiswa yang berhasil mendapat pendanaan dari BELMAWA di Gedung Aula FEB UMSU lantai 2. Adapun yang mendapat Pendanaan 7 Tim Usaha yang berkolaborasi dari berbagai lintas Fakultas.', '[\"public\\/foto-aktivitas\\/68fae29dabc6b.jpg\"]', '2025-10-24 09:21:17', '2025-10-24 09:21:17');
INSERT INTO `aktifitas` VALUES (2691, 101, 'Pelatihan Manajemen Keuangan kepada 7 Tim P2MW 2025', '2025-08-05', 'ertempat di Aula FEB, pelatihan manajemen keuangan P2MW 2025 UMSU dilangsungkan dengan narasumber Ibu Dr. Mutia Arda, S.E., M.Si dan dibuka langsung oleh Ibu Ketua PUSKIIBI Ibu Assoc. Prof. Dewi Andriany, S.E., M.M.', '[\"public\\/foto-aktivitas\\/68fae35aa71d4.jpg\"]', '2025-10-24 09:24:26', '2025-10-24 09:24:26');
INSERT INTO `aktifitas` VALUES (2692, 101, 'Pelatihan Digital Marketing P2MW 2025', '2025-08-19', 'Bertempat di Aula FEB, pelatihan digital marketing P2MW 2025 UMSU dilangsungkan dengan narasumber abang M. Yusuf Imfazu, S.Ikom selaku alumni P2MW 23/34 dan dibuka langsung oleh Ibu Ketua PUSKIIBI Ibu Assoc. Prof. Dewi Andriany, S.E., M.M.', '[\"public\\/foto-aktivitas\\/68fae3c63d72d.jpg\"]', '2025-10-24 09:26:14', '2025-10-24 09:26:14');
INSERT INTO `aktifitas` VALUES (2693, 101, 'UMSU PERINGKAT 1 PTN PTS SEINDONESIA DALAM PROGRAM P2MW TAHUN 2025', '2025-07-16', 'Alhamdulillah 7 Proposal Usaha Mahasiswa UMSU berhasil di danai oleh KEMDIKTISAINTEK dalam Program Pembinaan Mahasiswa Wirausaha (P2MW) 2025.', '[\"public\\/foto-aktivitas\\/68fae428c0c3a.jpg\"]', '2025-10-24 09:27:52', '2025-10-24 09:27:52');
INSERT INTO `aktifitas` VALUES (2694, 101, 'Pelatihan Dosen Pendamping P2MW Tahun 2025', '2025-02-19', 'PUSKIIBI UMSU melakukan Pelatihan Dosen Pendamping dalam Program Pembinaan Mahasiswa Wirausaha Tahun 2025. Kegiatan ini bertujuan untuk membekali para dosen dengan strategi pendampingan yang efektif dalam mendukung mahasiswa mengembangkan usaha mereka melalui Program Pembinaan Mahasiswa Wirausaha (P2MW).\r\n\r\nDengan semangat kolaborasi dan inovasi, kami yakin bahwa bimbingan yang tepat dari para dosen akan mendorong lahirnya wirausahawan muda yang kreatif dan berdaya saing. Mari bersama menciptakan ekosistem kewirausahaan yang lebih kuat di dunia akademik!', '[\"public\\/foto-aktivitas\\/68fae49323cdc.jpeg\"]', '2025-10-24 09:29:39', '2025-10-24 09:29:39');
INSERT INTO `aktifitas` VALUES (2695, 101, 'PELATIHAN PEMBUATAN PROPOSAL P2MW 2025', '2025-02-21', 'Kegiatan ini akan dilaksanakan pada 30 Januari 2025 di Aula FEB UMSU. Kegiatan pelatihan pembuatan proposal ini merupakan kegiatan reguler yang diadakan puskiibi dalam rangka membantu para mahasiswa umsu untuk mengembangkan minat wirausaha, mempersiapkan uji kompetensi kewirausahaan dan mempersiapkan lomba P2MW.\r\n\r\nPelatihan pembuatan proposal ini membahas isian bab yang ada dalam proposal bisnis sehingga mahasiswa dapat membuat rancangan bisnis yang baik dan benar.', '[\"public\\/foto-aktivitas\\/68fae4ee80e9e.jpg\"]', '2025-10-24 09:31:10', '2025-10-24 09:31:10');
INSERT INTO `aktifitas` VALUES (2696, 101, 'Kick Off Program Wirausaha Merdeka UMSU Tahun 2024', '2024-09-30', 'Kick Off Program Wirausaha Merdeka Tahun 2024 “Smart Entrepreneurship Season II” Society, Meaningful, Adaptive, Rich, Technology based” berlangsung pada Sabtu, 28 September 2024 pada pukul 09.00 WIB di Gedung Auditorium Rektor UMSU. Kegiatan ini dilaporkan langsung oleh Ketua Program WMK sekaligus Ketua PUSKIIBI yaitu Ibu Assoc. Prof. Dewi Andriany, S.E., M.M, dibuka oleh Bapak Rektor UMSU yaitu Bapak Prof. Dr. Agussani, MAP. Kegiatan ini juga menghadirkan Narasumber yang sangat berpengalaman di bidang wirausaha yang menjadi Bussines Development di startup RedBus yaitu Bapak Mohammad Arkham Chadiar Jantra atau yang sering disapa Pak Jantra.', '[\"public\\/foto-aktivitas\\/68fae54cc9dd7.jpeg\"]', '2025-10-24 09:32:44', '2025-10-24 09:32:44');
INSERT INTO `aktifitas` VALUES (2697, 101, 'PELATIHAN MANAJEMEN KEUANGAN UNTUK MAHASISWA P2MW 2024', '2024-05-30', 'ahasiswa Universitas Muhammadiyah Sumatera Utara telah memperoleh dana hibah dari KEMDIKBUDRISTEK dalam ajang Program Pembinaan Mahasiswa Wirausaha (P2MW) tahun 2024 sebanyak 16 tim. Hal ini tentunya perlu support dari UMSU khususnya tim PUSKIIBI dalam mengembangkan potensi pengembangan usaha yang dimiliki.\r\n\r\nMenindaklanjuti hal tersebut, tim PUSKIIBI UMSU melakukan Pelatihan Manajemen Keuangan dengan 16 tim pemenang P2MW 2024. Hal ini dimaksudkan agar Mahasiswa dapat dengan terarah mengembangkan usaha khususnya dalam melakukan manajemen keuangan tim mereka sesuai dengan harapan dan ketentuan KEMDIKBUDRISTEK.\r\n\r\nKegiatan ini dilakukan secara luring di Gedung Aula FAPERTA UMSU pada:\r\n\r\nHari/ tanggal      : Rabu / 08 Mei 2024\r\n\r\nWaktu                : 09.00 s/d selesai (P2MW)\r\n\r\nTempat               : Gedung Aula FAPERTA UMSU\r\n\r\nNarasumber : Mutia Arda, S.E., M.Si', '[\"public\\/foto-aktivitas\\/68fae5b9c851f.jpg\"]', '2025-10-24 09:34:33', '2025-10-24 09:34:33');
INSERT INTO `aktifitas` VALUES (2698, 101, 'PELATIHAN BUSINESS MODEL CANVAS UNTUK MAHASISWA P2MW 2024', '2024-05-30', 'Pelatihan business plan dan bmc ini membahas isian bab yang ada dalam proposal bisnis sehingga mahasiswa dapat membuat rancangan bisnis yang baik dan benar.', '[\"public\\/foto-aktivitas\\/68fae633d1c43.jpg\"]', '2025-10-24 09:36:35', '2025-10-24 09:36:35');
INSERT INTO `aktifitas` VALUES (2699, 101, '16 tim mahasiswa UMSU berhasil memperoleh Pendanaan P2MW 2024', '2024-04-04', 'alhamdulillah,\r\nUniversitas Muhammadiyah Sumatera Utara memperoleh peringkat ketiga PTMA se Indonesia, peringkat keempat PTN/PTS se Indonesia, peringkat pertama PTN/PTS se SUMUT, dan peringkat pertama LLDIKTI Wilayah I dalam Program Pembinaan Mahasiswa Wirausaha (P2MW) 2024.', '[\"public\\/foto-aktivitas\\/68fae6a024122.jpg\"]', '2025-10-24 09:38:24', '2025-10-24 09:38:24');
INSERT INTO `aktifitas` VALUES (2700, 101, 'DEMODAY & EXPO WIRAUSAHA MERDEKA UMSU 2023', '2023-12-12', 'Selasa, 28 November 2023 di Auditorium UMSU berlangsung kegiatan pembukaan Demoday dan Expo Program Wirausaha Merdeka Universitas Muhammadiyah Sumatera Utara. Kegiatan ini dibuka langsung oleh Bapak Rektor UMSU Prof. Dr. Agussani, M.AP, Ketua Program Wirausaha Merdeka UMSU, dan Kepala Dinas Pendidikan Sekolah Dasar.', '[\"public\\/foto-aktivitas\\/68fae70be3619.jpeg\"]', '2025-10-24 09:40:11', '2025-10-24 09:40:11');
INSERT INTO `aktifitas` VALUES (2701, 101, 'BOOTCAMP WIRAUSAHA MERDEKA UMSU 2023', '2023-11-22', 'Pre Immersion dan Immersion sudah berlalu, tanggal 22-23 November 2023 WMK UMSU melangsungkan Bootcamp outboond di Taman Edukasi Binjai. Kegiatan bootcamp ini termasuk dalam fase Post Immersion. Bootcamp dihadiri oleh dosen pendamping lapangan, tim pelaksana wmk umsu dan dibuka langsung oleh Bapak Wakil Rektor III UMSU.', '[\"public\\/foto-aktivitas\\/68fae76bf198e.jpeg\"]', '2025-10-24 09:41:47', '2025-10-24 09:41:47');
INSERT INTO `aktifitas` VALUES (2702, 101, 'MAHASISWA LAKSANAKAN “ENTREPRENEURIAL PRACTICAL” DI 30 UKM MITRA', '2023-10-04', 'Mahasiswa WMK UMSU melaksanakan magang di 30 UKM Mitra yang berlokasi di Medan sekitarnya. Magang ini berlangsung selama 2 bulan mulai sejak 17 September 2023 lalu hingga 17 November yang akan datang.', '[\"public\\/foto-aktivitas\\/68fae7cb674c1.jpg\"]', '2025-10-24 09:43:23', '2025-10-24 09:43:23');
INSERT INTO `aktifitas` VALUES (2703, 101, 'PELEPASAN MAHASISWA “ENTREPRENEURIAL PRACTICAL” WMK UMSU 2023', '2023-09-18', 'Senin, 18 September 2023 WMK UMSU melakukan pelepasan mahasiswa entrepreneurial practical yang dihadiri oleh mahasiswa dan DPL.\r\nAcara ini dibuka langsung oleh ketua program WMK UMSU.', '[\"public\\/foto-aktivitas\\/68fae81ceb42c.jpg\"]', '2025-10-24 09:44:44', '2025-10-24 09:44:44');
INSERT INTO `aktifitas` VALUES (2704, 101, 'BIMBINGAN TEKNIS LAPORAN KEMAJUAN P2MW 2023', '2023-09-19', '“Bimbingan teknis laporan kemajuan Program Pembinaan Mahasiswa Wirausaha (P2MW) tahun 2023” bersama Bapak Narasumber Dr. Wisnu Sakti Dewobroto, S.T., M.Sc, selaku Tim pengembangan Kewirausahaan Ditjen Belmawa Kemdikbudristek RI dan akan dibuka oleh Bapak WR III UMSU Assoc. Prof. Dr. Rudianto, S.Sos., M.Si. Adapun moderator pada kegiatan kali ini yaitu Ibu Mutia Arda, S.E., M.Si, yang merupakan Anggota PUSKIIBI dan Pendamping terbaik KMI EXPO 2022.\r\n\r\nWaktu pelaksanaan di hari Selasa, 19 September 2023 pukul 09.00 wib s.d. selesai via Zoom meeting.', '[\"public\\/foto-aktivitas\\/68fae8b538621.jpg\"]', '2025-10-24 09:47:17', '2025-10-24 09:47:17');
INSERT INTO `aktifitas` VALUES (2705, 101, 'Opening Ceremony Program Wirausaha Merdeka UMSU 2023', '2023-08-07', 'Opening Ceremony Program Wirausaha Merdeka Angkatan 2 Tahun 2023 “Smart Entrepreneurship” Society, Meaningful, Adaptive, Rich, Technology based” berlangsung pada Senin, 7 Agustus 2023 pada pukul 09.00 WIB di Aula Gedung G. Kegiatan ini dilaporkan langsung oleh Ketua Program WMK sekaligus Ketua PUSKIIBI yaitu Ibu Assoc. Prof. Dewi Andriany, S.E., M.M, dibuka oleh Bapak Wakil Rektor III UMSU yaitu Bapak Assoc. Prof. Dr. Rudianto, M.Si. Kegiatan ini juga menghadirkan Narasumber yang sangat berpengalaman di bidang wirausaha dari Universitas Prasetia Mulya yaitu Bapak M. Setiawan Kusmulyono atau sering dipanggil Pak Kelly.', '[\"public\\/foto-aktivitas\\/68fae917b7e51.jpg\"]', '2025-10-24 09:48:55', '2025-10-24 09:48:55');
INSERT INTO `aktifitas` VALUES (2706, 101, 'PELATIHAN BUSINESS PLAN & BUSINESS MODEL CANVAS UNTUK MAHASISWA P2MW', '2023-07-21', 'Pelatihan business plan dan bmc ini membahas isian bab yang ada dalam proposal bisnis sehingga mahasiswa dapat membuat rancangan bisnis yang baik dan benar.\r\n\r\nAcara ini dibuka oleh ibu ketua puskiibi yakni Assoc. Prof. Dewi Andriany, S.E., M.M …. serta ibu wakil ketua puskiibi yakni Assoc. Prof. ir. Gustina Siregar, M.Si. Adapun yang menjadi narasumber dalam pelatihan ini adalah Bapak Yuda Ardiansyah, S.P., M.P, ….. dan Ibu Assoc. Prof. Dewi Andriany, S.E., M.M.\r\n\r\nDalam pelatihan business plan dan bmc tahap pertama ini dihadiri sebanyak 80 mahasiswa yang berasal dari berbagai tim dari P2MW 2023.', '[\"public\\/foto-aktivitas\\/68fae98f3b343.jpg\"]', '2025-10-24 09:50:55', '2025-10-24 09:50:55');
INSERT INTO `aktifitas` VALUES (2707, 101, 'SILATURAHIM DAN PEMBEKALAN PEMENANG PROGRAM PEMBINAAN MAHASISWA WIRAUSAHA (P2MW) 2023', '2023-07-05', 'Pusat Kewirausahaan Inovasi dan Inkubator Bisnis (PUSKIIBI) Universitas Muhammadiyah Sumatera Utara (UMSU) mengadakan silahturahmi dan pembekalan mahasiswa Pemenang Program Pembinaan Mahasiswa Wirausaha (P2MW) 2023 yang diadakan di Gedung Aula FKIP pda hari Rabu tanggal 05 Juli 2023.  Pada acara ini turut dihadiri oleh Wakil Rektor III bagian kemahasiswaan Dr. Rudianto, M.Si, para pimpinan fakultas Universitas Muhammadiyah Sumatera Utara (UMSU), Ketua PUSKIIBI dan jajarannya, dan para mahasiswa pemenang program P2MW.', '[\"public\\/foto-aktivitas\\/68faea3ac6d86.jpg\"]', '2025-10-24 09:53:46', '2025-10-24 09:53:46');
INSERT INTO `aktifitas` VALUES (2708, 101, 'PUSKIIBI UMSU selenggarakan Bedah Proposal P2MW 2023', '2023-03-04', 'Kegiatan “Bedah Proposal Program Pembinaan Mahasiswa Wirausaha (P2MW) 2023” yang dilaksanakan pada Sabtu, 4 Maret 2023 di Gedung Aula Pertanian.', '[\"public\\/foto-aktivitas\\/68faeaa8375bd.jpeg\"]', '2025-10-24 09:55:36', '2025-10-24 09:55:36');
INSERT INTO `aktifitas` VALUES (2709, 101, 'UMSU Jadi Tuan Rumah Monev KBMI 2019', '2019-11-08', 'UMSU menjadi tuan rumah penyelenggaraan Monitoring dan Evaluasi  Kompetisi Bisnis Mahasiswa Indonesia (Monev KBMI) Tahun 2019 dari Kementrian Pendidikan & Kebudayaan. Monev KBMI tersebut diikuti oleh 17 peserta dari berbagai universitas di Sumut yang menerima hibah KBMI tahun 2019.\r\n\r\nHadir sebagai reviewer dan memberikan penilaian serta masukan terhadap produk wirausaha peserta KBMI Yon Sugiarto S.Si., M.Sc dari Institut Pertanian Bogor serta perwakilan dari Kemendikbud RI Agus nugrahma\r\n\r\nMonev yang dilaksanakan di ikuti oleh Mahasiswa dari berbagai Perguruan TInggi yang ada di Sumatera Utara, UMSU sendiri adalah Peserta terbanyak untuk seluruh Perguruan Tinggi yang ada di Sumatera Utara, yaitu sebanyak 5 proposal.', '[\"public\\/foto-aktivitas\\/68fb088320dac.jpeg\"]', '2025-10-24 12:02:59', '2025-10-24 12:02:59');
INSERT INTO `aktifitas` VALUES (2710, 101, 'EXPO Kewirausahaan Mahasiswa Indonesia (KMI) 2019 Nasional di Batam', '2019-11-25', '5 kelompok KBMI UMSU 2019 lolos dalam EXPO KMI 2019 yang diadakan pada:\r\n\r\n \r\n\r\nHari, tanggal   :  Jumat-Minggu,22-24 November 2019.\r\n\r\nWaktu             : 08.00 wib – selesai\r\n\r\nTempat            :  Politeknik Negeri Batam\r\n\r\nPada acara ini dilakukan KMI Awards 2019 untuk memilih produk/ jasa terbaik berdasarkan 5 kategori, yaitu makanan & minuman, jasa & perdagangan, produksi/ budidaya, teknologi, kreatif.', '[\"public\\/foto-aktivitas\\/68fb08fb52391.jpeg\"]', '2025-10-24 12:04:59', '2025-10-24 12:04:59');
INSERT INTO `aktifitas` VALUES (2711, 101, 'PUSKIIBI UMSU GELAR PELATIHAN BUSINESS PLAN & BMC BAGI MAHASISWA', '2019-10-23', 'PUSKIIBI memberikan pelatihan business plan & business model canvass kepada mahasiswa UMSU.\r\n\r\nKegiatan ini dilaksanakan pada 23 oktober 2019 di aula fkip umsu. Pelatihan business plan & bmc ini merupakan kegiatan reguler yang diadakan puskiibi dalam rangka membantu para mahasiswa umsu untuk mempersiapkan uji kompetensi kewirausahaan.\r\n\r\nPelatihan business plan dan bmc ini membahas isian bab yang ada dalam proposal bisnis sehingga mahasiswa dapat membuat rancangan bisnis yang baik dan benar.\r\n\r\nAcara ini dibuka oleh ibu wakil ketua puskiibi yakni Ir. Gustina Siregar …. serta ibu sekretaris puskiibi yakni Lila bismala, ST, M.Si. Adapun yang menjadi narasumber dalam pelatihan ini adalah Bapak Yuda Ardiansyah, ST, ….. dan Ibu Mutia Arda, SE, M.Si.\r\n\r\nDalam pelatihan business plan dan bmc tahap pertama ini dihadiri sebanyak 35 mahasiswa yang berasal dari FEB, FP, FKIP, dan FAI.', '[\"public\\/foto-aktivitas\\/68fb096de45cf.jpeg\"]', '2025-10-24 12:06:53', '2025-10-24 12:06:53');
INSERT INTO `aktifitas` VALUES (2712, 101, 'SEMINAR NASIONAL KEWIRAUSAHAAN & CALL PAPER 2019', '2019-10-05', 'Fakultas Ekonomi dan Bisnis Universitas Muhammadiyah Sumatera Utara bersama dengan Pusat Kewirausahaan, Inovasi dan Inkubator Bisnis Universitas Muhammadiyah Sumatera Utara telah menyelenggarakan Seminar Nasional Kewirausahaan tahun 2019 dengan tema “Bisnis Generasi Milenial Pada Era Revolusi 4.0” yang diadakan pada:\r\n\r\nHari/tanggal:   Sabtu, 5 Oktober 2019\r\n\r\nTempat:           Auditorium Universitas Muhammadiyah Sumatera Utara', '[\"public\\/foto-aktivitas\\/68fb0a4d9e569.png\"]', '2025-10-24 12:10:37', '2025-10-24 12:10:37');
INSERT INTO `aktifitas` VALUES (2713, 101, 'Pelatihan Social Business Model Canvas (SBMC) dari British Council', '2019-10-04', 'merupakan bentuk kolaborasi yang dijalin PUKSIIBI UMSU dengan British Council untuk pengembangan tenan yang dibina PUSKIIBI dalam menentukan sistem bisnis yang tepat dan bermanfaat sehingga tidak hanya bermanfaat bagi produsen dan konsumen tetapi juga untuk lingkungan sekitar di lokasi produksi, diadakan di AULA FKIP UMSU pada tanggal 04 Oktober 2019. Pelatihan ini mendatangkan pembicara dari British Council langsung yaitu Dr Dwi Indra Purnomo, STP. M.T seorang Creativepreneur dan Technopreneur serta seorang dosen di Universitas Padjajaran. Kegiatan ini dibuka langsung oleh Wakil Rektor III UMSU yaitu Dr. Rudianto, M,Si bersama dengan ketua PUSKIIBI UMSU Dewi Andriany, S.E., M.M. Pelatihan ini mengusung tema Sosial Binis Model Canvas (SBMC) dan Technic Pitching yang diikuti sebanyak 15 tim yang terdiri dari penerima hibah KBMI 2019, penerima dana Program Kreativitas Mahasiswa (PKM) 2018  pendanaan 2019,serta mahasiswa UMSU yang telah menjadi pengusaha kecil. Kegiatan dilakukan sebanyak 2 sesi yaitu Sesi pertama dimulai pada pukul 09.00-12.00 WIB, mahasiswa diberikan pengetahuan dan motivasi mengenai usaha yang dibuat tidak hanya memberikan keuntungan bagi pemilik usaha dan laku dipasaran saja tetapi juga harus berempati pada lingkungan sekitar dan memberikan manfaat yang berkelanjutan sehingga masalah yang dihadapi oleh masyarakat di lingkungan tersebut dapat terselesaikan. Sesi kedua dimulai pada pukul 14.00-17.00, praktek penentuan data dan informasi yang terdapat pada SBMC mulai dari Customer Segment sampai Revenue Stream. Hasil dari pelatihan ini adalah tenan menjadi mengerti dalam menentukan strategi agar produk mereka laku dan profit bagus tetapi dapat memberikan manfaat bagi lingkungan masyarakat sekitar. Pelatihan ini akan di follow up kembali untuk dievaluasi perkembangan lebih lanjut.', '[\"public\\/foto-aktivitas\\/68fb0b1768e49.jpeg\"]', '2025-10-24 12:13:59', '2025-10-24 12:13:59');
INSERT INTO `aktifitas` VALUES (2714, 101, 'Tokopedia Ajak Mahasiswa UMSU Kembangkan Bisnis Digital', '2019-09-27', 'Tokopedia class jilid II ini merupakan lanjutan kegiatan sebelumnya tetapi dengan peserta yang berbeda, karena tokopedia yang pertama memberikan efek yang sangat bagus bagi peserta sebelumnya sehingga banyak mahasiswa UMSU yang produknya sudah ada tetapi perlu pengembangan lebih lanjut, ingin mendapatkan pengalaman dan tips dan trik serta strategi yang sama, dan kali ini tema yang dibuat adalah “Sukses Berwirausaha di Marketplace”. Kegiatan ini dibuka langsung oleh Wakil rektor III UMSU Dr. Rudianto, S.Sos., M.Si di dampingi ketua PUSKIIBI Dew Andriany, S.E., M.M beserta seluruh jajaran pengurus di Aula FKIP pada tanggal 27 September 2019 pukul 09.00-12.00 WIB. Acara ini juga sangat sukses berjalan karena antusias peserta sangat baik dan pihak tokopedia membawa langsung alat sederhana berupa kotak kecil dengan lampu untuk pengambilan foto yang bagus untuk ditampilkan pada toko yang dibuat di Tokopedia.', '[\"public\\/foto-aktivitas\\/68fb0bb49db7e.jpeg\"]', '2025-10-24 12:16:36', '2025-10-24 12:16:36');
INSERT INTO `aktifitas` VALUES (2715, 101, 'MONEV INTERNAL KBMI 2019 DAN SITE VISIT PUSKIIBI UMSU', '2019-09-20', 'Internal visit merupakan kegiatan monitoring yang dilakukan oleh Tim Reviewer Internal PUSKIIBI didampingi oleh Dosen Pembimbing terhadap mahaiswa pemenang Hibah KBMI dari KEMENRITEKDIKTI pada tahun 2019 dengan jumlah pemenang sebanyak 6 tim. Kegiatan ini dilakukan 1 bulan setelah pemenang mendapatkan dana dan telah memulai produksi serta penjualan tepatnya pada tanggal 19 September 2019. Monev ini bertujuan untuk melihat langsung kegiatan yang sedang dilakukan oleh mahasiswa serta dapat langsung berdiskusi mengenai kendala apa saja yang dihadapi selama proses produksi dan pemasaran sehingga mahasiswa dapat secara langsung mendapat solusi dari Reviewer dan PUSKIIBI agar dapat langsung ditindaklanjuti untuk kemudahan dan kelancaran kegiatan selanjutnya. Dalam kegiatan ini tim Reviewer dan PUSKIIBI mengunjungi 6 lokasi satu persatu mulai dari Stabat (Langkat), Sunggal (Deli Serdang), dan sekitaran kota Medan dalam 2 hari.', '[\"public\\/foto-aktivitas\\/68fb0c1f0dc73.jpeg\"]', '2025-10-24 12:18:23', '2025-10-24 12:18:23');
INSERT INTO `aktifitas` VALUES (2716, 101, 'Tokopedia Class Bersama Mahasiswa UMSU', '2019-09-16', 'Tokopedia class merupakan hasil kerjasama PUSKIIBI dibawah pimpinan Dewi Andriany S.E, M.M  dengan Tokopedia untuk mengajarkan mahasiswa untuk memasuki pasar digital. Kegiatan ini diikuti oleh 30 orang mahasiswa terdiri dari mahasiswa pemenang KBMI, tenan yang dibina PUSKIIBI dan mahasiswa calon tenan yang telah memilki usaha tetapi perlu adanya pengembangan. Pembicara acara ini lansung diberikan oleh Pihak Tokopedia yaitu Wiwid Sugiarty selaku pimpinan  Tokopedia Regional Medan. Peserta sangat antusias dalam mengikuti acara ini karena mereka dibekali oleh pembicara mengenai bagaimana cara membuka toko di pasar digital mulai dari pembuatan judul produk yang menarik agar pembeli tertarik, pengambilan foto produk yang sesuai dengan standar digital marketing serta penentuan harga yang tepat sesuai dengan selera konsumen. Selain itu peserta juga mendapatkan pengetahuan mengenai bagaimana strategi agar produk selalu terlihat diurutan pertama ketika pembeli mengetik jenis barang pada form pencaraian produk pada aplikasi tersebut agar selalu terlihat oleh pembeli. Pihak Tokopedia juga memotivasi peserta agar selalu mengembangkan produk dan akan memberikan pelatihan khusus bagi peserta yang selalu update produk dan penjualan di Tokopedia. Kegiatan ini dilakukan di Aula FKIP pada tanggal 16 September 2019 pukul 14.00-16.00 WIB', '[\"public\\/foto-aktivitas\\/68fb115b7106b.jpeg\"]', '2025-10-24 12:40:43', '2025-10-24 12:40:43');
INSERT INTO `aktifitas` VALUES (2717, 101, 'UMSU Menyelenggarakan Pelatihan Marketing Studi untuk Mahasiswa Wirausaha', '2020-12-07', 'elatihan Manajemen Pemasaranini dilakukan pada hari Senin, 7 Desember 2020, pada pukul 14.00 sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Raihanah Daulay, S.E, M.Si, yang memiliki keahlian di bidang Manajemen Pemasaran.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nStrategi pemasaran yang efektif\r\nSegmentasi dan cara menentukan segmentasi pasar\r\nTargetting dan cara menentukan target pasar', '[\"public\\/foto-aktivitas\\/68fb11efc4003.png\"]', '2025-10-24 12:43:11', '2025-10-24 12:43:11');
INSERT INTO `aktifitas` VALUES (2718, 101, 'Mahasiswa UMSU Mengikuti Pelatihan Manajemen Keuangan yang Dilaksanakan oleh PUSKIIBI UMSU', '2020-12-08', 'Salah satu kelemahan pelaku usaha adalah manajemen keuangan, karena kebanyakan mereka tidak mampu melakukan pembukuan dan pengelolaan keuangan secara sistematis.  Kelemahan ini menyebabkan pelaku usaha tidak mengetahui perkembangan usahanya.  Maka pelatihan manajemen keuangan merupakan salah satu solusi untuk mengatasi masalah ini.\r\n\r\nPelatihan Manajemen keuangan  ini dilakukan pada hari Selasa, 8 Desember 2020, pada pukul 09.00 sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Henny Zurika Lubis, S.E, M.Si, yang memiliki keahlian di bidang Manajemen Keuangan.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nAnalisis Break Even Point\r\nPerhitungan harga pokok produksi\r\nNeraca\r\nCash flow\r\nPerhitungan pay back period\r\nPeserta dalam acara ini adalah mahasiswa tenant PUSKIIBI, sebanyak 30 orang, dan dalam pelatihan ini mereka memahami bagaimana melakukan manajemen keuangan yang efektif dalam usahanya, sehingga pencatatan keuangan dapat dilakukan secara sistematis dan mampu mengetahui perkembangan usaha.', '[\"public\\/foto-aktivitas\\/68fb1250d789b.jpeg\"]', '2025-10-24 12:44:48', '2025-10-24 12:44:48');
INSERT INTO `aktifitas` VALUES (2719, 101, 'PUSKIIBI UMSU Melakukan Audiensi ke Dinas Koperasi dan UKM Propinsi Sumatera Utara Terkait Penyuluhan Tentang Pendirian Koperasi', '2020-12-08', 'Salah satu luaran dari Gerakan Revolusi Mental, Indonesia Mandiri adalah mendirikan koperasi di lingkungan Universitas Muhammadiyah Sumatera Utara.  Namun sebelumnya, tim pelaksana melakukan kunjungan ke Dinas Koperasi dan UKM Propinsi Sumatera Utara untuk mendapatkan informasi tentang prosedur dan mekanisme pendirian koperasi dimaksud.  Adapun kegiatan ke Dinas Koperasi dan UKM Propinsi Sumatera Utara ini dilakukan oleh Ketua PUSKIIBI UMSU sekaligus Penanggung Jawab Program Indonesia Mandiri, Assoc Prof. Dewi Andriany, S.E, M.M, yang didampingi oleh Ir. Gustina Siregar, M.Si dan Lila Bismala, S.T, M.Si.  dari kunjungan yang dilakukan pada hari Selasa, 8 Desember 2020, pukul 09.00, diperoleh informasi bahwa sebelum dilakukan pendirian koperasi, maka pihak Dinas Koperasi dan UKM Propinsi Sumatera Utara akan melakukan penyuluhan kepada seluruh calon anggota koperasi.  Di samping itu, koperasi harus menyusun AD/ ART koperasi.  Dari pertemuan tersebut, petugas dari Dinas Koperasi dan UKM Propinsi Sumatera Utara menjadwalkan akan melakukan penyuluhan pada hari Senin, 14 Desember 2020 di kampus Universitas Muhammadiyah Sumatera Utara.', '[\"public\\/foto-aktivitas\\/68fb12a38c25f.png\"]', '2025-10-24 12:46:11', '2025-10-24 12:46:11');
INSERT INTO `aktifitas` VALUES (2720, 101, 'Mahasiswa UMSU Mengikuti Pelatihan Manajemen Produksi Yang Dilaksanakan Oleh PUSKIIBI UMSU', '2020-12-07', 'Pelaku usaha membutuhkan ilmu pengetahuan tentang manajemen produksi, karena berkaitan dengan kapasitas produksi, tata letak, manajemen mutu dan lingkungan fisik kerja.  Untuk itu, salah satu program dalam Gerakan Revolusi Mental adalah pelatihan manajemen produksi. Pelatihan Manajemen Produksi ini dilakukan pada hari Senin, 7 Desember 2020, pada pukul 09.00 sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Lila Bismala, S.T, M.Si, yang memiliki keahlian di bidang Manajemen Produksi.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nSystem produksi secara umum\r\nDampak system produksi terhadap tata letak/ lay out\r\nCara membuat peta proses operasi dan manfaatnya\r\nManajemen mutu\r\n5S/ 5R dalam tempat kerja dan langkah-langkahnya\r\nPeserta dalam acara ini adalah mahasiswa tenant PUSKIIBI, sebanyak 30 orang, dan dalam pelatihan ini mereka memahami bagaimana mengimplementasikan manajemen produksi dalam usahanya.', '[\"public\\/foto-aktivitas\\/68fb12f0b33c4.png\"]', '2025-10-24 12:47:28', '2025-10-25 09:39:52');
INSERT INTO `aktifitas` VALUES (2721, 101, 'UMSU Selenggarakan Pelatihan Bussiness Model Canvas Bagi Mahasiswa Wirausaha', '2020-12-05', 'Business model canvas merupakan gambaran keadaan bisnis yang disusun dalam sebuah peta/ matriks, dalam 9 kolom.  BMC ini sangat diperlukan oleh wirausaha, karena menggambarkan siapa konsumen yang sebenarnya, sumber daya yang dimiliki, keunggulan yang dimiliki, dan aspek-aspek lain yang dimiliki oleh bisnis.  Keterbatasan dalam penyusunan BMC ini, maka diperlukan pelatihan penyusunan BMC.\r\n\r\nPelatihan penyusunan Business Model Canvas  (BMC) ini dilakukan pada hari Sabtu, 5 Desember 2020, pada pukul 14.00 sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Ir. Gustina Siregar, M.Si, yang memiliki keahlian di bidang penyusunan Business Model Canvas.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nApa yang dimaksud dengan BMC\r\nElemen-elemen dalam BMC dan bagaimana menyusun dan mengidentifikasi elemen-elemen tersebut\r\nPeserta dalam acara ini adalah mahasiswa tenant PUSKIIBI, sebanyak 30 orang, dan dalam pelatihan ini melakukan penyusunan BMC untuk bisnis yang dijalaninya.', '[\"public\\/foto-aktivitas\\/68fb133172f1b.png\"]', '2025-10-24 12:48:33', '2025-10-24 12:48:33');
INSERT INTO `aktifitas` VALUES (2722, 101, 'UMSU Selenggarakan Pelatihan Bisnis Plan Bagi Mahasiswa Wirausaha', '2020-12-05', 'Bisnis plan merupakan suatu dokumen perencanaan bisnis yang diperlukan oleh wirausaha, yang menunjukkan ketersediaan sumber daya dan perencanaan ke depan.  Bisnis plan juga dapat digunakan untuk dapat memperoleh pendanaan dari pihak ketiga.  Seringkali mahasiswa tidak memiliki kemampuan dalam menyusun bisnis plan, sehingga pelatihan penyusunan bisnis plan sangat diperlukan oleh mahasiswa.\r\n\r\nPelatihan penyusunan Bisnis Plan ini dilakukan pada hari Sabtu, 5 Desember 2020, pada pukul 09.00 sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Yudha Andriansyah Putra, S.P, M.P, yang memiliki keahlian di bidang penyusunan Bisnis Plan.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nPoin-poin yang harus dijelaskan dalam bisnis plan\r\nBagaimana ide dasar, menentukan nama usaha\r\nMembuat analisis produk\r\nMelakukan analisis pasar dan strategi pemasaran\r\nAspek produksi dan operasional\r\nManajemen sumber daya manusia\r\nAspek keuangan\r\nPeserta dalam acara ini adalah mahasiswa tenant PUSKIIBI, sebanyak 30 orang, dan dalam pelatihan ini melakukan penyusunan Bisnis Plan sederhana untuk produknya.', '[\"public\\/foto-aktivitas\\/68fb137a3a422.png\"]', '2025-10-24 12:49:46', '2025-10-24 12:49:46');
INSERT INTO `aktifitas` VALUES (2723, 101, 'PUSKIIBI UMSU Peserta Pelatihan oleh GOOGLE', '2020-02-22', 'USKIIBI UMSU mendampingi mahasiswa dalam womenwill, pelatihan yang diadakan oleh google dalam mengembangkan usaha yang difokuskan pada wanita.  Acara ini diselenggarakan pada hari Sabtu  tanggal 22 Februari 2019, pukul  09.00 s/d selesai, bertempat  Ruang Semar Swiss Bell Inn Medan, Jl. Surabaya Ketua PUSKIIBI, Dewi Andriany, S.E, M.M memberikan sambutan sekaligus motivasi kepada mahasiswa UMSU yang mengikuti acara ini.  Acara ini dihadiri 50 mahasiswa UMSU sebagai peserta. Narasumber pada kesempatan ini adalah Qonitah Azzahra', '[\"public\\/foto-aktivitas\\/68fb13cfbe4a6.jpeg\"]', '2025-10-24 12:51:11', '2025-10-24 12:51:11');
INSERT INTO `aktifitas` VALUES (2724, 101, 'PUSKIIBI UMSU mengadakan Seminar dan Workshop Syariahpreneur', '2020-02-10', 'PUSKIIBI mengadakan Seminar dan Workshop Syariahpreneur.  Selama  ini system Syariah dalam kewirausahaan hanyalah slogan tanpa dipraktekkan, sehingga diperlukan pelatihan dan workshop untuk menguatkan implementasi Syariahpreneur tersebut.  Kegiatan syariahpreneur bagi mahasiswa ini akan diselenggarakan selama 2 (dua) hari pada:\r\n\r\nHari/ tanggal   : Senin, 10 Februari 2020\r\n\r\nWaktu             : 09.00 s/d selesai\r\n\r\nTempat            : Auditorium UMSU\r\n\r\nHari/ tanggal   : Rabu, 12 Februari 2020\r\n\r\nWaktu             : 09.00 s/d selesai\r\n\r\nTempat            : Ruang BPM Lt 2. Gedung FAI UMSU\r\n\r\nPada kesempatan ini Wakil Rektor III UMSU. DR. Rudianto, S.Sos, M.Si membuka acara sekaligus memberikan paparan sebagai Keynote Speaker.  Beliau menyatakan bahwa perkembangan teknologi informasi menuntut wirausaha untuk dapat kreatif dalam menciptakan dan mempromosikan produk.  Narasumber pada acara ini adalah M. Imron Farhani dan Ir. Abdul Kadir, yang memperkenalkan system digital networking.\r\n\r\nAcara ini dihadiri oleh 170 mahasiswa UMSU dari berbagai fakultas yang ada.', '[\"public\\/foto-aktivitas\\/68fb142b76579.png\"]', '2025-10-24 12:52:43', '2025-10-24 12:52:43');
INSERT INTO `aktifitas` VALUES (2725, 101, 'PUSKIIBI UMSU menerima kunjungan dari British Council (DICE)', '2020-02-10', 'PUSKIIBI menerima kunjungan dari British Council (DICE) pada hari Senin, 10 Februari 2020, jam 14.00 di ruang PUSKIIBI\r\n\r\nPUSKIIBI telah memperoleh kesempatan untuk menjadi peserta TOT dari DICE yang diadakan oleh British Council beberapa waktu lalu.  Untuk itu DICE ingin melakukan studi kasus di Indonesia tentang incubator bisnis yang menjalankan social entrepreneurship.  Dalam kesempatan ini, DICE memilih UMSU sebagai representasi dari perguruan tinggi swasta dan ITB sebagai perwakilan dari perguruan tinggi negeri.  Beberapa pertanyaan yang diajukan meliputi jumlah tenant, bagaimana prosedur rekrutmen, bagaimana dan apa saja ruang lingkup pendampingan yang dilakukan, perkembangan yang diperoleh tenant.', '[\"public\\/foto-aktivitas\\/68fb148f95d9a.png\"]', '2025-10-24 12:54:23', '2025-10-24 12:54:23');
INSERT INTO `aktifitas` VALUES (2726, 101, 'PUSKIIBI UMSU memberikan Penyuluhan Kepada Masyarakat Kabupaten Langkat', '2019-12-21', 'IMM Fakultas Ekonomi dan Bisnis melakukan program pengabdian kepada masyarakat dan meminta kesediaan PUSKIIBI dalam program penyuluhan kewirausahaan di Kabupaten Langkat.\r\n\r\nKegiatan ini dihadiri oleh ketua PUSKIIBI, Hj Dewi Andriany, S.E, M.M, didampingi oleh wakil ketua Ir. Gustina Siregar, M.Si dan sekretaris PUSKIIBI Lila Bismala, S.T, M.Si serta staff PUSKIIBI Zulfahmi Matondang, S.E.\r\n\r\nKegiatan ini diadakan pada hari Selasa,  tanggal       21 Desember 2019\r\n\r\nAdapun materi yang disampaikan meliputi bagaimana melakukan packaging sehingga produk yang dijual menarik minat konsumen.  Di samping itu narasumber menyarankan agar masyarakat membentuk kelompok sehingga memiliki standarisasi produk yang akan dijual.', '[\"public\\/foto-aktivitas\\/68fb14f0da0a0.png\"]', '2025-10-24 12:56:00', '2025-10-24 12:56:00');
INSERT INTO `aktifitas` VALUES (2727, 482, 'INKUBASI BISNIS', '2025-10-23', 'Kurasi UMKM dalam kegiatan  Inkubasi Bisnis yang di selenggarakan oleh Dinas Koperasi Usaha Kecil dan Menengah Provinsi Banten, Lembaga Inkubator PLUT Banten dan Lembaga Inkubator Pro Link Tanggal 23- 26 September 2025.', '[\"public\\/foto-aktivitas\\/68fb29ce15eca.jpg\",\"public\\/foto-aktivitas\\/68fb29ce16106.jpg\",\"public\\/foto-aktivitas\\/68fb29ce16204.jpg\",\"public\\/foto-aktivitas\\/68fb29ce162df.jpg\"]', '2025-10-24 14:06:41', '2025-10-24 14:25:02');
INSERT INTO `aktifitas` VALUES (2728, 101, 'PUSKIIBI UMSU Melakukan Rapat Pembentukan Koperasi Mahasiswa Bersama Dinas Koperasi dan UKM Propinsi Sumatera Utara', '2020-12-14', 'Luaran yang diharapkan selain peningkatan kemampuan dan pengetahuan peserta dalam program Revolusi Mental ini adalah pembentukan koperasi di lingkungan kampus Universitas Muhammadiyah Sumatera Utara.  Setelah sebelumnya, tim pelaksana mengadakan audiensi dengan pihak Dinas Koperasi dan UKM tentang prosedur pendirian koperasi, maka tahap selanjutnya adalah menyelenggarakan penyuluhan oleh Dinas Koperasi dan UKM Propinsi, yang dihadiri oleh calon anggota koperasi.  Acara ini diadakan pada hari Senin, 14 Desember 2020, pukul 14.00 sampai dengan selesai.', '[\"public\\/foto-aktivitas\\/68fb41e7b2e65.png\"]', '2025-10-24 16:07:51', '2025-10-24 16:07:51');
INSERT INTO `aktifitas` VALUES (2729, 101, 'Sosialisasi Program Kewirausahaan Mahasiswa Indonesia Nasional Tahun 2021', '2021-02-08', 'Kementerian Pendidikan dan Kebudayaan melalui Direktorat Pembelajaran dan Kemahasiswaan, Direktorat Jenderal Pendidikan Tinggi terus berupaya mengembangkan dan memperbanyak jumlah mahasiswa wirausaha. Hal ini dilakukan dengan adanya Program Kewirausahaan Mahasiswa Indonesia (PKMI), yang dilakukan setiap tahun. Karena PKMI 2021 akan dimulai, maka Kementerian Pendidikan dan Kebudayaan melalui Direktorat Pembelajaran dan Kemahasiswaan, Direktorat Jenderal Pendidikan Tinggi mengadakan sosialisasi panduan PKMI 2021. Kegiatan ini dilakukan pada hari Senin 8 Februari 2021, mulai pukul 09.00 sampai dengan selesai, dan diadakan secara daring.\r\n\r\nProgram Kewirausahaan 2021 memiliki 4 kegiatan unggulan yaitu Workshop Kewirausahaan, Kegiatan Berwirausaha Mahasiwa Indonesia (KBMI), Akselerasi Startup Mahasiswa Indonesia (ASMI) dan Pendampingan Kewirausahaan Mahasiswa Indonesia (PWMI). KBMI ditujukan untuk mahasiswa yang memerlukan stimulasi dana pengembangan usaha dan ASMI ditujukan bagi mahasiswa yang memiliki startup digital dan memerlukan akselerasi usahanya ke tahap lanjut.', '[\"public\\/foto-aktivitas\\/68fb426430d42.png\"]', '2025-10-24 16:09:56', '2025-10-24 16:09:56');
INSERT INTO `aktifitas` VALUES (2730, 101, 'UMSU Menyelenggarakan Kompetisi Produk Kreatif untuk Mahasiswa Wirausaha', '2020-12-14', 'Kreatifitas mahasiswa dalam menciptakan produk kreatif sangat penting dalam menciptakan peluang usaha.  Hal penting untuk menumbuhkan kreatifitas mahasiswa dalam menciptakan produk adalah dengan mengadakan kompetisi produk kreatif.  Dengan kompetisi ini, diharapkan produk kreatif yang muncul dapat dikomersialisasi dan diproduksi secara massal.  Kompetisi produk kreatif  ini diadakan pada hari Senin, 14 Desember 2020, pukul 09.00.  Adapun juri dalam kegiatan ini adalah Yusrita, S.E, M.Si dan Ratna Sari, S.H.  Acara ini diikuti oleh 30 kelompok mahasiswa.  Di mana tahap awal adalah mahasiswa mengirimkan foto produk kepada panitia, untuk kemudian diseleksi. Dan pada tahap final mereka menunjukkan produknya di hadapan tim juri.  Adapun pemenang kompetisi produk kreatif adalah:\r\n\r\nJuara 1. Kost art\r\n\r\nJuara 2. Global Account\r\n\r\nJuara 3. Siska Gallery', '[\"public\\/foto-aktivitas\\/68fb42ba673f3.png\"]', '2025-10-24 16:11:22', '2025-10-24 16:11:22');
INSERT INTO `aktifitas` VALUES (2731, 101, 'UMSU Menyelenggarakan Kompetisi Bisnis Plan untuk Mahasiswa Wirausaha', '2020-12-12', 'Bisnis plan sebagai sebuah perencanaan bisnis yang menggambarkan keadaan bisnis saat ini maupun ide bisnis yang akan diimplementasikan.  Untuk mengasah lebih kemampuan dalam  pembuatan bisnis plan, maka perlu diadakan kompetisi bisnis plan.  Kegiatan ini diadakan pada hari Jum’at, 12 Desember 2020, pukul 14.00.  Adapun juri dalam kegiatan ini adalah Yusrita, S.E, M.Si dan Ratna Sari, S.H.\r\n\r\nAcara ini diikuti oleh 30 kelompok mahasiswa.  Di mana tahap awal adalah mahasiswa mengirimkan proposal bisnis plan kepada panitia, untuk kemudian diseleksi. Dan pada tahap final mereka mempresentasikannya di hadapan tim juri.  Adapun pemenang kompetisi bisnis plan adalah:\r\n\r\nJuara 1. Rein Dimsum\r\n\r\nJuara 2. My Coffeendo\r\n\r\nJuara 3. Crot de Pomade', '[\"public\\/foto-aktivitas\\/68fb431194aa3.png\"]', '2025-10-24 16:12:49', '2025-10-24 16:12:49');
INSERT INTO `aktifitas` VALUES (2732, 101, 'Pelatihan Digital Marketing Diselenggarakan oleh PUSKIIBI UMSU untuk Mahasiswa Wirausaha', '2020-12-12', 'Di era millennium ini, system dan strategi marketing terus mengalami perkembangan, mengikuti revolusi industry 4.0, di mana saat ini semua sudah menggunakan digital marketing.  Terutama di era pandemic covid 19 dan memasuki era new normal, di mana dilakukan pembatasan fisik dan social, begitupun pelaku usaha, yang saat ini lebih banyak melakukan digital marketing dalam transaksi bisnis.  Mengingat sangat pentingnya digital marketing ini bagi pelaku usaha, maka dalam program Revolusi Mental ini, dilakukan pelatihan digital marketing.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan, dengan narasumber Yoshida Sary, S.Kom, M.Kom yang merupakan ahli di bidang digital marketing.\r\n\r\nDalam pelatihan ini, narasumber memberikan materi tentang:\r\n\r\nPerbedaan marketing secara konvensional dan secara digital\r\nKemudahan dan jangkauan pemasaran dalam digital marketing\r\nMedia-media yang dapat digunakan dalam digital marketing\r\nBagaimana tips dan trik dalam menggunakan digital marketing\r\nSales funnel, tahapan dan mengapa menerapkah sales funnel\r\nKegiatan ini diikuti oleh 30 orang peserta, yaitu mahasiswa.  Karena dampak covid 19 mempengaruhi bisnis, maka digital marketing dapat menjadi solusi jitu strategi pemasaran.', '[\"public\\/foto-aktivitas\\/68fb4367d9f6c.png\"]', '2025-10-24 16:14:15', '2025-10-25 09:40:48');
INSERT INTO `aktifitas` VALUES (2733, 101, 'UMSU Selenggarakan Pelatihan Kerajinan Batok Kelapa Bagi Mahasiswa Wirausaha', '2020-12-11', 'Batok kelapa merupakan limbah, namun dapat dimanfaatkan lebih lanjut sebagai bahan baku kerajinan, jika seseorang memiliki kreatifitas dalam mengolahnya.  Kerajinan berbahan batok kelapa memiliki nilai estetik yang tinggi, dan memiliki nilai jual yang tinggi, dan dapat menghasilkan beraneka ragam barang, seperti tempat tisu, tempat pensil, vas bunga dan aneka ragam barang lainnya.  Hal inilah yang mendasari diadakannya pelatihan kerajinan batok kelapa, yang diadakan pada hari Jum’at, 11 Desember 2020, di pelataran Ruang Pusat Kewirausahaan, Inovasi dan Inkubator Bisnis Universitas Muhammadiyah Sumatera Utara.', '[\"public\\/foto-aktivitas\\/68fb43f489769.png\"]', '2025-10-24 16:16:36', '2025-10-24 16:16:36');
INSERT INTO `aktifitas` VALUES (2734, 101, 'Mahasiswa UMSU Mengikuti Pelatihan Buket Bunga yang Dilaksanakan oleh PUSKIIBI UMSU', '2020-12-11', 'Pelatihan pembuatan produk merupakan hal yang perlu dilakukan sebagai implementasi dari ide kreatif.  Buket bunga banyak diperjual belikan ketika mahasiswa selesai melakukan siding meja hijau skripsi, sehingga hal ini dipandang sebagai sebuah peluang usaha yang dapat dilakukan mahasiswa.  Alasan lain adalah karena mudahnya memperoleh bahan baku dan harga bahan baku yang terjangkau serta proses produksi yang mudah.  Dalam program revolusi mental ini, dilakukan pelatihan membuat kerajinan buket bunga, yang dilakukan pada hari Jum’at, 11 Desember 2020, di Ruang Pusat Kewirausahaan, Inovasi dan Inkubator Bisnis Universitas Muhammadiyah Sumatera Utara.  Adapun narasumber dalam pelatihan ini adalah Susi Handayani, S.E, M.M yang merupakan pelaku usaha buket bunga.  Acara ini diikuti oleh 20 orang mahasiswa yang berminat, dan bermaksud untuk menindaklanjuti hasil pelatihan.', '[\"public\\/foto-aktivitas\\/68fb4472856c7.png\"]', '2025-10-24 16:18:42', '2025-10-24 16:18:42');
INSERT INTO `aktifitas` VALUES (2735, 101, 'UMSU Selenggarakan Pelatihan Inovasi Produk dan Kemasan Produk Bagi Mahasiswa Wirausaha', '2020-12-10', 'Inovasi merupana hal yang sangat penting di era millennium ini.  Jika produk tidak mampu berinovasi, maka produk tersebut kemungkinan besar akan kalah bersaing di pasar.  Demikian pula kemasan produk, yang sering kali menjadi daya tarik bagi konsumen untuk memutuskan perilaku pembelian.  Maka pelatihan inovasi produk dan kemasan produk menjadi salah satu program yang sangat penting dalam program ini.  Pelatihan inovasi produk dan kemasan produk ini dilakukan pada hari Selasa, 10 Desember 2020, pukul 14.00.  Narasumber  dalam kegiatan ini adalah Yudha Andriansyah Putra,S.P, M.P, yang memiliki keahlian di bidang inovasi produk dan kemasan produk.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.\r\n\r\nHal-hal yang disampaikan oleh narasumber dalam pelatihan meliputi:\r\n\r\nDefinisi inovasi dan apa saja yang termasuk inovasi\r\nFungsi kemasan, persyaratan kemasan produk yang disyaratkan\r\nRegulasi terkait kemasan produk', '[\"public\\/foto-aktivitas\\/68fb452cf332f.png\"]', '2025-10-24 16:21:48', '2025-10-24 16:21:48');
INSERT INTO `aktifitas` VALUES (2736, 101, 'Pelatihan Pengurusan Perizinan Di Ikuti Oleh Mahasiswa Wirausaha UMSU', '2020-12-10', 'Beragam usaha yang digeluti oleh mahasiswa wirausaha yang menjadi tenant atau binaan PUSKIIBI, yang tentunya memerlukan perijinan yang beragam.  Mulai dari NIB (nomor induk berusaha), PIRT (Perijinan Industri Rumah Tangga), ijin BPOM, sertifikasi halal dan perijinan lainnya, di mana semua itu memerlukan proses dan prosedur yang berbeda-beda, dan disesuaikan dengan bidang usaha.  Tim pelaksana program memandang bahwa permasalahan perijinan ini sangat penting bagi usaha apapun yang dijalankan, terutama jika ingin mengembangkan usaha.  Untuk itu, tim pelaksana program mengadakan pelatihan pengurusan perijinan, yang dilakukan pada  hari Kamis, 10 Desember 2020, pukul 09.00 s/d selesai.  Adapun narasumber dalam kegiatan ini adalah Ir. Gustina Siregar, M.Si, yang memiliki keahlian di bidang pengurusan perijinan.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.\r\n\r\nDalam pelatihan ini, narasumber menyampaikan hal-hal berikut:\r\n\r\nKeamanan pangan\r\nPerijinan yang diperlukan sesuai dengan bidang usaha yang dijalankan\r\nMasalah-masalah yang ditemui terkait produk pangan\r\nPengelompokan pangan\r\nTata cara penerbitan SPP-IRT dan persyaratannya\r\nPeraturan BPOM\r\nPelatihan ini memberikan manfaat yang cukup  besar, karena peserta memperoleh pemahaman tentang tata cara pengurusan perijinan yang diperlukan.', '[\"public\\/foto-aktivitas\\/68fb45a3e1545.png\"]', '2025-10-24 16:23:47', '2025-10-24 16:23:47');
INSERT INTO `aktifitas` VALUES (2737, 101, 'Mahasiswa UMSU Mengikuti Pelatihan Manajemen Stok Yang Dilaksanakan Oleh PUSKIIBI UMSU', '2020-12-08', 'Pelaku usaha seringkali mengabaikan manajemen stok dan melakukan pembelian bahan baku dalam jumlah besar karena adanya factor diskon.  Sementara hal tersebut menyebabkan penumpukan bahan baku yang tentu juga berdampak pada biaya persediaan, karena harus menyediakan ruangan dan juga perawatan terhadap bahan baku tersebut.  Untuk itu, diperlukan pelatihan tentang manajemen stok, sehingga mahasiswa wirausaha mampu menjaga stok barang dan tidak berlebihan dalam stok, namun tidak akan mengalami kekurangan persediaan ketika permintaan meningkat.\r\n\r\nPelatihan Manajemen stok  ini dilakukan pada hari Selasa, 8 Desember 2020, pada pukul 14.00 sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Lila Bismala, S.T, M.Si, yang memiliki keahlian di bidang Manajemen Stok.  Kegiatan ini dilaksanakan di Gedung F, Lt.2 Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nPentingnya stok dalam proses produksi\r\nJenis-jenis persediaan/ stok yang diperlukan dalam bisnis\r\nBeberapa kesalahan yang sering terjadi ketika melakukan perencanaan kapasitas\r\nSystem manajemen stok\r\nBiaya-biaya yang muncul dalam stok\r\nMetode yang dipergunakan dalam manajemen stok\r\nPelatihan ini diikuti  oleh mahasiswa tenant PUSKIIBI, sejumlah 30 orang.  Pelatihan manajemen stok ini sangat penting karena mempengaruhi biaya persediaan, dan bagaimana pelaku usaha melakukan manajemen stok sehingga tidak terjadi kekurangan atau kelebihan stok yang mempengaruhi biaya produksi.', '[\"public\\/foto-aktivitas\\/68fb45efbe8f3.png\"]', '2025-10-24 16:25:03', '2025-10-24 16:25:03');
INSERT INTO `aktifitas` VALUES (2738, 101, 'Sosialisasi Program Pembinaan Mahasiswa Wirausaha (P2MW) 2022', '2022-05-17', 'Kementerian Pendidikan, Kebudayaan, Riset dan Teknologi terus berupaya mengembangkan dan memperbanyak jumlah mahasiswa wirausaha, dengan mengadakan program P2MW 2022. Kegiatan ini adalah program pengganti dari KBMI (Kegiatan Berwirausaha Mahasiswa Indonesia) 2021. Kegiatan ini akan dibuka pada bulan April-September 2022.  Untuk itu PUSKIIBI  mengadakan sosialisasi kepada mahasiswa seluruh peserta wirausahawan dan dosen tentang program P2MW tersebut.\r\n\r\nKegiatan ini dilakukan secara daring pada:\r\n\r\nHari/ tanggal      : Selasa / 17 Mei 2022\r\n\r\nWaktu                : 09.30 s/d selesai\r\n\r\nTempat               : Daring', '[\"public\\/foto-aktivitas\\/68fb467537c27.png\"]', '2025-10-24 16:27:17', '2025-10-24 16:27:17');
INSERT INTO `aktifitas` VALUES (2739, 101, 'Sosialisasi Dan Pelatihan Dosen Pendamping Dalam Program Merdeka Belajar Kampus Merdeka', '2021-04-01', 'Program Merdeka Belajar Kampus Merdeka sudah mulain diimplementasikan pad tahun 2021 ini.  Di mana salah satu program yang akan dilaksanakan adalah Program Kewirausahaan. Program Kewirausahaan sendiri terdiri dari Implementasi Rencana Bisnis Mahasiswa, Magang Kewirausahaan dan Kegiatan Berwirausaha Mahasiswa Indonesia (KBMI). Untuk kegiatan ini tentunya duperlukan dosen pendamping, yang akan mendampingi dan membimbing Mahasiswa dalam kegiatan kewirausahaan tersebut. Untuk itu, tentunya dosen pendamping harus memiliki kompetensi dan kapabilitas dalam hal kewirausahaan sehingga dapat melaksanakan pendampingan dan pembimbingan dengan optimal.\r\n\r\nUntuk itu, PUSKIIBI memandang perlu untuk melakukan sosialisasi dan pelatihan Dosen Pendamping.  Sosialisasi dimaksudkan agar dosen pendamping memahami tugas, peran dan tanggung jawabnya sebagai dosen pendamping kewirausahaan dalam kegiatan kewirausahaan dalam program MERDEKA BELAJAR KAMPUS MERDEKA. Sementara pelatihan dimaksudkan agar dosen pendamping  memiliki kompetensi dan kapabilitas dalam proses pendampingan dan pembimbingan Mahasiswa yang mengikuti program kewirausahaan dalam program MERDEKA BELAJAR KAMPUS MERDEKA.\r\n\r\nKegiatan ini dilaksanakan pada\r\n\r\nHari/ tanggal   : Kamis, 1 April 2021\r\n\r\nWaktu             : 09.00 s/d  selesai\r\n\r\nKegiatan ini dibuka oleh Wakil Rektor I UMSU, Bapak Dr. M. Arifin, S.H, M.Hum.  Dalam sambutannya, WR I menyatakan bahwa Pelaksanaan MBKM adalah 1 semester, 16 kali pertemuan, Mahasiswa harus didampingi oleh dosen pendamping dan professional, sehingga perlu pemahaman segala aspek kewirausahaan.  Dan diharapkan ada inovasi-inovasi yang akan bermanfaat bagi peningkatan akreditasi.\r\n\r\nDalam paparannya, Ketua PUSKIIBI, Ibu Hj. Dewi Andriany, S.E, M.M, menyampaikan kriteria yang perlu dimiliki oleh seorang dosen pendamping.', '[\"public\\/foto-aktivitas\\/68fb46d49c789.jpg\"]', '2025-10-24 16:28:52', '2025-10-24 16:28:52');
INSERT INTO `aktifitas` VALUES (2740, 1374, 'Kegiatan Persiapan Lembaga Inkubator', '2025-10-21', 'Persiapan Program Kerja Inkubator Studio Spotlight Indonesia', '[\"public\\/foto-aktivitas\\/68fe191b304cf.jpg\"]', '2025-10-26 19:50:35', '2025-10-26 19:50:35');
INSERT INTO `aktifitas` VALUES (2741, 101, 'PELATIHAN BUSINESS PLAN & BUSINESS MODEL CANVAS UNTUK MAHASISWA P2MW', '2023-07-21', 'Pelatihan business plan dan bmc ini membahas isian bab yang ada dalam proposal bisnis sehingga mahasiswa dapat membuat rancangan bisnis yang baik dan benar.\r\n\r\nAcara ini dibuka oleh ibu ketua puskiibi yakni Assoc. Prof. Dewi Andriany, S.E., M.M …. serta ibu wakil ketua puskiibi yakni Assoc. Prof. ir. Gustina Siregar, M.Si. Adapun yang menjadi narasumber dalam pelatihan ini adalah Bapak Yuda Ardiansyah, S.P., M.P, ….. dan Ibu Assoc. Prof. Dewi Andriany, S.E., M.M.\r\n\r\nDalam pelatihan business plan dan bmc tahap pertama ini dihadiri sebanyak 80 mahasiswa yang berasal dari berbagai tim dari P2MW 2023.', '[\"public\\/foto-aktivitas\\/68fefe1520cdb.jpg\"]', '2025-10-27 12:07:33', '2025-10-27 12:07:33');
INSERT INTO `aktifitas` VALUES (2742, 101, 'SOSIALISASI WIRAUSAHA MERDEKA UMSU part II', '2023-07-03', 'Program Wirausaha Merdeka berkolaborasi dengan Perguruan Tinggi Pelaksana Program mengembangkan pembelajaran wirausaha yang mampu mengasah jiwa kewirausahaan, mendorong peningkatan pengalaman wirausaha dan peningkatan kemampuan daya kerja mahasiswa.', '[\"public\\/foto-aktivitas\\/68ff002d8ef31.jpg\"]', '2025-10-27 12:16:29', '2025-10-27 12:16:29');
INSERT INTO `aktifitas` VALUES (2743, 101, 'PUSKIIBI UMSU selenggarakan Sosialisasi dan Pelatihan Business Plan', '2023-01-24', 'Sosialisasi dan Pelatihan Bisnis Plan ini dilakukan pada hari Selasa, 24 Januari 2023, pada pukul 08.30 WIB sampai dengan selesai.  Adapun narasumber dalam kegiatan ini adalah Bapak Yudha Andriansyah Putra, S.P., M.P, dan Ibu Mutia Arda, S.E., M.Si yang memiliki keahlian di bidang penyusunan Bisnis Plan.  Kegiatan ini dilaksanakan di Gedung Aula FEB, Kampus Universitas Muhammadiyah Sumatera Utara, Medan.  Narasumber menjelaskan tentang:\r\n\r\nPoin-poin yang harus dijelaskan dalam bisnis plan\r\nBagaimana ide dasar, menentukan nama usaha\r\nMembuat analisis produk\r\nMelakukan analisis pasar dan strategi pemasaran\r\nAspek produksi dan operasional\r\nManajemen sumber daya manusia\r\nAspek keuangan\r\nPeserta dalam acara ini adalah mahasiswa UMSU yang telah dijaring PUSKIIBI tentang peminatannya di bidang wirausaha sebanyak 40 orang.', '[\"public\\/foto-aktivitas\\/68ff05e097055.jpg\"]', '2025-10-27 12:40:48', '2025-10-27 12:40:48');
INSERT INTO `aktifitas` VALUES (2744, 101, 'TOP 10 NATIONAL BUSINESS PLAN COMPETITION – UICC 2023', '2023-02-20', 'Dalam rangka Milad Universitas Muhammadiyah Sumatera Utara di tahun 2023 ini, UMSU mengadakan event menarik yakni “UMSU INOVATION AND CREATIVITY CARNIVAL (UICC) 2023”.\r\n\r\nUICC ini dibagi menjadi 2 kategori, yakni kategori Universitas se-Indonesia dan SMA/MA, SMK sederajat. Adapun salah satu lomba yang masuk di kategori Universitas yaitu National Business Plan Competition (NBPC).\r\n\r\nPendaftaran NBPC telah dibuka sejak bulan Januari 2023 dan ditutup pada tanggal 20 Februari 2023. Proses seleksi yang terjadi sangatlah kompetitif, karena seluruh proposal yang masuk adalah proposal proposal yang layak untuk di kembangkan menjadi wirausaha tangguh di masa yang akan datang.', '[\"public\\/foto-aktivitas\\/68ff0652f0889.jpg\"]', '2025-10-27 12:42:42', '2025-10-27 12:42:42');
INSERT INTO `aktifitas` VALUES (2745, 101, 'PELAKSANAAN PELAPORAN & PENILAIAN LAPORAN KEMAJUAN PROGRAM IWDM 2022', '2022-10-24', 'Setelah berjalan tiga bulan sejak pengumuman pemenang, KEMDIKBUDRISTEK melakukan Penilaian Laporan Kemajuan Perguruan Tinggi IWDM 2022 pada tanggal 25 Oktober 2022.  Adapun reviewer pada Penilaian pelaporan ini yaitu Bapak Arwan Nur Ramadhan dan Bapak Alamul Huda. Pelaksanaan pelaporan kemajuan ini bertempat di Galeri PUSKIIBI UMSU.', '[\"public\\/foto-aktivitas\\/68ff06e967180.jpg\"]', '2025-10-27 12:45:13', '2025-10-27 12:45:13');
INSERT INTO `aktifitas` VALUES (2746, 101, 'PELAKSANAAN PELAPORAN & PENILAIAN LAPORAN KEMAJUAN PROGRAM PEMBINAAN MAHASISWA WIRAUSAHA (P2MW) 2022', '2022-10-20', 'Setelah berjalan tiga bulan sejak pengumuman pemenang, KEMDIKBUDRISTEK melakukan Penilaian Laporan Kemajuan Perguruan Tinggi P2MW 2022 pada tanggal 20 Oktober 2022.  Adapun reviewer pada Penilaian pelaporan ini yaitu Ibu Dr. Tri Siwi Agustina, S.E., M.Si dan Bapak Hafiz Sezario. Pelaksanaan pelaporan kemajuan ini bertempat di Gedung Aula FEB UMSU. \r\n\r\nPelaksanaan pelaporan ini dibuka langsung oleh Bapak WR III UMSU Bapak Assoc. Prof. Dr. Rudianto, S.Sos., M.Si, di dampingi oleh Ka.BIMAWA UMSU Bapak Radiman, S.E., M.Si, dan dihadiri oleh enam tim pemenang P2MW, pengelola PT, dosen pendamping, mentor serta pengelola PUSKIIBI.', '[\"public\\/foto-aktivitas\\/68ff0750d285c.jpg\"]', '2025-10-27 12:46:56', '2025-10-27 12:46:56');
INSERT INTO `aktifitas` VALUES (2747, 101, 'MONITORING & EVALUASI PROGRAM PEMBINAAN MAHASISWA WIRAUSAHA (P2MW) 2022', '2022-09-22', 'Monev merupakan kegiatan monitoring yang dilakukan oleh Dosen Pembimbing terhadap mahaiswa pemenang Hibah P2MW dari KEMDIKBUDRISTEK pada tahun 2022 dengan jumlah pemenang sebanyak 6 tim. Kegiatan ini dilakukan 1 bulan setelah pemenang mendapatkan dana dan telah memulai produksi serta penjualan tepatnya pada tanggal 29 September 2022. Monev ini bertujuan untuk melihat langsung kegiatan yang sedang dilakukan oleh mahasiswa serta dapat langsung berdiskusi mengenai kendala apa saja yang dihadapi selama proses produksi dan pemasaran sehingga mahasiswa dapat secara langsung mendapat solusi dari Dosen Pembimbing dan tim PUSKIIBI agar dapat langsung ditindaklanjuti untuk kemudahan dan kelancaran kegiatan selanjutnya. Dalam kegiatan ini Dosen pembimbing dan tim PUSKIIBI mengunjungi 6 lokasi satu persatu mulai dari Tanjung Morawa, Binjai, dan sekitaran kota Medan dalam 1 hari.', '[\"public\\/foto-aktivitas\\/68ff07beec157.jpeg\"]', '2025-10-27 12:48:46', '2025-10-27 12:48:46');
INSERT INTO `aktifitas` VALUES (2748, 101, 'LAUNCHING PRODUK AC DOUBLE FUNCTION (PENGKONDISIAN UDARA DAN PENYEDIA AIR PANAS) TAHUN 2022', '2022-05-18', 'Pusat Kewirausahaan, Inovasi dan Inkubator Bisnis (PUSKIIBI) Universitas Muhammadiyah Sumatera Utara merupakan inkubator bisnis teknologi yang berfungsi untuk mengembangkan calon usaha rintisan berbasis teknologi yang dimiliki oleh mahasiswa, alumni maupun masyarakat luas.  Dosen UMSU yang merupakan tenant Puskiibi dengan produk AC Double Function (Pengkondisian Udara dan Penyedia Air Panas) tahun 2022 ini memenangkan hibah Calon Perusahaan Pemula Berbasis Teknologi.  Untuk memperkenalkan produk secara luas, maka PUSKIIBI mengadakan Launching Produk tersebut. Dalam Launching Produk ini diharapkan calon konsumen akan lebih memahami produk tersebut, baik dari aspek fungsi, spesifikasi dan keunggulan yang ditawarkan.', '[\"public\\/foto-aktivitas\\/68ff08251052e.png\"]', '2025-10-27 12:50:29', '2025-10-27 12:50:29');
INSERT INTO `aktifitas` VALUES (2749, 657, 'Workshop & Inkubasi BUMDes 2025', '2025-09-26', 'Kegiatan Workshop dan Inkubasi BUMDes yang diselenggarakan pada 26–27 September 2025 oleh Inkubator Desa Cerdas (IDC) berlangsung dengan sukses dan interaktif. Acara ini bertujuan untuk meningkatkan kapasitas pengelola Badan Usaha Milik Desa (BUMDes) dalam mengembangkan inovasi, memperkuat manajemen usaha, serta memperluas jejaring bisnis desa.\r\n\r\nSelama dua hari kegiatan, para peserta mendapatkan pembekalan dari para narasumber dan praktisi berpengalaman mengenai strategi pengembangan usaha desa, tata kelola keuangan, pemasaran digital, serta penguatan model bisnis berkelanjutan. Selain itu, sesi inkubasi juga memberikan kesempatan bagi peserta untuk mendiskusikan ide-ide bisnis potensial yang dapat diterapkan di desa masing-masing.\r\n\r\nMelalui kegiatan ini, diharapkan BUMDes mampu menjadi motor penggerak ekonomi lokal yang mandiri, inovatif, dan berdaya saing tinggi, sekaligus berkontribusi pada pembangunan ekonomi nasional yang inklusif.', '[\"public\\/foto-aktivitas\\/6900492feb74b.jpg\"]', '2025-10-28 11:40:15', '2025-10-28 11:40:15');
INSERT INTO `aktifitas` VALUES (2750, 53, 'Ketua LPKIB Perkuat Pelaku Usaha Binaan Program Premium Kemenag Kota Malang melalui Materi Manajemen Risiko Bisnis', '2025-09-20', 'Kementerian Agama Kota Malang melalui Program Premium kembali menghadirkan kegiatan pembinaan bagi para pelaku usaha binaan. Pada kesempatan ini, Ketua Lembaga Pengembangan Kewirausahaan dan Inkubasi Bisnis (LPKIB) UNISMA, Ibu Mila, hadir sebagai pemateri dengan topik Manajemen Risiko Bisnis.\r\n\r\nDalam paparannya, Ibu Mila menekankan pentingnya kemampuan pelaku usaha dalam mengidentifikasi, menganalisis, serta mengantisipasi berbagai potensi risiko yang dapat memengaruhi keberlangsungan usaha. Dengan pengelolaan risiko yang tepat, para pelaku usaha tidak hanya mampu bertahan, tetapi juga dapat tumbuh secara berkelanjutan di tengah tantangan persaingan pasar.\r\n\r\nKegiatan ini diharapkan mampu meningkatkan literasi kewirausahaan binaan Kemenag Kota Malang, sehingga mereka lebih siap dalam menghadapi dinamika bisnis dan mengembangkan usaha secara profesional.\r\nKegiatan ini diharapkan mampu meningkatkan literasi kewirausahaan binaan Kemenag Kota Malang, sehingga mereka lebih siap dalam menghadapi dinamika bisnis dan mengembangkan usaha secara profesional.', '[\"public\\/foto-aktivitas\\/69057379898aa.jpeg\",\"public\\/foto-aktivitas\\/6905737989ee5.jpeg\"]', '2025-11-01 09:42:01', '2025-11-01 09:42:01');
INSERT INTO `aktifitas` VALUES (2751, 53, 'Kapus Pengembangan Kewirausahaan LPKIB, Tingkatkan Kompetensi Pengurus Koperasi Merah Putih Kota Malang', '2025-09-20', 'Lembaga Pengembangan Kewirausahaan dan Inkubasi Bisnis (LPKIB) UNISMA kembali menunjukkan perannya dalam mendukung penguatan kapasitas koperasi di Kota Malang. Kali ini, Kepala Pusat (Kapus) Pengembangan Kewirausahaan, Bapak Bastomi, hadir sebagai pemateri dalam kegiatan peningkatan kompetensi pengurus Koperasi Merah Putih Kota Malang.\r\n\r\nDalam penyampaiannya, Bapak Bastomi menekankan pentingnya tata kelola koperasi yang profesional, strategi pengembangan usaha berbasis kebutuhan anggota, serta penerapan inovasi agar koperasi dapat lebih adaptif di era persaingan global.\r\n\r\nKegiatan ini diharapkan mampu memberikan wawasan baru bagi pengurus koperasi, sehingga Koperasi Merah Putih Kota Malang dapat berkembang menjadi lembaga usaha yang sehat, mandiri, dan berdaya saing.', NULL, '2025-11-01 09:59:12', '2025-11-01 09:59:12');
INSERT INTO `aktifitas` VALUES (2752, 53, 'Bazar Wirausaha & UMKM Binaan LPKIB Unisma: Dukung SDGs Melalui Kewirausahaan Berkelanjutan pada Fun Walk Dies Natalis ke-44 dan Hari Santri Nasional', '2025-10-21', 'Dalam rangka memperingati Dies Natalis Universitas Islam Malang (Unisma) ke-44 serta menyambut Hari Santri Nasional, kampus Unisma menggelar Bazar Wirausaha dan UMKM Binaan Lembaga Pengembangan Kewirausahaan dan Inkubator Bisnis (LPKIB). Kegiatan ini menjadi momentum penting bagi Unisma dalam menegaskan komitmennya sebagai entrepreneurial university mendukung SDSs tujuan 8 tentang Peningkatan Pertumbuhan Ekonomi, sekaligus memperkuat semangat kebersamaan melalui kegiatan Fun Walk yang diikuti oleh civitas akademika, alumni, dan masyarakat umum.\r\n\r\nBazar ini ditujukan sebagai bentuk milestone perjalanan Unisma menuju kampus yang berdaya saing di bidang kewirausahaan. Melalui bazar, LPKIB menghadirkan hasil pembinaan nyata kepada masyarakat serta menciptakan ruang interaksi langsung antara pelaku usaha, mahasiswa, dan pengunjung. Kegiatan semacam ini menjadi bagian dari strategi kampus untuk membangun budaya wirausaha sejak dini di lingkungan akademik.\r\n\r\nStan LPKIB tampil menarik dengan beragam konten unggulan. Ada Ministore yang menjual produk kreatif mahasiswa dan alumni, Bookstore yang menyediakan buku-buku inspiratif serta karya ilmiah civitas akademika, dan Unisma Cafe yang menjadi pusat interaksi hangat sambil menikmati sajian minuman dan makanan ringan. Selain itu, terdapat pameran hasil karya anak-anak Daycare Unisma yang menampilkan kreativitas anak didik usia dini, serta stan tenant UMKM binaan LPKIB yang memperkenalkan berbagai produk lokal berkualitas.\r\n\r\nMelalui bazar ini, LPKIB tidak hanya memperkenalkan hasil binaan tenant kepada masyarakat, tetapi juga membuka peluang kolaborasi bisnis antara kampus dan pelaku usaha. Para tenant yang ikut serta merupakan bagian dari program inkubasi LPKIB, yang telah dibina melalui pelatihan, mentoring, hingga pengembangan strategi pemasaran digital.\r\n\r\nSelain berfokus pada wirausaha, bazar juga membawa pesan lingkungan. Melalui program bank sampah botol plastik, LPKIB mengajak seluruh peserta untuk peduli pada kebersihan lingkungan. Pengunjung dapat menukar botol plastik bekas dan mendapatkan es teh gratis dari stan Unisma Café. Disinilah peran LPKIB memberi motivasi kepada masyarakat agar sadar akan pengelolaan sampah sesuai dengan SDGs tujuan 12. Program sederhana ini menjadi simbol komitmen Unisma dalam membangun budaya hijau dan tanggung jawab sosial di kalangan mahasiswa dan masyarakat.\r\n\r\nKemeriahan bazar berpadu dengan semangat Fun Walk yang melibatkan ribuan peserta dari berbagai kalangan. Rute santai di sekitar kampus menjadi wadah silaturahmi dan refleksi perjalanan Unisma selama 44 tahun. Kegiatan ini membuktikan bahwa semangat akademik, wirausaha, dan nilai keislaman dapat berjalan beriringan dalam satu napas kebersamaan.\r\n\r\nDengan berbagai inovasi tersebut, LPKIB Unisma terus memperkuat perannya dalam mencetak wirausaha muda yang tangguh berkarakter islami dan berdaya saing. Bagi masyarakat yang ingin mengenal lebih jauh program inkubasi, tenant binaan, atau kegiatan kewirausahaan lainnya, silakan kunjungi situs resmi lpkib.unisma.ac.id. Mari dukung bersama langkah Unisma menuju universitas berjiwa wirausaha yang inspiratif dan berkelanjutan.', NULL, '2025-11-01 10:20:55', '2025-11-01 10:20:55');
INSERT INTO `aktifitas` VALUES (2753, 53, 'Pendampingan Menulis Artikel UMKM untuk Mewujudkan Bisnis Berdaya & Berkelanjutan', '2025-10-25', 'Malang, 25 Oktober 2025 – Lembaga Pengembangan Kewirausahaan dan Inkubasi Bisnis (LPKIB) Universitas Islam Malang (UNISMA) menggelar kegiatan Pendampingan Menulis Artikel UMKM dengan tema “Sustainable Storytelling: Mewujudkan Bisnis Berdaya & Berkelanjutan”, bertempat di Ruang Inkubasi Bisnis LPKIB UNISMA.\r\n\r\nKegiatan ini dihadiri oleh para pelaku UMKM binaan LPKIB, mahasiswa pendamping, serta tim pengembang kewirausahaan UNISMA. Tujuan dari kegiatan ini adalah membekali peserta dengan kemampuan menulis artikel inspiratif dan berbasis keberlanjutan (sustainability), yang dapat digunakan untuk memperkuat citra, promosi, serta dokumentasi perjalanan usaha UMKM.\r\n\r\nDalam sambutannya, Ir. Brahmadhita Pratama Mahardhika, M.Si., IPP, selaku Kepala Pusat Inkubasi Bisnis LPKIB UNISMA, menyampaikan bahwa kemampuan menulis bagi pelaku UMKM menjadi penting di era digital saat ini. Melalui penulisan artikel, pelaku usaha dapat menyampaikan nilai, kisah, dan dampak sosial dari bisnisnya kepada masyarakat luas.\r\n\r\n“Setiap UMKM punya cerita perjuangan dan nilai keberlanjutan yang bisa menginspirasi. Melalui kegiatan ini, kami ingin membantu mereka menulis dan membagikan kisahnya dengan cara yang lebih menarik, terarah, dan bermanfaat,” ujar Brahmadhita.\r\n\r\nKegiatan pendampingan ini juga menjadi bagian dari komitmen LPKIB dalam mendukung Sustainable Development Goals (SDGs), terutama pada SDG 8 (Pekerjaan Layak dan Pertumbuhan Ekonomi), SDG 9 (Inovasi dan Infrastruktur), dan SDG 12 (Konsumsi dan Produksi yang Bertanggung Jawab).\r\n\r\nSelama kegiatan berlangsung, peserta mendapatkan materi mengenai konsep sustainable storytelling, teknik menulis artikel populer, dan di akhir sesi, para peserta praktik menulis kisah UMKM dengan bimbingan langsung dari mentor. Para peserta tampak antusias mengikuti setiap sesi. Salah satu peserta menyampaikan bahwa kegiatan ini membantu mereka memahami cara menulis yang menarik sekaligus memperkenalkan nilai-nilai keberlanjutan dalam usaha kecil.\r\n\r\nKegiatan ditutup dengan sesi foto bersama antara narasumber, peserta, dan panitia sebagai bentuk apresiasi dan simbol kolaborasi dalam memperkuat literasi serta keberlanjutan UMKM.\r\n\r\nDengan terselenggaranya kegiatan ini, diharapkan para peserta mampu menghasilkan karya tulis yang tidak hanya menginspirasi, tetapi juga menjadi media promosi positif bagi UMKM menuju bisnis yang berdaya, inklusif, dan berkelanjutan.', NULL, '2025-11-01 12:01:15', '2025-11-01 12:01:15');
INSERT INTO `aktifitas` VALUES (2754, 154, 'Kunjungan Tempat Usana Tenant Nayz Patissery', '2025-07-10', 'Kunjungan Tim PIB UNIBI kepada tenant inwall Nayz Patissery milik Nayyara Azzahralia mahasiswi UNIBI Program Studi Psikologi 2023 yang merupakan binaan PIB UNIBI yang bergerak di bidang F&B yakni Snack Box, kunjungan ini dimaksudkan untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/6908125f8b8ff.png\"]', '2025-11-03 09:24:31', '2025-11-03 09:26:54');
INSERT INTO `aktifitas` VALUES (2755, 154, 'Kunjungan Tempat Usana Tenant CemilQu by Teh Adel', '2025-07-23', 'Kunjungan Tim PIB UNIBI kepada tenant inwall CemilQu by Teh Adel milik Resty Delima mahasiswi UNIBI Program Studi Psikologi 2022 yang merupakan binaan PIB UNIBI yang bergerak di bidang F&B yakni Risoles, kunjungan ini dimaksudkan untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/690816544c933.png\"]', '2025-11-03 09:41:24', '2025-11-03 09:41:24');
INSERT INTO `aktifitas` VALUES (2756, 90, 'Seminar Digital Preneurship: Dari Scroll jadi Cuan! Bangun Income Lewat Konten & Affiliate Marketing', '2025-10-27', 'Pada hari senin, 27 Oktober 2025, bertempat di ruang Auditorium Universitas Al - Azhar Indonesia, Tajeer Inkubator Bisnis X Jago Akademi” bareng Annisa Damayanti (Head of Jago Akademi) mengadakan seminar tentang langkah-langkah praktis membangun income lewat Konten & Affiliate Marketing! 🚀\r\n\r\n💡 Tema:\r\n“Digital Preneurship: Dari Scroll jadi Cuan! Bangun Income Lewat Konten & Affiliate Marketing”\r\n\r\n📅 Senin, 27 Oktober 2025\r\n🕐 13.00 – 15.00 WIB\r\n📍 Auditorium Universitas Al-Azhar Indonesia, Lantai 3\r\n\r\n🎯 Table of Content terkait seminar tersebut yaitu:\r\n1️⃣ Kenali Ekosistem Affiliate Marketing\r\n2️⃣ Cara Membangun Personal Branding\r\n3️⃣ Strategi Monetisasi & Optimasi Affiliate TikTok\r\n4️⃣ Study Case Content Affiliate', '[\"public\\/foto-aktivitas\\/69082c2c43e08.jpeg\"]', '2025-11-03 11:14:36', '2025-11-03 11:14:36');
INSERT INTO `aktifitas` VALUES (2757, 154, 'Kunjungan Tempat Usana Tenant Susu Murni Kencana', '2025-08-15', 'Kunjungan Tim PIB UNIBI kepada tenant inwall Susu Murni Kencana milik Diva Hadaya mahasiswa UNIBI Program Studi Psikologi 2021 yang merupakan binaan PIB UNIBI yang bergerak di bidang FNB yakni susu murni, kunjungan ini dimaksudkan untuk melakukan kontrol dan sekaligus sharing.', '[\"public\\/foto-aktivitas\\/6909add2ddb84.png\"]', '2025-11-04 14:40:02', '2025-11-04 14:40:02');
