INSERT INTO `aktifitas` VALUES (2759, 523, 'Sosialisasi Koperasi Desa Merah Putih Kelurahan Peguyangan', '2025-06-17', 'Sosialisasi Kopersi Desa Merah Putih dilakukan di Kelurahan Peguyangan dimpimpin Bapak Kepala Dinas Koperasi dan UMKM Kota Denpasar didampingi oleh Ketua Bidang KPK, Tenaga Ahli Inbis, Ibu Sutrisna Dewi.', '[\"public\\/foto-aktivitas\\/690fb94f1105b.jpg\"]', '2025-11-08 21:01:47', '2025-11-09 04:42:39');
INSERT INTO `aktifitas` VALUES (2761, 523, 'WORKSHOP III STRATEGI KREATIF OPTIMALISASI IKLAN DAN META ADS', '2025-06-20', 'Kegiatan peningkatan kapasitas usaha bagi TENANT 2025 INBIS Pusaka Denpasar Collab melalui kegiatan WORKSHOP III dengan tema STRATEGI KREATIF OPTIMALISASI IKLAN DAN META ADS kali ini bekerja sama dengan INBIS TELKOM - INDIGO dibuka oleh Bapak Kepala Dinas Koperasi dan UMKM Kota Denpasar, di dampingi Ibu Ketua INBIS dan tim pengelola.', '[\"public\\/foto-aktivitas\\/690fb7ec0c4fc.jpg\"]', '2025-11-08 21:07:14', '2025-11-09 04:36:44');
