INSERT INTO `aktifitas` VALUES (2773, 523, 'Sharing Session GENERASI MUDA BERKARYA dari IDE KREATIF ke AKSI NYATA', '2025-08-01', 'Kegiatan Sharing session diadakan di sela kegiatan pameran Tenant INBIS 2025 dan peringatan hari KOPERASI dan hari UMKM Nasional (ADA CERITA GENSI DIBALIK SENJA. ) bertempat di Taman Kota Denpasar. \r\n\r\n Sahringg session ini mengangkat tema : GENERASI MUDA BERKARYA dari IDE KREATIF ke AKSI NYATA, Sharing session diisi oleh Ibu Sutrisna Dewi selaku moderator, Agi Pratama dari Umah Lokal dan IGN Airlangga Bayu dari BTI energi. Sasaran Kegiatan ini adalah pengusaha dan generasi muda Kota Denpasar.', NULL, '2025-11-08 21:28:26', '2025-11-12 12:25:13');
