INSERT INTO `aktifitas` VALUES (2781, 523, 'PAMERAN TENANT 2025 di HARI KOPERASI DAN HARI UMKM', '2025-08-01', 'Seluruh TENANT 2025 ikut melakukan kegiatan pameran dagang yang diselenggarakan dalam rangka memperingati hari Koperasi dan Hari UMKM dengan TEMA ADA CERITA GENSI dibalik SENJA. Kegiatan berlangsung selama tiga hari di Lapangan Lumintang Denpasar', NULL, '2025-11-08 21:36:14', '2025-11-08 21:36:14');
