INSERT INTO `aktifitas` VALUES (2857, 85, 'Program Inkubasi Produk Digital 2026', '2025-11-13', 'Program inkubasi untuk pendampingan dan pembinaan produk digital', '[\"public\\/foto-aktivitas\\/6929269faf7c2.jpg\",\"public\\/foto-aktivitas\\/6929269fafa45.jpg\",\"public\\/foto-aktivitas\\/6929269fafb68.jpg\"]', '2025-11-28 11:35:43', '2025-11-28 11:35:43');
INSERT INTO `aktifitas` VALUES (2858, 10, 'Program Inkubasi Mekaarpreneur Day 1 - Kick Off', '2025-08-06', 'Program Inkubasi Mekaarpreneur merupakan program pendampingan dan pengembangan usaha bagi UMKM perempuan yang bertujuan untuk meningkatkan kapasitas, kemandirian, dan daya saing wirausaha. Program ini menghadirkan proses inkubasi terpadu melalui pelatihan, mentoring, dan pendampingan intensif agar peserta mampu mengelola bisnis secara profesional, memperkuat branding, mengoptimalkan strategi pemasaran, serta memanfaatkan teknologi dalam pengembangan usaha. Melalui kegiatan ini diharapkan lahir wirausaha perempuan yang tangguh, inovatif, dan berdaya saing tinggi di tingkat lokal maupun nasional.', '[\"public\\/foto-aktivitas\\/692cffd1e3613.jpg\",\"public\\/foto-aktivitas\\/692cffd1e3c32.jpg\",\"public\\/foto-aktivitas\\/692cffd1e4085.jpg\"]', '2025-12-01 09:39:13', '2025-12-01 09:39:13');
