INSERT INTO `kontak_kami` VALUES (69, 'vera rizky gumilar', 'verarizkygumilar.vrg@gmail.com', 'izin bertanya untuk rekrutmen pegawai divisi layanan kemasan, file cv beserta berkas lainnya, dikirim ke email kemenkop ukm yg mana ya, mohon informasinya. trimakasih', '2023-08-30 20:21:15', '2023-08-30 20:21:15');
INSERT INTO `kontak_kami` VALUES (70, 'JUNAIDI', 'junaidi10031980@gmail.com', 'Kami mau berkoordinasi untuk pendaftarak Inkubator Bisnis mamdiri yang di kelola oleh salah satu ormas di kabupaten Batu Bara Sumatera Utara yg memfokuskan membentut Start Up sektor Kelautan dan Perikanan, mhn advis dan bimbingannya.\r\n\r\nJUNAIDI\r\n081280005551', '2023-09-02 00:51:13', '2023-09-02 00:51:13');
INSERT INTO `kontak_kami` VALUES (71, 'Ir. Aminan Trojaya, MSi', 'koppracentre@gmail.com', 'As.wr.wb., Kami Panitia Musker KOPPRA, Kab. Banyumas. Dengan ini memohon kesediaan bpk Drs. Teten Masduki (Kemenkop & UKM) ; kiranya dapat memenuhi undangan kami (koppra centre indonesia), pada Acara Musker-I, KOPPRA, pada tgl 13 September 2023, jam 9 pagi, tempat di Queen Garden Hotel  Kab. Banyumas.  Demikian undangan kami, atas kehadirannya kami haturkan terima kasih. Ttd. Aminan Trojaya, 082398350101. Wassalam.', '2023-09-02 16:24:36', '2023-09-02 16:24:36');
