INSERT INTO `kontak_kami` VALUES (83, 'Rico Ayatul Yuza', 'ricoyuza@desaberdaya.org', 'ibu/bpk admin, \r\nperkenalkan saya rico yuza dr lokadesa/desaberdaya dr sbg lembaga yg bergerak di bidang isu pangan dengan aktivitas utama inkubasi usaha mikro pedesaan diseluruh indonesia, lokasi kami di bandung jawa barat, \r\nkami berencana ingin menjadi lembaga inkubasi bisnis\r\nhal apa apa saja yang perlu kami persiapkan dan apakah kami bisa bersilahturahmi shg mengetahui syarat dan dibimbing langsung', '2023-10-20 16:26:06', '2023-10-20 16:26:06');
INSERT INTO `kontak_kami` VALUES (88, 'Sunardi', 'kudtanibahagia4@gmail.com', 'dari KUD Tani Bahagia Trenggalek Jawa Timur kami sedang mengurus IJIN USAHA perubahan nama perusahaan dar Koperasi Unit Desa Tani Bahagia Menjadi Koperasi Konsumen KUD Tani Bahagia berdasarkan AHU-0001778..AH.01.38.TAHUN 2022 NIK KOPERASI NO. 350307130015 Mhon bantuannya untuk menyingkronkan dengan DITJEN AHU.  karena tadi disistem oss. muncul pesan  gagal mencari data nama koperasi tidak diketemukan', '2023-11-01 13:12:33', '2023-11-01 13:12:33');
INSERT INTO `kontak_kami` VALUES (89, 'chahra event plus', 'partnership@chahraevent.id', 'Selamat pagi, saya ingin bertanya untuk mengajukan program, kemudian validasi untuk bisa didukung KEMENKOPUKM bagaimana ya stepnya? terima kasih', '2023-11-02 10:16:20', '2023-11-02 10:16:20');
