INSERT INTO `kontak_kami` VALUES (97, 'Junita Duwi Purwandari', 'jpurwandari@upnvj.ac.id', 'Selamat Pagi, \r\n\r\nSaya ingin menanyakan, kalau Inkubator Bisnis milik Universitas negeri, apakah juga diwajibkan mendaftarkan lembaga inkubator bisnisnya? Persyaratan akta pendirian/notaris juga wajibkah? Karena yang kami miliki hanya surat Keputusan Rektor saja. \r\n\r\nTerimakasih', '2023-11-24 09:32:16', '2023-11-24 09:32:16');
INSERT INTO `kontak_kami` VALUES (99, 'Vila Novita Syah Putri, S.H.,M.Kn', 'notarisvilanovita@gmail.com', 'Yth. \r\nDeputi Bidang Perkoperasian Kementerian Koperasi dan Usaha Kecil Menengah Republik Indonesia. \r\n\r\nSaya telah mengirim kan Fisik permohonan SK Notaris Pembuat Akta Koperasi', '2023-12-09 13:44:51', '2023-12-09 13:44:51');
INSERT INTO `kontak_kami` VALUES (100, 'olivia', 'oliv001@kominfo.go.id', 'Mohon info alamat email yang bisa dituju untuk Deputi Bidang Usaha Kecil dan Menengah , KemenkopUKM, dengan maksud pengiriman undangan kegiatan Kementerian Kominfo tanggal 14 Desember 2023. Terima kasih.', '2023-12-11 15:35:30', '2023-12-11 15:35:30');
