INSERT INTO `kontak_kami` VALUES (516, 'Pudio Iqbal Prayogi', 'blkkponpesalihsantemppurrejo@gmail.com', 'Selamat siang, mohon ijin bertanya. Untuk proses verifikasi registrasi email inkubator memerlukan waktu berapa lama?', '2024-06-22 11:14:47', '2024-06-22 11:14:47');
