INSERT INTO `kontak_kami` VALUES (2005, 'Future Lestari', 'melisa.nirmaladewi@Pijarfoundation.org', 'Permohonan Bantuan Terkait Kendala Registrasi di SIPENSI\r\n\r\nYth. Tim Website SIPENSI Kementerian UMKM,\r\nSaya ingin melaporkan kendala yang saya alami saat melakukan registrasi melalui laman SIPENSI (https://sipensi.kemenkopukm.go.id/registrasi). Meskipun saya telah mengisi seluruh data yang diperlukan, ketika saya mencoba mengirimkan formulir registrasi, halaman tiba-tiba mengalami error.\r\n\r\nMohon bantuannya untuk mengatasi permasalahan ini. Terima kasih atas perhatian dan bantuannya.\r\n\r\nSalam,\r\nMelisa Nirmaladewi\r\nFuture Lestari', '2025-03-19 14:23:04', '2025-03-19 14:23:04');
