INSERT INTO `produk` VALUES (1, 133, 'Pakan Lolohan Lovebird', '<p>ABL Nutrisi hadir dengan resep yang sesuai dengan kebutuhan nutrisi anakan Lovebird. Serta melalui eberapa reset yang menghasilkan produk ABL Nutrisi berkualitas dengan harga yang terjangkau</p>', '[\"public\\/file_foto_produk\\/63871c6e6ccd5.png\"]', '2022-11-30 09:03:42', '2022-11-30 09:03:42');
INSERT INTO `produk` VALUES (2, 157, 'Nasi Bakar', NULL, '[\"public\\/file_foto_produk\\/63871dd3a28cf.png\"]', '2022-11-30 09:09:39', '2022-11-30 09:09:39');
