INSERT INTO `produk` VALUES (5, 161, 'Sitem E-Ticketing Taman Nasional Baluran', NULL, '[\"public\\/file_foto_produk\\/63871fd658cf7.png\"]', '2022-11-30 09:18:14', '2022-11-30 09:18:14');
