INSERT INTO `produk` VALUES (7, 152, 'Susu Kemasan Liter', '<p>Susu kemasan 1 Liter tersedia susu murni, pasteurisasi &amp; aneka rasa. Kemasan Pasteurisasi bisa langsung dimunum atau untuk campuran minuman kesehatan lainnya&nbsp;</p>', '[\"public\\/file_foto_produk\\/638ec045d9790.png\"]', '2022-12-06 04:08:37', '2022-12-06 04:08:37');
INSERT INTO `produk` VALUES (8, 152, 'Kemasan 250ml dan 350ml', '<p>Kemasan 250ml tersedia aneka rasa Original, Chocolate, Strawberry, sweet, melon, grape, durian dan susu kurma. Kemasan botol mudah dibawa dan dikonsumsi langsung&nbsp;</p>', '[\"public\\/file_foto_produk\\/638ec1195e3f6.png\"]', '2022-12-06 04:12:09', '2022-12-06 04:12:09');
INSERT INTO `produk` VALUES (9, 152, 'Kemasan Cup dan Kiko', '<p>Kemasan ukuran ini untuk anak TK dan SD dengan harga terjangkau dan banyak pilihan rasa.&nbsp;</p>', '[\"public\\/file_foto_produk\\/638ec1a76862c.png\"]', '2022-12-06 04:14:31', '2022-12-06 04:14:31');
INSERT INTO `produk` VALUES (10, 151, 'Almond Crispy', '<p>Komposisi : Terigu, Telur, Mentega, Gula, Kacang Almond, Perasa, Keju</p><p>Berat : 30 gram, 50 gram, 100 gram</p><p>Legalitas : NIB, PIRT</p><p>Kemasan : Standing Pouch</p>', '[\"public\\/file_foto_produk\\/638ec3bc62606.png\"]', '2022-12-06 04:23:24', '2022-12-06 04:23:24');
INSERT INTO `produk` VALUES (11, 151, 'Butter Cake', '<p style=\"color: rgb(33, 37, 41);\">Komposisi : Terigu, Telur, Gula, Butter, Vanili, Bp</p><p style=\"color: rgb(33, 37, 41);\">Berat : 1 Kg</p><p style=\"color: rgb(33, 37, 41);\">Legalitas : NIB, Merk</p><p style=\"color: rgb(33, 37, 41);\">Kemasan : Mika dan karton</p>', '[\"public\\/file_foto_produk\\/638ec42b2ebd6.png\"]', '2022-12-06 04:25:15', '2022-12-06 04:25:15');
