INSERT INTO `produk` VALUES (52, 1414, 'Usadha.com', '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,&quot;serif&quot;;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Usadha.com merupakan layanan berbasis web dan\r\naplikasi yang menawarkan layanan pengobatan komplementer, sehingga setiap orang\r\nyang akan melakukan terapi dapat lebih mudah dalam berkomunikasi dengan <i>therapist</i> melalui platform tersebut&nbsp;</span><br></p>', '[\"public\\/file_foto_produk\\/64740c888f54c.png\",\"public\\/file_foto_produk\\/64740c888f897.png\"]', '2023-05-29 09:20:29', '2023-05-29 09:23:04');
