INSERT INTO `produk` VALUES (54, 1415, 'White Damask', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">This perfume can make you confident and charming in special moments with a variety of luxurious rose and sandalwood scents</span><br></p>', '[\"public\\/file_foto_produk\\/64740f460748b.png\"]', '2023-05-29 09:34:46', '2023-05-29 09:34:46');
