INSERT INTO `produk` VALUES (72, 2818, 'Manok-Itek Enjoy Aja', '<p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: Helvetica;\">Kamp menyediakan menu makan dan minum khusus, yaitu berupa paket ‘manok-itek enjoy aja’. Khusus untuk paket ini, setelah memesan, pengunjung dituntut untuk memasak sendiri dengan semua bahan dan fasilitas disiapkan oleh awak kamp.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: Helvetica;\">Bagi anda yang ingin bersantai sambil menikmati masakan dan minuman ala Kamp, anda bisa memanfaatkan fasilitas berupa hammock dan kursi santai enjoy aja. Di sini, anda boleh menaikkan kaki ke atas meja atau kursi tanpa perlu resah takut dimarahi<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/656b620487d27.png\"]', '2023-12-02 23:57:40', '2023-12-02 23:58:02');
INSERT INTO `produk` VALUES (73, 2818, 'RUANG DIALEKTIKA', '<p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: RobotoCondensed, serif; font-size: 11pt;\">Sejumlah pihak berdiskusi ringan di KAMP, membahas ide- ide potensial untuk Aceh dan Indonesia, sambil menunggu masaknya Kuah Beulangong untuk disantap bersama.</span><br></p><p><span style=\"color: black; font-size: 11pt; font-family: RobotoCondensed, serif;\">Support Kamp agar tetap eksis, untuk hidup dan menghidupi dirinya serta orang banyak</span><span style=\"color: rgb(0, 0, 0); font-size: medium;\"></span><br></p>', '[\"public\\/file_foto_produk\\/656b62b74117e.png\"]', '2023-12-03 00:00:14', '2023-12-03 00:00:39');
INSERT INTO `produk` VALUES (74, 2818, 'Senja Sakti', '<p style=\"margin-right: 0cm; margin-left: 0cm; font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 11pt; font-family: RobotoCondensed, serif;\">Tiap sore, KAMP yang bergabung dalam Persekutuan Buruh Biawak (PBB) akan membacakan puisi-puisi terbaik, nyanyian-nyanyian terindah, atau pertunjukan-pertunjukan menarik.</span><span style=\"font-size: 11pt;\"><o:p></o:p></span></p><p style=\"margin-right: 0cm; margin-left: 0cm; font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 11pt; font-family: RobotoCondensed, serif;\">\"SENJA SAKTI\" adalah sebuah sayembara pertunjukan seni, yang apabila anda ikut terlibat, baik membacakan puisi, berhikayat, berpantun, memainkan alat musik, berteater dan lain sebagainya, maka kami akan menyediakan hadiah-hadiah menarik untuk anda sekalian.</span><span style=\"font-size: 11pt;\"><o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/656b62f4b27f6.png\"]', '2023-12-03 00:01:40', '2023-12-03 00:01:40');
INSERT INTO `produk` VALUES (75, 2433, 'Garam Mineral Mon Kuta', '<span style=\"font-family: HelveticaNeue; font-size: 16px;\">Garam Mineral, beryodium, mengandung KI30 mpm, 30 ppm&nbsp;</span>', '[\"public\\/file_foto_produk\\/656b642441062.jpeg\"]', '2023-12-03 00:06:44', '2023-12-03 00:06:44');
INSERT INTO `produk` VALUES (76, 2433, 'SPBU Nelayan', '<span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(77, 81, 86);\">Campuran&nbsp;</span><span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(4, 12, 40);\">bahan&nbsp;</span><span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(77, 81, 86);\">bakar fosil yakni&nbsp;</span><span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(4, 12, 40);\">bahan&nbsp;</span><span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(77, 81, 86);\">bakar solar (diesel) dengan&nbsp;</span><span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(4, 12, 40);\">bahan&nbsp;</span><span style=\"font-size: 12pt; font-family: ArialMT; color: rgb(77, 81, 86);\">jenis organik atau disebut juga sebagai biomassa,&nbsp;</span>', '[\"public\\/file_foto_produk\\/656b6463e503c.jpeg\"]', '2023-12-03 00:07:47', '2023-12-03 00:07:47');
