INSERT INTO `produk` VALUES (78, 2945, 'ARENGA SUGAR', '<p><font color=\"#000000\"><span style=\"font-family: Lora, serif; font-size: 16px;\">Arenga Sugar is good for people with diabetic because it has lower glycemic index (35) compares to cane sugar (58) that doesn’t make the blood sugar level go uo. Arenga sugar is proven containing essential elements such as vitamin B1, vitamin B2, vitamin C and protein.&nbsp;<br></span><br>https://reinaherbal.com/product/arenga-sugar/</font><br></p>', '[\"public\\/file_foto_produk\\/657197935ad94.jpg\"]', '2023-12-07 16:59:47', '2023-12-07 17:03:52');
INSERT INTO `produk` VALUES (79, 2945, 'BALINESE BOREH', '<p><span style=\"color: rgb(111, 77, 53); font-family: Lora, serif; font-size: 16px; background-color: rgb(248, 247, 243);\">Balinese Boreh is suitable for those with arthistis, tired back, improves blood circulation. It brings warmth to the body. Balinese Boreh is being used to clean pores, promote the release of toxins and provide a deep sense of relaxation, resulting in deliciously fresh, smooth, and refined skin, as well as providing greater energy, clarity and well-being.<br></span><br>https://reinaherbal.com/product/balinese-boreh/<br></p>', '[\"public\\/file_foto_produk\\/657198dc2c530.jpg\"]', '2023-12-07 17:05:16', '2023-12-07 17:05:16');
INSERT INTO `produk` VALUES (80, 2945, 'Beauty Ritual Package', '<p style=\"box-sizing: inherit; border: 0px; font-size: 16px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline; font-family: Lora, serif;\"><font color=\"#000000\">This package is special for self-love and self-care treatment. One box, you can get traditional body scrub, perfume aromatherapy (feminine energy), herbal tea/ tisane tea.</font></p><p style=\"box-sizing: inherit; border: 0px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline;\"><font color=\"#000000\" style=\"\"><font face=\"Lora, serif\"><span style=\"font-size: 16px;\">The bonus you get Reina Wellness songs playlist (Spotify), while you enjoy ” me time” beauty ritual, you can hear the therapeutic songs.</span></font><br><br><font face=\"Lora, serif\"><span style=\"font-size: 16px;\">https://reinaherbal.com/product/beauty-ritual-package/</span></font><br></font></p>', '[\"public\\/file_foto_produk\\/6571994752368.png\"]', '2023-12-07 17:07:03', '2023-12-07 17:07:03');
