INSERT INTO `produk` VALUES (99, 3016, 'Berasae', '<b>Berasae</b> adalah pemberian nama dari warga Ngawi Raya untuk produk beras dari anggota produsen di koperasi Ngawi Tani Mandiri. Proses berasae menggunakan penggilingan, pengemasan dan manajemen mutu yang terorganisir dengan memaksimalkan potensi&nbsp; anggota. Terdapat beberapa varian beras berdasarkan spesifikasi yang berbeda, yaitu Berasae premium, Berasae Mentik Wangi, Berasae biasa, Berasae sayur, Berasae Hajatan dan lainnya. Ketersediaan stok harian untuk masing-masing mencapai 50 kg per hari dan tersedia sepanjang tahun dengan harga fluktuatif. selengkapnya bisa dicek di berasngawi.com', '[\"public\\/file_foto_produk\\/65aed73dac291.JPG\"]', '2024-01-23 03:59:41', '2024-01-23 03:59:41');
