INSERT INTO `produk` VALUES (131, 3197, 'ULTIMATE 5 MAX', '<p style=\"text-align: left; margin-bottom: 1.3em; color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium;\">Line Follower mikrokontroller tercepat dari ICHIBOT dengan teknologi terkini prosesor ESP32 clock speed 240MHz. Lebih mudah pengoperasiannya karena langsung dapat di setting pada layar robot. Dilengkapi dengan 14 sensor dan Motor DC dengan kecepatan 2500 RPM membuat robot ini dapat melaju dengan sangat cepat. Fitur Sensor Rotary Encoder juga membuat robot ini memili akurasi yang lebih tinggi dibandingkan dengan versi lainnya.</p><p style=\"text-align: left; margin-bottom: 1.3em; color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium;\">Selain dapat disetting pada robot secara langsung, robot ini dilengkapi dengan port USB type C yang dapat memungkinkan pengguna untuk memprograrm robot melalui komputer (Arduino IDE)</p>', '[\"public\\/file_foto_produk\\/65e1543f47519.JPG\"]', '2024-03-01 11:06:23', '2024-03-01 11:06:23');
INSERT INTO `produk` VALUES (132, 3197, 'Ultimate 4s', '<p style=\"margin-bottom: 1.3em; color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium;\"><span style=\"font-weight: bolder;\">ICHIBOT</span>&nbsp;sudah dilengkapi dengan operating system didalamnya, sehingga semua pengaturan gerakan robot langsung dapat diatur pada robot tersebut tanpa membutuhkan bantuan komputer.</p><p style=\"margin-bottom: 1.3em; color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium;\"><span style=\"font-weight: bolder;\">CHIOS</span>&nbsp;adalah sebuah operating system yang dikembangkan oleh ichibot untuk mengatur seluruh parameter robot Line Follower Ichibot dengan media display OLED 0.96 inch dan navigasi tombol 6 buah.</p><p style=\"margin-bottom: 1.3em; color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium;\"><span style=\"font-weight: bolder;\">Spesifikasi Display :</span></p><ul style=\"list-style-type: disc; margin-bottom: 1.3em; color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium;\"><li style=\"margin-bottom: 0.6em; margin-left: 1.3em;\">Oled 0.96 Single Color</li><li style=\"margin-bottom: 0.6em; margin-left: 1.3em;\">Pixel 128×64</li><li style=\"margin-bottom: 0.6em; margin-left: 1.3em;\">Comunication IIC</li><li style=\"margin-bottom: 0.6em; margin-left: 1.3em;\">Voltage 5v</li></ul>', '[\"public\\/file_foto_produk\\/65e154e84abd9.JPG\"]', '2024-03-01 11:09:12', '2024-03-01 11:09:12');
INSERT INTO `produk` VALUES (133, 3197, 'CHIDUINO NANO [2023] with Magcharge', '<p><span style=\"color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium; text-align: center;\">Robot line follower yang didesain untuk kamu yang ingin belajar pemrograman line follower.</span><br style=\"color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium; text-align: center;\"><span style=\"color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium; text-align: center;\">Robot ini dikuhusukan untuk pembelajaran atau perlombaan yang mengharuskan pengguna melakukan pemrograman (tidak ada fitur path planning dengan tombol)</span><br></p>', '[\"public\\/file_foto_produk\\/65e1556487c3d.JPG\"]', '2024-03-01 11:11:16', '2024-03-01 11:11:16');
INSERT INTO `produk` VALUES (134, 3197, 'TRAINER ARDUINO MEGA 2560', '<p><span style=\"color: rgb(119, 119, 119); font-family: Lato, sans-serif; font-size: medium; text-align: center;\">Trainer pembelajaran dengan papan kendali utama Arduino Mega 2560 dan dilengkapi dengan lebih dari 20 modul yang dapat digunakan sebagai media praktik programming Arduino.</span><br></p>', '[\"public\\/file_foto_produk\\/65e1562197443.JPG\"]', '2024-03-01 11:14:25', '2024-03-01 11:14:25');
