INSERT INTO `produk` VALUES (184, 3770, 'Yeppoo', 'Body Wash Organik', '[\"public\\/file_foto_produk\\/66ab07265d882.png\"]', '2024-08-01 10:55:18', '2024-08-01 10:55:18');
INSERT INTO `produk` VALUES (185, 3806, 'Oncom Hideng Ummi Pupu', NULL, '[\"public\\/file_foto_produk\\/66ac89c7a9b43.jpg\"]', '2024-08-02 14:24:55', '2024-08-02 14:24:55');
INSERT INTO `produk` VALUES (186, 3807, 'Kingpee', '<p>Kingpee merupakan produk usaha yang dibuat dengan bahan awal pisang, dan memiliki inovasi terbaru dengan berbagai produk lainnya.</p>', '[\"public\\/file_foto_produk\\/66ac8cbe3b31f.jpeg\"]', '2024-08-02 14:37:34', '2024-08-02 14:37:34');
INSERT INTO `produk` VALUES (187, 3808, 'Kepi', '<p>Nama “KEPI” yang berati topi kepi. Memvisualisasi suasana petualangan yang menarik dan unik di sekitar konsep kepi, mungkin dengan menggabungkan elemen militer pada nama menu yang disajikan. Dengan didesain secara&nbsp; &nbsp;modern dan topping yang melimpah, kehadiran \"KEPI\" diharapkan mendapatkan apresiasi luar biasa di setiap market<br></p>', '[\"public\\/file_foto_produk\\/66ac9088771ed.jpg\"]', '2024-08-02 14:53:44', '2024-08-02 14:53:44');
INSERT INTO `produk` VALUES (188, 3809, 'Kalapa Klopo', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Kami menjual Aneka Minuman Kelapa, Kelapa Muda, &amp; Kelapa Ijo</span><br></p>', '[\"public\\/file_foto_produk\\/66ac933679b79.jpeg\"]', '2024-08-02 15:05:10', '2024-08-02 15:05:10');
INSERT INTO `produk` VALUES (189, 3876, 'Katering Box', '<p>Katering Box, yang mengutamakan sajian makanan sehat khusus bagi masyarakat yang sedang menjalani program diet. Dengan perhatian penuh terhadap keseimbangan nutrisi dan kualitas bahan baku, Omnivour berkomitmen untuk mendukung gaya hidup sehat melalui pilihan menu yang lezat dan menyehatkan, tanpa mengorbankan cita rasa.<br></p>', '[\"public\\/file_foto_produk\\/66bc1241972cb.jpeg\"]', '2024-08-14 09:11:13', '2024-08-14 09:21:29');
INSERT INTO `produk` VALUES (190, 3957, 'Rendang Ikan', '<p>Rendang ikan,dimana ikan yang kami gunakan adalah ikan salai khas Riau,dan rendang kami ini menggunakan bumbu alami dna penyedap yang kami buat sendiri<br></p>', '[\"public\\/file_foto_produk\\/66bc1428c2b75.jpeg\"]', '2024-08-14 09:19:20', '2024-08-14 09:19:20');
INSERT INTO `produk` VALUES (191, 3958, 'Burger', '<p>Makanan Frozen</p>', '[\"public\\/file_foto_produk\\/66bc15d5385e6.jpeg\"]', '2024-08-14 09:26:29', '2024-08-14 09:26:29');
INSERT INTO `produk` VALUES (192, 3959, 'Kokedama', '<p>Kokedama memiliki bentuk yang unik, mudah dalam perawatan, minim pesaing. tidak hanya menjual produk tapi juga membuka kelas edukasi yaitu workshop kokedama<br></p>', '[\"public\\/file_foto_produk\\/66bc17af2846c.jpeg\"]', '2024-08-14 09:34:23', '2024-08-14 09:34:23');
INSERT INTO `produk` VALUES (193, 3960, 'Board Game Amukti Palapa', '<p>Board Game Amukti Palapa adalah permainan papan yang diadaptasi dari permainan tradisional Bas-Basan Sepur, di desain ulang dengan penambahan gameplay yang membuatnya memiliki potensi dimainkan oleh banyak orang dengan variable penjualan yang beragam, dari papan, bidak, dan item tambahan lainnya yang dijual terpisah.<br></p>', '[\"public\\/file_foto_produk\\/66bc19e97f956.jpeg\"]', '2024-08-14 09:43:53', '2024-08-14 09:43:53');
INSERT INTO `produk` VALUES (194, 3961, 'Palmcare', '<p>Palmcare merupakan produk perbekalan kesehatan rumah tangga berupa sabun cair untuk kebersihan alat dapur, pakaian dan alat rumah tangga lainnya<br></p>', '[\"public\\/file_foto_produk\\/66bc1bbf54f2a.jpg\"]', '2024-08-14 09:51:43', '2024-08-14 09:51:43');
INSERT INTO `produk` VALUES (195, 3878, 'DNA Kopie', '<p>Kopi yang mengkhususkan diri dalam penyajian kopi berkualitas, baik dari biji kopi utuh maupun kopi giling.<br></p>', '[\"public\\/file_foto_produk\\/66bc1c7756b6d.jpeg\"]', '2024-08-14 09:54:47', '2024-08-14 09:54:47');
INSERT INTO `produk` VALUES (196, 3962, 'Orek Tempe', '<p>Orek Tempe dalam kemasan yang ditujukan untuk mahasiswa kos, ibu bekerja, pelancong. Siap santap, mudah dibawa dan mudah disimpan.<br></p>', '[\"public\\/file_foto_produk\\/66bc1f1fccb2a.jpeg\"]', '2024-08-14 10:06:07', '2024-08-14 10:06:07');
INSERT INTO `produk` VALUES (197, 3962, 'Sambal Lingkung', '<p>Sambal Lingkung dalam kemasan yang ditujukan untuk mahasiswa kos, ibu bekerja, pelancong. Siap santap, mudah dibawa dan mudah disimpan.<br></p>', '[\"public\\/file_foto_produk\\/66bc1f5666a58.jpeg\"]', '2024-08-14 10:07:02', '2024-08-14 10:07:02');
INSERT INTO `produk` VALUES (198, 3962, 'Abon cakalang', '<p>Abon cakalang dalam kemasan yang ditujukan untuk mahasiswa kos, ibu bekerja, pelancong. Siap santap, mudah dibawa dan mudah disimpan.<br></p>', '[\"public\\/file_foto_produk\\/66bc1f838c3d0.jpeg\"]', '2024-08-14 10:07:47', '2024-08-14 10:07:47');
INSERT INTO `produk` VALUES (199, 3963, 'Selai Susu Dairyjam Plus', '<p>selai susu sehat yang berasal dari susu murni asli dan memiliki manfaat dalam mengatasi kekurangan gizi anak<br></p>', '[\"public\\/file_foto_produk\\/66bc2f1c657d4.jpeg\"]', '2024-08-14 11:14:20', '2024-08-14 11:14:20');
INSERT INTO `produk` VALUES (200, 3877, 'Flaksab', '<p>seral yang terbuat dari tepung labu kuning dan beras hitam yang memiliki kandungan zat tertentu sebagai antidiabetes dan anti hiperkolesterol. Selain itu, Flakslab memiliki rasa manis alami dari labu kuning tanpa tambahan gula buatan. Produk ini cocok untuk remaja yang membutuhkan asupan gizi yang cukup dan sehat, serta orang dewasa yang peduli dengan kesehatan.</p>', '[\"public\\/file_foto_produk\\/66bc4ef3da233.jpeg\"]', '2024-08-14 13:30:11', '2024-08-14 13:30:11');
INSERT INTO `produk` VALUES (201, 3969, 'Mentaisiss', '<p>Mentai rice dengan toping ayam karage yang sudah di slice dan di atasnya ditambahkan dengan sauce mentai, mentaisiss ini terbuat dari bahan berkualitas sehingga aman untuk di konsumsi setiap waktu.<br></p>', '[\"public\\/file_foto_produk\\/66bc50bb668a0.jpeg\"]', '2024-08-14 13:37:47', '2024-08-14 13:37:47');
INSERT INTO `produk` VALUES (202, 3879, 'Suka Robot Academy', '<p>Lembaga pendidikan non formal fokus memberikan edukasi bidang robotik dan koding yang dapat membangkitkan daya kreativitas, imajinasi dan inovasi anak&nbsp;<br></p>', '[\"public\\/file_foto_produk\\/66bc52ea004b4.jpeg\"]', '2024-08-14 13:47:06', '2024-08-14 13:47:06');
INSERT INTO `produk` VALUES (203, 3971, 'Prof Dito', '<p>Platform tes Bahasa Indonesia/Asing yang menyediakan berbagai macam jenis soal yang bisa kamu kerjakan.<br></p>', '[\"public\\/file_foto_produk\\/66bc58320cfbf.jpeg\"]', '2024-08-14 14:09:38', '2024-08-14 14:09:38');
INSERT INTO `produk` VALUES (204, 3881, 'AccounTax', '<p>&nbsp;Aplikasi untuk Laporan keuangan UMKM disusun sesuai dengan SAK EMKM. Pelaku UMKM dapat mengetahui PPh terutang atas usahanya menggunakan kalkulator pajak. Pelaku UMKM dapat melakukan pencatatan penjualan dan biaya operasional dengan mudah dan cepat. Pelaku UMKM dapat menyusun laporan keuangan di mana pun dan kapan pun dengan menggunakan handphone.<br></p>', '[\"public\\/file_foto_produk\\/66bc5d7cb1ca5.jpeg\"]', '2024-08-14 14:32:12', '2024-08-14 14:32:12');
INSERT INTO `produk` VALUES (205, 3972, 'buangsampah.com', '<p>Aplikasi Android, yang dapat meningkatkan pendapatan ekonomi masyarakat dari penjualan sampah, menciptakan peluang kerja bagi pengangkut sampah, menciptakan ekonomi sirkular, dengan melibatkan peran serta masyarakat secara massif dan melakukan pengolahan sampah secara berkelanjutan menuju zero waste<br></p>', '[\"public\\/file_foto_produk\\/66bc5f0875aee.jpeg\"]', '2024-08-14 14:38:48', '2024-08-14 14:38:48');
INSERT INTO `produk` VALUES (206, 3973, 'CG Automatic Plant Monitoring System', '<p>Teknologi pemantauan tanaman secara otomatis<br></p>', '[\"public\\/file_foto_produk\\/66bc5fe126758.jpg\"]', '2024-08-14 14:42:25', '2024-08-14 14:42:25');
INSERT INTO `produk` VALUES (207, 3974, 'Rizolles Yummy', '<p>Risol mayones, memiliki cita rasa yang berbeda serta isi lebih banyak.<br></p>', '[\"public\\/file_foto_produk\\/66bc61fe345b8.jpeg\"]', '2024-08-14 14:51:26', '2024-08-14 14:51:26');
INSERT INTO `produk` VALUES (208, 3975, 'HealTiny', '<p>HealTiny merupakan Chicken Salad Roll dimana mengandung unsur hewani dan nabati. Salad dressing dengan varian rasa yang menggugah selera dan dibaluri dengan kulit tortila membuat kombinasi rasa spectacular.</p><p><br></p><p>Dalam satu porsi Chicken Salad Roll terdiri dari:</p><p>1. Dada Ayam Panggang&nbsp;</p><p>2. Saus Creamy</p><p>3. Wortel</p><p>4. Bawang Bombay</p><p>5. Selada</p><p>6. Jagung</p><p>7. Tortila</p>', '[\"public\\/file_foto_produk\\/66bc63f9d0d97.jpeg\"]', '2024-08-14 14:59:53', '2024-08-14 14:59:53');
INSERT INTO `produk` VALUES (209, 3880, 'Tasadai', '<p>Tas yang memiliki 2 (dua) fungsi, fungsi pertama sebagai shoulder bag dan fungsi kedua sebagai totebag. Bentuk awal tas ini adalah sebagai shoulder bag yang memiliki resleting di bagian bawahnya yang jika resleting ini dibuka maka bentuknya akan lebih spacious menjadi totebag.&nbsp; Tas ini dapat digunakan dalam keadaan darurat saat seseorang lupa membawa kantong belanja dan hanya membawa atau memakai tas ini saja. Jadi selain untuk digunakan berpergian sehari-hari dengan barang bawaan tidak terlalu banyak yaitu sebagai shoulder bag tas ini juga memiliki space tambahan sehingga menjadi totebag yang dapat digunakan untuk membawa barang dengan jumlah yang lebih banyak.<br></p>', '[\"public\\/file_foto_produk\\/66bc66b7d656c.jpeg\"]', '2024-08-14 15:11:35', '2024-08-14 15:11:35');
INSERT INTO `produk` VALUES (210, 3976, 'Kenzu', '<p>Cemilan Saus Keju yang tidak bikin eneg, mengandung kalsium, vitamin A, dan vitamin D<br></p>', '[\"public\\/file_foto_produk\\/66bc68d268d0c.jpeg\"]', '2024-08-14 15:20:34', '2024-08-14 15:20:34');
INSERT INTO `produk` VALUES (211, 3977, 'Bebek Mrengkel Yahoohd', NULL, '[\"public\\/file_foto_produk\\/66bc7093d0b50.jpeg\"]', '2024-08-14 15:53:39', '2024-08-14 15:53:39');
INSERT INTO `produk` VALUES (212, 3980, 'Caksana Daycare Plus', '<p>Caksana Daycare Plus adalah tempat penitipan anak usia dini dengan fokus pendidikan, pengasuhan, perawatan, pertumbuhan, dan perkembangan anak dengan berbagai sentra bermain yang dirancang untuk mendukung lima aspek perkembangan: kognitif, sosial-emosional, bahasa, fisik dan motorik.<br></p>', '[\"public\\/file_foto_produk\\/66bc778f80579.jpg\"]', '2024-08-14 16:23:27', '2024-08-14 16:23:27');
INSERT INTO `produk` VALUES (213, 3982, 'Onikitty', '<p>Onikitty adalah inovasi produk makanan kucing yang menggabungkan dua tekstur sekaligus dalam satu bentuk yang menyerupai onigiri dengan bahan tepung maggot black soldier fly<br></p>', '[\"public\\/file_foto_produk\\/66bd74ef84d7f.jpg\"]', '2024-08-15 10:24:31', '2024-08-15 10:24:50');
INSERT INTO `produk` VALUES (214, 3985, 'Praktekin', '<p>Praktekin adalah platform pendidikan digital inovatif yang memberdayakan mahasiswa akhir dan lulusan baru untuk mengembangkan diri, membangun portofolio, dan meraih kesuksesan karier.<br></p>', '[\"public\\/file_foto_produk\\/66bda4ca9a0b5.jpg\"]', '2024-08-15 13:48:42', '2024-08-15 13:48:42');
INSERT INTO `produk` VALUES (215, 978, 'Cecenet', '<p><strong>Paket yang Ditawarkan:</strong></p><ol><li><p><strong>Personal &amp; Event Photography:</strong> Menangkap momen spesial seperti ulang tahun, pre-wedding, wedding, dan acara keluarga.</p></li><li><p><strong>Commercial Photography:</strong> Fotografi produk, fashion, makanan, dan real estate yang membantu bisnis Anda tampil lebih profesional dan menarik di mata pelanggan.</p></li><li><p><strong>Portrait Photography:</strong> Sesi pemotretan pribadi dengan gaya yang sesuai dengan kepribadian Anda, baik di studio maupun lokasi pilihan.</p></li></ol>', '[\"public\\/file_foto_produk\\/66bdbe2db913a.jpg\"]', '2024-08-15 15:37:01', '2024-08-15 15:37:01');
INSERT INTO `produk` VALUES (216, 4102, 'Jamur Nutrisi Malang', NULL, '[\"public\\/file_foto_produk\\/66c2b709ea9ea.jpg\",\"public\\/file_foto_produk\\/66c2b709eabcd.jpg\"]', '2024-08-19 10:07:53', '2024-08-19 10:07:53');
INSERT INTO `produk` VALUES (217, 4103, 'Fajar Music Studio (FMS) Production.', NULL, '[\"public\\/file_foto_produk\\/66c2b99c37950.jpeg\",\"public\\/file_foto_produk\\/66c2b99c37c42.jpeg\",\"public\\/file_foto_produk\\/66c2b99c37d11.jpeg\",\"public\\/file_foto_produk\\/66c2b99c37df2.jpg\"]', '2024-08-19 10:18:52', '2024-08-19 10:18:52');
INSERT INTO `produk` VALUES (218, 4105, 'Shen\'s Bag Souvenir', NULL, '[\"public\\/file_foto_produk\\/66c2c4e763b7a.jpg\",\"public\\/file_foto_produk\\/66c2c4e763ff4.jpg\"]', '2024-08-19 11:07:03', '2024-08-19 11:07:03');
INSERT INTO `produk` VALUES (219, 4104, 'Power Noise Merch', NULL, '[\"public\\/file_foto_produk\\/66c2c552ecf3b.jpg\",\"public\\/file_foto_produk\\/66c2c552ed1bd.jpg\"]', '2024-08-19 11:08:50', '2024-08-19 11:08:50');
INSERT INTO `produk` VALUES (220, 4107, 'Akar Lebat', NULL, '[\"public\\/file_foto_produk\\/66c2c76adc9ca.jpg\",\"public\\/file_foto_produk\\/66c2c76add30b.jpg\",\"public\\/file_foto_produk\\/66c2c76add847.jpg\"]', '2024-08-19 11:17:46', '2024-08-19 11:17:46');
INSERT INTO `produk` VALUES (221, 4115, 'Manajemen Keuangan', '<p>Manajemen Keuangan\r\nMempelajari fungsi dan tanggung jawab manajer keuangan dalam mengelola\r\nsumber daya keuangan perusahaan. Mencakup analisis laporan keuangan, perencanaan dan\r\npenganggaran, pengelolaan modal kerja, penilaian investasi, sumber pendanaan, kebijakan\r\ndividen, serta penerapan konsep nilai waktu uang dalam pengambilan keputusan keuangan\r\nyang optimal<br></p>', '[\"public\\/file_foto_produk\\/66c2eb2220df8.jpeg\"]', '2024-08-19 13:50:10', '2024-08-19 13:51:02');
INSERT INTO `produk` VALUES (222, 4115, 'Analisis Laporan Keuangan', '<p>Analisis Laporan Keuangan\r\nMembahas secara mendalam cara menganalisis laporan keuangan perusahaan,\r\nmeliputi pemahaman tentang komponen-komponen laporan keuangan, teknik analisis rasio,\r\nanalisis tren, serta interpretasi hasil analisis untuk menilai kinerja keuangan dan mengambil\r\nkeputusan bisnis yang tepat.&nbsp;<br></p>', '[\"public\\/file_foto_produk\\/66c2eba614fce.jpeg\"]', '2024-08-19 13:52:22', '2024-08-19 13:52:22');
INSERT INTO `produk` VALUES (223, 4115, 'Analisis Kelayakan Bisnis', '<p>Analisis Kelayakan Bisnis\r\nMembahas metode dan tahapan dalam melakukan studi kelayakan bisnis. Meliputi\r\nanalisis pasar, aspek teknis operasional, manajemen dan sumber daya, hingga penilaian\r\nkelayakan finansial. Menekankan pentingnya mengevaluasi peluang dan risiko sebelum\r\nmemulai usaha baru untuk meningkatkan probabilitas kesuksesan.<br></p>', '[\"public\\/file_foto_produk\\/66c2ec0093dbc.jpeg\"]', '2024-08-19 13:53:52', '2024-08-19 13:53:52');
INSERT INTO `produk` VALUES (224, 4115, 'Manajemen Operasional', '<p>Manajemen Operasional\r\nMempelajari cara mengatur dan mengoptimalkan proses operasional perusahaan, baik\r\nmanufaktur maupun jasa. Mencakup perencanaan kapasitas, tata letak fasilitas, pengendalian\r\npersediaan, penjadwalan produksi, manajemen mutu, dan penerapan konsep lean untuk\r\npeningkatan efisiensi dan produktivitas secara berkelanjutan<br></p>', '[\"public\\/file_foto_produk\\/66c2ec6040585.jpeg\"]', '2024-08-19 13:55:28', '2024-08-19 13:55:28');
INSERT INTO `produk` VALUES (225, 4115, 'Manajemen Pemasaran', '<p>Manajemen Pemasaran\r\nMengkaji konsep dan strategi pemasaran modern untuk menciptakan nilai bagi\r\npelanggan dan membangun keunggulan kompetitif. Membahas aspek perilaku konsumen,\r\nsegmentasi pasar, positioning produk, bauran pemasaran, manajemen hubungan pelanggan,\r\nserta penerapan teknologi digital dalam pemasaran.<br></p>', '[\"public\\/file_foto_produk\\/66c2eca9beefd.jpeg\"]', '2024-08-19 13:56:41', '2024-08-19 13:56:41');
INSERT INTO `produk` VALUES (226, 4115, 'Manajemen SDM', '<p>Manajemen SDM\r\nMempelajari praktik manajemen SDM yang efektif dalam memperoleh,\r\nmengembangkan, dan mempertahankan karyawan berkualitas. Mencakup perencanaan\r\nkebutuhan SDM, rekrutmen, seleksi, pelatihan, sistem kompensasi, penilaian kinerja,\r\nmanajemen talenta, serta pengembangan budaya organisasi yang mendukung\r\nproduktivitas.Mempelajari praktik manajemen SDM yang efektif dalam memperoleh,\r\nmengembangkan, dan mempertahankan karyawan berkualitas. Mencakup perencanaan\r\nkebutuhan SDM, rekrutmen, seleksi, pelatihan, sistem kompensasi, penilaian kinerja,\r\nmanajemen talenta, serta pengembangan budaya organisasi yang mendukung produktivitas.<br></p>', '[\"public\\/file_foto_produk\\/66c2ecf95d984.jpeg\"]', '2024-08-19 13:58:01', '2024-08-19 13:58:01');
INSERT INTO `produk` VALUES (228, 4116, 'Zuriyati Rajut', NULL, '[\"public\\/file_foto_produk\\/66c2fc96dac46.png\"]', '2024-08-19 14:55:11', '2024-08-19 15:04:38');
