INSERT INTO `produk` VALUES (236, 4319, 'Desain foto kolase Wajah 3d Hitam Putih', '<p>Desain foto kolase Wajah 3d dengan request Warna Hitam Putih<br></p>', '[\"public\\/file_foto_produk\\/66d07c4ec21f4.jpg\"]', '2024-08-29 20:49:02', '2024-08-29 20:49:02');
INSERT INTO `produk` VALUES (237, 4354, 'C-REX FARM', NULL, '[\"public\\/file_foto_produk\\/66daa629b3721.jpg\"]', '2024-09-06 13:50:17', '2024-09-06 13:50:17');
INSERT INTO `produk` VALUES (238, 4437, 'PHOTOGRAPHY', '<p><span style=\"font-size: 14px;\">Jasa fotografer adalah pekerjaan profesional yang berfokus dalam dunia seni guna memotret momen dalam bentuk foto menggunakan kamera digital atau analog</span></p><p><span style=\"font-size: 14px;\">kami mengambil foto orang, lokasi, serta objek untuk merekam peristiwa tertentu dan menceritakan kisahnya menggunakan gambar.</span></p>', '[\"public\\/file_foto_produk\\/66e5780bef756.jpg\"]', '2024-09-14 18:48:27', '2024-09-14 18:48:27');
INSERT INTO `produk` VALUES (240, 4439, 'Perikanan NUH', '<p><span style=\"font-size: 14px;\">Usaha perikanan adalah kegiatan yang dilakukan dengan sistem bisnis perikanan, yang&nbsp;</span></p><p><span style=\"font-size: 14px;\">meliputi: Praproduksi, Produksi, Pengolahan, Pascaproduksi, Pemasaran</span></p>', '[\"public\\/file_foto_produk\\/66e58b7902405.jpg\"]', '2024-09-14 20:11:21', '2024-09-14 20:11:21');
INSERT INTO `produk` VALUES (241, 4440, 'Kantin Sekolah', '<p><span style=\"font-size: 14px;\">Kantin sekolah khusus untuk menyediakan ,atk foto copy, makanan dan minuman kepada</span></p><p><span style=\"font-size: 14px;\">siswa selama jam istirarahat atau waktu makan.biasanya ,kantin terletak diarea yang</span></p><p><span style=\"font-size: 14px;\">mudah diakses oleh semua siswa.</span></p>', '[\"public\\/file_foto_produk\\/66e58d14f092e.jpg\"]', '2024-09-14 20:17:33', '2024-09-14 20:18:12');
INSERT INTO `produk` VALUES (242, 4441, 'Peternakan Rifai', '<div><font style=\"vertical-align: inherit;\">Usaha peternak dan pembudidaya sapi adalah usaha yg sistem kerjanya adalah</font></div><div><font style=\"vertical-align: inherit;\">pengembangan dan penggemukan</font></div><div><font style=\"vertical-align: inherit;\">Untuk sapi sapi yg sifatnya di bidang penggemukan yg sudah ADG nya sudah target maka</font></div><div><font style=\"vertical-align: inherit;\">sudah siap untuk dikeluarkan atau dijual</font></div><div><font style=\"vertical-align: inherit;\">Untuk pengembangan sapi \' dari kami fokus ke babonan sapi atau indukan sapi yg mana</font></div><div><font style=\"vertical-align: inherit;\">dari babon babon tersebut untuk peranakan</font></div><div><font style=\"vertical-align: inherit;\">Dan untuk pengembangan dari sini dapat memudahkan konsumen agar mudah</font></div><div><font style=\"vertical-align: inherit;\">mendapatkan bibit bibit sapi yang unggul</font></div><div><br></div>', '[\"public\\/file_foto_produk\\/66e58f981a037.jpg\"]', '2024-09-14 20:28:56', '2024-09-14 21:49:14');
INSERT INTO `produk` VALUES (243, 4442, 'Kebun Berkah Tani', '<p><span style=\"font-size: 14px;\">Kebun Berkah Tani adalah bisnis yang berjalan di bidang pembibitan tanaman, khususnya tanaman alpukat. Mulanya Kebun Berkah Tani bergerak sebagai reseller bibit buah- buahan. Kami menjual segala macam bibit tanaman, seperti jeruk, durian, kelengkeng, jambu</span></p><p><span style=\"font-size: 14px;\">air, jambu biji, manggis, dll. Dari sini kami menyadari bahwa bisnis tanaman sangat</span></p><p><span style=\"font-size: 14px;\">menguntungkan dan seharusnya ada “sesuatu” yang dapat dikembangkan sendiri, yakni</span></p><p><span style=\"font-size: 14px;\">produksi bibit. Kami mulai riset dan menemukan banyak sekali biji alpukat di daerah kami, dan</span></p><p><span style=\"font-size: 14px;\">hal inilah yang mendasari Kebun Berkah Tani untuk memutuskan memproduksi bibit alpukat. Terlebih di Banyuwangi belum ada produsen bibit tanaman. Seluruh lapak yang ada di sini rata</span></p><p><span style=\"font-size: 14px;\">-rata bibit dari produsen luar daerah. Tentu ini merupakan kesempatan, juga peluang. Berkah</span></p><p><span style=\"font-size: 14px;\">Tani ingin menjadi perintis produsen bibit alpukat di Banyuwangi, dan harapan besar kami, suatu saat Berkah Tani bisa melebarkan sayap, memiliki produk turunan lain seperti menjual</span></p><p><span style=\"font-size: 14px;\">buah alpukat, minuman alpukat, dan sejenisnya, agar bisa berdampak bagi sosial-ekonomi</span></p><p><span style=\"font-size: 14px;\">masyarakat sekaligus menjadi lapangan kerja.</span></p>', '[\"public\\/file_foto_produk\\/66e613ffbf53c.jpg\"]', '2024-09-15 05:53:51', '2024-09-15 05:54:39');
INSERT INTO `produk` VALUES (244, 4443, 'Toko Plastik', '<p><span style=\"font-size: 14px;\">1. Deskripsi Usaha</span></p><p><span style=\"font-size: 14px;\">Harga fleksibel, bisa beli ecera, mudah di dapat untuk kebutuhan sehari2</span></p>', '[\"public\\/file_foto_produk\\/66e672ad01bbf.jpg\"]', '2024-09-15 12:37:49', '2024-09-15 12:37:49');
INSERT INTO `produk` VALUES (245, 4444, 'Warung Sembako', '<p><span style=\"font-size: 14px;\">Warung menyediakan produk lokal dengan harga terjangkau, terletak di lokasi yang</span></p><p><span style=\"font-size: 14px;\">strategis,dan menawarkan pelayanan personal. Warung bisa menjual berbagai barang ,mulai</span></p><p><span style=\"font-size: 14px;\">dari makanan dan minuman hingga kebutuhan sehari-hari</span></p>', '[\"public\\/file_foto_produk\\/66e67446ee747.jpg\"]', '2024-09-15 12:44:38', '2024-09-15 12:44:38');
INSERT INTO `produk` VALUES (246, 4445, 'Usaha KONPEKSI', '<p><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Bahasa Inggris: KONPEKSI MANDIRI&nbsp;</font></font></p>', '[\"public\\/file_foto_produk\\/66e6758c20ae8.jpeg\"]', '2024-09-15 12:49:41', '2024-09-15 12:50:04');
INSERT INTO `produk` VALUES (247, 4446, 'Warung Sembako', '<p><span style=\"font-size: 14px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Saya menjual berbagai sembako dari mulai beras lauk pauk sayuran di tambah snack dan jajanan anak juga di tambah berbagai pupuk untuk pertanian dan pestisida</font></font></span></p>', '[\"public\\/file_foto_produk\\/66e690299bcf0.jpg\"]', '2024-09-15 14:43:37', '2024-09-15 14:43:37');
INSERT INTO `produk` VALUES (249, 4549, 'TENUN IKAT', '<p>Tenun Ikat Panataran merupakan kain tradisional Indonesia yang dibuat dengan teknik tenun ikat, di mana benang-benang yang akan ditenun diikat terlebih dahulu pada pola tertentu, kemudian dicelupkan dalam pewarna alami sebelum dipintal menjadi kain. Proses ini menghasilkan motif yang khas dan unik, dengan perpaduan warna yang elegan serta tekstur yang halus namun kuat. Produk ini dirancang dengan filosofi yang mendalam, mengangkat nilai-nilai tradisi dan seni dari para pengrajin lokal.</p><p><strong>Keunggulan Produk:</strong></p><ol><li><p><strong>Desain Unik dan Eksklusif:</strong> Setiap kain tenun ikat Panataran memiliki pola dan motif yang tidak bisa diduplikasi secara massal, sehingga setiap potong kain adalah karya seni yang unik. Motif-motif terinspirasi dari budaya lokal Blitar dan sejarah Candi Panataran.</p></li><li><p><strong>Kualitas Tinggi:</strong> Terbuat dari bahan-bahan alami seperti kapas atau sutra dengan pewarna alami yang ramah lingkungan, kain tenun ikat Panataran tidak hanya nyaman digunakan tetapi juga tahan lama.</p></li><li><p><strong>Proses Pembuatan Tradisional:</strong> Setiap lembar tenun dibuat dengan tangan oleh para penenun terampil, menjaga keaslian teknik tradisional yang telah diwariskan dari generasi ke generasi.</p></li><li><p><strong>Ramah Lingkungan:</strong> Pewarna yang digunakan dalam proses ikat ini berasal dari bahan-bahan alami yang tidak berbahaya bagi lingkungan, mendukung praktik berkelanjutan dalam industri tekstil.</p></li></ol><p><strong>Pilihan Warna dan Motif:</strong><br>Tenun Ikat Panataran hadir dalam berbagai pilihan warna alami seperti indigo, coklat tanah, merah marun, dan hijau daun, dengan motif yang bervariasi mulai dari geometris, flora, hingga motif klasik khas daerah Blitar. Motif-motif ini mencerminkan keindahan alam dan budaya lokal, memberikan nilai estetika yang tinggi pada setiap kain.</p><p><strong>Kegunaan:</strong><br>Kain tenun ikat Panataran dapat digunakan untuk berbagai keperluan, antara lain:</p><ul><li><strong>Fashion:</strong> Pakaian tradisional, gaun, syal, kemeja, dan rok.</li><li><strong>Aksesoris:</strong> Sarung, selendang, tas, dan aksesoris lainnya.</li><li><strong>Dekorasi Rumah:</strong> Kain hias, taplak meja, gorden, dan sarung bantal yang memberikan sentuhan etnik dan elegan pada interior.</li></ul><p><strong>Ukuran:</strong><br>Tersedia dalam berbagai ukuran yang dapat disesuaikan dengan kebutuhan, baik untuk kain utuh maupun potongan sesuai pesanan pelanggan.</p><p><strong>Harga:</strong><br>Harga produk tenun ikat Panataran bervariasi sesuai dengan tingkat kesulitan motif, ukuran kain, dan jenis bahan yang digunakan.</p>', '[\"public\\/file_foto_produk\\/66ef6dc24f4ca.png\"]', '2024-09-22 08:07:14', '2024-09-22 08:07:14');
INSERT INTO `produk` VALUES (250, 4614, 'Lilin Aromatherapy dari Gaun Gaharu', '<p>Lilin aromatherapy merupakan produk hasil penelitian mahasiswa dengan memanfaatkan daun gaharu sebagai bahan dalam pembuatan lilin aromatherapy.&nbsp;</p>', '[\"public\\/file_foto_produk\\/66fb87dc7529b.jpg\"]', '2024-10-01 12:25:48', '2024-10-01 12:25:48');
INSERT INTO `produk` VALUES (251, 4614, 'Roncean Melati dari Tissue', '<p>Produk roncean melati merupakan produk hasil penelitian mahasiswa dengan memanfaatkan tissue sebagai bahan dalam pembuatan pembuatan kuncup melati yang kemudian dirangkai dengan teknik tertentu sehingga dapat digunakan sebagai aksesoris tambahan pada tampilan pengantin.&nbsp;<br></p>', '[\"public\\/file_foto_produk\\/66fb8860eb3dc.jpg\"]', '2024-10-01 12:28:00', '2024-10-01 12:28:00');
INSERT INTO `produk` VALUES (252, 4615, 'Tahu Gimbal', '<p>Tahu gimbal merupakan jenis salad Indonesia yang terdiri dari tahu, gimbal udang, telur, lontong, dan saus kacang. Tersedia level rasa pedas, sedang, dan tidak pedas. Harga Rp 25.000</p>', '[\"public\\/file_foto_produk\\/66fba20488435.jpg\"]', '2024-10-01 14:17:24', '2024-10-01 14:31:40');
INSERT INTO `produk` VALUES (253, 4615, 'Lontong Sayur', '<p>Hanya Rp 20.000 lontong sayur spesial isian lontong, tahu, suwiran ayam, sayur jipan, telur dan krupuk sudah dapat diorder untuk menemani jamuan makanmu.&nbsp;</p>', '[\"public\\/file_foto_produk\\/66fba3eecdc16.jpg\"]', '2024-10-01 14:25:34', '2024-10-01 14:25:34');
INSERT INTO `produk` VALUES (254, 4615, 'Caramel Machiato', '<p>Melepas dahaga dengan kesegaran Caramel Machiato, hanya Rp 10.000 perbotol. Grab fast !</p>', '[\"public\\/file_foto_produk\\/66fbaa38d9864.jpg\"]', '2024-10-01 14:52:24', '2024-10-01 14:52:24');
INSERT INTO `produk` VALUES (255, 4614, 'Aksesoris Pengantin Semarangan dari Limbah Kaleng Biskuit', '<p>Aksesoris Pengantin Semarangan merupakan produk hasil penelitian mahasiswa dengan memanfaatkan limbah kaleng biskuit sebagai bahan dalam pembuatan aksesoris&nbsp;<br></p>', '[\"public\\/file_foto_produk\\/66fbab6ae229e.jpg\"]', '2024-10-01 14:57:30', '2024-10-01 14:57:30');
