INSERT INTO `produk` VALUES (310, 5091, 'KAOS KARAKTER LUKISAN BALI HANOMAN', '<p>Dari kaos pilihan dengan KARAKTER LUKISAN BALI HANOMAN</p>', '[\"public\\/file_foto_produk\\/676d67722b3f3.jpg\"]', '2024-12-26 21:25:54', '2024-12-26 21:25:54');
INSERT INTO `produk` VALUES (311, 5090, 'HYPNOTERAPY', '<p>Memberikan jasa layanan kesehatan mental dengan hypnoterapy</p>', '[\"public\\/file_foto_produk\\/676dd6d7837a9.jpg\"]', '2024-12-27 05:21:11', '2024-12-27 05:21:11');
INSERT INTO `produk` VALUES (312, 4202, 'Gendhes Manis Gula Aren Kristal', '<p><span id=\"docs-internal-guid-56ba3f7a-7fff-8c09-02d2-146f55c3cb94\"><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">Gendhes Manis Gula Aren Kristal adala gula yang dihasilkan dari nira atau sari cair kelapa. </span></span><span style=\"background-color: transparent; color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;, serif; font-size: 12pt; white-space-collapse: preserve;\">Proses produksi gula aren kristal menggunakan 100% bahan alami dan juga tidak menambah bahan kimia berbahaya. Dengan bahan baku utama Nira Aren yang diambil dari hasi panen kebun pribadi dan masyarakat</span></p>', '[\"public\\/file_foto_produk\\/67756ba393ca8.jpeg\"]', '2025-01-01 23:21:55', '2025-01-01 23:21:55');
INSERT INTO `produk` VALUES (313, 4214, 'Bakpia Khilma', '<p>Bakpia Khilma, camilan lezat dengan 5 varian rasa: Kacang Hijau, Ubi Ungi, Keju, Coklat, dan Pandan. Terbuat dari bahan alami, halal, dan memiliki tekstur yang enak serta gurih.</p>', '[\"public\\/file_foto_produk\\/67756ee314157.jpeg\"]', '2025-01-01 23:34:44', '2025-01-01 23:35:47');
INSERT INTO `produk` VALUES (314, 4214, 'Bakpia Khilma', NULL, '[\"public\\/file_foto_produk\\/67756f37c18b5.jpeg\"]', '2025-01-01 23:36:50', '2025-01-01 23:37:11');
INSERT INTO `produk` VALUES (315, 4203, 'Jamu Jeng Wulan', '<p>Jamu Jeng Wulan menggunakan bahan baku pilihan dari alam dan masih mempertahankan proses produksi secara tradisional menjadi salah satu keunggulan dari Jamu Jeng Wulan, sehingga rasa dan aroma yang muncul terasa khas. Jamu Jeng Wulan tesedia dalam kemasan pouch, thinwall dan kemasan botol siap minum.</p>', '[\"public\\/file_foto_produk\\/677571cd73bcf.jpeg\"]', '2025-01-01 23:48:13', '2025-01-01 23:48:13');
INSERT INTO `produk` VALUES (317, 4208, 'Erka Interior', '<p>Erika Interior menjual bahan baku interior premium dengan desain yang Anda inginkan.</p>', '[\"public\\/file_foto_produk\\/67757fb3b7a3c.jpeg\"]', '2025-01-02 00:47:31', '2025-01-02 00:47:31');
INSERT INTO `produk` VALUES (318, 5340, 'Muya muya', '<p>Muya muya ceriping pisang dengan rasa manis yang lezat tanpa tambahan bahan pengawet yang berbahaya</p>', '[\"public\\/file_foto_produk\\/677581d65a967.jpeg\"]', '2025-01-02 00:54:43', '2025-01-02 00:56:38');
INSERT INTO `produk` VALUES (319, 5341, 'Geblek Tambak Mbah Toipah', NULL, '[\"public\\/file_foto_produk\\/67758388d0c24.jpeg\"]', '2025-01-02 01:03:24', '2025-01-02 01:03:52');
INSERT INTO `produk` VALUES (320, 4204, 'Sulung Craft', '<p><span style=\"color: rgb(33, 37, 41);\">Sulung Craft adalah usaha yang memproduksi Kerajinan Batok Kelapa - Produk unik dan ramah lingkungan. Mengubah limbah menjadi karya seni yang indah dan fungsional.</span></p>', '[\"public\\/file_foto_produk\\/677585257e25c.png\"]', '2025-01-02 01:10:45', '2025-01-02 01:10:45');
INSERT INTO `produk` VALUES (321, 4201, 'Abon Lele', '<p>Abon Ikan Lele - Lezat, gurih, dan kaya protein. Terbuat dari ikan lele segar, tanpa bahan tambahan berbahaya.</p>', '[\"public\\/file_foto_produk\\/6775881c6dfc6.jpeg\"]', '2025-01-02 01:23:24', '2025-01-02 01:23:24');
INSERT INTO `produk` VALUES (322, 4201, 'Stik Ikan Lele', '<p>Stik Ikan Lele - Camilan lezat dan sehat! Terbuat dari ikan lele segar, tanpa bahan tambahan berbahaya. Kaya protein, rendah kalori</p>', '[\"public\\/file_foto_produk\\/6775885402fb3.jpeg\"]', '2025-01-02 01:24:20', '2025-01-02 01:24:20');
INSERT INTO `produk` VALUES (323, 5343, 'Aranjo Palm Sugar - Gula Aren Semut', '<p>Gula Aren Semut 100% aslidari bahan berkualitas</p>', '[\"public\\/file_foto_produk\\/6775ffcd648f1.jpeg\"]', '2025-01-02 09:54:05', '2025-01-02 09:54:05');
INSERT INTO `produk` VALUES (325, 4209, 'Keranjang Hantaran', '<p>Keranjang Hantaran Bambu adalah pilihan sempurna untuk acara pernikahan, ulang tahun, atau hadiah spesial. Terbuat dari bambu alami, keranjang ini menawarkan keunikan dan keindahan</p>', '[\"public\\/file_foto_produk\\/677602335a579.jpeg\"]', '2025-01-02 10:04:19', '2025-01-02 10:04:19');
INSERT INTO `produk` VALUES (326, 4209, 'Rantang Bambu', '<p>Rantang Bambu&nbsp;dirancang dengan sentuhan tradisional dan modern, cocok untuk segala acara. Bahan bambu yang ramah lingkungan menjamin kelestarian alam</p>', '[\"public\\/file_foto_produk\\/6776033c29b35.jpeg\"]', '2025-01-02 10:08:44', '2025-01-02 10:08:44');
INSERT INTO `produk` VALUES (327, 4209, 'Aneka Tas, Box  dan Keranjang Bambu', '<p>Kerajinan Bambu dirancang dengan sentuhan tradisional dan modern, cocok untuk segala acara. Bahan bambu yang ramah lingkungan menjamin kelestarian alam</p>', '[\"public\\/file_foto_produk\\/6776062fb1878.jpeg\"]', '2025-01-02 10:21:19', '2025-01-02 10:21:19');
INSERT INTO `produk` VALUES (328, 5353, 'Wayang Batik - Wijaya Craft', NULL, '[\"public\\/file_foto_produk\\/677726aa2bbe3.jpeg\"]', '2025-01-03 06:52:10', '2025-01-03 06:52:10');
INSERT INTO `produk` VALUES (329, 5098, 'POPOK KAIN RAMAH LINGKUNGAN', '<p>Popok Kain ramah lingkungan.&nbsp;</p><p>Terbuat dari bahan kain katun yg lembut sehingga tidak menyebabkan iritasi pada kulit.&nbsp;</p><p>Bahan serap dari handuk dan tidak mengandung bahan kimia.&nbsp;</p><p>Mengurangi penumpukan sampah residu karena dapat dicuci berkali-kali.&nbsp;</p><p>Pemakaian lebih dari 3 tahun, sehingga dapat menghemat pengeluaran.</p>', '[\"public\\/file_foto_produk\\/677746f8bc717.jpg\"]', '2025-01-03 09:10:00', '2025-01-03 09:10:00');
INSERT INTO `produk` VALUES (330, 5105, 'KOTAK TISSUE', '<p>Terbuat dari Produk tutup air minteral tak terpakai di olah menjadi produk kotak Tissue yang berdaya guna</p>', '[\"public\\/file_foto_produk\\/6777483b5ecdc.jpg\"]', '2025-01-03 09:15:23', '2025-01-03 09:17:55');
INSERT INTO `produk` VALUES (331, 5105, 'NAME BADGE RECYCLE', '<p>Terbuat dari sisa produk tutup galon tak terpakai diolah menjadi produk namebadge yang unik</p>', '[\"public\\/file_foto_produk\\/677748763ce03.jpg\"]', '2025-01-03 09:16:22', '2025-01-03 09:16:22');
INSERT INTO `produk` VALUES (332, 5105, 'STANDING HP', '<p>Terbuat dari recycle produk plastik dari tutup air mineral dll menjadi produk unik untuk standing hp</p>', '[\"public\\/file_foto_produk\\/677748c057f24.jpg\"]', '2025-01-03 09:17:36', '2025-01-03 09:17:36');
INSERT INTO `produk` VALUES (333, 5105, 'BANGKU karakter', '<p>Terbuat dari bahan recycle plastik yang diolah dengan sentuhan seni menghasilkan produk bangku yang unik bagus untuk digunakan di kebun rumah, cafe dsb</p>', '[\"public\\/file_foto_produk\\/6777494a387f9.jpg\"]', '2025-01-03 09:19:54', '2025-01-03 09:19:54');
INSERT INTO `produk` VALUES (334, 5105, 'aneka Kursi dan Meja', '<p>Produk bisa di order sesusai pesanan dan kesepakatan terbuat dari bahan recycle yang bermanfaat&nbsp;</p>', '[\"public\\/file_foto_produk\\/6777499013a1a.jpg\"]', '2025-01-03 09:21:04', '2025-01-03 09:21:04');
INSERT INTO `produk` VALUES (335, 5094, 'JASA CUKUR \"HomeService\"', '<p>Menyediakan Jasa Potong Rambut siap on call di tempat customer dengan pelayanan ramah dan profesional sehingga customer puas</p>', '[\"public\\/file_foto_produk\\/67774b3b3c5ff.jpg\"]', '2025-01-03 09:28:11', '2025-01-03 09:28:11');
INSERT INTO `produk` VALUES (336, 5107, 'Buku Bekas dari Banyak Genre', '<p>Menjual Buku-buku bekas dari banyak genre baik karya sastra, filsafat, psikologi,spiritual, parenting, motivasi kehidupan dan buku anak2</p>', '[\"public\\/file_foto_produk\\/6779a9f3aec6f.jpg\"]', '2025-01-05 04:36:51', '2025-01-05 04:37:11');
INSERT INTO `produk` VALUES (337, 5097, 'LELE SEGAR', '<p>Produk usaha top fish farm adalah ikan lele segar yg di budidaya menggunakan metode bioflok yg mampu menghasilkan daging yg lebih tebal, bersih dan tidak bau amis</p>', '[\"public\\/file_foto_produk\\/6779aaa2ada68.jpg\"]', '2025-01-05 04:39:46', '2025-01-05 04:39:46');
INSERT INTO `produk` VALUES (338, 5095, 'JIMBA - TOPI', '<p>Topi yang terbuat dari bahan tenun pilihan di design dengan sentuhan karya seni sehingga menghasilkan karya topi yang unik, modern dan kekinian</p>', '[\"public\\/file_foto_produk\\/6779ac1beb157.png\"]', '2025-01-05 04:45:40', '2025-01-05 04:47:29');
INSERT INTO `produk` VALUES (339, 5095, 'TUMBLER HOLDER', '<p>Terbuat dari bahan tenun pilihan yang di design dengan sentuhan seni disesuaikan dengan tumbler menghasilkan tumbler holder yang unik, modis dengan design yang modern</p>', '[\"public\\/file_foto_produk\\/6779acdca275b.png\"]', '2025-01-05 04:49:16', '2025-01-05 04:49:16');
INSERT INTO `produk` VALUES (340, 5095, 'TAS MAURA', '<p>Dibuat dari tenun pilihan dengan sentuhan seni yang artistik dan modern sehingga menjadi sebuah karya yang stylish dan modern</p>', '[\"public\\/file_foto_produk\\/6779ad2c54bd5.png\"]', '2025-01-05 04:50:36', '2025-01-05 04:50:36');
