INSERT INTO `produk` VALUES (348, 5461, 'Rimpi Pisang', '<p>R<span style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\">Rimpi pisang adalah&nbsp;</span><mark class=\"QVRyCf\" style=\"background: var(--m3c22); border-radius: 4px; padding: 0px 2px; font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\">makanan khas Kalimantan yang terbuat dari buah pisang yang dijemur atau diasapi untuk mengurangi kadar airnya</mark><span style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\">.</span></p>', '[\"public\\/file_foto_produk\\/6786200514a7b.JPG\"]', '2025-01-14 15:26:23', '2025-01-14 15:27:49');
INSERT INTO `produk` VALUES (349, 5407, 'Kacang Telor', '<p><span data-huuid=\"13062476667659123775\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\"><mark class=\"QVRyCf\" style=\"background: var(--m3c22); border-radius: 4px; padding: 0px 2px;\">camilan yang terbuat dari kacang tanah yang dibalut dengan adonan tepung dan telur</mark>.&nbsp;</span><span data-huuid=\"13062476667659124014\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\">Kacang telur memiliki rasa gurih dan renyah, serta cocok disantap saat bersantai&nbsp;</span></p>', '[\"public\\/file_foto_produk\\/67862560e6a41.JPG\"]', '2025-01-14 15:50:40', '2025-01-14 15:50:40');
INSERT INTO `produk` VALUES (350, 5462, 'Cantik Manis', '<p>Kue Cantik Manis&nbsp;</p>', '[\"public\\/file_foto_produk\\/6786276edef2a.jpg\"]', '2025-01-14 15:59:26', '2025-01-14 15:59:26');
INSERT INTO `produk` VALUES (351, 5408, 'Dodol Kandangan  - Kurnia', '<p><b style=\"color: rgb(32, 33, 34); font-family: sans-serif; font-size: 16px;\">Dodol Kandangan</b><span style=\"color: rgb(32, 33, 34); font-family: sans-serif; font-size: 16px;\">&nbsp;adalah makanan khas produksi masyarakat Kandangan, Hulu Sungai Selatan</span><span style=\"color: rgb(32, 33, 34); font-family: sans-serif; font-size: 16px;\">, secara turun temurun. Bahan utama pembuatan penganan ini adalah beras ketan dan gula aren.</span></p>', '[\"public\\/file_foto_produk\\/6786284a2d8b5.jpg\"]', '2025-01-14 16:03:06', '2025-01-14 16:03:06');
INSERT INTO `produk` VALUES (352, 5446, 'Dodol Kandangan', '<p><b style=\"color: rgb(32, 33, 34); font-family: sans-serif; font-size: 16px;\">Dodol Kandangan</b><span style=\"color: rgb(32, 33, 34); font-family: sans-serif; font-size: 16px;\">&nbsp;adalah makanan khas produksi masyarakat Kandangan, Hulu Sungai Selatan</span><span style=\"color: rgb(32, 33, 34); font-family: sans-serif; font-size: 16px;\">&nbsp;secara turun temurun. Bahan utama pembuatan penganan ini adalah beras ketan dan gula aren.</span></p>', '[\"public\\/file_foto_produk\\/6786293c093ba.JPG\"]', '2025-01-14 16:07:08', '2025-01-14 16:07:08');
INSERT INTO `produk` VALUES (353, 5446, 'Kue Gapit', '<div class=\"WaaZC\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\"><div class=\"RJPOee EIJn2\" style=\"animation: auto ease 0s 1 normal none running none !important; color: var(--m3c11);\"><div class=\"rPeykc\" data-hveid=\"CAYQAQ\" data-ved=\"2ahUKEwiri6ur7vSKAxUWwTgGHQVsPeMQo_EKegQIBhAB\" style=\"margin-bottom: 20px;\"><span data-huuid=\"15449148215180721696\">Kue gapit Kandangan adalah&nbsp;<mark class=\"QVRyCf\" style=\"background: var(--m3c22); border-radius: 4px; padding: 0px 2px;\">kue khas Kandangan yang merupakan cemilan tradisional </mark>.&nbsp;</span><span data-huuid=\"15449148215180721547\">Kue ini terbuat dari tepung, telur, dan gula pasir.<span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"121a8e07-6df2-4a0c-ab0d-507286d8b50d\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></span></div><div class=\"rPeykc\" data-hveid=\"CAYQAQ\" data-ved=\"2ahUKEwiri6ur7vSKAxUWwTgGHQVsPeMQo_EKegQIBhAB\" style=\"margin-bottom: 20px;\"><span data-huuid=\"15449148215180721547\"><span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"121a8e07-6df2-4a0c-ab0d-507286d8b50d\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\"><br></span></span></span><span style=\"color: var(--m3c11);\">Kue gapit memiliki bentuk pipih dan bulat, dan sekilas mirip dengan kue simping.</span><span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"7312faa5-4f51-4a4e-a917-d00a7a9143dd\" jsaction=\"rcuQ6b:npT2md\" style=\"color: var(--m3c11);\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></div></div></div>', '[\"public\\/file_foto_produk\\/678629a077f6a.JPG\"]', '2025-01-14 16:08:48', '2025-01-14 16:08:48');
INSERT INTO `produk` VALUES (354, 5447, 'Kue Satu', '<div class=\"WaaZC\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 18px;\"><div class=\"RJPOee EIJn2\" style=\"animation: auto ease 0s 1 normal none running none !important; color: var(--m3c11);\"><div class=\"rPeykc\" data-hveid=\"CAgQAQ\" data-ved=\"2ahUKEwio9sbt7vSKAxVQSWwGHYG2AGgQo_EKegQICBAB\" style=\"margin-bottom: 20px;\"><span data-huuid=\"13507267803081821998\">Kue satu adalah&nbsp;<mark class=\"QVRyCf\" style=\"background: var(--m3c22); border-radius: 4px; padding: 0px 2px;\">kue kering tradisional yang terbuat dari kacang hijau dan gula pasir</mark>.&nbsp;</span></div><div class=\"rPeykc\" data-hveid=\"CAgQAQ\" data-ved=\"2ahUKEwio9sbt7vSKAxVQSWwGHYG2AGgQo_EKegQICBAB\" style=\"margin-bottom: 20px;\"><span data-huuid=\"13507267803081820109\" style=\"color: var(--m3c11);\">Kue satu memiliki ciri-ciri:&nbsp;</span><span data-huuid=\"873292189518887097\" style=\"color: var(--m3c11);\">Berwarna putih, Bertekstur renyah dan sedikit keras, Kaya serat dan protein, Lumer di mulut, Awet disimpan lama</span></div></div></div>', '[\"public\\/file_foto_produk\\/67862a43399bd.JPG\"]', '2025-01-14 16:11:31', '2025-01-14 16:11:31');
