INSERT INTO `produk` VALUES (406, 5480, 'Wedang Celup Bunga Telang', '<p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\">Minuman herbal\r\nberwarna biru alami yang kaya akan antioksidan. Bunga Telang dikenal sebagai\r\nminuman sehat dengan rasa ringan yang cocok untuk segala usia.<br>\r\n<strong>Komposisi</strong>:<o:p></o:p></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Bunga\r\n     Telang Alami<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Jahe<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Serai<o:p></o:p></span></li>\r\n</ul><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n115%\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\"><strong>Manfaat</strong>:<o:p></o:p></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Membantu\r\n     meningkatkan daya tahan tubuh.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Kaya\r\n     antioksidan untuk membantu melawan radikal bebas.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Menenangkan\r\n     pikiran dengan rasa ringan dan aroma floral yang lembut.<o:p></o:p></span></li>\r\n</ul><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\"><strong>Catatan</strong>:\r\nTambahkan perasan lemon untuk menghasilkan warna ungu yang memukau.<o:p></o:p></p>', '[\"public\\/file_foto_produk\\/6796ef8a2b6e5.jpg\"]', '2025-01-27 09:29:30', '2025-01-27 09:29:30');
INSERT INTO `produk` VALUES (407, 5480, 'Wedang Celup Teh Sereh', '<p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\">Minuman herbal\r\nyang menyegarkan dengan aroma serai yang khas. Pilihan tepat untuk dinikmati\r\nhangat atau dingin.<br>\r\n<!--[if !supportLineBreakNewLine]--><br>\r\n<!--[endif]--><strong><o:p></o:p></strong></p><p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\"><strong>Komposisi</strong>:<o:p></o:p></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l3 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Serai\r\n     Segar<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l3 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Teh\r\n     Hitam<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l3 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Jahe<o:p></o:p></span></li>\r\n</ul><p class=\"MsoNormal\" style=\"margin-top:0cm;margin-right:0cm;margin-bottom:0cm;\r\nmargin-left:18.0pt;margin-bottom:.0001pt;line-height:115%\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\"><strong>Manfaat</strong>:<o:p></o:p></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l1 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Membantu\r\n     melancarkan pencernaan.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l1 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Mengurangi\r\n     rasa lelah dengan sensasi menyegarkan.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l1 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Kaya\r\n     akan zat alami untuk menjaga kesehatan tubuh.<o:p></o:p></span></li>\r\n</ul><div class=\"MsoNormal\" align=\"center\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;\r\ntext-align:center;line-height:115%\"><span style=\"font-size:12.0pt;line-height:\r\n115%;font-family:&quot;Times New Roman&quot;,serif\">\r\n\r\n<hr size=\"2\" width=\"100%\" align=\"center\">\r\n\r\n</span></div><h3 style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Keunggulan Weeka Teh Celup</span></strong><span style=\"font-size:12.0pt;line-height:115%\">:<o:p></o:p></span></h3><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo3;tab-stops:list 36.0pt\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Higienis&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong><span style=\"font-size:\r\n     12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">: Diproses\r\n     dengan standar kebersihan tinggi.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo3;tab-stops:list 36.0pt\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Praktis&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong><span style=\"font-size:\r\n     12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">: Teh celup\r\n     yang mudah disajikan kapan saja.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo3;tab-stops:list 36.0pt\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Tahan Lama&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">:\r\n     Dikemas modern untuk menjaga kesegaran lebih lama.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l0 level1 lfo3;tab-stops:list 36.0pt\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Alami dan Sehat&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">:\r\n     Tanpa bahan pengawet dan pewarna buatan.<o:p></o:p></span></li>\r\n</ul><div class=\"MsoNormal\" align=\"center\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;\r\ntext-align:center;line-height:115%\"><span style=\"font-size:12.0pt;line-height:\r\n115%;font-family:&quot;Times New Roman&quot;,serif\">\r\n\r\n<hr size=\"2\" width=\"100%\" align=\"center\">\r\n\r\n</span></div><h3 style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Cara Penyajian</span></strong><span style=\"font-size:12.0pt;line-height:115%\">:<o:p></o:p></span></h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l2 level1 lfo4;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Masukkan\r\n     1 sachet teh celup ke dalam cangkir (takr gula sesuai selera).<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l2 level1 lfo4;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Tambahkan\r\n     180-200 ml air panas.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l2 level1 lfo4;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Diamkan\r\n     selama 3-5 menit hingga warna dan aroma keluar sempurna.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l2 level1 lfo4;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">Sajikan\r\n     hangat atau tambahkan es untuk sensasi segar.<o:p></o:p></span></li>\r\n</ol>', '[\"public\\/file_foto_produk\\/6796efa9e5554.jpg\"]', '2025-01-27 09:30:01', '2025-01-27 09:30:01');
INSERT INTO `produk` VALUES (408, 5480, 'Telang Seruni', '<p style=\"margin:0cm;margin-bottom:.0001pt;line-height:115%\">Hadirkan keajaiban\r\nwarna, rasa, dan manfaat dalam satu cangkir dengan <strong>Bunga Telang + Lemon\r\nWeeka</strong>, kini diperkaya dengan <strong>serai</strong> dan <strong>jahe</strong>.\r\nKombinasi bahan alami ini menciptakan minuman herbal yang segar, menenangkan\r\ndan kaya manfaat. Cocok untuk dinikmati kapan saja, baik hangat maupun dingin.<o:p></o:p></p><div class=\"MsoNormal\" align=\"center\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;\r\ntext-align:center;line-height:115%\"><span style=\"font-size:12.0pt;line-height:\r\n115%;font-family:&quot;Times New Roman&quot;,serif\">\r\n\r\n<hr size=\"2\" width=\"100%\" align=\"center\">\r\n\r\n</span></div><h4 style=\"margin-top:0cm;line-height:115%\"><strong><span style=\"font-size:\r\n12.0pt;line-height:115%;mso-bidi-font-weight:normal\">Komposisi Bahan Alami</span></strong><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\"><o:p></o:p></span></h4><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\n     115%;mso-list:l2 level1 lfo1;tab-stops:list 36.0pt\"><strong><span style=\"font-size:12.0pt;line-height:115%\">Bunga Telang&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong><span style=\"font-size:12.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif\">:\r\n     Memberikan warna biru alami yang kaya antioksidan <o:p></o:p></span></li>\r\n</ol><p class=\"MsoNormal\" style=\"margin-top:0cm;margin-right:0cm;margin-bottom:0cm;\r\nmargin-left:108.0pt;margin-bottom:.0001pt;text-indent:36.0pt;line-height:115%\"><strong><span style=\"font-size:12.0pt;line-height:115%\">&nbsp;\r\n</span></strong><span style=\"font-size:12.0pt;line-height:115%;\r\nfont-family:&quot;Times New Roman&quot;,serif\">flavonoid, membant