INSERT INTO `produk` VALUES (419, 5654, 'Andrea Hoodie Sporty', NULL, '[\"public\\/file_foto_produk\\/67d3a8d8e49ba.jpg\"]', '2025-03-14 10:56:08', '2025-03-14 10:56:08');
INSERT INTO `produk` VALUES (420, 5684, 'Demeter pupuk organik', '<p class=\"MsoListParagraph\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Tahoma&quot;,sans-serif\">Produk ini akan bermanfaat bagi para\r\npetani sayuran dan buah – buahan terutama di daerah dataran tinggi dalam meningkatkan\r\nhasil panen budidaya mereka. Produk Demeter terbukti mampu meningkatkan\r\nkesuburan tanah dan hasil panen yang didapatkan akan semakin melimpah. Dengan\r\nadanya pupuk Demeter ini juga akan lebih mengurangi penggunaan bahan kimia yang\r\nberdampak buruk terhadap kesehatan dan lingkungan. Penggunaan bahan kimia yang\r\nberlebihan mengakibatkan pertumbuhan tanaman yang didapatkan akan lebih\r\nberkurang dari tahun ke tahun dan tanah akan menjadi tercemar. Harapan dengan\r\nadanya produk Demeter ini bisa memperlancar usaha para petani dalam\r\nmeningkatkan perekonomian mereka.&nbsp;<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/67da35cc5e1d4.jpg\"]', '2025-03-19 10:11:08', '2025-03-19 10:11:08');
INSERT INTO `produk` VALUES (421, 5685, 'Fashion', '<p class=\"MsoListParagraph\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Tahoma&quot;,sans-serif\">Fomaproka merupakan brand produk dalam\r\nbidang fashion. Selain kemeja kami akan mengembangkan bisnis ini untuk\r\nmemproduksi hoodie, crewneck, kaos maupun merchandise lainnya seperti totebag,\r\ntopi, dan lanyard. Tagline fomaproka yaitu “simple but meaningful” kami\r\nmenginginkan produk fomaproka dapat memiliki arti dan dampak yang positif\r\nterhadap konsumen. Kami menggunakan bahan lokal yang premium seperti contoh\r\nyang telah kami gunakan yaitu katun rayon twill dan katun rayon premium motif yang\r\nkami dapatkan dari UMKM. Kedua bahan ini menjanjikan tidak mudah menyusut dan\r\ntidak mudah robek dengan penggunaan sewajarnya. Produk kita dibagi menjadi dua subtema\r\nyaitu fomaplants dan Prokagain. Fomaplants sendiri akan memiliki ciri khas\r\nseperti gambar tumbuhan yang diharapkan akan bertumbuh dengan baik dan subur\r\nyang dimana tumbuhan akan semakin lebat jika pupuknya juga memiliki kualitas\r\nyang baik. Prokagain akan membawakan tema seputar hewan yang dapat berkembang\r\nbiak.<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/67da375bb7e47.JPG\"]', '2025-03-19 10:17:47', '2025-03-19 10:17:47');
INSERT INTO `produk` VALUES (422, 5672, 'Buket Bunga', '<p class=\"MsoListParagraph\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Tahoma&quot;,sans-serif\">Fomaproka merupakan brand produk dalam\r\nbidang fashion. Selain kemeja kami akan mengembangkan bisnis ini untuk\r\nmemproduksi hoodie, crewneck, kaos maupun merchandise lainnya seperti totebag,\r\ntopi, dan lanyard. Tagline fomaproka yaitu “simple but meaningful” kami\r\nmenginginkan produk fomaproka dapat memiliki arti dan dampak yang positif\r\nterhadap konsumen. Kami menggunakan bahan lokal yang premium seperti contoh\r\nyang telah kami gunakan yaitu katun rayon twill dan katun rayon premium motif yang\r\nkami dapatkan dari UMKM. Kedua bahan ini menjanjikan tidak mudah menyusut dan\r\ntidak mudah robek dengan penggunaan sewajarnya. Produk kita dibagi menjadi dua subtema\r\nyaitu fomaplants dan Prokagain. Fomaplants sendiri akan memiliki ciri khas\r\nseperti gambar tumbuhan yang diharapkan akan bertumbuh dengan baik dan subur\r\nyang dimana tumbuhan akan semakin lebat jika pupuknya juga memiliki kualitas\r\nyang baik. Prokagain akan membawakan tema seputar hewan yang dapat berkembang\r\nbiak.<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/67da386843650.jpg\",\"public\\/file_foto_produk\\/67da386843d87.jpg\"]', '2025-03-19 10:22:16', '2025-03-19 10:22:16');
INSERT INTO `produk` VALUES (423, 5687, 'Pop up book', '<p>Pop up book sexual education APROTEK ini bisa membantu orang tua dan guru dalam memberikan edukasi seksual kepada Anak Berkebutuhan Khusus, juga dapat membantu para orang tua dalam membangun kelekatan dengan anak. Buku yang kami buat ini merupakan sebuah inovasi dalam mengembangkan media pembelajaran seksual bagi Anak Berkebutuhan Khusus periode awal yaitu usia 2-6 tahun, untuk mencegah terjadinya pelecehan seksual kepada Anak Berkebutuhan Khusus. Kami membuat buku dengan tampilan yang lebih menarik dari segi ilustrasi, warna, cerita, media sensori dan bentuk 3 dimensi agar anak berkebutuhan khusus tidak merasa jenuh ketika belajar mengenai edukasi seksual ini.</p><div><br></div>', '[\"public\\/file_foto_produk\\/67da3ba5d00b2.jpg\",\"public\\/file_foto_produk\\/67da3ba5d02e4.jpg\"]', '2025-03-19 10:36:05', '2025-03-19 10:36:05');
INSERT INTO `produk` VALUES (424, 5688, 'Susu', '<p>MOKYCARE merupakan sebuah inovasi minuman susu kekinian dengan bahan dasar susu sapi segar dan dilengkapi edible straw. MOKYCARE ditujukan untuk membantu menekan angka perokok anak di Indonesia. Kandungan laktosa pada susu akan membuat rasa pahit pada lidah ketika merokok. Bubuk biji labu yang mengandung vitamin C dan triptofan asam amino pada edible straw dapat membantu untuk mengatasi kecemasan anak.</p><div><br></div>', '[\"public\\/file_foto_produk\\/67da3dbea0759.jpg\"]', '2025-03-19 10:45:02', '2025-03-19 10:45:02');
INSERT INTO `produk` VALUES (425, 5671, 'Tour Package', '<p class=\"MsoNormal\" style=\"margin-top:0cm;margin-right:0cm;margin-bottom:0cm;\r\nmargin-left:72.0pt;text-align:justify;text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">Kelas seni seperti seni karawitan,\r\nmembatik, dan juga menari&nbsp; yang\r\nmemberikan kesempatan kepada wisatawan untuk belajar dan berkreasi langsung\r\ndengan para seniman lokal.&nbsp;<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/67da3fabd3cc9.png\",\"public\\/file_foto_produk\\/67da3fabd3ff9.png\",\"public\\/file_foto_produk\\/67da3fabd41c0.png\"]', '2025-03-19 10:53:15', '2025-03-19 10:53:15');
INSERT INTO `produk` VALUES (426, 5673, 'Minuman', '<p><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:\r\n107%;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-font-kerning:1.0pt;mso-ansi-language:\r\nEN-US;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">KoKaBoost menawarkan\r\nalternatif yang lebih terjangkau dan kaya kalsium melalui minuman berbahan\r\ndasar kolang-kaling, yang mengandung sekitar 91 mg kalsium per 100 gram. Dengan\r\ntambahan bahan alami seperti jahe, cengkeh, dan kayu manis, KoKaBoost memberikan\r\nmanfaat kesehatan dalam bentuk minuman yang segar dan unik, khususnya bagi\r\nmereka yang alergi susu atau tidak menyukai sayuran.</span></p>', '[\"public\\/file_foto_produk\\/67da406b78e24.png\",\"public\\/file_foto_produk\\/67da406b790da.png\",\"public\\/file_foto_produk\\/67da406b79268.png\"]', '2025-03-19 10:56:27', '2025-03-19 10:56:27');
INSERT INTO `produk` VALUES (427, 5676, 'Maggot Box', '<p class=\"MsoNormal\" style=\"margin-top:0cm;margin-right:0cm;margin-bottom:0cm;\r\nmargin-left:54.0pt;text-align:justify;border:none;mso-padding-alt:31.0pt 31.0pt 31.0pt 31.0pt;\r\nmso-border-shadow:yes\"><span lang=\"EN-US\" style=\"font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:Arial;color:black\">Produk utama kami terbagi menjadi\r\ndua kategori yaitu Box Premium dan Box Ekonomis, yang masing-masing tersedia\r\ndalam ukuran Big dan Small. Box Premium cocok bagi customer yang ingin\r\nfasilitas lebih lengkap dan daya tampung yang lebih besar. Misalnya, Box\r\nPremium Big memiliki ukuran 41 cm x 26 cm x 14 cm, memberikan ruang lebih luas\r\nuntuk budidaya BSF skala besar. Box Premium Small, dengan ukuran yang lebih\r\nkecil yaitu 30 cm x 19 cm x 14 cm, cocok untuk customer yang butuh kotak\r\npremium dalam kapasitas yang lebih kecil.<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/67da4117ac012.jpg\",\"public\\/file_foto_produk\\/67da4117ac19a.png\"]', '2025-03-19 10:59:19', '2025-03-19 10:59:19');
INSERT INTO `produk` VALUES (428, 5674, 'Mix Farming', '<p class=\"MsoNoSpacing\" style=\"margin-left:3.0cm;text-indent:-14.15pt;line-height:\r\n150%;mso-list:l0 level2 lfo1;tab-stops:6.0cm\"><!--[if !supportLists]--><span lang=\"IN\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span><!--[endif]--><span lang=\"IN\">Pembuatan\r\nmedia buudidaya akuaponik<o:p></o:p></span></p><p class=\"MsoNoSpacing\" style=\"margin-left:3.0cm;text-indent:-14.15pt;line-height:\r\n150%;mso-list:l0 level2 lfo1;tab-stops:6.0cm\"><!--[if !supportLists]--><span lang=\"IN\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span><!--[endif]--><span lang=\"IN\">Penjualan\r\nproduk akuaponik <o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n</p><p class=\"MsoNoSpacing\" style=\"margin-left:3.0cm;text-indent:-14.15pt;line-height:\r\n150%;mso-list:l0 level2 lfo1;tab-stops:6.0cm\"><!--[if !supportLists]--><span lang=\"IN\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span><!--[endif]--><span lang=\"IN\">Promosi\r\nproduk dan alat akuaponik&nbsp;<o:p></o:p></span></p>', '[\"public\\/file_foto_produk\\/67da4d924e895.jpg\",\"public\\/file_foto_produk\\/67da4d924ec36.jpg\",\"public\\/file_foto_produk\\/67da4d924ed24.png\"]', '2025-03-19 11:52:34', '2025-03-19 11:52:34');
INSERT INTO `produk` VALUES (429, 5609, 'Tas', '<p><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:\r\n107%;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Urmo Bag memproduksi tas multifungsi yang dapat\r\ndisesuaikan dengan kebutuhan para konsumen. Urmo bag juga tersedia dalam\r\nberbagai ukuran dan warna, sehingga dapat disesuaikan dengan selera dan gaya\r\nmasing-masing konsumen. Tas ini memiliki tiga fungsi utama dalam satu produk,\r\nyaitu sebagai totebag, dompet, dan tas ponsel. Tas ini memiliki fitur yang\r\ndapat mempermudah penggunanya dalam penyimpanan berbagai macam barang, seperti\r\nbahan belanjaan, alat tulis, menyimpan uang, meletakkan ponsel, atau membawa barang\r\nsaat traveling, karena memiliki kompartemen yang luas dan kantong tambahan</span></p>', '[\"public\\/file_foto_produk\\/67da4f0b6f60d.jpg\",\"public\\/file_foto_produk\\/67da4f0b6f89d.jpg\",\"public\\/file_foto_produk\\/67da4f0b6f9d5.jpg\"]', '2025-03-19 11:58:51', '2025-03-19 11:58:51');
INSERT INTO `produk` VALUES (430, 5698, 'Persona', '<p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Persona TechWear hadir sebagai solusi untuk permasalahan yang ada di industri fashion Indonesia dengan menggabungkan seni, teknologi, dan kontribusi positif terhadap seniman lokal. Berikut adalah beberapa langkah yang diambil oleh Persona TechWear:</span></p><ol style=\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\"><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;margin-left: -18pt;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Penggabungan Teknologi NFT dan Augmented Reality (AR):</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> Persona TechWear menawarkan konsep unik dengan menyatukan kecanggihan teknologi NFT dan Augmented Reality (AR) langsung dalam setiap pakaian melalui NFC. Hal ini memberikan pengalaman yang interaktif dan inovatif bagi konsumen serta meningkatkan nilai estetika produk.w</span></p></li><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;margin-left: -18pt;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Kolaborasi dengan Seniman Lokal:</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> Persona TechWear berkomitmen untuk memajukan seni Indonesia dengan melibatkan seniman dalam proses desain. Melalui kolaborasi ini, Persona TechWear memberikan platform kepada seniman untuk memperkenalkan karya mereka kepada khalayak yang lebih luas, sambil memberikan penghargaan yang pantas atas kontribusi mereka.</span></p></li><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;margin-left: -18pt;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Penerapan Sistem Bagi Hasil:</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> Persona TechWear menerapkan sistem bagi hasil, di mana setiap penjualan baju akan memberikan kontribusi kepada seniman. Hal ini memastikan bahwa seniman mendapatkan penghargaan yang adil atas karya mereka dan mendorong kreativitas serta kolaborasi dalam industri fashion.</span></p></li><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;margin-left: -18pt;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Integrasi Teknologi Blockchain:</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> Persona TechWear mengintegrasikan teknologi Blockchain ke dalam setiap produk untuk memberikan bukti otentikasi dan kepemilikan asli. Setiap karya seni akan di-minting secara terbatas sebagai NFT, yang akan diberikan kepada pembeli melalui tautan klaim yang terintegrasi pada NFC yang tertanam pada label pakaian.</span></p></li></ol><p><span id=\"docs-internal-guid-019b4539-7fff-b0ab-5170-b46a6ca42967\"></span></p><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Dengan konsep yang unik dan berfokus pada penggabungan seni, teknologi, dan kontribusi positif terhadap komunitas seniman lokal, Persona TechWear berharap dapat menciptakan pengalaman baru yang inovatif dan memberdayakan dalam industri fashion pakaian di Indonesia.</span></p>', NULL, '2025-03-25 08:36:33', '2025-03-25 08:36:33');
