INSERT INTO `produk` VALUES (439, 5785, 'Bimbel Safa', '<p>Flyer pendaftaran rekrutment calon siswa bimbel safa</p>', '[\"public\\/file_foto_produk\\/684a852c5bd36.jpeg\"]', '2025-06-12 14:43:40', '2025-06-12 14:44:24');
INSERT INTO `produk` VALUES (440, 5797, 'Gula-Gula Soba Fitrah Gemilang', '<p>Permen Khas Gorontalo \"Soba Fitrah Gemilang\" yang terbuat dari bahan2 Alami.</p>', '[\"public\\/file_foto_produk\\/68678ae48d372.jpeg\"]', '2025-07-04 15:03:48', '2025-07-04 15:03:48');
INSERT INTO `produk` VALUES (441, 5788, 'Bawang Goreng Mamaca', '<p>Berawal dari dapur sederhana, Mamaca berkembang menjadi merek UMKM yang dipercaya oleh masyarakat sekitar karena kualitas rasa, pelayanan hangat, dan komitmen terhadap kebersihan serta konsistensi rasa.</p>', '[\"public\\/file_foto_produk\\/68678b7075831.jpeg\"]', '2025-07-04 15:06:08', '2025-07-04 15:06:08');
INSERT INTO `produk` VALUES (442, 5792, 'Novi Cookies', '<p>Novi Cookies adalah nama usaha kue di bidang kue kering, cake, roti dan kue ulang tahun.</p>', '[\"public\\/file_foto_produk\\/68678c9c694e1.jpeg\"]', '2025-07-04 15:11:08', '2025-07-04 15:11:08');
INSERT INTO `produk` VALUES (443, 5798, 'Kacang Ovaltine', '<p>Kacang ovaltin adalah salah satu cookies dengan perpaduan antara kacang coklat dan susu yang melimpah membuat cemilan ini sangat cocok untuk semua kalangan.</p>', '[\"public\\/file_foto_produk\\/68678dbdc0ba2.jpeg\"]', '2025-07-04 15:15:57', '2025-07-04 15:15:57');
INSERT INTO `produk` VALUES (444, 5794, 'Lakelor', '<p>Produksi Olahan Pangan berbahan dan varian daun kelor di antaranya teh daun kelor, sarabba kelor, kripik keju kelor, krupuk ubi kelor (versi mentah dan sudah di goreng)</p>', '[\"public\\/file_foto_produk\\/686791436feb6.jpeg\",\"public\\/file_foto_produk\\/68679143700e8.jpeg\",\"public\\/file_foto_produk\\/686791437024a.jpeg\"]', '2025-07-04 15:30:59', '2025-07-04 15:30:59');
INSERT INTO `produk` VALUES (445, 5795, 'Keripik Pisang Susu Salju', '<p>Humaya berasal dari kata bahasa daerah Gorontalo artinya Contoh. Usaha ini di dirikan pada tanggal 27 September 2017 tetapi aktif dalam usaha pada masa covid_19. Akhirnya pada tahun 2019 banyak peminat/pembeli Keripik Pisang Susu Salju, Dll.</p>', '[\"public\\/file_foto_produk\\/686793575f3e8.jpeg\",\"public\\/file_foto_produk\\/686793575f5f0.jpeg\",\"public\\/file_foto_produk\\/686793575f6d7.jpeg\"]', '2025-07-04 15:39:51', '2025-07-04 15:39:51');
INSERT INTO `produk` VALUES (446, 5793, 'Keripik Pisang Litata', '<p>Keripik LiTata terbuat dari pisang tanduk pilihan diproses dengan cara di goreng lalu di taburi toping kemudian di panggang, tersedia Varian susu keju, Original, pedas manis, dan coklat</p>', '[\"public\\/file_foto_produk\\/686b6c7e1bd98.jpeg\"]', '2025-07-07 13:43:10', '2025-07-07 13:43:10');
INSERT INTO `produk` VALUES (447, 5790, 'Pegatoz', '<p>Berkah Absyar adalah UMKM yang memproduksi rempeyek dengan bentuk bulat pertama dan satu-satunya di Gorontalo. Rempeyek bulat dibuat dari bahan dan rempah-rempah pilihan berkualitas dan halal.</p><p><br></p><p><br></p>', '[\"public\\/file_foto_produk\\/686b6dc5c3e9e.jpeg\"]', '2025-07-07 13:48:37', '2025-07-07 13:48:37');
INSERT INTO `produk` VALUES (449, 5791, 'Gapigo', '<p>&nbsp;Usaha Keripik Pisang Gapigo dengan 3 Varian rasa. Original, Balado dan Aren</p>', '[\"public\\/file_foto_produk\\/686b6f01d0cba.jpeg\",\"public\\/file_foto_produk\\/686b6f01d0e87.jpeg\",\"public\\/file_foto_produk\\/686b6f01d13a1.jpeg\"]', '2025-07-07 13:53:53', '2025-07-07 13:53:53');
INSERT INTO `produk` VALUES (450, 5796, 'Tifadu', '<p><span style=\"color: rgb(33, 37, 41);\">Tifadu memiliki berbagai macam produk unggulan, salah satunya panada tore yang memiliki beberapa varian rasa yakni rasa coklat, abon dan rasa kacang.</span></p>', '[\"public\\/file_foto_produk\\/686b72304d110.jpeg\",\"public\\/file_foto_produk\\/686b72304d32b.jpeg\",\"public\\/file_foto_produk\\/686b72304d3ee.jpeg\"]', '2025-07-07 14:07:28', '2025-07-07 14:07:28');
INSERT INTO `produk` VALUES (451, 5789, 'SobaPadu', '<p style=\"color: rgb(33, 37, 41);\">Berawal dari membuat camilan khusus untuk keluarga. Melihat&nbsp; camilan ini digemari keluarga maka saya berpikir untuk&nbsp; dijual. Ketika itu mulailah saya menjual di sekolah. Waktu itu penjualan sangat laris, maka saya kembangkan dengan mengurus legalitas yg menjadi persyaratan&nbsp; di ritel-ritel modern.</p><p style=\"color: rgb(33, 37, 41);\">Kini brand SOBA PADU sudah memiliki produk turunan berupa minyak kelapa kampung, stik kelapa muda.</p><p style=\"color: rgb(33, 37, 41);\">Olahan produk pertanian lainnya berupa: cengkeh bubuk, kayu manis bubuk, pala bubuk dan persiapan&nbsp; beras ukuran 5 kg dan 3 kg.</p>', '[\"public\\/file_foto_produk\\/686cbaff3254f.jpeg\"]', '2025-07-08 13:30:23', '2025-07-08 13:30:23');
INSERT INTO `produk` VALUES (452, 5902, 'Cocovate Souvenir', NULL, '[\"public\\/file_foto_produk\\/68a02e14a6438.jpeg\"]', '2025-08-16 14:07:00', '2025-08-16 14:07:00');
INSERT INTO `produk` VALUES (453, 5903, 'Kain Arunika', NULL, '[\"public\\/file_foto_produk\\/68a03425b7c5d.jpeg\"]', '2025-08-16 14:32:53', '2025-08-16 14:32:53');
INSERT INTO `produk` VALUES (454, 5988, 'Brownies Tempe', '<p>BOTEM (Brownies Tempe) Adalah Brownies Chips Dengan Kombinasi Tempe Scrumble, BOTEM sendiri memiliki target menembus pasar internasional atau Export, Dengan Memiliki Keunggulan Menggunakan Tempe Yang Merupakan Makanan Khas Indonesia Yang Sudah Mendunia Kita Yakin Bawahsanya BOTEM Juga Bisa Mendunia.</p>', '[\"public\\/file_foto_produk\\/68c3a52438b42.jpg\"]', '2025-09-12 11:44:20', '2025-09-12 11:44:20');
INSERT INTO `produk` VALUES (455, 5989, 'Jago Ternak (End-to-end Solution for Mitra Ternak)', '<p>Peternakan ayam kampung yang menawarkan end to end solution berbasis digital</p>', '[\"public\\/file_foto_produk\\/68c3a6c1745ca.jpg\"]', '2025-09-12 11:51:13', '2025-09-12 12:02:26');
INSERT INTO `produk` VALUES (456, 5990, 'Dulloch (Kacang Bawang)', '<p>&nbsp;kacang bawang dengan citarasa Nusantara&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3a7d15c10e.jpg\"]', '2025-09-12 11:55:45', '2025-09-12 11:55:45');
INSERT INTO `produk` VALUES (457, 5991, 'Delany Desserts (Dessert Box)', '<p>makanan penutup yang di kemas di cup akrilik kecil persegi, dengan isian cake serta cream dan di lapisi coklat leleh atau ganache dan diberi topping sesuai jenis variantnya. Terdapat 7 varian untuk mini dessert box yaitu Mini Oreo Cream Cheese, Mini Classic Chocolate Cake, Mini Cadbury Cream Cheese, Mini Tiramisu, Mini Matchamisu, Strawberry Shortcake, Shine Muscat Shortcake&nbsp; Selain dessert box kami juga memiliki produk soft cookies. Soft cookies dengan New York Style yang crispy diluar namun lembut didalam dengan tampilan yang agak tinggi dan tebal. Varian soft cookies kami ada 10 yaitu The OG, Matcha cookies, Redvelvet Cream Cheese, Cookie Monster, Unicorn Cookies, Nutella Smores Cookies, Lotus Biscoff Cookies, Cookies and Cream Cheese Cookies, Pretzel Smores Cookies dan coming soon Cookie Bomb&nbsp; Usaha kami bergerak di B2B dengan menjadi supplier makanan penutup di kafe kafe besar di Malang dan juga B2C di Online order delivery apps, seperti shopee food, gofood dan grabfood. Saat ini sedang pengembangan pemasaran melalui Instagram dan Tiktok, serta memaksimalkan jangkauan pemasaran secara nasional melalui penjualan live shopping di Tiktokshop. Dengan target pasar anak muda milineal dan gen Z yang berkumpul di kafe maupun platform Tiktokshop diharapkan potensi penjualan dapat tercapai dengan maksimal.&nbsp; Keunggulan produk kami yaitu memiliki keunikan tampilan visual produk yg disukai oleh anak muda serta rasa yg enak sehingga membuat pelanggan dapat terus repeat order. Serta dengan harga terjangkau untuk segmen pasar anak muda yaitu mulai Rp 10.000&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3a93193026.jpeg\"]', '2025-09-12 12:01:37', '2025-09-12 12:01:37');
INSERT INTO `produk` VALUES (458, 5992, 'Coosae (Koperasi Smart Agriculture Ecosystem)', '<p>Ekosistem pertanian cerdas berbasis kerja sama yang mengintegrasikan teknologi, kelembagaan, dan manajemen rantai pasok untuk meningkatkan produktivitas serta daya saing produk pertanian.&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3aa9e73764.jpeg\"]', '2025-09-12 12:07:42', '2025-09-12 12:07:42');
INSERT INTO `produk` VALUES (459, 5993, 'Lets Play (Game-based Learning)', '<p>Penyedia jasa pelatihan, konsultasi, dan pengembangan proyek berbasis gamification dan game-based learning. Produk dan layanan kami meliputi desain pelatihan interaktif menggunakan board game, pengembangan game edukasi, serta pendampingan organisasi dalam merancang strategi pembelajaran kreatif. Target pasar kami adalah lembaga pendidikan, komunitas, perusahaan, dan organisasi sosial yang ingin meningkatkan efektivitas pembelajaran atau kampanye melalui pendekatan permainan. Keunggulan kami terletak pada kemampuan menggabungkan teori pembelajaran, desain game, dan pengalaman fasilitasi di berbagai sektor, sehingga menghasilkan pengalaman belajar yang menyenangkan, relevan, dan berdampak jangka panjang.</p>', '[\"public\\/file_foto_produk\\/68c3b12c0cae9.jpg\"]', '2025-09-12 12:35:40', '2025-09-12 12:35:40');
INSERT INTO `produk` VALUES (460, 5994, 'Mie Fams (Mie Vegan Kemasan)', '<p>Produk vegan Noodle , target pasar anak2 , remaja , vegan , produk menggunakan sayur dan buah serta dengan menggunakan tepung mocaf glutten free.&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3b229a3c1d.jpg\"]', '2025-09-12 12:39:53', '2025-09-12 12:39:53');
INSERT INTO `produk` VALUES (462, 5996, 'Ramoris by Fifiediah (Produk Herbal)', '<p>Produk-produk minuman Herbal dan Personal Care (Perawatan Diri) berkualitas yang&nbsp; berfokus&nbsp; pada kesehatan dan perlindungan keluarga.&nbsp; Dengan menarget pasar : Unisex berusia 25-55thn, orang2 dengan gaya hidup modern yang tertarik dengan herbal atau metode pengobatan dengan bahan organik dan ingin tubuh dan organ yang sehat jangka panjang. Keunggulan :&nbsp; - bahan 100% alami berkualitas &amp; diolah scr profesional - kemasan praktis dan ekonomis - Terus ber-inovasi produk sesuai permintaan pasar #ramorisbyfifiediah</p>', '[\"public\\/file_foto_produk\\/68c3b92118aa0.jpg\"]', '2025-09-12 13:09:37', '2025-09-12 13:09:37');
INSERT INTO `produk` VALUES (463, 5997, 'Koperasi Lets Play Game Studio', '<p>&nbsp;Jasa pengembangan game, pelatihan perkoperasian dengan media game, dan pelatihan pengembangan game untuk pemula.</p>', '[\"public\\/file_foto_produk\\/68c3bb4a5013c.png\"]', '2025-09-12 13:18:50', '2025-09-12 13:18:50');
INSERT INTO `produk` VALUES (464, 5998, 'Donat', '<p>Produk donat, brownies dan pizza. Target pasar di mulai dari umur 15-40tahun. Keunggulan dari produk saya adalah rasanya yang enak, terbuat dari bahan berkualitas.</p>', '[\"public\\/file_foto_produk\\/68c3bc4453e67.png\"]', '2025-09-12 13:23:00', '2025-09-12 13:23:00');
INSERT INTO `produk` VALUES (465, 5999, 'La Noniik (Kue Kacang)', '<p>Perpaduan produk tradisional dan kue modern sehingga menghasilkan produk&nbsp; camilan premium yang menyasar pasar&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3bfc4da0c1.jpg\"]', '2025-09-12 13:37:56', '2025-09-12 13:37:56');
INSERT INTO `produk` VALUES (466, 6000, 'Kopi Raja (Bubuk Kopi Kota Batu)', '<p>KopiRaja merupakan produk umkm kota batu, sebagai binaan PLUT KUMKM Kota Batu yang menjadi produk unggulan. KopiRaja9 ini memiliki 2 jenis produk yaitu kopi robusta premium dan arabica giri arjuno. Dikemas standing pouch yang menarik dan drip bag instan siap seduh. Target pasar utama kami di pusat oleh-oleh, kemasan eye catching menjadi salah satu keunggulan kami, KopiRaja9 diproduksi menggunakan biji kopi pilihan dan diolah dengan standar kualitas tinggi sehingga menciptakan rasa tak tertandingi yang konsisten dan aroma khas.&nbsp; Selain pusat oleh-oleh, kami juga melayani cafe (dalam bentuk biji), resto, dipasarkan online (shopee), ekspor (handcarry), souvenir bundling package tumbler (instansi2)</p>', '[\"public\\/file_foto_produk\\/68c3c1cd9da5f.jpeg\"]', '2025-09-12 13:46:37', '2025-09-12 13:46:37');
INSERT INTO `produk` VALUES (467, 6001, 'AC Kopi (Bubuk Kopi Gunung Arjuno)', '<p>KopiRaja ini memiliki 2 jenis produk yaitu kopi robusta premium dan arabica giri arjuno. Dikemas standing pouch yang menarik dan drip bag instan siap seduh. Target pasar utama kami di pusat oleh-oleh, kemasan eye catching menjadi salah satu keunggulan kami, KopiRaja9 diproduksi menggunakan biji kopi pilihan dan diolah dengan standar kualitas tinggi sehingga menciptakan rasa tak tertandingi yang konsisten dan aroma khas.&nbsp; Selain pusat oleh-oleh, kami juga melayani cafe (dalam bentuk biji), resto, dipasarkan online (shopee), ekspor (handcarry), souvenir bundling package tumbler (instansi2)</p>', '[\"public\\/file_foto_produk\\/68c3c466b3470.png\"]', '2025-09-12 13:57:42', '2025-09-12 13:57:42');
INSERT INTO `produk` VALUES (468, 6002, 'Bolo Kopi (Bubuk Kopi Robusta)', '<p>kopi bubuk dari biji kopi murni/100% tanpa campuran asli dri petani lokal&nbsp; lereng arjuno,target pasarnya agar bisa bersaing di pasar nasional,rasa kopinya mantap dan nikmat</p>', '[\"public\\/file_foto_produk\\/68c3c7aeb697c.jpg\"]', '2025-09-12 14:11:42', '2025-09-12 14:11:42');
INSERT INTO `produk` VALUES (469, 6003, 'Rujak Bangkok Banyuwangi', '<p>Rujak buah segar dengan bumbu khas Banyuwangi dan cita rasa unik dari bumbu Bangkok yang best seller. Produk ini dikenal karena kesegarannya, rasa autentik, dan bumbu yang khas, cocok untuk semua kalangan.</p>', '[\"public\\/file_foto_produk\\/68c3c8ae3b720.jpg\"]', '2025-09-12 14:15:58', '2025-09-12 14:15:58');
INSERT INTO `produk` VALUES (470, 6004, 'Pawonkoe (Olahan Cumi, Ikan Laut)', '<p>Hasil perikanan yang berfokus pada produk olahan laut berkualitas, seperti rambak cumi, stik cumi, sambal cumi, dan aneka camilan seafood lainnya. Dengan bahan baku segar pilihan dan proses produksi higienis, Poklahsar Pawonkoe menghadirkan rasa gurih autentik yang digemari pecinta makanan laut.&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3c9c86bc26.jpg\"]', '2025-09-12 14:20:40', '2025-09-12 14:20:40');
INSERT INTO `produk` VALUES (471, 6005, 'JIVANA (Natural Food Product)', '<p>Himalaya Salt, Chia Seed, Whole Wheat Bread<br>Produksi makanan sehat yang minim proses serta menghindari penambahan BTP. Visi kami adalah menjadi brand makanan sehat pilihan utama yang bersumber secara etis, bermanfaat bagi kesejahteraan pelanggan dan berkelanjutan.&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3e46cd8019.jpg\"]', '2025-09-12 16:14:20', '2025-09-12 16:14:20');
INSERT INTO `produk` VALUES (472, 6006, 'Dhabi (Kerupuk Ikan)', '<p>Kerupuk ikan jenggelek merupakan produk unggulan Kota Probolinggo. Dimana Probolinggo merupakan pesisir pantai yang melimpah bahan baku ikan segar. Hal ini menjadi potensi untuk pengembangan produk hasil perikanan salah satunya kerupuk ikan jenggelek.</p>', '[\"public\\/file_foto_produk\\/68c3e6fc200c1.jpeg\"]', '2025-09-12 16:25:16', '2025-09-12 16:25:16');
INSERT INTO `produk` VALUES (473, 6007, 'Tombol Start (Game Developer, Game Studio, Game Enthusiast Community)', '<p>Tombol Start adalah media digital dari Malang yang fokus mendukung ekosistem game lokal Indonesia lewat berita, review, wawancara, dan liputan komunitas. Keunggulannya ada pada pendekatan humanis, kolaborasi erat dengan developer lokal, serta kampanye edukatif seperti #MainGameLokal dan #BeliGameLokal.</p>', '[\"public\\/file_foto_produk\\/68c3e8a98290b.png\"]', '2025-09-12 16:32:25', '2025-09-12 16:32:25');
INSERT INTO `produk` VALUES (474, 6008, 'MoBeliApa (Marketplace & POS UMKM)', '<p>Mobeliapa.com merupakan ecomerce o2o ( offline to online dan online to offline ) merupakan sistem kasir dan ecomerce yang dapat digunakan oleh umkm dalam bertransaksi. Ecomerce - ecomerce ini dapat saling terhubung melalui marketplace mobeliapa.com</p>', '[\"public\\/file_foto_produk\\/68c3ea751be58.png\"]', '2025-09-12 16:40:05', '2025-09-12 16:40:05');
INSERT INTO `produk` VALUES (475, 6009, 'Nipis Nikmat (Minuman Jeruk Nipis Kemasan)', '<p>Jeruk nipis (Citrus aurantifolia) sebagai sumber vitamin yang bermanfaat untuk kesehatan tubuh. NINI (Nipis Nikmat) kini hadir sebagai minuman dari ekstraksi Jeruk Nipis Asli. Menyediakan minuman yang sehat dan bisa dikonsumsi oleh semua kalangan.</p>', '[\"public\\/file_foto_produk\\/68c3ec361cbd2.png\"]', '2025-09-12 16:47:34', '2025-09-12 16:47:34');
INSERT INTO `produk` VALUES (476, 6010, 'UAO - UtakAtikOtak (Digital Agency untuk Pendidikan)', '<p>UtakAtikOtak merupakan media sosial yang mengusung konsep pendidikan dalam bentuk permainan, sehingga para penggunanya tetap bisa beraktivitas sebagaimana media sosial pada umumnya, tetapi sekaligus menambah wawasan. Pengguna dapat mengasah otak dengan cara saling berbagi soal dan pengetahuan serta menjawab soal melalui kuis untuk mendapatkan ranking atau lencana (badge) tertentu.</p>', '[\"public\\/file_foto_produk\\/68c3ed5876079.jpeg\"]', '2025-09-12 16:52:24', '2025-09-12 16:52:24');
INSERT INTO `produk` VALUES (477, 6011, 'Kamsitu (Sambal Cumi, Sambal Geprek)', '<p>Sambal Kamsitu : Sambal kemasan dengan varian sambal geprek, sambal cakalan, sambal cumi, target pasarnya adalah perempuan usia 18 - 40 Tahun yang senang pedas, keunggulan pedasnya nagih, kemasan kekinian, tahan 1 tahun</p>', '[\"public\\/file_foto_produk\\/68c3ee875abf4.jpg\"]', '2025-09-12 16:57:27', '2025-09-12 16:57:27');
INSERT INTO `produk` VALUES (478, 6012, 'Nusa Sari (Makaroni & Seblak Kering)', '<p>Nusa sari mempunyai 2 produk unggulan seblak kering dan makaroni yang memiliki targer pasar anak muda yang menyukai makanan hits ataupun jadul&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c3f185e384b.jpg\"]', '2025-09-12 17:10:13', '2025-09-12 17:10:13');
INSERT INTO `produk` VALUES (479, 6013, 'Agaya (Fashion Merch Probolinggo)', '<p>Agaya adalah sebuah visualisasi daerah Probolinggo yang diaplikasikan ke dalam media souvenir \'apparel\' yang dikemas secara premium, ditujukan untuk para wisatawan yang datang ke Probolinggo agar tetap mengenang pengalaman melancongnya. Mengusung kebudayan lokal dan kekayan alam Probolinggo, Agaya hadir untuk memperkenalkan serta mengawetkan ingatan akan indahnya keragaman Probolinggo yang tiada akhir. Target market Wisatawan lokal &amp; mancanegara Wanita &amp; Pria 20 – 40 tahun dengan persona Traveler, pecinta alam, antusias dalam kultur dan budaya, kolektor souvenir, kolektor baju bergambar, gaya santai/streetwear dengan pesan lokal yang kuat. Lebih dari sekadar ‘city merchandise’ Agaya merupakan karya yang mengabadikan pesona Probolinggo dalam wujud premium. Dibuat dengan material berkualitas nyaman digunakan, diproses melalui \'creative thinking\' untuk menciptakan desain grafis dan visual yang iconic, ‘wearable’&nbsp; dan ‘fashionable’. Dikemas dengan packaging ‘sustainable’ dan ’collectible’.</p>', '[\"public\\/file_foto_produk\\/68c769b32874c.jpg\"]', '2025-09-15 08:19:47', '2025-09-15 08:19:47');
INSERT INTO `produk` VALUES (480, 6014, 'NDAGO (Cakery)', '<p>Ndago Cake Cookies &amp; Bakery fokus menghadirkan produk lezat dan berkualitas tinggi dengan bahan premium, tanpa pengawet. Cita rasa yang otentik dan sehat menjadikan produk kami pilihan pelanggan yang mengutamakan kualitas. Kami memproduksi berbagai macam kue dan roti setiap hari.</p>', '[\"public\\/file_foto_produk\\/68c76af4dfc10.jpeg\"]', '2025-09-15 08:25:08', '2025-09-15 08:25:08');
INSERT INTO `produk` VALUES (481, 6015, 'Bolinggo (Bolen Probolinggo)', '<p>BOLLINGGO adalah kue bolen berbahan dasar pisang hasil budidaya petani Probolinggo. Cocok sebagai oleh-oleh khas dari Probolinggo. Citarasanya spesial, krenyes lembut saat digigit. Manisnya pas dan butter-nya terasa banget. Produk disajikan pada kemasan dengan desain menarik dan layak dibanggakan.</p>', '[\"public\\/file_foto_produk\\/68c76be244429.jpg\"]', '2025-09-15 08:29:06', '2025-09-15 08:29:06');
INSERT INTO `produk` VALUES (482, 6016, 'Nafifah Cake (Cakery)', '<p>Nafifah cake adalah sebuah usaha yang menawarkan produk berupa cake dan makanan, seperti prol tape, brownies, spiku, kue nampan, ketan durian, dll, target pasar kami adalah semua kalangan usia. Memiliki sertifikat halal untuk beberapa produk Memiliki NIB Memiliki berbagai macam produk yang sesuai dengan perkembangan tren</p>', '[\"public\\/file_foto_produk\\/68c77089d8404.png\"]', '2025-09-15 08:48:57', '2025-09-15 08:48:57');
INSERT INTO `produk` VALUES (483, 6017, 'DW Breadfruit Stick (Stick Sukun)', '<p>Olahan makanan ringan yg berbahan dasar buah sukun dg campuran tepung&nbsp; yg di olah menjadi camilan berbentuk stick yg di goreng dg rasa manis asin gurih yg di olah</p>', '[\"public\\/file_foto_produk\\/68c771d850b12.jpg\"]', '2025-09-15 08:54:32', '2025-09-15 08:54:32');
INSERT INTO `produk` VALUES (484, 6018, 'Cazmilk (Susu Pasteurisasi)', '<p>Susu pasteurisasi cazmilk adalah minuman susu berperisa dengan kemasan botol 250ml. Target pasar kami adalah keluarga. Kami memiliki 140 lebih titik penjualan di jawa timur</p>', '[\"public\\/file_foto_produk\\/68c773ef50407.jpeg\"]', '2025-09-15 09:03:27', '2025-09-15 09:03:27');
INSERT INTO `produk` VALUES (485, 6019, 'Ariverse Studio (Gamification Services)', '<p>Ariverse Studio merupakan studio game asal Malang yang mengembangkan game original sekaligus menyediakan layanan B2B seperti pengembangan permainan custom, VR/AR interaktif, dan gamifikasi. Kami menarget pasar perusahaan, institusi pendidikan, dan brand yang ingin menghadirkan inovasi digital yang imersif, dengan keunggulan pada kreativitas, solusi multi-platform, dan storytelling yang kuat.</p>', '[\"public\\/file_foto_produk\\/68c776acb8e38.jpg\"]', '2025-09-15 09:15:08', '2025-09-15 09:15:08');
INSERT INTO `produk` VALUES (486, 6020, 'Nutri Honey (Madu, Cuka Apel)', '<p>Nutrihoney merupakan produsen madu dan minuman buah fermentasi alami seperti cuka apel, cuka nanas, sari lemon dan chia seed. Bertujuan untuk membantu masyarakat mengenal realfood dengan hidup sehat tanpa obat, serta memberikan solusi bagi masyarakat yang takut mengonsumsi obat2 dengan herbal yang membantu dalam penyembuhan penyakit degeneratif. Didampingi oleh ahli gizi dan tenaga kesehatan secara langsung. Sudah bersertifikasi halal dan PIRT. Bekerjasama dengan petani sehingga membantu perekonomian lokal</p>', '[\"public\\/file_foto_produk\\/68c777cadae1d.jpeg\"]', '2025-09-15 09:19:54', '2025-09-15 09:19:54');
INSERT INTO `produk` VALUES (487, 6021, 'Diyu (Manisan Mangga)', '<p>Produk Manisan Mangga merupakan produk unggulan daerah kota probolinggo. Dimana Kota Probolinggo memiliki ikon Mangga.</p>', '[\"public\\/file_foto_produk\\/68c77c2de401b.jpeg\"]', '2025-09-15 09:38:37', '2025-09-15 09:38:37');
INSERT INTO `produk` VALUES (488, 6022, 'Tengger Arabica (Bubuk Kopi Gunung Bromo)', '<p>Kopi Tengger Arabica adalah sebuah usaha dari pemuda Probolinggo mengenalkan potensi Kopi Lokal, target pasar adalah internasional karena banyaknya Wisatawan Mancanegara yang singgah di Kota Probolinggo, keunggulannya adalah species dari arabica yang cenderung low bitter dan lebih manis.</p>', '[\"public\\/file_foto_produk\\/68c782bd94de4.jpeg\"]', '2025-09-15 10:06:37', '2025-09-15 10:06:37');
INSERT INTO `produk` VALUES (489, 6023, 'Dapur Rifqiaa (Marning Jagung Ketan)', '<p>Marning jagung ketan adalah camilan tradisional berbahan dasar jagung ketan yang diolah dengan cara digoreng dengan rasa yang renyah, lalu dibumbui (gurih atau pedas). Teksturnya garing tidak keras, rasa khas jagung ketan yang legit, dan cocok dinikmati sebagai teman minum teh/kopi.&nbsp; Target Pasar offline&nbsp; Rumah tangga yang mencari camilan renyah untuk sehari-hari&nbsp; Anak-anak,remaja, dewasa yang menyukai jajanan ringan&nbsp; Pecinta camilan tradisional&nbsp; Target Pasar Online&nbsp; Warung, toko kelontong, dan pedagang camilan untuk dijual kembali&nbsp; Konsumen camilan di e-commerce (Shopee, Tokopedia, Lazada)&nbsp; Pembeli di media sosial (Instagram, Facebook, TikTok Shop)&nbsp; Pecinta makanan tradisional di perantauan&nbsp; Reseller dan dropshipper camilan&nbsp; Komunitas pecinta kuliner dan UMKM.</p>', '[\"public\\/file_foto_produk\\/68c785f7cede2.png\"]', '2025-09-15 10:20:23', '2025-09-15 10:20:23');
INSERT INTO `produk` VALUES (490, 6024, 'Gedangkoe (Keripik Pisang)', '<p>Keripik pisang Gedang koe merupakan&nbsp; jenis makanan ringan yang terbuat dari&nbsp; bahan dasar buah pisang dengan racikan&nbsp; bumbu varian rasa yang memiliki tekstur&nbsp; renyah &amp; gurih.Anak-anak dan remaja: Suka ngemil, mencari rasa yang bervariasi dan kemasan menarik. Mahasiswa dan pekerja muda: Mencari camilan praktis dan terjangkau saat belajar atau bekerja. Pecinta kuliner: Mencari camilan unik, oleh-oleh khas daerah, atau rasa-rasa baru. Keluarga: Membeli keripik pisang sebagai camilan sehat untuk dinikmati bersama. Wisatawan: Membeli keripik pisang sebagai oleh-oleh khas daerah. Pelanggan setia: Membeli secara teratur karena menyukai rasa dan kualitas keripik pisang tertentu. Pemasok ke warung, toko, atau supermarket: Memenuhi kebutuhan pasar yang lebih luas.</p>', '[\"public\\/file_foto_produk\\/68c787bdd089b.jpeg\"]', '2025-09-15 10:27:57', '2025-09-15 10:27:57');
INSERT INTO `produk` VALUES (491, 6025, 'LAVARASA (Sambal dan Makanan Kemasan)', '<p>Lavarasa adalah sambal kemasan siap saji dengan berbagai varian. Yang mana bisa di konsumsi oleh semua kalangan terutama pecinta pedas. Dengan harga yang terjangkau di harapkan bisa menjangkau target pasar di semua kalangan. Semoga lavarasa bisa memjadi sambal unggulan dan kebanggaan dari banyuwangi.</p>', '[\"public\\/file_foto_produk\\/68c788ee50867.jpg\"]', '2025-09-15 10:33:02', '2025-09-15 10:33:02');
INSERT INTO `produk` VALUES (492, 6026, 'Silasnum Education (Bimbel, Edutech)', '<p>Silasnum Education adalah sebuah usaha di bidang jasa pendidikan nonformal yang bergerak sebagai bimbingan belajar online, khususnya untuk persiapan masuk perguruan tinggi negeri melalui jalur UTBK–SNBT dan seleksi mandiri. Layanan yang ditawarkan mencakup akses belajar selama satu tahun penuh, meliputi video pembelajaran, latihan soal, simulasi UTBK, forum diskusi, dan pendampingan dari tentor berpengalaman. Target pasar utama Silasnum Education adalah siswa SMA/SMK kelas 11 dan 12 serta alumni yang sedang mempersiapkan UTBK ulang, dengan fokus pada pelajar dari keluarga menengah ke bawah di seluruh Indonesia. Keunggulan utama Silasnum terletak pada harga yang sangat terjangkau, materi yang selalu diperbarui sesuai kebijakan seleksi nasional terbaru, akses belajar yang fleksibel tanpa batasan waktu, serta sistem pendampingan yang responsif dan berbasis komunitas.</p>', '[\"public\\/file_foto_produk\\/68c78bbb75cbd.png\"]', '2025-09-15 10:44:59', '2025-09-15 10:44:59');
INSERT INTO `produk` VALUES (493, 6027, 'Dapoer Kukits (Dessert Kota Batu)', '<p>Dapoer Kukits adalah usaha yang bergerak di bidang kuliner terutama dessert. Kami menjual berbagai dessert seperti brownies, burnt cheesecake dan beberapa varian lainnya seputar brownies dan cheesecake. Kami menjual brownies dan cheesecake karena di Kota Batu jarang orang menjual dessert yang enak tetapi ramah di kantong. Selain itu, target pasar kami adalah mulai dari anak-anak hingga dewasa sehingga produk kami tidak terlalu manis dan ada yang gluten free.</p>', '[\"public\\/file_foto_produk\\/68c78d4340938.png\"]', '2025-09-15 10:51:31', '2025-09-15 10:51:31');
INSERT INTO `produk` VALUES (494, 6028, 'Dapur Bu Pri (Ikan Laut Crispy)', '<p>Bu Pri merupakan usaha mikro kecil menengah yang bergerak dalam bidang olahan ikan dan makanan ringan. Produk yang dihasilkan keripik sukun dan ikan crispy. Kami menggunakan bahan baku segar dan lokal yaitu ikan laut segar dari nelayan lokal. Tanpa pengawet buatan, gluten free aman sehingga aman untuk anak-anak, juga menggunakan rempah-rempah pilihan. Untuk bumbu tabur varian rasa juga dibuat sendiri dari cabai dan bawang segar. Memiliki legalitas seperti NIB, PIRT, Halal dan Uji Nutrisi. Target pasar kami sekarang yaitu mahasiswa, pekerja, profesional muda dan keluarga karena ikan crispy bisa dijadikan alternatif lauk pendamping nasi yang praktis dan nyaman dibawa kemana-mana. Selain itu juga kepada toko oleh - oleh, para wisatawan dan travel umroh karena bisa dijadikan oleh-oleh dengan citarasa yg khas dan praktis dibawa. Selain itu juga kami sedang mengembangkan pemasaran online, karena di era sekarang semua serba digital.</p>', '[\"public\\/file_foto_produk\\/68c78e8724b38.jpg\"]', '2025-09-15 10:56:55', '2025-09-15 10:56:55');
INSERT INTO `produk` VALUES (495, 6029, 'Akar Lebat (Agriculture Product)', '<p>Akar Lebat Group didirikan pada tahun 2019, bergerak dibidang pertanian yang menjual berbagai macam bibit tanaman buah,sayur hingga tanaman hias. Pemasaran Akar Lebat Group berbasis offline dan online. Akar lebat Group juga salah satu platform yang menggaungkan semangat petani millenial untuk menyongsong gerakan Re-Generasi petani muda yang ada di Indonesia. Dengan aksi nyata yaitu Akar Lebat Group secara konsisten membagikan konten edukasi pertanian melalui platform media social seperti instagram, Tiktok, dan juga Youtube. Akar Lebat group kini memiliki ribuan customer yang tersebar di seluruh indonesia bai Online maupun Offline.</p>', '[\"public\\/file_foto_produk\\/68c79250ba52d.png\"]', '2025-09-15 11:13:04', '2025-09-15 11:13:04');
INSERT INTO `produk` VALUES (496, 6030, 'UD Diana Indah (Kerupuk Rengginang Ikan)', '<p>UD. Diana Indah adalah UMKM yang bergerak di bidang produksi makanan ringan tradisional berbasis hasil perikanan lokal. Produk unggulan kami adalah Rengginang Ikan dan Kerupuk Ikan dengan berbagai varian rasa, seperti gurih, terasi, udang, cumi, balado, dan manis.&nbsp; Target pasar kami mencakup konsumen lokal Situbondo, pasar retail modern seperti Indomaret, wisatawan di pusat oleh-oleh, serta pasar online nasional melalui Shopee, Tokopedia, dan media sosial.&nbsp; Keunggulan usaha kami terletak pada bahan baku ikan segar dari nelayan lokal, varian rasa inovatif, proses produksi yang mempertahankan cita rasa tradisional namun higienis, serta jaringan distribusi yang luas baik offline maupun online.</p>', '[\"public\\/file_foto_produk\\/68c793d765c7e.jpg\"]', '2025-09-15 11:19:35', '2025-09-15 11:19:35');
INSERT INTO `produk` VALUES (497, 6031, 'SOE77 Almond Crispy', '<p>1. Almond Krispy Soe77 adalah camilan ringan sehari hari yang bisa di konsumsi semua usia, di produksi dengan menggunakan alat alat produksi sederhana dan dengan menggunakan bahan bahan pilihan berkualitas.&nbsp; &nbsp;Target pasar untuk usia 10-50 THN, degan jangkauan lebih luas dari wilayah provinsi ke wilayah nasional. Keunggulan produk harga sangat bersaing dengan produk sejenis diantara kompetitor nya.</p>', '[\"public\\/file_foto_produk\\/68c7950002e95.jpeg\"]', '2025-09-15 11:24:32', '2025-09-15 11:24:32');
INSERT INTO `produk` VALUES (498, 6032, 'Boengah (Teh Racikan Bunga)', '<p>BOENGAH adalah brand teh bunga dan rempah lokal asal Kota Batu, Jawa Timur, yang memanfaatkan potensi bunga krisan—komoditas khas daerah yang selama ini hanya digunakan sebagai bunga potong—menjadi teh herbal bernilai tambah. Resmi diluncurkan pada Agustus 2024 dengan tiga varian, BOENGAH mengusung misi mengembangkan potensi lokal, menghadirkan pengalaman minum teh yang sehat dan estetis berbasis tradisi pengobatan, serta mendorong agrowisata dan UMKM desa. Dengan visi menjadi pelopor pengolahan bunga krisan sebagai minuman di Kota Batu, BOENGAH menargetkan pasar penikmat teh premium, pecinta herbal, wisatawan, dan konsumen urban yang menghargai gaya hidup sehat, serta dikenal publik melalui Instagram @tehboenga.</p>', '[\"public\\/file_foto_produk\\/68c796136dd7b.jpg\"]', '2025-09-15 11:29:07', '2025-09-15 11:29:07');
INSERT INTO `produk` VALUES (499, 6033, 'RESEP SIRO (Brownies Chips)', '<p>Resep Siro adalah usaha yang fokus pada bidang produksi aneka olahan brownis dan kue kering has lebaran. Sudah memiliki legalitas usaha dan sudah tersedia di lebih dari 30 outlet di Banyuwangi. Berawal hanya ingin menstabilkan ekonomi pasca covid 19 hingga kini bisa memberdayakan masyarakat setempat sebagai team produksi.&nbsp;&nbsp;</p>', '[\"public\\/file_foto_produk\\/68c7975b83624.jpg\"]', '2025-09-15 11:34:35', '2025-09-15 11:34:35');
INSERT INTO `produk` VALUES (500, 3809, 'Kelapa Ijo', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Green Coconut Water</span></p>', '[\"public\\/file_foto_produk\\/68df2f237c91d.jpeg\"]', '2025-10-03 09:04:19', '2025-10-03 09:04:19');
INSERT INTO `produk` VALUES (501, 5800, 'Aneka Olahan Ikan Oleh-oleh Khas Kabupaten Bandung', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">olahan nugget berbahan ikan lele yang diolah langsung mulai dari budidaya ikan lele, hingga menjadi olahan makanan.</span></p>', '[\"public\\/file_foto_produk\\/68df309cd5518.jpeg\"]', '2025-10-03 09:10:36', '2025-10-03 09:10:36');
INSERT INTO `produk` VALUES (502, 5801, 'Mental health service', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Jika saat ini mengalami mati rasa.. Gimana ya caranya supaya ga mati rasa lagi? 😔</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Tenang Sob! Kali ini Minsob akan kasih solusi buat kalian yang sedang mati rasa. Semoga kondisi kurang mengenakkan ini segera berlalu yaa 🤗</span></p>', '[\"public\\/file_foto_produk\\/68df31404b69f.jpeg\"]', '2025-10-03 09:13:20', '2025-10-03 09:13:20');
INSERT INTO `produk` VALUES (503, 5785, '𝙆𝙚𝙜𝙞𝙖𝙩𝙖𝙣 𝙈𝙚𝙣𝙜𝙚𝙣𝙖𝙡 𝘼𝙣𝙜𝙠𝙖', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Pada kegiatan banyak sekali manfaat yang didapatkan Ananda diantaranya;</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">1. Melatih Motorik Halus, gerakan menggunting dapat mengoptimal motorik halus tangan Ananda sebelum Pra Menulis</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">2. Belajar Angka, dengan mengenalkan Angka pada kertas kertas kecil.</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">3. Melatih Fokus dan Konsentrasi, kegiatan ini pun dapat mengasah kemampuan fokus dan konsentrasi.</span></p>', '[\"public\\/file_foto_produk\\/68df31d14a630.jpeg\"]', '2025-10-03 09:15:34', '2025-10-03 09:15:45');
INSERT INTO `produk` VALUES (504, 3808, 'Eksplorasi Rasa dengan Kepi ditanganmu', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Jagung manis dipadukan dengan keju dan susu serta Oreo , tersedia rasa susu vanila, coklat, dan strawberry</span></p>', '[\"public\\/file_foto_produk\\/68df3264143d6.jpeg\"]', '2025-10-03 09:18:12', '2025-10-03 09:18:12');
INSERT INTO `produk` VALUES (505, 3807, 'Roti Bakar Beef Pizza', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Udah bosen makan pizza? Pengen cobain yang beda tapi tetep mau ada pizza pizza nya? Nih, mimin punya Roti Bakar Beef Pizza, soal rasa gaperlu di tanyaaa lagi deh 😁😋 yuk cobainn&nbsp;</span></p>', '[\"public\\/file_foto_produk\\/68df32dbb6c46.jpeg\"]', '2025-10-03 09:20:11', '2025-10-03 09:20:11');
INSERT INTO `produk` VALUES (506, 3807, 'kingpee.indonesia', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">KingPeesang Mix rasa nya yang ngemix bisa buat sore kamu makin asix 😁</span></p>', '[\"public\\/file_foto_produk\\/68df333262753.jpeg\"]', '2025-10-03 09:21:38', '2025-10-03 09:21:38');
INSERT INTO `produk` VALUES (507, 5803, 'Pudding Cokelat Kolegarasa', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">This is called a foretaste of heaven ✨🍫</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><br></p>', '[\"public\\/file_foto_produk\\/68df33b5cf143.jpeg\"]', '2025-10-03 09:23:49', '2025-10-03 09:23:49');
INSERT INTO `produk` VALUES (508, 5803, 'Taiyaki Kolegarasa', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Hai&nbsp;</span><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" href=\"https://www.instagram.com/explore/tags/kolegaterasa/\" role=\"link\" tabindex=\"0\" style=\"color: rgb(65, 80, 247); cursor: pointer; outline: none; border-inline-width: 0px; margin-inline: 0px; border-inline-style: none; padding-inline: 0px; -webkit-tap-highlight-color: transparent; list-style-type: none; touch-action: manipulation; background-color: rgb(255, 255, 255); display: inline; border-top-style: none; border-bottom-width: 0px; border-bottom-style: none; border-top-width: 0px; overflow-wrap: break-word; font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">#kolegaterasa</a><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">&nbsp;, apakah kamu tau dan sudah pernah coba menu&nbsp;</span><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz notranslate _a6hd\" href=\"https://www.instagram.com/kolegarasa.id/\" role=\"link\" tabindex=\"0\" style=\"color: rgb(65, 80, 247); cursor: pointer; outline: none; border-inline-width: 0px; margin-inline: 0px; border-inline-style: none; padding-inline: 0px; -webkit-tap-highlight-color: transparent; list-style-type: none; touch-action: manipulation; background-color: rgb(255, 255, 255); display: inline; border-top-style: none; border-bottom-width: 0px; border-bottom-style: none; border-top-width: 0px; font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">@kolegarasa.id</a><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">&nbsp;yang satu ini?</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Ini merupakan snack populer di Negara Korea dan Jepang. Rasanya mirip seperti waffle/bolu dengan isian keju,coklat,dan kacang merah.</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"></p>', '[\"public\\/file_foto_produk\\/68df3420c41ab.jpeg\"]', '2025-10-03 09:25:21', '2025-10-03 09:25:36');
