INSERT INTO `produk` VALUES (510, 3806, 'Nasi Tutug Oncom', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Nasi tutug oncom olahan oncom hideng ummi pupu, dengan berbagai macam varian lauk.</span></p><p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Tersedia:</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">✅ Cumi sambal ijo</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">✅ Ayam bacem/goreng/geprek</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">✅ Teri kacang balado</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">✅ Tim peda</span></p>', '[\"public\\/file_foto_produk\\/68df354467bd1.jpeg\"]', '2025-10-03 09:30:28', '2025-10-03 09:30:28');
INSERT INTO `produk` VALUES (511, 5802, 'Nasi Jeruk Ayam Sambal Matah', '<p>Nasi Jeruk Ayam Sambal Matah dari Rokusouq berbentuk ricebowl yang dijual dengan harga yang sangat terjangkau.</p>', '[\"public\\/file_foto_produk\\/68df3677e4965.jpeg\",\"public\\/file_foto_produk\\/68df3677e4c26.jpeg\",\"public\\/file_foto_produk\\/68df3677e4d21.jpeg\"]', '2025-10-03 09:35:35', '2025-10-03 09:35:35');
