INSERT INTO `produk` VALUES (582, 6251, 'Program Kemitraan Es Teh Desa Pangandaran', '<p>Es Teh Desa Pangandaran, menawarkan Program Kemitraan Racikan dengan Cita Rasa berbeda, silahkan rasakan rasa Es Teh Desa di wilayah kabupaten Pangandaran, selanjutnya hubungi : 081322230514</p>', '[\"public\\/file_foto_produk\\/690ddb4d1fba9.jpeg\"]', '2025-11-07 18:43:09', '2025-11-07 18:43:09');
