INSERT INTO `produk` VALUES (584, 6255, 'NYENDOL EXTOBERRY', '<p>Merupakan produk CENDOL tempo dulu yang di produksi dengan bahan berkualitas dan rasa kekinian.</p>', '[\"public\\/file_foto_produk\\/69103c5dbe0cb.jfif\"]', '2025-11-09 14:01:49', '2025-11-09 14:01:49');
INSERT INTO `produk` VALUES (585, 6128, 'TOGA WISUDAWAN KHAS BALI', '<p>Memproduksi toga wisudawan dengan design sesuai permintaan customer dengan keunikan pada tenun khas BALI</p>', '[\"public\\/file_foto_produk\\/69103d0647baa.jfif\"]', '2025-11-09 14:04:38', '2025-11-09 14:04:38');
INSERT INTO `produk` VALUES (586, 6128, 'ANEKA FASHION DENGAN TENUN IKAT BALI', '<p>Yang menjadi ciri khas dari Produk DJANI ANANTA adalah cutting yang pas dan jahitan yang berkualitas dengan kombinasi kain tenun ikat BALI</p>', '[\"public\\/file_foto_produk\\/69103eea3e4d4.jpg\"]', '2025-11-09 14:12:42', '2025-11-09 14:12:42');
INSERT INTO `produk` VALUES (588, 6310, 'Ayana Series', '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">From a mother’s hands, to the world.</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Every piece in the Aiyana Series is stitched with hope,</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">so every step you take feels more meaningful.</span><br style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\"><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">This isn’t just clothing it’s a story you can wear.</span></p>', '[\"public\\/file_foto_produk\\/692d2b844e88e.png\"]', '2025-12-01 12:45:40', '2025-12-01 12:45:40');
