INSERT INTO `tenant` VALUES (11, 1, 'public/foto_profil_tenant/64d4688d3bb60.jpg', 'SANABEL - GULA KELAPA CAIR', 'SURAMININGSIH RAHAYU', 23, 2, 'Jl. S.Parman RT.02 RW.04 Bancar,Purbalingga', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(126, 128, 130); font-family: Lato, sans-serif; text-align: justify;\">Sanabel merupakan Merek dari Produk Gula Kelapa Cair (Palm Sugar). Gula Kelapa Cair Sanabel dengan komposisi 100% Nira Kelapa/Coconut Nectar. Nira Kelapa memgandung serat yang dikenal dengan nama Insulin. Dimana serat tersebut bisa membantu memperlambat proses penyerapan glukosa. Nira Kelapa juga mempunyai indeks glikemik yang rendah dan kandungan fruktosa nya juga sangat rendah. Nira Kelapa merupakan pemanis organik yang sehat dan lezat. Pemanis alami yang sempura dan tinggi kandungan mineral.</span><br></p>', NULL, NULL, NULL, '2023-08-10 11:33:17');
