INSERT INTO `tenant` VALUES (210, 13, 'public/foto_profil_tenant/641a8a5abaed5.png', 'PT. Widra Natural Synthetic', 'Gede Wikrama Putra Setya Adi', 27, 3, 'Jalan Laksmana Baktisraga Gang Darma 2 Blok D Nomer 13 Buleleng', NULL, '150.000.000,00', 'Facebook. IG', 'Nasional', NULL, '<p>PT. Widra Natural Synthetic merupakan perusahaan yang bergerak dalam bidang usaha kitchen set, souvenir dan peralatan rumah tangga lainnya, bahan baku utama yang digunakan oleh PT. Widra Natural Syntetic adalah sekam padi dan jerami yang diolah menggunakan teknologi nanokomposit dengan brand produk nya yang bernama Balisynwood<br></p>', '2021-03-15', '2023-09-28', NULL, '2023-07-07 10:01:27');
INSERT INTO `tenant` VALUES (211, 13, 'public/foto_profil_tenant/641a891611487.jpg', 'CV. Digital Lontar Nusantara', 'DIGITAL LONTAR NUSANTARA', NULL, NULL, 'Banjar Dinas Kuwum Tegallinggah, Desa Kuwum, Marga, Tabanan', NULL, NULL, 'Media Sosial, IG, STEAM', NULL, NULL, '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,&quot;serif&quot;;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Digital Lontar Nusantara</span><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,&quot;serif&quot;;\r\nmso-fareast-font-family:Calibri;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\"> menerapkan teknologi Virtual Reality dengan\r\ntema yang mengangkat seni budaya, sejarah dan legenda Nusantara dan pulau Bali.\r\nSaat ini Inovasi dan pengembangan produk yang kami lakukan adalah permainan VR\r\ndengan konsep MOBA (<i>multiplayer online\r\nbattle arena</i>).</span><br></p>', '2019-03-21', '2022-12-26', NULL, '2023-07-07 09:58:50');
INSERT INTO `tenant` VALUES (212, 13, 'public/foto_profil_tenant/641a8ae235523.jpg', 'PT. VisionBali Herbal Taru Pramana', 'I Nyoman Sridana', NULL, NULL, 'Jl. Tukad Badung XXIII No.27, Renon, Kodya, Kota Denpasar, Bali 80226', NULL, NULL, NULL, 'Nasional', NULL, '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,&quot;serif&quot;;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Taru Pramana merupakan usaha yang bergerak dalam\r\nbidang usaha produksi obat herbal, dalam proses produksi Taru Pramana\r\nmenggunakan teknologi yang sudah terstandar sehingga produk yang dihasilkan\r\nsudah terjamin oleh BPOM</span><br></p>', NULL, NULL, NULL, '2023-03-22 13:12:46');
