INSERT INTO `tenant` VALUES (218, 13, 'public/foto_profil_tenant/641a8acea0c11.jpeg', 'PT. Mulia Ayurvedic Sanjivani', 'I Wayan Taman Arnawa', 23, NULL, 'Jl. Raya Kesambi No.23, Kerobokan, Kuta, Kabupaten Badung, Bali', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,&quot;serif&quot;;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Produk yang dihasilkan oleh&nbsp;PT. Mulia Ayurvedic Sanjivani berasal\r\ndari rempah-rempah yang di olah menggunakan teknologi hexagonal dengan brandnya yang bernama&nbsp;</span><span style=\"font-family: &quot;Times New Roman&quot;, &quot;serif&quot;; font-size: 16px;\">Minyak Sari</span><span style=\"font-family: &quot;Times New Roman&quot;, &quot;serif&quot;; font-size: 16px;\">&nbsp;</span><br></p>', NULL, NULL, NULL, '2023-06-25 13:29:14');
INSERT INTO `tenant` VALUES (219, 13, 'public/foto_profil_tenant/641a8c4c7c2b1.jpeg', 'PT. Bulung Bali Sejahtera', 'Kadek Lila Antara', 23, NULL, 'JALAN RAYA LOVINA, DESA KALIBUKBUK, KECAMATAN BULELENG, KABUPATEN BULELENG, PROVINSI BALI.', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,&quot;serif&quot;;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Bulung Bali Sejahtera merupakan usaha yang bergerak\r\ndalam bidang budidaya dan pengolahan anggur laut menggunakan teknologi modern\r\nuntuk menjamin kualitas air laut agar tidak tercemar bakteri dan logam berat\r\nsehingga anggur laut yang dihasilkan memiliki mutu yang terjamin.</span><br></p>', '2019-03-21', '2022-12-26', NULL, '2023-07-07 09:57:21');
