INSERT INTO `tenant` VALUES (678, 56, NULL, 'PT Putra Medikaltek Indonesia', 'Gilang Putra Pradana, SE.', 43, NULL, 'Jl. Buwek Jaya No.121, RT.002/RW.002, Tridaya Sakti, Tambun Selatan, Bekasi, Jawa Barat - Indonesia', NULL, NULL, 'https://putramedikaltek.co.id/tentang-kami/', 'Nasional', NULL, '<h3 class=\"elementor-heading-title elementor-size-default\" style=\"font-family: Rubik, sans-serif; letter-spacing: -0.02em; line-height: 1.6em; -webkit-font-smoothing: antialiased; font-size: 16px; clear: both; margin-bottom: 0px;\"><font color=\"#000000\">PT. Putra Medikaltek Indonesia adalah perusahaan yang bergerak didalam bidang produsen alat kesehatan. Kami memproduksi peralatan gas medis yang terpasang di rumah sakit seluruh Indonesia. Produk kami antara lain sistem alarm gas medis, sistem sentral gas medis, sistem sentral udara tekan, sistem sentral vakum medik, dan komponen pendukung instalasi gas medik lainya. Produk yang kami buat tentunya sudah memiliki sertifikat izin edar dari Kementerian Kesehatan Republik Indonesia. Selain mengutamakan kualitas yang baik dengan harga yang bersaing, kami juga berfokus pada peluang menjadi prinsipal dalam kerjasama OEM.</font></h3>', '2018-03-01', '2021-11-30', NULL, '2024-06-18 22:31:03');
INSERT INTO `tenant` VALUES (679, 56, NULL, 'AI4LIFE: Aplikasi X-Ray Detection berbasis Artificial Intelligence', 'Tuti Purwaningsih, S.Stat., M.Si.', 43, NULL, 'Gedung Simpul Tumbuh Lt.3\r\nBoulevard Kampus Universitas Islam Indonesia\r\nJalan Kaliurang km.14,5 - DIY', NULL, NULL, NULL, NULL, NULL, '<p>AI4LIFE: Aplikasi X-Ray Detection berbasis Artificial Intelligence.&nbsp;<span style=\"color: black; font-family: &quot;Arial Narrow&quot;; font-size: 12pt;\">Aplikasi ini juga dapat digunakan sebagai X-RAY Covid-19 Detection sebagai Upaya Mengurangi Kontak Fisik dan Kerumunan di\r\nMasa Pandemi.</span></p><p><br></p>', '2021-03-01', '2024-03-31', NULL, '2024-06-18 22:12:41');
