INSERT INTO `tenant` VALUES (1077, 145, 'public/foto_profil_tenant/642d05ffa800c.png', 'Aplikasi Pak Budi', 'APLIKASI PAK BUDI', NULL, NULL, 'Perumahan Bale Prompong B3 RT 007 RW 004, Kelurahan Kutasari, Kecamatan Baturaden, Kabupaten Banyumas , Jawa Tengah', NULL, NULL, 'Media Digital', 'Pelajar, Mahasiswa/i', NULL, '<p>Pak Budi adalah aplikasi konseling pendidikan bagi pelajar di seluruh Indonesia. Pak Budi menjadi aplikasi konseling pendidikan pertama di Indonesia melalui konsultasi online, yang membantu siswa/i mensolusikan permasalahan-permasalahan mengenai bagaimana mengenali potensi diri dengan tes minat bakat,melatih dan meningkatkan kemampuan akademik dengan berbagai macam latihan soal, mencari informasi dan berkonsultasi masalah pendidikan melalui chat konseling dengan psikolog, guru BK atau kakak kelas.<br></p>', '2022-01-01', '2022-06-30', NULL, '2024-10-10 10:35:40');
