INSERT INTO `tenant` VALUES (1173, 71, 'public/foto_profil_tenant/63eb3ffbcd032.jpg', 'Barakuda Bali', 'Jaya Laksana', 23, 2, 'Jl. Tangkuban Perahu I Gang III No 2 Padangsambian - Denpasar Barat - Bali', NULL, '900.000.000,00', 'Instargram', 'Perguruan Tinggi, Perkantoran, Lingkungan Masyarakat Denpasar, Badung dan Sekitarnya', '-', '<p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;text-align:\r\njustify;line-height:normal;mso-layout-grid-align:none;text-autospace:none\"><b><span lang=\"IN\" style=\"font-size:12.0pt;font-family:&quot;Calibri-Bold&quot;,&quot;sans-serif&quot;;\r\nmso-bidi-font-family:Calibri-Bold\">BARAKUDA </span></b><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">atau Barisan Kuliner Muda adalah usaha\r\nyang bergerak di bidang jasa boga<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;text-align:\r\njustify;line-height:normal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">sebagai penyedia makanan dan minuman\r\n(kuliner) dibawah bendera <b>UD. BARA DANA</b>.\r\n<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;text-align:\r\njustify;line-height:normal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;text-align:\r\njustify;line-height:normal;mso-layout-grid-align:none;text-autospace:none\"><b><span lang=\"IN\" style=\"font-size:12.0pt;font-family:&quot;Calibri-Bold&quot;,&quot;sans-serif&quot;;\r\nmso-bidi-font-family:Calibri-Bold\">BARAKUDA</span></b><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\"> terbentuk karena permintaan akan pasar\r\nyang membutuhkan layanan makanan dan minuman yang praktis dan higenis seperti\r\nnasi kotak, snack kotak, nasi yasa, prasmana, tumpeng, coffe break dll.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">Karena </span><b><span lang=\"IN\" style=\"font-size:12.0pt;font-family:&quot;Calibri-Bold&quot;,&quot;sans-serif&quot;;mso-bidi-font-family:\r\nCalibri-Bold\">BARAKUDA</span></b><span lang=\"IN\" style=\"font-size:12.0pt;\r\nmso-ascii-font-family:Calibri;mso-hansi-font-family:Calibri;mso-bidi-font-family:\r\nCalibri\"> merupakan jasa, untuk pengantaran akan kami lakukan sendiri langsung,\r\nsehingga bisa dipastikan bahwa makanan atau minuman yang dipesan diantar tepat\r\nwaktu dan kualitas terjaga. Kami juga menyiapkan layanan <i>free delever</i></span><i><span style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri;mso-ansi-language:EN-US\">y</span></i><i><span style=\"font-size:12.0pt;mso-ascii-font-family:\r\nCalibri;mso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri\"> </span></i><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">untuk pengiriman wilayah Denpasar dan\r\nBadung Bali.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">Selain itu </span><b><span lang=\"IN\" style=\"font-size:12.0pt;font-family:&quot;Calibri-Bold&quot;,&quot;sans-serif&quot;;mso-bidi-font-family:\r\nCalibri-Bold\">BARAKUDA</span></b><span lang=\"IN\" style=\"font-size:12.0pt;\r\nmso-ascii-font-family:Calibri;mso-hansi-font-family:Calibri;mso-bidi-font-family:\r\nCalibri\"> menawarkan banyak layanan, mulai dari catering perusahaan, catering\r\nacara,catering rumahan, coffe brak, acara ulangtahun, kegiatan kampus/sekolah,\r\nreuni dan acara rapat kantoran.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">Semua menu yang tersedia di </span><b><span lang=\"IN\" style=\"font-size:12.0pt;font-family:&quot;Calibri-Bold&quot;,&quot;sans-serif&quot;;\r\nmso-bidi-font-family:Calibri-Bold\">BARAKUDA</span></b><b><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;\r\nmso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri\"> </span></b><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">&nbsp;adalah contoh</span><span style=\"font-size:\r\n12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:Calibri;mso-bidi-font-family:\r\nCalibri;mso-ansi-language:EN-US\"> atau pesanan yang telah kami layani</span><span lang=\"IN\" style=\"font-size:12.0pt;mso-ascii-font-family:Calibri;mso-hansi-font-family:\r\nCalibri;mso-bidi-font-family:Calibri\">, </span><span lang=\"IN\">jika anda\r\nmenginginkan menu variatif lainnya kami akan siapkan.</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><span lang=\"IN\">&nbsp;</span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal;mso-layout-grid-align:none;text-autospace:none\"><b><span lang=\"IN\" style=\"font-size:12.0pt;font-family:&quot;Calibri-Bold&quot;,&quot;sans-serif&quot;;mso-bidi-font-family:\r\nCalibri-Bold\">BARAKUDA</span></b><span lang=\"IN\"> selalu siap menerima pesanan\r\nanda, jadi jangan ragu untuk menghubungi kami melalui kontak dibawah ini:</span></p>', '2020-10-20', '0023-09-30', '2023-02-14 15:02:03', '2023-02-14 15:31:08');
INSERT INTO `tenant` VALUES (1174, 71, 'public/foto_profil_tenant/63ec500e09bf4.jpeg', 'Inkrebilitas', 'A.A.G. Adiputra, SE', 27, 1, 'Jl. Anyelir No. 11, Denpasar - Bali', NULL, '45.000.000,00', NULL, 'Masyarakat Bali dan para pariwisata', NULL, '<p class=\"MsoNoSpacing\" style=\"text-align:justify\"><span style=\"font-size:12.0pt\">Ide\r\nKelompok Disabilitas Berdaya Krama Inkrebilitas ini muncul di tahun 2019, melalui\r\nproses koordinasi dan&nbsp; pertemuan yang\r\nberkesinambungan diantara para penyandang Disabilitas Kota Denpasar serta\r\nsahabat yang peduli dalam pemberdayaan penyandang Disabilitas , dengan\r\nkesungguhan hati secara resmi didirikan di Denpasar pada Tanggal 2 Februari Tahun\r\n2023 sebagai bentuk respon maupun tanggung jawab para sahabat yang peduli dalam\r\npemberdayaan penyandang Disabilitas dan penyandang Disabilitas Kota Denpasar untuk\r\ndapat memanfaatkan akses, berkreativitas serta mengembangkan potensi kewirausahaan\r\npara penyandang Disabilitas secara mandiri berkelanjutan, memberikan manfaat\r\nbagi keluarga dan masyarakat untuk &nbsp;menciptakan Kota Denpasar yang Inklusif.&nbsp; Semangat yang tersirat dalam nama <b>Inkrebilitas ( Inovatif Kreatif Bisabilitas\r\n)</b>, mereka berusaha memotivasi, memberikan dukungan satu sama lainya,\r\nmenumbuhkan rasa percaya diri serta kemandirian guna meningkatkan abilitas ( kemampuan\r\n) talent dan kewirausahaannya harmoni dalam kehidupan sehari – hari.&nbsp;</span></p><p class=\"MsoNoSpacing\" style=\"text-align:justify\"><span style=\"font-size:12.0pt\"><o:p><br></o:p></span></p><p class=\"MsoNoSpacing\"><b>Visi :<o:p></o:p></b></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:12.0pt;\r\nline-height:115%\">Meningkatkan potensi, kemandirian dan kualitas hidup\r\npenyandang Disabilitas.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:12.0pt;\r\nline-height:115%\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><b><span style=\"font-size:12.0pt;line-height:115%\">Misi :<o:p></o:p></span></b></p><p class=\"MsoNoSpacing\" style=\"text-align:justify\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNoSpacing\" style=\"text-align:justify\"><span style=\"font-size:12.0pt\">Memberikan\r\ndukungan dan akses kepada para penyandang Disabilitas guna mengembangkan serta\r\nmeningkatkan potensinya dengan kepedulian dan pelayanan yang professional.<o:p></o:p></span></p>', '2023-02-02', '2026-02-02', '2023-02-15 10:22:54', '2023-02-15 10:22:54');
INSERT INTO `tenant` VALUES (1175, 71, 'public/foto_profil_tenant/63ec5c5d84ecf.jpeg', 'Sila Krama Creative Studio', 'I Putu Arya Finkayana', 42, 1, 'Jln. Ahmad Yani Utara No 517 Denpasar Bali', NULL, '65.000.000,00', 'Instagram, Facebook, Behance dan WA Bussines', 'Seleuruh Masyarkat Bali', '-', '<p>Sila Krama Creative Studio merupakan sebuah usaha dibidang jasa photo dan video yang berlokasi di Denpasar Bali. Usaha ini dibangun sejak tahun 2018 dan memiliki 3 lini produk unggulan diantaranya; 1) Pra dan Wedding, 2) Dokumentasi Event dan 3) Produk and Food Photography yang merupakan produk baru ditengah pandemi. Target pemasaran kami adalah Pengusaha kecil &amp; UMKM, instansi pemerintah &amp; pendidikan, Event Organizer, Wedding Organizer serta masyarakat umum.</p><p>Kekuatan utama kami terletak pada harga yang kompetitif, Fleksibelitas dan layanan konsultasi gratis bagi konsumen kami. Terlepas dari hal tersebut kami juga berinovasi untuk lebih memudahkan konsumen melalui layanan Office Visit Service dan One Day Process.</p>', '2021-02-20', '2023-10-20', '2023-02-15 11:15:25', '2023-02-15 11:15:25');
INSERT INTO `tenant` VALUES (1176, 71, 'public/foto_profil_tenant/63eda3639e3c9.jpeg', 'Krupuk Bagus', 'Ida Bagus Putu Dharma Santosa', 23, 1, 'Jl. Pulau Saelus II Gg Pudak No.8, Denpasar.', NULL, '60.000.000,00', 'Instagram, Facebook,  WA Bussines', 'Seluruh Indonesia', NULL, '<p>Produsen Kerupuk Kulit Ikan Tuna Asli Bali.</p><p>Terbuat dari kulit ikan tuna pilihan dan diproses dengan baik menghasilkan produk yang nikmat untuk menemani waktu berbagi keceriaan bersama orang tersayang.</p><p><br></p><p><br></p><p>Berdiri sejak 2016 hingga akhirnya bisa produksi sendiri dan menjadi finalis wirausaha muda denpasar 2018. Mengangkat produk lokal ikan tuna yang dulunya sering dibuang begitu saja menjadi limbah dan memberi tambahan nilai menjadi cemilan khas yang sangat menyenangkan untuk dinikmati bersama.</p>', '2021-10-20', '2023-10-20', '2023-02-16 10:30:43', '2023-02-16 10:30:43');
INSERT INTO `tenant` VALUES (1177, 71, 'public/foto_profil_tenant/63eda6bb01205.jpeg', 'AGET DEVELOPMENT', 'I Gde Dhika Widarnandana, M.Psi., Psikolog', 43, 1, 'Jalan Kepundung No 12 Denpasar Bali', NULL, '150.000.000,00', 'Instagram, website, google bisnis', 'Nasional', NULL, '<p>CV AGET Udayana adalah perusahaan yang bergerak di bidang pengembangan sumber daya manusia (SDM) sejak tahun 2013. Di dalam menjalankan programnya CV AGET Udayana didukung oleh tim yang solid dan memiliki expertise di bidangnya. Tim CV AGET Udayana terdiri dari Ilmuan Psikologi, praktisi, Psikolog dan sarjana Psikologi. CV AGET Udayana memiliki Motto “Together We Grow” yang berarti tumbuh secara bersama-sama, dalam hal ini dapat memberikan sumbangsih bagi pengembangan Sumber Daya Manusia di Indonesia. Adapun lima Tata Nilai yang dipegang yaitu Sigap, Unggul, Profesional, Ramah dan Inovasi. CV AGET Udayana memiliki beberapa program unggulan yakni : Outbound Team Building, Assessment Psikologi, Inhouse Training, dan Research. Program-program ini dilakukan dengan tim yang ahli dan professional di bidangnya dan selalu menekankan standar keilmuan ilmiah yang dapat diaplikasikan ke dalam pengembangan individu maupun organisasi.<br></p><div><br></div>', '2022-08-17', '2025-08-17', '2023-02-16 10:44:59', '2023-02-16 10:44:59');
INSERT INTO `tenant` VALUES (1178, 62, 'public/foto_profil_tenant/63edca71087a5.jpg', 'Mie Ayam Wonogiren', 'AndiPrasetyo', 23, 2, 'Kalikatir RT.2/6, Nambangan, Selogiri, Wonogiri', NULL, NULL, 'Instagram & Facebook', 'Wonogiri dan luar kota wonogiti', NULL, '<p><span style=\"font-size: 14px;\">Mie Wonogiren adalah sebuah produk Mie Ayam Instan dalam kemasan yang menyuguhkan cita rasa otentik mie</span></p><p><span style=\"font-size: 14px;\">ayam yang lebih sehat, alami, praktis dan higienis. Kami menjadi alternatif pecinta mie instan dengan genre berbeda</span></p><p><span style=\"font-size: 14px;\">tanpa pengawet dan perisa/MSG.</span></p>', NULL, NULL, '2023-02-16 13:17:21', '2023-02-16 13:17:21');
INSERT INTO `tenant` VALUES (1179, 62, 'public/foto_profil_tenant/63edcb4da3294.jpg', 'JOBHUN', 'CYNTHIA CECILIA', 42, 1, 'Gedung Inkubator Bisnis Universitas Airlangga,\r\nJl. Dharmawangsa No. 33B, Airlangga, Gubeng,\r\nSurabaya, Jawa Timur, Indonesia 60286', NULL, '380.000.000,00', 'Web, Instagram, Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Jobhun adalah perusahaan rintisan di bidang pengembangan karier yang memiliki beberapa layanan, meliputi</span></p><p><span style=\"font-size: 14px;\">pelatihan skill, mentoring, dan membantu para talenta bertemu dengan perusahaan yang membutuhkan pekerja.</span></p>', NULL, NULL, '2023-02-16 13:21:01', '2023-02-16 13:21:01');
INSERT INTO `tenant` VALUES (1180, 62, 'public/foto_profil_tenant/63eddcf9bfeec.png', 'AREN TIM', 'HASRUL', 23, NULL, 'Desa Matabondu, Kecamatan Tirawuta,\r\n\r\nKabupaten Kolaka Timur, Provinsi Sulawesi Tenggara.', NULL, '151.000.000,00', NULL, '120 Hotel, Restoran, Cafe/Warkop, Boba', NULL, '<p><span style=\"font-size: 14px;\">Natural Aren Koltim (Arentim) merupakan usaha mikro kecil yang bergerak dibidang industri pengolahan produk aren</span></p><p><span style=\"font-size: 14px;\">dan turunannya yang berasal dari Kabupaten Kolaka Timur, Provinsi Sulawesi Tenggara. Saat ini Arentim telah</span></p><p><span style=\"font-size: 14px;\">memproduksi gula aren serbuk dan gula aren cair yang memiliki kualitas terbaik dikelasnya dengan harga yang</span></p><p><span style=\"font-size: 14px;\">cukup terjangkau.</span></p><p><span style=\"font-size: 14px;\">Menjadi perusahaan yang berbasis pemberdayaan petani dan masyarakat lokal yang berwawasan lingkungan</span></p><p><span style=\"font-size: 14px;\">merupakan visi yang diusung sebagai bentuk kontribusi Arentim dalam pembangunan yang berkelanjutan.</span></p>', NULL, NULL, '2023-02-16 14:36:25', '2023-02-16 14:36:25');
INSERT INTO `tenant` VALUES (1181, 62, 'public/foto_profil_tenant/63edde5408986.jpg', 'AMX UAV', 'ABDUL MAJID ACHMAD FUAD', 18, NULL, 'Wirosaban Barat No.20, Sorosutan, Umbulharjo,\r\n\r\nYogyakarta 55162', NULL, '95.500.000,00', 'Instagram dan Facebook', 'Yogyakarta dan luar kota', NULL, '<p><span style=\"font-size: 14px;\">Manufaktur dan Jasa Drone khusunya untuk kebutuhan pemetaan udara.</span><br></p>', NULL, NULL, '2023-02-16 14:41:37', '2023-02-16 14:42:12');
INSERT INTO `tenant` VALUES (1182, 62, 'public/foto_profil_tenant/63eddfa6f1c41.jpeg', 'EQIYU INDONESIA', 'FARIZ CHAMIM UDIEN', 36, NULL, 'Outlet Malang : JL. BS. Riadi 76 Malang\r\nOutlet Yogya : JL. Pugeran 10 Yogyakarta', NULL, '617.275.000,00', 'Facebook dan Instagram', 'Surabaya & Yogyakarta', NULL, '<p><span style=\"font-size: 14px;\">Eqiyu merupakan lembaga pelatihan membuat bisnis kuliner &amp; pelatihan membuat produk food &amp; beverage.</span><br></p>', NULL, NULL, '2023-02-16 14:47:50', '2023-02-16 14:47:50');
INSERT INTO `tenant` VALUES (1183, 62, 'public/foto_profil_tenant/63ede07cc1dcd.jpg', 'KOOMIK.ID', 'BRIAN TANUTAMA ZUNAEDY, SIE SURYADI, YONATHAN RANDYANTO, ADIANTO WIDJAJA, MAUREEN MONITAN ZUNAEDY', 32, NULL, 'Jl Panggung Mas Raya B107 Semarang', NULL, NULL, 'Facebook & Instagram', 'Semarang dan Luar Kota', NULL, '<p><span style=\"font-size: 14px;\">Koomik.id adalah suatu platform berbagi komik karya komikus lokal Indonesia. Di Koomik.id para komikus bisa</span></p><p><span style=\"font-size: 14px;\">dengan mudah mengkonversi fanbase mereka menjadi penghasilan dengan sistem ads revenue sharing milik</span></p><p><span style=\"font-size: 14px;\">koomik.id, dimana kami memberikan kepada komikus share hasil pendapatan iklan yang dimiliki koomik.id.</span></p>', NULL, NULL, '2023-02-16 14:51:24', '2023-02-16 14:51:24');
INSERT INTO `tenant` VALUES (1184, 62, 'public/foto_profil_tenant/63ede154ee757.jpg', 'Global Millenial Group', 'MUFLIH DWI FIKRI', 36, NULL, 'Pondok Baru Permai, Blok A2, No.29, Gentan, Baki,\r\n\r\nSukoharjo', NULL, '1.133.000.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">GMG merupakan One-Stop Self-Development Solution, dimana GMG menyediakan berbagai platfrom</span></p><p><span style=\"font-size: 14px;\">pengembangan diri yang inklusif bagi pemula.</span></p>', NULL, NULL, '2023-02-16 14:55:00', '2023-02-16 14:55:00');
INSERT INTO `tenant` VALUES (1185, 62, 'public/foto_profil_tenant/63ede3ae8d6c6.jpg', 'TAMBIYAKU', 'MUHAMMAD BAYU HERMAWAN', 2, NULL, 'Jl. Tanjung Selor No 17a Kel. cideng, Kec. Gambir\r\n\r\nJakarta Pusat', NULL, '1.442.000.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Perusahaan makanan sehat berbahan dasar sorghum yang affordable.</span><br></p>', NULL, NULL, '2023-02-16 15:05:02', '2023-02-16 15:05:02');
INSERT INTO `tenant` VALUES (1186, 62, 'public/foto_profil_tenant/63ede4eaace8a.png', 'BIKINCV', 'I WAYAN ADISTHANA WIJAYA', NULL, NULL, 'Jalan Sulatri No. 168x, Denpasar, Bali, 80237', NULL, '210.600.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">BikinCV adalah platform untuk membuat CV dan Surat Lamaran Kerja secara online dengan mudah, cepat dan</span></p><p><span style=\"font-size: 14px;\">praktis. Hanya 5 menit, pengguna sudah dapat mengunduh CV berkualitas dan mengirim lamaran saat itu juga.</span></p>', NULL, NULL, '2023-02-16 15:10:18', '2023-02-16 15:10:18');
INSERT INTO `tenant` VALUES (1187, 62, NULL, 'DIACARE', 'WINDI INTAN PUSPITASARI', 43, NULL, 'Jl. Ki Hajar Dewantara Jebres, Banjarsari, Surakarta\r\n57126, Jl. K.H.Samanhudi No. 82 Laweyan, Surakarta\r\n57142', NULL, '60.000.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">DIACARE, Alat Kesehatan Solusi Alas Pelindung Ulkus Kaki Diabetic, Diabetes Care Indonesia, Pusat Diabetes No.1</span></p><p><span style=\"font-size: 14px;\">Ter-integrated di Indonesia, Sobat Diabetes Indonesia, Your Diabetes Support System.</span></p>', NULL, NULL, '2023-02-16 15:50:49', '2023-02-16 15:50:49');
INSERT INTO `tenant` VALUES (1188, 62, 'public/foto_profil_tenant/63edef001779f.png', 'SIDIGS', 'TRANSBARA WAHYU FIRMANSYAH', 36, NULL, 'Perum Bumi Mandoroko BF 3, Singosari - Kab. Malang', NULL, '90.000.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">SIDIGS adalah sebuah support system untuk membantu sekolah konvensional menjadi Smart School.</span><br></p>', NULL, NULL, '2023-02-16 15:53:20', '2023-02-16 15:53:20');
INSERT INTO `tenant` VALUES (1189, 62, NULL, 'NATURELINE', 'AQILATAMA ARYAPUTRI', 36, NULL, 'Jl. Sudirman RT 01/06, Candi, Ampel, Boyolali', NULL, '1.000.000.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Natureline adalah UKM asal Boyolali, Jawa Tengah yang bergerak dibidang produksi lilin aromaterapi, hampers,</span></p><p><span style=\"font-size: 14px;\">dan dekorasi. Bahan utama yang digunakan adalah palm wax atau minyak kelapa sawit. Kelebihannya adalah</span></p><p><span style=\"font-size: 14px;\">harganya jauh lebih terjangkau dibandingkan bahan lilin lainnya. Produk yang dijual berada pada range harga</span></p><p><span style=\"font-size: 14px;\">Rp 10.000 - Rp 200.000.</span></p>', NULL, NULL, '2023-02-16 15:56:28', '2023-02-16 15:56:28');
INSERT INTO `tenant` VALUES (1190, 62, 'public/foto_profil_tenant/63edf054c8441.png', 'BUANGDISINI', 'TUBAGUS SYAILENDRA, RHEZA VARIANTO, ARGA WICAKSONO', NULL, NULL, 'Jl.KH Malik Dalam No 38, Buring, Kec. Kedungkandang,\r\n1Kota Malang, Jawa Timur 65136', NULL, '196.000.000,00', 'IKLAN MEDIA SOSIAL', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Buangdisini adalah sebuah startup yang membantu pengelolaan sampah untuk memenuhi kebutuhan bahan baku</span></p><p><span style=\"font-size: 14px;\">industri daur ulang plastik.</span></p>', NULL, NULL, '2023-02-16 15:59:00', '2023-02-16 15:59:00');
INSERT INTO `tenant` VALUES (1191, 62, 'public/foto_profil_tenant/63edf11e33147.png', 'AGROEAST INDONESIA', 'YUVENALIS DWI KURNIAWAN, NOVELIETHA, WISEWARNA NAZARA', NULL, NULL, 'KUWA JAWA RT 10 RW 04 KELURAHAN ROWORENA BARAT, ENDE', NULL, '242.000.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Agroeast Indonesia adalah e-commerce dibidang pertanian yang menyediakan platform digital sebagai media</span></p><p><span style=\"font-size: 14px;\">transaksi jual beli dibidang pertanian, baik produk raw material maupun turunannya. Visi perusahaan kami adalah</span></p><p><span style=\"font-size: 14px;\">merevitalisasi dan memberdayakan peran kelompok tani sebagai supplier utama produk-produk pertanian, dengan</span></p><p><span style=\"font-size: 14px;\">harapan dapat meningkatkan daya tawar dan kesejahteraan petani.</span></p>', NULL, NULL, '2023-02-16 16:02:22', '2023-02-16 16:02:22');
