INSERT INTO `tenant` VALUES (1259, 62, 'public/foto_profil_tenant/63fce9b20d63a.png', 'UMMACADEMY', 'A.A. SUTADI SAPUTRA', 36, NULL, 'Jl. Sawo Raya No.3, RT.004/RW.004, Cibodasari,\r\nKec. Cibodas, Kota Tangerang, Banten 151384', NULL, '445.000.000,00', 'Web, Instagram, Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Ruang dan kawan belajar untuk mahasiswa kedokteran dan tenaga kesehatan.</span><br></p>', NULL, NULL, '2023-02-28 00:34:42', '2023-02-28 00:34:42');
INSERT INTO `tenant` VALUES (1260, 62, 'public/foto_profil_tenant/63fd14485fdd5.png', 'SCOLA', 'KRISNANTA Y.P', 36, NULL, 'Jalan Karang Tineung Indah 1 no. 12a', NULL, NULL, 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">SCOLA merupakan perusahaan di bidang teknologi pendidikan yang menyediakan solusi untuk sistem pendidikan</span></p><p><span style=\"font-size: 14px;\">digital di sekolah dengan menyediakan sistem pembelajaran online, sistem informasi sekolah dan konten-konten</span></p><p><span style=\"font-size: 14px;\">bahan ajar untuk mendukung metode pembelajaran menarik bagi siswa di era pendidikan digital.</span></p>', NULL, NULL, '2023-02-28 03:36:24', '2023-02-28 03:36:24');
INSERT INTO `tenant` VALUES (1261, 62, 'public/foto_profil_tenant/63fd16fb95fbf.jpeg', 'AKSEL (PT.KREASI PEMUDA BANGSA)', 'GABRIELLE SHANNEN LEONARD (CMO), SAMUEL DAVIDSEN WIDJAJA (CEO)', 36, NULL, 'AKSEL (PT.KREASI PEMUDA BANGSA)', NULL, '350.000.000,00', 'Web, Instagram, Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Aksel merupakan platform yang berfokus untuk menghubungkan pengusaha dengan talenta muda berkualitas serta</span></p><p><span style=\"font-size: 14px;\">memiliki tiga produk, yaitu Aksel CV Builder, Aksel Career Mentoring, dan Virtual Experience Program. Dalam platform ini,</span></p><p><span style=\"font-size: 14px;\">pengguna mendapat pelatihan secara virtual, membuat CV dengan format ATS, dan CV akan direview oleh seorang</span></p><p><span style=\"font-size: 14px;\">profesional.</span></p>', NULL, NULL, '2023-02-28 03:47:55', '2023-02-28 03:47:55');
INSERT INTO `tenant` VALUES (1262, 62, 'public/foto_profil_tenant/63fd1791b7762.jpg', 'TABULA', 'ARNOLD LUKITO & WILLIAM CAHYAWAN', 43, NULL, 'Legalyn Center, Kawasan CBD Rasuna Epicentrum,\r\nEpiwalk Office Suite Lt. 5 Unit A501, Jl. HR Rasuna Said,\r\nKel. Karet Kuningan, Kec. Setiabudi, Kota Adm. Jakarta\r\nSelatan, Provinsi DKI Jakarta, 12940', NULL, '86.424.341,00', 'Web, Instagram, Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Tabula adalah platform ekosistem wellness &amp; mental health yang bertujuan mempermudah masyarakat mengakses</span></p><p><span style=\"font-size: 14px;\">informasi dan layanan wellness &amp; mental health dan membantu praktisi wellness &amp; wellness menjangkau</span></p><p><span style=\"font-size: 14px;\">pengguna.</span></p>', NULL, NULL, '2023-02-28 03:50:25', '2023-02-28 03:50:25');
INSERT INTO `tenant` VALUES (1263, 62, NULL, 'RATU CIMOL', 'RESIKA CAESARIA PRIYONO', 23, NULL, 'Ratu Cimol adalah sebuah perusahaan UMKM yuang diwadahi oleh CV Made Arizka Sejahtera dengan dasar jual beli\r\ndan berbasis social. Alur bisnisnya menggunakan system social yang diterapkan dari hulu hingga hilir', NULL, '240.000,00', 'Instagram & Facebook', 'Seluruh Indonesia', NULL, '<p><span style=\"font-size: 14px;\">Ratu Cimol adalah sebuah perusahaan UMKM yuang diwadahi oleh CV Made Arizka Sejahtera dengan dasar jual beli</span></p><p><span style=\"font-size: 14px;\">dan berbasis social. Alur bisnisnya menggunakan system social yang diterapkan dari hulu hingga hilir</span></p>', NULL, NULL, '2023-02-28 03:52:06', '2023-02-28 03:52:06');
INSERT INTO `tenant` VALUES (1264, 109, 'public/foto_profil_tenant/63fd796c084d5.jpg', 'Traffic Signal Control )TSC)', 'Arum Cahyanti', 22, 3, 'Kalipucang Kulon Welahan Jepara Jawa Tengah', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-02-28 10:47:56', '2023-02-28 10:47:56');
INSERT INTO `tenant` VALUES (1265, 109, 'public/foto_profil_tenant/63fd7a7a81ede.jpg', 'Smartlight', 'Satria Pinandita', 22, 3, 'Jalan Dinar Blok C No. 24 Muktiharjo Kidul, Pedurungan\r\n Semarang – 50197', NULL, NULL, NULL, NULL, NULL, '<p>Nama dan Slogan Bisnis\r\n</p><p>1. Nama produk : SMART LIGHT\r\n</p><p>2. Slogan : Siram Bioporinya, Manfaatkan Energinya\r\n</p><p>Data Perusahaan\r\nNama perusahaan kami yaitu PT. Esa Eco Energi. berdiri pada hari minggu,tanggal 1\r\nSeptember 2017 di desa Sekaran kecamatan Gunungpati Kabupaten Semarang. Jenis\r\nperusahaan home industri. PT. Esa Eco Energi adalah Perusahaan yang berjalan pada bidang\r\nproduk ramah lingkungan, penjualan produk saat ini adalah SMART LIGHT yaitu Lampu\r\ntaman biopori sebagai solusi energi alternatif., kemudian dikembangkan menjadi Smart\r\nLight biopori mini yang berfungsi sebagai lampu emergency. Dalam rangka menangkap\r\nkesempatan sekaligus menyalurkan inovasi kami tentang energi baru terbarukan dan ramah\r\nlingkungan. Usaha ini kami juga mencoba untuk menyuguhkan dan mengenalkan tidak\r\nhanya alat itu sendiri tapi juga nilai dan manfaat yang terkandung pada teknologi tersebut.<br></p>', NULL, NULL, '2023-02-28 10:52:26', '2023-02-28 10:52:26');
INSERT INTO `tenant` VALUES (1266, 85, 'public/foto_profil_tenant/63fdb1395d97d.jpg', 'Sewek Natural Oil', 'M. Fathoni Irfan', 43, 2, 'Maredan, RT01 RW39, Sendangtirto, Berbah, Sleman, Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNoSpacing\" style=\"text-align:justify;text-indent:36.0pt\">Minyak obat herbal benama <b>Sewek Natural Oil</b> diracik oleh <b>M. Fathoni Irfan</b>, Seorang yang menekuni bidang pemberdayaan dan terapi, dan sudah banyak\r\npengalaman dalam terapi\r\npembetulan sendi, tulang belakang dan syaraf kejepit. Dia menjadi\r\ninisiator sekaligus founder dari <b>SEWEK\r\nTERAPI</b>, yang merupakan salah\r\nsatu metode seni tradisional Jawa pembetulan\r\ntulang belakang. Selain itu dia juga aktif dalam bidang pemberdayaan diri dengan metode “Sewek</p>\r\n\r\n<p class=\"MsoNoSpacing\" style=\"text-align:justify\">Meditasi”, seni meditasi pemberdayaan diri dan kesehatan. Sewek terapi,\r\nmerupakan warisan leluluhur hasil perpaduan olah tubuh, olah pikiran dan olah\r\nrasa yang bersinergi dengan alam.<o:p></o:p></p>\r\n\r\n<p class=\"MsoNoSpacing\" style=\"text-align:justify\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Hasilnya\r\nmenjadi sebuah metode klasik dan unik dalam hal pembetulan tulang belakang.\r\nDimana teknik ini sebenarnya sudah dilakukan oleh nenek moyang kita, dan telah\r\ndi ajarkan secara turun temurun. Tetapi teknik ini belum di bukukan dan di\r\nbakukan, sehingga dengan berjalannya<o:p></o:p></p>\r\n\r\n<p class=\"MsoNoSpacing\" style=\"text-align:justify\">waktu teknik ini sekarang sudah tidak terdengar dan hampir punah. Sewek\r\nTerapi hadir dengan menggali warisan leluhur, memuat kearifan lokal yang penuh\r\ndengan makna dan filosofi hidup. Bahwa manusia hidup itu tidak lepas dari peranan\r\norang tua terutama ibu, sewek (selendang) yang<o:p></o:p></p>\r\n\r\n<p class=\"MsoNoSpacing\" style=\"text-align:justify\">selalu di pakai oleh masyarakat Jawa ketika menggendong anak. Filosofi\r\nSewek Terapi, seorang manusia tidak boleh melupakan orang tua terutama ibu.\r\nKarena ibu lah yang berperan penting pada perkembangan tumbuh kembang anak\r\nsejak di lahir.<o:p></o:p></p>\r\n\r\n<p class=\"MsoNoSpacing\" style=\"text-indent:36.0pt\">Dari Pengalaman dalam\r\nmemberikan terapi, maka di cobalah untuk meramu sebuah herbal untuk membantu dalam\r\nproses terapi klien. Maka lahirlah <b>SEWEK\r\nNATURAL OIL</b>, merupakan perpaduan ramuan Jawa dan Dayak Kalimantan diolah\r\nsecara tradisional yang mengandung energi penyembuhan dari alam.</p>', '2022-08-27', '2023-02-27', '2023-02-28 14:45:05', '2023-11-06 09:38:09');
