INSERT INTO `tenant` VALUES (1276, 40, 'public/foto_profil_tenant/63fec01654be0.png', 'Angkuts Indonesia - CV Dua Ikan Group', 'M. Hafidz Waliyuddin', NULL, NULL, 'Jl. KARANGAN NO.1, KOMPLEK UNTAN. KEC. PONTIANAK TENGGARA, KOTA PONTIANAK\r\ninfo@angkuts.id', NULL, '1.200.000.000,00', 'Instagram, WA, Website, Jejaring Kerjasama', 'Indonesia', 'Tersedia', '<p><span style=\"color: rgb(99, 107, 111); font-family: &quot;Titillium Web&quot;, sans-serif; font-size: 16px;\">Angkuts. Established in Pontianak. A startup works to connect people and waste related actors. Waste actor such as garbage collector, trash processing place, communities, and so on.</span><br></p>', NULL, NULL, '2023-03-01 10:01:42', '2023-08-09 16:18:13');
INSERT INTO `tenant` VALUES (1277, 226, 'public/foto_profil_tenant/63fec12486372.jpg', 'KERITCU SUPER SINDI', 'Nur Rizkiana', 4, 2, 'Jl. RE. Martadinata No.09 Rt.05/02, Kel. Opas Indah, Kec. Taman Sari, Kota Pangkal Pinang, Bangka Belitung', NULL, NULL, NULL, 'Nasional', NULL, NULL, NULL, NULL, '2023-03-01 10:06:12', '2023-03-01 10:06:12');
INSERT INTO `tenant` VALUES (1278, 40, 'public/foto_profil_tenant/63fec1388fa66.png', 'Papon.id - CV. Aksi Kreasi Kolaborais', 'DImas Apriyanto', NULL, NULL, 'Jl. Danau Sentarum No. 286\r\nKota Pontianak', NULL, '25.000.000,00', 'Instagram, WA, Website', 'Kalimantan Barat', 'Tersedia', '<p><b><br></b></p><p><span style=\"color: rgb(63, 63, 70); font-family: Arial; font-size: medium;\"><b>Papon Indonesia adalah aplikasi media konten interaktif untuk mempromosikan pariwisata dan bisnis lokal yang ada di Pontianak. Aplikasi Papon dapat dinikmati dan dimainkan oleh semua kalangan umur. Semua berita terbaru dan acara terbaru yang ada di Pontianak, akan mudah diakses melalui aplikasi Papon. Aplikasi Papon akan segera bisa didownload di Play Store.</b></span><br></p>', NULL, NULL, '2023-03-01 10:06:32', '2023-08-09 16:19:17');
INSERT INTO `tenant` VALUES (1279, 40, 'public/foto_profil_tenant/63fec1c7e76c4.png', 'Pontinesia', 'Ridho Brilliantoro', NULL, NULL, 'Jl. Prof. Dr Hadari Nawawi Pontianak', NULL, '60.000.000,00', 'Instagram, WA, Website', 'Indonesia', 'Tersedia', '<p><br></p><p>Pontinesia adalah media yang berisi tentang keberagaman</p><p>potensi lokal dan dokumentasi digital Kota Pontianak.</p><p>Dari Pontianak Untuk Indonesia</p>', NULL, NULL, '2023-03-01 10:08:55', '2023-08-09 16:20:14');
INSERT INTO `tenant` VALUES (1280, 40, 'public/foto_profil_tenant/63fec25d41836.png', 'Pinawaste', 'Mahmud A.', NULL, NULL, 'Jl. Adi Sucipto 1 No.KM 10, Sungai Raya, Kec. Sungai Raya, Kabupaten Kubu Raya, Kalimantan Barat 78391', NULL, '40.000.000,00', 'Instagram, WA, Website', 'Indonesia', 'Tersedia', '<p><span style=\"font-family: Arial; font-size: 17px; letter-spacing: 0.25px;\"><font color=\"#000000\">Kami memproduksi produk biodegradable dan berkelanjutan terbuat dari Serat Daun Nanas (PLF) yang ramah lingkungan.</font></span><br></p>', NULL, NULL, '2023-03-01 10:11:25', '2023-08-09 16:19:52');
INSERT INTO `tenant` VALUES (1281, 40, 'public/foto_profil_tenant/63fec2da6ed77.png', 'Juragan Coffee - PT. Juragan Muda Indonesia', 'Budiansyah', 2, NULL, 'Jl. Pelita II Desa Punggur Kecil, Kecamatan Sungai Kakap, Kabupaten Kubu Raya, Kalimantan Barat.', NULL, '40.000.000,00', 'https://www.juragancoffee.com/', 'Kalimantan Barat', 'Tersedia', '<p style=\"border: 0px; font-size: 15px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 0); font-family: Poppins, sans-serif; text-align: justify;\"><span style=\"font-family: Arial;\">Melihat dari sisi demand-supply serta opportunity industri kopi lokal maupun global sangat berpotensi sekali. Budaya ngopi juga ternyata bukan hanya menjadi trend bermusim tetapi sudah menjadi kebutuhan hidup berbagai kalangan masyarakat baik muda maupun tua, dan tak pilih gender.</span></p><p style=\"border: 0px; font-size: 15px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 0); font-family: Poppins, sans-serif; text-align: justify;\"><span style=\"font-family: Arial;\">Melihat pada mata rantai produksi kopi di desa Punggur Kecil dan sekitarnya masyarakat hanya menjual bahan baku kopi mereka dalam bentuk bahan mentah, tidak diolah menjadi produk jadi (akhir). Melihat peluang ini Juragan Muda Indonesia berupaya untuk melahirkan produk kopi, menyerap bahan baku kopi dan diolah menjadi produk kemasan bahkan sampai siap saji.</span></p><p style=\"border: 0px; font-size: 15px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 0); font-family: Poppins, sans-serif; text-align: justify;\"><span style=\"font-family: Arial;\">Menambah mata rantai produksi maka akan muncul multi player efect, membuka lapangan pekerjaan, menyerap tenaga pekerja, yang pasti dapat menambah value dari komoditas/produk yang dikelolah.</span></p><p style=\"border: 0px; font-size: 15px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 0); font-family: Poppins, sans-serif; text-align: justify;\"><span style=\"font-family: Arial;\">Sejak 2018 sampai saat ini tidak hanya membuat sebuah produk kopi dan brand lokal, tetapi Juragan Muda Indonesia juga berupaya untuk memaksimalkan mata rantai produksi induatri kopi dari sektor hulu ke hilirnya. Mengingat lahan punggur yang sangat memungjinkan untuk dilakukan pengembangan sektor perkebunan kopi.</span></p><p style=\"border: 0px; font-size: 15px; margin-bottom: 1.75em; outline: 0px; vertical-align: baseline; color: rgb(0, 0, 0); font-family: Poppins, sans-serif; text-align: justify;\"><span style=\"font-family: Arial;\">Berwisata sambil belajar menjadi salah satu upaya yang dilakukan dengan konsep Kebun Agroeduwisata Kopi, yang akan memberikan Edukasi, Eksplorasi, dan Experient baru bagi masyarakat luas</span></p>', NULL, NULL, '2023-03-01 10:13:30', '2023-08-09 16:18:45');
