INSERT INTO `tenant` VALUES (1292, 35, 'public/foto_profil_tenant/63fedc4a02150.jpeg', 'Node Organic', 'David Chrisnaldi Setiawan', 20, 1, 'Jln. Siliwangi Koramil kp. Leuwinanggung RT 05/03, Ds. Nyangkowek, kec. Cicurug – Kab. Sukabumi', NULL, '500.000,00', 'online', 'internasional', 'menggunakan platform digital', '<p><span style=\"font-weight: 700; color: rgb(118, 118, 118); font-family: Roboto, Helvetica, sans-serif;\">Node</span><span style=\"color: rgb(113, 119, 125); font-family: Roboto, Helvetica, sans-serif;\">&nbsp;is a Product design company focused on creating ecofriendly lifestyle. Node sell limited Product and use the fund for our continuous research in ecofriendly materials and Product.&nbsp;</span><br></p>', '2022-03-01', '2022-09-30', '2023-03-01 12:02:02', '2023-03-01 12:02:02');
INSERT INTO `tenant` VALUES (1293, 227, 'public/foto_profil_tenant/640419b5924df.jpg', 'D\'EKA KARUNIA COFFEE LEGEND', 'TUTUK KURNIA WAHYUNINGTIAS', 23, NULL, 'JL LETJEND PANJAITAN NO 22 RT 001 RW 020 KELURAHAN KEBONSARI KECAMATAN SUMBERSARI KABUPATEN JEMBER PROVINSI JAWA TIMUR', NULL, '30.000.000,00', 'MEDIA SOSIAL (FB, INSTAGRAM), MARKETPLACE (SHOPEE, BLIBLI), OUTLET, TOKO OLEH OLEH', 'Antar Kota Kabupaten, Antar Provinsi, Nasional', 'Tahunan', '<p>D\'EKA KARUNIA COFFEE LEGEND merupakan Perusahaan yg bergerak di bidang Food &amp; Beverages (FnB) dimana menghasilkan produk inovasi olahan kopi dan cokelat yang dikemas secara praktis. Untuk produk olahan kopi ada berbagai macam varian, mulai dari kopi original seperti robusta, arabika, sampai ke inovasi kopi seperti ricebran kopi, kopi kapulaga, kopi blend robusta arabika, dan lainnya.</p><p>Olahan cokelat pun demikian, berbagai macam varian mulai dari cokelat milk 3in1, cokelat dark 3in1, cokelat dark (cocoa powder), sampai ke inovasinya seperti Cokelat Kapulaga 3in1.</p>', NULL, NULL, '2023-03-05 11:25:25', '2023-03-05 11:36:03');
INSERT INTO `tenant` VALUES (1294, 227, 'public/foto_profil_tenant/64041be340c60.jpg', 'CV MACARINDO BERKAH GROUP', 'HELMI ZAMRUDIANSYAH', 23, NULL, 'JL SRIWIJAYA XX NO 11 JEMBER', NULL, '30.000.000,00', 'INSTAGRAM, MARKETPLACE (SHOPEE)', 'Antar Kota Kabupaten, Antar Provinsi, Nasional', 'Bulanan', '<p>Perusahaan yang memproduksi snack Makaroni, dengan bahan premium dan rasa yang berkualitas, berdiri sejak Bulan April 2017 dan memiliki kapasitas produksi 500pcs per hari</p>', NULL, NULL, '2023-03-05 11:34:43', '2023-03-05 11:34:43');
