INSERT INTO `tenant` VALUES (1350, 39, 'public/foto_profil_tenant/64532b7ce94dd.jfif', 'Mie Ayam RAOSS', 'Moh. Abdul Malik', 23, NULL, 'Komplek Permata Biru, Blok R 106, Cinunuk, Cileunyi, Bandung', NULL, '24.500.000,00', 'Website , Instagram', 'Masih Lokal', NULL, '<p>Mie Ayam RAOSS merupakan sebuah brand dari inovasi Mie Ayam konvensional yang berdiri sejak tahun 1990 diwariskan secara turun-temurun. Mie Ayam RAOSS tidak hanya sebagai makanan yang memberikan kepuasan dari segi rasa saja, namun dari bahan baku yang digunakan mampu memenuhi kebutuhan gizi dalam setiap harinya.&nbsp;<br></p>', '2022-08-15', '2022-11-30', '2023-05-04 10:50:20', '2023-05-04 10:50:20');
INSERT INTO `tenant` VALUES (1351, 39, 'public/foto_profil_tenant/64532c802d170.jfif', 'Sora Trilogi', 'Fadilah Ahmad', 42, NULL, 'Jl. Mekar Biru Blok A No. 149 Cibiru, Bandung', NULL, '3.000.000,00', 'Website , Instagram', 'Lokal, Nasional, dan Internasional', NULL, '<p>Jasa Digital Marketing, Jasa Graphic Design, Jasa Business Consultant -&nbsp; Potensi dengan peluang market UMKM yang terus meningkat sepanjang bulan dan tahun.<br></p>', '2022-08-15', '2022-11-30', '2023-05-04 10:54:40', '2023-05-04 10:54:40');
