INSERT INTO `tenant` VALUES (1356, 39, 'public/foto_profil_tenant/645478602e027.jfif', 'Joeragan Artikel', 'Sri Kuswayati', 42, NULL, 'Komp. Margahayu Raya Blok A3 Jalan Uranus Utama VI No 74A Kel. Sekejati Kec. Buah Batu Bandung 40286', NULL, '40.000.000.000,00', 'Website , Instagram', 'Internasional', NULL, '<p>Buku (keunggulan : dihasilkan oleh member pelatihan yang terdiri dari IRT bekerja secara remote)&nbsp;</p><p>Pelatihan Online (keunggulan : dilaksanakan secara online dengan mentor dari kalangan IRT yang memiliki skill dan dapat melakukan transfer ilmu secara baik kepada peserta)</p>', '2022-08-15', '2022-11-30', '2023-05-04 11:47:50', '2023-05-05 10:30:40');
INSERT INTO `tenant` VALUES (1357, 39, 'public/foto_profil_tenant/645475a363c46.jfif', 'el-Moumtaza.com', 'Dr Uus Rustiman Lc.,M.Hum', 42, NULL, 'Jln Babakan Laksana 02/11 Desa Pangalengan Kab Bandung Jawa Barat 40378', NULL, '12.000.000,00', 'Website , Instagram', 'Lokasl, Nasional & International', NULL, '<p>Buku, Aplikasi Digital Arabic Course el Moumtaza<br></p>', '2022-08-15', '2022-11-30', '2023-05-04 11:50:08', '2023-05-05 10:18:59');
INSERT INTO `tenant` VALUES (1358, 39, 'public/foto_profil_tenant/64547892b9bee.jfif', 'sumbangbarang.com', 'Andi Setiawan', 42, NULL, 'Jl. Hayam Wuruk No.34-38, Citarum, Kec. Bandung Wetan, Kota Bandung, Jawa Barat 40115 Tenant Business Incubator Center (Bicube) Politeknik STIA LAN Bandung', NULL, NULL, 'Website , Instagram', 'Nasional', NULL, '<p>website pertama yang menyediakan layanan untuk menghubungkan donatur yang ingin menyumbangkan barang dan calon penerima barang, serta dapat memberikan informasi barang apa saja yang dapat diadopsi<br></p>', '2022-08-15', '2022-11-30', '2023-05-04 11:52:08', '2023-05-05 10:31:30');
INSERT INTO `tenant` VALUES (1359, 39, 'public/foto_profil_tenant/6454787f2bf0c.jfif', 'Ngaput Indonesia', 'Farhan Maldy Nugraha', 19, 1, 'Rancaekek Permai Blok C5 No 4 Rt 03 RW 18 Kec Ramcaekek Kab. Bandung', NULL, '25.000.000,00', 'Website , Instagram', 'Nasional', NULL, '<p>Pakaian, Tas, Sandal<br></p>', '2022-08-15', '2022-11-30', '2023-05-04 11:53:56', '2023-05-05 10:31:11');
INSERT INTO `tenant` VALUES (1360, 39, NULL, 'PICKNIC', 'Muhammad Maftuh Rizqi Rahardjo', 42, NULL, 'Jln. Banda No.40 Kota bandung', NULL, '12.000.000,00', 'Website , Instagram', 'Lokal, Jawa Barat (Sosial Media, Website)', NULL, '<p>Travel Planner&nbsp;</p><p>Integrasi program semua akomodasi wisata dalam satu aplikasi. Interaksi yang akan tersedia akan terhubung dengan Online Travel Agency sebagai bentuk sistem open gateway, dimana pengguna dapat dengan mudah mendapatkan paket wisata dan mengubah akomodasi.</p><p><br></p><p>Virtual Tour</p><p>Virtual Tour menyediakan 450 destinasi wisata di seluruh Indonesia dengan materi 3D menggunakan kamera 360 derajat. Berkolaborasi dengan Dinas UMKM dengan program #HelpUMKM dengan mempromosikan UMKM terpilih untuk dipromosikan sebagai produk unggulan daerah wisata.</p><p><br></p><p>Travel Consulting</p><p>Memberikan pelatihan untuk program Desa Wisata dan KKN universitas untuk membantu mengembangkan ekosistem SDM pariwisata. Selain itu, membantu memberikan rekomendasi dan analisis pasar untuk pengembangan wisata untuk pengembangan kebijakan pemerintah provinsi dalam hal pengembangan bisnis</p>', '2022-08-15', '2022-11-30', '2023-05-04 11:55:54', '2023-05-04 11:55:54');
INSERT INTO `tenant` VALUES (1361, 39, 'public/foto_profil_tenant/64547ce68ba3b.jfif', 'Koperasi Eptilu', 'Rizal Fahreza', 1, 2, 'Jalan Situgede No 1313, Desa Cigedug, Kec Cigedug Kab Garut, Jawa Barat', NULL, '1.625.000.000,00', 'website, instagram', 'Nasional', NULL, '<p><span style=\"color: rgb(68, 68, 68); font-family: Inter, arial, helvetica, sans-serif; font-size: 15px;\">Eptilu merupakan salah satu Agrowisata dan kebun edukasi yang ada di Garut. Dalam konsepnya, Eptilu menerapkan Closed Loop System, dimana semua pihak terlibat langsung mendampingi petani mulai dari proses produksi.</span><br></p>', '2021-06-10', '2023-11-30', '2023-05-05 10:49:58', '2023-05-08 15:13:16');
INSERT INTO `tenant` VALUES (1362, 39, 'public/foto_profil_tenant/64547eccc8d38.jfif', 'Bizlook', 'Ikhwan Nul Yusuf Maulana', 42, 3, 'Jl. raya Banjaran Langonsari Pameungpeuk Bandung', NULL, '210.000.000,00', 'Website , Instagram', 'Nasional', NULL, '<p>Bizlook merupakan Online C2C&nbsp; Marketplace Jasa&nbsp; yang&nbsp; menghubungkan antara Pelaku UMKM dengan Profesional untuk mengatasi beragam isu bisnis sebagai platform One Stop Business Solution.<br></p>', '2021-06-10', '2023-11-30', '2023-05-05 10:58:04', '2023-05-08 15:11:49');
INSERT INTO `tenant` VALUES (1363, 39, 'public/foto_profil_tenant/6458883040a7a.jfif', '8 Ice Blend & Squash', 'Reno Indra Pramana', 23, NULL, 'Perumahan Mutiara Cempaka Blok E No. 14 RT/RW: 03/09 Desa Cempaka Kecamatan Plumbon Kabupaten Cirebon - Jawa Barat', NULL, '100.000.000,00', 'Web, Instagram', 'Nasional', NULL, '<p>8 Ice Blend &amp; Squash adalah bisnis&nbsp; minuman kekinian&nbsp; berbasis kemitraan yang sudah memiliki lebih dari 100 mitra yang tersebar di seluruh Indonesia. Keunggulan produk:</p><p>-&nbsp; &nbsp; &nbsp; &nbsp;Bentuk/wadah penyimpanan menggunakan pouch</p><p>-&nbsp; &nbsp; &nbsp; &nbsp;Memiliki 35 varian rasa</p>', '2021-06-10', '2023-11-30', '2023-05-08 12:27:12', '2023-05-08 15:10:49');
INSERT INTO `tenant` VALUES (1364, 39, 'public/foto_profil_tenant/64588a8d65377.jfif', 'EcoplastID', 'Gabriel Sebastian Butarbutar', 13, 2, 'Jalan Dago No. 320 Bandung', NULL, '100.000.000,00', 'Website , Instagram', 'Nasional', NULL, '<p>EcoplastID merupakan produk bioplastik berupa kantong belanja yang terbuat dari limbah agro industri seperti limbah kulit singkong dan tandan kosong kelapa sawit. Produk bersifat biodegradable dan compostable karena bisa terdegradasi kurang dari 8 bulan sehingga ketika berada di alam tidak merusak lingkungan. EcoplastI memiliki karakteristik yang sama dengan kantong plastik pada umumnya namun yang membedakannya adalah biodegradablenya. Keunggulan:</p><p>-&nbsp; &nbsp; &nbsp;Produk lebih terjangkau dari kompetitor</p><p>-&nbsp; &nbsp; &nbsp;Menggunakan raw material limbah agroindustri yang kurang dimanfaatkan dan ketersediaannya di Indonesia cukup banyak</p><p>-&nbsp; &nbsp; &nbsp; &nbsp; Bahan yang digunakan bukan merupakan bahan pangan seperti&nbsp; &nbsp;yang menggunakan singkong, jagung dan kentang sehingga tidak mengganggu keseimbangan pangan di masa depan.</p><p>-&nbsp; &nbsp; &nbsp;Produk tahan terhadap air tidak seperti kompetitor yang mudah larut dalam air.</p><p>-&nbsp; &nbsp; &nbsp; &nbsp; Produk berkekuatan daya&nbsp; tarik&nbsp; yang&nbsp; cukup sekitar 5-8 kg kapasitas maksimum per satuan.</p>', '2021-06-10', '2023-11-30', '2023-05-08 12:37:17', '2023-05-08 15:12:26');
INSERT INTO `tenant` VALUES (1365, 39, 'public/foto_profil_tenant/64588c182fce0.jfif', 'Koperasi Wirausaha Jabar Sejahtera (WJS)', 'Tri Agustina Hernawati', 23, NULL, 'Komp. Lucky square mall antapani', NULL, NULL, 'Website , Instagram', 'Nasional', NULL, '<p>Koperasi WJS merupakan koperasi yang bergerak di bidang pemasaran kumpulan produk UMKM se Jawa Barat yang dibentuk pada tahun 2016. Koperasi WJS beranggotakan pelaku UMKM berupa sektor makanan dan minuman, fashion, handycraft, dan jasa kecantikan<br></p>', '2021-06-10', '2023-11-30', '2023-05-08 12:43:52', '2023-05-08 15:13:39');
INSERT INTO `tenant` VALUES (1366, 39, 'public/foto_profil_tenant/64589f153d90b.jfif', 'SCOBY-TEA', 'Annisa Abdiwijaya Qaromah', 23, NULL, 'Jl. Sukagalih Gg. Pak Elas II no 289/182 B Rt 01 Rw 08,  kel. Cipedes, kec. Sukajadi, Bandung 40162', NULL, NULL, 'Website , Instagram', 'Nasional', NULL, '<p>Minuman kombucha ready to drink hasil fermentasi teh manis berbahan baku teh bunga menggunakan bakteri dan jamur probiotik yang akan akan kandungan asam organik, vitamin, dan antioksidan, bermanfaat menjaga kesehatan dan mencegah penyakit kronis. Kapasitas produksi scoby.tea mencapai 250-1000L perbulan.<br></p>', '2021-06-10', '2023-11-30', '2023-05-08 14:04:53', '2023-05-08 15:14:37');
INSERT INTO `tenant` VALUES (1367, 39, 'public/foto_profil_tenant/64589fb170048.jfif', 'El Nadya / Prajurit Kopi Rempah', 'Sri Indirahayu', 23, NULL, 'Kp. Wangunwati Rt. 02 / Rw. 01 Desa Sukawangun', NULL, '180.000.000,00', 'Website , Instagram', 'Nasional', NULL, '<p>El Nadya merupakan produk kopi yang dipadukan dengan rempah.&nbsp;</p><p>Keunggulan :</p><p>-&nbsp; &nbsp; &nbsp;Terbuat dari biji kopi pilihan</p><p>-&nbsp; &nbsp; &nbsp;Mengandung rempah-rempah yang bermanfaat untuk kesehatan</p><p>-&nbsp; &nbsp; &nbsp;Kopi rempah praktis dan unik</p><div><br></div>', '2021-06-10', '2023-11-30', '2023-05-08 14:07:29', '2023-05-08 15:12:50');
INSERT INTO `tenant` VALUES (1368, 39, 'public/foto_profil_tenant/6458a0812e631.jfif', 'Saung Hidroponik Respati', 'Adi Gunadi Nurhidayat', 1, 2, 'Jl. Raya Barat Kp. Mekarsari No.78, RT.03/RW.2, Singasari, Kec. Singaparna, Kab. Tasikmalaya, Jawa Barat 46412', NULL, '41.943.337,00', 'Website , Instagram', 'Lokal dan Nasional', NULL, '<p>Saung&nbsp; &nbsp;Hidroponik&nbsp; &nbsp;Respati&nbsp; &nbsp;merupakan&nbsp; pusat&nbsp; belajar&nbsp; &nbsp;dan&nbsp; &nbsp;belanja&nbsp; &nbsp;berbagai&nbsp; jenis&nbsp; produk pertanian urban farming hidroponik pertama di Tasikmalaya</p><p>Keunggulan:</p><p>-&nbsp; &nbsp; &nbsp;Sudah dikenal luas di Tasikmalaya dan sekitarnya</p><p>-&nbsp; &nbsp; &nbsp;Memiliki teknisi instalasi hidroponik yang sudah berpengalaman</p><p>-&nbsp; &nbsp; &nbsp;Memiliki cukup banyak jejaring dari instansi pemerintah, petani dan UMKM&nbsp;</p><div><br></div>', '2021-06-10', '2023-11-30', '2023-05-08 14:10:57', '2023-05-08 15:14:18');
INSERT INTO `tenant` VALUES (1369, 39, 'public/foto_profil_tenant/6458a4c716274.jfif', 'Celosia Etnik', 'Valeria  Nisatama', 19, 1, 'Jl Tegal Kawung No 66 RT 01/08 Kel Cipageran Kec Cimahi Utara 40511', NULL, '680.000.000,00', 'Website , Instagram', 'Lokal dan Nasional', NULL, '<p>Celosia Etnik&nbsp; merupakan UKM bergerak&nbsp; di&nbsp; bidang fashion berupa outer&nbsp; batik&nbsp; yang bertujuan untuk mensejahterakan penjahit-penjahit wanita rumahan dan memasarkan batik modern secara global. Pemasaran dilakukan secara online melalui media sosial dan marketplace.&nbsp;</p><p>/bulan.</p><p>Keunggulan</p><p>-&nbsp; &nbsp; &nbsp;Batik ready to wear</p><p>-&nbsp; &nbsp; Bisa customize size dan model baju batik</p><p>-&nbsp; &nbsp; &nbsp;Worldwide shipping</p><div><br></div>', '2021-06-10', '2023-11-30', '2023-05-08 14:29:11', '2023-05-08 15:12:07');
INSERT INTO `tenant` VALUES (1370, 39, 'public/foto_profil_tenant/6458a5349e04c.jfif', 'Amorina', 'Michelle Azista Nabila Casandra', 43, 2, 'Jalan ibu ganirah no 92 cimahi', NULL, '150.000.000,00', 'Website , Instagram', 'Nasional', NULL, '<p>Amorina adalah Health and Beauty Products berbahan dasar Ganggang Hijau-Biru Spirulina yang dikombinasikan dengan bahan alami dan ramah lingkungan. Amorina memiliki manfaat bagi kesehatan untuk meningkatkan imunitas dan mencegah resiko serangan penyakit degeneratif, melindungi tubuh dari resiko kanker dan anti inflamasi.<br></p>', '2021-06-10', '2023-11-30', '2023-05-08 14:31:00', '2023-05-08 15:11:31');
INSERT INTO `tenant` VALUES (1371, 158, NULL, 'JJ COOK and CAKE', 'II HARNENIS', 23, 2, 'BANCAR, RT 002 RW 005, PURBALINGGA', NULL, NULL, 'akun media sosial', 'Purbalingga, Banyumas', NULL, 'JJ Cook and Cake merupakan salah satu produk&nbsp;', '2023-02-20', '2023-02-20', '2023-05-11 15:21:09', '2023-05-11 15:21:09');
