INSERT INTO `tenant` VALUES (1374, 158, NULL, 'DAPOER SYAFFIRA', 'NUR FITRI SETIASIH', 23, 2, 'PERUM PURI TAMA INDAH JLN. MATOA BLOK K-6, DS. GEMURUH RT 02/08, PADAMARA PURBALINGGA', NULL, NULL, NULL, NULL, NULL, NULL, '2023-02-20', '2023-02-20', '2023-05-11 15:25:41', '2023-05-11 15:25:41');
INSERT INTO `tenant` VALUES (1375, 39, NULL, 'Kopi Celup Kutawaringin', 'Heru Rusdiana', 23, 2, 'Kp.muara DS. Kopo Kutawaringin Kab. Bandung', NULL, '600.000.000,00', 'WhatsApp Business , Instagram, Website', 'Lokal dan Nasional', NULL, '<p>Kopi Celup Kutawaringin adalah Kopi Lokal dengan aroma Khas dari Pegunungan di Kab. Bandung, kopi lokal yang unik dengan penyajian yang simpel dan praktis serta memiliki rasa khas dengan inovasi toping kekinian.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 07:39:01', '2023-05-12 07:39:01');
INSERT INTO `tenant` VALUES (1376, 39, 'public/foto_profil_tenant/645d8b1c28aa8.jfif', 'Zico Corn Chips', 'Ahmad Shohibboniawan Wahyudi,S.P', 23, 2, 'Perumaham Grande Kencana Blok B.12 Rt.03/10 Kel. Harapanjaya Kec. Cibinong Kab. Bogor', NULL, NULL, 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Zico Corn Chips dibentuk pada awalnya hanya untuk menjadi sebuah</p><p>usaha mahasiswa yang didalamnya sebagai media pembelajaran dan</p><p>pengalaman untuk bekal dalam menghadapi dunia pekerjaan setelah</p><p>lulus kuliah. Seiring berjalannya waktu, komitmen dalam menjalankan</p><p>usaha ini menjadi lebih jelas, banyak harapan-harapan yang menjadi</p><p>tujuan dengan terbentuknya Zico Corn Chips diantaranya:</p><p>• Menjadi peluang atau membuka lapangan pekerjaan bagi masyarakat</p><p>di sekitar</p><p>• Dapat memberdayakan masyarakat di sekitar</p><p>• Menjadi suatu perusahaan yang bergerak dalam bidang pangan di&nbsp;</p><p>Indonesia</p><p>• Terus berinovasi dan memajukan sektor pertanian di Indonesia&nbsp;</p><p>khususnya dalam bidang pengolahan produk pertanian</p>', '2021-06-10', '2023-11-10', '2023-05-12 07:41:00', '2023-05-12 07:41:00');
INSERT INTO `tenant` VALUES (1377, 39, 'public/foto_profil_tenant/645d8b9f059ee.jfif', 'Ragam Racikan Eksotis / Barawang', 'Yulia Sari', 23, 2, 'Dusun Puhun RT 013 RW 004 Desa Kramatmulya Kecamatan Kramatmulya Kabupaten Kuningan, Jawa Barat 45553', NULL, '36.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Barawang merupakan produk olahan bawang sumenep yang memiliki 3 varian rasa yaitu Original, Pedas, dan Rebon daun Jeruk. Setiap varian rasa memiliki 2 jenis kemasan yaitu standing pouch (100gr) serta botol (65gr).&nbsp;</p><p>Keunggulan dari produk Barawang:</p><p>-&nbsp; &nbsp; &nbsp;100% bawang sumenep tanpa campuran tepung.</p><p>-&nbsp; &nbsp; &nbsp;Kemasan praktis dan menarik.</p><p>-&nbsp; &nbsp; &nbsp;Bahan baku berkualitas, tekstur renyah, rasa tidak pahit, tanpa pengawet,&nbsp; &nbsp;serta sangat sedikit mengandung minyak.</p><p><br></p>', '2021-06-10', '2023-11-10', '2023-05-12 07:43:11', '2023-05-12 07:43:11');
INSERT INTO `tenant` VALUES (1378, 39, NULL, 'Pertanian Budidaya Paprika', 'Delia Indah Khoerunnisa', 2, 2, 'Kp. Cikandang Kecamatan Cikajang Kabupaten Garut Provinsi Jawa Barat', NULL, '90.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Pangeran Farm merupakan UKM yang bergerak pada komoditas pertanian yaitu budidaya paprika&nbsp; dengan&nbsp; pengkondisian&nbsp; iklim&nbsp; mikro&nbsp; di&nbsp; dalam&nbsp; greenhouse&nbsp; sehingga&nbsp; paprika&nbsp; yang dihasilkan memiliki kualitas unggul. Keunggulan:<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 07:46:19', '2023-05-12 07:46:19');
INSERT INTO `tenant` VALUES (1379, 39, 'public/foto_profil_tenant/645ddf4f80eee.jfif', 'PT. Java Preanger Lestari Mandiri', 'Fitria Nuraeni', 2, 2, 'Jl. Raya Rancaekek Majalaya Dusun Tiga Rt 001 Rw 005 Solokanjeruk', NULL, '1.750.000.000,00', 'WhatsApp Business , Instagram, Website', 'Lokal, Nasional, Internasional', NULL, '<p>PT Java Preanger Lestari Mandiri merupakan wadah usaha produk kopi dari gabungan koperasi di Kabupaten Bandung yang memiliki keunggulan :</p><p>-&nbsp; &nbsp; &nbsp;Kapasitas produksi besar karena luas perkebunan mencapai 11.000 ha</p><p>-&nbsp; &nbsp; &nbsp;Peluang pasar sudah terbuka</p><p>-&nbsp; &nbsp; &nbsp;Kualitas dan kuantitas produk</p><p>-&nbsp; &nbsp; &nbsp;Bisa melayani pembelian dalam volume besar</p><div><br></div>', '2021-06-10', '2023-11-10', '2023-05-12 13:40:15', '2023-05-12 13:40:15');
INSERT INTO `tenant` VALUES (1380, 39, 'public/foto_profil_tenant/645df18888139.jfif', 'KaKebon', 'Dianisa Aska', 1, 2, 'Lembah Jamur Panyandaan, Jalan Babakan Slamet, Kecamatan Cisarua, Kabupaten Bandung Barat', NULL, '201.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>KaKebon merupakan produsen jamur tiram putih segar. Kami hadir dengan nilai kembali ke kebun dan kembali ke alam yang asri. Fokus</p><p>dengan budidayanya memungkinkan KaKebon memberikan produk jamur segar bebas pestisida kepada konsumen dalam berbagai ukuran</p><p>kemasan sesuai kebutuhan.</p><p>Limbah media tanam (baglog) kami usahakan untuk bekerja sama agar dapat dimanfaatkan sebagai pupuk ataupun media untuk cacing agar tidak menjadi limbah</p>', '2021-06-10', '2023-11-10', '2023-05-12 13:44:50', '2023-05-12 14:58:00');
INSERT INTO `tenant` VALUES (1381, 39, 'public/foto_profil_tenant/645de1522856f.jfif', 'Saung Yoghurt', 'Jajang Nurjaman', 23, 2, 'Kp.Sukamnis RT 003/001 Sukasukur Cisayong Tasikmalaya Jawabarat', NULL, '180.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Saung&nbsp; Yoghurt&nbsp; merupakan usaha bertempat di&nbsp; Tasikmalaya, memproduksi yoghurt dengan keunggulan rasa khas tanpa pemanis dan pengawet dengan lima varian rasa buah.<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 13:48:50', '2023-05-12 13:48:50');
INSERT INTO `tenant` VALUES (1382, 39, 'public/foto_profil_tenant/645de21f13b81.jfif', 'Pempek Gluten Free OMBAI', 'Indah Aprilia', 23, NULL, 'Cijawura girang 5, sekejati, buahbatu', NULL, '120.000.000,00', NULL, 'Lokal dan Nasional', NULL, '<p>Pempek Ombai satu produsen kuliner palembang yang berdomisili di Bandung. Nama ‘ombai’ adalah panggilan khas untuk nenek dari satu daerah di Sumatera Selatan yaitu Komering. Pempek Ombai telah dimodifikasi dengan rendah kalori agar lebih sehat aman dan bergizi. Pempek ombai berkomitmen memproduksi hanya dengan 100% ikan<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 13:52:15', '2023-05-12 13:52:15');
INSERT INTO `tenant` VALUES (1383, 39, 'public/foto_profil_tenant/645de2b24ca5a.jfif', 'PT Olahkarsa Inovasi Indonesia', 'Unggul Yoga Ananta', NULL, NULL, 'Jl Bukit Raya Tengah Nomor 206B Kota Bandung', NULL, '8.600.000.000,00', 'WhatsApp Business , Instagram, Website', 'Lokal dan Nasional', NULL, '<p>Perusahaan konsultasi CSR pertama di Indonesia&nbsp; yang&nbsp; memiliki&nbsp; sistem aplikasi&nbsp; terpadu (SR Apps) untuk optimalisasi program CSR perusahaan dengan tiga produk</p><p>-&nbsp; &nbsp; &nbsp;Sistem Aplikasi Terpadu bagi perusahaan (SR Apps)</p><p>-&nbsp; &nbsp; &nbsp;Platform Jaringan Ahli (ExpertHub)</p><p>-&nbsp; &nbsp; &nbsp;Platform Media CSR (Impactholic.com)&nbsp;</p><div><br></div>', '2021-06-10', '2023-11-10', '2023-05-12 13:54:42', '2023-05-12 13:54:42');
INSERT INTO `tenant` VALUES (1384, 39, 'public/foto_profil_tenant/645de4c74b753.jfif', 'Fatani/ubi madu dan olahannya', 'Fahmi Azkiya', 1, 2, 'atani Farm, Saung Sukandi - Jl. Wanayasa-Bojong, Cisasarap, ds. Wanayasa, kec. Wanayasa, kab. Purwakarta', NULL, '48.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Produk fatani berupa Ubi madu mentah, Ubi madu Panggang, dan berbagai olahan-olahan yang berbahan dasar dari ubi madu, seperti Pao Ubi, Kremes Ubi dan Keripik Ubi.<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 14:03:35', '2023-05-12 14:03:35');
INSERT INTO `tenant` VALUES (1385, 39, 'public/foto_profil_tenant/645df1a04ebfc.jfif', 'Peternakan dan Pertanian (Koperasi Melati Harapan Bangssa)', 'Nani Suherni, SE, MM.', 1, 2, 'Blok Ahad RT 02/RW 02 Desa Karangsambung, Kecamatan Kadipaten Kabupaten Majalengkang', NULL, '1.800.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Koperasi Melati Harapan Bangsa merupakan koperasi yang&nbsp; bergerak di&nbsp; bidang pertanian komoditas porang dan peternakan sapi. Hasil komoditas porang bermitra dengan PT PAIDI INDO PORANG, Madiun, Jawa Timur dan peternakan sapi dipasarkan melalui para pedagang di pasaran.<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 14:27:41', '2023-05-12 14:58:24');
INSERT INTO `tenant` VALUES (1386, 39, 'public/foto_profil_tenant/645df1744d545.jfif', 'Boksay.id', 'Muhammad Dien Rasyid', 1, 2, 'Kota Bandung', NULL, '50.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Boksay.id adalah start up e-commerce berbasis website dan aplikasi mobile yang didedikasikan untuk memberikankemudahan bagi pelanggan dalam mendapatkan berbagai bahan komoditas segar dan hasil olahan pertanian, yang disalurkan langsung dari produsen dan distributor lokal.</p><p>Keunggulan:</p><p>-&nbsp; &nbsp; &nbsp;Pelanggan dapat bertransaksi tanpa minimum order dengan ongkos kirim seikhlasnya</p><p>-&nbsp; &nbsp; &nbsp;Mengusung konsep go green menggunakan kemasan ramah lingkungan</p><p>-&nbsp; &nbsp; &nbsp;Tidak&nbsp; terjadi&nbsp; penumpukan&nbsp; stok,&nbsp; karena&nbsp; pengadaan&nbsp; produk&nbsp; berdasarkan&nbsp; jumlah preorder</p><div><br></div>', '2021-06-10', '2023-11-10', '2023-05-12 14:57:40', '2023-05-12 14:57:40');
INSERT INTO `tenant` VALUES (1387, 39, NULL, 'KKMB ( Koperasi Kesejahteraan Mahasiswa Bandung )', 'Marsa Hotimah', NULL, NULL, 'Jl Jalaprang 11 Kelurahan Sukaluyu Kec. Cibeunying Kaler', NULL, NULL, 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Koperasi Keluarga Mahasiswa Bandung (KKMB) merupakan koperasi&nbsp; yang diinisiasi oleh aktivis mahasiswa Bandung. Koperasi ini merupakan wadah usaha dari berbagai kategori usaha, mulai dari retail buku dan jasa (konveksi, penyewaan gedung, rental mobil, wartel, desain grafis, dll). Selain itu,&nbsp; KKMB juga merupakan lembaga pencetak kader-kader yang menumbuhkembangkan enterpreneurship<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 15:02:39', '2023-05-12 15:02:39');
INSERT INTO `tenant` VALUES (1388, 39, NULL, 'Organic Palm Sugar/Gula Semut Aren', 'Dr Uus Rustiman Lc.,M.Hum', 23, NULL, 'Jln Babakan Laksana 02/11 Desa Pangalengan Kec pangalengan Kab Bandung Jawa Barat 40378', NULL, '650.000.000,00', 'WhatsApp Business , Instagram', 'Lokal dan Nasional', NULL, '<p>Gula Aren Semut Organic Palm Sugar El&nbsp; Moumtaza merupakan produk hasil riset&nbsp; yang bermanfaat untuk kesehatan dan terbuat dari bahan baku pilihan dengan kualitas terbaik<br></p>', '2021-06-10', '2023-11-10', '2023-05-12 15:04:11', '2023-05-12 15:04:11');
INSERT INTO `tenant` VALUES (1389, 13, 'public/foto_profil_tenant/645f2db61c4ca.jpg', 'TSDC STORE', 'Ni Wayan Sri Mustika Dewi,SE', NULL, NULL, 'Jl. Jagaraga No 5 Celuk Sukawati Gianyar Bali', NULL, '15.000.000,00', 'comerce dan marketpalce.ecomerce ig dan flanding page marketpalce di shopee, tokopedia, blibli', 'Nasional, Internasional', 'ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">TSDC berdiri sejak tgl 6 Maret 2020, bergerak dibidang handicraf anyaman berbahan dasar serat alam seperti bahan baku dari ate, rotan, pandan dan purun. </span><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">TSDC</span><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\"> memberdayakn pengrajin disekitar untuk membuat produk seperti tas, dompet dan homedecor. saat ini TSDC udah bekerja sama dengan  toko oleh oleh di bali yaitu the keranjang, hotel bintang 5 yaitu di conrad dan di beacwalk di UNiqlo. Penjualan kami di nasional dan internasional. Produk TSDC udh ekpor ke negara jepang, mesir, autralia dan timur leste. Besar harapan kami setelah mengkuti inkubator dari UNHI kami bisa mendapatkan Investor dan menambah akses pasar baru buat ekpansi kita kedepannya.</span></p>', '2023-03-06', '2023-09-06', '2023-05-13 13:27:02', '2023-06-16 15:28:53');
INSERT INTO `tenant` VALUES (1390, 13, 'public/foto_profil_tenant/645f2f0432632.jpg', 'Littlepaobali', 'Renny S Kusuma', NULL, NULL, 'Jl. Batanghari XII no 18', NULL, '45.000.000,00', 'B2B', 'Nasional', 'ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Usaha kuliner yang memproduksi frozen food and aneka kripik</span><br></p>', '2023-03-06', '2023-09-06', '2023-05-13 13:32:36', '2023-06-16 15:34:58');
INSERT INTO `tenant` VALUES (1391, 13, 'public/foto_profil_tenant/645f2f947419c.jpg', 'Shreya and craft', 'Sri Martini Dian Handayani', NULL, NULL, 'Banjar Tegal Temu Kelod, Desa Tibubiu, Kecamatan Kerambitan, Tabanan', NULL, '12.000.000,00', 'Media Sosial', 'Lokal', 'ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Pembuatan tas jinjing berbasis kain endek Bali</span><br></p>', '2023-03-06', '2023-09-06', '2023-05-13 13:35:00', '2023-06-16 15:37:29');
INSERT INTO `tenant` VALUES (1392, 13, 'public/foto_profil_tenant/645f30413033d.png', 'PT. Komoditas Bumi Nusantara', 'I Nyoman Wahyu Widya Adnyana', 2, 2, 'Desa Pujungan, Pupuan, Tabanan, Bali', NULL, '15.000.000,00', 'Instagram, TikTok', 'Nasional', 'ada', '<p>Perkebunan Kopi</p>', '2023-03-06', '2023-09-06', '2023-05-13 13:37:53', '2023-06-16 15:36:23');
INSERT INTO `tenant` VALUES (1393, 13, 'public/foto_profil_tenant/645f30c47e119.png', 'Namaste 21 Handmade', 'Novita Wesley Simanjuntak', NULL, NULL, 'Jl. IB Mantra Gg. Sripadangkertha no.27 Kesambi Kesimankerthalangu, Dentim', NULL, '15.000.000,00', 'Sosial Media, Marketplace', 'Lokal, Nasional', 'ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Namaste 21 Handmade is a local brand from Bali, Indonesia that produces artisan jute bags. All of Namaste 21 bags are handmade products that are made by order. Namaste 21 guarantees that all works produced are made of 100% natural jute and 90% of domestic materials. The elegant and multifunctional design of the bag, mixed in traditional Balinese Woven Endek Fabrics, are the characteristics of Namaste 21 works.\r\nNamaste 21 offers a wide selection of jute bags for women and unisex. The main products of Namaste 21 consist of clutches, tote bags, messenger bags, shoulder bags, and backpacks.\r\nDo come and check out some more about us on </span><br></p>', '2023-03-06', '2023-09-06', '2023-05-13 13:40:04', '2023-06-16 15:33:21');
INSERT INTO `tenant` VALUES (1394, 13, 'public/foto_profil_tenant/645f3164a08de.jpeg', 'Kinan Florist', 'Ida Ayu Anjani Dwi Pradnyani', NULL, NULL, 'Jl. Padang Luwih no 7 Dalung', NULL, '50.000.000,00', 'Media Sosial', 'Lokal, Nasional, Internasional', 'ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Kinan florist : merukapan sebuah usaha yang menyediakan berbagai jenis rangkaian bunga, bunga utama yang kamu gunakan yaitu bunga lokal dan semi holand. Untuk pemesanan bisa melalui online/offline dan sudah disupport dengan pengiriman via Ojek Online.</span><br></p>', '2023-03-06', '2023-09-06', '2023-05-13 13:42:44', '2023-06-16 15:31:42');
INSERT INTO `tenant` VALUES (1395, 134, 'public/foto_profil_tenant/65718b4fc5c1b.jpeg', 'Joran natural dye', 'Ariana restu handari', NULL, 1, 'Masjid al mujahidin street 116 Rt 2 rw 7 limo meruyung depok', NULL, '5.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Produk joran natural dye adalah fashion, wall hanging tapestry, fiber art accesories, totebag craft; menggunakan bahan bahan alamiah , kain wastra tenun dan batik, lukisan spontan di atas karung goni dan disulam benang wool, pembuatan tapestry sebagai bagian dari aksentuasi di pakaian kebaya kutubaru, sematkan bahan alam manik2 .sentuhan art craft fiber menjadi keunggulan produk joran natural dye. Produk accesories kalung dengan design yang selalu berbeda menggunakan bahan2 recycle dan alam</p>', '2023-03-06', '2023-09-01', '2023-05-22 10:52:26', '2024-07-30 10:39:26');
INSERT INTO `tenant` VALUES (1396, 134, 'public/foto_profil_tenant/657171ebd5c69.png', 'Kampoeng Anyaman', 'Danang Sudrajat', NULL, 1, 'Dk. Pendekel Mergosono Buayan Kabupaten Kebumen', NULL, '180.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Produk kerajinan dari serat alam pandan, mendong, kulit kayu yg dibuat beragam produk seperti tas, topi, strapjam, sandal , box Bahan ramah lingkungan, Lebih fashionable</p>', '2023-03-06', '2023-09-01', '2023-05-22 11:29:09', '2024-07-30 14:51:31');
