INSERT INTO `tenant` VALUES (1414, 13, 'public/foto_profil_tenant/64740b4929bba.png', 'Usadha.com', 'Nyoman Adi Watu Karuniawan Putra', NULL, NULL, 'Buleleng', NULL, NULL, 'Web', NULL, NULL, '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,&quot;serif&quot;;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Usadha.com merupakan layanan berbasis web dan\r\naplikasi yang menawarkan layanan pengobatan komplementer, sehingga setiap orang\r\nyang akan melakukan terapi dapat lebih mudah dalam berkomunikasi dengan <i>therapist</i> melalui platform tersebut</span><span style=\"font-family: &quot;Times New Roman&quot;, &quot;serif&quot;; font-size: 12pt;\">Usadha.com merupakan layanan berbasis web dan\r\naplikasi yang menawarkan layanan pengobatan komplementer, sehingga setiap orang\r\nyang akan melakukan terapi dapat lebih mudah dalam berkomunikasi dengan </span><i style=\"font-family: &quot;Times New Roman&quot;, &quot;serif&quot;; font-size: 12pt;\">therapist</i><span style=\"font-family: &quot;Times New Roman&quot;, &quot;serif&quot;; font-size: 12pt;\"> melalui platform tersebut</span><span style=\"font-family: &quot;Times New Roman&quot;, &quot;serif&quot;; font-size: 12pt;\">&nbsp;</span></p>', '2021-11-14', '0023-11-14', '2023-05-29 09:17:45', '2023-05-29 09:17:45');
