INSERT INTO `tenant` VALUES (1432, 234, 'public/foto_profil_tenant/647e85627780e.jpeg', 'The Snackris', 'I Putu Krisna', 23, NULL, 'The Snackris, br Blangsinga, desa Saba, kec. Blahbatuh, kab. Gianyar-Bali 80581', NULL, '3.000.000,00', 'instagram, whatsapp, tiktok, shopee', '80% lokal bali 20% luar bali', 'Ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">The Snackris merupakan usaha keripik pisang dengan varian rasa kekinian untuk menarik minat konsumen mencoba keripik pisang yang terlihat biasa saja menjadi lebih beda dan menarik</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:01:22', '2023-06-06 08:01:22');
INSERT INTO `tenant` VALUES (1433, 234, NULL, 'HANNAS.ID', 'DEKA', 19, NULL, 'Jln pantai batu bolong no 63a', NULL, '1.000.000,00', 'Offline / online', 'anak muda / penyuka fashion', 'Ada (Excel)', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">usaha saya bergerak pada bidang clothing, menggunakan bahan kain catton combat 30S dan menggunakan bahan dtf. Dan usaha saya juga bisa custom t-shirts satuan. </span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:04:01', '2023-06-06 08:04:01');
INSERT INTO `tenant` VALUES (1434, 234, 'public/foto_profil_tenant/647e88319dfb9.png', 'KIRANA MAHESWARI BALI', 'LUH PUTU ASRI ADNYANI', 27, NULL, 'JL. GN. SERAYA IIA NO.31 TEGAL HARUM DENPASAR BALI', NULL, '20.000.000,00', 'INSTAGRAM, TIKTOK', 'ANTAR KOTA', 'Aplikasi dan manual', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Usaha kami  memproduksi keben legong dan tas tenun dgn kombinasi kain printing , bisa custom sesuai desain yg diinginkan, dengan desain yg unik dan menarik agar beda dipasaran dan memiliki ciri khas tersendiri</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:13:21', '2023-06-06 08:13:21');
INSERT INTO `tenant` VALUES (1436, 234, 'public/foto_profil_tenant/647e8f4974a11.jpg', 'Asih Vegan', 'Ni Made Wahyuni', 23, NULL, 'Jl. Gunung Agung Gg 1C Perum Graha Adi No.10A', NULL, '15.000.000,00', 'Outlet supermarket dan sosmed', 'Bali', 'Ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Asih Vegan bergerak di bidang kuliner,yaitu  makanan khusus vegetarian.\r\nYang beralamat di Jl. Gunung Agung, Denpasar.\r\nProduk terlaris yaitu kerupuk rumput laut yang terbuat dari bahan - bahan pilihan yang berkualitas, tanpa MSG, pengawet dan pewarna buatan.\r\nSudah memiliki ijin dari dinas kesehatan, PIRT dan ijin HALAL MUI.\r\nSudah tersedia di beberapa supermarket di bali</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:43:37', '2023-06-06 08:43:37');
INSERT INTO `tenant` VALUES (1437, 234, 'public/foto_profil_tenant/647e8faf49ef2.png', 'Kedai Warang', 'Ni putu yena dian Pratiwi', 23, NULL, 'Jalan Bingin ambe gang rambutan Kediri tabanan', NULL, '9.000.000,00', 'Instragram, Facebook', 'Lapangan, sekolah', 'Tidak Ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Menjual Makanan seperti : Ropang ,( Roti panggang), Nasi Goreng, Ayam Geprek, Ayam Bakar, Cemilan , Minuman Seperti : Korean Milk Strawberry, Minuman Milky , Cocktail, Mocktail, Kopi , Dan lain lain, Dengan tempat yang nyaman, jauh dari kebisingan , dan harga yang terjangkau.</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:45:19', '2023-06-06 08:55:48');
INSERT INTO `tenant` VALUES (1439, 234, 'public/foto_profil_tenant/647e90e4b7f9c.jpeg', 'Wine Tomato Jaya Pangus – Bali', 'I Komang Restu Widi Artha', 23, NULL, 'Jl. Udayana No.11, Singaraja, Buleleng, Bali (Universitas Pendidikan Ganesha)', NULL, '30.963.750,00', 'Online dan offline', 'Lokal, Nasional', 'Ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Wine Tomato Jaya Pangus-Bali adalah usaha minuman dalam bentuk olahan fermentasi tomat. Meskipun tidak dibuat dari anggur, namun keasaman dari cairan wine tesebut mirip dengan wine pada umunya. Wine tomat merupakan minuman hasil fermentasi yang dibuat dari sari buah tomat. Usaha kuliner minuman Wine Tomato Jaya Pangus-Bali ini berlokasi di Universitas Pendidikan Ganesha, Kecamatan Buleleng, Buleleng – Bali. Adapun profil usaha Wine Tomato Jaya Pangus-Bali sebagai berikut; Nama: Wine Tomato Jaya Pangus-Bali, Alamat: Universitas Pendidikan Ganesha, Singaraja, Buleleng, Bali, Jenis Usaha: Kuliner, Jenis Kuliner: Minuman, NPWP: 40.156.727.6-908.000, Jumlah Tenaga Kerja: 5 orang, Jumlah Produk: 250 botol, Omzet produksi: Rp. 30.963.750, Investasi Usaha: Rp. 6.192.750. Usaha Wine Tomato Jaya Pangus-Bali ini merupakan salah satu komoditas hasil binaan dan inkubasi program PPK Sciencepreneurship FMIPA Universitas Pendidikan Ganesha pada tahun 2022. Nama Wine Tomato Jaya Pangus-Bali terinspirasi dari nama raja Bali pertama yang beristana di Pura Dalem Balingkang, desa Pinggan, Kintamani – Bangli, yakni Raja Jaya Pangus. Desa Pinggan merupakan desa penghasil tanaman hortikultura khususnya buah tomat terbanyak di Bali. Usaha yang berjalan dengan baik tentunya mempunyai manajemen bisnis yakni untuk menunjukkan kapasitas dan kapabilitas keberlangsungan bisnis. Struktur organisasi dari usaha Wine Tomato Jaya Pangus-Bali terdiri atas Dewan Pembina, Pimpinan, Kepala Bagian, yakni Kepala Bagian Pemasaran, Kepala Bagian Produksi, Kepala Bagian Keuangan, Kepala Bagian Quality Control, dan  Karyawan.</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:50:28', '2023-06-06 08:50:28');
INSERT INTO `tenant` VALUES (1440, 234, 'public/foto_profil_tenant/647e914a22046.png', 'Anugrah Coconut Indonesia', 'Angga Nugraha', 43, NULL, 'Jln Waturenggong, Br Sangkanbuana, Klungkung', NULL, '50.000.000,00', 'Sosmed, Website, B2B', 'Lokal, Nasional', 'Ada', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space: pre-wrap;\">Anugrahcoco adalah perusahaan yang memproduksi produk turunan buah kelapa </span><br></p>', '2023-01-01', '2023-12-31', '2023-06-06 08:52:10', '2023-12-14 07:26:40');
INSERT INTO `tenant` VALUES (1441, 234, NULL, 'Kirtania wayang kamasan', 'Komang kirtania hari arati', 15, NULL, 'Br pande kaler, desa kamasan, Klungkung', NULL, '35.000.000,00', 'Ig,wa,shopee, fb', 'Bali, jakarta, lombok, sulawesi', 'Aplikasi & manual', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Kirtania wayang kamasan adalah usaha kerajinan seni lukis wayang kamasan yang membuat produk berlukis wayang kamasan di berbagai media lukis. Dengan memanfaatkan kecanggihan teknologi kirtania wayang kamasan membuat inovasi produk dan inovasi pemasaran sehingga membuat seniman yang sebagian besar adalah ibu- ibu rumah tangga yang tidak bekerja menjadi lebih produktif.</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-07 07:08:46', '2023-06-07 07:08:46');
