INSERT INTO `tenant` VALUES (1446, 234, NULL, 'Griya Anyar Dewata', 'Ni Nyoman Yeni Susanti', 19, 1, 'Jl. Danau Buyan Barat Dalam V Blok D 6 No 8 Jimbaran', NULL, '150.000.000,00', 'Instagram, fb, wa, tiktok, shopee', 'Lokal, Nasional', 'Ada (Manual)', '<div class=\"Qr7Oae\" role=\"listitem\" style=\"color: rgb(32, 33, 36); font-family: Roboto, RobotoDraft, Helvetica, Arial, sans-serif; font-size: medium; background-color: rgb(240, 235, 248);\"><div class=\"OxAavc NVbRL\" jsname=\"ibnC6b\" jscontroller=\"rDGJeb\" jsaction=\"sPvj8e:e4JwSe,Dlbleb;O22p3e:e4JwSe,F0zejc;\" data-required=\"true\" data-item-id=\"1279325646\" style=\"background-color: rgb(255, 255, 255); border: 1px solid rgb(218, 220, 224); border-radius: 8px; margin-bottom: 12px; padding: 24px; break-inside: avoid; transition: background-color 200ms cubic-bezier(0, 0, 0.2, 1) 0s;\"><div class=\"Ih4Dzb\" style=\"margin-top: 12px; margin-bottom: 12px;\"><div class=\"q4tvle JqSWld yqQS1\" style=\"width: 720px; font-family: Roboto, Arial, sans-serif; font-size: 14px; letter-spacing: 0.2px; line-height: 20px; border-bottom: 1px dotted rgba(0, 0, 0, 0.38); min-height: 20px; white-space-collapse: preserve;\">Griya Anyar Dewata adalah umkm yg bergerak dibidang craft/kriya/fashion produknya berupa pencetakan motif alami ( daun, bunga dan pewarna alam ) yang disebut ecoprint,  pengerjaannya  dilakukan pada media kain, kulit, keramik dan kertas.  Griya anyar Tahun 2019  mulai bermitra dengan  masyarakat setempat yang berbakat dan terampil, terutama merekrut para ibu ibu rumah tangga dalam proses pengerjaan ecoprint sehingga bisa menambah perekonomian mereka , sehinga kita mampu menghadirkan produk-produk berkualitas  tinggi yang dibuat dengan pemikiran penuh di Bali.  Bersama Griya Anyar Dewata  mari kita membangun  hari esok  yang lebih baik dan melestarikan  alam, iman , tradisi dan budaya . Dengan menggunakan Produk ini diharapkan mampu mendukung  green  life dengan mengurangi pewarna sintetis penghasil polutan -polutan  berbahaya  bagi bumi kita, namun anda masih bisa tampil modis  dengan menggunakan produk ini sembari melindungi  bumi.</div></div></div></div><div class=\"Qr7Oae\" role=\"listitem\" style=\"color: rgb(32, 33, 36); font-family: Roboto, RobotoDraft, Helvetica, Arial, sans-serif; font-size: medium; background-color: rgb(240, 235, 248);\"><div class=\"OxAavc\" jsname=\"ibnC6b\" jscontroller=\"Fr6DJf\" jsaction=\"JIbuQc:Fh4HNb(mWZCyf);gdexC:dLu6cf;\" data-required=\"true\" data-input=\"L9xHkb\" data-item-id=\"1320086471\" style=\"background-color: rgb(255, 255, 255); border: 1px solid rgb(218, 220, 224); border-radius: 8px; margin-bottom: 12px; padding: 24px; break-inside: avoid; transition: background-color 200ms cubic-bezier(0, 0, 0.2, 1) 0s;\"><div class=\"pYfr3c\" style=\"display: flex; -webkit-box-pack: justify; justify-content: space-between; margin-bottom: 16px;\"><div class=\"prOLdf\" style=\"-webkit-box-align: start; align-items: flex-start; display: flex; flex-direction: column; max-width: 100%; min-width: 0%; position: relative;\"><div class=\"g53bl\" style=\"display: flex; width: 84.2812px;\"><div class=\"cTDvob D1wxyf RjsPE\" id=\"c6955\" role=\"heading\" aria-level=\"3\" aria-describedby=\"i.desc.1320086471 c6959\" style=\"font-family: Roboto, Arial, sans-serif; font-size: 16px; letter-spacing: 0.2px; line-height: 24px; display: flex; width: 84.2812px; word-break: break-word;\"></div></div></div></div></div></div>', '2023-01-01', '2023-12-31', '2023-06-07 08:41:31', '2023-06-07 08:41:31');
INSERT INTO `tenant` VALUES (1447, 234, NULL, 'Neira Pockets Handmade (Kriya)', 'Ditta Rachmawati', NULL, NULL, 'Jl. Jepun perumahan Griya Dhadi Idaman blok B3 Desa Dauh peken banjar tegal belodan, kec. Tabanan, kab. Tabanan Bali 82111', NULL, '3.000.000,00', 'Instagram, facebook, WA', 'Domestik', 'Dengan aplikasi UKM akuntansi', '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Neira Pockets Handmade membuat aneka kriya dengan memilih batik Bali sebagai ciri khas kriya kami. Produk berupa slingbag, totebag, taplak meja, topi, dll.</span><br></p>', '2023-01-01', '2023-12-31', '2023-06-07 09:53:01', '2023-06-07 09:53:01');
