INSERT INTO `tenant` VALUES (1450, 154, 'public/foto_profil_tenant/6492a3d4796a5.jpg', 'Bitna Outfit', 'Maitsa Sifa', 19, 1, 'Jl. Pagarsih Gg Holili rt 05/rw 09. Kel. Jamika Kec. Bojongloa kaler', NULL, NULL, 'Shopee dan Instagram', 'Lokal', NULL, '<p>Bitna Outfit merupakan pakaian wanita dengan style ala korea dari kain pilihan kualitas tinggi, dengan harga jual yang terjangkau mulai dari Rp 49.000 sampai dengan Rp 300.000 sangat cocokdigunakan bagi wanita yang ingin tampil sederhana tetapi tetap stylish. Bitna Outfit lahir karena sebagaian besar penduduk Indonesia sangat menyukai budaya korea mulai dari makanan, musik, film, dan pakaian, maka dari itusaya yakin bahwa Bitna Outfit akan laku dipasaran dan berumur panjang.</p>', '2023-06-20', '2025-06-20', '2023-06-21 14:16:36', '2023-06-21 15:20:13');
INSERT INTO `tenant` VALUES (1451, 154, 'public/foto_profil_tenant/6492a5f42118f.jpg', 'Revolusioner Store', 'Ade Sintia', 39, 1, 'Jl. Pakasih No 19 Bojongloa Kidul, Kota Bandung', NULL, '4.000.000,00', 'Marketplace dan Instagram', 'Lokal', NULL, '<p>Revolusioner Store menyediakan beberapa produk Fashion sesuai dengan hobby dan daya minat pelanggan seperti Kaos Distro Kualitas Premium, Boxer dengan berbagai bahan yang terbaik dan motif yang unik, Sandal dan berbagai macam Fashion lainnya maka dari itu revolusioner ini toko yang tepat untuk mencari fashion dengan kualitas terbaik dan terjangkau.</p>', '2023-06-20', '2025-06-20', '2023-06-21 14:25:40', '2023-11-27 15:50:20');
INSERT INTO `tenant` VALUES (1452, 154, 'public/foto_profil_tenant/6492a6cecf7fa.jpg', 'Sukma Project', 'Maulidia Sukmayanti', NULL, NULL, 'Jl. Karang Sari 01 Rt.01 Rw.03 No.43 Cibeureum, Cimahi Selatan', NULL, '1.500.000,00', 'Instagram', 'Lokal', NULL, '<p>Sukma Project merupakan usaha yang menyedikan beberapa jasa diantaranya:</p><p>1. Make Up</p><p>2. Kelas Tari Jaipong Anak</p><p>3. Sewa Baju Jaipong</p><p>Saat ini untuk kelas tari masih terpusat di Kota Cimahi.</p>', '2023-06-20', '2025-06-20', '2023-06-21 14:29:18', '2023-11-27 15:50:39');
