INSERT INTO `tenant` VALUES (1695, 40, 'public/foto_profil_tenant/64cb4ee2982bd.jpg', 'Biogreenfiil', 'M. Machmud', 30, 2, 'Jl. Karya Sosial Pontianak Kalimantan Barat', NULL, '200.000.000,00', 'Jejaring dan Event Pameran', 'Indonesia', 'Tersedia', '<p>Perusahaan yang bergerak di bidang riset dan produsen pupuk berkteknologi yang ramah lingkungan dan berbahan baku limbah.&nbsp;&nbsp;</p>', '2022-10-20', '2024-10-20', '2023-08-03 13:53:22', '2023-08-03 13:53:22');
INSERT INTO `tenant` VALUES (1696, 40, 'public/foto_profil_tenant/64cb4ffcde91f.png', 'Sampah Market', 'M. Zacky', 30, NULL, 'Jl. Dr. Wahidin Sudirohuodo Pontianak, Kalimantan Barat', NULL, '20.000.000,00', 'Instagram, WA, Website', 'Kalimantan Barat', 'Tersedia', '<p>Start up di bidang lingkungan yang membantu masyarakat dalam mengolah dan mengubah sampah menjadi bernilai ekonomis. SM juga berkolaborasi dengan bank sampah lokal dengan menyediakan layanan secara digital.</p>', '2022-10-20', '2024-10-20', '2023-08-03 13:57:46', '2023-08-03 13:58:04');
INSERT INTO `tenant` VALUES (1697, 40, 'public/foto_profil_tenant/64cb541a863f1.jpg', 'Arcia Oil', 'Hadi Susanto', NULL, NULL, 'Gg. Jiran 1 No.33, Tengah, Kec. Pontianak Kota, Kota Pontianak, Kalimantan Barat 78111', NULL, '300.000.000,00', 'IG, WA, Pameran', 'Indonesia, Asia dan Eropa', 'Tersedia', '<p><span style=\"color: rgb(85, 85, 85); font-family: Rubik, sans-serif; font-size: 16px;\">Arcia Oil adalah UMKM yang bergerak dibidang kosmetika dan kesehatan. Arcia Oil didirikan pada tanggal 1 januari 2019. Arcia Oil merupakan UMKM yang menggunakan bahan-bahan endemik Kalimantan Barat sebagai bahan baku produk yang dihasilkan. Selain itu Arcia Oil juga mengutamakan penggunaan bahan ramah lingkungan untuk menjaga kelestarian lingkungan. Tujuan berdirinya Arcia Oil adalah untuk menampilkan produk lokal yang mampu bersaing dengan produk nasional maupun internasional sehingga meningkatkan taraf hidup masyarakat lokal.</span><br></p>', '2021-10-10', '2021-10-10', '2023-08-03 14:15:38', '2023-08-03 14:15:38');
INSERT INTO `tenant` VALUES (1698, 40, 'public/foto_profil_tenant/64cb5673e22b3.jpg', 'PT AKCAYA AGRO MANDIRI', 'Indra Wijaya Kusuma', 30, 2, 'Jl. Padat Karya Pontianak Kalimantan Barat', NULL, '50.000.000,00', 'IG, WA', 'Indonesia', 'Tersedia', '<p><span style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 16px; text-align: justify;\">PT Akcaya Agro Mandiri merupakan perusahaan yang bergerak di sektor pertanian. PT Akcaya Agro Mandiri berdiri pada tanggal 27 Mei 2022, sekarang PT Akcaya Agro Mandiri merencanakan perancangan aplikasi yang berfokus kepada pembentukan komunitas pertanian. Komunitas tersebut dinamakan “Kebun Komunal“ yang menjual bibit unggul dan jasa pemeliharaan tanaman milik pembeli yang pada prosesnya memanfaatkan teknologi dan metode pertanian unggulan untuk mendapatkan hasil panen terbaik.</span><br></p>', '2021-10-10', '2021-10-10', '2023-08-03 14:25:39', '2023-08-03 14:27:30');
