INSERT INTO `tenant` VALUES (1817, 203, 'public/foto_profil_tenant/64d0b2c246d5d.jpeg', '‘’Kopi Alam Sagara’’', 'Abdul Aziz,', 23, 2, 'Sindangwangi, Kec Bantarkawung, Kab Brebes', NULL, '10.000.000,00', 'Online', 'Seluruh Indonesia', NULL, NULL, '2023-03-30', '2023-04-30', '2023-08-07 16:00:50', '2023-08-07 16:00:50');
INSERT INTO `tenant` VALUES (1818, 185, 'public/foto_profil_tenant/64d203a35a2b8.jpeg', 'Fanida Snack dan Cake', 'Fatmi Sulusi', 23, 2, 'Jln Cilik Riwut Km 3 (jln Intan No 24)', NULL, '3.000.000,00', 'konvensional (keliling dan titip produk) dan wa', 'lokal dan nasional', 'konvensional', '<p>UMKM Fanida bergerak dalam bidang pengolahan makanan&nbsp; dan memiliki beberapa produk seperti serbuk jahe, kue mochi, nugget, rainbow cake.</p><p>kendala yang dihadapi yaitu pada bagian pembukuan keuangan, marketing dan packing labeling</p>', '2023-08-08', '2023-08-08', '2023-08-08 15:58:11', '2023-08-09 14:23:35');
INSERT INTO `tenant` VALUES (1819, 345, 'public/foto_profil_tenant/64d2ef2138a74.jpg', 'PT Boga Tani Makmur', 'Tutut Wulan Andayani', 1, 2, 'Jl Raya Muara Gembong Kp gaga Kel Pantai Mekar Kec Muara Gembong Kab Bekasi', NULL, '150.000.000,00', 'ig, facebook ads', 'Jawa Barat', '-', '<p>PT Boga Tani Makmur adalah Produsen rumput laut gracilaria yang berlokasi di Bekasi, Jawa Barat, Indonesia.&nbsp; Kami memulai bisnis dari tahun 2004 dengan membentuk koperasi yang bernama Muara Gembong Maju bersama yang dipesertai oleh para petani, masyarakat sekitar dan ibu-ibu pekerja di desa. Fokus utama kami adalah untuk mengirimkan bahan baku produk rumput laut gracilaria yang bisa tembus hingga ke&nbsp; pasar Internasional. Kami juga terus meningkatkan kuantitas terbaik untuk pasar domestik dengan menyesuaikan proses kami sesuai dengan kebutuhan pelanggan.&nbsp;&nbsp;<br></p>', '2023-08-23', '2023-12-16', '2023-08-09 08:42:57', '2023-08-09 08:42:57');
INSERT INTO `tenant` VALUES (1820, 345, 'public/foto_profil_tenant/64d2f02ee3cfe.jpeg', 'DapurCK', 'Rian Aulia Dwilazuaris', 23, NULL, 'Jalan Raya Rancah No. 172 RT. 05 RW. 05 Desa Rancah Kecamatan Rancah', NULL, '300.000.000,00', 'Instagram : @dapurck.id Facebook : @dapurck Tiktok : @dapurck Youtube : @dapurck', 'Jawa Barat', '-', '<p>DapurCK merupakan UMKM yang berkembang dan berinovasi menjadi UMKM naik kelas.</p><p>DapurCK berdiri pada tahun 2017 yang merupakan UMKM yang bergerak di bidang kuliner Cake &amp; Bakery.&nbsp;</p>', '2023-08-23', '2023-12-16', '2023-08-09 08:47:26', '2023-08-09 08:47:26');
INSERT INTO `tenant` VALUES (1821, 345, 'public/foto_profil_tenant/64d2f5237013e.jpg', 'Sarjana Martabak', 'Elfan Tawekal', 23, NULL, 'Jln. Angkrek No 52 \r\nMall Asia Plaza Sumedang Lt. Gf', NULL, '400.000.000,00', 'satarbak.id', 'Jawa Barat', '-', '<p>Sarjana Martabak berdiri sejak thn 2018 mulai merintis saat masih berkuliah semester 4 dengan mentarget pasarkan para mahasiswa dan pelajar, sehingga inovasi prodak dan harga menyesuaikan pasar anak muda, yaitu martabak size sedang dengan varian toping kekinian, selain itu terdapat juga Corndog mozarella manis.<br></p>', '2023-08-23', '2023-12-16', '2023-08-09 09:08:35', '2023-08-09 09:08:35');
INSERT INTO `tenant` VALUES (1822, 345, 'public/foto_profil_tenant/64d3124020534.jpeg', 'CV. Citra Prima Jaya', 'Helmiati', 23, NULL, 'Jln. Tytyan Indah Utama II Blok B1 no.10, rt. 001/rw.010, Kalibaru - Bekasi', NULL, '480.000.000,00', 'Market place : Tokopedia, Shopee', 'Jawa Barat', '-', '<p>Usaha dimulai sejak April 2017, dengan nama UMKM Citra Prima. Dimulai dari mambuat rendang daging yang dijual dilingkungan teman dan keluarga. Usaha berkembang dengan penambahan varian rendang menjadi 4 varian dan mendapat legalitas ijin edar P-IRT pada thn yang sama. Tahun 2018 mulai mencari kemasan untuk produk bisa tahan lama beserta mesin penunjang nya. Maret 2019 mulai retail modern Transmart, dan Lotte Grosir di bulan Oktober. Tahun 2020 menambah varian rendang menjadi total 10 varian dan&nbsp;</p><p>terpilih menjadi kontestan Food Startup Indonesia yang diselenggarakan Kemenparekraf dan berhasil menjadi salah satu 25 besar FSI. Tahun 2021 mulai mengaplikasikan&nbsp; Retort System sehingga rendang bisa tahan sampai 1 tahun dan pertama kali berhasil eksport.. Tahun 2022 masuk Indomaret dan Alfamart dan dengan meredanya pandemi di akhir 2022 mulai masuk beberapa retail.modern lainnya seperti Lulu, Hypermart dan GS supermarket. Saat ini sedang proses memperoleh Bpom dan HACCP</p>', '2023-08-23', '2023-12-16', '2023-08-09 11:12:48', '2023-08-09 11:12:48');
INSERT INTO `tenant` VALUES (1823, 345, 'public/foto_profil_tenant/64d313b2e5237.jpeg', 'Dapi Sno', 'Erna Yulia', 23, NULL, 'Kavling Bobojong No A12 Rt 07 Rw 15  Cipageran indah Kel Cipageran  Cimahi Utara', NULL, '350.000,00', 'ig, facebook ads', 'Jawa Barat', '-', '<p>Dapu Sano adalah perusahaan yang memproduksi kopi Bubuk Dapi Sari dan Ciokies kopi,&nbsp;<br></p>', '2023-08-23', '2023-12-16', '2023-08-09 11:18:58', '2023-08-09 11:18:58');
INSERT INTO `tenant` VALUES (1824, 345, 'public/foto_profil_tenant/64d3181b1d3d4.jpeg', 'Indara Mediana Factory', 'Indri Meilandi', 23, NULL, 'Kavling Leuwidulang No C 02 RT 06 RW 02 Kelurahan Rancamulya Kecamatan Pameungpeuk', NULL, '150.000.000,00', 'IG : Nuimefood,   Tiktok: Nuime_food, FB : Indri.Meilandi', 'Jawa Barat', '-', '<p>Kami adalah home industri makanan yang fokus pada olahan pangan legendaris Indonesia menjadi panganan yg bisa bersaing dengan kuliner lainnya.<br></p>', '2023-08-23', '2023-12-16', '2023-08-09 11:37:47', '2023-08-09 11:37:47');
INSERT INTO `tenant` VALUES (1825, 345, 'public/foto_profil_tenant/64d318fb6209f.jpeg', 'Pisang Bolen RICH', 'Dede Iwanah', 23, NULL, 'Komp. Inkopad Blok F10/6 RT 013/05 Desa Sasakpanjang Kecamatan Tajurhalang Kabupaten Bogor 16320', NULL, '180.000.000,00', 'ig, facebook ads', 'Jawa Barat', NULL, '<p>Usaha di bidang makanan olahan pisang yang berkualitas dan dikemas untuk oleh-oleh.<br></p>', '2023-08-23', '2023-12-16', '2023-08-09 11:41:31', '2023-08-09 11:41:31');
INSERT INTO `tenant` VALUES (1826, 345, 'public/foto_profil_tenant/64d319c796523.jpeg', 'Fe.Outfit', 'Fetti Fathia Insani', 19, 1, 'De green grande residences Blok A5', NULL, '500.000.000,00', '(shopee/tiktok)', 'seluruh indonesia', '-', '<p>Jual pakaian muslimah melalui online/ marketplace (shopee/tiktok)&nbsp;<br></p>', '2023-08-23', '2023-12-16', '2023-08-09 11:44:55', '2023-08-09 11:44:55');
INSERT INTO `tenant` VALUES (1827, 345, 'public/foto_profil_tenant/64d31de45497c.jpeg', 'PT. Salaku Cara Enak Makan Salak', 'Dheaneira', 23, NULL, 'Jalan Zamrud Utara IV Blok N1/17 Padurenan Mustikajaya Kota Bekasi', NULL, '350.000.000,00', 'ig, facebook ads', 'seluruh indonesia', '-', '<p>SALAKU®️ brand lokal yg focus dan konsisten mengolah salak sejak tahun 2016. Pelopor olahan serba salak pertama yg berbasis zero waste dengan varian terlengkap.<br></p>', '2023-08-16', '2023-12-16', '2023-08-09 12:02:28', '2023-08-09 12:02:28');
INSERT INTO `tenant` VALUES (1828, 345, 'public/foto_profil_tenant/64d320b5c1e09.png', 'Safputri jaya food/ brand unuy snack', 'Nurbayani', 23, NULL, 'Jl Cihanjuang gang martasim rt04 rw02 cibabat Cimahi Utara', NULL, '300.000.000,00', 'FB, IG unuy Snack, tiktok unuysnack85', 'seluruh indonesia', '-', '<p>Safputri jaya food dengan brand Unuy Snack adalah produsen cemilan ringan yang memproduksi sumpia udang dengan 3 variant yaitu original, pedas dan keju, dengan pemasaran offline dan online oleh agen, reseller, toko oleh2, dropship dan pemasaran luar negri.&nbsp;<br></p>', '2023-08-16', '2023-12-16', '2023-08-09 12:07:42', '2023-08-09 12:14:29');
INSERT INTO `tenant` VALUES (1829, 345, 'public/foto_profil_tenant/64d3221f12121.jpeg', 'Nensi Snack', 'Nenden Sukarsih', 23, NULL, 'Jl. Siti Jenab Gg. Melati No. 21 Rt. 01 Rw. 04 Kel. Pamoyanan Kec. Cianjur Kab. Cianjur 43211 Jawa Barat', NULL, NULL, NULL, 'seluruh indonesia', '-', '<p>BERDIRI TANGGAL 19 JULI 2019</p><p>DENGAN NAMA USAHA : NENSI SNACK&nbsp;</p><p>DENGAN KARYAWN 5 ORANG&nbsp;</p><p>LATAR BELAKANG</p><p>&nbsp;Ceritakan sejarah pendirian dan perjalanan perusahaan Anda dalam 2 paragraf singkat:</p><p>- Didirikan oleh Nenden Sukarsih, berdiri sejak 19 Juli 2019, karena sejak saya single parent</p><p>&nbsp;Ketiadaan itu untuk kehidupan sehari-hari kemudian menggiring bisnis di bidang makanan khas seperti Toraci (manisan tomat yg dikeringkan), abon umbian, abon jengkol, abon sayuran</p><p>&nbsp;Sebagai cemilan dan juga sebagai teman nasi.</p><p>- Dengan berdirinya usaha tersebut, kemudian mengembangkan pemasaran ke berbagai macam</p><p>&nbsp;Kecamatan di Kota Cianjur,</p><p>&nbsp;Seiring berjalannya waktu kemudian ke berbagai kota di Jawa Barat dan Jakarta lalu</p><p>&nbsp;Ke seluruh Indonesia jugs ke Luar NegeriSelain iti mengikuti berbagai Program yang di Fasilitasi oleh Pemerintah Daerah, Provinsi maupun Pusat&nbsp;&nbsp;</p><p>TAHUN 2021 PAMERAN DI ACARA INTERNATIONAL CAIRO EXPO DI CAIRO, MESIR</p><p>TAHUN 2022 : LOLOS KURASI PELATIHAN CPNE (COACHING FOR NEW EXPORTER) FASILITASI DINAS</p><p>PERDAGANGAN DAN PERINDUSTERIAN JAWA BARAT DENGAN BANK EXIM</p><p>TAHUN 2022 : SOSIALISASI PEMBIAYAAN KURASI KELAYAKAN PEMBIAYAAN UKM EKSPOR PROVINSI</p><p>JAWA BARAT FASILITASI : KEMENKOP DAN UKM, INDAG JABAR</p><p>TAHUN 2022 : CPNE COCHING PROGRAM NEW EKSPOR DI FASILITASI OLEH INDAG JAWA BARAT</p><p>TAHUN 2023</p><p>TERPILIH 40 IKM WORKSHOP DAN VERIFIKASI PERUSAHAAN EKSPOR COACHING PROGRAM REGIONAL&nbsp; JAWA BARAT DI FASILITASI OLEH PPEJP, KEMENDAG DAN INDAG JAWA BARAT</p>', '2023-08-23', '2023-12-16', '2023-08-09 12:20:31', '2023-08-09 12:20:31');
INSERT INTO `tenant` VALUES (1830, 185, 'public/foto_profil_tenant/64d341a531890.jpeg', 'dapoer Wie', 'Rahmadewi Utari', 23, 2, 'Jln Cristopel Mihing VIII No 20 RT 001 dan RW 010', NULL, '15.000.000,00', 'konvensional dan online', 'lokal', 'konvensional', '<p>UMKM ini bergerak di bidang makanan dan minumam, ada 4 jenis produk yang di miliki yaitu salad buah, pudig, akar pinang dan peyek.</p><p>kendala yang dihadapi seperti pada bagian pembukuan usaha.</p>', '2023-08-09', '2023-08-09', '2023-08-09 14:35:01', '2023-08-09 14:35:01');
INSERT INTO `tenant` VALUES (1831, 185, 'public/foto_profil_tenant/64d3445c64ca0.jpeg', 'Makmuro Kripik', 'Suwati', 23, 2, 'Jln Cilik Riwut Km 1 (jalan Tambora no 28)', NULL, '9.000.000,00', 'konvensional dan gerobakan', 'lokal', 'belum ada', '<p>UMKM ini bergerak di penjualan kripik. ada 3 produk yang dimiliki yaitu kripik pisang, kripik singkong dan kripik tempe</p><p>kendala yang dihaapi saat ini yaitu di labelling produk, belum memiliki PIRT, marketing masih konvensional, Pembukuan yang belum dilaksanakan terkait dengan pembiayaan</p>', '2023-08-09', '2023-08-09', '2023-08-09 14:46:36', '2023-08-09 14:46:36');
INSERT INTO `tenant` VALUES (1832, 345, 'public/foto_profil_tenant/64d34cdd66318.jpg', 'CV. Dzikra Indonesia', 'Risa Kristalia Nurlaela ST.,MT', 23, NULL, 'Perumahan Pepabri Batulawang no 183 Blok. E RT. 05/09 desa talagasari kec. Kadungora kab. Garut', NULL, '100.000.000,00', 'Instagram @cokusi_id', 'Jawa Barat', '-', '<p>CV. Dzikra Indonesia bergerak di bidang pengolahan makanan, salah satu produk nya adalah Cokusi kameumeut. Cokusi kameumeut ini adalah makanan olahan yang terbuat dr buah kurma diisi dodol dibalut coklat dan ditaburi keju panggang sehingga rasa nya unik dan menarik<br></p>', '2023-08-16', '2023-09-23', '2023-08-09 15:22:53', '2023-08-09 15:22:53');
INSERT INTO `tenant` VALUES (1833, 1, 'public/foto_profil_tenant/64d4640bc407e.jpg', 'CV ALLISHA  FOODS - SATE AMBAL KEMASAN', 'Titin Agustinah', 23, 2, 'RT 01 RW 03 No. 22 Tambakrejo Buluspesantren - Kebumen', NULL, NULL, 'Online dan Offline', 'Nasional', NULL, '<ul role=\"region\" aria-label=\"carousel\" style=\"list-style-position: outside; color: rgb(16, 21, 24); font-family: Roboto, &quot;helvetica neue&quot;, helvetica, arial, sans-serif; font-size: 16px;\"><li class=\"va-top ov-h\" role=\"group\" aria-label=\"Item 1 of 1\" style=\"margin-bottom: 4px; vertical-align: top; overflow: hidden; zoom: 1;\">CV Allisha Foods adalah perusahaan yang memproduksi, mendistribusikan, dan menjual sate ayam dan beberapa makanan tradisional Indonesia dengan teknologi pengemasan retort.&nbsp;Allisha Sate Ambal&nbsp;merupakan sate kemasan pertama di Indonesia dengan bumbu khas dari daerah Ambal Kebumen yang dapat bertahan hingga 18 bulan pada suhu kamar.</li></ul>', NULL, NULL, '2023-08-10 11:09:03', '2023-08-10 11:15:30');
INSERT INTO `tenant` VALUES (1834, 345, 'public/foto_profil_tenant/64d4681e4f279.jpeg', 'INNOVATIVE COFFEE ROASTERY', 'SARIMUN', 23, NULL, 'TAMAN SAGATI MARGACINTA. DESA CIJULANG KECAMATAN CIJULANG KABUPATEN PANGANDARAN', NULL, '350.000.000,00', 'IG : INNOVATIVECOFFEEROASTERY TIKTOK : INNOVATIVE COFFEE ROASTERY', 'Jawa Barat', '-', '<p>Bergerak di bidang pengolahan kopi dimana proses pengolahan dari hulu sampai hilir.</p><p>mulai dari proses pertanian sampai dengan pengolahan biji kopi sangrai, seduhan,d an juga pengemasan yg dijual ke customer baik perorangan atau perusahaan</p>', '2023-08-23', '2023-12-16', '2023-08-10 11:31:26', '2023-08-10 11:31:26');
INSERT INTO `tenant` VALUES (1835, 345, 'public/foto_profil_tenant/64d46b730c724.jpeg', 'GRANOKU', 'FANDY', 23, NULL, 'Jl. Ciumbuleuit No.80A/155A, Kota Bandung', NULL, '180.000.000,00', 'instagram.com/granoku.id', 'seluruh indonesia', '-', '<p>Sejarah GRANOKU dimulai dari cinta seorang ibu kepada anaknya dengan menyajikan sarapan pagi yang sehat.<br></p>', '2023-08-23', '2023-08-23', '2023-08-10 11:45:39', '2023-08-10 11:45:39');
INSERT INTO `tenant` VALUES (1836, 345, 'public/foto_profil_tenant/64d46daa6f5e8.jpeg', 'mBrebes Mili Food', 'Mohammad D Marhendra', 23, NULL, 'Komplek Departemen Koperasi Blok A19 RT 02/015 Jl. Radar Auri Mekarsari Cimanggis Depok', NULL, '1.000.000.000,00', 'ig, facebook ads', 'seluruh indonesia', '-', '<p>Produsen Bawang goreng tanpa tepung yang menggunakan hanya Bawang merah Brebes dengan minyak sekali pakai<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 11:55:06', '2023-08-10 11:55:06');
INSERT INTO `tenant` VALUES (1837, 357, 'public/foto_profil_tenant/64d477389940c.jpeg', 'Afifah Mart', 'Abdul Gaffar latjokke', 40, 2, 'Jln. Achamad Najamuddin. No. 17 Kota Gorontalo', NULL, '20.000.000,00', '-', 'mahasiswa di sekitar kampus ichsan', 'Buku Kas (Cash Book) dan Jurnal Umum (General Journal)', '<p>Afifah Mart&nbsp; memiliki toko ukuran yang lebih kecil dibandingkan supermarket tradisional, menawarkan produk sehari-hari yang dibutuhkan oleh mahasiswa&nbsp; seperti makanan ringan, minuman, bahan makanan, dan barang-barang kecil lainnya. Jam operasional yang lebih fleksibel, bahkan&nbsp; buka 24 jam dalam sehari. Ini memberi pelanggan akses yang mudah kapan pun mereka membutuhkan. Karena ukurannya yang kecil, toko ini cenderung memiliki stok terbatas dibandingkan supermarket besar. Namun, mereka berfokus pada produk-produk yang paling sering dibeli oleh mahasiswa yang ada di ichsan . Layanan Cepat dan Sederhana: Pelayanan di toko kecil seperti mart cenderung sederhana dan cepat. Pelanggan membawa produk ke kasir, membayar, dan pergi dengan cepat.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', '2021-06-10', '2021-06-10', '2023-08-10 12:35:52', '2023-08-11 12:59:59');
INSERT INTO `tenant` VALUES (1838, 1, 'public/foto_profil_tenant/64d485c7207ae.jpg', 'CV SUMI INOTECH - MAGIC RING PENGHEMAT BBM', 'Sumiyanto', 30, 5, 'Jl. Bima 038 Jetis RT 05/06, Gagaksipat, Kec. Ngemplak, Kabupaten Boyolali,', NULL, NULL, NULL, NULL, NULL, '<p style=\"text-align: justify; \">CV. Sumi Inotech adalah menjadi perusahaan spare part kendaraan bermotor yang inovatif dan berdaya saing. Sedangkan misi perusahaan adalah memberi kepuasan, menjaga komitmen dan kepercayaan konsumen dengan pelayanan yang prima, membuat inovasi spare part tanpa henti untuk kepuasan pelanggan, dan memberikan hasil yang terbaik untuk konsumen secara optimal dan setulus hati.<br></p>', NULL, NULL, '2023-08-10 13:37:59', '2023-08-10 13:37:59');
INSERT INTO `tenant` VALUES (1839, 345, 'public/foto_profil_tenant/64d486fc33b2a.jpeg', 'PT Batik Gending Amarta', 'Poppy Sri Hendriani', 19, 1, 'Komplek Permata Cimahi 2 blok N 19 no RT 5 RW 24 desa Tanimulya Kecamatan Ngamprah Kabupaten Bandung Barat', NULL, '300.000.000,00', 'IG: gendingamarta_batik', 'seluruh indonesia', '-', '<p>Batik Tulis yang mengangkat tema Cerita Legenda Indonesia dan Destinasi Wisata Indonesia juga produk turunan batik: Tumbler motif batik, blek krupuk motif batik dll<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 13:43:08', '2023-08-10 13:43:08');
INSERT INTO `tenant` VALUES (1840, 1, 'public/foto_profil_tenant/64d487263473e.jpeg', 'CV. Seleksi Alam Muria', 'Tri Yanto', NULL, NULL, 'Muria Kabupaten Kudus', NULL, NULL, NULL, NULL, NULL, '<div style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><div class=\"scrool-down\" style=\"padding-right: 25px; border: 0px; outline: 0px; height: 100px; overflow-y: scroll; text-align: justify;\">Alammu berasal dari kata alam muria, dimana buah parijotho ini adalah buah endemik Gunung Muria yang terletak di Kab. Kudus. perusahaan mempunyai brand yaitu Alammu food and beverages yaitu olahan makanan yang semua bahan baku dari Buah Parijotho.</div></div><center style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><br></center>', NULL, NULL, '2023-08-10 13:43:50', '2023-08-10 13:43:50');
INSERT INTO `tenant` VALUES (1841, 1, 'public/foto_profil_tenant/64d487cadb344.jpg', 'CV. GANESHA ECO ENERGI - BRIKET KOKAWA', 'M. Adam Gana', NULL, NULL, 'Jln. Gajah Mada 218 Purworejo', NULL, NULL, NULL, NULL, NULL, '<div style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><div class=\"scrool-down\" style=\"padding-right: 25px; border: 0px; outline: 0px; height: 100px; overflow-y: scroll; text-align: justify;\">CV Ganesha Ecoenergy merupakan perusahaan yang bergerak dibidang Jasa dan Pengembangan Produk Briket Shisha \"KOKAWA\". Briket KOKAWA menghasilkan asap dan residu yang sangat sedikit sehingga ramah lingkungan, berbeda dengan briket lainnya. Selain itu, teknik pengolahan yang dilakukan menghasilkan Briket Kokawa dengan nilai kalor tinggi dan memenuhi SNI yaitu 5.866 kal/gram.</div></div><center style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><br></center>', NULL, NULL, '2023-08-10 13:46:34', '2023-08-10 13:46:34');
INSERT INTO `tenant` VALUES (1842, 345, 'public/foto_profil_tenant/64d48836dd821.jpeg', 'Keysha Kitchen', 'Erwin Pramadya', 23, NULL, 'Harva Residence, Blok Harmonia 1, Jalan Bima, RT 70, RW 19, Sukamekar, Kelurahan Cigadung, Kecamatan Subang, Kabupaten Subang, Jawa Barat 41213', NULL, '400.000.000,00', 'Instagram, Tiktok', NULL, NULL, '<p>Keysha kitchen berdiri pada tanggal 17 Februari 2012 dan dikenal oleh para customernya sebagai ukm yang selalu menyajikan kue2 lezat&nbsp; dan berkelas mulai dari cookies, aneka cake, kue nampan dan strudel nanas dan minuman olahan buah2an. Membawa pesan sebagai olahan lokal daerah bercita rasa tinggi, strudel nanas di bulan kedua launching sudah booming dan terkirim ke hampir seluruh kota2 di Indonesia dan di branding oleh Bapak Menteri Sandiaga Uno menjadi PANAS BANG yaitu Pastry nanas Subang. Keistimewaannya terletak pada ke khas an nanas Subang yang dipadukan dengan rempah pilihan dan pastry berlapis menjadikan oleh2 premium kota Subang.&nbsp;</p><p>Ditambah lagi dengan De Pineapple fresh drink, yang bukan minuman biasa. Hasil kolaborasi Keysha Kitchen dan Brin Subang, menghasilkan produk minuman dengan kandungan peptin dan vitamin C, yang menjadikan minuman berbahan dasar nanas Subang yang manis dan segar ini mengandung collagen booster.&nbsp;</p>', '2023-08-23', '2023-12-16', '2023-08-10 13:48:22', '2023-08-10 13:48:22');
INSERT INTO `tenant` VALUES (1843, 345, 'public/foto_profil_tenant/64d489964e048.jpeg', 'Jelujur', 'Dinni Nurhayati', NULL, NULL, 'Jl. Sekar Gambir I no. 17 Kel. Turangga Kec. Lengkong Kota Bandung', NULL, '135.000.000,00', 'IG/Tiktok : Jelujur_id ; FP. Jelujur by Deandrahandmade', 'seluruh indonesia', NULL, '<p>Jelujur merupakan brand modest fashion yang mengangkat kerajinan tradisional bordir manual dan dipadukan dengan wastra nusantara yaitu batik. Berupaya untuk memberdayakan wanita penjahit rumahan dan pengrajin bordir yang ada di sekitar lokasi usaha. Jelujur juga berkomitimen untuk menggunakan bahan baku dengan kualitas terbaik dan ramah lingkungan, yaitu cotton, linen, dobby, rayon dan lain-lain.<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 13:54:14', '2023-08-10 13:54:14');
INSERT INTO `tenant` VALUES (1844, 345, 'public/foto_profil_tenant/64d48a95ebf17.jpeg', 'Difia', 'Anisa Fitriani', 19, 1, 'Jl Panaragan Kidul No 25 Kota Bogor Tengah', NULL, '300.000.000,00', 'Instagram : Difia.id , Difia Souvenir Market Place ShopeeMall : Difia Official Shop', 'seluruh indonesia', '-', '<p>Difia sebuah brand lokal yang berdiri sejak 20 Agustus 2020, Perusahaan ini berbasis perorangan tergolong UMKM Home Industry di Bidang Fashion telah terdaftar di HAKI dan partnership dengan Business Indonesia Singapore Association (BISA)&nbsp;<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 13:58:29', '2023-08-10 13:58:29');
INSERT INTO `tenant` VALUES (1845, 345, 'public/foto_profil_tenant/64d48bce393e2.jpeg', 'Koppontren Baiturrahman (Kopbar)', 'Yudi Suryadi, S.Si., M.Pd', 23, NULL, 'Jl Merdeka Tegallaya No.67 RT 01/04 Kel. Cipanengah Kec. Lembursitu Kota Sukabumi', NULL, NULL, 'Youtube, FB, IG, WA ; @calala.sukabumi', 'seluruh indonesia', '-', '<p>Kami menjalankan usaha dari produksi Roti, Donat, dan Kue/cake.</p><p>Untuk display kami pajang di Koppontren Baiturrahman (Koperasi yg kami kelola).</p><p>Selain display di koperasi, kami bekerjasama dg kantin² sehat sekolah dan online shop (shopee food), WA Bisnis, IG, FB untuk menjangkau pasar yg lebih luas.</p><p>Koppontren Baiturrahman (kopbar) yang kami kelola selain menjual barang² yang kami produksi juga menjual produk² buatan masyarakat sekitar dan barang² lain karena memang koperasi kami adalah koperasi konsumen.</p>', '2023-08-23', '2023-12-16', '2023-08-10 14:03:42', '2023-08-10 14:03:42');
INSERT INTO `tenant` VALUES (1846, 345, 'public/foto_profil_tenant/64d48cccb4c4c.jpeg', 'Sirmione Footwear', 'Adi Candra Wiratmadja', 20, 1, 'Jl. Lokanatya no. 3, Tatar Lokacitra, Kota Baru Parahyangan', NULL, '120.000.000,00', '@sirmione.pro & @sirmione.id', 'seluruh indonesia', '-', '<p>Sirmione Footwear merupakan brand alas kaki asal Kab. Bandung Barat yang diproduksi oleh pengrajin lokal yang sudah berpengalaman selama puluhan tahun dengan menggunakan standar bahan yang tinggi dan telah melalui proses kurasi.<br></p>', NULL, NULL, '2023-08-10 14:07:56', '2023-08-10 14:07:56');
INSERT INTO `tenant` VALUES (1847, 345, 'public/foto_profil_tenant/64d48dbacc828.jpeg', 'NAMINA DIGITAL FASHION HOUSE', 'SANTI HERA BILLIAN', 19, 1, 'PERUMAHAN TAMAN BILQIS REGENCY JL. SURAKARTA BLOK BB5 CIANJUR', NULL, '350.000.000,00', 'http://www.instagram.com/nmn.apparel', 'seluruh indonesia', '-', '<p>Berdiri sejak Maret 2020 di kabupaten Cianjur Provinsi Jawa Barat dengan bidang usaha utama membuat berbagai jenis pakaian printing atau non printing kategori dewasa atau anak baik perempuan atau laki-laki meliputi : T-Shirt, Kemeja, Tunik, Gamis, Cardigan, Jersey, Jaket, Sweater, Scraft, kerudung, Masker dll. Dan bidang usaha tambahan menjual pakaian anak. Keunggulan produk kami yaitu Unique Design And Costum Order. Proses produksi menggunakan sistem makloon atau cut make trim (CMT) dengan tujuan mendayagunakan para pengrajin dilingkungan sekitar. Dengan pertimbangan aspek kelebihan dan kekurangan yang dimiliki, kami membuka kesempatan bagi para investor dan buyer untuk mendukung pengembangan usaha kami ini.<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 14:11:54', '2023-08-10 14:11:54');
INSERT INTO `tenant` VALUES (1848, 345, 'public/foto_profil_tenant/64d48e9b5dcc0.jpeg', 'PT Imah Teuweul Indonesia', 'Amaar Afifi Thohir', 3, 2, 'Dusun Wage RT/RW 15/04 Desa Bojong, Kec. Kramatmulya Kuningan', NULL, '250.000.000,00', 'IG @madukuningan.official', 'seluruh indonesia', '-', '<p>Usaha berbasis pemberdayaan, kemitraan dan pelestarian lingkungan. Produk madu murni dan olahan makanan, minuman, perawatan kulit, hingga kriya berbahan dasar madu dan turunan lebah lainnya, dengan lebih dari 20 inovasi produk<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 14:15:39', '2023-08-10 14:15:39');
INSERT INTO `tenant` VALUES (1849, 1, 'public/foto_profil_tenant/64d48f0ada355.jpeg', 'CV. GARAM MULIA', 'Sujarwi', NULL, NULL, 'Desa Bumiayu Rt 2/Rw 5 Kec. Wedarijaksa Kabupaten Pati', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(126, 128, 130); font-family: Lato, sans-serif; text-align: justify;\">CV. Garam Mulia merupakan perusahaan yang bergerak dibidang Jasa dan Pengembangan Produk Mesin Perata dan panen Garam Rakyat (MOBGAR). Mobile Garam (MOBGAR) merupakan mesin yang bergerak dalam bidang pertambakan garam digunakan untuk meratakan meja garam dan proses pemanenan garam, mesin ini dapat digunakan siang ataupun malam hari dengan terciptanya mesin ini diharapkan dapat membantu petani garam konvensional beralih ke modernisasi.</span><br></p>', NULL, NULL, '2023-08-10 14:17:30', '2023-08-10 14:17:30');
INSERT INTO `tenant` VALUES (1850, 1, 'public/foto_profil_tenant/64d48f43dcb39.jpg', 'CV. KUBAJATANI', 'Heri Siswanto', NULL, NULL, 'Kebonsari RT002 / RW001, Kec. Dempet, Kab. Demak', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(126, 128, 130); font-family: Lato, sans-serif; text-align: justify;\">CV. Kubajatani merupakan Perusahaan manufaktur yg bergerak dalam perancangan dan produksi alat dan mesin pertanian serta teknologi tepat guna.</span><br></p>', NULL, NULL, '2023-08-10 14:18:27', '2023-08-10 14:18:27');
INSERT INTO `tenant` VALUES (1851, 1, NULL, 'CV. SANGKO USAHA BARU', 'Mardiyono', 17, 2, 'Dsn. Grubug RT/RW: 002/004, Desa Wonotirto, Kecamatan Bulu, Kabupaten Temanggung', NULL, NULL, NULL, NULL, NULL, '<div style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><div class=\"scrool-down\" style=\"padding-right: 25px; border: 0px; outline: 0px; height: 100px; overflow-y: scroll; text-align: justify;\">CV. Sangko Usaha Baru Merupakan usaha yang bergerak di bidang manufacturing peralatan pangan. Salah satunya ya itu Mesin penyangrai kopi.<br></div></div>', NULL, NULL, '2023-08-10 14:20:31', '2023-08-10 14:20:31');
INSERT INTO `tenant` VALUES (1852, 345, 'public/foto_profil_tenant/64d48fc36891f.jpeg', 'Pt.Trikarya Budaya Indonesia', 'Septian Cahya Dijaya', 19, 1, 'Ruko Lumbung padi merah No.11, Citeureup, Kec. Cimahi Utara, Kota Cimahi, Jawa Barat 40512', NULL, '3.000.000.000,00', 'https://instagram.com/zeea.official', 'seluruh indonesia', '-', '<p>Penjualan retail di marketplace lokal dengan produk outfit olah raga muslimah<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 14:20:35', '2023-08-10 14:20:35');
INSERT INTO `tenant` VALUES (1853, 1, 'public/foto_profil_tenant/64d4903dae0de.png', 'CV. YUAM ROASTED COFFE', 'Yuri Dulloh', NULL, NULL, 'Jalan kambalan, Jl. Krajan kecamatan, RT.2/RW.2, Krajan, Pucangan, Kec. Ambal, Kabupaten Kebumen', NULL, NULL, NULL, NULL, NULL, '<p style=\"text-align: justify; \">CV. Yuam Roasted Coffe merupakan perusahaan bergerak dibidang pengembangan kopi dari mulai hulu sampai hilir, selain itu juga melakukan pendampingan pengembangan kopi di pesisir pantai selatan khususnya di Kabupaten Kebumen<br></p>', NULL, NULL, '2023-08-10 14:22:37', '2023-08-10 14:22:37');
INSERT INTO `tenant` VALUES (1854, 345, 'public/foto_profil_tenant/64d4907c5394e.jpeg', 'Batik Kakak', 'Fitri Apriyanti', 19, 1, 'Jl Perum Mangkalaya', NULL, '200.000.000,00', 'ig, facebook ads', 'seluruh indonesia', '-', '<p>Batik Kakak telah menjalankan usaha sejak Maret 2018 yang difokuskan untuk mendapatkan profit serta turut menjaga dan melestarikan Batik, dengan produk utama Batik dan produk turunan lainnya dari Batik seperti Pakaian Batik, Gift/hampers/souvenir Batik, Batik Custom/Berlogo, Batik wastra Daerah (Sukabumian).<br></p>', '2023-08-23', '2023-12-16', '2023-08-10 14:23:40', '2023-08-10 14:23:40');
INSERT INTO `tenant` VALUES (1855, 1, 'public/foto_profil_tenant/64d490c4496fa.png', 'CV. HARYO INDUSTRI', 'Banar Haryo', NULL, NULL, 'Jln Rejotaruno No 13, RT 01 RW 04, Desa Tamanrejo,Kecamatan, Kabupaten Kendal', NULL, NULL, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Sirup Daker adalah hasil produksi dari usaha yang bergerak di bidang herbal. Sirup Daker memiliki manfaat untuk mengendalikan kadar gula darah, kolestrol dan asam urat. Dimana bahan baku yang kami pakai alami tanpa efek samping dan harga terjangkau. Salah satu fokus usaha ini menjadi kan sirup daker bermanfaat bagi masyarakat dan minuman sehat. Besarnya peluang bisnis dikarenakan jumlah kompetitor yang masih tergolong sedikit sehingga penjualan sirup Daker mulai meningkat setiap bulan.<br></p>', NULL, NULL, '2023-08-10 14:24:52', '2023-08-10 14:24:52');
INSERT INTO `tenant` VALUES (1856, 1, NULL, 'CV. CIPTA UTAMA KARYA MANDIRI', 'Patra Agung W', NULL, NULL, 'Jl. Brigjen Katamso No 28 Magelang', NULL, NULL, NULL, NULL, NULL, '<div style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><div class=\"scrool-down\" style=\"padding-right: 25px; border: 0px; outline: 0px; height: 100px; overflow-y: scroll; text-align: justify;\">CV. Cipta Karya Mandiri merupakan perusahaan yang bergerak dibidang Jasa dan Pengembangan Produk Magicgrill - Alat panggang otomatis dengan rangkaian mekanik dan elektronik yang disatukan dalam sebuah booth.</div></div><center style=\"border: 0px; outline: 0px; color: rgb(126, 128, 130); font-family: Lato, sans-serif;\"><div class=\"button small hover-thin blue mt-20\" style=\"margin-top: 20px; padding: 8px 13px; border: 2px solid transparent; outline: none; font-size: 11px; background: linear-gradient(rgb(255, 255, 255), rgb(255, 255, 255)) padding-box padding-box, linear-gradient(60deg, rgb(0, 143, 215) 0%, rgb(244, 169, 87) 74%) border-box border-box; color: rgb(45, 45, 45); border-radius: 15px; transition: all 0.3s ease 0s; position: relative; line-height: 16px; display: inline-block;\"><a href=\"https://api.whatsapp.com/send?phone=628122981818\" target=\"_blank\" class=\"btn-whatsapp\" style=\"background: rgb(37, 211, 102); color: rgb(255, 255, 255); margin-right: 0.5rem; padding: 7px 8px; border: none; transition: all 0.3s ease 0s; width: 3.125rem; height: 3.125rem; overflow: hidden; display: inline-block; position: relative; font-size: 18px; border-radius: 50%; outline: none !important;\"><span class=\"fa fa-phone\" style=\"margin-right: 5px; margin-left: -1px; border: 0px; outline: 0px;\"></span></a></div></center>', NULL, NULL, '2023-08-10 14:35:55', '2023-08-10 14:35:55');
INSERT INTO `tenant` VALUES (1857, 185, 'public/foto_profil_tenant/64d9eb8080b4a.jpeg', 'Relyntea', 'Nurawati', 23, 2, 'Jln Matal Permai 7A No 26', NULL, '1.500.000,00', 'konvensional dan online', 'Lokal, Nasional', 'konvensional', '<p>Relyntea bergeak di bidang makanan dan herbal. makanan yang di buata ada 3 jenis yaitu stik bawang, stik ubi ungu dan kacang asin goreng.</p><p>herba&nbsp; yang dijual berupa Teh celup bajakah, herba akar kuning, herba bawang dayak, herba bawang tunggal fermentasi dan herba pasak bumi. jumlah produk yang dimiliki yaitu 8 jenis produk, sudah memiliki PIRT dan NIB.</p><p>kesulitan yang dihadapi yaitu terkait dengan modal, tempat usaha mandiri (karena saat ini masih join), packing, pemasaran, pembukuan.</p><p>omset menurun untuk produk herbal seiring endemi covid 19. awalnya bida memperoleh omset 9.000.000 perbulan, sekarang hanya dapat 1.500.000 saja</p>', '2023-08-14', '2023-08-14', '2023-08-14 15:53:20', '2023-08-14 15:53:20');
INSERT INTO `tenant` VALUES (1858, 290, 'public/foto_profil_tenant/64db20c0e3be4.jpg', 'SANSGEN SOLUTION', 'A. Zulkarnain', 44, 5, 'Jalan Serigala Lr 10 No 3', NULL, '150.000.000,00', 'Instagram', 'Nasional', '-', '<p>Sansgen adalah sebuah platform pengembangan diri, untuk meningkatkan kualitas hidup&nbsp; dengan pengetahuan dan skill. Berfokus untuk menyelesaikan masalah rendahnya minat baca di Indonesia yang menyebabkan kurangnya pengetahuan dan skill yang dimiliki oleh masyarakat.</p>', '2022-10-15', '2023-09-30', '2023-08-15 13:39:44', '2023-08-15 13:52:48');
INSERT INTO `tenant` VALUES (1859, 185, 'public/foto_profil_tenant/64db2b8405ad7.jpeg', 'Pizza Nyambi Momong', 'Dwi Wulandari', 23, 2, 'Jalan G.Obos 1 Kota Palangka Raya Kalimantan Tengah', NULL, '6.000.000,00', 'online dan offline', 'lokal', 'sudah memakai aplikasi', '<p>UMKM yang dilakukan terkait dengan Pizza Nyambi Momong yang berlokasi di Jln G. Obos 1 Kota Palangka Raya. memiliki produk berupa pizza dengna berbagai topping&nbsp; diantaranya sweet cheese, buah lumer, coklat keju, sosis bolognese, ayam black paper, smoke beef, tiramisu, dan ayam terayaki.&nbsp;</p><p>permasalahan yang dihadapi saat ini yaitu terkait di modal.</p>', '2023-08-15', '2023-08-15', '2023-08-15 14:38:44', '2023-08-15 14:38:44');
INSERT INTO `tenant` VALUES (1860, 185, 'public/foto_profil_tenant/64db2df8495c0.jpeg', 'Dapur Ratna Endah', 'Ratna Rosaria Indah', 23, 2, 'Jln Bangas Permai II No 24 RT 001 RW 10 Kota Palangka Raya', NULL, '3.000.000,00', 'online dan offline', 'lokal dan nasional', 'konvensional', '<p>UMKM Dapur Ratna Endah yang berlokasi di jalan bangas Permai II sudah menghasilkan beberapa produk olahan makanan diantaranya seperti&nbsp;</p><p>uyah acan pencokan, seluang goreng krispy, kripik ikan bilis,&nbsp; kripik ikan lain dan beberapa produk lain seperti usaha catering, kue kering dan kue basah</p><p>permasalahan yang dihadapi saat ini yaitu modal yang terbatas, pembukuan yang masih manual, packing yang masih sederhana.</p>', '2023-08-15', '2023-08-15', '2023-08-15 14:49:12', '2023-08-15 14:49:12');
INSERT INTO `tenant` VALUES (1861, 185, 'public/foto_profil_tenant/64dc5c6c103b3.jpeg', 'Pidjar Ecoprint', 'Siti Juhairiyah', 26, 1, 'Jln Sapan 5  Kota Palangka Raya', NULL, '4.000.000,00', 'online dan offline', 'lokal dan nasional', 'konvensional', '<p>UMKM Pidjar Ecoprint yang beralamat di jalan Sapan 5. produk yang dihasilkan ada 3 produk diantaranya</p><p>produck Ecoprint (pakaian, celana, kriya dll)</p><p>lilin aromaterapi</p><p>Sabun padat cuci tangan</p><p>kendala yang dihadapi terutama di modal, material mentah produk, pembukuan dan marketing</p><p>umkm ini sudah berjalan selama 1 tahun</p>', '2023-08-16', '2023-08-16', '2023-08-16 12:19:40', '2023-08-16 12:19:40');
INSERT INTO `tenant` VALUES (1862, 185, 'public/foto_profil_tenant/64dc6245ed923.jpeg', 'Sanggar Kriya Lina', 'Herlina iswahyudi', 26, 1, 'Jln Samudin Aman 4B, No 12 Palangka Raya', NULL, '10.000.000,00', 'online dan offline', 'lokal dan nasional', 'belum ada', '<p>UMKM Sanggar Kriya Lina yang ada di Kota palangka Raya memiliki produk diantaranya</p><p>Ecoprint( Jilbab, Kain, Outher, Sandal, Tas, Topi, Dompet, Asesoris, Sarung Bantal, Seprei dan Cover Kursi)</p><p>Kerjinan Bunga</p><p>Ikat Rambut</p><p>Bando</p><p>kendala yang dihadapi seperti management UMKM yang belum berjalan dengan baik, packing yang belum sempurna.</p><p>usaha sudah berjalan kurang lebih 6 tahun.&nbsp;</p>', '2023-08-16', '2023-08-16', '2023-08-16 12:44:37', '2023-08-16 12:44:37');
