INSERT INTO `tenant` VALUES (1882, 255, NULL, 'Mama Cookies', 'Anjani Risma Damarjati', 23, 2, 'Perum Hinalang Asri, Jl. Umbul Rondo No.12 RT 01 RW 37, Wedomartani, Ngemplak, Sleman, Yogyakarta', NULL, '2.400.000,00', 'Facbook, Instagram, dan Youtube, Lebih dari satu Marketplace', 'Nasional', 'Arus Kas Sederhana', '<p>Mama Cookies sangat mengutamakan rasa dan kualitas bahan yang premium. Ada ciri khas tersendiri di produk kue Mama Cookies yang akan membuat para pelanggan selalu kangen akan semua produk Mama Cookies. Moto kami : Serve the Best Taste with Low Price, yang berarti meskipun Mama Cookies memiliki cita rasa premium namun soal harga masih sangat terjangkau.<br></p>', '2021-06-07', '2021-10-16', '2023-08-25 11:35:59', '2023-08-25 11:35:59');
INSERT INTO `tenant` VALUES (1883, 255, NULL, 'Batika', 'Anindya Satyanugraha', 19, 1, 'MAGUWOHARJO DEPOK KABUPATEN SLEMAN', NULL, '14.040.000,00', 'Facebook / Instagram', 'Export', 'Arus Kas Sederhana', '<p>Batika merupakan produsen tas dengan bahan utama kain nusantara dikombinasikan dengan kulit sapi asli atau kulit sintetis. Saat ini kami juga mengembangkan produk lain seperti payung batik tulis dengan kualitas premium. Kami berusaha menjaga standar produksi kami dan terus meningkatkan kualitas.</p><div><br></div>', '2021-06-07', '2021-10-16', '2023-08-25 11:40:18', '2023-08-25 11:40:18');
INSERT INTO `tenant` VALUES (1884, 255, NULL, 'Beras Murni Organik', 'Khodijah Nur Hanifa', 40, 2, 'Jl. Sisingamangaraja No 22-B Mergangsan Brontokusuman Yogyakarta', NULL, '4.800.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Arus Kas Sederhana', '<p>Murni Organik merupakan penyedia beras organik di Yogyakarta yang berdiri sejak tahun 2014. Murni Organik berkomitmen untuk senantiasa amanah, meningkatkan mutu produk, mematuhi sistem pengendalian kualitas sesuai regulasi yang diterbitkan oleh Pemerintah Indonesia termasuk&nbsp; standar organik SNI 6729-2016 dan standar halal MUI serta memelihara kemitraan yang sehat (fair trade) dengan kelompok tani mitra berlandaskan mutual trust.</p><div><br></div>', '2021-06-07', '2021-10-16', '2023-08-25 11:43:55', '2023-08-25 11:43:55');
INSERT INTO `tenant` VALUES (1885, 255, NULL, 'Dermayu Catering Jogja', 'Putri Yufiza Atha', 23, 2, 'Perumahan Alam Citra Blok E/7, Panggungharjo, Sewon, Bantul, DIY', NULL, '3.600.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Arus Kas Sederhana', '<p>Kami penyedia jasa Snack &amp;amp; rice box service, namun saat ini juga menyediakan penjualan produk Aneka risol dan ayam berbumbu</p><div><br></div>', '2021-06-07', '2021-10-16', '2023-08-25 11:46:19', '2023-08-25 11:46:19');
INSERT INTO `tenant` VALUES (1886, 255, NULL, 'Sam Florist', 'Susanna Stella Wulandari', 40, 1, 'Jalan setyaki no 23, wirobrajan, Yogyakarta', NULL, '240.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', 'Ekonomi Kreatif pembuatan kerajinan', '2021-06-10', '2021-10-17', '2023-08-25 11:50:11', '2023-08-25 11:50:11');
INSERT INTO `tenant` VALUES (1887, 255, NULL, 'Rendang Tuna bin Sangkut', 'Aulia Mahmud', 4, NULL, 'Jl. Podang No.6, RT.13/RW.49.03, Mrican, Catur Tunggal, Depok, Sleman', NULL, '1.020.000,00', 'Facebook / Instagram', 'Nasional', 'Rugi Laba,Arus Kas Sederhana', '<p>bin Sangkut adalah produsen olahan ikan tuna yang berbasis di Sleman, dengan produk utamanya yaitu rendang ikan tuna.</p><div><br></div>', '2021-07-10', '2021-10-17', '2023-08-25 19:54:19', '2023-08-25 19:54:19');
INSERT INTO `tenant` VALUES (1888, 255, NULL, 'Kepiting Unyuk', 'Hadianti Deliana Ragacosanda', 23, NULL, 'CABEYAN RT 02, PANGGUNGHARJO, SEWON, BANTUL', NULL, '5.000.000,00', 'Facbook, Instagram, dan Youtube', 'Nasional', 'Rugi Laba', '<p>Kepiting Unyuk Spesialis Kepiting Kerang Bumbu Gemes Khas Pantura satu-satunya di JOGJA yang sudah melalang buana ke Jabodetabek, Bandung, Bogor Solo, Malang, Kediri, Pare, Banyuwangi, Jember dan terjauh sampai ke Balikpapan, Sumatera Selatan<br></p>', '2021-07-10', '2021-10-17', '2023-08-25 20:04:40', '2023-08-25 20:04:40');
INSERT INTO `tenant` VALUES (1889, 255, NULL, 'Indokarya Jogja sandal wudhu', 'Fitri ariyani', 20, NULL, 'Danukusuman GK 4 no 1166 RT 12 RW 04, BACIRO, GONDOKUSUMAN, KOTA YOGYAKARTA', NULL, '120.000.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>\"Indokarya jogja adalah produsen sandal jepit berbahan spon eva dengan mengusung brand \' SANDALWUDHU.NET \' . Diawal berdiri kami produksi sandal wudhu atau sandal jepit untuk sedekah, dengan tulisan cutting press.Dengan proses cutting press, produk kami jamin anti luntur sampai tipisnya sandal. Saat ini,kami telah mengembangkan varian produk, yaitu sandal custom nama, untuk mencakup market yang lebih luas. Bulan Juni 2022 kita lounching brand dengan nama \' tatag\'\"</p><div><br></div>', '2021-06-10', '2021-10-17', '2023-08-25 20:14:07', '2023-08-25 20:14:07');
INSERT INTO `tenant` VALUES (1890, 255, NULL, 'Bandeng Rawe', 'Ma\'ruf Kamala Rizki', 4, NULL, 'Jl.Bibis DS Gancahan 8, RT.4/RW.18, Sidomulyo, Sleman, Yogyakarta, Daerah Istimewa Yogyakarta 55264', NULL, '50.000.000,00', 'Facbook, Instagram, dan Youtube', 'Export', 'Pembukuan sederhana (uang masuk dan uang keluar), Neraca laba rugi, Jurnal UMUM, HPP, Laporan arus kas', '<p>Bandeng Rawe kondisi saat ini lebih dalam tahap berkembang&nbsp; , karena sudah memiliki legalitas berbadan hukum PT , Halal , Jogjamark&nbsp; , dan BPOM ( procsess) , saat ini kendala kami&nbsp; adalah&nbsp; pemgembangan di bagian produksi dan&nbsp; pemasaran .</p><div><br></div>', '2021-06-10', '2021-10-17', '2023-08-25 20:20:17', '2023-08-25 20:20:17');
INSERT INTO `tenant` VALUES (1892, 255, NULL, 'Kripik wader Sidiq Rizal', 'Dita Bela Saputri', 23, NULL, 'Pundung , Pedukuhan V,  rt/rw 017/009 , Banaran , Galur , Kulon progo', NULL, '60.000.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Pembukuan sederhana (uang masuk dan uang keluar), HPP', '<p>Pesanan mulai banyak dan mulai berkembang kembali namun masih perlu scale up</p><div><br></div>', '2021-06-10', '2021-10-17', '2023-08-25 20:52:35', '2023-08-25 20:52:35');
INSERT INTO `tenant` VALUES (1893, 255, NULL, 'Omah Nyulam', 'Faida Zuhria', 40, NULL, 'Kajen RT 01, Bangunjiwo, Kasihan, Bantul', NULL, '10.000.000,00', 'Facebook / Instagram', 'Nasional', 'Microsoft Excel', '<p>Omah nyulam didirikan sejak tahun 2017, namun pertumbuhannya masih sangat lambat dan dalam tahap berkembang.&nbsp;</p><div><br></div>', '2021-06-10', '2021-10-17', '2023-08-25 20:59:20', '2023-08-25 20:59:20');
INSERT INTO `tenant` VALUES (1894, 255, NULL, 'HWW Food & Snack', 'Hanum Wahyu Wibisono', 23, 2, 'Klewonan RT 21 RW 09, Triharjo, Wates, Kulon Progo, DI Yogyakarta', NULL, '72.000.000,00', 'Facebook / Instagram', 'Export', 'Neraca,Rugi Laba,Jurnal,Arus Kas Sederhana', '<p>Mengembangkan usaha dengan mencoba masuk ke toko retail</p><div><br></div>', '2021-06-10', '2021-10-17', '2023-08-25 21:16:29', '2023-09-04 14:25:53');
