INSERT INTO `tenant` VALUES (1899, 185, 'public/foto_profil_tenant/64f53c7391353.png', 'Hidroponik', 'Yulianus Asi', 2, 2, 'Jalan Cilik Riwut  Km 8', NULL, '1.000.000,00', 'Hybrid', 'Lokal', 'belum ada', '<p>usaha yang dijalankan di bidang hidroponik dengan produk berupa sawi daging dan sawi hijau biasa.&nbsp; awal usaha di jalan cristopel mihing, sekarang sudah pindah ke jalan cilik riwut km 8. permasalahan yang di hadapi saat ini yaitu hilirisasi produk, modal yang terbatas, pembukuan yang belum ada, packing produk masih minimalis, belum memiliki label tetap produk.. panen sayur dilakukan 2 kali dalam sebulan. harga sayur perbungkusnya yaitu 10.000</p>', '2023-08-30', '2023-08-30', '2023-09-04 09:09:55', '2023-09-04 09:09:55');
INSERT INTO `tenant` VALUES (1900, 185, 'public/foto_profil_tenant/64f53e76301b8.jpeg', 'Warung Makan Fatima', 'Nurmin', 23, 2, 'Jln Pinus RT 003 Rw 014 Panarung Pahandut Kota Palangka Raya', NULL, '5.000.000,00', 'hybrid', 'lokal', 'belum', '<p>UMKM bergerak dibidang pengolaan bahan makanan (makanan dan minuman) produk yang dijual dalam kondisi segar seperti produk catering dan olahan makanan warung. packing dan label prodk blm ada, pembukuan belum ada.&nbsp;</p>', '2023-08-30', '2023-08-30', '2023-09-04 09:18:30', '2023-09-04 09:18:30');
