INSERT INTO `tenant` VALUES (1948, 255, NULL, 'Dien Cakery', 'Nisa Setiyadin Ayu Lestari', 23, 2, 'Perum. APH blok A-10 Seturan, CATUR TUNGGAL, DEPOK, KABUPATEN SLEMAN', NULL, '3.000.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Arus kas sederhana', '<p>saat ini sedang berkembang, tetapi agak lambat, dan berencana di tahun ke-2 menambah karyawan dan perluasan ruang kerja.&nbsp; dan Rencana tahun ke-5 memiliki outlet dan tidak lagi menjadi bisnis rumahan.<br></p>', '2021-10-06', '2021-10-17', '2023-09-04 14:59:38', '2023-09-04 14:59:38');
INSERT INTO `tenant` VALUES (1949, 255, NULL, 'Ghalasa Griya Jahit dan BAHITUNG BLACK GARLIC', 'AMILATUL FADHILAH', 23, 2, 'NGRINGIN, Rt. 002 Rw. 022', NULL, NULL, NULL, NULL, NULL, NULL, '2021-06-10', '2021-10-17', '2023-09-04 15:01:50', '2023-09-04 15:01:50');
INSERT INTO `tenant` VALUES (1950, 255, NULL, 'Mama Cookies', 'Anjani Risma Damarjati', 23, 2, 'Perum Hinalang Asri, Jl. Umbul Rondo No.12 RT 01 RW 37, Wedomartani, Ngemplak, Sleman, Yogyakarta', NULL, '2.400.000,00', 'Facbook, Instagram, dan Youtube', 'Nasional', 'Arus Kas Sederhana', '<p>Mama Cookies dimulai sejak Maret, 2014. Berawal dari hobi saya dan suami yang suka makan kue, lalu iseng mencoba membuat kue sendiri. Dari keisengan, saat ini Mama Cookies menjadi penopang ekonomi keluarga. Mama Cookies adalah usaha yang dibangun atas kerjasama dan kekompakan antara istri dan suami. Berlokasi di Kota Jogja, dari halaman rumah yang dirubah jadi tempat produksi kue rumahan. Mama Cookies sangat mengutamakan rasa dan kualitas bahan yang premium. Ada ciri khas tersendiri di produk kue Mama Cookies yang akan membuat para pelanggan selalu kangen akan semua produk Mama Cookies. </p><p>Moto kami : Serve the Best Taste with Low Price, yang berarti meskipun Mama Cookies memiliki cita rasa premium namun soal harga masih sangat terjangkau.</p>', '2021-06-10', '2021-10-17', '2023-09-04 15:02:21', '2023-09-04 15:12:25');
