INSERT INTO `tenant` VALUES (2017, 312, 'public/foto_profil_tenant/64f6a8a203c49.jfif', '@lokalasari', 'Selvi Tisari Handayani', 23, 2, 'Gg. Masjid RT 07/05 No. 15, Ratu Jaya, Cipayung, Depok', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-09-05 11:03:46', '2023-09-05 11:03:46');
INSERT INTO `tenant` VALUES (2018, 255, 'public/foto_profil_tenant/64f6cc4dd05ee.png', 'Begjava', 'Rosi Nolasari', 27, 2, 'Tegalsari rt10, gang sadewo no59, jomblangan banguntapan bantul 55198', NULL, '60.000.000,00', 'Facbook, Instagram, dan Youtube', 'Nasional', 'Arus Kas Sederhana', '<p>Begjava adalah sebuah kerajinan tas dan dompet handmade yang terbuat dari 60% bahan wastra nusantara dengan perpaduan bahan tekstil lainya<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 13:30:28', '2023-09-06 08:30:58');
INSERT INTO `tenant` VALUES (2019, 255, 'public/foto_profil_tenant/64f7db3b8f33b.png', 'Pancal Bike', 'Sri Ratna Sari', 15, 2, 'Karangturi rt 07, Manggisan, Baturetno, Banguntapan, Bantul, Yogyakarta (55197)', NULL, '116.400.000,00', 'Facbook, Instagram, dan Youtube', 'Nasional', 'Arus Kas Sederhana', '<p>Pancal Bike Craft adalah usaha kecil menengah yang bergerak di bidang kerajinan kayu. Kerajinan kayu yang kami produksi adalah berupa sepeda, keseimbangan atau balance bike yang digunakan untuk anak – anak usia 1,5 – 6 tahun. Pancal Bike sudah bersertifikasi SNI, jadi aman untuk anak.</p>', '2022-05-17', '2022-09-14', '2023-09-05 13:34:32', '2023-09-06 08:51:55');
INSERT INTO `tenant` VALUES (2020, 255, 'public/foto_profil_tenant/64f7db7f156d3.jpg', 'Mbah Carik', 'Angga  Kusuma Arybowo', 23, 2, 'JL PALAGAN KM 16, GLONDONG, PURWOBINANGUN, PAKEM, SLEMAN', NULL, '116.400.000,00', 'Facebook / Instagram', 'Nasional', 'Neraca,Rugi Laba,Jurnal,Arus Kas Sederhana', '<p>Warung Jadah Tempe Mbah Carik (Palagan) melestarikan kuliner autentik Jogjakarta</p>', '2022-05-17', '2022-09-14', '2023-09-05 13:38:59', '2023-09-06 08:53:03');
INSERT INTO `tenant` VALUES (2021, 255, 'public/foto_profil_tenant/64f6cd2c62d25.jpg', 'Ui&iO d\'chocolato', 'Pisilia Yusika', 23, 2, 'Jl.imogiri barat km 5 dusun Tanjung RT 04 Bangunharjo Sewon Bantul Yogyakarta', NULL, '60.000.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>Utik_iyok CokelatKarakterJogja berdiri pada tanggal 26 Mei 2020, berlokasi di Jl.imogiri barat km 5 dusun tanjung RT 04 Bangunharjo Sewon bantul Yogyakarta, Kami memproduksi olahan&nbsp; Cokelat karakter yang kami kemas dalam berbagai kemasan mengikuti target pasar yanng dituju...</p><p>1. kemasan retail plastik opp (untuk mitra jajanan pasar)</p><p>2. kemasan Loly ( untuk toko retail dan bakery)</p><p>3. kemasan box custom ( untuk online)</p><p>4. kemasan toples ( paket hampers hari besar)</p>', '2022-05-17', '2022-09-14', '2023-09-05 13:39:40', '2023-09-06 08:48:35');
INSERT INTO `tenant` VALUES (2022, 255, 'public/foto_profil_tenant/64f7dba94b035.jpeg', 'Lapakkarya', 'Ima Azzahra', 15, 2, 'Jl.Minggiran No.14, RT 51/RW 14, Suryodiningratan, Mantrijeron, Yogyakarta', NULL, '60.000.000,00', '-', 'Export', 'Neraca,Rugi Laba,Arus Kas Sederhana', NULL, '2022-05-17', '2022-09-14', '2023-09-05 13:43:41', '2023-09-06 08:53:45');
INSERT INTO `tenant` VALUES (2023, 255, 'public/foto_profil_tenant/64f6ce428438d.png', 'WONBI', 'Ratna  Palupi', 23, 2, 'Sanggrahan, RT. 08, Gg. Rebab, Sanggrahan, Ngestiharjo, Kec. Kasihan, Kabupaten Bantul, Daerah Istimewa Yogyakarta 55184', NULL, '60.000.000,00', 'Facbook, Instagram', 'Nasional', 'Neraca,Rugi Laba,Jurnal', '<p>Usaha rumahan yang dimulai dari 10 juni 2022.</p><p>dimulai dari kemasan yang sederhana, masih rawan bocor. Kemudian kami berusaha untuk terus berinovasi menjadikan WONBI menjadi produk unggulan ibu-ibu untuk membantu mempermudah aktivitas di dapur.</p>', '2022-05-17', '2022-09-14', '2023-09-05 13:44:18', '2023-09-06 08:48:05');
INSERT INTO `tenant` VALUES (2024, 255, 'public/foto_profil_tenant/64f7dbdb518e3.png', 'Akukira Indonesia', 'Azhar Assa  M', 15, 2, 'Jalan Wonosari km 8 Sekarsuli RT 04', NULL, '48.000.000,00', 'Facebook / Instagram', 'Nasional', 'Neraca,Rugi Laba,Arus Kas Sederhana', NULL, '2022-05-17', '2022-09-14', '2023-09-05 13:45:27', '2023-09-06 08:54:35');
INSERT INTO `tenant` VALUES (2025, 255, 'public/foto_profil_tenant/64f6cef7ae4b9.jpg', 'Mie Ayam  Kura-kura  Kecil', 'Agita Yuri Wida  Kiatanti', 23, 2, 'Jomegatan, Tirtonirmolo, Kasihan, Bantul', NULL, '48.000.000,00', 'Facebook / Instagram', 'Nasional', 'Rugi Laba,Jurnal,Arus Kas Sederhana', '<p>Usaha ini pertama kali berdiri pada tanggal 7 September 2017 bertempat di gang kecil dekat pusat bakpia, tapi hanya sebagai sambilan di sore hari. Usaha warung kemudian pindah ke Jatimas selama beberapa bulan lalu kami putuskan berhenti di bulan Oktober 2018 karena kesulitan finansial. Berkat pandemi dan pengalaman PHK, usaha warung dibuka lagi secara online. Karena melihat animo yang bagus, maka diadakanlah warung offline sejak 2 Februari 2022, bertempat di Jomegatan Bantul.<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 13:47:19', '2023-09-06 08:47:30');
INSERT INTO `tenant` VALUES (2026, 255, 'public/foto_profil_tenant/64f6d02141997.jpg', 'Auko', 'Dody R', 23, 2, 'Jl kyai mojo 64 Yogyakarta', NULL, NULL, 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>Auko adalah produsen makanan siap makan memajukan citarasa makanan Indonesia<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 13:52:17', '2023-09-06 09:19:30');
INSERT INTO `tenant` VALUES (2027, 255, 'public/foto_profil_tenant/64f6d065527ef.jpeg', 'Wisticy  Outfit', 'lswati', 26, 1, 'Harjowinatan PA1/757 044/010 Pakualaman Purwokinannti 55112, KOTA YOGYAKARTA', NULL, '36.000.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>Wisticy Outfit merupakan usaha dibidang fashion ready to wear serta aksesoris dengan memanfaatkan kain-kain tradisional sebagai bahan utamanya.&nbsp;</p><p><br></p><p>Menggunakan konsep zero waste pada aplikasinya sehingga meminimalisir adanya limbah dari kain yang dihasilkan bahkan sisa kain yang dihasilkan masih bisa dirangkai ulang menjadi</p><p>suatu produk baru.</p><p><br></p><p>Kedepannya Wisticy ingin lebih fokus sebagai produk yang ramah lingkungan, dan mengembangkan upcycle produk baru yang lebih kekinian.</p>', NULL, NULL, '2023-09-05 13:53:25', '2023-09-05 13:53:25');
INSERT INTO `tenant` VALUES (2028, 255, 'public/foto_profil_tenant/64f6d1145e97c.png', 'Simbok  Sireng', 'Mega  Rahmawati', 23, 2, 'Kiringan RT.004 Canden Jetis Bantul DIY 55781', NULL, '30.000.000,00', 'Facebook / Instagram', 'Nasional', 'Neraca,Rugi Laba,Jurnal,Arus Kas Sederhana', '<p>Simbok Sireng merupakan UKM yang bergerak pada usaha jamu tradisional. Terdapat 2 jenis produk Simbok Sireng yaitu jamu tradisional cair dan jamu tradisional instan. Jamu tradisional cair terdiri dari 10 varian yaitu beras kencur, kunyit asam, parem, godhong telo, uyup-uyup, paitan, temulawak, jamu galian (pegel linu), sirih, parem taun, dan untuk jamu tradisional instan terdiri dari 5 varian yaitu: beras kencur, kunyit asam, jahe merah, jahe wangi, dan wedang uwuh.<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 13:56:20', '2023-09-06 08:44:59');
INSERT INTO `tenant` VALUES (2029, 255, NULL, 'Rocklee.inc', 'Mariana  Febrianti', 19, 1, 'jl.wates km.10 pedes rt.05, argomulyo, sedayu, bantul', NULL, NULL, 'Facebook / Instagram', 'Nasional', NULL, NULL, '2022-05-17', '2022-09-14', '2023-09-05 13:56:55', '2023-09-06 09:21:10');
INSERT INTO `tenant` VALUES (2030, 255, 'public/foto_profil_tenant/64f6d2d3afded.png', 'AnD  (Furniture)', 'AnD  (Furniture)', 5, 2, 'Jl. Bandulan RT 07 RW 14', NULL, NULL, 'Facebook / Instagram', 'Ekspor', 'Jurnal', '<div style=\"text-align: justify;\">Nangoma adalah pelaku usaha yang bergerak di bidang homedecor dari kayu dan bahan lain untuk pendamping atau modifikasi. Mempunyai visi menjadikan usaha yang berkelanjutan antara nangoma dengan pembeli juga nangoma dengan mitra kerja kami. Misi kami adalah selalu mengirim produk yang sesuai dengan pesanan dan harapan pembeli,menjaga komunikasi yang baik juga menjaga kepercayaan.</div>', '2022-05-17', '2022-09-14', '2023-09-05 14:03:47', '2023-09-06 09:22:17');
INSERT INTO `tenant` VALUES (2031, 255, 'public/foto_profil_tenant/64f6d34302e6d.jpeg', 'Nangkatsu', 'Hidayati  Nur Hakimah', 23, 2, 'Gang Mawar 8d, Jalan Affandi, Santren, Caturtunggal, Depok, Sleman, Yogyakarta', NULL, '18.000.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Rugi Laba,Arus Kas Sederhana', NULL, '2022-05-17', '2022-09-14', '2023-09-05 14:05:39', '2023-09-06 08:43:50');
