INSERT INTO `tenant` VALUES (2035, 255, 'public/foto_profil_tenant/64f7dc497e480.jpg', 'Berlyan Food', 'Atmini  Yulianti', 23, 2, 'Ngrancah, Rt 04, Sriharjo,Imogiri,Bantul,Yogyakarta', NULL, '24.000.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Laporan Laba/Rugi, Arus Kas Sederhana', '<p>Berlyan Food Jogja </p><p>produk: Herbs dan bumbu masakan, home made saus pasta, Pizza&nbsp;</p><p>Supplier Bahan Kuliner : Keju Mozzarella, saus home made, dan lainnya sesuai permintaan yang dibutuhkan sesama umkm dan pelaku usaha</p>', '2022-05-17', '2022-09-14', '2023-09-05 14:10:46', '2023-09-06 08:56:25');
INSERT INTO `tenant` VALUES (2036, 255, 'public/foto_profil_tenant/64f6d4b96756e.jpg', 'Tutemy', 'Erny susanti', 23, 2, 'jalan ringroad timur (majapahit) wonocatur 14c, banguntapan bantul 55198, KABUPATEN BANTUL', NULL, '18.000.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Arus Kas Sederhana', NULL, '2022-05-17', '2022-09-14', '2023-09-05 14:11:53', '2023-09-06 13:11:40');
INSERT INTO `tenant` VALUES (2037, 255, 'public/foto_profil_tenant/64f6d4dca1d6f.jpg', 'Kedaton  Tailor & konveksi', 'Kedaton  Tailor & konveksi', 19, 1, 'Kedaton, Rt. 01 Desa Pleret, Kec. Pleret, Kabupaten Bantul', NULL, NULL, 'Facebook / Instagram', 'Ekspor', NULL, NULL, '2022-05-17', '2022-09-14', '2023-09-05 14:12:28', '2023-09-06 13:20:03');
INSERT INTO `tenant` VALUES (2038, 255, 'public/foto_profil_tenant/64f7dc7e6ccc3.png', 'Drana', 'Maria  Primasari  Dewi', 23, 2, 'Jl. Adisucipto no 22 trirenggo Bantul', NULL, '24.000.000,00', '-', 'Wilayah DI Yogyakarta', 'Neraca,Rugi Laba,Arus Kas Sederhana', '<p>Drana Kitchenette merupakan usaha makanan online berbasis menu pasta, pudding, pie. Dimulai sejak tahun 2020 dengan 2 produk, hingga tahun 2023 sudah memiliki 22 pilihan menu yang beragam<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 14:14:24', '2023-09-06 08:57:18');
