INSERT INTO `tenant` VALUES (2040, 255, 'public/foto_profil_tenant/64f6d63c34900.png', 'somah  wooden  cutery', 'Leonie  Dian Anggrasari', 15, 2, 'Gesik RT 3 padukuhan Kalipucang,BANGUNJIWO,KASIHAN,KABUPATEN BANTUL', NULL, '6.000.000,00', 'Facebook / Instagram', NULL, 'Arus Kas Sederhana', NULL, '2022-05-17', '2022-09-14', '2023-09-05 14:18:20', '2023-09-06 13:12:39');
INSERT INTO `tenant` VALUES (2041, 255, 'public/foto_profil_tenant/64f7dcb68f844.jpeg', 'Batu Sangka Sate Padang', 'Batu Sangka Sate Padang', 23, 2, '1. Jl. Taman Siswa, Wirogunan, Kec. Mergangsan, Kota Yogyakarta, Daerah Istimewa Yogyakarta 55151 (utara printshop jogja)', NULL, '18.000.000,00', 'Facebook / Instagram', 'Nasional', 'Jurnal, Arus Kas Sederhana', '<p>Usaha ini dimulai sejak tahun 2018, merupakan cabang dari rumah makan dan sate padang bang kumis batusangka yang ada di Sumatera dan Riau. Sate padang bang kumis batusangka, rendang batusangka, dan kripik manihot, merupakan brand dari kegiatan usaha penulis, karena masakan tersebut merupakan masakan khas daerah dengan bahan baku seperti beras, daging sapi, dan ubi singkong serta rempah pilihan yang menjadikan produk tersebut khas.<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 14:20:53', '2023-09-06 08:58:14');
INSERT INTO `tenant` VALUES (2042, 255, 'public/foto_profil_tenant/64f6d763f1a74.jpeg', 'KOTES  (Kentang  Olahan Tasty)', 'Rijalul Alam', 23, 2, 'Demangan Ponegaran Rt 05, JAMBIDAN, BANGUNTAPAN, KABUPATEN BANTUL', NULL, '282.000,00', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Rugi Laba,Arus Kas Sederhana', '<p>ERRA Food adalah produsen kering kentang mustofa dengan merek KOTES. Fokus dalam industri makanan terutama fokus keripik kentang</p><p>KOTES telah memiliki legalitas lengkap Dinkes P-Irt, MUI Halal, Merek HKI, dan Jogja Mark</p>', '2023-05-17', '2023-09-14', '2023-09-05 14:23:15', '2023-09-06 13:13:58');
INSERT INTO `tenant` VALUES (2043, 255, NULL, 'Artniq  Batik', 'Sumarni  Alisha Aprilia', 19, 2, 'Singosaren, Desa Singosaren, Kec. Bangutapan, Kab. Bantul', NULL, NULL, 'Facebook / Instagram', 'Nasional', NULL, NULL, '2022-05-17', '2022-09-14', '2023-09-05 14:23:18', '2023-09-06 13:23:05');
INSERT INTO `tenant` VALUES (2044, 255, 'public/foto_profil_tenant/64f7dce8533f9.jpg', 'Griya Tani Lestari', 'Beni Puji Astuti', 1, 2, 'JL Rajawali 3 gang 1 no B-18 Klaseman, Sinduharjo, Ngaglik, Sleman, Yogyakarta', NULL, '18.000.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>Griya Tani Lestari: Memajukan Kelompok Perempuan melalui gerakan pangan lestari skala rumah tangga untuk mencukupi kebutuhan harian rumah tangga dan mendorong kegiatan women – entrepreneurship</p>', '2022-05-17', '2022-09-14', '2023-09-05 14:25:15', '2023-09-06 08:59:04');
