INSERT INTO `tenant` VALUES (2047, 255, 'public/foto_profil_tenant/64f7dd0c06cdc.png', 'Seguut', 'Andi Sopyan Sauri', 23, 2, 'Bedreg Gg. Matahari I no 11 RT 09 RW 41 Sembego, Maguwoharjo, Depok, Sleman, Yogyakarta', NULL, '15.707.167,20', 'Facebook / Instagram', 'Wilayah DI Yogyakarta', 'Neraca,Rugi Laba,Jurnal,Arus Kas Sederhana', '<p>Seguut mempunyai 2 kategori makanan yaitu makanan berat dan jajanan. Makanan beratnya yaitu ayam Taliwang dan jajanan seblak, cireng dan sebagainya<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 14:27:34', '2023-09-06 08:59:40');
