INSERT INTO `tenant` VALUES (2049, 255, 'public/foto_profil_tenant/64f7dd3dd4f98.jpg', 'De Chens Aloevera', 'Rr. Chrityaningsih', 23, 2, 'Pendem Rt. 08 Rw. 04 Sidomulyo pengasih kulon progo', NULL, '12.000.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>De Cends Aloevera merupakan usaha agrobisnis tanaman lidah buaya mulai dari budidaya, pengolahan hasil panen hingga pemasaran hasil olahan tanaman lidah buaya<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 14:29:55', '2023-09-06 09:00:29');
INSERT INTO `tenant` VALUES (2050, 255, NULL, 'Elfamous', 'M izzuddin  elyas', 26, 2, 'Perum puspa indah blok j/17 rt 09\r\nDesa Bangunjiwo, Kec. Kasihan, Kab. Bantul', NULL, NULL, NULL, 'Wilayah DI Yogyakarta', NULL, NULL, '2022-05-17', '2022-09-14', '2023-09-05 14:31:16', '2023-09-06 13:25:18');
INSERT INTO `tenant` VALUES (2051, 255, 'public/foto_profil_tenant/64f7ddba809de.jpg', 'Cemilicious', 'Cemilicious', 23, 2, 'Pelemsewu RT 01, Panggungharjo, Seown, Bantul', NULL, '9.600.000,00', 'Facebook / Instagram', 'Nasional', 'Rugi Laba,Arus Kas Sederhana', '<p>Cemilicious merupakan produsen makanan ringan yang sangat cocok untuk menemani waktumu. Produk kami berupa Peyek Kacang dan Keripik Bayam. Selain kedua produk unggulan tersebut, kami juga memproduksi pesanan khusus seperti peyek teri, cabe, kacang hijau dan kremesan.<br></p>', '2022-05-17', '2022-09-14', '2023-09-05 14:33:22', '2023-09-06 09:02:34');
INSERT INTO `tenant` VALUES (2052, 255, NULL, 'Makler Makaroni Chips & Banana Chips', 'Brahmantya  eko H  S', 23, 2, 'Dagen RT 03 Pendowoharjo Sewon Bantul', NULL, '7.200.000,00', 'Facebook / Instagram', 'Nasional', 'Arus Kas Sederhana', '<p>Maklerfood adalah usaha makanan ringan yang dirintis oleh seorang pria asal Bantul bernama Putra. Pria yang biasa dipanggil Putra ini memulai bisnisnya pada akhir tahun 2021 lalu. Berawal dari bisnis makanan kecil yang dipasarkan di sekolah-sekolah, produk Putra bisa berkembang dan bertransformasi. Maklerfood adalah produk makanan ringan makaroni dan keripik pisang dengan banyak varian. Beberapa pilihan makanan ringan dari Maklerfood adalah Makaroni Chips Chocolate, dan Banana Chips Chocolate. Pilihan produk lainnya bisa Anda lihat secara langsung di akun Instagram @maklerfood</p>', '2022-05-17', '2022-09-14', '2023-09-05 14:38:03', '2023-09-06 09:04:06');
