INSERT INTO `tenant` VALUES (2364, 376, 'public/foto_profil_tenant/64fed4ac83513.jpeg', 'BAKSO MALANG 3 SAUDARA', 'FERRY YANTO', 23, 2, 'Jl. Liwa Krui, Desa Labuhan Mandi. Kec, Way Krui', NULL, '15.000.000,00', 'Banner, FB, WA', 'Pasar Lokal', NULL, '<p>Usaha Bakso Malang 3 Saudara menjual Bakso Malang, Mie Ayam, Soto Surabaya yang berlokasi di&nbsp;Jl. Liwa Krui, Desa Labuhan Mandi. Kec, Way Krui dan Depan Lapangan Merdeka Labuhan Jukung Pesisir Barat</p>', '2023-09-11', '2023-09-11', '2023-09-11 15:49:48', '2023-09-11 15:50:01');
INSERT INTO `tenant` VALUES (2365, 376, 'public/foto_profil_tenant/683d44ab7049e.jpeg', 'Kuralin_Bag', 'Kerajinan Tangan (Handycraft)', 13, 1, 'Jl. Pantai Harapan No. 106 Pekon Walur, Kec. Krui Selatan Kabupaten Pesisir Barat', NULL, '15.000.000,00', 'Instagram, Facebook, Tiktok, Grup Whatsapp', 'Pasar Lokal', 'Buku Kas dan Aplikasi Excel', '<p>Kuralin bag adalah usaha yang bergerak di bidang kerajinan tangan khususnya Tas dari Anyaman Tali Plastik, yang dibuat dengan berbagai macam bentuk dan ukuran oleh Ibu-Ibu di Pekon Walur, Kec. Krui Selatan Kabupaten Pesisir Barat sejak Tahun 2018.</p>', '2023-09-14', '2023-09-14', '2023-09-15 10:04:13', '2025-06-02 13:28:59');
INSERT INTO `tenant` VALUES (2366, 376, NULL, 'Homemade_Bundanizaky', 'Etika Merlina', 23, 2, 'Pekon Way Sindi Hanuan Kec. Karya Penggawa Kabupaten Pesisir Barat', NULL, '2.000.000,00', 'Banner dan Media Sosial', 'Pasar Lokal dan Nasional', 'Buku Manual', '<p>Homemade_Bundanizaky bergerak dibidang Kuliner, menyediakan berbagai macam menu kekinian dan sehat. contoh : Salad Buah, Jasuke, Sari Kacang Hijau berdiri sejak tahun 2017</p>', '2023-09-15', '2023-09-15', '2023-09-15 11:24:35', '2023-09-15 11:24:35');
INSERT INTO `tenant` VALUES (2367, 376, NULL, 'Ayam Geprek Djontor', 'Revadila Alzilzalia', 23, 2, 'Seray, SP. Bandara', NULL, '20.000.000,00', 'Media Sosial, Banner', 'Pasar Lokal', 'Buku Manual', '<p>Ayam Geprek Djontor menjual makanan berat berupa Ayam, Ikan dan Bebek.</p>', '2023-09-15', '2023-09-15', '2023-09-15 11:35:50', '2023-09-15 11:36:42');
INSERT INTO `tenant` VALUES (2368, 376, 'public/foto_profil_tenant/675fa2c4553f2.jpeg', 'KERUPUK IKAN MARLIN', 'ALI ALHAFIF', 23, 2, 'Jl. Abdul Hamid Bhakti Rahayu Rawas Kecamatan Pesisir Tengah Kabupaten Pesisir Barat', NULL, '10.000,00', 'Instagram, Grup to Grup WhatsApp', 'Pesisir Barat Lampung', 'Buku Kas dan Aplikasi Spread Sheet', '<p>Krupuk Ikan Marlin adalah usaha yang bergerak di bidang produk sneck oleh-oleh, yang menggunakan inovasi olahan ikan marlin khas Pesisir Barat, berdiri sejak tahun 1985 di Krui<br></p>', '2023-09-06', '2023-09-08', '2023-09-18 13:49:32', '2024-12-16 10:47:16');
INSERT INTO `tenant` VALUES (2369, 249, 'public/foto_profil_tenant/6509555343535.jpg', 'Forestri Hidro Farm', 'Muhammad Faiz', 1, 2, 'Dusun Japing, Desa Sunggumanai, Kecamatan Pattallassang, Kabupaten Gowa', NULL, '3.000.000,00', 'Instagram dan facebook', 'frozen food', 'ada', '<p>Budidaya tanaman selada sistem pertanian hidroponik rakit apung</p>', '2023-09-11', '2024-06-30', '2023-09-19 13:40:46', '2023-12-11 11:50:03');
INSERT INTO `tenant` VALUES (2370, 249, 'public/foto_profil_tenant/65095bec6a7c4.jpeg', 'COBASAI', 'Elvira', 23, 2, 'Cambayya, Desa Lonrong, Kecamatan Eremerasa, Kabupaten Bantaeng', NULL, '2.500.000,00', 'WhatsApp, Instagram, Facebook', 'Kabupaten Bantaeng, Makassar, dan Kabupaten Kolaka Utara', 'Ada', '<p>Usaha ini bernama \"COBASAI\" yang terbentuk pada tahun 2021 dengan jargon \"Galau? Di CoBain aja, Karena Kamu Berhak Bahagia\". Usaha ini bergerak pada olahan biji kakao dan memiliki beberapa produk yaitu CoBa Puding dan Minuman serbuk. Varian minuman serbuk COBASAI memiliki beberapa varian rasa yaitu CoBa Original, CoBA susu, dan CoBa Kopi. Minuman serbuk ini dapat dinikmati panas maupun dingin sehingga dapat menemani disemua kondisi.<br></p>', '2023-09-11', '2024-06-30', '2023-09-19 15:29:32', '2023-12-11 11:49:41');
INSERT INTO `tenant` VALUES (2371, 236, 'public/foto_profil_tenant/650961b233c97.png', 'Digdaya Farm', 'Tedi Hidayatulloh, S.Tr.Pt.', NULL, NULL, 'Polbangtan Bogor Kampus Cinagara \r\nJl. Snakma Desa Pasir Buncir Kec. Caringin Kab. Bogor Prov. Jawa Barat', NULL, '493.000.000,00', 'Instagram: @Digdayafarm.id; Tiktok: @Digdayafarm.id', NULL, NULL, NULL, '2023-08-29', '2025-08-29', '2023-09-19 15:54:10', '2023-09-19 15:54:10');
INSERT INTO `tenant` VALUES (2372, 236, 'public/foto_profil_tenant/650969be56eca.jpeg', 'Oyag Farm', 'Fajar Arifin, S.Tr.Pt.', NULL, NULL, 'Komplek Balittri Rt 46 Rw 19 Desa Sundawenang\r\nKecamatan Parungkuda Kabupaten Sukabumi', NULL, '32.000.000,00', 'Instagram: Oyag Group. Co', NULL, NULL, '<p>Usaha yang bergerak di bidang budidaya domba</p>', '2023-08-29', '2025-08-29', '2023-09-19 16:28:30', '2023-09-19 16:28:30');
INSERT INTO `tenant` VALUES (2373, 249, 'public/foto_profil_tenant/650eda0a6171b.jpeg', 'SG FARM 99', 'Syahrul Gunawan', 3, 2, 'Kampung beru Desa Buakkang Kec. Bungaya Kab. Gowa', NULL, '2.500.000,00', 'WhatsApp', 'Pedagang dan masyarakat di Kabupaten Gowa', 'ada', '<p>SG FARM 99 dibangun sebagai skala usaha dibidang peternakan kususnya ternak ruminansia (sapi). Peternakan ini fokus pada penggemukan sapi dimana dilakukan pembelian sapi yg kurus-kurus badannya selanjutnya digemukkan dikandang.<br></p>', '2023-09-11', '2024-06-30', '2023-09-20 12:49:59', '2023-12-11 11:50:26');
INSERT INTO `tenant` VALUES (2374, 197, 'public/foto_profil_tenant/677b5004ee593.shtml', 'Dunia Sayur', 'Nurhikmah', 23, 2, 'Jl. Bukit Raya Barat Loktabat Selatan, Banjarbaru Kalimantan Selatan', NULL, '144.000.000,00', 'Instagram, Whatsapp', 'Lokal', 'Ada', '<p>Dunia Sayur adalah (1) Kemudahan konsumen untuk menyediakan masakan olahan sendiri di rumah untuk keluarga, (2) Kemudahan untuk menperoleh bahan sayuran dan lauk pauk, (3) Proses memasak yang lebih praktis karena sayur sudah dipotong - Kupas dan dicuci, (4) tersedia dalam bentuk menu masakan, (5) Sayur sudah komplit Bumbu siap masaka dan (6) Hemat tenaga, waktu dan juga harga.</p>', '2023-09-01', '2023-09-01', '2023-09-21 14:14:52', '2025-01-06 10:37:40');
INSERT INTO `tenant` VALUES (2375, 197, 'public/foto_profil_tenant/650bee241a067.jpg', 'Kebun Sayur Segar', 'Mokamat Pudin', 1, 2, 'Jl.Lok Damar Desa Banyu Irang Rt.08', NULL, '150.000.000,00', NULL, 'lokal', 'ada', '<p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Arial,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Kebun Sayur Segar</span></p><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Arial,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">-&nbsp; Masih segar segar langsung dari kebun</span></p><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Arial,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">- Banyaknya jenis sayuran yang ada di kebun kami&nbsp;</span></p><p><span id=\"docs-internal-guid-b769414c-7fff-94e4-6d58-0aad347e897e\"></span></p><p dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Arial,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">- Memudahkan para pelanggan untuk memilih jenis dan jumlah sayuran yang diinginkan/diperlukan</span></p>', '2023-09-01', '2025-09-01', '2023-09-21 14:17:56', '2023-09-21 14:17:56');
INSERT INTO `tenant` VALUES (2376, 197, 'public/foto_profil_tenant/650befd717619.jpg', 'Sahabat Tani', 'Muhammad Achditia Anbahar', 1, NULL, 'Komp. Pasar Bawahan RT 02 RW 01 Desa Bawahan Pasar Kecamatan Mataraman Kabupaten Banjar', NULL, '58.000.000,00', 'Whatsapp', 'Lokal', 'Ada', '<p><span style=\"font-size: 14px;\">Nilai tambah untuk pruduk kami kepada masyarakat adalah kualitas lombok kami adalah berbeda dengan produk dipasar dikarenakan, buah segar langsung petik.&nbsp; Kalau dipasar produk atau kualitasnya antara buah bagus tercampur dengan buah buruk maka pelanggan dapat membedakan mana yang untung dan tidak.</span></p><p><span style=\"font-size: 14px;\">- perawatan yang sehat akan menimbulkan konsumen yang sehat</span></p><p><span style=\"font-size: 14px;\">-&nbsp; tujuannya untuk menjaga ketahanan pangan daerah</span></p><p><span style=\"font-size: 14px;\">-meningkatkan peluang kerja dimasyarakat sekitar&nbsp;</span></p><p><span style=\"font-size: 14px;\">-memotivasi pemuda-pemudi agar semangat berwirausaha mandiri</span></p>', '2023-09-01', '2025-09-01', '2023-09-21 14:25:11', '2023-09-21 14:25:11');
INSERT INTO `tenant` VALUES (2377, 236, 'public/foto_profil_tenant/650c01f56414e.jpeg', 'Bogam Permata Bumi', 'Nahi Tua Giri, S.Tr.P.', NULL, NULL, 'Kp Bojongkapol Desa Wandasari Kecamatan Bojonggambir, Tasikmalaya', NULL, '120.000.000,00', 'Instagram Bogam Permata Bumi', NULL, NULL, '<p>Usaha yang bergerak di bidang budidaya kapolaga, jahe, cabai, timun, dan gula aren.</p>', '2023-08-29', '2025-08-29', '2023-09-21 15:42:29', '2023-09-21 15:42:29');
INSERT INTO `tenant` VALUES (2378, 410, NULL, 'Lingkar Hijau', 'Zikran', NULL, 2, 'Jl Tanggul Selatan Palu', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-09-26 14:44:59', '2023-09-26 14:44:59');
INSERT INTO `tenant` VALUES (2379, 251, 'public/foto_profil_tenant/6513be8c9b8ce.png', 'PRASEGI ART', 'YONA PRASEGI', 10, 3, 'RT 03 RW 02 Dsn. Kandeg Ds. Waung Kec. Baron Kab. Nganjuk', NULL, '200.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'BALI, KALIMANTAN', 'EXCEL', '<p><span class=\"OYPEnA text-decoration-none text-strikethrough-none\" style=\"color: rgb(33, 51, 67);\">Prasegi Art adalah usaha yang bergerak dibidang aksesoris dan modifikasi, selain itu juga memproduksi aneka kerajinan dari barang bekas.</span><br></p>', '2023-05-11', '2023-12-02', '2023-09-27 12:33:00', '2023-09-27 12:51:50');
INSERT INTO `tenant` VALUES (2380, 251, 'public/foto_profil_tenant/6513bfa5cebdc.png', 'ANANDAYU', 'SHOLAHUR ROBBANI', 19, 1, 'Dusun Wates, rt. 35 rw. 09, Desa Gondanglegi wetan, Kecamatan Gondanglegi, Kabupaten Malang, Jawa Timur', NULL, '116.100.000,00', 'WHATSAPP BUSINESS', 'Malang Raya', 'EXCEL', '<div><span data-canva-clipboard=\"\"></span><p>Hijab ecoprint adalah produk hijab yang dibuat menggunakan bahan serat alam yang ramah lingkungan. Kain hijab diwarnai menggunakan pewarna alami, sehingga aman untuk digunakan dan tidak berdampak buruk bagi lingkungan.\r\n\r\nHijab ecoprint memiliki ukuran 115 cm2, cukup besar untuk menutupi kepala dengan sempurna. Desain hijab dibuat dengan pola ecoprint yang unik &amp; elegan sehingga terlihat cantik dan anggun.\r\n\r\nSelain memiliki keindahan visual yang menarik, hijab ecoprint juga memiliki kualitas yang baik dan nyaman dipakai. Kain serat alam yang digunakan memberikan sirkulasi udara yang baik dan mengurangi risiko iritasi kulit, sehingga hijab ini cocok untuk digunakan sehari-hari.\r\n\r\nDengan menggunakan hijab ecoprint, Anda dapat tampil modis sambil tetap memperhatikan lingkungan dan keberlanjutan. Produk ini sangat cocok untuk Anda yang peduli dengan lingkungan dan ingin mendukung produk-produk yang ramah lingkungan.</p></div>', '2023-05-11', '2023-12-02', '2023-09-27 12:37:41', '2023-09-27 12:51:37');
INSERT INTO `tenant` VALUES (2381, 251, 'public/foto_profil_tenant/6513c0da06e17.png', 'SAE ROTAN SINTETIS', 'DEDY SUSANTO', 28, 3, 'Jl.sumber dongbang RT.02 RW.04 kecamatan singosari kabupaten Malang Jawa timur', NULL, '120.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'PEMASARAN LOKAL DAN EXPOR KE SINGAPURA', 'EXCEL', '<div><span data-canva-clipboard=\"\"></span><p>Produksi kerajinan, pernik hias serta furniture, juga home dekorasi untuk indoor dan out door mulai dr halaman rumah sampai dapur dari bahan rotan sintetis.</p></div>', '2023-05-11', '2023-12-02', '2023-09-27 12:42:50', '2023-09-27 12:51:21');
INSERT INTO `tenant` VALUES (2382, 251, 'public/foto_profil_tenant/6513c27e3473d.png', 'IBANA CRAFT', 'KHORUL AMIN', 28, 3, 'Jalan Pendidikan, RT 02 RW 04 Trepan Babat Lamongan Jawa Timur', NULL, '60.000.000,00', 'INSTAGRAM, WHATSAPP BUSINESS', 'LINTAS KAB/KOTA', 'EXCEL', '<span data-canva-clipboard=\"\"></span><div><span data-canva-clipboard=\"\"></span><p>Produk ini berbahan dasar pelepah pisang kering, kemudian dijadikan kerajinan berupa tas, peci dll.</p></div>', '2023-05-11', '2023-05-11', '2023-09-27 12:49:50', '2023-09-27 12:51:05');
INSERT INTO `tenant` VALUES (2383, 251, 'public/foto_profil_tenant/6513c38188287.png', 'SETARA', 'MAS IIN INAYATUL MAHMUDAH', 19, 1, 'Desa Gambuhan RT 03 RW 02 Kecamatan Kalitengah Lamongan', NULL, '500.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI, PALEMBANG, JAWA BALI', 'EXCEL', '<div><span data-canva-clipboard=\"\"></span><p>Setara Fashion menjual Dress yang di produksi sendiri oleh Setara Konveksi, kita memperhatikan kualitas produk yang kami jual, dari bahan dan jahitan.</p></div>', '2023-05-11', '2023-05-11', '2023-09-27 12:53:58', '2023-09-27 12:54:09');
INSERT INTO `tenant` VALUES (2384, 251, 'public/foto_profil_tenant/6513c45918e2a.jpg', 'FAIRALFAN COLLECTION', 'FARIDA', 19, 1, 'Dusun Krajan 010 09/03 Kel.Sumberpasir,kec.Pakis,kab.Malang,Jatim', NULL, '100.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI, KALIMANTAN, SULAWESI, PAPUA', 'EXCEL', '<div><span data-canva-clipboard=\"\"></span><p>Pada tahun 2005 saya bekerja sebagai tenaga migran Indonesia (PMI) di Hongkong,sebagian besar teman2 kami disana adalah wanita,dari pengalaman itu saya bertekad sepulang dr Hongkong akan membuka usaha yang bisa membantu untuk para wanita bekerja tanpa harus meninggalkan keluarga,dengan berbekal keahlian saya dibidang Embroidery saya mencoba membuka usaha dibidang fashion bordir dengan memberdayakan masyarakat ditempat saya pada awalnya,Alhamdulillah dengan berjalanya waktu saya juga mengikuti berbagai ujian kompetensi dibidang bordir sulam untuk meningkatkan kualitas bordir saya dan untuk bisa berbagi ilmu dibidang tersebut,sehingga sekarang saya pun bisa mengajar dibidang bordir dan sulam hingga sampai di titik penguji bordir sulam</p></div>', '2023-05-11', '2023-05-11', '2023-09-27 12:57:45', '2023-09-27 12:57:45');
INSERT INTO `tenant` VALUES (2385, 251, 'public/foto_profil_tenant/6513c54fe4401.jpg', 'BATIK MUTHIDEA', 'MUTHMAINAH', 19, 1, 'Jalan Panglima Sudirman, Rt. 35 Rw. 09 Desa Gondanglegi wetan, Kecamatan Gondanglegi, Kabupaten Malang', NULL, '100.000.000,00', 'INSTAGRAM', 'LINTAS PROVINSI, DENPASAR , BOGOR', 'EXCEL', '<div><span data-canva-clipboard=\"\"></span><p>Produk batik tulis dan batik cap yang kami tawarkan dibuat dari bahan katun premium berkualitas tinggi dengan ukuran per lembar mulai dari 2 meter sampai 2,5 meter dengan lebar 115 dan 150 cm. Kami menggunakan pewarna sintetis dan alami yang dapat disesuaikan dengan permintaan pelanggan. Pewarna sintetis memberikan kecerahan warna yang tahan lama, sementara pewarna alami memberikan sentuhan alami yang khas dan tidak berbahaya bagi lingkungan.\r\n\r\nSetiap produk batik kami dibuat dengan tangan oleh pengrajin batik yang ahli dan berpengalaman, sehingga menghasilkan kualitas batik yang luar biasa dan khas. Batik tulis dan batik cap yang kami tawarkan memiliki berbagai macam motif dan warna yang menarik, sehingga Anda dapat memilih sesuai dengan selera dan kebutuhan.\r\n\r\nDengan menggunakan produk batik kami, Anda dapat tampil gaya dengan nuansa tradisional yang elegan. Selain itu, produk batik kami juga cocok untuk menjadi pilihan hadiah yang unik dan berkesan untuk keluarga, teman, atau kolega Anda.</p></div>', '2023-05-11', '2023-05-11', '2023-09-27 13:01:51', '2023-09-27 13:01:51');
INSERT INTO `tenant` VALUES (2386, 251, 'public/foto_profil_tenant/6513c63ecc74f.jpg', 'DANITA HOMEMADE', 'PUJI ASTUTIK, S.E', 19, 1, 'Perum Graha permata reciden blokX4-5 RT7/RW14 Desa  Pakisjajar kec Pakis Kab. Malang Jawa timur', NULL, '100.000.000,00', 'INSTAGRAM', 'LINTAS KAB/KOTA', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Kaos ecoprint warna hitam, motif daun. Bahan kaos katun bambu yg yg ramah lingkungan. \\nCotton Bamboo memiliki sifat anti bakteri karena mengandung zat anti bakteri alami bernama PENNY QUINONE\\nSpesifikasi Produk :\\nBAHAN : Cotton Bamboo 30S (Kwalitas Premium)\\nKOMPOSISI : Serat Bambu 70% Katun 30% \\n\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Kaos ecoprint warna hitam, motif daun. Bahan kaos katun bambu yg yg ramah lingkungan.<br>Cotton Bamboo memiliki sifat anti bakteri karena mengandung zat anti bakteri alami bernama PENNY QUINONE<br>Spesifikasi Produk :<br>BAHAN : Cotton Bamboo 30S (Kwalitas Premium)<br>KOMPOSISI : Serat Bambu 70% Katun 30%<br><br></span></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:05:50', '2023-09-27 13:05:50');
INSERT INTO `tenant` VALUES (2387, 251, 'public/foto_profil_tenant/6513c6d5c81a5.jpeg', 'TUNIK PUTRI', 'PUTRI APRILIA', 19, 1, 'KAPAS MADYA BARAT 9A NO 30 RT 10 RW 01 KEL. KAPAS MADYA BARU KEC. TAMBAK SARI', NULL, '80.000.000,00', 'INSTAGRAM, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Batik fosfor adalah jenis batik yang memiliki kemampuan untuk bersinar atau berpendar dalam gelap. Batik ini menggunakan pewarna fosfor yang dapat menyimpan cahaya dan memancarkannya kembali dalam kegelapan. Efek ini menciptakan tampilan yang menarik dan unik pada batik fosfor.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Batik fosfor adalah jenis batik yang memiliki kemampuan untuk bersinar atau berpendar dalam gelap. Batik ini menggunakan pewarna fosfor yang dapat menyimpan cahaya dan memancarkannya kembali dalam kegelapan. Efek ini menciptakan tampilan yang menarik dan unik pada batik fosfor.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:08:09', '2023-09-27 13:08:21');
INSERT INTO `tenant` VALUES (2388, 251, 'public/foto_profil_tenant/6513c84a5dab0.png', 'GAWEKNO ROSALINI', 'UNIN ROSALINI', 19, 1, 'Jalan Gatot kaca RT 018 RW 004 kelurahan Sidorahayu kecamatan Wagir kabupaten Malang', NULL, NULL, 'INSTAGRAM, FACEBOOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI, SUMATERA, JAKARTA, SULAWESI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Produk rajut, yang dirajut secara manual menggunakan tangan. Dengan benang pilihan serta dibuat sesuai pola yang diinginkan customer&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Produk rajut, yang dirajut secara manual menggunakan tangan. Dengan benang pilihan serta dibuat sesuai pola yang diinginkan customer</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:14:34', '2023-09-27 13:14:34');
INSERT INTO `tenant` VALUES (2389, 251, 'public/foto_profil_tenant/6513c8fde942e.jpg', 'BATIK DAMARAN', 'RAHAYU NINGSIH', 19, 1, 'Dusun Krajan 2 rt 007  RW 002 desa Burno,kec.Senduro', NULL, NULL, 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'LINTAS KAB/KOTA', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Batik Damaran : Batik Tulis halus khas Lumajangan yg bercerita tentang keindahan alam&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Batik Damaran : Batik Tulis halus khas Lumajangan yg bercerita tentang keindahan alam</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:17:33', '2023-09-27 13:17:33');
