INSERT INTO `tenant` VALUES (2391, 251, 'public/foto_profil_tenant/6513ca1aad12e.jpg', 'AELEEN', 'ANGGREANA NILA AGUSTINA', 19, 1, 'Jl Empu Purwo no 290 RT 08/ RW 07, Kel. Candirenggo, Kec. Singosari, Kab. Malang', NULL, '40.000.000,00', 'INSTAGRAM, FACEBOOK, WHATSAPP BUSINESS', 'LOKAL', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Tas Kanvas dengan menggunakan Ecoprint teknik Basic dan medium teknik\\nMenggunakan Pewarna Alam Sechang\\nDaun yg digunakan Eucalyptus\\nKain yg digunakan jenis Kanvas\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Tas Kanvas dengan menggunakan Ecoprint teknik Basic dan medium teknik<br>Menggunakan Pewarna Alam Sechang<br>Daun yg digunakan Eucalyptus<br>Kain yg digunakan jenis Kanvas<br></span></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:22:18', '2023-09-27 13:22:18');
