INSERT INTO `tenant` VALUES (2393, 251, 'public/foto_profil_tenant/6513cd8ed8492.jpeg', 'KEMBANG TANJUNG', 'SOFI HIDAYAH', 19, 1, 'JL PANGLIMA SUDIRMAN GG 22 NO 21 BATU', NULL, '10.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Kembang Tanjung memproduksi berbagai produk dari jumputan dengan pewarna alami dan ecoprint antara lain kain lembaran, outer, hem, kebaya, berbagai tas, sepatu, syal dan udeng. Mengusung konsep ramah lingkungan dengan produk 100% handmade menjadikan produk Kembang Tanjung limited edition.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Kembang Tanjung memproduksi berbagai produk dari jumputan dengan pewarna alami dan ecoprint antara lain kain lembaran, outer, hem, kebaya, berbagai tas, sepatu, syal dan udeng. Mengusung konsep ramah lingkungan dengan produk 100% handmade menjadikan produk Kembang Tanjung limited edition.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:37:02', '2023-09-27 13:37:02');
INSERT INTO `tenant` VALUES (2394, 251, 'public/foto_profil_tenant/6513ce4fb9230.png', 'TJOKROHOETOMO BATIK TULIS', 'FARIDA NURSANTI', 19, 1, 'Jl. Sultan Hadiwijaya 21 Bunulrejo Blimbing Kota Malang', NULL, '50.000.000,00', 'INSTAGRAM, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Batik Tulis dengan pewarnaan alami dimana zat warna  dibuat dan diambil dari kebun pengrajin &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Batik Tulis dengan pewarnaan alami dimana zat warna dibuat dan diambil dari kebun pengrajin</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:40:15', '2023-09-27 13:40:15');
INSERT INTO `tenant` VALUES (2395, 251, 'public/foto_profil_tenant/6513ced795e2e.jpg', 'PIASONG BATIK', 'INDAHSAH FATIMATUS ZAHROH', 19, 1, 'Jl Purwantoro RT 31 RW 03 sukorejo Gondanglegi kabupaten Malang Jawa timur 65174', NULL, '50.000.000,00', 'INSTAGRAM, FACEBOOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Piasongbatik ECO dan craft adalah produk handmade berupa batik tulis, ecoprint dan craft ,sarung.\\nberdiri sejak tahun 2018,kami menggunakan bahan bahan yg berkualitas tinggi dan dikerjakan oleh tenaga ahli di bidangnya, motif bisa custom.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Piasongbatik ECO dan craft adalah produk handmade berupa batik tulis, ecoprint dan craft ,sarung.<br>berdiri sejak tahun 2018,kami menggunakan bahan bahan yg berkualitas tinggi dan dikerjakan oleh tenaga ahli di bidangnya, motif bisa custom.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:42:31', '2023-09-27 13:42:31');
INSERT INTO `tenant` VALUES (2396, 251, 'public/foto_profil_tenant/6513cfaee30c3.png', 'GALERI RADITAJAYA', 'MARIA NOFITA, S.Pd', 19, 1, 'Jl brigjen katamso 1 no 149 RT 16 RW 03 desa kedungrejo kecamatan waru kabupaten sidoarjo', NULL, NULL, 'INSTAGRAM, FACEBOOK', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Produk Hand Painting dengan cita karya bernilai seni yang tinggi. Sentuhan seni lukis yang unik dan ber karakter ada di produk kami Galeri Raditajaya. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Produk Hand Painting dengan cita karya bernilai seni yang tinggi. Sentuhan seni lukis yang unik dan ber karakter ada di produk kami Galeri Raditajaya.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:46:06', '2023-09-27 13:46:06');
INSERT INTO `tenant` VALUES (2397, 251, 'public/foto_profil_tenant/6513d24542999.jpeg', 'SELARAS', 'RISMIATI', 19, 1, 'JLN MAWAR RT001/RW001 DESA KARANGNONGKO KEC.PONCOKUSUMO', NULL, '60.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Batik Selaras adalah sebuah keajaiban kain tradisional yang merefleksikan harmoni dan keindahan dalam sebuah karya seni. Dibuat dengan penuh ketelitian dan dedikasi, Batik Selaras menampilkan desain yang mempesona dengan perpaduan warna yang cerdas dan simetri yang sempurna.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Batik Selaras adalah sebuah keajaiban kain tradisional yang merefleksikan harmoni dan keindahan dalam sebuah karya seni. Dibuat dengan penuh ketelitian dan dedikasi, Batik Selaras menampilkan desain yang mempesona dengan perpaduan warna yang cerdas dan simetri yang sempurna.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 13:57:09', '2023-09-27 13:57:09');
INSERT INTO `tenant` VALUES (2398, 251, 'public/foto_profil_tenant/6513d33c4c6fb.jpg', 'TOPENG MALANGAN', 'ENIK SETYOWATI', 19, 3, 'Jl.S supriadi 07 rt 01 rw 06 malang 65147', NULL, '40.000.000,00', 'INSTAGRAM, FACEBOOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Souvenir topeng malangan menggambarkan ciri khas kota malang dgn lebih dari 9 karakter mengingatkan kembali kepada masyarakat tentang cerita rakyat kota malang.souvenir berupa topeng untuk menari...edukasi...juga untuk oleh oleh....&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Souvenir topeng malangan menggambarkan ciri khas kota malang dgn lebih dari 9 karakter mengingatkan kembali kepada masyarakat tentang cerita rakyat kota malang.souvenir berupa topeng untuk menari...edukasi...juga untuk oleh oleh....</span><br></p>', '2023-05-11', '2023-12-02', '2023-09-27 14:01:16', '2023-09-27 14:01:16');
INSERT INTO `tenant` VALUES (2399, 251, 'public/foto_profil_tenant/6513d3cf8b4fa.jpg', 'BUNGKOH BATIK BAROYUS', 'NI\'MATUL JANNAH', 19, 1, 'Dsn watu salang RT 01 RW 03 desa Pasinan kecamatan Lekok kabupaten Pasuruan provinsi Jawa timur', NULL, '80.000.000,00', 'FACEBOOK, WhatsApp', 'LINTAS PROVINSI', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Batik butterfly adalah batik tulis yg menceritakan tentang seekor kupu-kupu yg indah yg di hasilkan oleh tapaan sebuah kepompong ulat sutra &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Batik butterfly adalah batik tulis yg menceritakan tentang seekor kupu-kupu yg indah yg di hasilkan oleh tapaan sebuah kepompong ulat sutra</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 14:03:43', '2023-09-27 14:03:43');
INSERT INTO `tenant` VALUES (2400, 251, 'public/foto_profil_tenant/6513d4b3458ad.png', 'ELJUAN', 'ELLY RISMINA S.Sos', 19, 3, 'Jl.Kedung Doro 9 / 9  RT.9 RW.11 Kel.Sawahan Kec.Sawahan Surabaya.Jawa Timur', NULL, '90.000.000,00', 'INSTAGRAM, FACEBOOK, TIKTOK, WHATSAPP BUSINESS', 'LINTAS PROVINSI', 'EXCEL', 'Aksesoris berupa kalung, gelang dan bros yang terbuat dari tulang dan sirip ikan&nbsp;', '2023-05-11', '2023-05-11', '2023-09-27 14:07:31', '2023-09-27 14:07:31');
INSERT INTO `tenant` VALUES (2401, 251, 'public/foto_profil_tenant/6513d541d12c8.jpeg', 'SANDITA (ECOPRINT BATIK)', 'YUVITA MUSDYAWATI', 19, 1, 'JL. SEBUKU 2B/ 12 RT 1 RW 8 KELURAHAN BUNULREJO KECAMATAN BLIMBING KOTA MALANG', NULL, '15.000.000,00', 'INSTAGRAM, FACEBOOK', 'LINTAS KAB/KOTA', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Batik Tulis , Sybory, Ecoprint karya handmade , pemesanan bisa custom, produk beruoa Kain, Baju, Acesories, Homedekor. ECOPRINT pewarnaan menggunakan warna alam( misal dari daun, bunga, kulit kayu sehingga ramah lingkungan)&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Batik Tulis , Sybory, Ecoprint karya handmade , pemesanan bisa custom, produk beruoa Kain, Baju, Acesories, Homedekor. ECOPRINT pewarnaan menggunakan warna alam( misal dari daun, bunga, kulit kayu sehingga ramah lingkungan)</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 14:09:53', '2023-09-27 14:09:53');
INSERT INTO `tenant` VALUES (2402, 251, 'public/foto_profil_tenant/6513d5dfb76a3.png', 'CRODERY CRAFT', 'RISVICO WAHYU SUKMAWATI', 19, 1, 'Jl. Golf No. 55 RT. 04 RW. 01 Kelurahan Tasikmadu Kecamatan Lowokwaru Kota Malang Jawa Timur', NULL, '8.400.000,00', 'INSTAGRAM, Youtube', 'EKSPOR', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Kalung etnik Crodery, adalah kalung yang diperuntukan para perempuan yang ingin selalu tampil trendi dan fashionable khususnya saat memakai baju batik di berbagai acara formal. Kalung etnik Crodery dirangkai dari manik-manik yang memanfaatkan daur ulang kayu yang kemudian dibalut dengan rajutan benang katun premium. Ada beberapa pilihan warna menyesuaikan warna-warna kain batik di pasaran. Kalung etnik rajut Crodery, pilihan smart perempuan masa kini.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Kalung etnik Crodery, adalah kalung yang diperuntukan para perempuan yang ingin selalu tampil trendi dan fashionable khususnya saat memakai baju batik di berbagai acara formal. Kalung etnik Crodery dirangkai dari manik-manik yang memanfaatkan daur ulang kayu yang kemudian dibalut dengan rajutan benang katun premium. Ada beberapa pilihan warna menyesuaikan warna-warna kain batik di pasaran. Kalung etnik rajut Crodery, pilihan smart perempuan masa kini.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 14:12:31', '2023-09-27 14:12:31');
INSERT INTO `tenant` VALUES (2403, 251, 'public/foto_profil_tenant/6513d6839a417.png', 'OMAH DELAFEMME', 'MAYA KARTIKA AYU EKA NUGRAHA', 19, 1, 'Jalan karyawan no.330 RT.10/RW.04 Tumpang', NULL, '120.000.000,00', 'INSTAGRAM, WHATSAPP BUSINESS', 'EKSPOR', 'EXCEL', '<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Seluruh produk omah delafemme fokus pada tehnik beading (seni payet), dari aksesoris, souvenir dan perlengkapan homedekor.  Pembuatan nya masih manual membutuhkan ketelitian pengerjaan. Seluruh desain adalah murni desain dari omah delafemme. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Seluruh produk omah delafemme fokus pada tehnik beading (seni payet), dari aksesoris, souvenir dan perlengkapan homedekor. Pembuatan nya masih manual membutuhkan ketelitian pengerjaan. Seluruh desain adalah murni desain dari omah delafemme.</span><br></p>', '2023-05-11', '2023-05-11', '2023-09-27 14:15:15', '2023-09-27 14:15:15');
INSERT INTO `tenant` VALUES (2404, 134, 'public/foto_profil_tenant/6572708f49ff7.jpg', 'Barlocaatha Handmade', 'Atha', 26, 1, 'Jl.bendungan jago rt/rw 004/001 utan kayu panjang Kemayoran\r\nJakpus', NULL, '5.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Design yg otentik dn original dengan material kain khas Indonesia<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 09:16:39', '2023-12-08 08:25:35');
INSERT INTO `tenant` VALUES (2405, 134, 'public/foto_profil_tenant/6571785b939bf.jpeg', 'Rosse Ethnic', 'Dian Damayanti', 26, 1, 'Telaga Golf. Nuansa Bali A9 no 7, rt 001/008 Sawangan Depok Jabar', NULL, '50.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Sandal sepatu nyaman dengan sol yg empuk. Dengan bahan material\r\nkain khas indonesia an juga ada tambahan aksen bordir membuat\r\nproduk berciri khas Indonesia.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 09:24:04', '2023-12-07 14:46:35');
INSERT INTO `tenant` VALUES (2406, 134, 'public/foto_profil_tenant/657174c03b565.jpeg', 'Sloopie Handmade', 'Ervina', 26, 1, 'Metro Permata 1, Blok K3 No.1, rt 001/005 Parung Jaya, Karang Tengah, Tangerang Banten', NULL, '8.500.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Sloopie Handmade membuat tas handmade yang berbasis kanvas,\r\ndibuat secara fashionable dan model terbatas agar terlihat unik.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 09:41:07', '2024-07-30 15:03:49');
INSERT INTO `tenant` VALUES (2407, 134, 'public/foto_profil_tenant/657178926ddf0.jpeg', 'Wienacraft', 'Erwina', 26, 1, 'Jl. Jati makmur no 61 C rt 02/09 Pondok gede Bekasi, Jawa Barat', NULL, '100.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Produk wienacraft menghasilkan produk yg unik dan bernilai seni yg\r\ntinggi serta berbahan ramah lingkungan. Wienacraft menggunakan\r\nserat alam di dukung pewarna alam dan serta dedaunan dan bunga\r\nyg di ambil dr lingkungan sekitar tanpa merusak tanaman itu\r\nsendiri.dengan cara menanam kembali utk melestarikan nya.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 09:46:27', '2024-07-30 15:09:46');
INSERT INTO `tenant` VALUES (2408, 134, 'public/foto_profil_tenant/657271b131552.jpeg', 'CV Ridaka', 'Ibrahim A Kadir NIK', 26, 1, 'Jln H Agus Salim, Klego 6/4, rt02/04, Klego, Pekalongan Jawa Tengah', NULL, '50.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Semua produk kami terbuat dari bahan-bahan alam, ramah\r\nlingkungan, zero waste, handmade by women and local artisans<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 09:55:08', '2023-12-08 08:30:25');
INSERT INTO `tenant` VALUES (2409, 134, 'public/foto_profil_tenant/65716ffe4205d.jpeg', 'EXOBROOCH', 'Ika Bunga Maharani', 26, 1, 'Perum Jatijajar blok a25 no 3 Tapos Depok, rt 007/010 Jawa Barat', NULL, '34.000.000,00', 'Instagram', 'Dalam Negeri', 'Aplikasi', '<p>Exobrooch bermula dari singkatan dari exotic brooch, yang mewakili\r\nkeunikan karya dengan produk awal wirebrooch dengan mengambil\r\nkonsep bentuk dasar geometri. Kemudian kami melebarkan usaha ke\r\ndunia fashion dengan produk custom, modest muslim wear, kids wear\r\ndan mukena. Exobrooch telah mendapatkan sertifikat HAKI dan\r\nbeberapa penghargaan antara lain dari Dies Natalis Arsitektur ITS ke50 2015, Scale Up Femina X Facebook 2021, Entrepreneurs Class\r\nFEUI x BSI 2021, Uniqlo Neighborhood 2022 dan Depok Fashion\r\nFestival 2022 Disdagin Kota Depok - Dekranasda. Pemasaran produk\r\nmelalui beberapa e-commerce Indonesia hingga mancanegara\r\nmelalui Indonesia in Your Hand. Saat ini Exobrooch sedang\r\nmeluncurkan program Collab Project dengan workshop dan runway di\r\nbeberapa event. Karena kami yakin bahwa setiap dari kita memiliki\r\npotensi berkarya dan saling memberi manfaat semakin berarti.\r\nExobrooch, Extraordinary Creation, Extraordinary You<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:09:39', '2024-07-30 15:03:04');
INSERT INTO `tenant` VALUES (2410, 134, 'public/foto_profil_tenant/657273afb391a.jpg', 'Intan\'s Craf', 'Intan Rachmawati', 26, 1, 'Jl.Rs.Fatmawati No. 20. Rt 06 Rw 03. Cilandak 12430.Jakarta Selatan', NULL, '5.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Membuat tas handmade dan handycraft dengan berbagai macam\r\nmodel dan motif. Dari framed bag, speedy bag dari bahan songket,\r\nbucket hat, tempat tissue dll. Aku sebisa mungkin berusaha utk zero\r\nwaste, bahan yg tersisa (perca/sisa kain) tidak ada yang dibuang\r\ndiproduksi lagi menjadi tas perca, taplak meja dll.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:15:31', '2024-07-30 10:37:56');
INSERT INTO `tenant` VALUES (2411, 134, 'public/foto_profil_tenant/657272b2ae822.jpeg', 'disable corner', 'Maria Ulfah', 26, 1, 'Jl. Makmur No. 37 RT 004/03 Kebayoran Lama Jakarta Selatan', NULL, '3.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Produk kami merupakan hasil karya dari teman-teman disabilitas<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:19:44', '2023-12-08 08:34:42');
INSERT INTO `tenant` VALUES (2412, 134, 'public/foto_profil_tenant/65717da1695a1.jpeg', 'PT Oemah Mega Quanza', 'Megawati Rachman', 26, 1, 'JL. CIKARET NO.60 RT.003 RW.011 CIKARET BOGOR SELATAN, JAWA BARAT', NULL, '567.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Penggunaan kain tenun batik yang melapisi pita plastik atau plastik\r\nmika menjadi anyaman, produk yang dihasilkan bisa berupa\r\nkeranjang, tas atau hiasan dinding<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:22:30', '2024-07-30 15:11:27');
INSERT INTO `tenant` VALUES (2413, 134, 'public/foto_profil_tenant/6571762507572.jpeg', 'Rumah Rajut Syafir', 'Mita Sari Dewi', 26, 1, 'Jorong kapalo koto nagari koto laweh kecamatan sepuluh koto\r\nkabupaten tanah datar provinsi sumatera barat, 27151', NULL, '105.500.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Produk-produk rajutan asli handmade di buat oleh tangan-tangan\r\ntrampil dan terbuat dari benang-benang berkualitas, produk tahan\r\nlama, bisa order sesuai selera customers.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:32:21', '2024-07-30 14:50:21');
INSERT INTO `tenant` VALUES (2414, 134, 'public/foto_profil_tenant/657189e0be766.jpeg', 'Pujil laku', 'Rahmi faddilah', 26, 1, 'Kp. citeko Rt 001/003, des. Citeko, Kec. Cisarua, Kab. Bogor, Jawa Barat', NULL, '20.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Memanfaatkan waktu luang di toko sambil menyulam.dan Bisa\r\nmenambah lapangan pekerjaan dan pendapatan untuk ibu-ibu sekitar\r\nlingkungan.dan pemanfaatan sisa kain perca agar mengurangi limbah\r\nkain.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:35:05', '2024-07-30 15:02:21');
INSERT INTO `tenant` VALUES (2415, 134, 'public/foto_profil_tenant/65717aaf0e900.png', 'Paduzzeecraft', 'Siera Eka Sukma', 26, 1, 'Legenda wisata no S12/28, rt 001/019, Nagrak, Gunung Putri, Bogor, Jawa Barat', NULL, '105.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Manual', '<p>Produk artisan tas wanita berbahan kain nusantara, minimal ada 2\r\njenis kain dari etnik berbeda yang dikombinasikan dengan\r\nkulitvsapinaslindan serat alami. Dibuat secara handmade dan bekerja\r\nsama dengan perempuan disekitar workshop dalam memanfaatkan\r\nperca wastra untuk diolah menjadi aksesoris dan suvenir, sejalan\r\ndengan misi Paduzzee dalam pemberdayaan perempuan dan zero\r\nwste production<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:40:39', '2024-07-30 15:08:08');
INSERT INTO `tenant` VALUES (2416, 134, 'public/foto_profil_tenant/65717e8602ee6.jpeg', 'Omah Aksesoris Batik', 'Siswo Iriantono', 26, 1, 'Jl. Danau Matana D II No.12, rt 013/004, Bendungan Hilir, Tanah Abang,Jakarta Pusat', NULL, '10.000.000,00', NULL, 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Home Industri Handmade Aksesoris Etnik Wanita Kombinasi Kain\r\nTenun Nusantara, Batik, Lurik, dsb dikombinasikan dengan Pendant\r\nAsli Pengrajin Perak Lokal Dalam Negeri<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:42:18', '2023-12-07 15:12:54');
INSERT INTO `tenant` VALUES (2417, 134, 'public/foto_profil_tenant/657273f1e6286.png', 'Eccello', 'Sri Rahayu', 26, 1, 'Jl.Majapahit Kp.Sembung Rt.005/Rw.006 Cikokol-Tangerang 15117\r\nBanten.', NULL, '10.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Sepatu sport/sneakers dengan bahan/motif Batik/Tenun Indonesia.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:45:02', '2023-12-08 08:40:01');
INSERT INTO `tenant` VALUES (2418, 134, 'public/foto_profil_tenant/65717afc726ba.jpeg', 'YORIHAN', 'Sri Yusriyati', 26, 1, 'Perumahan Cipondoh Makmur Blok B Vb no 8 RT 04 RW 04\r\nKelurahan Cipondoh Makmur Kecamatan Cipondoh Kota Tangerang\r\nProvinsi Banten', NULL, '15.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Saya membuat produk Tas seperti Slingbag, Totebag, Tas Ransel,\r\nPouch, Rope Bowl, Rope plate, Origami box, scrunchies, bandana,\r\ngantungan kunci, aksesoris, selain membuat produk sesuai selera\r\npasar, produk saya dibuat dengan jahitan yang rapi dan kuat\r\nterkadang ditambah dengan aplikasi sulam sesuai permintaan\r\nCustomer. Saat ini saya sedang mengikuti bazar di Living world\r\nbersama komunitas OTang sejak bulan September 2022, serta selalu\r\ningin belajar agar usaha saya terus berkembang. Saya juga\r\nmenerima jasa membuat baju pesta, baju anak, baju gamis, jilbab\r\ninstan. Saya juga memproduksi celana panjang cingkrang, baju anak,\r\nbaju gamis.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 10:57:12', '2024-07-30 10:40:34');
INSERT INTO `tenant` VALUES (2419, 134, 'public/foto_profil_tenant/65717b184698e.jpeg', 'Zante', 'Susy Darmayanti', 26, 1, 'Jl Loka Indah No 5, rt 12/04, Kalibata, Pancoran, Jakarta Selatan', NULL, '12.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Meningkatkan nilai anyaman asli Indonesia dg mengkombinasikan\r\nbahan kulit asli sisa<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 11:01:05', '2024-07-30 14:48:31');
INSERT INTO `tenant` VALUES (2420, 134, 'public/foto_profil_tenant/65717a8a9afcc.jpeg', 'Miyshaide', 'Vita Suci Rahayu', 26, 1, 'Jl. Anjasmoro VI NO 17 rt 04/06 Kel. Bugullor Kec. Panggungrejo Kota Pasuruan 67122', NULL, '30.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Kami mempunyai puluhan tenaga penyulam, penjahit, pembordir,\r\nyang sudah berpengalaman produksi selama 4 tahun. Kami\r\nmempunyai lebih dari 100 SKU produk mulai dari fashion,\r\nperlengkapan sholat, dan home decor. Beberapa produk kami pernah\r\nmenjadi produk terlaris nomor 3 di shopee untuk mukena. Kami siap\r\nmemperbanyak tenaga penyulam jika ada permintaan order yang\r\nlebih besar.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 11:03:44', '2024-07-30 15:07:32');
INSERT INTO `tenant` VALUES (2421, 134, 'public/foto_profil_tenant/65717dda534d5.jpeg', 'Dya by_widya', 'Widya', 26, 1, 'Jl Cibubur III no.87, rt 011/001, Ciracas, Jakarta Timur, DKI Jakarta', NULL, '35.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Manual', '<p>Fashion &amp; aksesoris etnik modern Nusantara<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 11:06:27', '2024-07-30 15:06:36');
INSERT INTO `tenant` VALUES (2422, 134, 'public/foto_profil_tenant/65717adc961fb.jpeg', 'Trigi Homedecor', 'laksono wiby prayoga', 26, 1, 'Ds bojong indah rt005/002 Parung - bogor, Jawa Barat', NULL, '220.000.000,00', 'Instagram', 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Walldecor untuk mempercantik ruangan -menggunakan bahan\r\nplywood 3 dan 6mm -pernish waterbase ramah lingkungan<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 11:08:30', '2024-07-29 15:20:53');
INSERT INTO `tenant` VALUES (2423, 134, 'public/foto_profil_tenant/657278a4a74f2.jpeg', 'NUNKY BOUTIQUE', 'Yeti kusmayanti', 26, 1, 'The green cluster venetian C10/7 Bsd City, rt 019/007, Cilenggang, Serpong, Tangerang Selatan, Banten', NULL, '70.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Fashion dengan bahan ramah lingkungan</p>', '2023-03-06', '2023-09-01', '2023-10-02 11:11:48', '2024-07-30 15:09:10');
INSERT INTO `tenant` VALUES (2424, 134, 'public/foto_profil_tenant/657298ab59e00.jpeg', 'Koto batu', 'Yulianti Mayang', 26, 1, 'Jl.Kejaksaan I No.5, rt 03/06, Kreo Larangan Tangerang Banten', NULL, '10.000.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Koto batu merupakan brand aksesoris handmade yang dibuat\r\nlangsung oleh lokal artisan dengan fokus material batu alam dan\r\nserat alam lainnya seperti bambu &amp; biji jenitri. Tiap desain yang\r\ndihasilkan terbatas jumlahnya sehingga menimbulkan rasa\r\nkekhususan bagi yang menggunakannya. Kami percaya bahwa tiap\r\nbatu dan material alam yang digunakan memiliki manfaat positif ketika\r\ndigunakan oleh manusia.<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 13:34:53', '2024-07-30 15:10:53');
INSERT INTO `tenant` VALUES (2425, 134, 'public/foto_profil_tenant/657189fbe467c.jpeg', 'WIEK\'S Craft', 'Yuniar sri widarwati', 26, 1, 'Jl. Semboja 9 Malang, rt 07/09, Lowokwaru Malang Jakarta Timur', NULL, '2.500.000,00', 'Instagram', 'Dalam Negeri', 'Manual', '<p>Berbahan dasar kain perca dgn desain unik dgn kombinasi\r\nketrampilan sulam tangan<br></p>', '2023-03-06', '2023-09-01', '2023-10-02 13:36:59', '2023-12-07 16:01:47');
