INSERT INTO `tenant` VALUES (2433, 450, 'public/foto_profil_tenant/652cef6d7dc25.jpeg', 'Koperasi Tunas Usaha Sejahtera', 'Muhammad Hatta', 4, NULL, 'Jl. Banda Aceh - Calang Km. 57 Desa Pasie Kec. Lhoong Kab. Aceh Besar Prov. Aceh', NULL, '50.000.000,00', 'Penjualan Lansung', 'Aceh Besar dan Sekitarnya', 'Digital', '<p style=\"text-align: left; margin: 0cm 0cm 0cm 13px; font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); line-height: 24px;\"><span style=\"font-family: Helvetica;\">Koperasi Tunas Usaha Sejahtera berbasis di Aceh Besar hadir dan bergerak dalam sektor kelautan dan perikanan. Koperasi Tunas Usaha Sejahtera bertujuan untuk mengembangkan sektor kelautan dan perikanan Kawasan Kecamatan Peukan Bada, Lhoknga, Lhong dan Leupung,</span></p><p style=\"text-align: left; margin: 0cm 0cm 0cm 13px; font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); line-height: 24px;\"><span style=\"font-family: Helvetica;\"><br></span><span style=\"font-family: Helvetica; font-size: 12pt;\">Koperasi berfokus pada penjualan minyak solar bersubsidi, produksi garam,&nbsp; budidaya laut, pengolahan ikan, dan pemasaran produk-produk perikanan.</span></p><p class=\"MsoListParagraph\" style=\"margin: 6.9pt 0cm 0cm 168.9pt; text-indent: -168.9pt; font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); line-height: 24px; border: none;\"><span style=\"font-family: Helvetica; font-size: 12pt; text-indent: -168.9pt;\">&nbsp; &nbsp;Tujuan Pendampingan</span><br></p><h1 align=\"left\" style=\"margin: 0cm 210.5pt 0.0001pt 0cm; font-size: 11.5pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); line-height: 23px;\"><span style=\"font-size: 11pt; line-height: 22px; font-family: Helvetica;\">&nbsp;</span></h1><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 0cm 38px; font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); text-inde