INSERT INTO `tenant` VALUES (2726, 484, NULL, 'Laku - Lampah Ghaisan', 'Siti Fatimah', 23, NULL, 'Link. Ciriu RT/RW 01/06 Kelurahan Samang Raya Kecamatan Citangkill Kota Cilegon', NULL, '2.000.000,00', 'Online Shop', 'Cilegon dan Serang', 'Pendapatan dan Pengeluaran Lewat Buku Harian', '<p>Mulai berdiri : 12 Juli 2017</p><p>Produk yang dijual : makanan ringan, gipang dan gegetas</p><p>Pemasaran : Melalui Whatsapp dan media sosial lainnya.</p>', '2024-02-16', '2024-06-30', '2023-11-30 10:11:05', '2024-03-20 08:01:29');
INSERT INTO `tenant` VALUES (2728, 484, NULL, 'Snack Galipat  (354)', 'Diah Nur Aini', 23, NULL, 'Link. Sumur Bambu RT/RW 04/07', NULL, '500.000,00', 'Whatsapp dan Facebook', 'Merak, Cilegon dan Serang', 'Di Buku', '<p>Snack Galipat (354) berdiri pada tahun 2009/2010 yang diawali oleh Ibu saya. Lalu saya melanjutkan usahanya sejak akhir tahun 2021, karena ibu saya meninggal dan usaha ini masih tetap berjalan hingga saat ini.&nbsp;</p><p>Produk - produk dari Snack Gaupay (354) diantaranya yaitu Keripik Talas, Keripik Pisang, Kentang Mustofa, Peyek, dll.</p><p>Selain itu kami juga menyediakan kue basah dan nasi kotak.</p>', NULL, NULL, '2023-11-30 10:26:07', '2023-11-30 16:48:02');
INSERT INTO `tenant` VALUES (2729, 484, NULL, 'Cokeis Bunda R & A', 'Merlin Diana', 23, NULL, 'Perumahan Grand Sutera Blok F No. 25', NULL, '5.000.000,00', 'Whatsapp, Tiktok dan Secara Langsung', 'Online, Offline, dan Tetangga Sekitar Area Cilegon - Merak', 'Pencatatan Pembiayaan, Pengeluaran dan Pengeluaran Pendapatan di Buku', '<p>Kue Kering : Nastar, Kastangel, Putri Salju, Nastar Cokelat, Telur Gabus, Sagu Keju, Chocostik Coklat.</p><p>Berdiri sejak tahun 2014 hingga saat ini. Penjualan sudah lumayan banyak pelanggan di sekitar seperti teman dan pada media sosial.</p>', NULL, NULL, '2023-11-30 10:38:56', '2023-11-30 10:38:56');
INSERT INTO `tenant` VALUES (2730, 484, NULL, 'ELlovers Kitchen', 'Iin Mayasari', 23, NULL, 'Link. Kependilan Baru No. 25 RT/RW 004/001 Kel. Panggung Rawi, Kec. Jombang 42412', NULL, '1.000.000,00', 'Whatsapp, Menitipkan di Lapak Kue dan Secara Langsung', 'Ibu Rumah Tangga, Instansi Pemerintah (Cilegon), dan Kantor', 'Buku dan Rekening', '<p>Ellovers Kitchen berdiri dari 25 Februari 2016, berawal dari iseng bikin bolu rainbow lalu di uppload pada status whatsapp dan ternyata ada yang berminat. Lalu mencoba menitipkan pada salah satu toko kue di Cilegon dan sampai sekarang masih menjual berbagai macam kue basah (Bisa Request), baik jual langsung maupun dititipkan di lapak kue. Untuk saat ini menjadi venndor salah satu rumah sakit di Cilegon.&nbsp;</p>', NULL, NULL, '2023-11-30 10:54:07', '2023-11-30 10:54:07');
INSERT INTO `tenant` VALUES (2731, 484, NULL, 'Dapoer Hanah', 'Nur Hasanah', 23, NULL, 'Komp. TWI FWA 79B NO. 05 RT/RW 02/05 Kel. Warnasari Kec. Citangkil Kota Cilegon Banten', NULL, '1.000.000,00', 'Sosial Media', 'Masyarakat Umum', 'Di Buku', '<p>Awal berdiri tahun 2017</p><p>- Kue Basah dan Nasi Box&nbsp;</p><p>- Roti Pisang Keju dan Aneka Bolu&nbsp;</p><p>- Sambel Pecel</p>', NULL, NULL, '2023-11-30 11:10:16', '2023-11-30 11:10:16');
