INSERT INTO `tenant` VALUES (2758, 484, NULL, 'Ayam Bakar Manis UGA', 'Yeni Susanti', 23, 2, 'Link. Penyairan Baru No. 2', NULL, '3.000.000,00', 'Whatsapp dan Secara Langsung', 'Cilegon dan Serang', 'Di Buku', '<p>Kuliner, Ayam Bakar, Aneka Kripik Buah dan Sayur.</p><p>Berdiri sejak tahun 2019</p>', NULL, NULL, '2023-11-30 12:59:47', '2023-12-03 11:18:44');
INSERT INTO `tenant` VALUES (2759, 484, NULL, 'Jananan Teh Ida', 'Siti Jumaidah', 23, NULL, 'Link. Serang Baru RT/RW 04/08Kel. Kota Bumi Kec. Purwakarta', NULL, '3.000.000,00', 'Oflline dan Media Sosial (Online)', 'Sekitar Rumah', NULL, '<p>Beridiri dari 2010 Saya Merintis usaha dari berjualan berbagai es serbuk seperti es teajus, jasjus, nutrisari, pop ice dan berbagai jajanan seperti ciki.</p><p>Lalu saya berinovasi dari yang awalnya hanya bermodal meja, termos dan teko sekarang sudah bisa membuat warung kecil-kecilan yang isinya juga ditambah sembako. Disamping itu saya juga mempunyai usaha rumahan yang saya olah sendiri yaitu keripik singkong, makaroni, kue basah dan berbagai gorengan. Hingga sekarang mempunyai stan untuk jualan dari hari Rabu dan hari Sabtu.</p>', NULL, NULL, '2023-11-30 13:21:59', '2023-11-30 13:21:59');
INSERT INTO `tenant` VALUES (2760, 484, NULL, 'Banana King', 'Seviana Dwi Farahayu', 23, NULL, 'Perumahan Cilegon Islamic Village C2 No. 16 Ciwedus Kali Kalong', NULL, '2.000.000,00', 'Whatsapp (reseller)', 'Kantin sekolah dan Warung terdekat sekitar Cilegon', 'Di Buku', '<p>Menjual Kue Basah dan Keripik dengan logo Banana King dan Dapur Nona berdiri sejak tahun 2019 hingga saat ini, dan bisa didapatkan di warung, kantin sekolah serta dapat di order melalui whatsapp.</p>', NULL, NULL, '2023-11-30 13:28:48', '2023-11-30 13:28:48');
INSERT INTO `tenant` VALUES (2761, 484, NULL, 'Toko Dwi Indah Collection Love Snack Cemilan Enak', 'Dewi Cahya Ningsih', NULL, NULL, 'Pasar Kelapa Blok D No. 9 Ciwaduk Kota Cilegon', NULL, '3.500.000,00', 'Instagram, Facebook, dan Market Place', 'Lokal, para pembeli di pasar, Koperasi Sekolah, Koperasi Kantor', 'Di Buku Pendapatan dan Pengeluaran', '<p>- Menjual baju atasan dan berbagai macam aksesoris seperti kerudung, bahan, dll</p><p>- Konveksi menjahit seragam sekolah, seragam kerja, dll</p><p>- Menjual makanan ringan pastel mini kering isi abon love snack cemilan enak</p>', NULL, NULL, '2023-11-30 13:35:56', '2023-11-30 13:35:56');
INSERT INTO `tenant` VALUES (2762, 484, NULL, 'Kawung LDK', 'Binur Hayati', 23, 2, 'Link. Duku Malang RT/RW 016/004 Kwl. Tegal Bunder Kec. Purwakarta Cilegon', NULL, '10.000.000,00', 'Whatsapp, Toko Pedia, dan Shopee', 'Direct Selling (Royale Krakatau, Koperasi KIEC, Koperasi KWT, Koperasi KDL, Bintang Swalayan, Bebek Mbak Dwi, dan Warung Sayur', 'Buku dan Rekening', '<p>Berdiri mulai Januari 2023&nbsp;</p><p>Produk : Gula Aren Semot, Gula Aren Cair, Gula Aren Batok (distributor).</p><p>Memproduksi sendiri : kacang kribo gula aren, bimbing wuluh gula aren.</p>', '2023-11-01', '2024-06-28', '2023-11-30 13:41:50', '2024-02-25 19:54:06');
