INSERT INTO `tenant` VALUES (2871, 18, NULL, 'Koperasi Tegal Manufaktur Indonesia', 'Koperasi Tegal Manufaktur Indonesia', 11, 4, 'Komplek LIK Takaru , Jalan Raya Dampyak KM4 ,Kel Dampyak, Kec Kramat , Kab Tegal\r\nKAB. TEGAL , Prov. JAWA TENGAH', NULL, NULL, NULL, NULL, NULL, '<p>Koperasi Manufaktur Tegal Indonesia merupakan koperasi gabungan dari 24 pengusaha logam Tegal yang berdiri sejak tahun 2018. Saat ini mempunyai unit usaha bernama material center dengan 5 bidang usaha yang meliputi consumable, jasa logistik, jasa permesinan, perdagangan produk dan penyedia material logam. UKM</p><p>​</p>', '2022-03-07', '2022-03-07', '2023-12-06 17:22:27', '2023-12-06 17:22:27');
