INSERT INTO `tenant` VALUES (2884, 18, NULL, 'Lumbung Bumi Dharmaputra', 'Achmad Jazuri', 40, 2, 'Jl.Limbangan sumowono km 7,Nambangan , Ds Gondang kec. limbangan kab.Kendal', NULL, '5.000.000,00', 'Instagram, dll', 'Lokal', NULL, '<p>dagang sayur sayuran&nbsp;</p>', '2023-01-04', '2024-12-31', '2023-12-06 18:14:17', '2023-12-06 18:14:17');
INSERT INTO `tenant` VALUES (2885, 100, 'public/foto_profil_tenant/657124e57bf6f.jpeg', 'Capli', 'Yuliana, S.Kom', 23, 2, 'Desa Blang Oi Kecamatan Meuraxa, Kota Banda Aceh', NULL, '400.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Capli Sambal Rawit Hijau Aceh is a typical Acehnese Chili Sauce processed using 60% original cayenne pepper taken directly from Aceh Farmers and combined with asam sunti (fermented wuluh starfruit) which functions as a flavor enhacer, thickener, preservative and acidifier do as to create a distinctive cayenne chili sauce flavor from Aceh</p>', '2021-02-01', '2021-02-01', '2023-12-07 08:50:29', '2023-12-07 08:50:29');
INSERT INTO `tenant` VALUES (2886, 100, 'public/foto_profil_tenant/657126507ba5c.jpg', 'Aslam Atjeh', 'M. Sulaiman', 23, 2, 'Lamteuba, Kabupaten Aceh Besar', NULL, '130.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Aslam Atjeh merupakan usaha yang menghasilkan bumbu kunyit siap pakai (instan). Aslam Atjeh dalam sepak terjangnya usahanya juga melakukan pemberdayaan kepada petani-petani kunyit di desa Lamteuba dan tentunya juga menjadi salah satu penggerak ekonomi petani kunyit. Aslam Atjeh kini juga telah melakukan inovasi produk berupa kopi kunyit yang memiliki banyak khasiat untuk kesehatan.&nbsp;&nbsp;</p>', '2021-02-01', '2021-11-30', '2023-12-07 08:56:32', '2023-12-07 08:56:32');
INSERT INTO `tenant` VALUES (2887, 100, 'public/foto_profil_tenant/6571284f5c2ce.jpg', 'Abon Ikan Tuna Aroma Food', 'Taufik Gunawan', 23, 2, 'Desa Ulee Pata Kecamatan Jaya Baru, Kota Banda Aceh', NULL, '115.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Abon Ikan Tuna Aroma Food merupakan usaha yang menghasilkan produk olahan makanan siap saji yakni berbahan dasar ikan tuna. Ide dari terbentuknya usaha ini yaitu keresahan owner melihat banyak sekali ikan-ikan tuna yang busuk dan di buang ke laut karena basi dan tidak terjual, padahal tangkapan nelayan di Aceh melimpah. meluhat permasalahan itu owner beinisiatif membuat olahan makanan yang tahan lama, sehat, dan bergizi tentunya. Semenjak berjalannya usaha ini para nelayan merasa sangat terbantu karena hasil tangkapannya ada yang menampung baik dalam jumlah kecil maupun besar. Sehingga dalam hal ini tidak ada ikan yang terbuang secara percuma dan tentunya dapat meningkatkan perekonomian para nelayan di Aceh.<br></p>', '2021-02-01', '2021-11-30', '2023-12-07 09:05:03', '2023-12-07 09:05:03');
INSERT INTO `tenant` VALUES (2888, 100, 'public/foto_profil_tenant/65712a20aced3.jpeg', 'Coconite Teeth Whitening', 'Agung Wiranto', 25, 2, 'Desa Lampeuneurut, Kabupaten Aceh Besar', NULL, '105.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Coconite Teeth Whitening merupakan perusahaan yang menghasilkan produk pemutih gigi yang memiliki kandungan Virgin Coconut Oil (VCO) dan actived charcoal dari hasil pembakaran kelapa. Visi perusahan ini yaitu menghasilkan produk kesehatan sehari-hari yang menggunakan bahan baku alami yang diperoleh dari masyarakat lokal Aceh.<br></p>', '2021-02-01', '2021-11-30', '2023-12-07 09:12:48', '2023-12-07 09:12:48');
INSERT INTO `tenant` VALUES (2889, 100, 'public/foto_profil_tenant/65712ccee469e.png', 'Bili Droe', 'Ulfa Fithria', 15, 2, 'Desa Lampanah Tunong kecamatan Indrapuri, Kabupaten Aceh Besar', NULL, '95.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional dan Internasional', 'Sudah Teratur', '<p>Bili comes fromthe Acehnese language which means a plant called bemban or bamban (Donax Canniformis). This plant is a type of shrub of herbaceous plant. Raw Materials for bili fronds are obtained from the mountains around Lampanag teunong Village. We produce a wide range of woven products such as serving lids, tote bags, wallets, baskets, fishpans, flower vases and others.</p>', '2023-04-12', '2023-09-05', '2023-12-07 09:24:14', '2023-12-07 09:24:14');
INSERT INTO `tenant` VALUES (2890, 100, 'public/foto_profil_tenant/65712e062c37c.jpeg', 'Cil Food', 'Teuku Muammar Whadafi Tuwasza, SE', 23, 2, 'Desa Blang Oi Kecamatan Meuraxa, Kota Banda Aceh', NULL, '150.000.000,00', 'Instagram, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Cil Food is a business that produces ready-to-eat dry food as a complement to the main meal. One of Cil Food\'s flagship products is Abon Keumamah, which is Abon Tuna Fish that is specially mixed using Acehnese Keumamah seasoning so that it has its distinctive taste. Other Cil Food products are coconut serundeng, mini crispy shrimp, Chicken Egg Roll, and Tuna Egg Roll</p>', '2023-04-12', '2023-09-05', '2023-12-07 09:29:26', '2023-12-07 09:29:26');
INSERT INTO `tenant` VALUES (2891, 100, 'public/foto_profil_tenant/65712fa9ac03d.jpg', 'Bandeng Presto Mama Kembar', 'Ellena Efda', 23, 2, 'Desa Landom kecamatan Lueng Bata, kota Banda Aceh', NULL, '120.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional dan Internasional', 'Sudah Teratur', '<p>Bandeng Presto is a food made from fresh fish products that are processed with high temperature pressure and a long time to produce fish that is tender to the bone. Blended with Acehnese spices, it produces presto milkfish with a distinctive Acehnese flavor and complements Indonesia\'s culinary diversity.</p>', '2023-04-12', '2023-09-05', '2023-12-07 09:36:25', '2023-12-07 09:36:25');
INSERT INTO `tenant` VALUES (2892, 100, 'public/foto_profil_tenant/65713101bea7e.jpg', 'Krips Chips', 'Wahyu Aulia', 23, 2, 'Desa Lampoh Daya kecamatan Jaya Baru, kota Banda Aceh', NULL, '280.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional dan Internasional', 'Sudah Teratur', '<p>Krips Chips is a banana chips snack with flavor variants made from local Acehnese organic kepok bananas that are kept authentic and then combined with secret spices without using causative ingredients to create healthy and quality banana chips. Since 2018 Krips Chips has always improved quality and made innovations, one of our real innovations is creating chocolate bars with banana chips inside.</p>', '2023-04-12', '2023-09-05', '2023-12-07 09:42:09', '2023-12-07 09:42:09');
INSERT INTO `tenant` VALUES (2893, 100, 'public/foto_profil_tenant/657132f1dd15e.jpeg', 'Neelam Geutanyoe', 'Muhammad haiqal, S.Sos', 12, 2, 'Keutapang Sanggeue, Kabupaten Pidide', NULL, '59.000.000,00', 'Instagram, Facebook, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Neelam Geutanyoe is a potential business that prioritizes pure Acehnese patchouli raw materials, which are then processed into raw materials for making typical Acehnese perfume. 14 variants of aroma from Neela Geutanyie perfume with 4 best series. Neelam Geutanyoe perfume has received awards and appreciations from various institutions and figures.</p>', '2023-04-12', '2023-09-05', '2023-12-07 09:50:25', '2023-12-07 09:50:25');
INSERT INTO `tenant` VALUES (2894, 100, 'public/foto_profil_tenant/6571356d90629.jpeg', 'Neng Food', 'Neneng Afriya Ningsih', 23, 2, 'Desa Cot irie Kecamatan Ulee Kareng, Kota Banda Aceh', NULL, '50.000.000,00', 'Instagram, Tiktok', 'Nasional', 'Sudah Teratur', '<p>Neng Food is a food brand that has been established since 2015. The products produced by Neng Food are peanut peyek, potato, and cassava saw chips. One of Neng Food\'s mainstay products is peanut peyek. Neng food snacks can be enjoyed anytime and anywhere.</p>', '2023-04-12', '2023-09-05', '2023-12-07 10:01:01', '2023-12-07 10:01:01');
INSERT INTO `tenant` VALUES (2895, 100, 'public/foto_profil_tenant/657138f9d2846.png', 'Beydara', 'Sayed Ludhfi', 25, 2, 'Desa Lamteumen Timur Kecamatan Jaya Baru, Kota Banda Aceh', NULL, '75.000.000,00', 'Instagram, Tiktok', 'Nasional', 'Sudah Teratur', 'Beydara Pill Herbal Medicine is one of the products that has been used for generations by Acehnese women in treating and treating feminine problems such as cysts, myomas, vaginal discharge, can tighten the muscle of the womanhood for mother after childbirth, can remove dirt in the miss V area and many other properties. The advantage of Beydara pills is that they can be used by ghurah (inserting beydara pills into the miss V) so that the healing process is faster because the use of drugs directly to the target center of the disease.', '2023-04-12', '2023-09-05', '2023-12-07 10:16:09', '2023-12-07 10:16:09');
INSERT INTO `tenant` VALUES (2896, 478, 'public/foto_profil_tenant/6571413202255.jpg', 'PT. Cita Indonesia Bersih (Cleansheet)', 'Dihqon Nadaamist', 32, 5, 'Jl Taman Cimanggu Tengah U2/9 Kota Bogor', NULL, '35.000.000,00', 'Sosmed', 'Lokal', 'Sistem', '<p>Layanan jasa kebersihan dan platform (aplikasi layanan jasa kebersihan)<br></p>', '2023-06-06', '2023-06-06', '2023-12-07 10:51:14', '2023-12-07 10:51:14');
INSERT INTO `tenant` VALUES (2897, 18, NULL, 'Homie Geprek', 'Wendy', 23, NULL, 'Sekaran, Gunungpati Semarang', NULL, '300.000.000,00', 'Instagram, dll', 'Lokal dan Nasional', NULL, '<p>Bergerak dibidang makanan dan minuman dengan sambal fresh&nbsp;</p>', '2020-01-01', '2022-12-31', '2023-12-07 10:54:46', '2023-12-07 10:54:46');
INSERT INTO `tenant` VALUES (2898, 478, 'public/foto_profil_tenant/65714300389dd.jpg', 'PT. Nectars Natura Karya', 'Ruri Prihatini Arimbi S.Si', 26, 2, 'Komplek Pertanian Jl. Penegak II No. 32 RT. 002 RW 10 Loji, Kec. Bogor Barat, Kota Bogor, Jawa Barat', NULL, '10.000.000,00', 'Sosmed', 'Nasional', 'Excel', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Skincare atau perawatan kesehatan kulit berbasis natural dan organik serta vegan. Bahan baku dari tanaman biodiversitas lokal yang cenderung melimpah dan endemik di negeri ini dengan kadar atioksidan tinggi serta mengusung nilai-nilai kearifan lokal. Kisaran harga Rp 100.000 hingga Rp 500.000 per produk. Diformulasi secara unik dan resep otentik khas artisan untuk mencitrakan ekslusivitas yang tinggi dalam sebuah industri kosmetik.</span><br></p>', '2023-06-06', '2023-06-06', '2023-12-07 10:58:56', '2023-12-07 10:58:56');
