INSERT INTO `tenant` VALUES (2974, 522, 'public/foto_profil_tenant/657bd62cd10a2.png', 'Dyslexia Kids', 'Donny Aggriawan', 19, 1, 'Kavling Larasati Village, Jl. Sadewa No.71, RT.03/RW.08, Patokan, Kec. Cimanggis, Kota Depok, Jawa Barat 16454', NULL, '100.000.000,00', 'Shopee', 'Nasional', NULL, NULL, '2023-05-22', '2023-09-22', '2023-12-15 11:23:53', '2025-02-20 10:13:21');
INSERT INTO `tenant` VALUES (2975, 522, 'public/foto_profil_tenant/657bd6383367a.jpg', 'Dahlia Batik Genturan', 'Eliana Tresnawati', 19, 1, 'Jl. Raya Sukabumi No.42, Cikaroya, Kec. Warungkondang, Kabupaten Cianjur, Jawa Barat 43261', NULL, '500.000.000,00', 'Whats App', 'Nasional', NULL, '<p><span style=\"caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Rumah Produksi Batik Khas Cianjur</span><br></p>', '2023-05-23', '2023-09-22', '2023-12-15 11:25:15', '2025-02-20 10:05:05');
INSERT INTO `tenant` VALUES (2976, 522, 'public/foto_profil_tenant/657bd6c9892d0.jpg', 'Cover SMC', 'Dani', 19, 5, 'Bogor, Jawa Barat', NULL, '1.000.000.000,00', 'https://sarungmobil.com', 'Nasional', NULL, '<p style=\"margin-bottom: 10px; border: medium; outline: currentcolor; position: relative; caret-color: rgb(41, 41, 41); color: rgb(41, 41, 41); font-family: &quot;Open Sans&quot;, sans-serif;\">Dewasa ini banyak produsen sarung mobil dan sarung motor yang memproduksi cover mobil / motor dengan kualitas yang belum teruji. Produsen-produsen tersebut biasanya menggunakan bahan-bahan dengan kualitas yang menurut kami tidak layak untuk dijadikan sebuah cover mobil dan cover motor. Mengapa kami bisa mengatakan seperti itu ? Dikarenakan banyak customer yang mengeluh kepada kami bahwa produk yang mereka beli secara online / offline tidak sesuai dengan harapan mereka. Biasanya kita banyak menemukan produk-produk tersebut dibandrol dengan harga kisaran Rp. 200.000 – Rp.350.000, memang harga yang mereka tawarkan sangat murah dan menggiurkan tetapi ketika melihat kualitas sebenarnya jauh dari apa yang kita harapkan.</p><p style=\"margin-bottom: 10px; border: medium; outline: currentcolor; position: relative; caret-color: rgb(41, 41, 41); color: rgb(41, 41, 41); font-family: &quot;Open Sans&quot;, sans-serif;\">Sarungmobil.com sendiri adalah sebuah solusi untuk segala permasalahan yang dihadapi pemilik kendaraan, kami adalah produsen yang berdomisili di Bogor. Workshop adalahj tempat kami berkreasi dan berproduksi, karena owner dari brand ini adalah seorang aktivis di bidang otomotif indonesia, sudah banyak prestasi dan trophy yang beliau hasilkan dari ikut sertanya dalam beberapa kejuaraan kontes mobil. Beliau adalah founder dari brand ini dan sudah bergelut di bidang cover mobil kurang lebih 6 tahun dan sudah memproduksi lebih dari 20.000 unit cover mobil.</p>', '2023-05-22', '2023-09-22', '2023-12-15 11:32:09', '2025-02-20 10:00:55');
