INSERT INTO `tenant` VALUES (2987, 36, 'public/foto_profil_tenant/657fa6c3eb96a.jpeg', 'CACIES', 'Abdurrohim', 23, NULL, 'Dsn. Gung gung Desa Perreng, Bumeh, Bangkalan', NULL, NULL, 'IG : instagram.com/ca.cies', NULL, NULL, '<p style=\"text-align: justify; \"><span style=\"font-family: &quot;Comic Sans MS&quot;;\">Cacies merupakan salah satu produk bakery yang digemari masyarakat, dan menggunakan tepung berbahan dasar cangkang telur ke dalam cookies yang merupakan cara terbaik untuk memanfaatkan sumber kalsium</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Comic Sans MS&quot;;\">Cangkang telur merupakan sampah rumah tangga sekaligus sampah industri pangayang memakai bahan baku cangkang telur Kandungan kalsium yang cukup tinggi tersebut sampai saat ini belum dimanfaatkan secara optimal. Kekurangan kalsium telah menjadi masalah yang umum dialami oleh masyarakat Indonesia. Melihat hal tersebut dan pentingnya kalsIum bagi masyarakat maka terbentuklah Cacies (Cookies tinggi kalsium )</span></p>', '2023-06-01', '2023-12-31', '2023-12-18 08:56:19', '2023-12-18 08:56:19');
INSERT INTO `tenant` VALUES (2988, 36, 'public/foto_profil_tenant/657fb3120c0a1.jpg', 'CANORI', 'Anggita Ulvia Savitri', 23, NULL, 'Dsn. Kranjan RT 001 RW 002 Ds. Parangbatu, Parengan, Tuban', NULL, NULL, 'IG : instagram.com/yourcanori', NULL, NULL, '<p style=\"text-align: justify; \">Canori snack merupakan produk diversifikasi pangan dari bahan baku rumput laut lokal Indonesia jenis anggur laut dengan rasa autentik anggur laut tanpa adanya penambahan bahan pengawet dan penguat rasa (MSG). Canori snack kaya kandungan Asam Glutamat 5.30% dan Asam Aspartam 2.65% yang baik untuk memenuhi kebutuhan asam amino non esensial pada tubuh. Canori snack memiliki warna produk hijau asli tanpa bahan pewarna artifisial yang diperoleh dari kandungan klorofil pada anggur laut. Manfaat lain dari klorofil adalah untuk meningkatkan imunitas tubuh, sumber energi, anti depresan pada susunan saraf pusat, mencegah konstipasi, perbaikan jaringan, dan membantu pembentukan hemoglobin. Canori snack juga kaya akan serat sehingga mampu memberikan nutrisi serat harian pada konsumen.</p>', '2023-06-01', '2023-12-31', '2023-12-18 09:48:50', '2023-12-18 09:48:50');
INSERT INTO `tenant` VALUES (2991, 230, 'public/foto_profil_tenant/659e20181b37e.jpg', 'PT. Karya Iwin Insani', 'Iwin Insani', 26, 1, 'Kawasan Inkubasi Bisnis BRIDA NTB- Jalan Bypass ZAMIA 2 - Desa Lelede - Kecamatan Kediri- Kode Pos 83362\r\nKabupaten Lombok Barat - Provinsi Nusa Tenggara Barat', NULL, NULL, 'Linktr.eeWebsite, Instagram, Facebook, Brosur,Inaexport.id,dll', 'Dalam Negeri dan Luar Negeri', 'Aplikasi Akuntansi', '<p><span style=\"color: rgb(5, 5, 5); font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; font-size: 15px; white-space-collapse: preserve;\">PT. </span><span style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; color: rgb(5, 5, 5); font-size: 15px; white-space-collapse: preserve;\"><a tabindex=\"-1\" style=\"color: rgb(56, 88, 152); cursor: pointer; font-family: inherit;\"></a></span><span style=\"color: rgb(5, 5, 5); font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; font-size: 15px; white-space-collapse: preserve;\">Karya Iwin Insani merupakan One Stop Service untuk berbagai kebutuhan bisnis kosmetikmu, mulai dari konsep, formulasi, legalitas, hingga produksi.</span><br></p>', NULL, NULL, '2024-01-10 11:42:00', '2024-01-10 11:42:00');
