INSERT INTO `tenant` VALUES (3013, 24, 'public/foto_profil_tenant/65a0ef50bd62c.png', 'Umbi.io', 'Umbi Teknologi Indonesia', NULL, NULL, 'Jl.Kartika 1 rt.003 Rw.017, Jebres, Jebres, Surakarta 5712', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Umbi.io adalah startup digital company dengan artificial intelligence sebagai visa utamanya, namun umbi memulai project awalnya dengan mengembangkan Iot khususnya Smarthome dan MVP awal Umbi yaitu Smartswitch, sebelum nantinya berkembang ke smartplug, smart remote, smart IR, smart gate, smart garden,serta smart energy.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:12797,&quot;3&quot;:{&quot;1&quot;:0,&quot;3&quot;:1},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:0,&quot;11&quot;:4,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\" data-sheets-textstyleruns=\"{&quot;1&quot;:0,&quot;2&quot;:{&quot;3&quot;:&quot;Calibri&quot;,&quot;4&quot;:11}}\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Umbi.io adalah startup digital company dengan artificial intelligence sebagai visa utamanya, namun umbi memulai project awalnya dengan mengembangkan Iot khususnya Smarthome dan MVP awal Umbi yaitu Smartswitch, sebelum nantinya berkembang ke smartplug, smart remote, smart IR, smart gate, smart garden,serta smart energy.</span><br></p>', NULL, NULL, '2024-01-12 14:50:40', '2024-01-12 14:50:40');
INSERT INTO `tenant` VALUES (3014, 24, 'public/foto_profil_tenant/65a0f0b4a08b1.jpeg', 'Syuukaa', 'Arva Rochmawati', 23, NULL, 'Bayan RT08 RW10, Kadipiro, Kota Solo, Jawa Tengah', NULL, NULL, 'Instagram, Tiktok, Youtube, dan Facebook', NULL, NULL, '<p>Criping pisang cap syuukaa merupakan criping pisang non msg, halal, enak, gurih, dan renyah dengan berbagai varian rasa.</p>', NULL, NULL, '2024-01-12 14:56:36', '2024-01-12 14:56:36');
