INSERT INTO `tenant` VALUES (3055, 40, NULL, 'Si Boolat', 'Lalak Tarbiyatun Nasyin Maleiva', NULL, NULL, 'Jalan Perdamaian, Komplek Ari Karya Indah 4, Gg. Sinar Pelita No. 6, Pal 9, Sungai Kakap, Kuburaya', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Si Boolat merupakan persuahaan yang menjual minuman berupa sari lemon murni, susu jagung, kopi susu gula aren, yogurt pisang (varian original, peanut butter, dan oatmeal), dan dessert box (coklat, keju, matcha)<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:16:50', '2024-02-07 15:16:50');
INSERT INTO `tenant` VALUES (3056, 40, NULL, 'Pondok Kite Yook', 'FRANSISKA', NULL, NULL, 'Jl. Darma Bakti Gg. Parit Tengkorak RT/RW 006/008 Kel. Parit Baru Kec. Sungai Raya', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Pondok Kite Yook merupakan usaha yang menjual Bumbu Beras Bubur Pedas, Sambal Cumi Botolan, Kerupuk Nasi, Ayam Geprek, Bubur Pedas, Mie Tiau<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:18:03', '2024-02-07 15:18:03');
INSERT INTO `tenant` VALUES (3057, 40, NULL, 'Mokomi (Mozarella Corndok Yummy)', 'Aulyahaq Tiabarte', NULL, NULL, 'Jl. Tanjung Raya 2, teras Alfamart Saigon', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Mokomi&nbsp; merupakan perusahaan yang menjual Jajanan asal korea bernama Mozarella Corndok, keju mozarella dibalur dengan adonan roti, kemudian diberi topping asin (mayo/saos) dan manis (coklat, tiramisu, greentea, taro, dll).<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:19:46', '2024-02-07 15:19:46');
INSERT INTO `tenant` VALUES (3058, 40, NULL, 'Reker', 'Dimas Sigit Prasetyo', NULL, NULL, 'Jl. Nirbaya, Komp. Villa Mas No.10', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Reker merupakan perusahaan yang menjual produk makanan ringan berupa keripik jagung ala meksiko yang dikemas dengan design menarik.<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:20:55', '2024-02-07 15:20:55');
INSERT INTO `tenant` VALUES (3059, 40, NULL, 'Bakul Lazizz', 'Rika Wulandari', NULL, NULL, 'Jl Dr Wahidin GG Sepakat 8 jalur 6 kompleks sepakat 88 no A2 Pontianak', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Bakul Lazizz merupakan perusahaan yang memproduksi berbagai makanan sehat premium - menu masakan sehat - pastry - bakery - pudding * Kursus cooking baking dengan tujuan agar peserta dapat membuka usaha sendiri<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:22:19', '2024-02-07 15:22:19');
INSERT INTO `tenant` VALUES (3060, 40, NULL, 'Aulia\'s kitchen', 'Eka Rosdiyanti S.S.Pd', NULL, NULL, 'Jl. Dharma putra rt 08 rw 02 kelurahan ladang kecamatan sintang Kalimantan Barat', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Aulia\'s kitchen adalah perusahaan yang memproduksi dan menjual Kripik kelapa muda dari kelapa pirang pilihan yang di hasilkan dari kebun masyarakat Penibung Mempawah Kalimantan Barat. Kripik kelapa muda di olah dengan melalui proses protokol kesehatan dengan menggunakan masker, sarung tangan, penutup kepala dan celemek. Di produksi oleh karyawan yang sudah mahir dalam pembuatan kripik ini. dengan bantuan tepung sagu tani dan tepung beras serta telur sehingga setelah di lakukan penggorengan maka kripik terasa lebih gurih.<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:23:27', '2024-02-07 15:24:03');
INSERT INTO `tenant` VALUES (3061, 40, NULL, 'Juragan Donat', 'Ridho hudayana', NULL, NULL, 'Jalan Tabrani Ahmad komplek ari karya Indah 9', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Juragan Donat merupakan perusahaan yang memproduksi dan menjual Donat Kekinian<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:25:14', '2024-02-07 15:25:14');
INSERT INTO `tenant` VALUES (3062, 40, NULL, 'Kue Kering Kanji Abang Sayang', 'Muhammad Al Furqan', NULL, NULL, 'Jalan Sungai Raya Dalam No 30B, Kec. sungai raya, Kab. kubu raya', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Kue Kering Kanji Abang Sayang adalah perusahaan yang menyediakan Kue kering berbahan dasar tepung kanji dengan bentuk cetak yg unik dan mungil, sehingga mengundang selera untuk dimakan. Memliki 4 varian rasa : original, keju, pandan dan coklat. Rasanya manis, gurih dan bikin nagih<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:26:22', '2024-02-07 15:26:22');
INSERT INTO `tenant` VALUES (3063, 40, NULL, 'KUPS muara abadi', 'Jamiin', NULL, NULL, 'Desa Nanga lauk kec.embaloh hilir kab.kapuas hulu kalbar', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>KUPS muara abadi adalah perusahaan dibidang Budidaya ikan patin<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:27:29', '2024-02-07 15:27:29');
INSERT INTO `tenant` VALUES (3064, 40, NULL, 'IKM Jangek', 'Ayu Rahmawati', NULL, NULL, 'Jl H A Rajak no 10, Kelurahan Saigon Kecamatan Pontianak Timur, Kota Pontianak', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>IKM Jangek merupakan perusahaan dibidang pengolahan Makanan Ringan dari Kulit sapi, dinamakan Kerupuk Jangek<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:44:30', '2024-02-07 15:44:30');
INSERT INTO `tenant` VALUES (3065, 40, NULL, 'JESIKA (Jeruk Sambal Asli KalBar)', 'Arief Pramudi', NULL, NULL, 'Dsn.Merak, Sungai Kakap, Kubu Raya', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>JESIKA merupakan suatu perusahaan pengelolaan Jeruk Sambal/Jeruk Kalamansi/Jeruk Limau kecil, yang di ekstrak sehingga menjadi sirup (minuman) alami. Adapun produk olahan kami menjadikan ikhtiar kami untuk bersama-sama menjaga kesehatan dan stamina tubuh (imun tubuh).<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:45:40', '2024-02-07 15:45:40');
INSERT INTO `tenant` VALUES (3066, 40, NULL, 'Mitra sejahtera industri', 'M. Salihin', NULL, NULL, 'Rt.17 desa Teluk Batang Kecamatan Teluk Batang Kabupaten Kayong Utara', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Mitra sejahtera industri adalah perusahaan jyang menyediakan Kopi bubuk<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:47:10', '2024-02-07 15:47:10');
INSERT INTO `tenant` VALUES (3067, 40, NULL, 'Madu Hutan Riparian', 'Rio Afiat', NULL, NULL, 'Kota Pontianak', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Madu Hutan Riparian merupakan usaha yang Menjual madu hutan Riparian yang berasal dari hutan desa Nanga Lauk Kabupaten Kapuas Hulu Kalbar<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:48:15', '2024-02-07 15:48:15');
INSERT INTO `tenant` VALUES (3068, 40, NULL, 'Makros jaya abadi', 'Ikhfanuddin', NULL, NULL, 'Jl komyossudarso gg duku baru dalam no 80', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Makros jaya abadi merupakan Bisnis lokal yang memproduksi snack jadul dengan tampilan kekinian<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:49:32', '2024-02-07 15:49:32');
INSERT INTO `tenant` VALUES (3069, 40, NULL, 'Alam Berdaya', 'M. Arief fathony', NULL, NULL, 'Jln. Danau Kayan dalam no 5 Putussibau.', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Alam berdaya merupakan usaha berbasis pemanfaatan sumberdaya alam lokal secara lestari dan berkelanjutan. Mengolah hasil alam dan kemudian meningkatkan nilai jual. Alam berdaya selain memproduksi produk berupa pangan atau makanan juga memproduksi Pupuk organik (alami) dan pestisida alami dengan memanfaatkan limbah limbah makanan, buah-buahan , dan limbah pertanian serta beberapa bahan alam lainnya.<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:50:58', '2024-02-07 15:50:58');
INSERT INTO `tenant` VALUES (3070, 40, NULL, 'Hygge Kitchen', 'Ais Fitaloka', NULL, NULL, 'jl. khatulistiwa Gg teluk berlian Pontianak Utara', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Hygge Kitchen merupakan usaha pangan yang memproduksi makanan real food. makanan yang di buat hanya menggunakan bahan-bahan alami yang di beli dari para petani lokal. menggunakan bahan yang berkualitas, tanpa pewarna, pengawet dan perasa buatan.<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:52:12', '2024-02-07 15:52:12');
INSERT INTO `tenant` VALUES (3072, 40, NULL, 'DAPOER UMAK', 'YOVI SUHARTADI, SE', NULL, NULL, 'Jl. Juang Km.2 Desa Tanjung Niaga Kec. Nanga Pinoh Kab. Melawi', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>DAPOER UMAK adalah usaha yang Menyiapkan Makanan Siap Saji dengan Konsep Masakan Ala dapur rumah.<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:54:28', '2024-02-07 15:54:28');
INSERT INTO `tenant` VALUES (3073, 40, NULL, 'Taman aqiqah Pontianak', 'Azuwar Muhammad Zein', NULL, NULL, 'Jln Nurul Huda , gang mutiara nomor 1', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Taman aqiqah Pontianak merupakan perusahan yang menyediakan Jasa kambing Aqiqah dan Qurban yang dimulai pertengahan tahun 2018 yang diawali dengan melihat peluang bisnis yang cukup menjanjikan ,karena di kalbar ini,khusus nya di pontianak ,kubu raya dan sekitarnya sangat minim sekali menawarkan jasa kambing aqiqah dan qurban .<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:55:41', '2024-02-07 15:55:41');
INSERT INTO `tenant` VALUES (3074, 40, NULL, 'Pouring Coffee', 'Wahyu ochiano saputro', NULL, NULL, 'Jalan Hm suwignyo, komplek suwignyo permai 1 no 18', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Pouring Coffee merupakan perusahaan yang Menjual kopi dengan produk kopi lokal, tepatnya jenis kopi liberika dan robusta kayong utara.<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:56:48', '2024-02-07 15:56:48');
INSERT INTO `tenant` VALUES (3075, 40, NULL, 'Madu Kapuas', 'Ihzal Muhaini', NULL, NULL, 'Jl. Wonoyoso 1 Gg 3, Pontianak Selatan', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Madu Kapuas merupakan perusahaan yang menyediakan Madu hutan/liar Kapuas Hulu, dari lebah Apis Dorsata<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 15:58:06', '2024-02-07 15:58:06');
INSERT INTO `tenant` VALUES (3076, 40, NULL, 'Madu Kanzia', 'Joko Setiadi', NULL, NULL, 'Jalan Sungai Raya Dalam Gang Semi No 2 Kubu Raya', NULL, NULL, 'IG, FB, Website', 'Kalimantan Barat', NULL, '<p>Madu Kanzia merupakan perusahaan yang menyediakan jenis madu hutan khas Kalimantan Barat, dikemas secara menarik yang telah melewati serangkaian proses uji kemurnian mulai dari lab, LPPOM MUI dan PIRT<br></p>', '2022-10-10', '2024-10-10', '2024-02-07 16:01:43', '2024-02-07 16:01:43');
