INSERT INTO `tenant` VALUES (3116, 7, 'public/foto_profil_tenant/65d4461f030d4.png', 'BicaraPede Academy', 'Ahmad Qaedi Luthfi', NULL, NULL, 'Gedung Wirausaha Lantai 1 Unit 104, Jalan HR Rasuna Said Kav. C-5, Desa/Kelurahan Karet, Kec. Setiabudi, Kota Adm. Jakarta Selatan, Provinsi DKI Jakarta,', NULL, '300.000.000,00', 'Instagram, website, brosur, media cetak', 'Pelajar dan mahasiswa', NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Star-Up yang berfokus pada bidang Pelatihan Kursus Public Speaking dan Komunikasi&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Star-Up yang berfokus pada bidang Pelatihan Kursus Public Speaking dan Komunikasi</span><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span></p><p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><u>Investasi/kerjasama yang sudah dilakukan :</u></span></p><p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;2022 - IYT ITS - Kerjasama dalam hal pendanaan bisnis\\n2023 - ILBI ITS - Kerjasama dalam hal pendanaan hibah&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">2022 - IYT ITS - Kerjasama dalam hal pendanaan bisnis<br>2023 - ILBI ITS - Kerjasama dalam hal pendanaan hibah</span><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span></p><p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><u>Transaksi penjualan/penyewaan produk: </u></span></p><p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Kerjasama dengan Instansi Pemerintahan - 15+ instansi\\nFollowers Social Media - 50k+\\nKelas Terlaksana - 100+\\nPeserta Kelas - 10k+ (alumni)\\nProyek Sosial - 5+&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Kerjasama dengan Instansi Pemerintahan - 15+ instansi<br>Followers Social Media - 50k+<br>Kelas Terlaksana - 100+<br>Peserta Kelas - 10k+ (alumni)<br>Proyek Sosial - 5+</span><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span></p><p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><u>Capaian : </u></span></p><p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Finalist of Pertamina Muda Seed and Scale Bussiness by PT Pertamina Persero di Denpasar, Bali 2022\r\nAwardee Rumah Akselerasi Inovasi by XL Future Leader Bussiness Awards, Jakarta 2022\r\nSemi Finalist of Talenta Wirausaha BSI kategori Rintisan by Bank Syariah Indonesia, Jakarta 2022\r\nFinalist Diplomat Success Challenge 2 Milliar by PT Wismilak Foundation, Surabaya 2023\r\nSemi Finalist of Kompetisi SOPREMA UGM x Kemenpora, Yogyakarta 2022\r\nFinalist Youth Economic Leadership Program by Bank Indonesia Insitute, Jakarta 2022</span><br></p>', '2022-09-30', NULL, '2024-02-20 13:26:39', '2024-02-20 13:26:39');
