INSERT INTO `tenant` VALUES (3119, 62, 'public/foto_profil_tenant/65def005b5f27.jpg', 'RachmaJaya WoodCraft', 'Fahmi Rachmanda Putra', 15, 3, 'Wonosari RT 4, Sambirembe, Kalijambe, Sragen', NULL, NULL, 'Instagram', NULL, NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Pet furniture, pembuatan kandang dan rumah hewan peliharaan</span><br></p>', '2023-03-21', '2023-11-25', '2024-02-28 15:34:13', '2024-02-28 15:34:13');
INSERT INTO `tenant` VALUES (3120, 62, 'public/foto_profil_tenant/65def1dd3dfbc.jpg', 'Vita Collection', 'Vironita Puspitasari', 39, 1, 'Ngawen rt 2 rw 1 purbayan baki', NULL, '550.000.000,00', 'Instagram', 'Jawa Tengah dan', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Produsen tas dan merchandise</span><br></p>', '2023-03-23', '2023-11-25', '2024-02-28 15:42:05', '2024-02-28 15:42:05');
INSERT INTO `tenant` VALUES (3121, 62, 'public/foto_profil_tenant/65def36562529.png', 'Lurik Rachmad', 'Lissa Ratna Dewi Wijayanti', 39, 1, 'Jl. Griya Prima Timur no 417, Belang wetan, Klaten Utara', NULL, '4.600.000.000,00', 'Instagram dan Webiste', 'Indonesia dan luar negeri', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Berdiri sejak tahun 1960, Lurik Rachmad merupakan perusahaan yang bergerak dalam bidang industri kain tenun nusantara yang berasal dari Pedan, Jawa Tengah.\r\n\r\nDengan menitikberatkan corak yang berlajur lajur, Rachmad yang lahir dari pengusaha tenun, telah memulai perjalanannya menjadi sang maestro semenjak masa remaja.\r\n\r\nSaat ini, upaya yang dicita citakan Rachmad telah berganti tingkat estafet. Pengalaman yang tak ternilai harganya ini, kami terus kembangkan dalam menggapai produk yang menjadi kebanggaan Indonesia.\r\n\r\nMenjadi produk warisan nusantara, berkualitas dan tak henti berinovasi, merupakan cermin jati diri kami, dalam menjadikan Lurik Rachmad sebagai Identitas Warisan Nusantara.</span><br></p>', '2023-03-23', '2023-11-25', '2024-02-28 15:48:37', '2024-02-28 15:48:37');
INSERT INTO `tenant` VALUES (3122, 62, 'public/foto_profil_tenant/65def56eb482b.jpg', 'Tenun Mitra Warna', 'Irbab Aulia Amri', 39, 1, 'Troso Rt04 Rw 07', NULL, '144.000.000,00', 'Instagram', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Menjadi pusatnya edukasi dan belanja tenun di jepara yang menawarkan berbagai jenis produk berkualitas baik bahan kain tenun, baju tenun, fashion tenun, aksesoris tenun serta wisata tenun. Tenun kami asli handmade, ethnic, melayani custom motif daerah serta bervariasi dalam motif dan warna dengan bahan yang berkualitas sehingga menjadi oleh oleh khas Jepara yang cocok untuk seragam couple, sekolah, lembaga, perusahaan dan instansi</span><br></p>', '2023-03-23', '2023-11-25', '2024-02-28 15:57:18', '2024-02-28 15:57:18');
INSERT INTO `tenant` VALUES (3123, 62, 'public/foto_profil_tenant/65def6a64d441.jpg', 'Ipang Production', 'Apsasi Annisa Romas', 42, 3, 'Dusun Nepen 002/005 Gunungpring, Kec. Muntilan', NULL, '1.440.000.000,00', 'Instagram dan Offline', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Ipangproduction adalah perusahaan yang bergerak di bidang industri seni cetak  saring (sablon) yang berdiri sejak tahun 2014. Dalam perjalanannya, perusahaan  yang berlokasi di Nepen RT/W 02/05 Gunungpring Muntilan Magelang ini telah  banyak menangani berbagai jenis produk pakaian dengan beragam material dan telah mengembangkan produk seperti souvenir, bordir, serta percetakan dengan  konsumen yang tersebar diberbagai wilayah Indonesia.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:02:30', '2024-02-28 16:02:30');
INSERT INTO `tenant` VALUES (3124, 62, 'public/foto_profil_tenant/65def79728422.jpg', 'Terebatik', 'Teresia Leony Widi Hastuti SE.MM', 39, 1, 'Jalan, Gondang Manis ruko Wijaya royal residen No.7', NULL, '1.500.000.000,00', 'Instagram dan TikTok', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Batik tulis, batik cap, fashion</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:06:31', '2024-02-28 16:06:31');
INSERT INTO `tenant` VALUES (3125, 62, 'public/foto_profil_tenant/65def86986c59.png', 'House of Triana', 'Triana Rahmawati', 26, 1, 'jalan letnan karjono 120 parakancanggah Banjarnegara', NULL, '360.000.000,00', 'Instagram dan WA', 'Banjarnegara dan Jawa Tengah', NULL, '<p>house of triana adalah bisnis yang bergerak di bidang jasa pernikahan dan dekorasi. Saat ini juga melayani wedding organizer&nbsp; dan persewaan kebaya.<br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:10:01', '2024-02-28 16:10:01');
INSERT INTO `tenant` VALUES (3126, 62, 'public/foto_profil_tenant/65def91ac0098.png', 'Izzi Craft', 'Ivon Linza Kurniasih', 39, 1, 'Karanganyar rt 01 rw 02 dukuhturi tegal', NULL, '300.000.000,00', 'TikTok, Instagram, Shopee', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">izzi craft berawal dari produsen aksesoris handmade izzi handycraft aksesoris daily used yg up to date, berkarakter dan mengutamakan kenyamanan bagi pemakai dan kini berkembanng menjadi toko bahan aksesoris dan craft serta floris izzi handycraft yang menyediakan aneka macam alat dan  bahan2 aksesoris, craft, floris utk memenuhi kebutuhan pasar  utk bahan2 kerajinan terutama di wilayah kota tegal, kab tegal, brebes dan pemalang</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:12:58', '2024-02-28 16:12:58');
INSERT INTO `tenant` VALUES (3127, 62, 'public/foto_profil_tenant/65def9fd06708.jpg', 'Bikin Kreatif Digital Agency', 'Abdul khadik', 42, 5, 'Wirosaban Barat no. 20', NULL, '466.310.000,00', 'Instagram dan Website', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Kami adalah digital Agency yang menyediakan jasa Pengelolaan sosial media, foto produk, pembuatan website, video promosi dan layanan digital marketing</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:16:45', '2024-02-28 16:16:45');
INSERT INTO `tenant` VALUES (3128, 62, 'public/foto_profil_tenant/65defb0885825.png', 'GodhongKoe', 'Reno Suryani', 19, 1, 'Jalan Bonang 5 RT 05 RW 02 Joyotakan', NULL, '180.000.000,00', 'Instagram dan WA', 'Surakarta dan Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">GodhongKoe merupakan usaha yang bergerak dibidang fashion dan craft berupa batik pewarna alam dan ecoprint.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:21:12', '2024-02-28 16:21:12');
INSERT INTO `tenant` VALUES (3129, 62, 'public/foto_profil_tenant/65defc3077779.jpg', 'Tia seprei', 'Bastiatun', 19, 1, 'Jl Ade Irma Suryani rt 04 rw 08 brebes', NULL, '300.000.000,00', 'Instagram, Shopee, dan WA', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Tia seprei yg memproduksi seprei home Made ,dengan kwalitas bagus jg motif beragam,kain yg tidak luntur dan nyaman dipakai pas banget buat kekuarga</span><br></p>', '2023-02-23', '2023-02-23', '2024-02-28 16:26:08', '2024-02-28 16:26:08');
INSERT INTO `tenant` VALUES (3130, 62, 'public/foto_profil_tenant/65defe790bf87.png', 'tatarapi', 'Zihni Ihkamuddin', 22, 3, 'GIRI MUKTI NO 216', NULL, '310.000.000,00', 'Instagram, Website, WA', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Usaha Kebersihan dan laundry di Semarang. Kami menangani pembersihan cuci pakaian harian, pakaian satuan dry clean dan wet clean, perlengkapan bayi, sepatu, tas, helm, kasur, sofa, karpet dan kebersihan rumah ataupun kantor pasca renovasi atau baru selesai perbaikan. \r\n</span></p><div><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span></div>', NULL, '2023-11-25', '2024-02-28 16:35:53', '2024-02-28 16:35:53');
INSERT INTO `tenant` VALUES (3131, 62, 'public/foto_profil_tenant/65deffc88389b.png', 'Kakarobot ID', 'Danya Deluca', 22, 3, 'Gondang Timur V No 53', NULL, '250.000.000,00', 'Instagram, TikTok, dan Youtube', 'Indonesia dan luar negeri', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Kakarobot merupakan start up research and development berbasis teknologi dimana menawarkan pembuatan alat industri seperti robotika, AI, IoT, ERP System, Website dan Aplikasi dimana menyesuaikan dengan kebutuhan customer dan problem yang dialami mereka di industri nya. Selain itu Kakarobot juga mengadakan pembelajaran robotika, computational thinking, dan IoT untuk berbagai jenjang mulai dari SD hingga Mahasiswa dan juga umum. Dimana untuk kelas nya dapat dilakukan secara offline maupun online melalui website kami dan penjualan robot atau modul pembelajaran dapat dibeli melalui e-commerce</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:41:28', '2024-02-28 16:41:28');
INSERT INTO `tenant` VALUES (3132, 62, 'public/foto_profil_tenant/65df00c968184.jpg', 'Pasar Sayoor', 'M Unggul Tri Budiharjo', 1, 2, 'Jl supriyadi no 39 rt 01 rw 05 kel pringrejo, kec pekalongan barat, 51116', NULL, '800.000.000,00', NULL, 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">E-Groceries Distributor for Business, menyediakan jasa distribusi bahan makanan segar (sayur, daging, telur, sembako, dan bumbu dapur) ke mitra bisnis kuliner (Caffee, Boarding School, Rumah sakit, Hotel)</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:45:45', '2024-02-28 16:45:45');
INSERT INTO `tenant` VALUES (3133, 62, 'public/foto_profil_tenant/65df01eac396b.png', 'Solohabo', 'Mellenia Putri Fiorentina', 15, 1, 'Jl. Tambora Tengah VI No. 6 RT 04/RW 21 Mojosongo, Jebres, Surakarta', NULL, '140.000.000,00', 'Instagram dan Shopee', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Bisnis yang menjual hampers kayu dan foto bingkai kayu</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:50:34', '2024-02-28 16:50:34');
INSERT INTO `tenant` VALUES (3134, 62, 'public/foto_profil_tenant/65df02d68234e.jpg', 'SANGA', 'SIGIT GUNAWAN', 19, 1, 'Desa Rajawana RT 07/02, Kec. Karangmoncol', NULL, '120.000.000,00', 'Instagram, Facebook', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">SANGA Merupakan perusahakan yang bergerak \r\ndi bidang jasa konveksi pembuatan seragam kantor, \r\nkaos custom, jaket. Selain konveksi juga melayani \r\nsablon kaos, plastik dan cup dan perusahakan kami \r\nmelayani jasa cetak buku, nota, faktur, dus kemasan \r\ndan masih banyak lagi.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:54:30', '2024-02-28 16:54:30');
INSERT INTO `tenant` VALUES (3135, 62, 'public/foto_profil_tenant/65df0376d432a.png', 'Percetakan DIM', 'Hanif Firmansyah', 42, 1, 'Jl. Mayjend Bambang Sugeng 21', NULL, '480.000.000,00', 'Instagram', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Merupakan perusahaan yang bergerak dalam bidang percetakan yang berdiri pada tahun 2002. Perusahaan kami selalu berkomitmen untuk membangun lingkungan kerja yang nyaman dan berkualitas, melalui pelayanan terbaik yang diberikan.\r\n\r\nDIM adalah perusahaan percetakan yang menawarkan produk-produk sepert : undangan, brosur, buku, kalender, kartu nama, ID Card, kaos, spanduk, banner, neon box, benda-benda promosi, dan lain-lain. \r\n\r\nDidukung oleh tenaga muda yang handal dan alat-alat yang mampu memberi pelayanan yang terbaik dalam harga, waktu, dan kualitas.DIM  telah  menghadirkan  karya-karya  yang  berkualitas  dan  inovatif  yang tersebar. \r\n\r\nDIM  mempunyai  komitmen  sebagai  mitra  kerja  yang  handal  dan terpercaya  untuk mewujudkan yang terbaik telah menjadi motor penggerak bagi kami untuk memberikan layanan yang terbaik bagi klien kami. Kami  selalu  berusaha  untuk  memberikan  servis  dan  produk yang terbaik  serta mengusahakan  produk  kami  agar  esien  dan  efektif  dalam  menyampaikan pesan-pesan Anda ke masyarakat.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 16:57:10', '2024-02-28 16:57:10');
INSERT INTO `tenant` VALUES (3136, 62, 'public/foto_profil_tenant/65df047d23cf4.jpg', 'MIDRAR MOSLEM SHIRT', 'M. Yusuf Al Faruq', 19, 1, 'Buko, RT. 02 RW. 02 Wedung Demak', NULL, '134.400.000,00', 'Instagram', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">MIDRAR merupakan produsen Basic Moslem Shirt yang berasal dari Demak, Jawa Tengah. Berdiri pada tahun 2021, MIDRAR memiliki tagline \"Kemeja Keberlimpahan\". Selama dua tahun perjalanannya, MIDRAR telah merilis berbagai produk baju dengan beragam desain dan variasi warna dan telah menjual lebih dari 1500 pcs. Sebagai sebuah brand, MIDRAR diupayakan untuk terus bertumbuh sehingga menjadi brand baju muslim terbesar di Jawa Tengah.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:01:33', '2024-02-28 17:01:33');
INSERT INTO `tenant` VALUES (3137, 62, 'public/foto_profil_tenant/65df0511ea5ed.jpeg', 'Kampung Garment Banyumas', 'Zakaria Asidiq', 19, 1, 'Jl. Kedung Kambang RT 01 RW 01 Desa Pekunden Kec. Banyumas Kab. Banyumas', NULL, '596.000.000,00', 'Instagram', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Kampung garment banyumas merupakan bisnis yang bergerak pada bidang konveksi pembuatan pakaian.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:04:01', '2024-02-28 17:04:01');
INSERT INTO `tenant` VALUES (3138, 62, 'public/foto_profil_tenant/65df05bb48863.jpg', 'Batik Solo 85', 'Agustin Dyah Utami', 19, 1, 'Gabahan RT.005 RW.012 KEL. JOMBOR, KEC.BENDOSARI, KAB.SUKOHARJO, JATENG.', NULL, '360.000.000,00', 'Instagram', 'Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Batik Solo 85 dirintis sejak tahun 2010, usaha kami bergerak di bidang Fashion Batik dari Sukoharjo, Jawa Tengah. Kami memproduksi home dress batik cap (daster, babydoll, gamis, celana batik), seragaman batik  baik kain maupun baju jadi (seragaman kantor, seragam RT, seragam instansi, seragam gamis ibu-ibu pengajian,dll). Kami juga menerima permintaan custom size. Kami telah memasarkan produk kami di seluruh kota di seluruh Indonesia dan di luar negeri. Kami mengutamakan kualitas dan model yang selalu up to date. </span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:06:51', '2024-02-28 17:06:51');
INSERT INTO `tenant` VALUES (3139, 62, 'public/foto_profil_tenant/65df06e90214e.png', 'Taggallery Agency', 'TRIAWANDA TIRTA ADITYA', 42, 3, 'Banyumanik, Semarang', NULL, '360.260.000,00', 'Instagram', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Start Up yang bergerak di bidang digital creative agency. Menawarkan jasa kelola sosmed, fotografi event, dan videografi event</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:11:53', '2024-02-28 17:11:53');
INSERT INTO `tenant` VALUES (3140, 62, 'public/foto_profil_tenant/65df077b19c87.png', 'Elinor Jewelry', 'Syifa khusnul khotimah', 11, 1, 'Jl Tarakan No 15 Rt 01 Rw 06', NULL, '3.100.000.000,00', 'Instagram', 'Indonesia', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Elinor Jewelry adalah sebuah produk perhiasan yang terbuat dari ASI dan DNA atau biasa disebut breastmilk jewelry. Produk ini didirikan pada tahun 2021 dan bekerja sama dengan klinik bersalin dan rumah sakit di area Solo. Elinor Jewelry merupakan produk yang sepenuhnya handmade dan diproduksi oleh pengerajin perhiasan lokal yang saat ini mulai langka di daerah Solo Raya. Salah satu keunggulan dari Elinor Jewelry adalah produk ini memiliki nilai emosi yang sangat kuat. Hal ini disebabkan oleh bahan utama dari perhiasan ini yaitu ASI dan DNA bayi yang diambil dari customer. Dengan begitu, setiap perhiasan yang dihasilkan oleh Elinor Jewelry memiliki nilai sentimental yang sangat berharga bagi para ibu. Selain itu, dengan menggunakan bahan utama dari ASI dan DNA bayi, Elinor Jewelry memberikan kesempatan kepada para ibu untuk memperlihatkan kecintaan mereka terhadap anak mereka melalui sebuah perhiasan. Produk ini juga membantu para pengerajin perhiasan lokal di area Solo Raya dengan memberikan pekerjaan dan membantu mempertahankan keberlangsungan kerajinan perhiasan lokal.</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:14:19', '2024-02-28 17:14:19');
INSERT INTO `tenant` VALUES (3141, 62, 'public/foto_profil_tenant/65df083c0fd19.png', 'Asdosku', 'Yustitia Septri Saputra', 32, 5, 'Babakan RT 01 RW 01', NULL, '110.000.000,00', 'Instagram', 'Banyumas dan Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Asdosku adalah platform yang memudahkan dosen menemukan asisten dosen untuk membantu melaksanakan tri dharma perguruan tinggi</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:17:32', '2024-02-28 17:17:32');
INSERT INTO `tenant` VALUES (3142, 62, 'public/foto_profil_tenant/65df08e122c71.jpg', 'Printpackindo', 'Yoke Wandaningrum', 42, 3, 'Villa Aster 2 blok Q no.14 Banyumanik Semarang', NULL, '180.000.000,00', 'Instagram', 'Semarang dan Jawa Tengah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Percetakan merchandise dan souvenir</span><br></p>', '2023-03-23', '2023-03-23', '2024-02-28 17:20:17', '2024-02-28 17:20:17');
INSERT INTO `tenant` VALUES (3143, 62, 'public/foto_profil_tenant/65df1f1a9d25a.png', 'Okami', 'Hendi Suryo Leksono', 43, NULL, 'Jl Sudimoro No 10 A Malang Jawa Timur', NULL, '50.000.000,00', NULL, NULL, NULL, '<p>Okami saat ini merupakan klinik hewan integratif yang menyediakan solusi berupa layanan kesehatan hewan yang komprehensif baik untuk hewan yang meliputi jasa check up dokter hewan, farmasi obat, jasa lab (usg, hemo darah, rontgen dll) , rawat inap, homecare, vaksin, serta untuk pet owner</p>', NULL, NULL, '2024-02-28 18:55:06', '2024-02-28 18:55:06');
INSERT INTO `tenant` VALUES (3144, 62, 'public/foto_profil_tenant/65df1f61ac44f.jpg', 'Fisiohome', 'Hasnal Wenes', 43, NULL, 'QP Office, Perkantoran Tanjung Mas Raya, Blok B1. No. 44, Jakarta Selatan. 12530', NULL, '500.000.000,00', NULL, NULL, NULL, '<p>Fisiohome merupakan platform home visit fisioterapi pertama di Indonesia yang menawarkan solusi bagi segala persoalan gerak dan fungsi tubuh, dimana tidak ada lagi jarak dan waktu yang menjadi halangan pasien untuk mendapatkan pelayanan fisioterapi kapanpun dan dimanapun.</p><div><br></div>', NULL, NULL, '2024-02-28 18:56:17', '2024-02-28 18:56:17');
INSERT INTO `tenant` VALUES (3145, 62, 'public/foto_profil_tenant/65df1fd59a44b.jpg', 'Nom Nom Herbs & Spices', 'Arif Rahman Faiza Asri', 23, 2, 'Jl. Maribaya No. 41 Lembang, Bandung Barat 40391', NULL, '150.000.000,00', NULL, NULL, NULL, '<p>Nom Nom Herbs &amp; Spices (NMHS) adalah pemasok bumbu dan rempah terkemuka yang hanya mengirimkan bumbu dan rempah Indonesia terbaik ke pasar domestik dan internasional. Mengembangkan teknologi canggih di sektor hulu dan hilir, NMHS berupaya menyediakan pertanian yang adil dan ramah lingkungan untuk mempromosikan petani, rantai pasokan, dan kelestarian lingkungan</p><div><br></div>', NULL, NULL, '2024-02-28 18:58:13', '2024-02-28 18:58:13');
INSERT INTO `tenant` VALUES (3146, 62, 'public/foto_profil_tenant/65df20af7c905.jpg', 'AKOR', 'Novia Anggita', 2, 2, 'Lahat, Indonesia', NULL, NULL, NULL, NULL, NULL, '<p>Akor Indonesia merupakan perusahaan yang berdiri sejak tahun 2021 untuk memberikan solusi di bidang perdagangan internasional berbasis social enterprise di Provinsi Sumatera Selatan dengan menyelesaikan masalah rantai pasokan pertanian antara importir sebagai pembeli dan petani sebagai produsen.</p><div><br></div>', NULL, NULL, '2024-02-28 19:01:51', '2024-02-28 19:01:51');
INSERT INTO `tenant` VALUES (3147, 62, 'public/foto_profil_tenant/65df212ebd842.jpg', 'Teman Pasar', 'Ahmad Alimuddin', 44, 2, 'Graha Mandiri Nomor 1, Jl. Tugu Raya, Tugu, Cimanggis, Depok, Jawa Barat', NULL, '285.000.000,00', NULL, NULL, NULL, '<p>Teman pasar merupakan platform belanja di pasar tradisional terdekat di Indonesia. Platform ini membantu bisa membantu pengguna atau konsumen berbelanja ke pasar tradisional terfavorit dan terdekat. Dengan Teman Pasar, pengguna nantinya mendapatkan teman belanja dan teman antar yang selalu siap membeli serta mengantar kebutuhan harian atau mingguan.</p><div><br></div>', NULL, NULL, '2024-02-28 19:03:58', '2024-02-28 19:03:58');
INSERT INTO `tenant` VALUES (3148, 62, 'public/foto_profil_tenant/65df217516e0a.jpg', 'Minaverse', 'Dyogi Miyosa Trianzie', 4, 2, 'Ringinsari, Maguwoharjo, Depok, Sleman, Yogyakarta.', NULL, '20.000.000,00', NULL, NULL, NULL, '<p>Budidaya ikan nila sistem zero waste yang terintegrasi antara pertanian, peternakan, dan perikanan dengan penambahan probiotik (bakteri pengurai) buatan sendiri yg berfungsi sebagai pengendalian penyakit dan meminimalisir penggunaan obat kimia.<br></p>', NULL, NULL, '2024-02-28 19:05:09', '2024-02-28 19:05:09');
INSERT INTO `tenant` VALUES (3149, 62, 'public/foto_profil_tenant/65df21c514404.jpg', 'TARUNIRA', 'I Komang Sukarma', 2, 2, 'BD Cutcut, Desa Ban, Kecamatan Kubu, Kabupaten Karangasem, Bali 80853', NULL, '25.000.000,00', NULL, NULL, NULL, '<p>Produk utama kami adalah gula lontar organik (organic palmyra sugar) hasil dari pemanfaatan potensi alam pedesaan pohon lontar (Borassus flabellifer lin) terutama air niranya sembari memberdayakan dan mempekerjakan petani dan ibu-ibu lokal di Karangasem, Bali.</p><div><br></div>', NULL, NULL, '2024-02-28 19:06:11', '2024-02-28 19:06:29');
INSERT INTO `tenant` VALUES (3150, 62, 'public/foto_profil_tenant/65df220a44e9e.jpg', 'OKE Garden', 'Hadid Fathul Alam', 34, 2, 'Jl. Lettu. H. Abdul Karim No.73, Bedahan, Kota Depok, Jawa Barat', NULL, '333.094.027,00', NULL, NULL, NULL, '<p>OKE Garden adalah platform digital&nbsp; yang menyediakan layanan pembuatan lanskap untuk membantu para milenial dan ibu rumah tangga yang tidak memiliki banyak waktu untuk membangun dan merawat taman tetapi ingin memilikinya. OKE Garden mempertemukan calon konsumen dengan desainer lanskap bersertifikat,tukang taman serta petani lokal dengan cara yang mudah dan dapat diandalkan.&nbsp;</p><div><br></div>', NULL, NULL, '2024-02-28 19:07:38', '2024-02-28 19:07:38');
INSERT INTO `tenant` VALUES (3151, 62, 'public/foto_profil_tenant/65df2249a451f.jpg', 'Today Tech', 'Rakhman Ardiansyah', 2, 2, 'Purwomartani Baru Blok 2 No. 37 Kalasan Sleman', NULL, '100.000.000,00', NULL, NULL, NULL, '<p>TODAY TECH hadir untuk membantu para petani dalam mengoptimalkan hasil pertanian dengan penerapan teknologi drone untuk penyemprotan yang didukung oleh evaluasi yang komprehensif dari sisi agronomis dan juga ekologis.&nbsp;</p><div><br></div>', NULL, NULL, '2024-02-28 19:08:41', '2024-02-28 19:08:41');
INSERT INTO `tenant` VALUES (3152, 62, 'public/foto_profil_tenant/65df2299c15b0.jpg', 'Kasihinbaju.id', 'Aldi Gagan Rohmatu Salam', 19, 1, 'Cimahi', NULL, '50.000.000,00', NULL, NULL, NULL, '<p>Kasihinbaju.id merupakan bisnis yang bergerak di bidang social enterprise yang fokus dalam penguraian limbah tekstil dan pemberdayaan ekonomi masyarakat. Produk yang dihasilkan berupa totebag, pouch, hingga pakaian.</p><div><br></div>', NULL, NULL, '2024-02-28 19:10:01', '2024-02-28 19:10:01');
INSERT INTO `tenant` VALUES (3153, 62, 'public/foto_profil_tenant/65df22ec1994a.jpg', 'Omahcetak indonesia', 'Haryo Suryo Kusumo', 42, NULL, 'Jl. Murcoyo 1, RT.14/RW.04, Krajan, Gondanglegi Wetan, Kec. Gondanglegi, Kabupaten Malang', NULL, '50.000.000,00', NULL, NULL, NULL, '<p>Omah Cetak Indonesia atau Omah Creative merupakan bisnis yang&nbsp; bergerak di bidang jasa percetakan, sablon, Merchandise serta digital agency.&nbsp;</p><div><br></div>', NULL, NULL, '2024-02-28 19:11:24', '2024-02-28 19:11:24');
INSERT INTO `tenant` VALUES (3154, 62, 'public/foto_profil_tenant/65df232c2d223.jpg', 'Ecoplast ID', 'Gabriel Butarbutar', 13, NULL, 'Bandung, Jawa Barat', NULL, NULL, NULL, NULL, NULL, '<p>Ecoplat.ID merupakan bisnis yang bergerak di sektor social entrepreneur dengan menciptakan produk pengganti plastik dengan mendaur ulang sampah.</p><div><br></div>', NULL, NULL, '2024-02-28 19:12:28', '2024-02-28 19:12:28');
INSERT INTO `tenant` VALUES (3155, 62, 'public/foto_profil_tenant/65df23fbe4ca0.jpg', 'Ungatawwa Handmade', 'Tenripakkua Bungawalia', 19, 1, 'Jl. Daeng Tata 1 Komp. Depag Tabaria Blok A4 No. 9  Makassar', NULL, '7.500.000,00', NULL, NULL, NULL, '<p>Produk buatan tangan dengan teknik rajut; tas, aksesoris, produk fashion, boneka amigurumi; dengan atau tanpa kombinasi bahan lainnya.&nbsp;</p><div><br></div>', NULL, NULL, '2024-02-28 19:15:55', '2024-02-28 19:15:55');
INSERT INTO `tenant` VALUES (3156, 62, 'public/foto_profil_tenant/65df243b21a14.jpg', 'Ms Artsy', 'Tiara Ika Putri Christianingrum', 19, 1, 'Prum Nusantara Permai Blok B 1 No. 10, Sukabumi, Bandar Lampung, Lampung', NULL, '3.000.000,00', NULL, NULL, NULL, '<p>Ms Artsy hadir dengan produk slow fashion craft berupa tas dan aksesoris handmade dari seni macrame yang menggunakan bahan dasar tali katun premium sehingga biodegradable dan durable in use. Desain yang kami usung menggunakan konsep \"Luxury in Simplicity\" sehingga menghasilkan produk yang unik namun tetap elegan ketika dipakai.</p><div><br></div>', NULL, NULL, '2024-02-28 19:16:59', '2024-02-28 19:16:59');
INSERT INTO `tenant` VALUES (3157, 62, 'public/foto_profil_tenant/65df24917ce6e.jpg', 'Hamka Indonesia', 'Fajri Gufran Zainal', 19, 1, 'Jalan Dr. M. Hatta Koto Tingga, Pasar Ambacang, Kuranji, Kota Padang', NULL, '20.000.000,00', NULL, NULL, NULL, '<p>Pakaian muslim pria modern berupa Koko original, Kimono Shalat, Kimono Songket Minang, Kurta, Jubah, Rompi Shalat</p><div><br></div>', NULL, NULL, '2024-02-28 19:18:25', '2024-02-28 19:18:25');
INSERT INTO `tenant` VALUES (3158, 62, 'public/foto_profil_tenant/65df2959f314d.jpg', 'KawaMala', 'Malasari', 19, 1, 'Jalan Batua Raya 9 No. 15, Makassar, Sulawesi Selatan', NULL, '20.000.000,00', NULL, NULL, NULL, '<p>Tas boba, tas berbahan benang polyester berbentuk kotak ada bulat2 di tiap sisi ada handle dan ada tali panjangnya di rajut jg</p><p>tas wavey, tas berbentuk gelombang atau rempel-rempel, berbahan milk cotton ada handle dan ada tali panjang berbahan kulit sintetis.&nbsp;</p><p>Semua tas menggunakan besi premium dari kancing magnet, besi ring 0 dan besi pengait tali panjang.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:38:49', '2024-02-28 19:38:49');
INSERT INTO `tenant` VALUES (3159, 62, 'public/foto_profil_tenant/65df29d4950a7.png', 'Nyalanesia', 'Lenang Manggala', 42, NULL, 'Jl. Kebangkitan Nasional No.56, Penumping, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57141', NULL, '500.000.000,00', NULL, NULL, NULL, '<p>Nyalanesia adalah startup pengembang program literasi sekolah terpadu, yang memberikan pendampingan dan fasilitas terlengkap bagi mitra sekolah untuk mengembangkan program gerakan literasi sekolah secara efektif, efisien dengan output berupa karya, sertifikat kompetensi dan program apresiasi.&nbsp;</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:40:52', '2024-02-28 19:40:52');
INSERT INTO `tenant` VALUES (3160, 62, 'public/foto_profil_tenant/65df2a1bf3e57.jpg', 'IOTA Kreatif Media', 'Gunawan', 44, NULL, 'Jaya Building 9th Floor, A02, Jl. MH Thamrin No.12, Jakarta Pusat, Indonesia 10340', NULL, '200.000.000,00', NULL, NULL, NULL, '<p>IOTA Kids Apps - Platform untuk anak Preschool sampai SD, didalamnya tersedia banyak pilihan aktivitas untuk menunjang tumbuh kembang anak seperti motion storybook, permainan/game, aktivitas (mewarnai, menggambar, senam/dance, menyanyi, keterampilan, dll), merchandise store dll.&nbsp;</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:42:03', '2024-02-28 19:42:03');
INSERT INTO `tenant` VALUES (3161, 62, 'public/foto_profil_tenant/65df2a684740f.jpg', 'Lombok Kuning Simpati', 'Melyana Khohari', 23, NULL, 'Jl. Sulawesi No.204, Melayu Baru,  Kec. Wajo, Kota Makassar,  Sulawesi Selatan 90171', NULL, '150.000.000,00', NULL, NULL, NULL, '<p>Lombok Kuning Simpati adalah saos sambel tradisional dengan ciri khas daerah yang memiliki citarasa unik dari kawasan timur Indonesia. Lombok kuning simpati dibuat dari perpaduan dari cabe rawit segar yang diolah dengan bahan bahan berkualitas menggunakan resep yang telah turun temurun sehingga menghasilkan rasa unik pedas asin kecut yang bercampur dengan aroma bawang putih yang menggoda.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:43:20', '2024-02-28 19:43:20');
INSERT INTO `tenant` VALUES (3162, 62, 'public/foto_profil_tenant/65df2ab254034.jpg', 'Pukis Badran', 'Renata Zoraifi', 23, NULL, 'Jl. Kenanga 25 Badran Solo', NULL, '100.000.000,00', NULL, NULL, NULL, '<p>Pukis Badran merupakan pukis premium yang diolah dengan komposisi bahan pilihan, dimana bahan tersebut merupakan bahan yang halalan toyiban. Hal ini dibuktikan dengan pencantuman logo Halal resmi dari pemerintah setelah melalui tahapan dikatakan sebagai makanan halal.</p><p><br></p><p>Saat ini, Pukis Badran memiliki 3 produk utama, yaitu Pukis Badran, Pulis Cup dan Minuman Goelasem</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:44:34', '2024-02-28 19:44:34');
INSERT INTO `tenant` VALUES (3163, 62, 'public/foto_profil_tenant/65df2b344d1f6.jpg', 'Moringa Good', 'Ginanjar Widya Pamungkas', 23, NULL, 'Probolinggo, Jawa Timur', NULL, '10.000.000,00', NULL, NULL, NULL, '<div><font face=\"Montserrat\" color=\"#000000\"><span style=\"font-size: 16px;\">Moringa Good adalah perusahaan sosial yang mengolah dan memproses pangan berbasis tumbuhan kelor serta bergerak dengan nilai pangan yang sehat dan proses rantai yang berkelanjutan. Mi Instan Kelor adalah salah satu flagship produk yang dirilis di pasar saat ini, dibuat dengan bahan alami tanpa menggunakan MSG dan pengawet</span></font></div><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:46:44', '2024-02-28 19:46:44');
INSERT INTO `tenant` VALUES (3164, 62, 'public/foto_profil_tenant/65df2b6eca439.jpg', 'Dapur Cimorama', 'Isnawarika ilyas', 23, NULL, 'Jl Faisal Raya 2 No 52   Makassar', NULL, '8.000.000,00', NULL, NULL, NULL, '<p>Dapur cimorama bergerak di bidang kuliner, produk unggulan kami yaitu nasi kuning dimana nasi kuning yg kami buat ini beda dari nasi kuning pada umumnya, baik dr segi rasa maupun mutunya.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:47:42', '2024-02-28 19:47:42');
INSERT INTO `tenant` VALUES (3165, 62, 'public/foto_profil_tenant/65df2ba84d83c.jpg', 'Sanfood Brilian', 'Eka Risky Septiani', 23, NULL, 'Cisauk, Tangerang', NULL, '100.000.000,00', NULL, NULL, NULL, '<p>PT. Sanfood Brilian Indonesia adalah industri pangan olahan yang memproduksi makanan sehat di tujukan untuk segala usia.</p><p>Ragam produk kami mencakup bumbu masak, sereal, pasta, aromatic oil juga aneka produk olahan lainnya yang mengakomodir kebutuhan kaum urban dan menunjang \"healty life style\".</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:48:40', '2024-02-28 19:48:40');
INSERT INTO `tenant` VALUES (3166, 62, 'public/foto_profil_tenant/65df2d96ecb32.jpg', 'Jiwanta', 'Fajar alam islami', 23, NULL, 'Perum De Cluster Kav 8, Pisang kipas, Malang', NULL, '3.000.000,00', NULL, NULL, NULL, '<p>Jiwanta hadir dengan mengusung konsep artisan tea local premium, selain hal tersebut jiwanta memiliki harga yang affordable bagi kelas teh premium. Teh yang berada di dalam kemasan jiwanta memiliki standar yang tinggi yaitu Teh kelas 1 hingga 3. Standart ini pada umumnya sering di ekspor oleh perkebunan teh lokal. Harapan adanya jiwanta dapat mengenalkan teh premium Nusantara kepada seluruh masyarakat Indonesia ataupun dunia.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:56:54', '2024-02-28 19:56:54');
INSERT INTO `tenant` VALUES (3167, 62, 'public/foto_profil_tenant/65df2dd150a21.jpg', 'Bina rasa Bakery', 'Maya Sari', 23, NULL, 'Jl. Pampang 2 No. 42 Makassar, Sulawesi Selatan', NULL, '4.000.000,00', NULL, NULL, NULL, '<p>Bina Rasa Bakery merupakan bisnis yang bergerak di sektor FnB dengan menjual roti Sehat tanpa Bahan Pengawet seperti roti abun, roti keju, hingga cake.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:57:53', '2024-02-28 19:57:53');
INSERT INTO `tenant` VALUES (3168, 62, 'public/foto_profil_tenant/65df2e1987e6c.jpg', 'Lapak Cindo', 'Zuhandri, S.T', 23, NULL, 'Jl Raya Sumberjaya No A.13 Tambun Selatan Kabupaten Bekasi', NULL, '140.000.000,00', NULL, NULL, NULL, '<p>Lapak Cindo merupakan brand lokal asli Indonesia yang bergerak dibidang pengolahan ikan. Mulai supply chain yaitu produsen ikan giling dan olahannya seperti pempek, tekwan, model, kerupuk kemplang, dan lainnya.&nbsp;</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 19:59:05', '2024-02-28 19:59:05');
