INSERT INTO `tenant` VALUES (3173, 62, 'public/foto_profil_tenant/65df2f30df8b0.jpg', 'UMEDS', 'Alif Andika Sutadi Saputra', 43, NULL, 'Eighty Eight Kasablanka, Office Tower, Jl. Raya Casablanca Raya No.Kav. 88,, Kota Jakarta Selatan', NULL, '42.000.000,00', NULL, NULL, NULL, '<p>UMEDS (sebelumnya Ummacademy) adalah platform all-in-one untuk pembelajaran digital dalam ilmu kedokteran dan kesehatan.</p><p>UMEDS memberi siswa pengetahuan dasar medis dan bimbingan klinis instan dan on-the-go dengan sistem pembelajaran asinkron dan sinkron untuk menerapkan Pembelajaran Aktif Berpusat Siswa (SCL).</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:03:44', '2024-02-28 20:03:44');
INSERT INTO `tenant` VALUES (3174, 62, 'public/foto_profil_tenant/65df2f7040ff0.jpg', 'betukang.id', 'dezan taruna jaya', 29, NULL, 'Jalan  Sultan Syahrir Abdurahman, Gedung Pelni Coworking Space Diamond', NULL, '30.000.000,00', NULL, NULL, NULL, '<p>betukang.id adalah aplikasi pemesanan jasa tukang online yang memudahkan pemanggilan jasa tukang dan memudahkan para tukang mendapatkan pekerjaan di era digital saat ini.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:04:48', '2024-02-28 20:04:48');
INSERT INTO `tenant` VALUES (3175, 62, 'public/foto_profil_tenant/65df2faf811ab.jpg', 'Arsibro', 'Apriansyah Saputra', 29, NULL, 'Serpong Jaya Cluster The Groove Blok GV/B28', NULL, '10.000.000,00', NULL, NULL, NULL, '<p>Arsibro adalah sebuah startup marketplace yang bergerak di bidang arsitektur, desain interior serta eksterior yang melayani kebutuhan untuk 2 subject yaitu society dan&nbsp; community. Society adalah masyarakat yang memiliki keinginan untuk memperoleh sebuah ruang atau bangunan yang nyaman sesuai keinginan mereka tetapi dengan harga terjangkau.&nbsp;</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:05:51', '2024-02-28 20:05:51');
