INSERT INTO `tenant` VALUES (3177, 62, 'public/foto_profil_tenant/65df2ff4eb95e.jpg', 'Link Productive', 'Gerry Anugrah Dwiputra', 42, NULL, 'Ruko BBS III, Blok B3, No.9, Kelurahan Ciwaduk, Kecamatan Cilegon, Kota Cilegon, Provinsi Banten', NULL, '20.000.000,00', NULL, NULL, NULL, '<p>Kami adalah suatu platform digital terintegrasi yang mempertemukan mahasiswa, siswa, pencari kerja, sekolah, universitas, perusahaan, UMKM, dan pemerintah agar dapat meningkatkan produktivitas yang berwawasan hijau dari masing-masing stakeholder sehingga mampu mengurangi sampah plastik, dan daur ulang sampah, meningkatkan kualitas pendidikan SMK &amp; Universitas.&nbsp;</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:07:00', '2024-02-28 20:07:00');
