INSERT INTO `tenant` VALUES (3179, 62, 'public/foto_profil_tenant/65df3035a08a8.jpg', 'Nikahyuk', 'Deni Fathul Aziz', 42, NULL, 'Jalan Baypass Zamia 2, Kawasan Inkubasi Bisnis BRIDA NTB, desa lelede', NULL, '25.000.000,00', NULL, NULL, NULL, '<p>Nikahyuk adalah sebuah platform berbasis marketplace yang memudahkan seseorang untuk mempersiapkan pernikahannya, dari booking paket pernikahan, bulan madu sampai cari pasangan dalam satu aplikasi.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:08:05', '2024-02-28 20:08:05');
