INSERT INTO `tenant` VALUES (3181, 62, 'public/foto_profil_tenant/65df315960560.jpg', 'Inorder', 'Inorder', 42, NULL, 'Jl. Pampang 2 No. 42, Kalimantan Timur', NULL, '5.000.000,00', NULL, NULL, NULL, '<p>Aplikasi webapp yang dapat melakukan pemesanan dan juga pembayaran yang mudah melalui scan kode QR dengan tampilan yang menarik dan mudah digunakan.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:12:57', '2024-02-28 20:12:57');
INSERT INTO `tenant` VALUES (3182, 62, 'public/foto_profil_tenant/65df3192588c9.jpg', 'GELATAH', 'GELATAH', 30, NULL, 'Surabaya, Jawa Timur', NULL, '14.000.000,00', NULL, NULL, NULL, '<p>GELATAH merupakan bahan bakar semi padat atau gel berbahan baku minyak jelantah yang ramah lingkungan dan zero waste. Berdasarkan hasil pengujian, produk ini lebih cepat memadat setelah dipanaskan, tahan ±7 jam, kualitas api lebih memusat, daya tahan api lebih stabil, serta tidak mengeluarkan jelaga, abu langu dan leaking pada kaleng.</p><div><br></div>', '2023-02-02', '2023-05-30', '2024-02-28 20:13:54', '2024-02-28 20:13:54');
