INSERT INTO `tenant` VALUES (3184, 62, NULL, 'Haripanen', 'Mamba’ul Ulum', 2, 2, 'Temanggung, Indonesia', NULL, NULL, NULL, NULL, NULL, '<p>\r\n\r\n\r\n\r\n\r\n\r\n<!--StartFragment-->\r\n\r\n\r\n\r\n<!--EndFragment--></p><p style=\"language:en-ID;line-height:115%;margin-top:0pt;margin-bottom:0pt;\r\nmargin-left:0in;margin-right:0in;text-indent:0in;text-align:justify;text-justify:\r\ninter-ideograph;direction:ltr;unicode-bidi:embed\"><span style=\"font-size:12.0pt;\r\nfont-family:&quot;Quattrocento Sans&quot;;mso-ascii-font-family:&quot;Quattrocento Sans&quot;;\r\nmso-fareast-font-family:&quot;Quattrocento Sans&quot;;mso-bidi-font-family:&quot;Quattrocento Sans&quot;;\r\nfont-variant:normal;color:black;text-transform:none;language:en-ID;font-weight:\r\nnormal;font-style:normal;mso-style-textfill-type:solid;mso-style-textfill-fill-color:\r\nblack;mso-style-textfill-fill-alpha:100.0%\">Haripanenise</span><span style=\"font-size:12.0pt;font-family:&quot;Quattrocento Sans&quot;;mso-ascii-font-family:\r\n&quot;Quattrocento Sans&quot;;mso-fareast-font-family:&quot;Quattrocento Sans&quot;;mso-bidi-font-family:\r\n&quot;Quattrocento Sans&quot;;font-variant:normal;color:black;text-transform:none;\r\nlanguage:en-ID;font-weight:normal;font-style:normal;mso-style-textfill-type:\r\nsolid;mso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%\">-commerce\r\nfor an agricultural, healthy lifestyle, and rural tourism. </span><span style=\"font-size:12.0pt;font-family:&quot;Quattrocento Sans&quot;;mso-ascii-font-family:\r\n&quot;Quattrocento Sans&quot;;mso-fareast-font-family:&quot;Quattrocento Sans&quot;;mso-bidi-font-family:\r\n&quot;Quattrocento Sans&quot;;font-variant:normal;color:black;text-transform:none;\r\nlanguage:en-ID;font-weight:normal;font-style:normal;mso-style-textfill-type:\r\nsolid;mso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%\">Haripanen</span><span style=\"font-size:12.0pt;font-family:&quot;Quattrocento Sans&quot;;mso-ascii-font-family:\r\n&quot;Quattrocento Sans&quot;;mso-fareast-font-family:&quot;Quattrocento Sans&quot;;mso-bidi-font-family:\r\n&quot;Quattrocento Sans&quot;;font-variant:normal;color:black;text-transform:none;\r\nlanguage:en-ID;font-weight:normal;font-style:normal;mso-style-textfill-type:\r\nsolid;mso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%\">\r\nprovides fresh, organic produce from the farm to the consumer doorstep (farm to\r\nfork). We aim a healthy lifestyle, easy purchase, and affordable produce for\r\nconsumers, also helping the growers to level up their business. With </span><span style=\"font-size:12.0pt;font-family:&quot;Quattrocento Sans&quot;;mso-ascii-font-family:\r\n&quot;Quattrocento Sans&quot;;mso-fareast-font-family:&quot;Quattrocento Sans&quot;;mso-bidi-font-family:\r\n&quot;Quattrocento Sans&quot;;font-variant:normal;color:black;text-transform:none;\r\nlanguage:en-ID;font-weight:normal;font-style:normal;mso-style-textfill-type:\r\nsolid;mso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%\">Haripanen</span><span style=\"font-size:12.0pt;font-family:&quot;Quattrocento Sans&quot;;mso-ascii-font-family:\r\n&quot;Quattrocento Sans&quot;;mso-fareast-font-family:&quot;Quattrocento Sans&quot;;mso-bidi-font-family:\r\n&quot;Quattrocento Sans&quot;;font-variant:normal;color:black;text-transform:none;\r\nlanguage:en-ID;font-weight:normal;font-style:normal;mso-style-textfill-type:\r\nsolid;mso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%\">,\r\nwe can cut the long and complicated food distribution.</span></p>', '2020-10-15', '2020-10-15', '2024-02-28 20:22:47', '2024-02-28 20:22:47');
