INSERT INTO `tenant` VALUES (3219, 189, NULL, 'Mitra Deceng Team', 'Tahrir Nurhidayat', 23, 2, 'Desa Dampang (Samping Lapangan),  Kec. Gantarang, Kab. Bulukumba', NULL, NULL, NULL, NULL, NULL, NULL, '2021-06-27', '2021-12-26', '2024-03-07 10:48:55', '2024-03-07 10:48:55');
INSERT INTO `tenant` VALUES (3220, 473, 'public/foto_profil_tenant/65ecb5956d56e.jpg', 'KONVERSI KE MODEL KOPERASI MULTIPIHAK', 'KOPERASI NGAW TANI MANDIRI', 1, 2, 'Jalan Kartini No.25 Ngawi', NULL, '1.100.000.000,00', 'online offline', 'nasional', NULL, '<p>Koperasi Produsen Ngawi Tani Mandiri beranggotakan dari hampir 70% Petani dan selebihnya dari pengusaha, ahli dan pemerhati pertanian. Jenis koperasi produsen yang juga terdiri dari kelompok-kelompok yang heterogen,&nbsp; bukan hanya homogen dari petani. dengan demikian bisnis koperasi dalam menjual beli produk anggota petani menjadi lebih efisien dengan adanya pembagian tugas sesuai potensi anggota. Model ini lebih sesuai dengan Koperasi Multipihak sehingga semua anggota dapat berkontribusi sesuai potensi masing-masing dan pengambilan keputusan menjadi lebih cepat sehingga bisnis koperasi dapat menjadi lebih baik. Dalam Proses inkubasi ini, Inbis Cah Angon membantu dalam proses konversi dari Konvensional menuju Multipihak serta membantu menyusun rencana Perubahan Anggaran Dasar. Karena Anggaran dasar dari Kop. NTM tidak sesuai dengan jenis koperasi saat ini dan banyak sekali salah ketik dan salah tulis yang dilakukan oleh Notaris. kami telah berdiskusi&nbsp; aktif dengan Dinas Koperasi dan UKM Kab. Ngawi dalam proses ini dan turut menghadirkan salah satu pengagas Koperasi Multipihak di Indonesia dari ICCN yaitu mas Firdaus Putra. Kop. NTM juga telah mengikuti pembinaan tentang Koperasi Multipihak dari Kementrian Koperasi dan UKM RI.&nbsp;</p>', '2024-02-01', '2024-06-30', '2024-03-10 02:14:13', '2024-03-11 00:38:20');
INSERT INTO `tenant` VALUES (3221, 85, 'public/foto_profil_tenant/65f292857ea2c.JPG', 'akademik.co.id', 'Ahmad Sa`di', NULL, NULL, 'Graha Univ. AMIKOM Yogyakarta, Gedung 2, lantai 2, Jl. Padjajaran, Ring Road Utara, Kel. Condongcatur, Kec. Depok, Kab. Sleman', NULL, NULL, 'akademik.co.id Instagram, Whatshapp', NULL, NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Sistem Informasi Sekolah Terpadu, untuk digitalisasi Sekolah. Mendukung kurikulum K13 dan Kurikulum merdeka</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-14 13:00:37', '2024-03-14 13:06:54');
INSERT INTO `tenant` VALUES (3222, 85, 'public/foto_profil_tenant/65f29c8f3e3d6.JPG', 'Cokisku', 'Puryaningsih', 23, 2, 'Kentungan Condongcatur Depok Sleman Yogyakarta', NULL, '12.000.000,00', 'Instagram, Facebook, Whatshapp', 'Lokal, Lintas Provinsi', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Buah Kurma tanpa Biji yang diisi menggunakan filling rasa seperti coklat, vanilla, tiramisu, greentea dan taro untuk bagian luarnya di lapisi dengan coklat dark </span></p><p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Cokisku adalah merek produk yang kami pasarkan,  nama usaha kami Barak Patndolu tahun berdiri 2019, cokisku salah satu produk yang berbahan baku dari kurma tanpa biji yang diisi dengan filling rasa seperti Coklat, keju, vanila, tiramisu, greentea, taro dan bagian luarnya dilapisi menggunakan coklat compound, dengan harga 25.000 per pouch dan netto 150gram, Cokisku sudah tersedia di beberapa pusat oleh2 di Jogjakarta diantaranya \r\n1. Bandara YIA\r\n2. Koperasi JPN \r\n3. Hamzah Batik\r\n4. Bakpia Djokem\r\n5. Je jamuran dan masih banyak lagi \r\nselain itu Barak Patndolu juga memproduksi kue kering, cake dan tart dengan sistem pre order. </span><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span><br></p>', '2022-08-27', '2023-02-27', '2024-03-14 13:42:44', '2024-03-22 13:46:17');
INSERT INTO `tenant` VALUES (3223, 85, 'public/foto_profil_tenant/65f2a0ffe0e46.jpg', 'Yang-Ti', 'Andrianto Soeristyo Soerahmad', 23, 2, 'Perum II Jln Jeruk D36 Sidoarum Godean Sleman DIY', NULL, '65.000.000,00', 'Instagram, Facebook, Whatshapp', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><font color=\"#1f1f1f\" face=\"IBM Plex Sans\"><span style=\"font-size: 12px; white-space-collapse: preserve;\">Sirup dan Minuman Rempah</span></font></p><p><span style=\"font-family: Arial;\">Yang-Ti adalah singkatan kata eYANG puTrI&nbsp;</span><br></p><p>Dedikasi kepada sosok seorang Ibu sepuh yang ubet ulet berusaha mandiri, istiqomah dalam mengisi kegiatan di usia lanjutnya. Teringat akan sosok Ibu Sepuh yang penuh kasih sayang, nuansa Jawa, Rindu, Rumah dan Pulang. Melestarikan resep turun temurun yang beliau miliki, melintas dari generasi ke generasi. Ternyata Ramuan ini bisa menghangatkan badan, stamina, dan mood booster.</p>', '2022-08-27', '2023-02-27', '2024-03-14 14:02:23', '2024-03-14 14:02:23');
INSERT INTO `tenant` VALUES (3224, 85, 'public/foto_profil_tenant/65f2a2a3263e6.JPG', 'Dropzhip', 'Bagus Tri Hartono', NULL, NULL, 'Jl. Apel RT 03/03 Desa Gombolharjo Kec.Adipala Kab.Cilacap', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Startup Aplikasi E-COMMERCE B2B</span><br></p>', '2022-08-27', '2022-08-27', '2024-03-14 14:09:23', '2024-03-14 14:09:23');
INSERT INTO `tenant` VALUES (3225, 85, 'public/foto_profil_tenant/65f2aaf94c2ff.png', 'Zamzamy', 'Rizky', NULL, NULL, 'Jalan rajawali raya no 6 D, manukan, sleman, yogyakarta', NULL, NULL, 'https://sebangku.co.id/ Instagram, Facebook, Whatshapp', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Zamzamy merupakan boardgame edukasi untuk memperkenalkan anak-anak tentang belajar huruf-huruf hijaiyah melalui permainan yang menarik dan menyenangkan</span><br></p>', '2019-03-21', '2019-11-15', '2024-03-14 14:43:06', '2024-03-14 14:44:57');
INSERT INTO `tenant` VALUES (3226, 85, 'public/foto_profil_tenant/65f2af432f1aa.jpeg', 'SayBu', 'Aji suryo jatmiko', 2, 2, 'Dsn Gendingan RT 05 RW012, Tirtomartani Kalasan Sleman', NULL, NULL, 'Saybu.id Instagram, Facebook, Whatshapp', NULL, NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">SayBu merupakan usaha dibidang pertanian, dimana produk unggulan SayBu merupakan Sayur Siap Masak. Sayur siap masak merupakan paket sayur yang teridiri dari beberapa sayuran, yang sudah dibersihkan dipotong plus bumbu yang sudah tersedia, sehingga mempersingkat waktu memasak.</span><br></p>', '2020-03-13', '2020-09-14', '2024-03-14 15:03:15', '2024-03-14 15:03:15');
INSERT INTO `tenant` VALUES (3227, 85, 'public/foto_profil_tenant/65f2b4899b50b.png', 'RAPO', 'Wakhid Wijaya', NULL, NULL, 'Mandungan RT 03, Sriamrtani, Piyungan, Bantul, Yogyakarta 55792', NULL, NULL, 'https://rapo.online Instagram, Facebook, Twitter, Whatshapp', NULL, NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Rapo adalah one stop solution platform untuk memberikan kemudahan stakeholder sekolah dalam mejalankan dan memanajemen pelaksanaan pembelajarannya. Tujuan utama rapo adalah membantu guru lebih nyaman dan lebih cepat dalam bekerja menggunakan kekuatan teknologi.</span><br></p>', '2020-03-13', '2020-09-14', '2024-03-14 15:25:45', '2024-03-14 15:25:45');
INSERT INTO `tenant` VALUES (3228, 85, 'public/foto_profil_tenant/65f2b766909e1.jpg', 'Pejalan', 'Donang Wahyu', 41, 5, '18 Office Park Building 12th Floor Unit A & H, Jl. TB Simatupang No.Kav. 18, RT.2/RW.1, Pasar Minggu, Jakarta Selatan - 12520', NULL, NULL, 'https://pejalan.id https://pejalan.id', 'Lintas Provinsi', NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Ekosistem pariwisata berbasis komunitas\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Aplikasi ekosistem pariwisata digital berbasis komunitas yang menghubungkan wisatawan satu dengan yang lain untuk saling berbagi informasi (Foto, Video, Artikel), menjual paket wisata, reservasi, dan memberikan rekomendasi lokasi wisata khususnya di Indonesia.</span><br></p>', '2021-05-10', '2021-12-10', '2024-03-14 15:37:58', '2024-03-14 15:37:58');
INSERT INTO `tenant` VALUES (3229, 85, 'public/foto_profil_tenant/65f2b8fa7f63f.jpg', 'Roomansa', 'Renesa Balqis', 43, 2, 'Lippo Village Sektor 3 Blok B23 No.16', NULL, '15.000.000,00', 'www.roomansa.id Instagram, Facebook, Twitter, Whatshapp', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Arial Black&quot;; font-size: 12px; white-space-collapse: preserve;\">Family Mental Health Services</span></p><p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Platform komunitas untuk keluarga muda dengan layanan konsultasi, teman dengar, dan kelas yang membahas seputar topik Parenting, Family Wellness, dan Mental Health.\r\nSudah berbentuk badan usaha PT</span></p>', '2021-05-10', '2021-12-10', '2024-03-14 15:44:42', '2024-03-20 11:37:47');
INSERT INTO `tenant` VALUES (3230, 85, 'public/foto_profil_tenant/65f2baf9e1251.png', 'Kodekarta', 'Rohmad Fajarudin', NULL, NULL, 'Kemantren 13/04, Bulurejo, Juwiring, Klaten', NULL, NULL, 'https://kodekarta.com Instagram', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Kodekarta adalah aplikasi web yang menyediakan tantangan praktikal untuk mereka yang sedang belajar pemrograman. Kodekarta menyediakan Jalan Pintas Mencapai Mastery. Jalan pintas ini berupa Problem Exercise yang dapat diakses secara gratis, Peer Review untuk belajar dari sesama, lalu Mentorship untuk belajar langsung dari mereka yang membuat problem exercise tersebut. Kodekarta bersifat community-driven, ini memberikan kelebihan berupa konten yang selalu up-to-date lebih cepat dengan perkembangan.</span><br></p>', '2021-05-10', '2021-12-10', '2024-03-14 15:53:13', '2024-03-14 15:53:13');
INSERT INTO `tenant` VALUES (3231, 85, 'public/foto_profil_tenant/65f2c123797c2.JPG', 'BOTANG', 'Hafidh Dody Prasetya', NULL, NULL, 'Perumahan Tambak Mas no. 71, Ngestiharjo, Kasihan, Bantul, DIY', NULL, '15.000.000,00', 'Www.pandawatech.com Instagram, Facebook, Whatshapp', 'Lokal, Ekspor, Lintas Provinsi', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Botang adalah Robot Angkut jenis Automated Guided Vehicle yang berfungsi untuk alat bantu handling material di bidang logistik maupun manufaktur. Material BOTANG 80% dalam negeri, Tenaga Kerja 100% dalam negeri, menjadikan BOTANG sebagai robot produksi dalam negeri. Untuk pengembangan baik hardware maupun software juga 100% dikerjakan oleh tim Pandawatech, sehingga sangat mudah bagi BOTANG untuk dikembangkan sesuai keinginan customer.</span><br></p>', '2021-07-30', '2021-11-30', '2024-03-14 16:19:31', '2024-03-14 16:19:31');
INSERT INTO `tenant` VALUES (3232, 85, 'public/foto_profil_tenant/65f7a66a6a02d.JPG', 'INAERO-AEROpro', 'Christy Aryani Sunaryo', NULL, NULL, 'Jl. Bantul Km.5, Kweni Rt.03 Sewon Bantul Daerah Istimewa Yogyakarta', NULL, '150.000.000,00', 'inaero.id Instagram, Facebook, Whatshapp, Youtube', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">INAERO memiliki beberapa produk drone dengan merek dagang AEROpro. \r\nAEROpro di desain dengan aerodinamika yang akurat dan diproduksi dengan teknologi yang menghasilkan produk airframe yang presisi, sebagai solusi teknologi otomatisasi. Selain digunakan dalam bidang pertahanan keamanan, teknologi AEROpro yang dilengkapi dengan system autonomous dapat diaplikasikan dalam bidang konstruksi, pertanian, perkebunan, perikanan, lingkungan hidup dan kehutanan, pertambangan, dan kebencanaan.</span><br></p>', '2019-03-21', '2019-11-15', '2024-03-18 09:26:50', '2024-03-18 09:26:50');
INSERT INTO `tenant` VALUES (3233, 85, 'public/foto_profil_tenant/65f7aa73469aa.png', 'Gizipedia Indonesia', 'Hafizhatunnisa', NULL, NULL, '-', NULL, NULL, 'Tokopedia, Shopee', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Gizipedia Indonesia adalah platform edukasi gizi bagi masyarakat dan calon ahli gizi Indonesia.\r\n\r\nPertama kali didirikan pada 29 April 2019 di Yogyakarta oleh Hafizhatunnisa, S.Gz kemudian kedua temannya Ayu Fauziyyah Adhimah, S.Gz dan Yusrina Husnul, S.Gz bergabung menjadi co-founder setengah tahun setelahnya. Gizipedia telah mendapatkan penghargaan dari PERSAGI (Persatuan Ahli Gizi Indonesia) dalam pengabdian edukasi gizi untuk masyarakat, mendapatkan pelatihan kelas Track SDGs 2020 dari Center for Indonesia’s Strategic Development Initiatives (CISDI) dan Oxfam, selain itu Sehatin, aplikasi konsultasi berserta meal plan personal yang sedang dikembangkan Gizipedia mendapatkan kesempatan inkubasi dan mentoring selama satu tahun di Amikom Business Park.\r\n\r\nSaat ini tim inti Gizipedia masih terus bertambah untuk mengembangkan beragam buku dan prototype untuk memperluas jangkauan edukasi gizi demi terwujudnya Indonesia yang sehat dan kuat.\r\n</span>Sudah berbadan Usaha PT</p>', '2020-03-13', '2020-09-14', '2024-03-18 09:44:03', '2024-03-18 09:44:03');
INSERT INTO `tenant` VALUES (3234, 85, 'public/foto_profil_tenant/65f7ad57c678e.png', 'EGROTEK', 'Sigit Pramono, ST,MT', NULL, NULL, 'PERUM BUMI CITRA LESTARI BLOK A14 PURWOKERTO 53145', NULL, '49.600.000,00', 'www.egrotek.com Instagram, Facebook, Youtube, Tiktok', 'Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Sistem monitoring dan kontrol  kelembaban kumbung jamur tiram berbasis Internet of Things (IoT) merupakan solusi baru dalam pengendalian kelembaban pada kumbung jamur.  Perangkat ini memadukan antara otomatisasi Nozzle Sprayer dan teknologi Internet of  Things sehingga kelembaban dapat dimonitoring dan real time dari jarak jauh dan pompa Nozle Spayer dikendaliakan dari Cloud (internet). Layout komponen sisi depan berisi LCD dan Keypad sedangkan sisi belakang berisi modem GSM dan Relay modul serta Embedded System berbasis Microcontroller ATmega328 dengan Clock Speed sebesar 16 MHz, kapasitas SRAM 2 KB dan Flash Memory 32 KB. Sistem masih terpisah menjadi beberapa module dan  koneksi antar module menggunakan kabel jumper sehingga rentan gangguan.</span></p><p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">PT EGROTEK KARSA UTAMA</span><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span><br></p>', '2019-03-21', '2019-11-15', '2024-03-18 09:56:23', '2024-03-18 09:56:23');
INSERT INTO `tenant` VALUES (3235, 85, 'public/foto_profil_tenant/65f7c0dc3168c.png', 'FOTY - Keyboard Kaki dan Mouse Kaki', 'Moch Farid Fauzi', NULL, NULL, 'Jalan Pamularsih, RT.6/RW.38, Sinduharjo, Ngaglik, Sleman, Yogyakarta', NULL, NULL, 'https://keyboardfoty.id/  Tokopedia, Shopee', 'Lintas Provinsi', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">FOTY (Keyboard dan Mouse Kaki Untuk Tunadaksa) adalah Keyboard dan mouse yang didesain khusus untuk dapat dengan mudah dan nyaman digunakan dengan kaki. Keyboard dan Mouse Kaki. Tidak seperti keyboard dan mouse pada umumnya yang didesain untuk tangan, produk ini memiliki bentuk, ukuran, dan tata letak tombol yang sesuai untuk dioperasikan dengan kaki.</span><br></p>', '2021-07-30', '2021-11-30', '2024-03-18 11:18:06', '2024-03-18 11:19:40');
INSERT INTO `tenant` VALUES (3236, 85, 'public/foto_profil_tenant/65f7c2c17a15f.JPG', 'DAPURGO', 'Eka Setyawati', NULL, NULL, 'Kliwonan, Rt 02, Rw 17 Sidorejo Godean Sleman', NULL, NULL, 'Instagram, Facebook, Whatshapp www.dapurgo.com', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">PT. DAPURGO TEKNO TAMA\r\n</span><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Food Innovation Superapp</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-18 11:27:45', '2024-03-18 11:27:45');
INSERT INTO `tenant` VALUES (3237, 85, 'public/foto_profil_tenant/65f7e9531ccbb.png', 'VILABS', 'Ambar Setyawan', NULL, NULL, 'Jatimas Permai K22, Jatisawit, Balecatur, Kec. Gamping, Kabupaten Sleman, Daerah Istimewa Yogyakarta 55292', NULL, '500.000.000,00', 'instagram.com/vilabsid www.vilabs.id', 'Nasional', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Virtual Experience Tech Company\r\n▫️AR VR\r\n▫️AI Hologram\r\n▫️Immersive Projection\r\n▫️Interactive Tech</span><br></p>', '2023-04-07', '2023-11-07', '2024-03-18 14:12:19', '2024-03-22 16:18:16');
INSERT INTO `tenant` VALUES (3238, 85, 'public/foto_profil_tenant/65f7f8486a642.jpg', 'TemanGuru', 'Moch. Mutawakkil A, Aisyah Astri Damayanti, Titan Bagus Bramantyo', NULL, NULL, 'Jl. Padjajaran, Ring Road Utara, Kel. Condongcatur, Kec. Depok, Kab. Sleman, Prop. Daerah Istimewa Yogyakarta 55283', NULL, '10.000.000,00', 'https://teman-guru.com/ https://www.instagram.com/teman_guru/ https://www.linkedin.com/company/74706208/admin/feed/posts/', 'Regional (Provinsi)', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">TemanGuru merupakan salah satu startup binaan ABP Incubator  dalam bidang Teknologi pendidikan. kita mempunyai 2 program yaitu mengajar guru dan teman belajar ini, mengajar guru itu pelayanan mengajar guru khususnya dalam bidang teknologi yang menawarkan offline training secara langsung dan konsultasi selamanya kepada guru dengan dapat sepenuhnya di nikmati secara gratis tagline kami Improve and Empower Teacher Quality</span><br></p>', '2021-05-10', '2021-12-10', '2024-03-18 15:16:08', '2024-03-18 15:16:08');
INSERT INTO `tenant` VALUES (3239, 85, 'public/foto_profil_tenant/65f7f927b8fd4.jpeg', 'Sayur Sleman', 'Janu Muhammad', NULL, NULL, 'Caturharjo, Sleman, DIY 55515', NULL, '100.000.000,00', 'www.sayursleman.id / IG sayursleman.id', 'Nasional', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Sayur Sleman menyediakan produk sayur dan melon hidroponik untuk individu dan pelaku usaha, menyediakan jasa pelatihan dan konsultasi agribisnis.</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-18 15:19:51', '2024-03-18 15:19:51');
INSERT INTO `tenant` VALUES (3241, 85, 'public/foto_profil_tenant/65f8f1f4465b9.png', 'Dcreativ Indonesia', 'Muhammad Adnan Rizki Issanjaya', NULL, NULL, 'Jl. Telekomunikasi, Universitas Telkom, Bandung', NULL, '10.000.000,00', NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Layanan pesan antar makan area telkom university dan percetakan</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-19 09:01:24', '2024-03-19 09:15:14');
INSERT INTO `tenant` VALUES (3242, 85, 'public/foto_profil_tenant/65f8f8cbd1e10.PNG', 'HICO – HYBRID SMART CONTROLLER', 'Pendi Ventri Hendika', NULL, NULL, 'Jl. Paingan 4 No. 105 RT 05/05 Maguwoharjo, Kab. Sleman, Yogyakarta.', NULL, NULL, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Sistem HICO menggunakan teknologi terbaru dalam pengaplikasiannya. Pemilihan ini didasarkan pada kebutuhan akan adanya aplikasi yang mudah digunakan, mudah diakses di berbagai tempat, komunikasi data yang baik dalam kondisi jaringan terbatas dan keamanan sistem yang baik. Kemudahan yang diinginkan dari user adalah aplikasi yang mudah digunakan, informatif dan mudah diakses. Sedangkan dari sisi developer produk menginginkan aplikasi yang terjaga kerahasiaan datanya, kejelasan alur kerja, kemudahan komunikasi data antar device dan tersedianya tools atau alat yang memudahkan sistem mengontrol device</p>', '2016-06-06', '2016-11-06', '2024-03-19 09:30:35', '2024-03-19 09:30:35');
INSERT INTO `tenant` VALUES (3243, 85, 'public/foto_profil_tenant/65f8fce946b08.PNG', 'Dengerin Indonesia', 'Evi Yulian Safitri', NULL, NULL, 'Jl. Perum Purwo Asri No. D706, Purwomartani, Kalasan, Sleman', NULL, NULL, NULL, NULL, NULL, '<p>Dengerin.id adalah platform belajar dan pengelolaan kelas secara digital yang menyediakan materi pelajaran dalam 2 gaya belajar auditori dan kinestetik. Dengerin.id juga menyediakan fitur untuk pengelolaan kelas untuk pengajar seperti, Absensi digital yang teritegrasi langsung ke orang tua siswa, manajemen PR, sistem informasi penilaian.</p>', '2017-05-22', '2017-11-30', '2024-03-19 09:48:09', '2024-03-19 09:48:09');
INSERT INTO `tenant` VALUES (3244, 85, 'public/foto_profil_tenant/65fbc8ffe1779.JPG', 'LOKY (Smart Locker Public Identity)', 'Muhammad Arief Hidayatullah', NULL, NULL, 'Condong Catur, Depok, Sleman, Yogyakarta', NULL, NULL, NULL, 'Lintas Provinsi', NULL, '<p>produk LOKY (Smart Public Locker Identity) yaitu sebuah loker pintar dengan biometric key berupa sidik jari, PIN maupun E-KTP. Sehingga pengguna bisa menggunakan loker dengan biometric key tanpa perlu takut kehilangan kunci seperti penitipan loker konvensional. Dari evaluasi yang kami dilakukan, ada beberapa masalah yang perlu kami benahi agar produk LOKY (Smart Public Locker Identity) semakin berkualitas dan dapat dikomersialkan.</p>', '2021-12-07', '2022-06-15', '2024-03-21 12:43:27', '2024-03-21 12:43:27');
INSERT INTO `tenant` VALUES (3245, 85, 'public/foto_profil_tenant/65fbcc441981a.png', 'My Eda', 'Ujang Fahmi', NULL, NULL, 'Gejayan, Sleman, Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-a2c763b3-7fff-9b92-9d44-3793a6620fe0\"><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Myeda</span><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> merupakan sebuah alat berbasis web yang didesain untuk memudahkan mulai dari akademisi/peneliti hingga organisasi bisnis untuk mendapatkan </span><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">big data</span><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> dari sumber-sumber publik, mengolah, dan membuat laporan hasil analisis. </span></span><br></p>', '2019-03-21', '2019-11-15', '2024-03-21 12:57:24', '2024-03-21 12:59:38');
INSERT INTO `tenant` VALUES (3246, 85, 'public/foto_profil_tenant/65fd26af428fa.JPG', 'Anglu', 'Penti Makarti', NULL, NULL, 'Perumahan Minomartani Jl.Gabus 1 no.3 Minomartani, Ngaglik, Sleman, Yogyakarta', NULL, '60.000.000,00', 'intagram', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Manisan dan sirup jahe lemon</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-22 13:33:13', '2024-03-22 13:35:27');
INSERT INTO `tenant` VALUES (3247, 85, 'public/foto_profil_tenant/65fd280e09180.png', 'Psikologi Koe', 'Anugrah Rizqi Putra Satiadi', NULL, NULL, 'Sidoarjo', NULL, '800.000.000,00', 'psikologikoe.com', 'Lokal, Lintas Provinsi', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Psikologi Koe merupakan sebuah platform untuk membantu kamu dalam memberikan solusi dari masalah yang kamu utarakan melalui keilmuan \"psikologi\". Dipandu oleh professional ahli yang memiliki segudang pengalaman untuk memberikan pengalaman terbaik untuk kamu.</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-22 13:41:18', '2024-03-22 13:41:18');
INSERT INTO `tenant` VALUES (3248, 85, 'public/foto_profil_tenant/65fd28fa63479.jpg', 'Jessamyn', 'Virilanika Yuliantin', NULL, NULL, 'Tunjungan rt 03 rw 02 Selomartani Kalasan Sleman Yogyakarta', NULL, '40.000.000,00', 'instagram', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Produk Spa dan Aromaterapi untuk bayi, anak dan ibu hamil. Usaha berdiri pada September 2018 berlokasi di Tunjungan, Selomartani, Kalasan, Sleman, Yogyakarta. Produk yang dihasilkan adalah Massage Oil, Baby Oil, Bath Salt, Bubble Bath, Masker Wajah, dan Lulur. Saat ini  produk Jessamyn sudah dipakai oleh ratusan klinik Mom &amp; Baby Spa merata di seluruh Indonesia.</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-22 13:45:14', '2024-03-22 13:45:14');
INSERT INTO `tenant` VALUES (3249, 85, 'public/foto_profil_tenant/65fd2a07dcd11.JPG', 'Ti.craftq', 'Prihastuti', NULL, NULL, 'Trimulyo Sleman', NULL, NULL, 'instagram', 'Lokal, Lintas Provinsi, Lintas Kab/Kota', 'Memiliki pembukuan usaha secara digital', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Produk tas berbahan manik-manik,dibuat dengan dironce manual.</span><br></p>', '2022-08-27', '2023-02-27', '2024-03-22 13:49:43', '2024-03-22 13:49:43');
