INSERT INTO `tenant` VALUES (3252, 85, 'public/foto_profil_tenant/65fd2db7947a7.jpg', 'KAWAN MESSENGER', 'BIMA SAKTI', NULL, NULL, 'Sleman', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-40fd2dba-7fff-e85b-45a2-e043582fee43\"><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Sebuah platform chatting yang memiliki fitur jual beli online dan marketplace di dalamnya, terintegrasi dan didukung dengan sistem pembayaran RekBer (Rekening Bersama).</span></span><br></p>', '2018-04-02', '2018-11-15', '2024-03-22 14:05:27', '2024-03-22 14:05:27');
INSERT INTO `tenant` VALUES (3253, 85, 'public/foto_profil_tenant/65fd2e98ba290.png', 'PIGMI MINI 3D PRINTER', 'Ruslan Abdul Ghani', NULL, NULL, 'Sleman', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-a2505125-7fff-4773-505a-9654db19db5c\"><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Printer 3D dengan ukuran mini yang dapat dioperasikan hanya dengan smartphone</span></span><br></p>', '2018-04-02', '2018-11-15', '2024-03-22 14:09:12', '2024-03-22 14:09:12');
INSERT INTO `tenant` VALUES (3254, 85, 'public/foto_profil_tenant/65fd2f87aa177.JPG', 'LUNASBOS', 'Adjie Purbojati', NULL, NULL, 'Sleman', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-4ff2f39d-7fff-9ad6-1ac3-f4e6316f9ab4\"><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">LUNASBOS adalah aplikasi yang digunakan untuk mempermudah masyarakat dalam pencatatan utang piutang terutama orang yang banyak memiliki aktifitas sosial bersama teman atau rekan kerja yang berutang atau memberi utang dengan nilai kecil namun besar. Menurut riset kami sering kali utang kecil tidak dipedulikan dan tidak tercatat sehingga menimbulkan kesalahpahaman saat ditagih atau di ingatkan tentang piutang kecil itu. </span><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"><br></span><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"><br></span><span style=\"font-size: 11pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Lunasbos hadir dengan teknologi cloud data computing yang dapat memberikan fasilitas sinkronasi data dua arah untuk menyimpan transaksi antara pengutang dan pemberi utang, sehingga catatan akan utang tetap aman walaupun HP hilang/rusak. Di dukung pula dengan teknologi Push Notification untuk management pengingat utang dan penagihan utang.</span></span><br></p>', '2018-04-02', '2018-11-15', '2024-03-22 14:13:11', '2024-03-22 14:13:11');
INSERT INTO `tenant` VALUES (3255, 85, 'public/foto_profil_tenant/65fd32ed95b63.png', 'B-SMART - BRAILLE SMART APPLICATION', 'Elik Hari Muhtafin', NULL, NULL, 'Sleman', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-54bd5e44-7fff-5a4b-d6d0-13fdd3a0a999\"><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">B-SMART adalah </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">personal mobile application </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">berbasis</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Android</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">yang dapat difungsikan untuk memenuhi kebutuhan komunikasi, pendidikan dan kebutuhan sehari hari yang dapat dikendalikan tanpa perlu kemampuan melihat, sehingga cocok digunakan oleh tunanetra. B-SMART terdiri dari 3 sub aplikasi yaitu, B-TOUCH untuk memenuhi kebutuhan komunikasi, B-TOOLS untuk memenuhi kebutuhan sehari hari dan B-SCHOOL untuk memenuhi kebutuhan pendidikan pengguna tunanetra. Aplikasi B-SMART dilengkapi dengan teknologi yang kami kembangkan yaitu </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Virtual Braille Keyboard</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">, sebuah metode yang dapat digunakan untuk melakukan input dan navigasi aplikasi dengan menerapkan konsep huruf braille, sehingga tunanetra dapat menggunakanya tanpa mengalami kesulitan dan tanpa perlu kemampuan melihat. Produk B-SMART menjadi solusi untuk tunanetra, karena untuk beberapa tahun kedepan, keberadaan Smartphone akan mengantikan Handphone dengan </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">keypad. </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Tunanetra mengalami kesulitan untuk menggunakan </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Smartphone</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> karena metode </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">input</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">-nya mengunakan </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">touchscreen</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> (layar sentuh), sehingga tidak bisa diraba seperti </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Keypad, </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">hadirnya produk B-SMART adalah solusi yang tepat untuk menjawab persoalan tersebut.</span></span><br></p>', '2017-05-22', '2017-11-15', '2024-03-22 14:27:41', '2024-03-22 14:27:41');
INSERT INTO `tenant` VALUES (3256, 85, 'public/foto_profil_tenant/65fd34b1ed4f8.JPG', 'Detron Engineering', 'Yudhis Thira Kabul Yunior', NULL, NULL, 'Surabaya', NULL, NULL, NULL, NULL, NULL, '<p>DTRON Smart Chair dapat di operasikan dengan mode 3 sistem kendali yaitu kendali mata, kendali suara dan kendali manual, sehingga cocok untuk efektifitas dan efisiensi pengguna Produk DTRON Smart Chair dapat dipakai oleh pengguna difabel dan disabilitas dengan latar belakan yang berbeda beda dan sesuai dengan kemampuan, karena produk DTRON Smart Chair menawarkan dalam 3 mode sistem kendali.penyandang disabilitas dan difabel.</p>', '2017-05-22', '2017-11-15', '2024-03-22 14:35:13', '2024-03-22 14:35:13');
INSERT INTO `tenant` VALUES (3257, 85, 'public/foto_profil_tenant/65fd35c51db58.jpg', 'UAV 2200 Solar System', 'Ivan Adhi Nugroho', NULL, NULL, 'Prambanan,Sleman,Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p>UAV 2200 Solar System adalah sebuah pesawat terbang tanpa awak dengan kategori fixed wing yang dirancang untuk dapat terbang dengan menggunakan energi listrik tenaga matahari (solar cell) dan baterai sebagai cadangan. Berdasarkan pengujian efisiensi energi yang telah dilakukan maka pesawat ini membutuhkan daya sebesar 76 watt dengan total produksi daya solar cell sebesar 100watt atau masih ada sisa daya sebesar 24 watt, sehingga pesawat ini dapat terbang terus menerus pada saat cuaca cerah. Selain dapat terbang dengan waktu yang lama, pesawat ini dirancang untuk dapat terbang stabil pada kondisi crosswind (angin dari samping) serta mampu terbang pada kecepatan yang rendah yaitu minimal 25 km/h atau 40km/h pada kecepatan cruise. Dengan durasi terbang yang lama dan kecepatan terbang yang rendah maka pesawat ini sangat cocok digunakan untuk misi pengamatan atau monitoring.</p>', '2017-05-22', '2017-11-15', '2024-03-22 14:39:49', '2024-03-22 14:39:49');
INSERT INTO `tenant` VALUES (3258, 85, 'public/foto_profil_tenant/65fd39dba7014.JPG', 'GaBlind (Glasses and Shoes for Blind)', 'Arvin C Frobenius', NULL, NULL, 'condong catur, Sleman', NULL, NULL, NULL, NULL, NULL, '<p>GaBlind (Glasses and Shoes for Blind) adalah alat bantu inovatif berupa kacamata dan sepatu khusus yang di desain untuk tunanetra untuk meningkatkan kemampuan bernavigasi diluar rumah. Tujuan utama GaBlind adalah untuk meningkatkan kemampuan mobilitas, dengan menggabungkan Hardware dan Software Concept. GaBlind menggunakan mikrokontroler dan berbagai sensor untuk mendeteksi halangan yang berada di depan tunanetra. Koneksi bluetooth digunakan untuk bertukar data dengan aplikasi mobile dan Global Positioning System (GPS) berbasis android.Penyandang tunanetra dapat menggunakan GaBlind seperti contohnya untuk pergi ke sekolah, atau menemukan kantor pos atau rumah sakit terdekat, keberadaan GaBlind akan menggantikan beberapa alat bantuan tradisional seperti anjing penuntun, tongkat, ataupun tactile paving untuk melakukan aktivitas di luar rumah, hadirnya produk GaBlind adalah solusi yang tepat untuk menjawab persoalan tersebut.</p>', '2017-05-22', '2017-11-15', '2024-03-22 14:57:15', '2024-03-22 14:57:15');
INSERT INTO `tenant` VALUES (3259, 85, 'public/foto_profil_tenant/65fd3b0051b00.png', 'Election Tech', 'Kardilah Rohmat Hidayat', NULL, NULL, 'Depok, Sleman,Daerah Istimewa Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p>Election Day merupakan game edukasi tentang sosialisai pemilihan calon pemimpin baik itu pemilihan presiden, pemilihan gubernur maupun pemilihan bupati/walikota. Election Day terbagi menjadi 2 bagian yang saling terintegrasi secara realtime yaitu Web dan Mobile Android.</p>', '2017-05-22', '2017-11-15', '2024-03-22 15:02:08', '2024-03-22 15:02:08');
INSERT INTO `tenant` VALUES (3260, 85, 'public/foto_profil_tenant/65fd3d0a02038.png', 'G-CIRCLE', 'Novandi Rezeki', NULL, NULL, 'Condong Catur, Depok,Sleman', NULL, NULL, NULL, NULL, NULL, '<p>G-CIRCLE adalah produk monitoring anggota kelompok yang menggunakan tools berupa gelang yang memanfaatkan GPS dan kombinasi RFID untuk mendeteksi keberadaan anggota rombongan dalam sebuah kegiatan kelompok. G-CIRCLE adalah solusi yang dikembangkan untuk memberikan penjagaan kepada rombongan agar dapat berada dijarak yang dapat dideteksi. G-CIRCLE juga dilengkapi dengan fitur pendukung yang disesuaikan dengan kebutuhan monitoring.</p>', '2017-05-22', '2017-11-15', '2024-03-22 15:10:50', '2024-03-22 15:10:50');
INSERT INTO `tenant` VALUES (3261, 85, 'public/foto_profil_tenant/65fd3fe97d5fa.JPG', 'BoPark', 'Naufal Idharuddin Nasiri', NULL, NULL, 'Sleman, Yogyakarta.', NULL, NULL, NULL, NULL, NULL, '<p>BOPARK menawarkan solusi informasi update ketersediaan tempat parkir bagi pengemudi serta menyediakan fitur pemesanan (booking) tempat parkir, sehingga pengemudi sudah mendapatkan kepastian tempat parkir sebelum tiba dilokasi. Pemesanan ini bahkan bisa dilakukan beberapa hari sebelumnya.</p>', '2017-05-22', '2017-11-15', '2024-03-22 15:23:05', '2024-03-22 15:23:05');
INSERT INTO `tenant` VALUES (3262, 85, 'public/foto_profil_tenant/65fd41e531395.JPG', 'SMART SCHOOL', 'Ahmad Toha', NULL, NULL, 'condongcatur, sleman, yogyakarta.', NULL, NULL, NULL, NULL, NULL, '<p>Smart School menyediakan solusi sistem informasi untuk semua stakeholder dengan aplikasi yang lengkap, mudah dan informatif. Menyediakan tool analisa bagi guru untuk memonitior dan menganalisa siswa dan bagi kepala sekolah untuk memonitor guru dan siswa</p>', '2017-05-22', '2017-11-15', '2024-03-22 15:31:33', '2024-03-22 15:31:33');
INSERT INTO `tenant` VALUES (3263, 85, 'public/foto_profil_tenant/65fd4597e9e17.JPG', 'Barberhub', 'Arif Dian M', NULL, NULL, 'Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-3a030cbd-7fff-26f0-214d-417f03ec9505\"><span style=\"font-size: 9pt; font-family: Roboto, sans-serif; color: rgb(31, 31, 31); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Platform layanan potong rambut online on demand services yang menghubungkan Barberman/Barbershop dengan pemesan melalui aplikasi yang mudah dipakai, nyaman, aman</span></span><br></p>', '2022-03-07', '2022-09-15', '2024-03-22 15:47:19', '2024-03-22 15:47:19');
INSERT INTO `tenant` VALUES (3264, 85, 'public/foto_profil_tenant/65fd470cae9dc.png', 'Retailo', 'Gede Roomiswara', NULL, NULL, 'Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-6192b5e5-7fff-da00-29d4-505aa4e4d8a9\"><span style=\"font-size: 10pt; font-family: Arial, sans-serif; color: rgb(31, 31, 31); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">A mobile app which handle pick up orders from small retail to any shipping services</span></span><br></p>', '2021-05-10', '2021-12-30', '2024-03-22 15:53:32', '2024-03-22 15:53:32');
INSERT INTO `tenant` VALUES (3265, 85, 'public/foto_profil_tenant/65fd485f33e0b.JPG', 'Ummacademy', 'Alif Andika Sutadi Saputra', NULL, NULL, 'Jakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-d14274ca-7fff-fcc9-83e3-5dc1f227caa8\"><span style=\"font-size: 10pt; font-family: Arial, sans-serif; color: rgb(31, 31, 31); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Layan Penunjang Belajar dan Bimbingan Karir Kedokteran, Kedokteran Gigi dan Kesehatan Umum</span></span><br></p>', '2022-03-07', '2022-09-15', '2024-03-22 15:59:11', '2024-03-22 15:59:11');
INSERT INTO `tenant` VALUES (3266, 85, 'public/foto_profil_tenant/65fd492bc8e90.JPG', 'UI Creative', 'Yanuar Prisantoso', NULL, NULL, 'Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-8238204e-7fff-e91f-d05e-7dba7ae6d9a9\"><span style=\"font-size: 10pt; font-family: Arial, sans-serif; color: rgb(31, 31, 31); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">UICreative.net is a Creative Digital Studio that provides ready-to-use graphic design solutions for designers.</span></span><br></p>', '2021-05-10', '2021-12-10', '2024-03-22 16:02:35', '2024-03-22 16:02:35');
INSERT INTO `tenant` VALUES (3267, 85, 'public/foto_profil_tenant/65fd4a2e9b5af.JPG', 'Ruwindomart', 'Akhmad Erik Dzulkifli', NULL, NULL, 'Jawa Timu', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-990b927e-7fff-2c13-e28e-68ab7a91fce8\"><span style=\"font-size: 10pt; font-family: Arial, sans-serif; color: rgb(31, 31, 31); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Platform e-commerce ASLI MALANG yang berfokus pada penjualan sayur dan berbagai kebutuhan pokok</span></span><br></p>', '2022-03-07', '2022-09-15', '2024-03-22 16:06:54', '2024-03-22 16:06:54');
INSERT INTO `tenant` VALUES (3268, 85, 'public/foto_profil_tenant/65fd4af35cfb7.JPG', 'IOWORK Indonesia', 'Oki Wibowo', NULL, NULL, 'Jakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-eda6e107-7fff-ecd1-b156-0fb165076657\"></span></p><p dir=\"ltr\" style=\"line-height:1.2;margin-top:0pt;margin-bottom:0pt;\"><span style=\"font-size:10pt;font-family:Arial,sans-serif;color:#1f1f1f;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">HR Tech Startup which provide mobile apps to connect job-provider and job-seeker.</span></p>', '2022-03-07', '2022-09-15', '2024-03-22 16:10:11', '2024-03-22 16:10:11');
INSERT INTO `tenant` VALUES (3269, 85, 'public/foto_profil_tenant/65fd4c665a48e.JPG', 'Unguin', 'Muh Zaki Choiruddin', NULL, NULL, 'Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p><span id=\"docs-internal-guid-d7ba7092-7fff-d84d-6064-bebb78494307\"><span style=\"font-size: 10pt; font-family: Arial, sans-serif; color: rgb(31, 31, 31); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Unguin is a startup that provides link management services with various innovative features such as link shortening, password protection, link collaboration, and comprehensive statistical analytics. </span></span><br></p>', '2023-04-07', '2023-11-07', '2024-03-22 16:16:22', '2024-03-22 16:16:22');
