INSERT INTO `tenant` VALUES (3279, 51, 'public/foto_profil_tenant/660f188eb750c.jpg', 'Andiko Gallery', 'Dina Yopita', 23, 2, 'Jl. Bhayangkara Gg Gelatik 2 no. 19/28  Kel Gunung Puyuh Sukabumi 43123', NULL, '60.000.000,00', 'Faceebook, IG, WA', 'Nasional', 'Digital', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Berawal dari hobi akan makanan / cemilan tradisional dan sebagai penyaluran ilmu tentang\\npanganan, serta keinginan untuk memiliki penghasilan tetap tanpa meninggalkan tugas utama\\nsebagai seorang IBU, pada tanggal 17 Oktober 2005, mulai membuat panganan tradisional\\nyang untuk dijual kemasyarakat umum dengan di beri merk dagang Andiko Gallery.\\nSeiring dengan berjalannya waktu dan melihat pangsa pasar yang ada, selain membuat \\nmakanan dan cemilan tradisional Andiko Gallery juga membuat membuat minuman berbahan dasar Lidah Buaya\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Berawal dari hobi akan makanan / cemilan tradisional dan sebagai penyaluran ilmu tentang<br>panganan, serta keinginan untuk memiliki penghasilan tetap tanpa meninggalkan tugas utama<br>sebagai seorang IBU, pada tanggal 17 Oktober 2005, mulai membuat panganan tradisional<br>yang untuk dijual kemasyarakat umum dengan di beri merk dagang Andiko Gallery.<br>Seiring dengan berjalannya waktu dan melihat pangsa pasar yang ada, selain membuat<br>makanan dan cemilan tradisional Andiko Gallery juga membuat membuat minuman berbahan dasar Lidah Buaya<br></span></p>', '2021-03-09', '2021-03-09', '2024-04-05 04:15:43', '2024-04-05 04:15:58');
