INSERT INTO `tenant` VALUES (3291, 51, 'public/foto_profil_tenant/6611d799c195b.jpg', 'Galeri cindycahya', 'Cindy Cahya Mulyani', 19, 1, '\"Jl prana Babakan jampang no 70 rt02/rw10 \r\nkel.cisarua kec.cikole kota Sukabumi \"', NULL, '45.000.000,00', 'facebook. Instagram, Wahatsapp dan Offline store', 'Jawa Barat', 'Digital', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Galeri Cindycahya usaha yang bergerak dibidang kerajinan tangan berupa rajutan produk yg dihasilkan seperti tas, dompet, sepatu, baju, boneka, aksesoris-aksesoris dan home dekor. Selain produk rajutan jadi kamipun menjual peralatan dan perlengkapan aneka kerajinan tangan. Kami menjual produk rajutan dalam skala kecil dan skala besar, yang dalam pengerjaaannya memberdayakan ibu-ibu rumah tangga yang ada sekitar Galeri Cindycahya&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Galeri Cindycahya usaha yang bergerak dibidang kerajinan tangan berupa rajutan produk yg dihasilkan seperti tas, dompet, sepatu, baju, boneka, aksesoris-aksesoris dan home dekor. Selain produk rajutan jadi kamipun menjual peralatan dan perlengkapan aneka kerajinan tangan. Kami menjual produk rajutan dalam skala kecil dan skala besar, yang dalam pengerjaaannya memberdayakan ibu-ibu rumah tangga yang ada sekitar Galeri Cindycahya</span><br></p>', '2024-03-09', '2024-03-09', '2024-04-07 06:15:37', '2024-04-07 06:15:37');
INSERT INTO `tenant` VALUES (3292, 51, 'public/foto_profil_tenant/6611d8e18b7a6.png', 'Tempe Crispy Mas Nu', 'Agus Wibowo', 23, NULL, 'Jl. Nanas Graha Pratama Permai Blok B6 no.12 Kel. Anggadita Kec. Klari , Karawang', NULL, NULL, 'facebook. Instagram, Wahatsapp', 'Karawang, Bandung', 'Digital', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Tempe Crispy Mas Nu diproduksi sejak tahun 2018 dengan aneka varian rasa. Tempe Crispy sedang mengembangkan produk dengan base Tempe dibuat menjadi stick Tempe.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Tempe Crispy Mas Nu diproduksi sejak tahun 2018 dengan aneka varian rasa. Tempe Crispy sedang mengembangkan produk dengan base Tempe dibuat menjadi stick Tempe.</span><br></p>', '2024-03-09', '2024-03-09', '2024-04-07 06:21:05', '2024-04-07 06:21:05');
INSERT INTO `tenant` VALUES (3293, 527, 'public/foto_profil_tenant/661f9383dee60.PNG', 'Sigi Lestari', 'Vinrike', 23, 2, 'Desa Kalawara Kecamatan Gumbasa', NULL, '10.000.000,00', 'Facebook, Instagram, WA', 'Dalam daerah dan Luar Daerah', 'Ada', '<p dir=\"ltr\" style=\"line-height:1.56;margin-left: 1pt;margin-right: 7.3pt;margin-top:0pt;margin-bottom:0pt;\"><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve; text-decoration-skip-ink: none;\">Sigi lestari adalah usaha dibidang pangan dengan bahan dasar bawang batu yang berasal dari petani sekitar Desa Soulowe dan diolah menjadi bawang garing yang kriuk dan renyah menjadi pelengkap makanan. Usaha ini terbentuk sejak tahun 2015, melibatkan ibu-ibu rumah tangga sekitar sebagai tenaga kerja dalam proses produksinya. \r\n</span><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve; font-weight: bold; text-decoration-skip-ink: none;\">Legalitas dan izin edar yang dimiliki</span><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve; text-decoration-skip-ink: none;\"> : NIB, PIRT dan Sertifikat Halal.</span><br></p>', '2023-04-10', '2023-06-23', '2024-04-17 15:53:52', '2024-04-17 16:16:51');
INSERT INTO `tenant` VALUES (3295, 471, 'public/foto_profil_tenant/661f94d1802f6.png', 'OSYIN CRAFT', 'LIRA NOVIANTI', NULL, NULL, 'Kel. Koto Panjang, Payobasung, Kec. Payakumbuh Tim., Kota Payakumbuh, Sumatera Barat 26237', NULL, '40.000.000,00', 'INASTAGRAM, FACEBOOK, WHATSAPP, TIK TOK, SHOPEE, TOKOPEDIA, BUKALAPAK', 'SEMATERA DAN JAWA', 'CATATAN MANUAL PAKAI BUKU', '<p>Osyin craft adalah sebuah brand usaha dari kerajinan rajut di Kota Payakumbuh Sumbar dimana Osyin Craft memproduksi berbagai macam kerajinan rajut seperti tas, sepatu, dompet, alas meja, sarung bantal set dll.</p>', '2024-01-03', '2024-01-03', '2024-04-17 16:22:25', '2024-04-17 16:22:25');
INSERT INTO `tenant` VALUES (3296, 527, 'public/foto_profil_tenant/66208057076c4.jpg', 'Dua Putra', 'Irmayanti', 23, 2, 'Desa Soulowe, Kecamatan Sigi Biromaru', NULL, NULL, 'FB : Irmayanti - IG : irmayanti4071', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve;\">Dua Putra merupakan usaha perseorangan yang terbentuk pada tahun 2017 dengan produk unggulannya yaitu bawang garing. Memiliki pertanian bawang batu merupakan keunggulan yang dimiliki usaha ini, karna akses bahan baku yang didapatkan jauh lebih muda. Bawang garing Dua Putra menjadi andalan wisatawan saat berkunjung ke Kabupaten Sigi. Channel pemasaran online juga sangat berdampak bagi usaha ini karena memiliki respon positif bagi konsumennya.\r\nLegalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 08:49:29', '2024-04-18 09:07:19');
INSERT INTO `tenant` VALUES (3297, 527, 'public/foto_profil_tenant/66208164afe8f.jpg', 'Pipikoro Coffee & Roastery', 'Hari Ramdani', 23, 2, 'Desa Mpanau Kecamatan Sigi Biromaru', NULL, '15.000.000,00', 'FB : Pipikoro Coffee & Roastery - IG : @pipikorocoffee', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve;\">Pipikoro Coffee &amp; Roastery berawal dari cemooh biji kopi Sigi memiliki kualitas yang kurang bagus dan mimpi untuk mensejahterakan petani kopi ditanah kelahiran yaitu Kabupaten Sigi. Usaha ini dibentuk pada tahun 2017 di Jakarta dengan perlahan memperbaiki permasalahan kopi yang ada di Kabupaten Sigi. Saat ini, owner Pipikoro Coffee &amp; Roastery sudah kembali ke Kabupaten Sigi dan membuka gerai kopi di Kota Palu. Selain menjual kopi untuk kebutuhan konsumen, juga turut menjadi vendor bagi 7 coffeshop yang ada di Kota Palu.\r\nLegalitas dan Izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Hak Merek.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:11:48', '2024-04-18 09:11:48');
INSERT INTO `tenant` VALUES (3298, 527, 'public/foto_profil_tenant/6620821e470ef.jpg', 'Prilian Kulawi', 'Ramla', 23, 2, 'Desa Bolapapu, Kecamatan Kulawi', NULL, '10.000.000,00', 'FB : Kopi Prilian Kulawi - IG : @priliankulawi', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve;\">Prilian Kulawi merupakan usaha keluarga yang berdiri tahun 2015 di dataran tinggi kabupaten Sigi yaitu Kecamatan Kulawi. Kopi bubuk Prilian adalah produk unggulan yang dimiliki dan sampai saat ini sudah konsisten masuk dibeberapa oleh-oleh di Kota Palu. Selain kopi bubuk murni, Prilian juga berinovasi dengan membuat varian kopi jahe yang dapat menjadi pilihan bagi penikmat kopi.\r\nLegalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Hak Merek.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:14:54', '2024-04-18 09:14:54');
INSERT INTO `tenant` VALUES (3299, 527, 'public/foto_profil_tenant/66208318628ee.PNG', 'Eymo', 'Aminah', 23, 2, 'Desa Bolapapu Kecamatan Kulawi', NULL, '8.000.000,00', 'FB : Aminah Insen - IG : @kopieymo', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span style=\"color: rgb(0, 0, 0); font-family: docs-Cambria; font-size: 13px; white-space-collapse: preserve;\">EYMO adalah usaha rumahan  yang diberdiri pada tahun 2018 di Kecamatan Kulawi Kabupaten Sigi. Kopi Murni dan Kopi Jahe adalah produk yang dimiliki dengan bahan baku lokal petani kopi di wilayah tersebut. Proses tradisional dalam me-roasting biji kopi menggunakan wajan besar/kavali (dalam bahasa daerah kaili) menjadi ciri khas UMKM ini. \r\nLegalitas dan izin edar yang dimiliki : NIB, PIRT dan Sertifikat Halal.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:19:04', '2024-04-18 09:19:04');
INSERT INTO `tenant` VALUES (3300, 527, 'public/foto_profil_tenant/66208402e9e19.jpg', 'Menggaka', 'Hajaria', 23, 2, 'Desa Porame, Kecamatan Kinovaro', NULL, '1.000.000,00', 'FB : IKM Menggaka Hajariah - IG : @saraba_kelor_jahe_instan', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Menggaka adalah kelompok usaha yang terbentuk karena keresahan masyarakat sekitar, khususnya ibu-ibu rumah tangga melihat kelor yang hanya habis digunakan untuk konsumsi sehari-hari saja sedangkan disetiap pekarangan rumah sangat banyak tumbuh. Berkat ilmu yang didapatkan dalam pelatihan beberapa tahun silam tentang pembuatan keripik usaha ini menjadi semakin produktif. Inovasi yang dilakukan adalah memperpanjang masa simpan kelor menjadi bubuk kelor, seduh kelor, saraba kelor dan keripik kelor.  \\nLegalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Merek&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Menggaka adalah kelompok usaha yang terbentuk karena keresahan masyarakat sekitar, khususnya ibu-ibu rumah tangga melihat kelor yang hanya habis digunakan untuk konsumsi sehari-hari saja sedangkan disetiap pekarangan rumah sangat banyak tumbuh. Berkat ilmu yang didapatkan dalam pelatihan beberapa tahun silam tentang pembuatan keripik usaha ini menjadi semakin produktif. Inovasi yang dilakukan adalah memperpanjang masa simpan kelor menjadi bubuk kelor, seduh kelor, saraba kelor dan keripik kelor.<br>Legalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Merek</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:22:58', '2024-04-18 09:22:58');
INSERT INTO `tenant` VALUES (3302, 527, 'public/foto_profil_tenant/662084d5bcf9d.jpg', 'Rajata Cakery', 'Normawati', 23, 2, 'Desa Tinggede, Kecamatan Marawola', NULL, '9.000.000,00', 'FB : Rajata - IG : @rajatacakery', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Rajata Cakery adalah usaha perorangan yang mulai dirintis karena kegemaran membuat kue dan memasak. Kue basah dan kering adalah produk pertama yang dimiliki oleh usaha ini, namun seiring berjalannya waktu terus melakukan inovasi dan membuat beraneka ragam produk diantaranya stik kelor, kopi bubuk murni dan juga kacang disko yang berhasil mengisi gerai beberapa toko oleh-oleh di Kota Palu.\\nLegalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Merek&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Rajata Cakery adalah usaha perorangan yang mulai dirintis karena kegemaran membuat kue dan memasak. Kue basah dan kering adalah produk pertama yang dimiliki oleh usaha ini, namun seiring berjalannya waktu terus melakukan inovasi dan membuat beraneka ragam produk diantaranya stik kelor, kopi bubuk murni dan juga kacang disko yang berhasil mengisi gerai beberapa toko oleh-oleh di Kota Palu.<br>Legalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Merek</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:26:29', '2024-04-18 09:26:29');
INSERT INTO `tenant` VALUES (3303, 527, 'public/foto_profil_tenant/662085da2139f.jpg', 'Fasta Food', 'Eny Kustiyah', 23, 2, 'Desa Tinggede, Kecamatan Marawola', NULL, '10.000.000,00', '\"FB : Fasta Food | Eni Kustiyah - IG : fasta_food\"', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Fasta Food adalah home industry yang berdiri pada tahun 2012 dengan mengelolah hasil perikanan sebagai produk unggulannya seperti abon ikan, sambal ikan roa, rengginang ikan, Namun, seiring berjalannya waktu usaha ini terus mengembangkan produknya dengan mengelola hasil pertanian seperti bawang garing, saraba/jahe dan dodol Sigi. \\nLegalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Hak Merek.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Fasta Food adalah home industry yang berdiri pada tahun 2012 dengan mengelolah hasil perikanan sebagai produk unggulannya seperti abon ikan, sambal ikan roa, rengginang ikan, Namun, seiring berjalannya waktu usaha ini terus mengembangkan produknya dengan mengelola hasil pertanian seperti bawang garing, saraba/jahe dan dodol Sigi.<br>Legalitas dan izin edar : NIB, PIRT, Sertifikat Halal dan Sertifikat Hak Merek.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:30:50', '2024-04-18 09:30:50');
INSERT INTO `tenant` VALUES (3304, 527, 'public/foto_profil_tenant/662088c0ce045.jpg', 'Bungi Namomi', 'Mohamad Annas', NULL, 1, 'Desa Beka, Kecamatan Marawola', NULL, NULL, '\"FB : Bungi Namomi - IG : @bungi_namomi | @mohammad_annas_\"', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Bungi Namomi adalah pelaku usaha bidang kriya dan daur ulang. Hasil kerajinan dari usaha ini merupakan limbah alam dan limbah rumahan yang didaur ulang. Ciri khas produk Bungi Namomi adalah tekstur kulit kayu dan anyaman tikar ntiko. Usaha ini melibatkan kaum muda dan ibu-ibu lansia (penganyam tikar ntiko) di Desa Beka.\\nLegalitas dan izin edar : NIB&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Bungi Namomi adalah pelaku usaha bidang kriya dan daur ulang. Hasil kerajinan dari usaha ini merupakan limbah alam dan limbah rumahan yang didaur ulang. Ciri khas produk 