INSERT INTO `tenant` VALUES (3305, 527, 'public/foto_profil_tenant/66208a2f89ce5.jpg', 'Nelamayu Tradisional Skincare', 'Nelam Ayu Kusuma', NULL, NULL, 'Desa Kaleke, Kecamatan Dolo Barat', NULL, '8.000.000,00', 'IG : @official_nelamayuskincare', NULL, NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Nelamayu Traditional Skincare adalah usaha yang berfokus pada bidang kecantikan dan kesehatan kulit secara tradisional khas kaili (Suku Sulawesi Tengah) pada tahun 2017.  Usaha ini memproduksi masker wajah dan lulur dengan menggunakan bahan alami seperti kopi dan beras ketan.  Produk ini pun diharapkan dapat berkontribusi dengan penjagaan alam dan pemulihan ekonomi masyarakat.\\nLegalitas dan izin edar : NIB, Sertifikat Halal dan Sertifikat Hak Merek&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Nelamayu Traditional Skincare adalah usaha yang berfokus pada bidang kecantikan dan kesehatan kulit secara tradisional khas kaili (Suku Sulawesi Tengah) pada tahun 2017. Usaha ini memproduksi masker wajah dan lulur dengan menggunakan bahan alami seperti kopi dan beras ketan. Produk ini pun diharapkan dapat berkontribusi dengan penjagaan alam dan pemulihan ekonomi masyarakat.<br>Legalitas dan izin edar : NIB, Sertifikat Halal dan Sertifikat Hak Merek</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:49:19', '2024-04-18 09:49:19');
INSERT INTO `tenant` VALUES (3306, 527, 'public/foto_profil_tenant/66208ae1b5a01.jpg', 'Bukit Tujuh', 'Ilham Ari Wibadi', 23, 2, 'Desa Mpanau, Kecamatan Sigi Biromaru', NULL, '15.000.000,00', 'IG : @bukittuju.organik', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Bukit Tujuh adalah usaha yang dibentuk berdasarkan Koperasi Pertanian yaitu Koperasi Bukit Sari Rejeki yang berfokus pada pertanian organik di Kabupaten Sigi. Bukit tujuh sangat berfokus kepada perawatan pertanian yang organik sehingga produk yang diciptakan bernilai baik bagi tubuh. Usaha ini telah melakukan kerjasama dengan salah satu bakery besar yang berada di Kota Palu dengan demand yang cukup besar setiap bulannya. Produk unggulan dari usaha ini adalah tepung mocaf.\\nLegalitas dan izin edar : NIB, PIRT, Sertifikat Halal, Merek dan Organik.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Bukit Tujuh adalah usaha yang dibentuk berdasarkan Koperasi Pertanian yaitu Koperasi Bukit Sari Rejeki yang berfokus pada pertanian organik di Kabupaten Sigi. Bukit tujuh sangat berfokus kepada perawatan pertanian yang organik sehingga produk yang diciptakan bernilai baik bagi tubuh. Usaha ini telah melakukan kerjasama dengan salah satu bakery besar yang berada di Kota Palu dengan demand yang cukup besar setiap bulannya. Produk unggulan dari usaha ini adalah tepung mocaf.<br>Legalitas dan izin edar : NIB, PIRT, Sertifikat Halal, Merek dan Organik.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:51:57', '2024-04-18 09:52:17');
INSERT INTO `tenant` VALUES (3307, 527, 'public/foto_profil_tenant/66208b8a87e18.jpg', 'Alentris Oil', 'Endang Trismiati Boso', 23, 2, 'Desa Jono Oge, Kecamatan Sigi Biromaru', NULL, '10.000.000,00', 'FB : Mosango Mandiri Abadi - IG : @mosangomandiriabadi', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Mosango Mandiri Abadi merupakan usaha yang berada di Desa Jonooge Kecamatan Biromaru yang merupakan lokasi likuifaksi pada tahun 2018 silam. Dibentuk dengan tujuan memulihkan kembali ekonomi keluarga pasca bencana, usaha ini mulai berfokus mengembangkan komoditas yang ada yaitu buah kelapa. Virgin Coconut Oil (VCO) dengan brand Alentris oil, merupakan produk unggulan yang mampu bersaing dengan produk sejenisnya dipasaran.\\nLegalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Mosango Mandiri Abadi merupakan usaha yang berada di Desa Jonooge Kecamatan Biromaru yang merupakan lokasi likuifaksi pada tahun 2018 silam. Dibentuk dengan tujuan memulihkan kembali ekonomi keluarga pasca bencana, usaha ini mulai berfokus mengembangkan komoditas yang ada yaitu buah kelapa. Virgin Coconut Oil (VCO) dengan brand Alentris oil, merupakan produk unggulan yang mampu bersaing dengan produk sejenisnya dipasaran.<br>Legalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:55:06', '2024-04-18 09:55:06');
INSERT INTO `tenant` VALUES (3308, 527, 'public/foto_profil_tenant/66208c4e36fac.jpg', 'Banggele Sigi', 'Yeny Agustina', 23, 2, 'Desa Bunga, Kecamatan Palolo', NULL, '8.000.000,00', '\"FB : Yenny Putong - IG : @yennyagustina28\"', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Banggele Sigi adalah kelompok usaha wanita yang terbentuk di Desa Bunga Kecamatan Palolo. Produk yang dimiliki usaha ini adalah Kecap Rempah dengan tujuan pemanfaatamn hasil pertanian kemiri yang berlimpah diwilayah ini. Rasa unik yang ada dalam kecap rempah membuat produk ini digemari oleh konsumen karna cocok digunakan sebagai kondimen dalam sajian makanan.\\nLegalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Banggele Sigi adalah kelompok usaha wanita yang terbentuk di Desa Bunga Kecamatan Palolo. Produk yang dimiliki usaha ini adalah Kecap Rempah dengan tujuan pemanfaatamn hasil pertanian kemiri yang berlimpah diwilayah ini. Rasa unik yang ada dalam kecap rempah membuat produk ini digemari oleh konsumen karna cocok digunakan sebagai kondimen dalam sajian makanan.<br>Legalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 09:58:22', '2024-04-18 09:58:22');
