INSERT INTO `tenant` VALUES (3313, 527, 'public/foto_profil_tenant/66209429657d1.PNG', 'LPKD Hintuwu Salua', 'Daiman', 23, NULL, 'Desa Salua, Kecamatan Kulawi', NULL, '5.000.000,00', '\"FB : LPKD Hintuvu Salua - IG : @lpkdhintuvusalua_sigi\"', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Lembaga Pengelola Konservasi Desa (LPKD) Hintuvu Salua adalah kelompok yang terbentuk dengan tujuan awal mengelola dan menjaga wilayah konservasi disekitarnya dengan melakukan pengelolaan HHBK (hasil hutan bukan kayu) sebagai sumber usaha baru. Gula aren semut dengan ciri khas menjadikan produk ini direspon baik kepada beberapa konsumen dan toko oleh-oleh untuk memberikan pasarnya.\\nLegalitas dan izin edar : NIB, PIRT dan Sertifikat Halal (onprogress)&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Lembaga Pengelola Konservasi Desa (LPKD) Hintuvu Salua adalah kelompok yang terbentuk dengan tujuan awal mengelola dan menjaga wilayah konservasi disekitarnya dengan melakukan pengelolaan HHBK (hasil hutan bukan kayu) sebagai sumber usaha baru. Gula aren semut dengan ciri khas menjadikan produk ini direspon baik kepada beberapa konsumen dan toko oleh-oleh untuk memberikan pasarnya.<br>Legalitas dan izin edar : NIB, PIRT dan Sertifikat Halal (onprogress)</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 10:31:53', '2024-04-18 10:31:53');
INSERT INTO `tenant` VALUES (3314, 527, 'public/foto_profil_tenant/662094bd718f0.jpg', 'Coklat Pak Tani', 'Thomas', 23, NULL, 'Desa Omu, Kecamatan Gumbasa', NULL, '8.000.000,00', 'IG : @cokelatpaktani', 'Dalam daerah dan Luar Daerah', 'Ada', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Koperasi Agro Industri Omu adalah koperasi pertanian yang 2 tahun terakhir melakukan inovasi produk pertanian kakaonya menjadi Cokelat Bar dengan brand Cokelat Pak Tani. Produk yang sudah berhasil berkolaborasi dengan 10 alumni masterchef ini terus belajar untuk mempertahankan kualitas dan ciri khas (70% konsentrasi cokelat) di pasar nasional.\\nLegalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:5053,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Cambria&quot;}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, Arial;\">Koperasi Agro Industri Omu adalah koperasi pertanian yang 2 tahun terakhir melakukan inovasi produk pertanian kakaonya menjadi Cokelat Bar dengan brand Cokelat Pak Tani. Produk yang sudah berhasil berkolaborasi dengan 10 alumni masterchef ini terus belajar untuk mempertahankan kualitas dan ciri khas (70% konsentrasi cokelat) di pasar nasional.<br>Legalitas dan izin edar : NIB, PIRT dan Sertifikat Halal.</span><br></p>', '2023-04-10', '2023-06-25', '2024-04-18 10:34:21', '2024-04-18 10:34:21');
INSERT INTO `tenant` VALUES (3315, 471, 'public/foto_profil_tenant/66209dce6c0bc.jpeg', 'DapurnyaAmi', 'MARDELI YUSNA', NULL, NULL, 'RESIDEN KEC BANUHAMPU KAB AGAM', NULL, '400.000.000,00', 'INSTAGRAM, WA BISNIS, FACEBOOK , SHOOPEE, TOKO PEDIA', 'SUMBAR RIAU', 'BELUM ADA CATATAN KEUANGAN', '<p class=\"MsoNormal\"><span style=\"font-size: 10pt; line-height: 107%; font-family: Arial, sans-serif; color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">FROZENFOOD RUMAHAN TANPA MICIN\r\nTANPA PENGAWET ,, ANEKA LAUK SIAP SANTAP SIAP PANASKAN</span><o:p></o:p></p>', '2024-01-03', NULL, '2024-04-18 11:13:02', '2024-04-18 11:13:02');
INSERT INTO `tenant` VALUES (3317, 471, 'public/foto_profil_tenant/6620a46fb7418.jpeg', 'FUNKAKTUS', 'WAHYU OKTARIADI', NULL, NULL, 'Ampalu Rt03 Rw20. Kelurahan Pegambiran Ampalu Nan XX. Kecamatan Lubuk Begalung kota Padang', NULL, '65.000.000,00', NULL, 'KOTA PADANG', 'PENCATANAN MANUAL', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Funkaktus adalah usaha produksi pot bunga lukis berbahan gypsum dengan sistem cetak. Selain itu usaha ini juga melakukan budidaya kaktus mini. </span><br></p>', '2024-01-03', NULL, '2024-04-18 11:41:19', '2024-04-18 11:41:19');
INSERT INTO `tenant` VALUES (3318, 471, 'public/foto_profil_tenant/6620a65569a8b.jpeg', 'LOKAK LEATHER CRAFT', 'FAHRU GUNNARDI', NULL, NULL, 'PERUM UNAND BLOK B3/05 NO 11', NULL, NULL, 'INSTAGRAM', 'LOKAL DAN NASIONAL', 'BELUM ADA CATATAN KEUANGAN', 'KERAJINAN KULIT DENGAN PRODUK UNGGULAN DOMPET LAKI-LAKI, TAS, DLL', '2024-01-03', NULL, '2024-04-18 11:49:25', '2024-04-18 11:49:25');
INSERT INTO `tenant` VALUES (3320, 471, 'public/foto_profil_tenant/6620a92ae1f4c.jpeg', 'ALFINA', 'OKFI RESTI', 23, NULL, 'Jl. Damang Nur Suhud No 75 A Batuang Baririk Nag. Tanjuang Baringin Kec. Lubuk Sikaping Kab. Pasaman', NULL, '120.000.000,00', 'Ig, Fb, Tiktok', 'SUMATERA BARAT', 'PENCATANAN MANUAL', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Usaha kami bergelut pada bidang kuliner khususnya mengolah buah </span><br></p>', '2024-01-03', NULL, '2024-04-18 12:01:30', '2024-04-18 12:01:30');
INSERT INTO `tenant` VALUES (3321, 471, 'public/foto_profil_tenant/6620aa5829707.jpg', 'SEKUKIS.ID COOKIES & DESSERT', 'PUTRI RAHMA SARI', 23, NULL, 'Jl. By Pass Padang Panjang. Tabek Gadang RT 11, Kel. Ganting, Kec. Padang Panjang Timur', NULL, '18.000.000,00', 'Instagram (visual katalog produk/soft selling) WhatsApp (hard selling) Facebook (hard selling) Tiktok (baru mulai)(story telling)', NULL, 'Local di Padang Panjang, Bukittinggi, Padang dan Jakarta', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\">Usaha cookies yang berawal di akhir tahun 2020 tepatnya bulan Oktober dengan produk pertama kami yaitu  soft thin cookies \'crunchy outside, soft inside\'. Kami mengeluarkan beberapa varian diantaranya classic OG, cornflakes chocochip, choco beng² dan oreo choco.\r\nProduk sekukis selain varian dengan diameter 8cm kami juga mengeluarkan varian bite size. Ditahun 2023 kami mengeluarkan varian baru yaitu white choco matcha yang menjadi best seller sekarang ini. Distribusi penjualan sekukis ke cafe di Padang Panjang, CFD setiap minggu dan mengikuti event bazzar yang diaadakan pemerintah/swasta.\r\n\r\nProduk terbaru kami yaitu Pare Crispy bulan November 2023. Berawal dari hasil panen sendiri kemudian timbul ide untuk mengolah pare menjadi keripik. Varian saat ini ada original, rendang dan peyek. Varian peyek menjadi best sellat saat ini. Distribusi penjualan pare crispy secara langsung, memitipkan produk di sentra oleh² di Payakumbuh \'Uda Sayang\' dengan sistem konsiyasi, dan beberapa toko di Kota Padang Panjang.\r\n\r\nPerizinan yang sudah dimiliki yaitu NIB, HALAL. Perizinan P-IRT sedang diurus berkasnya.\r\n</span></p><div><span style=\"color: rgb(0, 0, 0); font-family: Arial; font-size: 13px; white-space-collapse: preserve;\"><br></span></div>', '2024-01-03', NULL, '2024-04-18 12:06:32', '2024-04-18 12:06:32');
INSERT INTO `tenant` VALUES (3325, 471, 'public/foto_profil_tenant/6620c5e0d2333.png', 'FIARA SULAM', 'FITRI NURFAJRINA', NULL, NULL, 'Lundang, panampuang, kec. Ampek angkek, kab. Agam', NULL, '650.000.000,00', NULL, NULL, NULL, '<p>Fiara Sulam adalah perusahaan yang bergerak di bidang produksi pakaian dan aplikasi bordir, dengan fokus khusus pada sulaman tangan. Berlokasi di Ampek Angkek, Kabupaten Agam, Sumatera Barat yang terkenal dengan keahliannya dalam menyulam. Kami mengutamakan keberlanjutan bahan baku dan pelestarian lingkungan dengan meminimalkan penggunaan bahan dan memastikan efisiensi yang optimal. Produk bordir kami sudah tersebar di berbagai kota di Indonesia, antara lain Jakarta, Banda Aceh, Medan, Batam, dan lain-lain.</p>', '2024-01-03', NULL, '2024-04-18 14:04:00', '2024-04-18 14:04:00');
INSERT INTO `tenant` VALUES (3326, 471, 'public/foto_profil_tenant/6620c88a8b236.JPG', 'MATCHA! BAKERY', 'JANUARAHMAD ERVA', 23, NULL, 'Perum Lanefa Residence No 375, Ampalu, Pariaman Utara, Kota Pariaman', NULL, '50.000.000,00', NULL, NULL, NULL, '<p>Matcha! Bakery selalu menghasilkan produk dengan rasa yang lebih enak di bandingkan bakery umumnya. Untuk memasarkan produk roti, kami langsung menyasar kepada cafe-cafe dan coffee shop, yang mana memiliki pangsa pasar kalangan menengah ke atas. Sementara ini untuk kota pariaman belum terdapat kompetitor lain yang melakukan hal serupa. Namun untuk penjualan pizza kami langsung menjual ketangan konsumen dan kami memiliki banyak loyal costumer. Dengan banyaknya jumlah coffe shop atau cafe dibeberapa kota seperti kota padang atau sekitaran kota pariaman, ini merupakan peluang besar untuk menambah jumlah target pasar, dan tentunya meningkatkan jumlah produksi kedepannya sehingga dapat mencapai target pendapatan yang diharapkan.</p>', '2024-01-03', NULL, '2024-04-18 14:15:22', '2024-04-18 14:15:22');
INSERT INTO `tenant` VALUES (3327, 471, NULL, 'KOMAK TOROIJI', 'MARIANI', NULL, NULL, 'Muara Siberut, Dusun Peigu, Kecamatan Siberut Selatan', NULL, '5.000.000,00', NULL, NULL, NULL, '<p>Komak Toroiji adalah sebuah usaha yang berada di Kabupaten Kepulauan Mentawai, Kecamatan Siberut Selatan yang berfokus pada produksi dan penjualan kain dalam bentuk batik yang terinspirasi dari motif Mentawai. Kami bertujuan untuk membesarkan dan mempromosikan keindahan dan keunikan Komak (kain) kepada pelanggan lokal maupun internasional. Dengan menggunakan teknik tradisional dan bahan berkualitas dari Kota Solo, Jawa tengah, kami ingin memberikan pengalaman berbelanja dan memuaskan bagi pelanggan kami.</p>', '2024-01-03', NULL, '2024-04-18 14:30:41', '2024-04-18 14:30:41');
INSERT INTO `tenant` VALUES (3330, 471, NULL, 'CAP ANGSA', 'YUNIERTI', NULL, NULL, 'KOTA PADANG', NULL, NULL, NULL, NULL, NULL, NULL, '2024-01-03', NULL, '2024-04-18 15:01:09', '2024-04-18 15:01:09');
INSERT INTO `tenant` VALUES (3331, 471, 'public/foto_profil_tenant/6620d525565d1.jpeg', 'KERIPIK TEMPE LIES', 'LISDIAWATI', NULL, NULL, 'Jorong bandarejo dusun 2, nagari lingkuang aua, kec. Pasaman, kab. Pasaman barat, sumatera barat', NULL, '100.000.000,00', NULL, NULL, NULL, '<p>Usaha keripik tempe adalah bisnis yang menghasilkan keripik dari bahan dasar tempe kedelai yang digoreng tipis dan dicampur dengan bumbu rempah serta bahan-bahan lainnya. Keripik tempe memiliki cita rasa yang gurih, renyah, dan lezat sehingga dapat menjadi camilan harian, jajanan khas, dan oleh-oleh bagi keluarga atau kerabat. Selain itu, keripik tempe juga memiliki nilai gizi yang baik karena tidak mengandung bahan pengawet dan digoreng pada suhu rendah sehingga nutrisi tidak hilang, untuk tahan lebih lama keripik tempe kami juga mengfgunakan mesin pengering agar minyaknya tidak banyak.</p>', '2024-01-03', NULL, '2024-04-18 15:09:09', '2024-04-18 15:09:09');
INSERT INTO `tenant` VALUES (3332, 471, 'public/foto_profil_tenant/6620d8227b171.jpeg', 'DAPUR_LIDYAA', 'LIDYA OKTAVIA', NULL, NULL, 'Kampung pinang RT/RW 001/011 kel/desa ALAI PARAK KOPI kecamatan padang utara', NULL, '50.000.000,00', NULL, NULL, NULL, '<p>Dapur Lidyaa menyediakan berbagai macam menu masakan rumahan, menu-menu tersebut akan di perbarui dan setiap minggu nya akan di rooling agar pelanggan tidak merasa bosan dan tertantang untuk terus mencoba kelezatan menu-menu kami. Dalam setiap menu kami menambahkan unsur kekinian di setiap masakan untuk menarik pelanggan.</p>', NULL, NULL, '2024-04-18 15:21:54', '2024-04-18 15:21:54');
INSERT INTO `tenant` VALUES (3333, 471, 'public/foto_profil_tenant/6620d94cb9af0.jpeg', 'SHOWROOM TUAN CRAB', 'ALGHANY PERDANA ARSYADI', NULL, NULL, 'Jl. Gurita No.1, RT 005, RW 004 Ulak Karang Selatan, Kec. Padang Utara, Kota Padang', NULL, '150.000.000,00', NULL, NULL, NULL, '<p>Showroom Tuan Crab merupakan kegiatan pembudidayaan kepiting bakau menggunakan sistem RAS (Recirculation Aquaculture System) dengan teknik Vertical Crab House yang meliputi penggemukan dan kepiting cangkang lunak (Soka) yang dapat dikelola di areal sempit seperti perkarangan rumah, garasi ataupun ruko namun memiliki potensi yang besar karena kebutuhan konsumsi kepiting bakau di masyarakat indonesia maupun luar negeri sangat tinggi.</p><p>Mengingat potensi kepiting bakau di SUMBAR sangat melimpah dan belum terdapatnya pelaku usaha yang menggarap teknologi budidaya kepiting bakau secara serius maka bila ditekuni lebih lanjut maka usaha ini menjanjikan keuntungan yang besar dilihat dari permintaan lokal (indonesia) yang belum terpenuhi dan permintaan internasional (singapore, china, hongkong, korea dll) yang terus meningkat sekitap tahunnya</p>', '2024-01-03', NULL, '2024-04-18 15:26:52', '2024-04-18 15:26:52');
INSERT INTO `tenant` VALUES (3335, 471, NULL, 'KERUPUK IKAN', 'SRI ZIKRA FADILLAH', NULL, NULL, 'KOTA PADANG', NULL, NULL, NULL, NULL, NULL, NULL, '2024-01-03', NULL, '2024-04-18 15:44:50', '2024-04-18 15:44:50');
INSERT INTO `tenant` VALUES (3336, 471, 'public/foto_profil_tenant/6620deb001ccd.jpeg', 'BGD_HYDROFARM PADANG', 'MUHAMMAD RIDWAN KURNIAWAN', NULL, NULL, 'Komplek griya permata 1 Blok B 2 nomor 2 gunung pangilin padang', NULL, '15.000.000,00', NULL, NULL, NULL, NULL, '2024-01-03', NULL, '2024-04-18 15:49:52', '2024-04-18 15:49:52');
INSERT INTO `tenant` VALUES (3337, 77, 'public/foto_profil_tenant/6621d0b7973ac.jpeg', 'L\'Arbre Seho', 'Inneke Victor', 23, 2, 'Jalan Poluan 1, Kakaskasen Dua, Kec Tomohon Utara, Kota Tomohon', NULL, NULL, 'WhatsApp', 'Provinsi Sulawesi Utara', NULL, NULL, '2023-02-25', NULL, '2024-04-19 08:41:18', '2024-08-05 12:16:19');
INSERT INTO `tenant` VALUES (3338, 77, 'public/foto_profil_tenant/6621d3f5e691c.jpeg', 'Kreatifitas Seni Ukiran dari Limbah Kayu', 'Oktafio Wohon', NULL, 2, 'Kembes II, Jaga III, Kec. Tombulu, Kab. Minahasa, Sulawesi Utara', NULL, NULL, 'WhatsApp, Facebook, Instagram', 'Kota Manado', NULL, '<div style=\"outline: none; color: rgb(126, 126, 126); font-family: Poppins, sans-serif; font-size: 16px;\"><font face=\"Times New Roman, serif\" style=\"outline: none;\">Kayu merupakan sumber daya yang paling sering dimanfaatkan diseluruh dunia, baik sebagai bahan konstruksi maupun untuk kebutuhan sehari-hari. Dengan keindahan alaminya dan kualitasnya yang beragam, kayu telah menjadi bahan utama dalam industri konstruksi, kerajinan, dan manufaktur mebel. Meskipun demikian, di balik manfaatnya, terdapat permasalahan serius, terutama terkait dengan mudahnya kayu terbakar.</font></div><div style=\"outline: none; color: rgb(126, 126, 126); font-family: Poppins, sans-serif; font-size: 16px;\"><font face=\"Times New Roman, serif\" style=\"outline: none;\">Menurut Prasetya (2015), potongan limbah kayu dari proses produksi mebel yang tidak dapat digunakan lagi oleh tukang kayu dapat menyebabkan akumulasi limbah yang berpotensi menciptakan kondisi mendukung kebakaran. Dampaknya meliputi kerugian ekonomi, kerusakan lingkungan, dan bahkan risiko keamanan masyarakat. Beberapa limbah kayu digunakan sebagai sumber energi melalui pembakaran, namun perlu diingat bahwa praktik ini berdampak negatif pada kesehatan. Oleh karena itu, pemanfaatan limbah kayu melalui ukiran tidak hanya menciptakan peluang ekonomi yang signifikan tetapi juga memberikan dampak positif pada lingkungan.</font></div><div style=\"outline: none; color: rgb(126, 126, 126); font-family: Poppins, sans-serif; font-size: 16px;\"><font face=\"Times New Roman, serif\" style=\"outline: none;\">Ukiran huruf dan nama dari kayu masih kurang populer di Indonesia, bahkan di Kecamatan Tombulu, Kabupaten Minahasa belum ada praktik tersebut. Meskipun begitu, ukiran huruf dan nama menggunakan kayu sisa menjadi pilihan yang diminati karena fungsionalitasnya, seperti pembuatan papan nama keluarga, papan nama alamat rumah, dan gantungan kunci. Kerajinan tangan manual dengan ukiran kayu memberikan nilai seni tersendiri, menjadikannya pilihan yang populer di kalangan berbagai lapisan masyarakat.</font></div><div style=\"outline: none; color: rgb(126, 126, 126); font-family: Poppins, sans-serif; font-size: 16px;\"><font face=\"Times New Roman, serif\" style=\"outline: none;\">Mengingat hal tersebut, kami ingin memanfaatkan keahlian kami dalam seni ukir huruf dan nama dengan menggunakan gergaji ukir. Proses ini melibatkan pembersihan dan perapian kayu sisa, pembuatan pola pada kertas, penerapan pola pada kayu yang telah dibersihkan, dan pengukiran sesuai pola menggunakan gergaji ukir berukuran sangat kecil, yakni sekitar 2 mm. Ukuran kecil ini memungkinkan kami menghasilkan ukiran huruf yang sangat detail, menciptakan hasil akhir yang estetis, dan memberikan nilai tambah pada kayu sisa yang kami olah.</font></div><div style=\"outline: none; color: rgb(126, 126, 126); font-family: Poppins, sans-serif; font-size: 16px;\"><font face=\"Times New Roman, serif\" style=\"outline: none;\">Selain itu, kami melakukan inovasi dengan menciptakan ukiran yang dapat disesuaikan dengan selera konsumen dan mengadopsi pendekatan digital dalam pemasaran. Kami memanfaatkan platform digital, seperti media sosial, untuk memperluas cakupan pasar. Dengan menggunakan limbah kayu dari industri mebel sebagai bahan utama, harapan kami adalah melatih jiwa kewirausahaan, memenuhi permintaan untuk ukiran papan nama dan gantungan kunci, serta mendukung prinsip keberlanjutan lingkungan</font></div>', '2023-12-05', NULL, '2024-04-19 08:52:54', '2024-04-30 10:01:16');
INSERT INTO `tenant` VALUES (3339, 77, 'public/foto_profil_tenant/6621d0dd88d49.jpeg', 'Budidaya Ikan Mujair Ramah Lingkungan', 'Reynaldi Kerap', 4, 2, 'Jalan Perkebunan Rap-rap, Kel. Rap-rap, Kec. Airmadidi, Minahasa Utara', NULL, NULL, 'Facebook, Instagram', 'Kota Manado', NULL, '<p class=\"MsoListParagraphCxSpFirst\" style=\"outline: none; margin: 0cm 0cm 0cm 14.2pt; line-height: 24px; font-size: medium; font-family: Calibri, sans-serif; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); text-align: justify; text-indent: 21.8pt;\"><span lang=\"EN-GB\" style=\"outline: none;\">Perikanan merupakan semua kegiatan yang berhubungan dengan pengelolaan dan pemanfaatan sumber daya ikan; dalam hal ini mencakup kegiatan dari praproduksi, produksi, pengolahan sampai dengan proses pemasaran yang dilaksanakan dalam suatu bisnis perikanan. Dengan demikian, seluruh aktivitas yang terhimpun dalam sektor perikanan berpotensi menciptakan kesempatan ekonomi yang luas sehingga dapat meningkatkan kesejahteraan masyarakat yang secara otomatis akan berdampak baik dalam pembangunan perekonomian. Ikan mujair&nbsp;<i style=\"outline: none;\">(Oreochromis Mossambicus)&nbsp;</i>adalah jenis ikan konsumsi air tawar yang banyak diminati oleh masyarakat. Jenis-jenis ikan mujair yang sering dikenal yaitu mujair biasa, mujair merah, dan mujair albino. Banyaknya kandungan gizi yang terdapat pada ikan mujair menjadikan ikan ini salah satu ikan yang paling diminati banyak orang. Dengan jumlah perminataan yang tinggi ini maka budidaya dan penjualan ikan mujair sangat menjanjikan.<o:p style=\"outline: none;\"></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"outline: none; margin: 0cm 0cm 0cm 14.2pt; line-height: 24px; font-size: medium; font-family: Calibri, sans-serif; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); text-align: justify; text-indent: 21.8pt;\"><span lang=\"EN-GB\" style=\"outline: none;\">Budidaya ikan mujair sudah banyak dilakukan di Indonesia, khususnya di Kecamatan Airmadidi, Kabupaten Minahasa Utara. Banyaknya pelaku budidaya ikan mujair ini tentunya disertai dengan tingginya limbah yang dihasilkan dari kolam budidaya. Penyebab limbah dalam budidaya ikan disebut sebagai sindrom Nitrogen (N). Sindrom Nitrogen ini kerap menjadi masalah karena bahan organik yang berasal dari sisa pakan dan kotoran ikan nantinya akan mengalami perombakan, kemudian larut menjadi amoniak (NH3) atau amonium (NH4+) dan ini akan menjadi racun. Hal ini tentunya berbahaya bagi kelangsungan ekosistem jika limbah budidaya langsung dibuang ke sungai tanpa ada tindakan pengelolaan limbah yang dilakukan.</span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"outline: none; margin: 0cm 0cm 0cm 14.2pt; line-height: 24px; font-size: medium; font-family: Calibri, sans-serif; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); text-align: justify; text-indent: 21.8pt;\"><span lang=\"EN-GB\" style=\"outline: none;\">Maka dari itu, kami ingin memanfaatkan telaga berukuran 8 x 12 m yang berlokasi di Kelurahan Rap-Rap, Kecamatan Airmadidi untuk dijadikan kolam budidaya ikan mujair. Pada sistem budidaya ini&nbsp;&nbsp;kami akan menggunakan sistem bioflok yaitu dengan memanfaatkan bakteri heterotrof dengan menambahkan molase pada kolam budidaya. Bakteri heterortof berperan untuk menurunkan kadar amonia dalam air sehingga air limbah yang dihasilkan akan lebih ramah lingkungan dan tidak akan merusak ekosistem yang ada. Selain itu kami melakukan inovasi dengan melakukan digitalisasi dalam pemasaran (<i style=\"outline: none;\">digital marketing</i>) dengan memanfaatkan berbagai platform digital (sosial media)&nbsp;&nbsp;untuk memasarkan ikan Mujair agar memperoleh cakupan pasar yang lebih luas.<o:p style=\"outline: none;\"></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"outline: none; margin: 0cm 0cm 0cm 14.2pt; line-height: 24px; font-size: medium; font-family: Calibri, sans-serif; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); text-align: justify; text-indent: 21.8pt;\"><span lang=\"EN-GB\" style=\"outline: none;\"></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"outline: none; margin: 0cm 0cm 0cm 14.2pt; line-height: 24px; font-size: medium; font-family: Calibri, sans-serif; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); text-align: justify; text-indent: 21.8pt;\"><span lang=\"EN-GB\" style=\"outline: none;\">Dengan dikembangkannya system budidaya Ikan mujair yang ramah lingkungan ini diharapkan untuk melatih jiwa kewirusahaan kami, memenuhi kebutuhan permintaan ikan mujair, serta mendukung konsep keberlanjutan lingkungan.</span></p>', '2023-09-20', '2023-09-20', '2024-04-19 08:59:04', '2024-04-30 10:05:53');
INSERT INTO `tenant` VALUES (3340, 77, 'public/foto_profil_tenant/6621d66113150.jpeg', 'D\'Goraka', 'Daysi Mariani Goni', 23, 2, 'Kel. Kolongan Ling.II, Desa/Kelurahan Kolongan, Kec. Tomohon Tengah, Kota Tomohon, Provinsi Sulawesi Utara', NULL, NULL, 'WhatsApp', NULL, NULL, NULL, '2023-02-25', NULL, '2024-04-19 09:26:41', '2024-04-19 09:26:41');
INSERT INTO `tenant` VALUES (3341, 77, 'public/foto_profil_tenant/6621d740b14c5.jpeg', 'Kerupuk Kelor', 'Miknasye Bogia', 23, 2, 'Jaga 1, Desa/Kelurahan Suluan, Kec. Tombulu, Kab. Minahasa, Provinsi Sulawesi Utara', NULL, NULL, 'WhatsApp, Facebook, Instagram', 'Provinsi Sulawesi Utara', NULL, NULL, '2023-02-25', NULL, '2024-04-19 09:30:24', '2024-04-19 09:30:24');
INSERT INTO `tenant` VALUES (3342, 19, NULL, 'SOGU (Solusi Sagu)', 'I Putu Candra Suhendra', 23, 2, 'Br. Petang Suci, Desa Petang', NULL, '5.000.000.100.000,00', 'Instagram, WA, Website', '-', '-', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;SOGU (Solusi Sagu) dari pengolahan batang pohon aren menjadi tepung. SOGU merupakan tepung yang dibuat dari bahan baku batang pohon aren dengan spesifikasi batang pohon yang belum mati dan tidak mengandung air, sehingga dapat menghasilkan sagu yang merupakan salah satu komoditas perkebunan di Kecamatan Petang.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">SOGU (Solusi Sagu) dari pengolahan batang pohon aren menjadi tepung. SOGU merupakan tepung yang dibuat dari bahan baku batang pohon aren dengan spesifikasi batang pohon yang belum mati dan tidak mengandung air, sehingga dapat menghasilkan sagu yang merupakan salah satu komoditas perkebunan di Kecamatan Petang.</span><br></p>', '2024-01-02', '2024-12-01', '2024-04-19 13:24:48', '2024-04-19 13:24:48');
INSERT INTO `tenant` VALUES (3343, 19, 'public/foto_profil_tenant/66275a45427c8.jpg', 'Numbas Dodol', 'I Gede Karma Santiyasa', 23, 2, 'Lingkungan Jeroan, Lukluk, Mengwi, Badung', NULL, '1.000.000,00', 'WhatsApp, Instagram', NULL, NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Startup yang bergerak dibidang makanan khusus nya jajanan khas bali utara dodol, kami sebagai pihak yang membantu UMKM disana untuk dapat bersaing lebih baik di sektor jajanan dan oleh oleh khas bali dengan digitalisasi&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Startup yang bergerak dibidang makanan khusus nya jajanan khas bali utara dodol, kami sebagai pihak yang membantu UMKM disana untuk dapat bersaing lebih baik di sektor jajanan dan oleh oleh khas bali dengan digitalisasi</span><br></p>', '2024-01-02', '2024-12-01', '2024-04-19 13:28:53', '2024-04-23 13:50:45');
INSERT INTO `tenant` VALUES (3344, 19, NULL, 'B’thelabel', 'Ni Wayan Bijikamiati', 19, 1, 'Nusa Dua', NULL, '300.000,00', 'Instgaram, WA', NULL, NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;B’thelabel berdiri pada 1 Juni 2023, Yang  menjual produk wanita dan pria  &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">B’thelabel berdiri pada 1 Juni 2023, Yang menjual produk wanita dan pria dengan harga terjangkau&nbsp;</span><br></p>', '2024-01-02', '2024-12-01', '2024-04-19 13:33:58', '2024-04-19 13:33:58');
INSERT INTO `tenant` VALUES (3345, 19, 'public/foto_profil_tenant/66275a0b9de2c.png', 'Palm Studio', 'I Wayan Wahyu Surya Putra', 32, 8, 'Universitas Primakara Jl. Tukad Badung No.135, Renon, Denpasar Selatan, Kota Denpasar, Bali 80226', NULL, '2.000.000,00', 'Instagram, LinkedIn', 'Indonesia-Luar Negeri', NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Palm Studio adalah sebuah perusahaan pengembangan permainan (game development) yang berfokus pada menciptakan pengalaman bermain yang menghibur dan inovatif. Mereka bergerak di industri game, merancang dan mengembangkan permainan untuk berbagai platform, termasuk PC dan perangkat mobile. Palm Studio didirikan oleh sekelompok individu yang telah memiliki pengalaman dan minat di industri game. Para pendiri memiliki latar belakang yang beragam, termasuk pemrograman, desain artistik, rekayasa suara, dan manajemen proyek. Motivasi mereka untuk mendirikan Palm Studio berasal dari keinginan untuk menyatukan keahlian dan pengalaman mereka dalam sebuah entitas yang fokus pada inovasi dan kreativitas dalam pengembangan permainan.  Sejak berdiri, Palm Studio telah mencapai beberapa tonggak penting dalam perkembangannya. Mereka telah berhasil merilis beta test beberapa permainan yang mendapat sambutan positif dari para pemain dan kritikus. Pengalaman mereka yang kaya dalam industri game telah membantu mereka membangun pondasi yang kuat untuk pertumbuhan masa depan. Palm Studio terus mengembangkan portofolio mereka dengan mengikuti tren terbaru dalam industri game dan menjaga kualitas permainan mereka.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Palm Studio adalah sebuah perusahaan pengembangan permainan (game development) yang berfokus pada menciptakan pengalaman bermain yang menghibur dan inovatif. Mereka bergerak di industri game, merancang dan mengembangkan permainan untuk berbagai platform, termasuk PC dan perangkat mobile. Palm Studio didirikan oleh sekelompok individu yang telah memiliki pengalaman dan minat di industri game. Para pendiri memiliki latar belakang yang beragam, termasuk pemrograman, desain artistik, rekayasa suara, dan manajemen proyek. Motivasi mereka untuk mendirikan Palm Studio berasal dari keinginan untuk menyatukan keahlian dan pengalaman mereka dalam sebuah entitas yang fokus pada inovasi dan kreativitas dalam pengembangan permainan. Sejak berdiri, Palm Studio telah mencapai beberapa tonggak penting dalam perkembangannya. Mereka telah berhasil merilis beta test beberapa permainan yang mendapat sambutan positif dari para pemain dan kritikus. Pengalaman mereka yang kaya dalam industri game telah membantu mereka membangun pondasi yang kuat untuk pertumbuhan masa depan. Palm Studio terus mengembangkan portofolio mereka dengan mengikuti tren terbaru dalam industri game dan menjaga kualitas permainan mereka.</span><br></p>', '2024-01-02', '2024-12-02', '2024-04-22 12:45:46', '2025-07-14 21:06:39');
INSERT INTO `tenant` VALUES (3346, 19, 'public/foto_profil_tenant/6625fa5f2bdde.png', 'Nutriwell', 'I Gusti Ayu Nita Janisya', 23, 2, 'Br.Petang Suci, DS.Petang, Kec. Petang, Badung', NULL, '50.000,00', 'Istagram,  WhatsApp', NULL, NULL, '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Nutriwell adalah Start up yang secara eksklusif berfokus pada produksi mie sehat dengan bahan-bahan organik dan berkualitas yang mana kami akan menggunakan beberapa sayur mayur seperti bayam, labu siam dan wortel serta kami tidak menggunakan msg. Nutriwell juga ingin membantu para pedagang sayur untuk meminimalisir limbah sayur yang selalu dibuang ketika tidak laku terjual. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:513,&quot;3&quot;:{&quot;1&quot;:0},&quot;12&quot;:0}\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Nutriwell adalah Start up yang secara eksklusif berfokus pada produksi mie sehat dengan bahan-bahan organik dan berkualitas yang mana kami akan menggunakan beberapa sayur mayur seperti bayam, labu siam dan wortel serta kami tidak menggunakan msg. Nutriwell juga ingin membantu para pedagang sayur untuk meminimalisir limbah sayur yang selalu dibuang ketika tidak laku terjual.</span><br></p>', '2024-01-02', '2024-12-12', '2024-04-22 12:48:27', '2024-04-22 12:49:19');
INSERT INTO `tenant` VALUES (3347, 19, 'public/foto_profil_tenant/6626007834aa7.png', 'Ngelindeng Photography', 'I Made Jun Laori', 22, 5, 'Br. Jasan No 57, Sebatu, Tegallalang, Gianyar, Bali', NULL, '40.000,00', NULL, NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Ngelindeng\r\n  photography adalah usaha yang bergerak di bidang jasa fotografi, dengan\r\n  segmen pasar yang kami sasar yaitu wisudawan, orang yang mau menikah, dan\r\n  orang liburan.</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 13:15:20', '2024-04-22 13:15:20');
INSERT INTO `tenant` VALUES (3348, 19, 'public/foto_profil_tenant/66260495816a7.jpg', 'Seraya Popcorn', 'I Komang Agus Adi Saputra', 23, 2, 'Jalan Seraya-Amed,BanjarTukad Buah Seraya Timur, Karangasem-Bali', NULL, '1.000.000,00', NULL, NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Seraya\r\n  Organik adalah wirausaha sosial (socio-entrepreneur)berbasis masyarakat yang\r\n  didirikan di Desa Seraya, KabupatenKarangasem-Bali. Usaha ini bergerak di\r\n  bidang pienyediaanproduk organik dan produk olahan organik yang\r\n  prosespenanaman dan produksinya berasal dari sumber daya alam danmanusia di\r\n  Desa Seraya.Tujuannya adalah untuk membangkitkankembali kejayaan Desa Seraya\r\n  sebagaidaerah penghasil jagungberkualitas tinggi.</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 13:32:53', '2024-04-22 13:32:53');
INSERT INTO `tenant` VALUES (3349, 19, 'public/foto_profil_tenant/662606e23ab04.jpg', 'Rescentify', 'Ni Kadek Sri Mas Dwayani', 12, NULL, 'Kuta Utara, Badung, Bali', NULL, '2.000.000,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Rescentify\r\n  adalah startup yang bergerak di bidang pengolahan limbah minyak goreng\r\n  menjadi produk bermanfaat berupa lilin aromaterapi yang aromanya bisa\r\n  disesuaikan dengan keinginan dan keperluan pengguna. Rescentify menyediakan\r\n  platform digital melalui halaman web yang akan memudahkan pengguna untuk\r\n  dapat menemukan dan melakukan pemesanan lilin sesuai dengan preferensi aroma\r\n  mereka.</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 13:42:42', '2024-04-22 13:42:42');
INSERT INTO `tenant` VALUES (3356, 19, 'public/foto_profil_tenant/662608eb1e82c.jpeg', 'Taman Sari Rental bali', 'I Putu Jagat Satria', 33, 5, 'Jl. Pura Desa No.8, Peguyangan Kangin, Kec. Denpasar Utara, Kota Denpasar, Bali 80238', NULL, '5.000.000,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Taman\r\n  Sari Rental Bali merupakan usaha yang bergerak di bidang jasa, yang\r\n  memberikan penyewaan kendaraan berupa mobil khususnya minibus.</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 13:51:23', '2024-04-22 13:51:23');
INSERT INTO `tenant` VALUES (3358, 19, 'public/foto_profil_tenant/66260b3385023.png', 'Bali Treesco', 'Ni Putu Lisa Cahaya Dewi', 23, 2, 'Jl. Lembu sora no 20, Denpasar', NULL, '5.000.000,00', NULL, NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Bali\r\n  treesco adalah produsen coconut product yang diantaranya coconut sugar,\r\n  coconut milk powder, dan virgin coconut oil</td></tr></tbody></table>', '2024-01-02', NULL, '2024-04-22 14:01:07', '2025-07-14 20:53:21');
INSERT INTO `tenant` VALUES (3359, 19, NULL, 'Chakeku', 'Ni Putu Angga Riastika Putri', 23, NULL, 'Tumbak bayuh, canggu, badung, bali', NULL, '2.500.000,00', 'Istagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Chakeku\r\n  menjual makanan dari yg manis sampai yg asin asin juga ada dengan farian rasa\r\n  baru dan istimewa, kami menjual dari desert sampai pasta selain itu juga ada\r\n  seblak yg paling laris</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:17:38', '2024-04-22 14:17:38');
INSERT INTO `tenant` VALUES (3360, 19, 'public/foto_profil_tenant/66260ff4661f3.png', 'Benerin.id', 'Sayyidah Amalia Rokhimah', 22, 5, 'Universitas Primakara', NULL, '10.000.000,00', 'Website, Istagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Benerin.id\r\n  adalah startup yang jadi solusi untuk mengatasi sulit nya mencari teknisi\r\n  servis</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:21:24', '2024-04-22 14:21:24');
INSERT INTO `tenant` VALUES (3361, 19, NULL, 'Vestbiz', 'I Gst Agung Ayu Wulan Permana Dewi', 44, NULL, 'Jl. Tukad Badung No.135, Renon, Denpasar Selatan, Kota Denpasar, Bali 80226', NULL, '3.000.000,00', 'Istagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Vestbiz\r\n  adalah usaha yang menjual jasa poto produk untuk pemasaran suatu bisnis</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:23:45', '2024-04-22 14:23:45');
INSERT INTO `tenant` VALUES (3362, 19, NULL, 'Warkop Djaja Abadi', 'Edward Peter Kurniawan', 23, NULL, 'Jl. Tukad Badung 141b', NULL, '25.000.000,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Warkop\r\n  Djaja Abadi Bali didirikan pada 24 Januari 2020 oleh 2 remaja yang memiliki\r\n  ketertarikan dalam dunia kopi. UMKM ini bergerak dibidang Makanan dan Minuman\r\n  dimana berfokus di penjualan minuman kopi baik panas maupun dingin.<br>\r\n    <br>\r\n    </td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:26:23', '2024-04-22 14:26:23');
INSERT INTO `tenant` VALUES (3363, 19, NULL, 'Tria Aksesoris', 'Luh Leniya Dyantari Artha', 11, NULL, 'Undisan Kelod, Tembuku, Bangli', NULL, '10.000.000,00', 'Istagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Usaha\r\n  yang bergerak di bidang pengerajin akasesoris rias pengantin bali</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:30:29', '2024-04-22 14:30:29');
INSERT INTO `tenant` VALUES (3364, 19, 'public/foto_profil_tenant/66261568df6d3.PNG', 'TAKSU', 'NI KADEK MUTIARA SETIAWATI', NULL, 5, 'Br. Pacung, Ds. Keliki,  Tegallalang, Gianyar', NULL, '2.000.000,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Taksu\r\n  adalah sebuah platform digital untuk membantu sanggar-sanggar yang ada di\r\n  Bali serta pelaku seniman Bali dalam dalam bidang marketing/promosi kepada\r\n  customer/penikmat seni. Taksu menyediakan jasa make up tarian Bali dan\r\n  distributor yang menjual atau menyewakan kostum tarian kesenian khususnya\r\n  Bali dengan harga yang terjangkau tetapi tetap dengan kualitas, sehingga\r\n  pelaku seni mudah dalam mencari kostum dan make up yang bagus dan\r\n  berkualitas.</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:44:40', '2024-04-22 14:44:40');
INSERT INTO `tenant` VALUES (3365, 19, NULL, 'Tika Herbal', 'Putu Intan Julia Pratiwi', 23, 2, 'Jl. Imam Bonjol, Gg. Batan Kepel No.9, Denpasar. Pekandelan, Pemecutan Kelod, Denpasar Barat.', NULL, '2.000.000,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Memproduksi\r\n  dan menjual olahan jamu herbal dengan resep tradisional, dan lebih pas di\r\n  lidah anak muda</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:46:39', '2024-04-23 13:30:05');
INSERT INTO `tenant` VALUES (3366, 19, 'public/foto_profil_tenant/6626167c31edd.png', 'Fundamental Codes', 'I Wayan Adi Sudirtayasa', 44, 5, 'Universitas Primakara', NULL, NULL, NULL, NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Bootcamp\r\n  pemrograman</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:49:16', '2024-04-22 14:49:16');
INSERT INTO `tenant` VALUES (3367, 19, NULL, 'Sevent (sobat event)', 'Ida Bagus Surya Wangsa', 44, 5, 'Universitas Primakara', NULL, NULL, NULL, NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Start\r\n  up yang menyediakan layanan sewa barang jada untuk memenuhi keperluan event\r\n  anda</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:53:10', '2024-04-22 14:53:10');
INSERT INTO `tenant` VALUES (3368, 19, NULL, 'Pesona Plastic', 'I Dewa Agung Ary Krisna', 13, 4, 'Jl Raya banjar tubuh Gg Bima No: 2, Batubulan,Gianyar,Bali', NULL, '8.000.000,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Pesona\r\n  Plastic adalah sebuah bisnis yang bergerak di bidang pengolahan limbah sampah\r\n  plastik menjadi barang-barang eksterior maupun interior. Pesona plastic juga\r\n  mempunyai program untuk melayani masyarakat dengan mengadakan bank sampah di\r\n  beberapa banjar di daerah batubulan dan pesona plastic ini bersifat sosial\r\n  jadi dengan sentiasa menerima masyarakat yang mau belajar&nbsp; tentang pengolahan sampah dan bersama\r\n  menciptakan lingkungan yang bersih bersama masyarakat. Pesona plastic juga\r\n  telah bekerjasama dengan beberapa UMKM,prusahaan dan kampus demi menciptakan\r\n  kesadaran masyarakat yang tinggi terhadap masalah limbah sampah plastik</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:55:46', '2024-04-22 14:55:46');
INSERT INTO `tenant` VALUES (3369, 19, 'public/foto_profil_tenant/662618efbdbb2.png', 'Hita Upakara', 'Ni Luh Gede Yasningsih', NULL, NULL, 'Universitas Primakara', NULL, '500,00', 'Instagram', NULL, NULL, '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"212\" style=\"width: 159pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"212\" style=\"height:15.75pt;width:159pt\">Awal\r\n  mula penemuan ide Startup Hita Upakara bermula dari adanya dampak pandemi\r\n  Covid-19 membuat perekonomian di Bali menjadi terpuruk sehingga memerlukan\r\n  perhatian khusus agar segera pulih. Untuk dapat menopang dan menggerakkan\r\n  ekonomi daerah, usaha upakara atau banten menjadi salah satu alternatif\r\n  karena usaha ini terbilang cukup mudah karena warga Bali sudah terbiasa\r\n  dengan berbagai banten upakara, lalu untuk peminat dari banten ini juga\r\n  tergolong banyak dikarenakan banyak wanita di Bali yang berperan sebagai\r\n  business women, yang sangat memerlukan bantuan dalam menjalankan kewajibannya\r\n  sebagai warga Bali dalam menjalani kebudayaan yang ada di Bali. Hita Upakara\r\n  merupakan startup yang bergerak dibidang jasa yang menyediakan platform\r\n  penjualan produk dari industri kreatif di bidang budaya salah satunya\r\n  upakara.</td></tr></tbody></table>', '2024-01-02', '2024-12-02', '2024-04-22 14:59:43', '2024-04-22 14:59:43');
