INSERT INTO `tenant` VALUES (3405, 230, 'public/foto_profil_tenant/663aeb186bad1.png', 'Wishfood Indonesia', 'Miftahurrizki', 23, 2, 'Kawasan Inkubasi Bisnis BRIDA NTB - JL. By Pass Zamia 2, Desa Lelede, Kecamatan Kediri, Kabupaten Lombok Barat, Provinsi Nusa Tenggara Barat', NULL, '2.000.000,00', 'Website, Facebook, Instagram, Marketplace,', 'Seluruh daerah di Provinsi NTB, Nasional', 'Menggunakan Aplikasi Keuangan', '<p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:等线;mso-bidi-font-family:\'Times New Roman\';\r\nfont-size:11,0000pt;\">Wishfood Indoensia merupakan sebuah usaha yang berfokus pada penjualan produk yang dihasilkan oleh perempuan pesisir yang berlokasi di pesisir Nusa Tenggara Barat. Usaha ini didirikan oleh beberapa pemuda di Kabupaten Lombok Timur yang berfokus terhadap bidang sosiopreneur. Sampa saat ini Wishfood Indonesia telah bermitra dengan Kelompok Perempuan Pesisir yang ada di Nusa Tenggara Barat dengan lebih dari 5 produk hasil perikanan dan kelautan.</span><span style=\"mso-spacerun:\'yes\';font-family:等线;mso-bidi-font-family:\'Times New Roman\';\r\nfont-size:11,0000pt;\"><o:p></o:p></span></p>', '2023-12-29', '2025-12-29', '2024-05-08 10:01:44', '2024-05-08 10:01:44');
