INSERT INTO `tenant` VALUES (3470, 613, 'public/foto_profil_tenant/66a5f46b5b6ff.jpg', 'Wirausaha Coffee Shop” Yuks Ngopi”', 'Sahdan Anwar (5404211414) , Trisya Ramayani (5604221074), Wirda Tuljannah (5604221076),  Zulfa  Salsabila (5604221073)', 23, 2, 'Politeknik Negeri Bengkalis', NULL, '0', 'Instagram', 'Sekitaran kampus', 'Konvensional', 'Pemilik usaha ini merupakan Mahasiswa yang menerima hibah dari kegiatan Program Mahasiswa Wirausaha. Kegiatan ini merupakan kegiatan rutin yang menjadi cikal bakal untuk menumbuhkan minat Mahasiswa berwirausaha. Untuk hibah yang diberikan sebesar Rp.&nbsp;<span style=\"font-size:11.0pt;line-height:115%;\r\nfont-family:&quot;Bookman Old Style&quot;,serif;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;mso-bidi-font-family:Calibri;color:black;\r\nmso-ansi-language:EN-US;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">16.934.000</span>', '2023-11-14', '2026-11-14', '2024-06-27 09:16:55', '2024-07-29 14:31:41');
INSERT INTO `tenant` VALUES (3471, 613, 'public/foto_profil_tenant/66a5f743da19c.png', 'Wirausaha Coffee Shop “ Makanan Ringan Sehat dari Mahasiswa untuk Mahasiswa', 'Zidan Nurhisyam (5404211397), Dea Khoirun Nisa (5604221513),  Alia (5604211398)', 23, 2, 'Politeknik Negeri Bengkalis', NULL, '2.000.000,00', 'Instagram', 'Sekitaran kampus', 'Konvensional', '<p><span style=\"color: rgb(33, 37, 41);\">Pemilik usaha ini merupakan Mahasiswa yang menerima hibah dari kegiatan Program Mahasiswa Wirausaha. Kegiatan ini merupakan kegiatan rutin yang menjadi cikal bakal untuk menumbuhkan minat Mahasiswa berwirausaha. Untuk hibah yang diberikan sebesar Rp.&nbsp;</span><span style=\"font-size: 11pt; line-height: 16.8667px; font-family: &quot;Bookman Old Style&quot;, serif; color: black;\">4.000.000</span><br></p>', '2023-11-14', '2026-11-14', '2024-06-27 09:24:51', '2024-07-29 15:08:56');
