INSERT INTO `tenant` VALUES (3571, 584, 'public/foto_profil_tenant/668f7b5e5f237.png', 'Resep Siro', 'Siti Ropiah', 23, NULL, 'Dusun Plaosan RT 4 RW 1 Gendoh Kecamatan Sempu Kabupaten Banyuwangi', NULL, NULL, 'Instagram', 'Banyuwangi, Jawa Timur', NULL, '<p><span class=\"OYPEnA text-decoration-none text-strikethrough-none\" style=\"color: rgb(0, 0, 0);\">Resep Siro adalah usaha yang fokus di bidang cake dan cookies, khususnya brownies lumer, brownies crispy, dan aneka kue kering lebaran. Produk-produk ini merupakan unggulan dari dapur kami dan sangat diminati oleh semua kalangan. Kami tidak hanya melayani pesanan individu, tetapi juga telah mensuplai produk kami ke berbagai supermarket di seluruh Banyuwangi. Kualitas dan rasa yang konsisten membuat produk kami menjadi pilihan favorit pelanggan. Kami terus berinovasi untuk menghadirkan variasi kue yang lezat dan berkualitas tinggi, memenuhi kebutuhan pasar yang terus berkembang.</span><br></p>', '2024-06-20', '2024-06-28', '2024-07-11 13:27:42', '2024-07-11 13:27:42');
INSERT INTO `tenant` VALUES (3572, 351, 'public/foto_profil_tenant/668f7bca5a459.jpg', 'HUNS BATIK', 'ANJAR HANI PRATIWI', 26, 1, 'DONOWARIH RT 04 RW 03 BULAKAN SUKOHARJO', NULL, '30.000.000,00', 'media sosial', 'Nusantara', NULL, '<p>Jual batik lurik</p>', '2024-06-10', NULL, '2024-07-11 13:29:30', '2024-07-11 13:29:30');
INSERT INTO `tenant` VALUES (3573, 584, 'public/foto_profil_tenant/668f7ca5ccc22.png', 'Javcolletion', 'Suyanti', NULL, 1, 'Perumahan Berlian Citra Kertanegara Blok G No 6 Banyuwangi', NULL, NULL, 'Instagram', NULL, NULL, '<p><span class=\"OYPEnA text-decoration-none text-strikethrough-none\" style=\"color: rgb(0, 0, 0);\">Javcollection adalah toko fashion atau baju wanita yang mengikuti trend fashion terkini dengan berbagai macam model baju yg uptodate dengan kwalitas terbaik. Dengan banyak nya model- model baju terbaru seperti blouse, gamis, kemeja, knit import, celana, rok dan berbagai macam hijab. Javcollection juga melayani pembelian ecer dan grosir dengan harga murah.</span></p><p><br></p>', '2024-06-20', '2024-06-28', '2024-07-11 13:33:09', '2024-07-11 13:33:09');
