INSERT INTO `tenant` VALUES (3680, 587, 'public/foto_profil_tenant/669f23fdcda2e.png', 'Tepang', 'IGN. WISETO PRASETYO AGUNG, S.T., M.Sc., Ph.D', 44, 5, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, 'tepang.id', NULL, NULL, '<p class=\"MsoNormal\" style=\"margin-left:36.0pt;text-indent:9.0pt\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-font-kerning:0pt;mso-ligatures:none;mso-ansi-language:EN-ID\">Tepang\r\nmerupakan layanan yang akan hadir di platform web dan mobile yang bergerak\r\ndalam bidang olahraga penyewaan lapangan, sekolah sepak bola dan event\r\nolahraga. Dalam tepang kamu bisa menemukan berbagai lapangan olahraga yang kamu\r\nbutuhkan dan dapat mengikuti berbagai event olahraga yang sudah tersedia\r\ndidalam aplikasi.<o:p></o:p></span></p>', NULL, NULL, '2024-07-23 10:31:09', '2024-07-23 10:31:09');
INSERT INTO `tenant` VALUES (3681, 587, 'public/foto_profil_tenant/669f290df0f20.png', 'Ensiklotari', 'IEDAM FARDIAN ANSHORI, S.T,M.Kom, M.M.', 44, 5, 'Jalan Sekolah Internasional No.1-2 Antapani, Bandung - Jawa Barat, Indonesia 40282', NULL, NULL, 'ensiklotari.id', 'Nasional', NULL, '<p class=\"MsoNormal\" style=\"margin-left:36.0pt;text-indent:9.0pt\"><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-font-kerning:0pt;mso-ligatures:none\">Seni Tari selalu identik sebagai bukti\r\nkeragaman budaya Nusantara. Dari Sabang sampai Merauke, masyarakat Indonesia\r\nberekspresi melalui berbagai gerak tari yang atraktif dan menggambarkan\r\nkeharmonisan bangsa. Selain itu, seni tari pun membawa banyak manfaat untuk kesehatan\r\njasmani dan rohani. Tapi sejujurnya, sejauh apa kita mengenal ragam gerak tari\r\nIndonesia ? EnsikloTari akan membawa Anda dalam perjalanan untuk\r\nmengembalikan&nbsp;The Joy Of Dancing.Menemukan ketenangan,&nbsp;that it\'s OK\r\nto not be OK.&nbsp;Para pemula dapat belajar sesuai dengan kecepatan mereka\r\nsendiri. Tanpa malu, tanpa ragu. Pintu sanggar terbuka lebar. Anda dapat\r\nbelajar dari sanggar mana pun, di mana pun, dan di waktu yang Anda mau.<o:p></o:p></span></p>', '2022-01-01', '2022-12-31', '2024-07-23 10:52:45', '2024-07-23 10:52:45');
INSERT INTO `tenant` VALUES (3682, 587, 'public/foto_profil_tenant/669f2b9853afe.png', 'Netters', 'Ervian Junianto', 22, 5, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, 'Netters.id', 'Nasional', NULL, '<p>Netters adalah program komputer ( AI ) yang dirancang untuk berinteraksi dengan pengguna khususnya mahasiswa ARS University melalui percakapan berbasis teks untuk memberikan informasi seputar perkuliahan.<br></p>', '2023-01-01', '2023-12-31', '2024-07-23 10:58:48', '2024-07-23 11:03:36');
INSERT INTO `tenant` VALUES (3683, 587, 'public/foto_profil_tenant/669f2ad2a39d5.png', 'NgeKost', 'ANI SOLIHAT, S.Pd., SST., MM', 44, 5, 'Jalan Sekolah Internasional No.1-2 Antapani, Bandung - Jawa Barat, Indonesia 40282', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoNormal\" style=\"margin-left:36.0pt;text-indent:9.0pt\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-font-kerning:0pt;mso-ligatures:none;mso-ansi-language:EN-ID\">NgeKost</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-font-kerning:0pt;mso-ligatures:none;mso-ansi-language:EN-ID\"> merupakan\r\naplikasi digital yang menyediakan akses bagi masyarakat untuk menemukan dan\r\nmemesan layanan akomodasi berupa rumah kost dengan fitur-fitur menarik di\r\ndalamnya. \"NgeKost\" hadir memberikan solusi untuk mempermudah\r\npengguna dalam&nbsp;melakukan pencarian &nbsp; kost- kostan &nbsp; yang &nbsp;\r\ndiinginkan, di tengah aktivitas yang padat tanpa harus repot <i>survey </i>ke\r\nbeberapa tempat dan wilayah yang berbeda,pastinya&nbsp; akan memakan waktu,\r\nenergi, dan biaya transportasi.<o:p></o:p></span></p>', '2022-01-01', '2022-12-31', '2024-07-23 11:00:18', '2024-07-23 11:00:18');
INSERT INTO `tenant` VALUES (3684, 587, 'public/foto_profil_tenant/669f2b5de9ad7.png', 'RUANG KARYA', 'Panji Firman Rahadi', 44, 5, 'Jalan Sekolah Internasional No.1-2 Antapani, Bandung - Jawa Barat, Indonesia 40282', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoNormal\" style=\"margin-left:36.0pt;text-indent:9.0pt\"><b><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-font-kerning:0pt;mso-ligatures:none\">Ruang Karya </span></b><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\r\nmso-font-kerning:0pt;mso-ligatures:none\">bergerak sebagai platform yang\r\nberfokus pada Virtual Reality. Produk pertama yang akan diproduksi oleh Ruang\r\nKarya adalah replika artefak-artefak budaya Sunda dalam bentuk modelling 3\r\ndimensi.<o:p></o:p></span></p>', '2022-01-01', '2022-12-31', '2024-07-23 11:02:37', '2024-07-23 11:02:37');
INSERT INTO `tenant` VALUES (3685, 587, 'public/foto_profil_tenant/669f2bd41c022.jpg', 'PANDAI STUDIO', 'IEDAM FARDIAN ANSHORI, S.T,M.Kom, M.M.', 44, 5, 'Jalan Sekolah Internasional No.1-2 Antapani, Bandung - Jawa Barat, Indonesia 40282', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoListParagraph\"><b><span style=\"font-size:\r\n12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:\r\nEN-ID\">Pandai Studio </span></b><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">merupakan sebuah\r\nplatform sebagai penyedia jasa webinar. Dengan harga yang terjangkau bagi\r\npelajar dan masyarakat umum</span><span lang=\"EN-US\" style=\"font-size:12.0pt;\r\nline-height:107%;font-family:&quot;Times New Roman&quot;,serif\"><o:p></o:p></span></p>', '2022-01-01', '2022-12-01', '2024-07-23 11:04:36', '2024-07-23 11:04:36');
INSERT INTO `tenant` VALUES (3686, 587, 'public/foto_profil_tenant/669f2c12a526c.jpeg', 'Vachat', 'Iedam Fardian Anshori', 22, 5, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, 'vachat.id', 'Nasional', NULL, '<p class=\"MsoListParagraph\"><span lang=\"EN-ID\">adalah program komputer yang dirancang untuk\r\nmelakukan percakapan dengan manusia melalui antarmuka teks. Dengan kemajuan\r\nkecerdasan buatan, chatbot ini lebih canggih dalam mengenali bahasa manusia dan\r\nmemberikan respons yang relevan melalui Aplikasi Whatsapp<o:p></o:p></span></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:05:38', '2024-07-23 11:18:58');
INSERT INTO `tenant` VALUES (3687, 587, 'public/foto_profil_tenant/669f2c58a356d.png', 'REALSIGHT', 'DINAR DINA KARAMANI, S.I.KOM., M.I.KOM', NULL, NULL, 'RealSight merupakan platform media digital yang hadir untuk memfasilitasi kompetensi yang dimiliki oleh seluruh masyarakat yang ingin berkontribusi dalam memberikan sajian informasi valid, edukatif dan research-based kepada masyarakat luas. Serta, menjadikan platform media digital yang dapat berkontribusi dalam melestarikan Bahasa Indonesia dan bahasa daerah serta berkontribusi untuk menguasai bahasa asing.', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoListParagraph\"><b><span style=\"font-size:\r\n12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:\r\nEN-ID\">RealSight </span></b><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">merupakan platform\r\nmedia digital yang hadir untuk memfasilitasi kompetensi yang dimiliki oleh\r\nseluruh masyarakat yang ingin berkontribusi dalam memberikan sajian informasi\r\nvalid, edukatif dan <i>research-based </i>kepada masyarakat luas. Serta,\r\nmenjadikan platform media digital yang dapat berkontribusi dalam melestarikan\r\nBahasa Indonesia dan bahasa daerah serta berkontribusi untuk menguasai bahasa\r\nasing.<o:p></o:p></span></p>', '2022-01-01', '2022-12-31', '2024-07-23 11:06:48', '2024-07-23 11:06:48');
INSERT INTO `tenant` VALUES (3688, 587, 'public/foto_profil_tenant/669f2cc2d0469.png', 'Tekku', 'Salman Topiq', 22, 5, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, 'tekku_id', 'Nasional', NULL, '<p class=\"MsoListParagraphCxSpFirst\" style=\"text-align:justify;text-indent:.5in\"><b><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Tekku</span></b><span style=\"font-family:&quot;Times New Roman&quot;,serif\"> adalah platform yang menyediakan\r\njasa perbaikan elektronik <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-left:0in;mso-add-space:auto;\r\ntext-align:justify;text-indent:.5in\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">yang\r\nmudah dijangkau, handal, dan terpercaya. Dengan memanfaatkan <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-left:0in;mso-add-space:auto;\r\ntext-align:justify;text-indent:.5in\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">teknologi,\r\nTekku menjamin transparansi dalam biaya perbaikan, proses <o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoListParagraphCxSpLast\" style=\"margin-left:0in;mso-add-space:auto;\r\ntext-align:justify;text-indent:.5in\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">perbaikan,\r\ndan pembelian suku cadang<o:p></o:p></span></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:08:34', '2024-07-23 11:20:53');
INSERT INTO `tenant` VALUES (3689, 587, 'public/foto_profil_tenant/669f2cc60dc16.png', 'ACCOME', 'Reza Rizkina Taufik, S.I.Kom., M.M', 44, 5, 'Jalan Sekolah Internasional No.1-2 Antapani, Bandung - Jawa Barat, Indonesia 40282', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoListParagraph\"><b><span style=\"font-family:\r\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Accome</span></b><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"> merupakan\r\nsingkatan dari accommodate yang memiliki arti akomodasi, ACCOME ialah startup\r\nyang dapat memberikan jasa penyewaan MC, fotografer dan videografer terbaik\r\ndengan membangun relasi dengan pengguna maupun client seluas mungkin agar dapat\r\nmemberikan pelayanan terbaik bagi kedua belah pihak.<o:p></o:p></span></p>', '2022-01-01', '2022-12-31', '2024-07-23 11:08:38', '2024-07-24 11:29:42');
INSERT INTO `tenant` VALUES (3690, 587, 'public/foto_profil_tenant/669f2d8c64d9d.png', 'EduTrack', 'ALI AKBAR RISMAYADI', NULL, NULL, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, 'edutrack.id', 'Nasional', NULL, '<p class=\"MsoListParagraph\" style=\"text-align:justify;text-indent:.5in\"><b>Edutrack</b>\r\nadalah platform website yang mempermudah siswa siswi kelas 12 untuk menentukan\r\njurusan untuk masuk ke perguruan tinggi negeri atau swasta dengan bantuan\r\nkuisoner pilihan, dan menghubungkan ke alumni jurusan<o:p></o:p></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:11:56', '2024-07-23 11:21:31');
INSERT INTO `tenant` VALUES (3691, 587, 'public/foto_profil_tenant/669f2d914f147.png', 'KINALAMAN', 'Yudi Ramdhani', 44, 5, 'KINALAMAN menjadi platform terbaik dalam bidang pertanian. Platform adalah media yang menyediakan fasilitas-fasilitas untuk para pegiat bisnis melakukan kegiatan jual beli.', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoListParagraph\"><b><span style=\"font-family:\r\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">KINALAMAN </span></b><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">menjadi\r\nplatform terbaik dalam bidang pertanian. Platform adalah media yang menyediakan\r\nfasilitas-fasilitas untuk para pegiat bisnis melakukan kegiatan jual beli.<o:p></o:p></span></p>', '2021-01-01', '2021-12-31', '2024-07-23 11:12:01', '2024-07-23 11:12:01');
INSERT INTO `tenant` VALUES (3692, 587, 'public/foto_profil_tenant/669f2df924f5e.png', 'PRANKO', 'Asti Herliana, S.Kom, M.Kom', 28, 4, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, NULL, 'Nasional', NULL, '<p class=\"MsoListParagraph\"><b><span style=\"font-family:\r\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Pranko</span></b><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"> merupakan\r\nsebuah apparel brand yang bergerak pada bidang fashion dengan mengusung tema\r\nnature/alam. Pranko bertujuan untuk memanfaatkan barang bekas dari pakaian yang\r\nsudah tak terpakai.<o:p></o:p></span></p>', '2022-01-23', '2022-12-31', '2024-07-23 11:13:45', '2024-07-23 11:27:35');
INSERT INTO `tenant` VALUES (3693, 587, 'public/foto_profil_tenant/669f2eb0b731c.png', 'NATURLICH', 'Sari Susanti, S.Kom., M.Kom', 43, 1, 'Jalan Sekolah Internasional No.1-2 Antapani, Bandung - Jawa Barat, Indonesia 40282', NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoListParagraph\"><b><span style=\"font-family:\r\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Natürlich</span></b><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"> dibentuk\r\nsejak Januari 2019 dan masih berjalan sampai sekarang, Natürlich termasuk ke\r\ndalam kategori usaha produksi yang bergerak di bidang perawatan/kecantikan.\r\nNatürlich diciptakan untuk menjadi solusi bagi permasalahan kulit wajah seperti\r\nkusam,berminyak dan kulit berjerawat.<o:p></o:p></span></p>', '2022-01-01', '2022-12-31', '2024-07-23 11:16:48', '2024-07-23 11:16:48');
INSERT INTO `tenant` VALUES (3694, 587, 'public/foto_profil_tenant/669f2ee8a3b90.png', 'TANARA', 'SARI SUSANTI', NULL, NULL, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, 'tanara.id', 'Nasional', NULL, '<p class=\"MsoListParagraphCxSpFirst\" style=\"text-align:justify;text-indent:.5in\"><b><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Tanara</span></b><span style=\"font-family:&quot;Times New Roman&quot;,serif\"> adalah startup yang bergerak di\r\nbidang jual beli rumah dan bangunan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">dengan konsep yang berbeda dari\r\nyang lain. Tanara tidak hanya menawarkan properti<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">yang berkualitas, tetapi juga\r\nmemberikan arah dan bimbingan kepada pelanggan untuk<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">menemukan properti yang sesuai\r\ndengan keinginan dan kebutuhan mereka. Tanara<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">memiliki tim ahli yang siap\r\nmembantu pelanggan dalam proses jual beli properti, mulai<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">dari survei, negosiasi, perizinan,\r\nhingga pembiayaan. Tanara juga memiliki platform<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">online yang mudah digunakan, dimana\r\npelanggan bisa mencari, membandingkan, dan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">memesan properti yang diinginkan\r\ndengan cepat dan aman. Tanara berkomitmen untuk<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">memberikan layanan terbaik dan\r\nterpercaya kepada pelanggan,serta menjadi mitra yang<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">dapat diandalkan dalam mencapai\r\nimpian memiliki properti.<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoListParagraphCxSpLast\" style=\"text-align:justify\"><o:p>&nbsp;</o:p></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:17:44', '2024-07-23 11:17:44');
INSERT INTO `tenant` VALUES (3695, 587, 'public/foto_profil_tenant/669f320958652.png', 'AQIBERS', 'das', NULL, NULL, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, NULL, NULL, NULL, '<p><b><span style=\"font-size:11.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;mso-fareast-theme-font:\r\nminor-latin;mso-ansi-language:EN-US;mso-fareast-language:EN-US;mso-bidi-language:\r\nAR-SA\">Aqibers</span></b><span style=\"font-size:11.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;mso-fareast-theme-font:\r\nminor-latin;mso-ansi-language:EN-US;mso-fareast-language:EN-US;mso-bidi-language:\r\nAR-SA\"> adalah sebuah platform online penyedia jasa pembelian hewan secara\r\nonline yang di khusukan untuk aqiqah dengan memberikan akses pilihan hewan\r\nberkualitas sesuai syariat, transparansi informasi, dan layanan pendukung\r\nseperti pengiriman dan pemotongan sesuai syariat.</span><br></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:30:49', '2024-07-23 11:31:05');
INSERT INTO `tenant` VALUES (3696, 587, 'public/foto_profil_tenant/669f328d49c53.png', 'MOCHINTA', 'SD', NULL, NULL, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"margin-left:.5in;text-align:justify;text-indent:.5in\"><b>Mochinta</b>\r\n(Mochi yang dibuat dengan sepenuh cinta) merupakan dessert mochi dengan isian\r\nbuah strawberry segar yang dibalut dengan coklat. Mochinta dapat menjadi solusi\r\nuntuk meningkatkan suasana hati. Perpaduan serasi antara tepung ketan yang\r\nkenyal dan tidak terlalu manis dengan isian strawberry segar, manis, serta asam\r\nyang dibaluti oleh cokelat menyempurnakan rasa dari produk Mochinta. Mochinta\r\njuga merupakan makanan yang mengenyangkan perut dan simpel untuk dibawa kemana\r\npun dan kapan pun.<o:p></o:p></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:33:17', '2024-07-23 11:33:17');
INSERT INTO `tenant` VALUES (3697, 587, 'public/foto_profil_tenant/669f32e2ef8fd.png', 'GYOZHU', 'SA', NULL, NULL, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoListParagraph\" style=\"text-align:justify;text-indent:.5in\"><b>Gyozhu</b>\r\ndibentuk sejak 2023 dan masih berjalan sampai sekarang, Gyozhu termasuk ke\r\ndalam kategori usaha produksi yang bergerak di bidang makanan. Gyozhu\r\ndiciptakan untuk menjadi solusi bagi para konsumen yang menyukai makanan khas\r\njepang namun tetap ingin mempertahankan khas dari negaranya sendiri. Gyozhu ini\r\nmemiliki bahan dasar tahu putih dan memiliki bahan lain, sawi, wortel, telur\r\ndan ayam . Gyozhu merupakan singkatan dari Gyoza Tahu , meskipun gyoza ini\r\nmemiliki bahan dasar tahu namun rasanya tetap seimbang dengan bahan lainnya.<o:p></o:p></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:34:42', '2024-07-23 11:34:42');
INSERT INTO `tenant` VALUES (3698, 587, 'public/foto_profil_tenant/669f333197452.png', 'NARAGIH', 'Ani Solihat', NULL, NULL, 'Antapani, Jl. Terusan Sekolah No.1-2, Cicaheum, Kec. Kiaracondong, Kota Bandung, Jawa Barat 40282', NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"margin-left:.5in;text-align:justify;text-indent:.5in\"><b>Naragih</b> dibentuk sejak awal tahun\r\n2023, yang diinisiasi oleh 5 orang mahasiswa Ilmu Komunikasi angkatan 2021\r\nUniversitas ARS. Produk yang kami ciptakan adalah produk “Keripik kentang dan\r\nCemilan Naragih” sebagai kategori produk makanan sehat. “Naragih” hadir memberikan\r\nsolusi untuk meningkatkan pilihan varian baru keripik kentang dengan banyak\r\npilihan rasa, terutama di kalangan anak muda / remaja. Tujuan “Naragih” hadir\r\nagar keripik kentang semakin banyak disukai oleh banyak orang termasuk\r\nanak-anak dan remaja.<o:p></o:p></p>', '2023-01-01', '2023-12-31', '2024-07-23 11:36:01', '2024-07-23 11:40:58');
INSERT INTO `tenant` VALUES (3699, 391, 'public/foto_profil_tenant/66a081da78148.jpeg', 'Rastra', 'M. Nuh', 23, 2, 'Desa Rambai Kecamatan Pangkalan Lampam Kab. OKI Prov. Sumsel', NULL, '10.000.000,00', 'ig, Facebook', 'Kabupaten Ogan Komering Ilir dan Kota Palembang', NULL, NULL, NULL, NULL, '2024-07-24 11:06:56', '2024-07-24 11:32:14');
INSERT INTO `tenant` VALUES (3700, 73, 'public/foto_profil_tenant/66a30a3c3f953.png', 'USMAN', 'Elik Hari Muktafin', 22, NULL, 'Yogyakarta', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Alat sterilisasi lantai masjid berbasis robotik dikombinasikan dengan sinar UVC</span><br></p>', '2021-05-08', '2024-05-08', '2024-07-26 09:30:20', '2024-07-26 09:35:48');
INSERT INTO `tenant` VALUES (3701, 73, 'public/foto_profil_tenant/66a30a9cc5c53.jpeg', 'Halo Servis', 'Oky Putra Pamungkas', 22, NULL, 'kp panjangan rt6 rw6', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">HALO SERVIS, SEBUAH PLATFORM DIMANA PENGGUNA DAPAT MENEMUKAN INFORMASI TERKAIT KERUSAKAN DEVICE (LAPTOP, HANDPHONE /SMARTPHONE, PRINTER) DAN DAPAT MELAKUKAN KONSULTASI SERTA MENDAPATKAN LAYANAN PERBAIKAN DEVICE ON DEMAND, TANPA HARUS REPOT DATANG KE TEMPAT SERVICE</span><br></p>', '2021-05-08', '2024-05-08', '2024-07-26 09:31:56', '2024-07-26 09:35:24');
INSERT INTO `tenant` VALUES (3702, 73, 'public/foto_profil_tenant/66a30b29743c2.jpg', 'CULTURE ACADEMY INDONESIA', 'HENDRIANSYAH', 22, NULL, 'Jln. Ngabul - Bawu , RT.39 . RW.08 Jepara , jawa tengah', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Culture Academy Indonesia Adalah Suatu Platform yang disiapkan Khusus untuk UMKM , untuk membantu meningkatkan kualitas produk kerajinan UMKM di indonesia</span><br></p>', '2021-05-08', '2024-05-08', '2024-07-26 09:34:17', '2024-07-26 09:35:05');
INSERT INTO `tenant` VALUES (3703, 73, 'public/foto_profil_tenant/66a30be4119f9.JPG', 'DeTroBot_Vision', 'Reza Baihaqi Nur', 22, NULL, 'Tamansari Indah J2 Bondowoso', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Platform Robot Vision dan Computer Vision Berbasis Internet of Things (IoT) dan Manajemen Data System Sebagai Solusi Efektivitas dan Efisiensi Pada Era Kehidupan Baru</span><br></p>', '2021-05-08', '2024-05-08', '2024-07-26 09:37:24', '2024-07-26 09:37:24');
INSERT INTO `tenant` VALUES (3704, 73, 'public/foto_profil_tenant/66a30c60e41bd.jpeg', 'SOJA', 'Ratu Tiara Azzahranur', 23, NULL, 'Komplek sawangan elok blok a1 no 17 rt 01 rw 10. Depok', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Somay yang biasanya terbuat dari daging ayam maupun daging ikan, namun pada produk kami terbuat dari Jamur Tiram yang mana somay dengan bahan baku jamur tiram ini jarang ditemukan. Penggunaan jamur tiram dengan harga yang ekonomis namun kaya kandungan, jamur tiram mudah ditemukan dan dapat  membantu para pengusaha jamur untuk diolah menjadi makanan cemilan seperti somay</span><br></p>', '2021-08-07', '2024-08-07', '2024-07-26 09:39:28', '2024-07-26 09:39:28');
INSERT INTO `tenant` VALUES (3705, 73, 'public/foto_profil_tenant/66a30cc8a41a1.jpeg', 'Eteris', 'Abdurrafi', 26, NULL, 'Taman Dramaga Permai 3, Blok D6/1, Cihideung Udik, Ciampea, Kab. Bogor', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">ETERIS diambil dari nama lain minyak \r\natsiri yaitu Etheric Oil. ETERIS berlokasi di Kabupaten Bogor tepatnya di \r\nTaman Dramaga Permai 3, Blok D5/2, Desa Cihideung Udik, Kecamatan \r\nCiampea. Eteris merupakan produk anti nyamuk alami yang menggunakan bahan \r\naktif fraksi minyak serai wangi sehingga aman bagi kesehatan. Eteris aman \r\ndigunakan oleh segala usia, segala jenis kulit serta harga yang terjangkau. Bahan aktifnya \r\ndibuat dengan Teknologi Fraksinasi yang membuat produk ETERIS memiliki \r\naroma wangi yang unik dan dapat dijadikan sebagai aromaterapi sekaligus. \r\nETERIS menggunakan bahan aktif 100% essential oil sehingga aman \r\ndigunakan tanpa khawatir sesak napas, batuk, ruam merah, dan gatal-gatal. </span><br></p>', '2021-08-10', '2024-08-10', '2024-07-26 09:41:12', '2024-07-26 09:41:12');
INSERT INTO `tenant` VALUES (3706, 73, 'public/foto_profil_tenant/66a30d38a3f19.jpg', 'FogharvesTex', 'Nurmalinda Rahmawati', 22, NULL, 'Villa Padurenan Indah II Blok B No.5 RT 06 RW 07 Kel. Padurenan Kec. Mustika Jaya Kota Bekasi 17156', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Alat Penangkap Kabut Berbahan Tekstil Inspirasi dari Alam sebagai Sumber Air Alternatif dari Udara</span><br></p>', '2021-08-15', '2024-08-15', '2024-07-26 09:43:04', '2024-07-26 09:43:04');
INSERT INTO `tenant` VALUES (3707, 73, 'public/foto_profil_tenant/66a30d8ed823a.jpg', 'Rho Co', 'Vannisa Wulandari', 26, NULL, 'Kencana Loka Sektor 12.5', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Produksi kolagen dengan brand Rho Co sebagai produk inovasi  ini mengacu terhadap kebutuhan pasar lokal dan pasar impor terhadap kolagen di bidang kosmetik. Terlebih di masa depan produk kolagen ini dapat dikembangkan dibidang farmasi dan kesehatan untuk memperbaiki atau meregenasi sel-sel yang rusak melalui stem sel. Industri ini juga memanfaatkan limbah sisik ikan dari produk samping pengalengan dan pengolahan ikan di perairan Indonesia. Sehingga dari limbah tersebut dapat ditingkatkan nilai jual dan nilai ekonomisnya\r\n</span></p><div><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\"><br></span></div>', '2021-08-16', '2024-08-16', '2024-07-26 09:44:30', '2024-07-26 09:44:30');
INSERT INTO `tenant` VALUES (3708, 73, 'public/foto_profil_tenant/66a30de7ed5d5.jpeg', 'Dub Dub', 'Tetra Perwira', 22, NULL, 'jl abdul wahab rt 03 rw 03 no 26 sawangan depok 16511', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Alat kesehatan yang digunakan untuk mendeteksi secara dini kelainan jantung pada penggunanya yang terintegrasi dengan aplikasi yang dapat berkonsultasi dengan kardiolog secara langsung dan pembacaan hasil data rekam jantung secara langsung.</span><br></p>', '2021-08-18', '2024-08-18', '2024-07-26 09:45:59', '2024-07-26 09:45:59');
INSERT INTO `tenant` VALUES (3709, 73, 'public/foto_profil_tenant/66a30eae1c540.jpg', 'PROTOBLIND', 'Muhammad Akmal Rizki Rivaldi', 22, NULL, 'Tegal, Jawa Tengah', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Protoblind merupakan sebuah usaha yang memproduksi dan menjual IDOPU, yaitu Inovasi Dompet Pendeteksi Uang, alat bantu pendeteksian uang berbentuk dompet yang diperuntukkan untuk tunanetra. Selain untuk tunanetra, IDOPU juga dapat digunakan masyarakat pada umumnya</span><br></p>', '2021-08-20', '2024-08-20', '2024-07-26 09:49:18', '2024-07-26 09:49:18');
INSERT INTO `tenant` VALUES (3710, 73, NULL, 'Bursatan Investa Agraria', 'Ghani Fikri Baihaqi', NULL, NULL, 'Jl Syibromalisi Blok C No.4 RT 06 RW 01 komplek LBS, Cilegon, Banten', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Equity qrowdfunding Budidaya Tanaman Porang dan Pepaya</span><br></p>', '2021-08-23', '2024-08-23', '2024-07-26 09:50:56', '2024-07-26 09:50:56');
INSERT INTO `tenant` VALUES (3711, 73, 'public/foto_profil_tenant/66a312fd8d149.png', 'Rhisoya', 'Elza Wijaya', 23, NULL, 'Villa Melati Mas blok I10/28', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">RHISOYA merupakan produk kaldu nabati berbentuk bubuk yang diolah dari tempe semangit dan dihasilkan melalui teknologi tinggi terkini.\r\nRHISOYA telah melalui penelitian bertahap untuk mencapai cita rasa yang diinginkan. Terbuat dari proses fermentasi alami dari tempe semangit yang diformulasikan dengan perpaduan bahan pilihan sehingga menciptakan rasa gurih.\r\nRHISOYA dibuat dari bahan alami berkualitas tanpa penambahan MSG, pewarna, dan pengawet. Sangat praktis digunakan untuk menambahkan rasa gurih pada masakan Anda sehari-hari.</span><br></p>', '2021-08-26', '2024-08-26', '2024-07-26 10:07:41', '2024-07-26 10:07:41');
INSERT INTO `tenant` VALUES (3712, 73, 'public/foto_profil_tenant/66a3183063309.png', 'Jasa Prototyping dengan 3D printing dan Casting Resin', 'Ilham Defra Nugraha', NULL, NULL, 'Jl. Mawar X, D3/7, Taman Kedaung, Pamulang, Tangerang Selatan.', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">menyediakan jasa pembuatan dan produksi (manufaktur) untuk mewujudkan berbagai objek, benda, atau barang yang ada anda imajinasikan (prototyping dan product development), dengan metode yang sedia saat ini 3D printing dan Casting Resin. </span><br></p>', '2021-10-21', '2024-10-21', '2024-07-26 10:29:52', '2024-07-26 10:29:52');
INSERT INTO `tenant` VALUES (3713, 73, 'public/foto_profil_tenant/66a318c39691d.jpg', 'Sagu Keju Ikan Tuna', 'Jupandes muki', 23, NULL, 'Jl.karadenan RT/RW 002/009 NO.120 KEL.KARADENAN KEC.CIBINONG KAB.BOGOR', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Saat Hari Raya tiba, kue kering biasanya menjadi salah satu kudapan yang wajib tersaji di meja. Selain kue nastar dan kastangel, kue sagu keju juga bisa dibilang wajib hadir diantaranya. Kali ini Healthy bar mencoba inovasi baru dengan menambah varian rasa pada Kue sagu keju ini. Ikan tuna menjadi salah satu pilihan inovasi rasa baru, ikan tuna sirip kuning merupakan komiditi yang banyak di laut indonesia sama hal nya seperti tepung sagu atau tepung tapioka. Dari 2 komoditi yang banyak di indonesia ini healthy bar menggabungkan nya agar menjadi kue kering premium dengan segudang gizi dari ikan tuna. Sagu keju ini sangat aman di makan segala umur karna tidak mengandung terigu sama sekali atau bisa di bilang \"GLUTEN FREE\" , sagu keju ikan tuna nikmat di konsumsi sambil minum kopi atau teh. \r\nDari inovasi produk ini, healthy bar berharap dapat mengenalkan makanan khas indonesia kepada dunia.\r\nSAGU KEJU IKAN TUNA \"ENAK, SEHAT, PECAH DIMULUT\"</span><br></p>', '2021-10-27', '2024-10-27', '2024-07-26 10:32:19', '2024-07-26 10:32:19');
INSERT INTO `tenant` VALUES (3714, 73, NULL, 'Pempek,Tekwan,Siomay dan Jus Buah / Kuliner', 'Iwan', 23, NULL, 'Reni Jaya Jl. Sumbawa III m2 18 Pamulang Tangsel', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Kami  menyajikan sebuah hidangan praktis yang cepat sajikan, kami memilih mengolah buah-buahan segar untuk dijadikan jus buah kemasan botol dan ikan hasil laut negri kita untuk diolah menjadi Pempek, Tekwan serta siomay dengan harapan membantu meningkatkan kesediaan makanan yang bergizi dan menyehatkan. Cocok dikonsumsi oleh anak-anak hingga orang dewasa .Hasil olahan ikan kami menghilangkan aroma amis ikan karena bahan baku yang kami gunakan adalah bahan baku segar.\r\n</span><br></p>', '2022-01-26', '2025-01-26', '2024-07-26 10:34:05', '2024-07-26 10:34:05');
INSERT INTO `tenant` VALUES (3715, 73, 'public/foto_profil_tenant/66a3198f3e56b.jpg', 'Serundeng Ayam Suir by Dw Catering', 'Purwanti Wilujeng', 23, NULL, 'Vila Pamulang Mas E4 No 6 Pamulang Tangsel', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Olahan Ayam dan Kelapa Parut segar yang dibumbui dengan aneka rempah rempah yang menyehatkan dan lezat</span><br></p>', '2022-01-26', '2025-01-26', '2024-07-26 10:35:43', '2024-07-26 10:35:43');
INSERT INTO `tenant` VALUES (3716, 73, 'public/foto_profil_tenant/66a319e69e12d.png', 'Aneka sambal kemasan dgn merk Ceu\'Meti', 'Selamet Ibrohim', 23, NULL, 'Komplek Griya Pamulang Lestari blok A no 7 pamulang Tangsel', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Sambal Obonk adalah sambal kemasan dengan menggunakan 2 kali proses pengolahan sehingga menghasilkan rasa dan aroma yang Otentik Khas Sambal Obonk Ceu\' Meti dan meninggalkan pengalaman yang berbeda ketika mengkonsumsi sambal Obonk , makanya tagline sambal ceu\'meti, juaranya temen nasi. \r\nSambal obonk diproduksi saat ini dg menghasilkan 5 varian, sambal bawang, Sambal rebon, sambal cumi, sambal jambal dan sambal bandeng. </span><br></p>', '2022-01-26', '2025-01-26', '2024-07-26 10:37:10', '2024-07-26 10:37:10');
INSERT INTO `tenant` VALUES (3717, 73, 'public/foto_profil_tenant/66a31a6a8b0bd.png', 'AYAM TALIWANG DAPUR NYONYA GENDUT', 'NONOT YULIANTORO', 23, NULL, 'JL. SALVIA 1 BLOK UD NO. 15, SEKTOR 1.2 EXTENSION GRIYA LOKA, RT. 003, RW. 006, KEL. RAWABUNTU, KEC.SERPONG, KOTA TANGERANG SELATAN', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">AYAM TALIWANG DAPUR NYONYA GENDUT dimasak dengan bumbu bumbu otentik nusantara,. Ayam ukuran utuh dengan konsep hidangan untuk keluarga, dengan harga yang terjangkau. sekali mencoba pasti bikin nagih.</span><br></p>', '2022-01-26', '2025-01-26', '2024-07-26 10:39:22', '2024-07-26 10:39:22');
INSERT INTO `tenant` VALUES (3718, 73, 'public/foto_profil_tenant/66a31ac887a34.jpg', 'Kacang Bawang dan Akar Kelapa \"Kanjeng\"', 'Endang Triwahyuni Muchtar', 23, NULL, 'Komplek Puspiptek Blok 1 D no 6 RT 012 RW 06, Setu, Tangerang Selatan', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Kacang Bawang Kanjeng merupakan produk yg kami oleh sedemikian rupa sehingga rendah minyak dan kolesterol. Berbeda dari kacang kebanyakan, kacang kanjeng dgn ukuran bulir yg besar sehingga lebih gurih . Dengan rasa gurih asli tanpa tambahan msh berpadu dg rasa asin dan manis. Cocok dinikmati seluruh kalangan baik usia anak-anak maupun dewasa dan semua gender \r\n\r\nAkar kelapa Kanjeng merupakan makanan ringan khas Betawi yg diolah dengan cita rasa kekinian. Dibuat dgn resep original akar kelapa namun dibentuk menyerupai churros yg lebih familiar di kalangan milenial. Memiliki 6 varian rasa,yaitu original,keju, coklat,jintan hitam, cinnamon,dan kelor.  Cocok dijadikan teman ngemil maupun hantaran utk keluarga</span><br></p>', '2022-01-26', '2025-01-26', '2024-07-26 10:40:56', '2024-07-26 10:40:56');
