INSERT INTO `tenant` VALUES (3725, 73, 'public/foto_profil_tenant/66a3237ad313d.jpg', 'Makaroni Rese', 'Riska larasati', 23, NULL, 'Jl. Kemiri Raya No. 62 Rt. 003 Rw. 011 Pondok Cabe udik Pamulang Tangerang selatan', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Makaroni Rese ( Renyah, enak, special )\r\nMakaroni yg diolah dari minyak pilihan menghasilkan tekstur menjadi renyah membuat makaroni ini digemari kalangan remaja, anak - anak maupun dewasa. </span><br></p>', '2022-01-27', '2025-01-27', '2024-07-26 11:18:02', '2024-07-26 11:18:02');
INSERT INTO `tenant` VALUES (3726, 73, 'public/foto_profil_tenant/66a323d03a21d.jpg', 'Kerupuk RHR', 'Mamat', 23, NULL, 'Jln babakan pocis gg mandor rt 02 rw02 no 35 kel baktijaya kec setu tangsel', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Kerupuk RHR \r\nSebagai produsen olahan makanan ringan berbahan baku tepung tapioka bumbu bumbu pilihan dan berbahan dasar ikan dengan merek rhr .  rhr ber cita cita mencipta kan produk produk makanan atau cemilan yang sehat kreatif  inovatif memenuhi asupan nutrisi setiap orang khusus nya makan makanan yang mengandung segala kebaikan ikan, jengkol, kentang, bawang merah\r\n\r\n</span></p>', '2022-01-27', '2025-01-27', '2024-07-26 11:19:28', '2024-07-26 11:19:28');
