INSERT INTO `tenant` VALUES (3967, 152, 'public/foto_profil_tenant/66bc3247e84a0.jpg', 'Hanenda', 'Meyna Cinta', 47, 1, 'Sendangadi Sleman', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-08-14 11:27:51', '2024-08-14 11:27:51');
INSERT INTO `tenant` VALUES (3968, 152, 'public/foto_profil_tenant/66bc33d08a454.png', 'Baskara', 'Romandon Wahyu Prastiyo', 47, 1, 'Sempu Wedomartani', NULL, '4.500,00', 'IG Web', NULL, NULL, '<p>Baskara merupakan usaha di bidang fashion yang memproduksi pakaian kekinian dengan mengangkat konsep budaya nusantara untuk dikenalkan kepada generasi muda Indonesia sebagai upayamelestarikan kekaayaan budaya Indonesia melalui media yang kreatif dan kekinian.</p>', '2023-02-08', '2023-02-08', '2024-08-14 11:34:24', '2024-08-30 10:00:30');
INSERT INTO `tenant` VALUES (3969, 104, 'public/foto_profil_tenant/66bc4ff97f68c.jpeg', 'Mentaisiss', 'Fachrul Aulia Razak', 23, 7, 'Dekat pemancingan, Lembah griya indah blok G5 ujung no 27, RT.05/RW.09, Cipayung Jaya, Cipayung', NULL, '450.000.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>Mentai rice dengan toping ayam karage yang sudah di slice dan di atasnya ditambahkan dengan sauce mentai, mentaisiss ini terbuat dari bahan berkualitas sehingga aman untuk di konsumsi setiap waktu.<br></p>', '2023-06-05', NULL, '2024-08-14 13:34:33', '2024-08-14 13:34:33');
INSERT INTO `tenant` VALUES (3970, 10, 'public/foto_profil_tenant/66bc5269481bd.jpg', 'Goat Milk Sahi', 'Dora Didanata', 23, 7, 'Jl. Tasikmadu Regency Jl. Atletik Kav 27, Tasikmadu, Kec. Lowokwaru, Kota Malang, Jawa Timur 65143', NULL, '80.000.000,00', 'Online  dan offline', 'indonesia', NULL, '<div class=\"flex max-w-full flex-col flex-grow\"><div data-message-author-role=\"assistant\" data-message-id=\"dd64f529-c477-46ef-8e22-926a867ca0c4\" dir=\"auto\" class=\"min-h-[20px] text-message flex w-full flex-col items-end gap-2 whitespace-pre-wrap break-words [.text-message+&amp;]:mt-5 overflow-x-auto\"><div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\"><div class=\"markdown prose w-full break-words dark:prose-invert dark\"><p><strong>Goat Milk Sahi</strong> adalah usaha yang bergerak di bidang produksi dan penjualan susu kambing segar yang dihasilkan dari kambing pilihan dengan proses yang higienis dan alami. Produk susu kambing ini kaya akan nutrisi penting seperti kalsium, protein, dan vitamin, serta mudah dicerna, sehingga cocok untuk berbagai kalangan usia, termasuk anak-anak dan orang tua. Selain menyediakan susu kambing murni, Goat Milk Sahi juga menawarkan berbagai varian rasa dan produk turunan, seperti yogurt dan keju, yang diolah tanpa bahan pengawet atau pewarna buatan. Dengan komitmen pada kualitas dan kesehatan konsumen, Goat Milk Sahi siap menjadi pilihan utama bagi mereka yang mencari produk susu kambing berkualitas tinggi.</p></div></div></div></div><div class=\"mt-1 flex gap-3 empty:hidden -ml-2\"><div class=\"items-center justify-start rounded-xl p-1 flex\"><div class=\"flex items-center\"><span class=\"\" data-state=\"closed\"><br></span></div></div></div><p></p>', '2021-04-10', '2022-04-10', '2024-08-14 13:44:57', '2024-08-14 13:44:57');
INSERT INTO `tenant` VALUES (3971, 104, 'public/foto_profil_tenant/66bc56d02b45f.png', 'Prof Dito', 'Rosi Hatala', 46, 6, 'Jl. TB Simatupang No.18, Kebagusan, Ps. Minggu, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12520 (Lantai 10)', NULL, '20.000.000,00', 'Media sosial', 'Nasional', 'Digital', '<p>Prof.Dito merupakan platform tes Bahasa Indonesia/Asing yang menyediakan berbagai macam jenis soal yang bisa kamu kerjakan.</p><p>Disusun oleh para profesional dengan pengalaman lebih dari 15 tahun dalam pelatihan Bahasa Asing, desain kurikulum dan pengembangan materi pembelajaran.</p>', '2023-06-05', NULL, '2024-08-14 14:00:45', '2024-08-14 14:03:44');
INSERT INTO `tenant` VALUES (3972, 104, 'public/foto_profil_tenant/66bc5e74371bb.png', 'buangsampah.com', 'Rudi Setiawan', 50, 6, 'Aplikasi Android, yang dapat meningkatkan pendapatan ekonomi masyarakat dari penjualan sampah, menciptakan peluang kerja bagi pengangkut sampah, menciptakan ekonomi sirkular, dengan melibatkan peran serta masyarakat secara massif dan melakukan pengolahan sampah secara berkelanjutan menuju zero waste', NULL, '11.200.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>Aplikasi Android, yang dapat meningkatkan pendapatan ekonomi masyarakat dari penjualan sampah, menciptakan peluang kerja bagi pengangkut sampah, menciptakan ekonomi sirkular, dengan melibatkan peran serta masyarakat secara massif dan melakukan pengolahan sampah secara berkelanjutan menuju zero waste<br></p>', '2023-06-05', NULL, '2024-08-14 14:36:20', '2024-08-15 10:19:27');
INSERT INTO `tenant` VALUES (3973, 104, 'public/foto_profil_tenant/66bc5faceedde.jpg', 'CG Automatic Plant Monitoring System', 'Christian Jonathan Pascoal', 48, 6, 'Jl Gandaria 2 Blok FF3 No.2, Sukatani', NULL, '1.000.000,00', 'Media sosial', 'Lokal', 'Non digital', '<p>Startup yang berdedikasi untuk memperkenalkan solusi inovatif untuk pemantauan tanaman secara otomatis. Menggabungkan teknologi canggih dengan kecintaan kami pada alam, kami bertujuan untuk memberdayakan para petani, pecinta tanaman, dan penghobi taman dalam merawat dan memantau tanaman mereka dengan cara yang lebih efisien dan akurat.<br></p>', '2023-06-05', '2023-12-31', '2024-08-14 14:41:32', '2024-08-15 10:20:08');
INSERT INTO `tenant` VALUES (3974, 104, 'public/foto_profil_tenant/66bc60ef3c73c.jpg', 'Rizolles Yummy', 'Indri Damayanti Ismi', 23, 7, 'Jln. Kp. Pulo No.56 Rt/Rw 008/04, Kel. Pinang Ranti , Kec. Makasar , Jakarta Timur', NULL, '2.400.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>Risol mayones, memiliki cita rasa yang berbeda serta isi lebih banyak.<br></p>', '2023-06-05', '2023-12-31', '2024-08-14 14:46:55', '2024-08-14 14:56:25');
INSERT INTO `tenant` VALUES (3975, 104, 'public/foto_profil_tenant/66bc62ec1f42a.jpg', 'HealTiny', 'Fitri Hindarti', 23, 7, 'Jakarta', NULL, '15.000.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>HealTiny merupakan Chicken Salad Roll dimana mengandung unsur hewani dan nabati. Salad dressing dengan varian rasa yang menggugah selera dan dibaluri dengan kulit tortila membuat kombinasi rasa spectacular.<br></p>', '2023-06-05', '2023-12-31', '2024-08-14 14:55:24', '2024-08-14 14:55:24');
INSERT INTO `tenant` VALUES (3976, 104, 'public/foto_profil_tenant/66bc68ac1dd6f.png', 'Kenzu', 'Salwa Fatima Zahra', 23, 7, 'Bogor', NULL, '250.000.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>Cemilan Saus Keju yang tidak bikin eneg, mengandung kalsium, vitamin A, dan vitamin D<br></p>', '2023-06-05', '2023-12-31', '2024-08-14 15:19:56', '2024-08-15 10:50:38');
INSERT INTO `tenant` VALUES (3978, 104, NULL, 'Pawplus', 'Ridwan Kusumawardani', 43, NULL, 'Cirebon', NULL, NULL, NULL, NULL, NULL, '<p>Pawplus adalah platform inovatif yang dirancang untuk menyederhanakan perawatan hewan peliharaan dengan menghubungkan pemilik hewan dengan dokter hewan secara efisien. Dengan visi menghadirkan layanan kesehatan hewan yang terjangkau, terpercaya, dan menyenangkan, Pawplus bertujuan untuk mengatasi tantangan yang dihadapi pemilik hewan peliharaan dalam menemukan klinik terdekat, mendapatkan informasi yang akurat, dan berkonsultasi dengan dokter hewan.<br></p><div><br></div>', NULL, NULL, '2024-08-14 16:06:15', '2024-08-14 16:06:15');
INSERT INTO `tenant` VALUES (3980, 104, 'public/foto_profil_tenant/66bc76d7c5a4c.png', 'Caksana Daycare Plus', 'Siti Hafifah', 46, 9, 'Jakarta', NULL, '5.000.000,00', 'Media sosial', 'Lokal', 'Digital', '<p class=\"MsoNormal\">Caksana Daycare Plus adalah tempat penitipan anak usia dini\r\ndengan fokus pendidikan, pengasuhan, perawatan, pertumbuhan, dan perkembangan\r\nanak dengan berbagai sentra bermain yang dirancang untuk mendukung lima aspek\r\nperkembangan: kognitif, sosial-emosional, bahasa, fisik dan motorik.<o:p></o:p></p>', '2024-07-04', NULL, '2024-08-14 16:20:23', '2024-08-14 16:24:50');
INSERT INTO `tenant` VALUES (3982, 104, 'public/foto_profil_tenant/66bd5d9fddaed.jpg', 'Onikitty', 'Silvia Atriyanti Saputri', 14, 2, 'Jakarta', NULL, '3.915.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>Onikitty adalah inovasi produk makanan kucing yang menggabungkan dua tekstur sekaligus dalam satu bentuk yang menyerupai onigiri dengan bahan tepung maggot black soldier fly<br></p>', '2024-07-04', NULL, '2024-08-15 08:45:03', '2024-08-15 08:45:03');
INSERT INTO `tenant` VALUES (3983, 104, NULL, 'Chessin', 'Erliana Bertha Larasati', 23, 7, 'Jl. Purbasari no 134 rt 004/003, kel. gunung batu, Bogor, 16118', NULL, '7.497.000,00', 'Media sosial', 'Lokal', 'Non digital', NULL, NULL, NULL, '2024-08-15 10:27:17', '2024-08-15 10:27:17');
INSERT INTO `tenant` VALUES (3984, 104, NULL, 'Bimbel Bazil', 'Isnawati', 46, 9, 'JALAN AUP RT006/010 NO 45 PASAR MINGGU', NULL, NULL, NULL, NULL, NULL, '<p>Lembaga bimbingan belajar (bimbel) membaca,menulis dan berhitung (calistung) bagi anak usia dini (4-9 tahun) dengan prioritas utama segmen kami adalah anak yang berasal dari kalangan menengah ke bawah namun kami juga tidak menutup pintu untuk anak dari kalangan menengah ke atas untuk dapat menuntut ilmu di bimbel ini.<br></p>', '2023-06-05', '2023-06-05', '2024-08-15 10:36:29', '2024-08-15 14:51:53');
INSERT INTO `tenant` VALUES (3985, 104, 'public/foto_profil_tenant/66bda47336799.png', 'Praktekin', 'Firmansyah', 46, 6, 'Jl. Kav Polri No. 63, Kec. Jagakarsa, Jakarta Selatan 12550 , DKI Jakarta,\r\nIndonesia', NULL, '1.000.000,00', 'Media sosial', 'Lokal', 'Digital', '<p>Praktekin adalah platform pendidikan digital inovatif yang memberdayakan mahasiswa akhir dan lulusan baru untuk mengembangkan diri, membangun portofolio, dan meraih kesuksesan karier.<br></p>', '2024-07-04', NULL, '2024-08-15 13:47:15', '2024-08-15 13:47:15');
INSERT INTO `tenant` VALUES (3986, 16, 'public/foto_profil_tenant/66bdf97970db5.jpeg', 'Djamoer Doeloe', 'Hikmat Al Hakim', 48, 2, 'Jl. Al-Farabhi Blok GB No. 39 Perdos Tamalanrea', NULL, '4.000.000,00', 'Instagram dan WhatshApp', 'Sulawesi Selatan, Jawa Timur, dan Jakarta', NULL, '<p>Growkit merupakan produk yang digunakan sebagai pembelajaran awal untuk orang yang ingin budidaya jamur tiram yang di desain menarik, terdapat kurikulum budidaya, tempat konsultasi, resep Pembuatan jamur tiram, dan bisa dijadikan buah tangan untuk anak-anak hingga dewasa sebagai pembelajaran ketahanan pangan.<br></p>', '2024-06-03', '2024-12-31', '2024-08-15 19:48:42', '2024-08-20 10:22:24');
INSERT INTO `tenant` VALUES (3987, 16, 'public/foto_profil_tenant/66c31752c4f37.jpeg', 'PT Bolkom Amanah Agro', 'Arham, S.P.', 48, 2, 'Jalan Poros Kajang, Dusun Jampang Desa Tambangan, Kec. Kajang, Kab. Bulukumba', NULL, '3.750.000,00', 'Facebook', 'Nasional', NULL, '<p>Beras Jagung Bija\' lebih rendah kandungan Glukosa dan tinggi serat.<br></p>', '2024-06-03', '2024-12-31', '2024-08-15 19:54:17', '2024-08-19 16:58:42');
INSERT INTO `tenant` VALUES (3988, 16, 'public/foto_profil_tenant/66c317c8be7d4.png', 'PT. Agro Farm Econesia', 'Rahmat Hidayat S.Pi', 50, 2, 'Kantor di Jl. Mangga Besar no. 17 NTI, Kel. Kapasa, Kec. Tamalanrea Kota Makassar. Pabrik di Kec. Segeri, Kab. Pangkep, Prov. Sulsel.', NULL, '7.000.000,00', 'Instagram, WhatsApp, Tiktok, Youtube, Facebook dan juga pemasaran langsung seperti pasang Boot dan brosure', 'Indonesia Timur', NULL, '<p>Cyclevalue adalah brand Team sekaligus Farming / Pabrik yang berlokasi dipangkep.<br></p>', '2024-06-03', '2024-12-31', '2024-08-15 20:01:53', '2024-08-19 17:00:40');
INSERT INTO `tenant` VALUES (3989, 16, 'public/foto_profil_tenant/66c30ca955eea.png', 'Gerapari.id', 'Masyita BJ', 48, 2, 'Jalan sukamaju kasuarrang, Rt 002/Rw004, Allepolea, Kec. lau, Kab. Maros .', NULL, '2.400.000,00', 'WhatsApp', 'Makassar dan Maros', NULL, 'Gerapari Feed atau pakan gerapari merupakan Produk Pakan berbentuk Pakan pelet, Produk pakan ini diproduksi dengan bahan bahan yang memiliki sublayer bahan baku yang memadai untuk memastikan ketersediaan bahan baku terjamin, menggunakan bahan yang bisa dimanfaatkan dari alam, atau dari limbah yang mengandung protein sesuai dengan kebutuhan ikan yang dibudidayakan, gerapari feed ini Memegang teguh konsep Sahabat Pembudidaya, Dalam artian Harga pakan dan kandungan protein pakan bisa disesuaikan dengan kebutuhan dan budget pembudidaya itu sendiri.', '2024-06-03', '2024-12-31', '2024-08-15 20:25:10', '2024-08-19 16:13:13');
INSERT INTO `tenant` VALUES (3990, 16, 'public/foto_profil_tenant/66c31664af8c9.png', 'PT Tani Organik Indonesia', 'Muh. Ilmi Ikhsan Sabur, S.P.', 48, 2, 'Perum Nirwana Permai 3, Moncongloe Lappara, Moncongloe, Kab Maros', NULL, '5.000.000,00', 'Instagram dan Facebook', 'Provinsi Sulsel', NULL, '<p>Jasa penjualan dan pengantaran produk pertanian organik.</p><p>Produknya adalah beras organik.</p>', '2024-06-03', '2024-12-31', '2024-08-15 20:33:04', '2024-08-19 16:54:44');
INSERT INTO `tenant` VALUES (3991, 16, 'public/foto_profil_tenant/66c304305340b.jpeg', 'Aerasea Startup PT Media Teknologi Celebes', 'Abd Salam, S.T.', 48, 6, 'Jl. Poros Malino, Kelurahan Borongloe, Kec. Bontomarannu, Kab. Gowa, 92171', NULL, '3.000.000,00', 'Instagram dan B2B', 'Makassar', NULL, '<div>Aquanotes merupakan sistem cerdas optimalisasi manajemennya kualitas air kolam budi daya air payau dengan menggunakan teknologi Internet of Things terintegrasi Kecerdasan Buatan melalu aplikasi mobile.</div>', '2024-06-03', '2024-12-31', '2024-08-15 20:39:12', '2024-08-19 15:37:04');
INSERT INTO `tenant` VALUES (3992, 16, 'public/foto_profil_tenant/66c3153846144.jpg', 'PT Sitinaja Global Ekspor', 'Ahmad Azhar Rasak, S.IP.', 48, 2, '1. Alamat Kantor: Jl. Grahambel P1/B , Desa/Kelurahan Tamalanrea Jaya, Kec. Tamalanrea, Kota Makassar, Provinsi Sulawesi Selatan, Kode Pos: 90245\r\n2. Unit Kolaborasi untuk Produksi : Jl. Mattoanging, Balleangin, Kec. Ujung Loe, Kabupaten Bulukumba, Sulawesi Selatan 92562\r\n3. Gudang dan kantor pemasaran : Perum Dosen No.BLOK L NO.15 Unit 2, RT.002/RW.04, Tamalanrea, Jaya, Kec. Tamalanrea, Kota Makassar, Sulawesi Selatan 90245', NULL, '5.000.000,00', 'Instagram dan WhatsApp', 'Nasional dan Internasional', NULL, '<p>Cocopeat adalah produk diversifikasi sabut kelapa.</p>', '2024-06-03', '2024-12-31', '2024-08-15 20:47:06', '2024-08-20 10:30:38');
INSERT INTO `tenant` VALUES (3993, 16, 'public/foto_profil_tenant/66c3020ea971a.png', 'AIOF', 'Muh. Irwansyah', 48, 2, 'Moncongloe Lappara', NULL, '50.000,00', 'WhatsApp', 'Makassar', NULL, '<span style=\"color: rgb(31, 31, 31); font-family: &quot;Google Sans&quot;, Roboto, sans-serif; font-size: 12px; white-space-collapse: preserve;\">Artificial Intelegence Organik Farming (AIOF) merupakan lahan tanam yang menerapkan Smart farming.</span>', '2024-06-03', '2024-12-31', '2024-08-15 20:51:00', '2024-08-19 16:04:29');
