INSERT INTO `tenant` VALUES (3995, 16, 'public/foto_profil_tenant/66c31db065b44.jpg', 'Qindo-Cho', 'Haura Ganesia Hartawan', 48, 2, 'Jl. Poros Majene No.187 Lampa-Mapilli, Polewali Mandar, Sulawesi Barat', NULL, '3.000.000,00', 'Instagram dan Shopee', 'Jangkauan ke konsumen yang peduli dengan kesehatan, lingkungan, dan produk halal. Pasar domestik dan internasional, juga kolaborasi bersama para distributor', NULL, '<div>Qindo-Cho berfokus pada produksi coklat premium yang menggabungkan bahan-bahan alami dengan nilai kesehatan. Utamanya, produk ini terbuat dari biji kakao fermentasi yang pure berasal dari polewali mandar, gula aren alami serta bahan tambahan yang menyehatkan seperti daun kelor.</div>', '2024-06-03', '2024-12-31', '2024-08-15 20:58:59', '2024-08-20 10:32:07');
