INSERT INTO `tenant` VALUES (4276, 53, 'public/foto_profil_tenant/66ced3e4b2234.png', 'ROASTING KOPI ARJUNA ARABIKA (KAA), BIBIT STOBERI', 'Suliono', 2, 2, 'Ds. Klampok Bonjati RT 04 RW 06 Kec. Singosari Kab. Malang', NULL, '5.000.000,00', 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, NULL, NULL, NULL, '2024-08-28 14:38:12', '2024-08-28 14:38:12');
INSERT INTO `tenant` VALUES (4277, 53, 'public/foto_profil_tenant/66ced43117222.png', 'ROASTING COFEE BEAN, PRINTING KAOS MALANG', 'Wildan Reyvaldi R.', 47, 1, 'Malang', NULL, '5.000.000,00', NULL, 'Lokal, Nasional', NULL, NULL, NULL, NULL, '2024-08-28 14:39:29', '2024-08-28 14:39:29');
INSERT INTO `tenant` VALUES (4278, 53, 'public/foto_profil_tenant/66ced6ab4326e.png', 'NASI COKOT', 'Putri Silvia', 23, 7, 'Malang', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Nasi cokot merupakan olahan nasi putih yang umumnya berisi potongan ayam atau ayam suwir dan sambal, kemudian dibungkus dengan kertas nasi. Berbentuk seperti burger dan tersedia berbagai isian rasa seperti&nbsp; ikan tongkol suwir, dll</p>', NULL, NULL, '2024-08-28 14:50:03', '2024-08-28 14:50:03');
INSERT INTO `tenant` VALUES (4279, 53, 'public/foto_profil_tenant/66ced7327eb94.png', 'SAMBEL PECEL KARUNIA', 'Salsabilla Sukmana Putri', 23, 7, 'Dsn Banjarjo Ds Bangsri RT 04 RW 11 Kecamatan Nglegok Kab Blitar', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Sambel pecel ini merupakan makanan khas blitar yang memberikan rasa gurih dan pedas yang menambahkan rasa makanan lebih enak.&nbsp;</p>', NULL, NULL, '2024-08-28 14:52:18', '2024-08-28 14:52:18');
INSERT INTO `tenant` VALUES (4280, 53, 'public/foto_profil_tenant/66ced79447075.png', 'SNACK BOX', 'Gishela Ameliya P.', 23, 7, 'Malang', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Berupa aneka ragam kue basah yang nantinya di kemas di sebuah box. Tersedia variasi kue basah seperti risol mayo, apem, roti gulung, dll.&nbsp;</p>', NULL, NULL, '2024-08-28 14:53:56', '2024-08-28 14:53:56');
INSERT INTO `tenant` VALUES (4281, 53, 'public/foto_profil_tenant/66ced7dd7584f.png', 'KERIPIK SUKUN', 'Sayyid Hosen Afandi', 23, 7, 'Jln. Tata Surya no.03 Dinoyo Lowokwaru Kota Malang', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Produk ini berbahan dasar buah sukun yang di olah oleh masyarakat lokal Kangean, kripik sukun ini merupakan makanan ringan yang dapat di jadikan salah satu&nbsp; oleh-oleh khas Kangean.</p>', NULL, NULL, '2024-08-28 14:55:09', '2024-08-28 14:55:09');
INSERT INTO `tenant` VALUES (4282, 53, 'public/foto_profil_tenant/66ced8147af25.png', 'KUE KACANG', 'Nur Hidayah Asia Putri', 23, 7, 'Malang', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Kue kacang adalah kue yang terbuat dari kacang dengan bahan&nbsp; baku utama. Kue ini tersedia berbagai bentuk yang beragam.</p>', NULL, NULL, '2024-08-28 14:56:04', '2024-08-28 14:56:04');
INSERT INTO `tenant` VALUES (4283, 53, 'public/foto_profil_tenant/66ced84f11ae6.png', 'KRIPIK PISANG DANGPIT', 'Talita Ibtisama', 23, 7, 'Malang', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Kripik pisang dangpit beda dengan kripik pisang yang ada biasanya, kripik pisang satu ini memiliki beberapa&nbsp; macam rasa dan variasi ,untuk variasinya ada 2&nbsp; lumer&nbsp; dan kering, untuk yang kering ada rasa pedas, dan coklat, nangka dan durian, untuk yang lumer ada tiramitsu, coklat, susu, dan macha, kripik pisang ini tanpa pengawet buatan, dan kripik ini tergolong tidak terlalu bertahan lama jangka waktunya 1 bulan&nbsp;</p>', NULL, NULL, '2024-08-28 14:57:03', '2024-08-28 14:57:03');
INSERT INTO `tenant` VALUES (4284, 53, 'public/foto_profil_tenant/66ced88180102.png', 'D’CAMIL', 'Dewanty Rochmatulloh', 23, 7, 'Malang', NULL, NULL, 'Instagram, Shopee, Facebook, Tokopedia', 'Lokal, Nasional', NULL, '<p>Usaha makanan ringan, mulai dari kue kering sampai jajanan pedas. Cocok untuk teman setia kapanpun disaat kita merasa lapar.</p>', NULL, NULL, '2024-08-28 14:57:53', '2024-08-28 14:57:53');
