INSERT INTO `tenant` VALUES (4320, 152, 'public/foto_profil_tenant/66d1373b30b36.jpg', 'Diginus', 'Muhammad Alfi Ramadhan', 47, 8, 'Jl. Padjajaran Jl. Ring Road Utara No.104, Ngropoh, Condongcatur, Kec. Depok, Kabupaten Sleman, Daerah Istimewa Yogyakarta 55283', NULL, NULL, NULL, NULL, NULL, '<p>Diginus merupakan usaha yang memproduksi kartu permainan augmented reality bertema budaya Indonesia untuk mengenalkan budaya indonesia kepada generasi muda melalui permainan virtual yang dibuat lebih menarik dengan penggunaan augmented reality.</p>', NULL, NULL, '2024-08-30 10:06:35', '2024-08-30 10:06:35');
INSERT INTO `tenant` VALUES (4321, 152, 'public/foto_profil_tenant/66d138130cfe7.jpg', 'Drink With Telangi', 'Fatimah Az-zakiah', 23, 7, 'Jl. Padjajaran Jl. Ring Road Utara No.104, Ngropoh, Condongcatur, Kec. Depok, Kabupaten Sleman, Daerah Istimewa Yogyakarta 55283', NULL, NULL, NULL, NULL, NULL, '<p>Drink With Telangi merupakan usaha yang memproduksi minuman sehat kekinian dari bahan baku yaitu bunga telang. Usaha ini melakukan beberapa diversifikasi dengan membuat berbagai jenis minuman dari bahan bunga telang yang dipasarkan melalui media sosial.</p>', NULL, NULL, '2024-08-30 10:10:11', '2024-08-30 10:10:11');
INSERT INTO `tenant` VALUES (4322, 152, 'public/foto_profil_tenant/66d1397f8198d.jpg', 'Mocgumie', 'Fanisa Rahma Salsabila', 23, 7, 'Jl. Padjajaran Jl. Ring Road Utara No.104, Ngropoh, Condongcatur, Kec. Depok, Kabupaten Sleman, Daerah Istimewa Yogyakarta 55283', NULL, NULL, NULL, NULL, NULL, '<p>Mocgumie adalah usaha yang memproduksi produk mie sehat yang terbuat dari tepung mocaf dan campuran sayur bayam. Mocgumie menargetkan konsumen yang memiliki fokus pada makanan sehat dengan menyediakan produk mie sehat sehingga kosumen tetap dapat menikmati produk mie tanpa khawatir.</p>', NULL, NULL, '2024-08-30 10:16:15', '2024-08-30 10:16:15');
INSERT INTO `tenant` VALUES (4323, 152, 'public/foto_profil_tenant/66d13a10d6fdc.jpg', 'Girslhub', 'Ajeng Anugrah Djatmiko', 42, 6, 'Jl. Padjajaran Jl. Ring Road Utara No.104, Ngropoh, Condongcatur, Kec. Depok, Kabupaten Sleman, Daerah Istimewa Yogyakarta 55283', NULL, NULL, NULL, NULL, NULL, '<p>GirlsHub merupakan usaha yang mempertemukan influencer wanita dengan UMKM untuk dapat membentu menaikkan produk awareness melalui strategi endorsement melalui influencer wanita.</p>', NULL, NULL, '2024-08-30 10:18:40', '2024-08-30 10:18:40');
