INSERT INTO `tenant` VALUES (4365, 7, 'public/foto_profil_tenant/66daad647ba98.png', 'IHEART/ITSMEDIKA TEKGRO NARTOKU', '\"Abdullah Faqih Septiyanto, S.Kom, M.Kom  \"', 43, 6, 'Surabaya', NULL, NULL, 'Instagram', NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">Alat pengukuan Non-Invasif untuk tekanan darah menggunakan gelombang cahaya jari tangan.</span><br></p>', '2022-09-30', NULL, '2024-09-06 14:21:08', '2024-09-06 14:21:08');
INSERT INTO `tenant` VALUES (4366, 7, 'public/foto_profil_tenant/66daae1b28f1d.png', 'Inisial Research', 'Muhammad Iklil Al Milady, S.Stat', 46, 6, 'Surabaya', NULL, NULL, 'Instagram', 'Pelajar dan mahasiswa', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">Membantu memberikan informasi kepada masyarakat tentang hal-hal sosial melalui media yang mudah diakses dengan data yang konkret dan pemahaman yang mudah.</span><br></p>', '2022-09-30', NULL, '2024-09-06 14:24:11', '2024-09-06 14:24:11');
INSERT INTO `tenant` VALUES (4367, 7, NULL, 'Makmur Amanah Sejahtera Sawit', 'Mukhlis Sholehudin', 30, 2, 'Surabaya', NULL, NULL, 'Instagram', 'Pemerintahan, Perumahan, Perusahaan', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">Cangkang sawit adalah limbah perkebunan sawit yang memiliki banyak manfaat, yang salah satunya adalah sebagai pengganti batubara untuk memanaskan boiler</span><br></p>', '2022-09-30', NULL, '2024-09-06 14:31:26', '2024-09-06 14:31:26');
INSERT INTO `tenant` VALUES (4368, 7, NULL, '3D Expert', 'Muhammad Samsuddin', 29, 4, 'Surabaya', NULL, '1.000.000.000,00', 'Instagram, website, brosur, media cetak', 'Perusahaan, Instansi pendidikan dan pemerintah', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">3D Expert adalah startup edutech yang bergerak di bidang training desain teknik 3D</span><br></p>', '2023-02-27', NULL, '2024-09-06 14:34:41', '2024-09-13 15:49:44');
INSERT INTO `tenant` VALUES (4369, 7, 'public/foto_profil_tenant/66dab0fa310c5.png', 'Cavatoz', 'Ardhiana Iffa Farida', 23, 7, 'Solo', NULL, NULL, 'Instagram, website, brosur, media cetak', 'Masyarakat umum', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">Snack keripik getuk singkong dengan berbagai varian rasa yang memiliki keunggulan bebas msg-bebas pengawet- dan bebas pewarna buatan. Keripik getuk merupakan inovasi pengolahan singkong asli (tanpa tambahan gandum) menjadi keripik dengan melalui proses pengolahan : pengukusan dan penggilingan, sehingga menghasilkan tekstur keripik yang lebih renyah dan empuk dibanding keripik singkong pada umumnya.</span><br></p>', '2023-02-27', NULL, '2024-09-06 14:36:26', '2024-09-06 14:36:26');
INSERT INTO `tenant` VALUES (4370, 7, 'public/foto_profil_tenant/66dab17e51e6f.png', 'Materalab', 'Muhammad Lukmanul Hakim', 43, 6, 'Surabaya', NULL, NULL, 'Instagram, website', 'Rumah Sakit, Klinik, Puskesmas', NULL, '<p><span data-sheets-root=\"1\" style=\"font-size: 12pt; font-family: Arial; color: rgb(31, 31, 31);\">Sebuah software ERP yang berfokus pada sistem rekam medis elektronik hingga monitoring dalam rangka meningkatkan efisiensi operasional pada pelayanan kesehatan</span><br></p>', '2023-02-27', NULL, '2024-09-06 14:38:38', '2024-09-06 14:38:38');
