INSERT INTO `tenant` VALUES (4374, 7, 'public/foto_profil_tenant/66e28ffaeb8b2.png', 'Voltech Engineering', 'Ilham Wahyu Eko Prasetyo', 46, 6, 'Surabaya', NULL, '200.000.000,00', 'Instagram, website', 'Pelajar dan mahasiswa', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">ICT &amp; Robotic - Kit Trainer Robotik untuk siswa SMP hingga SMA</span><br></p>', '2023-02-27', NULL, '2024-09-12 13:53:46', '2024-09-12 13:53:46');
INSERT INTO `tenant` VALUES (4375, 7, 'public/foto_profil_tenant/66e290ec6eac6.png', 'Tanam Kota', 'Agung Purwanto', 50, NULL, 'Surabaya', NULL, NULL, 'Instagram', 'Masyarakat, komunitas hidroponik, perusahaan perkebunan dan pertanian', NULL, '<p><span data-sheets-root=\"1\" style=\"font-size: 12pt; font-family: Arial; color: rgb(31, 31, 31);\">Agri-tech Startup yang berfokus pada urban agriculture dengan visi membangun Smart Green City. Produk Tanam Kota merupakan produk Agriculture berbasis IoT (Internet Of Things) dengan metode precision farming dan vertikultur yang ditujukan untuk kegiatan pertanian di wilayah perkotaan.</span><br></p>', '2023-02-27', NULL, '2024-09-12 13:57:48', '2024-09-12 13:57:48');
INSERT INTO `tenant` VALUES (4376, 7, 'public/foto_profil_tenant/66e29190a2eb9.png', 'Aither', 'Farel', 50, 6, 'Surabaya', NULL, '300.000.000,00', 'Instagram, website, brosur, media cetak', 'Pemerintahan, Perumahan, Perusahaan', NULL, '<p><span data-sheets-root=\"1\" style=\"font-size: 12pt; font-family: Arial; color: rgb(31, 31, 31);\">StartUp yang fokus kepada pengurangan emisi karbon di udara dengan menciptkana atau membuat alat air purifier dengan memanfaatkan alga.</span><br></p>', '2023-02-27', NULL, '2024-09-12 14:00:32', '2024-09-12 14:00:32');
INSERT INTO `tenant` VALUES (4377, 7, 'public/foto_profil_tenant/66e29261e10e9.png', 'Etergy', 'Farrel Muh N S K', 30, 5, 'Surabaya', NULL, NULL, 'Instagram', 'Perusahaan Kontruksi', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">“Inovasi Green Booster sebagai peningkat kualitas bahan bakar bagi perusahaan konstruksi”</span><br></p>', '2022-09-30', '2023-02-27', '2024-09-12 14:04:01', '2024-09-12 14:04:01');
INSERT INTO `tenant` VALUES (4378, 7, 'public/foto_profil_tenant/66e2930061bfc.png', 'Makmur Amanah Sejahtera', 'Vicky Firmansyah', 14, 2, 'Surabaya', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Arial;\">adalah salah satu perusahaan yang bergerak di bidang pakan ternak alternatif, kami memanfaatkan limbah pengolahan minyak kelapa sawit berupa bungkil sawit (palm kernell meal). Makmur Amanah Sejahtera juga melakukan diversifikasi produk untuk lebih meningkatkan approach kepada konsumen khususnya peternak lokal, terbagi menjadi tiga produk, yaitu bunggas (bungkil sawit untuk unggas), bungkan (bungkil sawit untuk ikan), dan bungur (bungkil sawit untuk ruminansia).</span><br></p>', '2022-09-30', NULL, '2024-09-12 14:06:40', '2024-09-12 14:06:40');
