INSERT INTO `tenant` VALUES (4436, 7, 'public/foto_profil_tenant/66e3fc5928a77.png', 'PT. Datasoft Solusi Indonesia', 'Setya Budi Utama', 47, 6, 'Surabaya', NULL, NULL, 'Instagram, website', NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">ATM Setoran Susu</span><br></p>', '2019-06-26', '2020-06-26', '2024-09-13 15:48:25', '2024-09-13 15:48:25');
INSERT INTO `tenant` VALUES (4437, 911, 'public/foto_profil_tenant/66e5770626967.jpg', 'Abby Photo', 'YOGA KHIDAYATUDIN,S.Pd.I', 51, 1, 'KP CIGAGAK RT 07 RW 05 DESA BARANANGSIANG\r\n       KEC CIPONGKOR KAB BANDUNG BARAT', NULL, '54.000.000,00', 'Online dan Offline', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">Jasa fotografer adalah pekerjaan profesional yang berfokus dalam dunia seni guna memotret momen dalam bentuk foto menggunakan kamera digital atau analog</span></p><p><span style=\"font-size: 14px;\">kami mengambil foto orang, lokasi, serta objek untuk merekam peristiwa tertentu dan menceritakan kisahnya menggunakan gambar.</span></p>', '2024-09-14', '2026-09-14', '2024-09-14 18:44:06', '2024-09-14 20:02:12');
INSERT INTO `tenant` VALUES (4439, 911, 'public/foto_profil_tenant/66e58a7f0664a.jpg', 'Perikanan NUH', 'ASEP HIDAYAT NURHIKAM', 4, 2, 'Kp.Lampegan RT 05-001 Desa Wargasaluyu Kec.Gununghalu Kab. Bandung Barat', NULL, '150.000.000,00', 'Offline dan Online', 'CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">Usaha perikanan adalah kegiatan yang dilakukan dengan sistem bisnis perikanan, yang&nbsp;</span></p><p><span style=\"font-size: 14px;\">meliputi: Praproduksi, Produksi, Pengolahan, Pascaproduksi, Pemasaran</span></p>', '2024-09-14', '2026-09-14', '2024-09-14 20:07:11', '2024-09-14 20:09:54');
INSERT INTO `tenant` VALUES (4440, 911, 'public/foto_profil_tenant/66e58cbeedadc.jpg', 'Kantin Sekolah', 'Nuraida Kania Haerani', 23, 7, 'KP CIBALOK RT 01.RW 04.DES, CITALEM KEC,CIPONGKOR ,KAB\r\nBANDUNG BARAT', NULL, '15.000.000,00', 'Online dan Offline', 'Untuk semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">Kantin sekolah khusus untuk menyediakan ,atk foto copy, makanan dan minuman kepada</span></p><p><span style=\"font-size: 14px;\">siswa selama jam istirarahat atau waktu makan.biasanya ,kantin terletak diarea yang</span></p><p><span style=\"font-size: 14px;\">mudah diakses oleh semua siswa.</span></p>', '2024-09-14', '2026-09-14', '2024-09-14 20:16:46', '2024-09-14 20:16:46');
INSERT INTO `tenant` VALUES (4441, 911, 'public/foto_profil_tenant/66e58ef137dcf.jpg', 'Peternakan Rifai', 'Ahmad Rifai', 3, 2, 'Rama Gunawan kec.seputih raman kab.lampung tengah', NULL, '50.000.000,00', 'Offline dan Online', 'Lokal dan Daerah, CO, Semua kalangan sesama rekan :sesama provesi :petani :jagal', 'Laporan Pembukuan Tenant', '<div><span style=\"font-size: 14px;\">Usaha peternak dan pembudidayaan sapi adalah usaha yg sistim kerjanya adalah</span></div><div><span style=\"font-size: 14px;\">pengembangan dan penggemukan</span></div><div><span style=\"font-size: 14px;\">Untuk sapi sapi yg sifatnya di bidang penggemukan yg sudah ADG nya sudah target maka</span></div><div><span style=\"font-size: 14px;\">sudah siap untuk di keluarkan atau di jual</span></div><div><span style=\"font-size: 14px;\">Untuk pengembangan sapi \' dari kami fokus ke babonan sapi atau indukan sapi yg mana</span></div><div><span style=\"font-size: 14px;\">dari babon babon tersebut untuk peranakan</span></div><div><span style=\"font-size: 14px;\">Dan untuk pengembangan dari sini dapat memudahkan konsumen agar mudah</span></div><div><span style=\"font-size: 14px;\">mendapatkan bibit bibit sapi yg unggul</span></div>', '2024-09-14', '2026-09-14', '2024-09-14 20:26:09', '2024-09-14 21:48:13');
INSERT INTO `tenant` VALUES (4442, 911, 'public/foto_profil_tenant/66e613c2058b5.jpg', 'Kebun Berkah Tan', 'Wahyu Hidayat', 48, 9, 'Padang Bulan, RT 1, RW 1, Tegalrejo, Tegalsari, Banyuwangi', NULL, '20.000.000,00', 'Online dan Offline', 'a. Petani b. Penghobi Tanaman c. Reseller Bibit Buah d. Instansi dan Komunitas Penyelenggara Program Tanam', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">Kebun Berkah Tani adalah bisnis yang berjalan di bidang pembibitan tanaman, khususnya tanaman alpukat. Mulanya Kebun Berkah Tani bergerak sebagai reseller bibit buah- buahan. Kami menjual segala macam bibit tanaman, seperti jeruk, durian, kelengkeng, jambu</span></p><p><span style=\"font-size: 14px;\">air, jambu biji, manggis, dll. Dari sini kami menyadari bahwa bisnis tanaman sangat</span></p><p><span style=\"font-size: 14px;\">menguntungkan dan seharusnya ada “sesuatu” yang dapat dikembangkan sendiri, yakni</span></p><p><span style=\"font-size: 14px;\">produksi bibit. Kami mulai riset dan menemukan banyak sekali biji alpukat di daerah kami, dan</span></p><p><span style=\"font-size: 14px;\">hal inilah yang mendasari Kebun Berkah Tani untuk memutuskan memproduksi bibit alpukat. Terlebih di Banyuwangi belum ada produsen bibit tanaman. Seluruh lapak yang ada di sini rata</span></p><p><span style=\"font-size: 14px;\">-rata bibit dari produsen luar daerah. Tentu ini merupakan kesempatan, juga peluang. Berkah</span></p><p><span style=\"font-size: 14px;\">Tani ingin menjadi perintis produsen bibit alpukat di Banyuwangi, dan harapan besar kami, suatu saat Berkah Tani bisa melebarkan sayap, memiliki produk turunan lain seperti menjual</span></p><p><span style=\"font-size: 14px;\">buah alpukat, minuman alpukat, dan sejenisnya, agar bisa berdampak bagi sosial-ekonomi</span></p><p><span style=\"font-size: 14px;\">masyarakat sekaligus menjadi lapangan kerja.</span></p>', '2024-09-14', '2026-09-14', '2024-09-15 05:52:50', '2024-09-15 05:52:50');
INSERT INTO `tenant` VALUES (4443, 911, 'public/foto_profil_tenant/66e6728bb9c17.jpg', 'Toko Plastik', 'Dedi Muhlis', 40, 1, 'Kp. Cibalok 01 04 CITALEM CIPONGKOR BANDUNG BARAT JAWA BARAT', NULL, '36.500.000,00', 'Offline dan Online', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Deskripsi Usaha</font></font></span></p><p><span style=\"font-size: 14px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Harga fleksibel, bisa beli ecera, mudah di dapat untuk kebutuhan sehari2</font></font></span></p>', '2024-09-14', '2026-09-14', '2024-09-15 12:37:15', '2024-09-15 12:37:15');
INSERT INTO `tenant` VALUES (4444, 911, 'public/foto_profil_tenant/66e6741e60a07.jpg', 'Warung Sembako', 'SOPIAH NURMAGFIROH', 27, 7, 'Kp. Cibalok 01 04 CITALEM CIPONGKOR BANDUNG BARAT JAWA BARAT', NULL, '10.000.000,00', 'Online dan Offline', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">Warung menyediakan produk lokal dengan harga terjangkau, terletak di lokasi yang</span></p><p><span style=\"font-size: 14px;\">strategis,dan menawarkan pelayanan personal. Warung bisa menjual berbagai barang ,mulai</span></p><p><span style=\"font-size: 14px;\">dari makanan dan minuman hingga kebutuhan sehari-hari</span></p>', '2024-09-14', '2026-09-14', '2024-09-15 12:43:58', '2024-09-15 12:43:58');
INSERT INTO `tenant` VALUES (4445, 911, 'public/foto_profil_tenant/66e6755361947.jpeg', 'Usaha KONPEKSI', 'Nirwan Aripin', 19, 1, 'Jl. Pesantren Cibalok 01 04 CITALEM CIPONGKOR BANDUNG BARAT JAWA BARAT', NULL, '150.000.000,00', 'Offline dan Online', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Bahasa Inggris: KONPEKSI MANDIRI&nbsp;</font></font></p>', '2024-09-14', '2026-09-14', '2024-09-15 12:49:07', '2024-09-15 12:49:07');
INSERT INTO `tenant` VALUES (4446, 911, 'public/foto_profil_tenant/66e68fef58932.jpg', 'Warung Sembako', 'Didah', 40, 7, 'Kp. Cimanila 02 04 Citalem Cipongkor Bandung Barat Jawa Barat', NULL, '10.000.000,00', 'Online dan Offline', 'ANAK 2 dan dewasa\'', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Saya menjual berbagai sembako dari mulai beras lauk pauk sayuran di tambah snack dan jajanan anak juga di tambah berbagai pupuk untuk pertanian dan pestisida</font></font></span></p>', '2024-09-14', '2026-09-14', '2024-09-15 14:42:39', '2024-09-15 14:42:39');
INSERT INTO `tenant` VALUES (4447, 391, 'public/foto_profil_tenant/6729928172eb7.jpeg', 'Sambal Baaba', 'Nurcahayati', 23, 7, 'Desa Panca Tunggal Benawa Kecamatan Teluk Gelam', NULL, '3.000.000,00', 'ig, Facebook', 'Kabupaten Ogan Komering Ilir', NULL, '<p>Sambal baaba merupakan sambal homemade berbhan dasar ikan tongkol yang diasap sehingga memberikan rasa yang menyatu dengan pedasnya cabe pilihan, bawang putih, bawang merah, cabai dan bahan pilihan lainnya berpadu dengan bumbu rahasia Dapur Baaba, membuat Sambal Baaba nikmat gak ada matinya</p>', '2024-06-17', '2024-06-17', '2024-09-17 10:14:44', '2024-11-05 10:35:29');
INSERT INTO `tenant` VALUES (4448, 391, 'public/foto_profil_tenant/67299222250d2.jpeg', 'Kerupuk Kemplang Hj. Nuriah', 'Leni', 23, 7, 'Penginapan Mikial Ismi Jalan. letnan Muchtar Saleh No. 123 Kayuagung', NULL, '10.000.000,00', 'Facebook, WA', 'Kabupaten Ogan Komering Ilir dan Kota Palembang', NULL, '<p>Kerupuk kemplang Hj. Nuriah terbuat dari bahan daging ikan gabus/ikan putak/ikan kecilbsegar dan higenis diolah dengan cara di kukus dan direbus serta di iris serta di jemur hingga kering sehingga di goreng dan di panggang. Hasil nya menjadi gurih dan enak sekali. \"mencoba akan membuat ketagihan untuk meinkmati kerupuk kempangnya\".</p>', '2024-06-17', '2024-06-17', '2024-09-17 10:19:17', '2024-11-05 10:33:54');
