INSERT INTO `tenant` VALUES (4761, 336, NULL, 'Kuliner dapur maisa', 'Putri Hadijah Istiqomah', 40, 7, 'Brebes', NULL, '50.000.000,00', 'Facebook', 'Lokal', 'Belum ada', '<p>Menjual jajanan basah. Sementara ini menerima pesanan rapat dan menjual eceran.</p>', '2024-06-21', '2024-11-21', '2024-10-12 04:06:00', '2024-10-12 04:06:00');
INSERT INTO `tenant` VALUES (4762, 336, NULL, 'Keripik Pisang Rejeh', 'Purniasih', 40, 7, 'Losari, Brebes', NULL, '100.000.000,00', 'Facebook', 'Lokal dan antar kecamatan', 'Sudah ada', '<p>Mengepul pisang dari petani lokal Losari dan mengolahnya menjadi keripik pisang. Psar yang dituju adalah pasar lokal dan kecamatan sekitar Losari Brebes</p>', '2024-06-21', '2024-11-21', '2024-10-12 04:07:58', '2024-10-12 04:07:58');
INSERT INTO `tenant` VALUES (4763, 336, NULL, 'Furniture Mini', 'Joko Sulistyo', 47, 3, 'Banjarharjo, Brebes', NULL, '50.000.000,00', 'Facebook', 'Lokal dan antar kecamatan', 'Sudah ada', '<p>Membuat mini properti berupa perabotan dapur aestetik dan meja kursi kafe&nbsp;</p>', '2024-06-21', '2024-11-21', '2024-10-12 04:10:00', '2024-10-12 04:10:00');
INSERT INTO `tenant` VALUES (4764, 336, NULL, 'Kuliner Sempolan Ayam', 'Miska Fitriana', 40, 7, 'Brebes', NULL, '10.000.000,00', 'Facebook', 'Lokal', 'Belum ada', '<p>Berusaha di bidang kuliner sempolan ayam. Berdagang di alun alun Brebes. Omset masih kecil dan butuh pendampingan</p>', '2024-06-21', '2024-11-21', '2024-10-12 04:12:56', '2024-10-12 04:12:56');
