INSERT INTO `tenant` VALUES (4773, 911, 'public/foto_profil_tenant/670b2b7aa658b.jpg', 'Kantin Sekolah', 'Zidni Ilma', 27, 7, 'Kp. Cibalok 01 04 CITALEM CIPONGKOR BANDUNG BARAT JAWA BARAT', NULL, '15.000.000,00', 'Online dan Offline', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Bahasa Inggris: Kantin Sekolah SMP IT AL-MASHDUQIYAH&nbsp;</font></font></p>', '2024-09-20', '2027-09-20', '2024-10-13 09:07:54', '2024-10-13 09:07:54');
INSERT INTO `tenant` VALUES (4774, 911, 'public/foto_profil_tenant/670b3c978e6ad.jpg', 'BUDIDAYA IKAN NILA', 'Saepul Anwar', 4, 2, 'Kp. Perlas desa Budiharja Kec CILILIN bandung barat', NULL, '50.000.000,00', 'Online dan Offline', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">10.Deskripsi Usaha&nbsp;</span></p><p><span style=\"font-size: 14px;\">Budidaya perikanan adalah salah satu sektor yang mendorong maju nya&nbsp;</span></p><p><span style=\"font-size: 14px;\">tingkat perekonomian di masyarakat.</span></p><p><span style=\"font-size: 14px;\">Tak jarang banyak masyarakat selain bekerja di dunia luar seperti perkantoran&nbsp;</span></p><p><span style=\"font-size: 14px;\">dan di berbagai bidang untuk memilih mendirikan sebuah usaha peternakan&nbsp;</span></p><p><span style=\"font-size: 14px;\">atau perikanan contohnya budidaya ikan nila, lele, patin, dan sebagainya.</span></p><p><span style=\"font-size: 14px;\">Selain mengisi waktu luang, berbudidaya perikanan pun juga memberikan hal&nbsp;</span></p><p><span style=\"font-size: 14px;\">positif bagi kehidupan Sang wirausaha dan masyarakat sekitar tempat&nbsp;</span></p><p><span style=\"font-size: 14px;\">budidaya. Contohnya memberikan kesejahteraan ekonomi secara tidak&nbsp;</span></p><p><span style=\"font-size: 14px;\">langsung, mampu membuka lapangan kerja, menjadi pendorong bagi warga&nbsp;</span></p><p><span style=\"font-size: 14px;\">lain untuk membuka sektor budidaya perikanan.</span></p><p><span style=\"font-size: 14px;\">Tidak hanya warga pesisir saja yang mampu membuka lahan perikanan, warga&nbsp;</span></p><p><span style=\"font-size: 14px;\">yang tinggal di tengah perkampungan, perkotaan pun mampu membuka usaha&nbsp;</span></p><p><span style=\"font-size: 14px;\">serupa. Dengan membuka lahan sebagai waduk, atau kolam sebagai tempat&nbsp;</span></p><p><span style=\"font-size: 14px;\">memulai sebuah budidaya perikanan.</span></p>', '2024-09-20', '2025-09-20', '2024-10-13 10:20:30', '2024-10-13 11:01:16');
INSERT INTO `tenant` VALUES (4775, 911, 'public/foto_profil_tenant/670b3d831cd51.jpg', 'BUDIDAYA Lele', 'M HELMI FAEROZI', 4, 2, 'Kp. Cibalok 01 04 CITALEM CIPONGKOR BANDUNG BARAT JAWA BARAT', NULL, '54.000.000,00', 'Offline dan Online', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">KATA PENGANTAR</span></p><p><span style=\"font-size: 14px;\">Alhamdulillah, segala puji dan syukur bagi Allah SWT atas petunjuk dan hidayah-</span></p><p><span style=\"font-size: 14px;\">Nya, sehingga kami dapat menyusun proposal ini. Shalawat teriring salam semoga&nbsp;</span></p><p><span style=\"font-size: 14px;\">senantiasa dilimpah ruahkan atas Nabi Muhammad SAW berkat perjuangan Beliau kita&nbsp;</span></p><p><span style=\"font-size: 14px;\">senantiasa berada di alam yang penuh berkah dan kasih sayang.</span></p><p><span style=\"font-size: 14px;\">Dengan rendah hati, saya mempersembahkan proposal ini sebagai langkah pertama</span></p><p><span style=\"font-size: 14px;\">dalam mewujudkan visi saya dalam bidang budidaya ikan lele konvensional. Usaha ini&nbsp;</span></p><p><span style=\"font-size: 14px;\">bukan hanya sekadar bisnis bagi saya pribadi, tetapi juga sebuah komitmen pesantren&nbsp;</span></p><p><span style=\"font-size: 14px;\">untuk berkontribusi dalam memenuhi kebutuhan pangan para santri dengan cara yang&nbsp;</span></p><p><span style=\"font-size: 14px;\">berkelanjutan dan bertanggung jawab. Selain itu usaha ini juga sebagai upaya dalam&nbsp;</span></p><p><span style=\"font-size: 14px;\">mewujudkan kemandirian ekonomi pesantren. Sejak tahun 2022, saya telah membangun&nbsp;</span></p><p><span style=\"font-size: 14px;\">pondasi yang kokoh untuk usaha ini, dengan fokus utama pada kualitas, inovasi, dan&nbsp;</span></p><p><span style=\"font-size: 14px;\">efisiensi serta melakukan pengembangan usahayang saling terintegrasi dari hulu hingga&nbsp;</span></p><p><span style=\"font-size: 14px;\">hilir.</span></p><p><span style=\"font-size: 14px;\">Proposal ini secara langsung maupun tidak langsung banyak mendapat dukungan&nbsp;</span></p><p><span style=\"font-size: 14px;\">dari berbagai pihak. Ucapan terimakasih kami sampaikan pada semua pihak yang telah&nbsp;</span></p><p><span style=\"font-size: 14px;\">turut membantu, memberikan inspirasi, dan mendorong kami. Mudah-mudahan&nbsp;</span></p><p><span style=\"font-size: 14px;\">bermanfaat serta mendapat ridlo Allah SWT. Amiin...</span></p>', '2024-09-20', '2025-09-20', '2024-10-13 10:24:51', '2024-10-13 11:00:44');
INSERT INTO `tenant` VALUES (4776, 911, 'public/foto_profil_tenant/670b3e252eed2.jpg', 'Budidaya Puyuh', 'Aripin', 3, 2, 'Kp. Cibalok 01 04 CITALEM CIPONGKOR BANDUNG BARAT JAWA BARAT', NULL, '15.000.000,00', 'Offline dan Online', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Budidaya Puyuh&nbsp;</font></font></p>', '2024-09-20', '2025-09-20', '2024-10-13 10:27:33', '2024-10-13 11:01:36');
