INSERT INTO `tenant` VALUES (4778, 18, NULL, 'Koperasi Shidobiru Sakatani Makmur', 'Koperasi Shidobiru Sakatani Makmur', 2, 1, 'Jl. Raya Wonoboyo, Desa Wonoboyo, Kec. Wonoboyo, Kab. Temanggung, Jawa Tengah', NULL, '1.906.503.315,00', NULL, NULL, NULL, '<p>Koperasi produsen penghasil pewarna alam indigo dari tanaman strobilantes cusia.</p>', '2024-03-12', '2024-09-12', '2024-10-13 12:21:09', '2024-10-13 12:25:13');
INSERT INTO `tenant` VALUES (4779, 18, NULL, 'Koperasi Mitra Mentari Timur', 'Koperasi Mitra Mentari Timur', 40, 2, 'Desa Nglantung RT 03/ RW 01, Kabupaten Semarang, Jawa Tengah', NULL, '1.586.344.000,00', NULL, NULL, NULL, '<p>Koperasi konsumsi yang menyediakan bahan baku anggota berupa gula rafinasi.</p>', '2024-03-12', '2024-09-12', '2024-10-13 12:33:46', '2024-10-13 12:33:46');
INSERT INTO `tenant` VALUES (4780, 18, NULL, 'Koperasi Taras Karya Abadi', 'Koperasi Taras Karya Abadi', 48, 2, 'Jalan Puwareja, Dusun Kalikidang Lor, Kec. Purworeja Klampok, Kabupaten Banjarnegara, Jawa Tengah', NULL, NULL, NULL, NULL, NULL, '<p>Koperasi ini bergerak pada bidang retail saprodi untuk sarana produksi pertanian bagi petani anggota, dan usaha penghimpunan hasil pertanian (padi dan jagung) dari anggota petani kemudian disetorkan kepada perusahaan penggilingan padi.</p>', '2024-03-12', '2024-09-12', '2024-10-13 12:43:09', '2024-10-13 12:43:09');
INSERT INTO `tenant` VALUES (4781, 18, NULL, 'Koperasi Produsen KUD Tani Jaya Banjarejo', 'Koperasi Produsen KUD Tani Jaya Banjarejo', 48, 2, 'Desa Mojowetan, Kec. Banjarejo, Kabupaten Blora, Jawa Tengah', NULL, '1.939.650.122,00', NULL, NULL, NULL, '<p>Koperasi produsen serba usaha dengan jenis usaha pupuk, padi, jagung, wood pallet, peternakan, dan simpan pinjam. Jumlah anggota saat ini lebih dari 500 anggota.</p>', '2024-03-12', '2024-09-12', '2024-10-13 12:48:33', '2024-10-13 12:48:33');
