INSERT INTO `tenant` VALUES (4786, 18, NULL, 'Koperasi Konsumen ART Bersama', 'Koperasi Konsumen ART Bersama', 40, 5, 'Jalan Raya Tegal Pemalang KM 11, Desa Sidaharja RT 02 RW 02, Kecamatan Suradadi, Kabupaten Tegal', NULL, '319.582.500,00', NULL, NULL, NULL, '<p>Koperasi konsumen yang bergerak pada bidang perdagangan besar dan eceran reparasi/perawatan mobil dan sepeda.<br></p>', '2024-03-12', '2024-09-12', '2024-10-13 19:15:14', '2024-10-13 19:15:14');
INSERT INTO `tenant` VALUES (4787, 18, NULL, 'Koperasi Produsen Rempah Vanila Nusantara', 'Koperasi Produsen Rempah Vanila Nusantara', 48, 2, 'Jalan Cendrawasih No. 558, Brogo, Donohudan, Kecamatan Ngemplak, Kabupaten Boyolali, Jawa Tengah', NULL, NULL, 'ig: karavanjawa', NULL, NULL, 'Vanila dari petani diolah koperasi menjadi beams yang disortir dengan berbagai grade. selain vanila, juga memproduksi rempah-rempah yang dibuat cip (kering).', '2024-03-12', '2024-09-12', '2024-10-13 19:22:37', '2024-10-13 19:51:42');
INSERT INTO `tenant` VALUES (4788, 18, NULL, 'Kopontren Mubarokul Ulum', 'Kopontren Mubarokul Ulum', 49, 9, 'Jalan Suka Asih No. 8, Desa Penanggapan, Kabupaten Brebes, Jawa Tengah', NULL, '40.000.000,00', NULL, NULL, NULL, 'Koperasi simpan pinjam yang beranggotakan hanya karyawan pondok pesantren.', '2024-03-12', '2024-09-12', '2024-10-13 19:56:49', '2024-10-13 20:36:11');
INSERT INTO `tenant` VALUES (4789, 911, 'public/foto_profil_tenant/670bc8afd6eca.jpg', 'Ternak Domba', 'Sobirin', 3, 2, 'Jl. Pesantren Cibalok 01 04 Citalem Cipongkor Bandung Barat Jawa Barat', NULL, '150.000.000,00', 'Online dan Offline', 'Lokal dan Daerah, CO, Semua kalangan', 'Laporan Pembukuan Tenant', '<p><span style=\"font-size: 14px;\">A. Deskripsi Usaha</span></p><p><span style=\"font-size: 14px;\">1. KERJASAMA BISNIS</span></p><p><span style=\"font-size: 14px;\">Dalam mengembangkan bisnis peternakan ini, kami telah menjalin kerjasama dengan&nbsp;</span></p><p><span style=\"font-size: 14px;\">beberapa instansi, yaitu:</span></p><p><span style=\"font-size: 14px;\">- Kelompok ternak dan kelompok tani</span></p><p><span style=\"font-size: 14px;\">- Pengusaha Peternakan</span></p><p><span style=\"font-size: 14px;\">- Balai Latihan Kerja (BLK) Lembang</span></p><p><span style=\"font-size: 14px;\">- Koperasi dan Kopontren lain</span></p><p><span style=\"font-size: 14px;\">- Konsultan Keuangan Kita Kaya Financial Jakarta&nbsp;</span></p><p><span style=\"font-size: 14px;\">- Dinatan bandunf barat&nbsp;</span></p><p><span style=\"font-size: 14px;\">- Diskuk Jabar</span></p><p><span style=\"font-size: 14px;\">- Baznas Pusat</span></p><p><span style=\"font-size: 14px;\">- Baznas Bandung Barat</span></p><p><span style=\"font-size: 14px;\">- BAMUIZ BNI&nbsp;</span></p><p><span style=\"font-size: 14px;\">- BPKH RI&nbsp;</span></p><p><span style=\"font-size: 14px;\">2. KEUNGGULAN BISNIS</span></p><p><span style=\"font-size: 14px;\">- Peternakan kami melakukan aktifitas penggemukan dan pembibitan domba yang&nbsp;</span></p><p><span style=\"font-size: 14px;\">berpedoman pada PERMENTAN RI No 102/Permentan/OT.140/7/2014 Tentang&nbsp;</span></p><p><span style=\"font-size: 14px;\">Pedoman Pembibitan Kambing dan Domba yang Baik, yang disesuaikan dengan kondisi</span></p><p><span style=\"font-size: 14px;\">masyarakat</span></p><p><span style=\"font-size: 14px;\">- Kami menerapkan sistem peternakan terpadu (integrated farming) yang mengedepankan&nbsp;</span></p><p><span style=\"font-size: 14px;\">ramah lingkungan serta meminimumkan limbah (zero waste), sehingga hasil ternak lebih&nbsp;</span></p><p><span style=\"font-size: 14px;\">sehat dan lingkungan kandang lebih bersih.</span></p><p><span style=\"font-size: 14px;\">- Kotoran serta urine domba dikoleksi langsung dari kandang dan dibuat pupuk dengan&nbsp;</span></p><p><span style=\"font-size: 14px;\">cara komposting</span></p><p><span style=\"font-size: 14px;\">- Pupuk kita gunakan dalam penanaman rumput</span></p><p><span style=\"font-size: 14px;\">- Rumput dimakan kembali oleh kambing</span></p><p><span style=\"font-size: 14px;\">- Untuk menjaga ketersediaan pakan, terdapat lahan untuk penanaman rumput odot,&nbsp;</span></p><p><span style=\"font-size: 14px;\">indigofera dan rumput gajah</span></p><p><span style=\"font-size: 14px;\">- Proses pemberian pakan rumput, selain pakan hijau segar, juga diawetkan dengan proses&nbsp;</span></p><p><span style=\"font-size: 14px;\">silase dari rumput yang dicacah</span></p><p><span style=\"font-size: 14px;\">- Selain rumput, pupuk kita gunakan juga untuk memenuhi pemupukan pertanian dan&nbsp;</span></p><p><span style=\"font-size: 14px;\">sayuran disekitar pesantren</span></p><p><span style=\"font-size: 14px;\">3. Jenis ternak adalah Domba Priangan dan domba garut</span></p><p><span style=\"font-size: 14px;\">4. Lama usaha Berdiri usaha 2016</span></p><p><span style=\"font-size: 14px;\">5. PEROSES PEMBELIAN BIBIT PENGURUSAN SAMAPI PEMASARAN</span></p><p><span style=\"font-size: 14px;\">Cara ternak domba diawali dengan pemilihan bibit domba yang tepat dan benar. Karena Jika salah</span></p><p><span style=\"font-size: 14px;\">dalam memilih bibit domba, maka pengeluaran akan jauh lebih banyak. Selain itu pertumbuhan&nbsp;</span></p><p><span style=\"font-size: 14px;\">domba akan tidak optimal.</span></p><p><span style=\"font-size: 14px;\">Hal ini dikarenakan pemilihan bibit adalah faktor yang penting dalam menghasilkan domba-domba berkualitas</span></p><p><span style=\"font-size: 14px;\">tinggi. Bibit domba unggul didapat dari indukan yang baik.</span></p>', '2024-09-20', '2025-09-20', '2024-10-13 20:18:39', '2024-10-13 20:18:39');
INSERT INTO `tenant` VALUES (4790, 18, NULL, 'Koperasi Produsen Pertanian Sukma Sejahtera', 'Koperasi Produsen Pertanian Sukma Sejahtera', 48, 2, 'Jalan Tumenggung Mertowijoyo, RT 04 RW 02, Kabupaten Kendal, Jawa Tengah', NULL, '40.538.298,00', 'ig: koptan.sukma.sejahtera', NULL, NULL, '<p>Koperasi pertanian yang mengolah padi sehat dengan menggunakan pupuk alami dan penyediaan jasa-jasa peralatan pertanian.</p>', '2024-03-12', '2024-09-12', '2024-10-13 20:40:37', '2024-10-13 20:40:37');
INSERT INTO `tenant` VALUES (4791, 18, NULL, 'Koperasi Produsen Purworejo Maju Selaras', 'Koperasi Produsen Purworejo Maju Selaras', 48, 2, 'Perumahan KORPRI No. 18 RT 01/ RW 04, Kelurahan Cangkreplor, Kecamatan Purworejo, Kabupaten Purworejo, Jawa Tengah', NULL, '25.000.000,00', NULL, NULL, NULL, '<p>Koperasi produsen yang bergerak pada bidang pertambangan rakyat emas dan perak, industri gula merah dan keturunannya, industri pariwisata alam Gunung Ijo, pertanian dan perkebunan holticultural.</p>', '2024-03-12', '2024-09-12', '2024-10-13 20:47:15', '2024-10-13 20:47:15');
INSERT INTO `tenant` VALUES (4792, 18, NULL, 'BMT Husnul Faizah', 'BMT Husnul Faizah', 49, 9, 'Jalan Hayam Wuruk No. 6, Kabupaten Temanggung, Jawa Tengah', NULL, '1.200.000.000,00', NULL, NULL, NULL, 'Koperasi yang bergerak pada bidang simpan pinjam.', '2024-03-12', '2024-09-12', '2024-10-13 21:22:20', '2024-10-13 21:22:20');
INSERT INTO `tenant` VALUES (4793, 18, NULL, 'Koperasi Unit Desa Makmur', 'Koperasi Unit Desa Makmur', 48, 2, 'Jalan Raya Jumo, Jamusan, Kecamatan Jumo, Kabupaten Temanggung, Jawa Tengah', NULL, '42.959.256.336,00', NULL, NULL, NULL, '<p>Pertanian kopi dijual dalam bentuk biji kopi, dari petani 78.000 dijual koperasi 84.500. Padi dari petani diselep koperasi dijual dalam bentuk beras. Melayani juha PPOB. Kayu dari beberapa supplier dikirim ke pembeli (koperasi sebagai mediator).&nbsp;</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:15:47', '2024-10-13 22:15:47');
INSERT INTO `tenant` VALUES (4794, 18, NULL, 'Koperasi Semi Rahayu Mandiri', 'Koperasi Semi Rahayu Mandiri', 2, 2, 'Dusun Tanjungsari RT 05/ RW 05, Desa Prapagan, Kecamatan Jeruklegi, Kabupaten Cilacap, Jawa Tengah', NULL, '822.659.250,00', NULL, NULL, NULL, '<p>Koperasi produsen yang memproduksi bahan setengah jadi gula semut dengan standarisasi yang sesuai mutu perusahaan dengan skala ekspor. Kegiatan produksi dilakukan oleh anggota dengan menerapkan standarisasi yang sesuai dengan spesifikasi perusahaan.</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:27:02', '2024-10-13 22:27:02');
INSERT INTO `tenant` VALUES (4795, 18, NULL, 'Koperasi Nafi Berkah Jaya', 'Koperasi Nafi Berkah Jaya', 48, 2, 'Penakir, Kabupaten Pemalang, Jawa Tengah', NULL, '450.000.000,00', NULL, NULL, NULL, '<p>Koperasi pertanian tanaman obat atau biofarma rimpang. Koperasi hanya sebagai penyedia hasil tanaman tersebut kepada Pak Yogi (selaku bendahara) yang kemudian diolah atas nama sendiri.</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:40:40', '2024-10-13 22:40:40');
INSERT INTO `tenant` VALUES (4796, 18, NULL, 'Koperasi Produsen Primer Pengelola Sampah Kabupaten Semarang', 'Koperasi Produsen Primer Pengelola Sampah Kabupaten Semarang', 48, 2, 'Jalan Lemahireng Raya, Dusun Krajan RT 05/ RW 03, Desa Randugunting, Kecamatan Bergas, Kabupaten Semarang, Jawa Tengah', NULL, NULL, NULL, NULL, NULL, '<p>Koperasi produsen yang memproduksi pupuk organik sayur, penjualan bahan baku limbah kotoran hewan, penjualan aktivator untuk fermentasi pupuk organik.</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:44:52', '2024-10-13 22:44:52');
INSERT INTO `tenant` VALUES (4797, 18, NULL, 'Koperasi Konsumen Usaha Prima Mandiri', 'Koperasi Konsumen Usaha Prima Mandiri', 40, 9, 'Jalan Pawiyatan Luhur RT 01/ RW 01, Bendan Dhuwur, Kota Semarang, Jawa Tengah', NULL, '44.750.475,00', NULL, NULL, NULL, '<p>Koperasi konsumen dengan jenis usaha pengadaan, pemeliharan, dan simpan pinjam.&nbsp;</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:50:01', '2024-10-13 22:50:01');
INSERT INTO `tenant` VALUES (4798, 18, NULL, 'Koperasi Mitra Kerja Kita', 'Koperasi Mitra Kerja Kita', 48, 2, 'Jalan Wiroto Raya No. 43, Krobokan, Kota Semarang, Jawa Tengah', NULL, '2.198.672.500,00', NULL, NULL, NULL, '<p>Koperasi dengan sektor usaha berupa industri pengolahan perdagangan padi dan palawijo.</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:53:06', '2024-10-13 22:53:06');
INSERT INTO `tenant` VALUES (4799, 18, NULL, 'Koperasi Konsumen Karya Bunda Sejahtera', 'Koperasi Konsumen Karya Bunda Sejahtera', 40, 2, 'Jalan Pusponjolo Tengah III No. 2, Kota Semarang, Jawa Tengah', NULL, '170.000.000,00', 'WA Business', NULL, NULL, '<p>Koperasi konsumen yang bergerak pada bidang perdagangan sembako.</p>', '2024-03-12', '2024-09-12', '2024-10-13 22:56:12', '2024-10-13 22:56:12');
INSERT INTO `tenant` VALUES (4800, 18, NULL, 'Koperasi Produsen Sentra Logam Semarang', 'Koperasi Produsen Sentra Logam Semarang', 11, 3, 'Jalan Raya Semarang-Kendal KM 12, Kantor Gedung Galeri Lantai 1, Karanganyar Tugu, Kota Semarang, Jawa Tengah', NULL, NULL, NULL, NULL, NULL, '<p>Koperasi memproduksi barang-barang yang berbahan dari logam, misalnya meja dan kursi stainless, mesin pencacah, mesin cocopet, mesin smoker, produk-produk souvenir, dll.</p>', '2024-03-12', '2024-09-12', '2024-10-13 23:00:42', '2024-10-13 23:00:42');
INSERT INTO `tenant` VALUES (4801, 18, NULL, 'Koperasi Tani Sari Makmur', 'Koperasi Tani Sari Makmur', 48, 2, 'Jalan Raya Juwono Rembang KM 3 Desa Tambakagung Kec. Kaliori, Kab. Rembang, Jawa Tengah', NULL, '2.000.000.000,00', 'ig: koptan sari makmur', NULL, NULL, '<p>Pengolahan garam.</p>', '2024-03-12', '2024-09-12', '2024-10-13 23:03:28', '2024-10-13 23:03:28');
