INSERT INTO `tenant` VALUES (4867, 182, NULL, 'Bolia', 'Bowo', 23, 7, 'Tanjung Barat', NULL, NULL, NULL, NULL, NULL, NULL, '2024-07-22', '2024-10-15', '2024-10-16 17:51:33', '2024-10-16 17:51:33');
INSERT INTO `tenant` VALUES (4868, 918, 'public/foto_profil_tenant/674bd643eb93d.png', 'UD. PUTRA MANDIRI Jayalaksana', 'AANG YUDIMAN', 48, 2, 'KP. CISEUPAN RT. 003 RW. 006 DESA HEGARMANAH KECAMATAN BAYONGBONG KABUPATEN GARUT PROVINSI JAWA BARAT', NULL, '45.000.000,00', 'Spanduk, facebook, Instagram', 'Pasar Lokal dan Pasar Regional', NULL, '<p><strong>1. Bawang Merah</strong><br>Bawang merah adalah jenis tanaman umbi-umbian yang banyak digunakan sebagai bahan dasar dalam masakan berbagai budaya. Berikut adalah deskripsi rinci:</p><ul><li><strong>Nama Ilmiah</strong>: <em>Allium cepa</em> var. <em>aggregatum</em></li><li><strong>Karakteristik</strong>: Bawang merah berbentuk bulat dengan kulit tipis berwarna merah keunguan. Daging umbinya berlapis dan berwarna putih hingga merah muda.</li><li><strong>Manfaat</strong>:<ul><li><strong>Fungsional</strong>: Sebagai bahan penyedap rasa alami dalam masakan.</li><li><strong>Kesehatan</strong>: Mengandung antioksidan, vitamin C, dan senyawa belerang yang dapat meningkatkan imunitas dan mencegah penyakit kardiovaskular.</li></ul></li><li><strong>Kegunaan Utama</strong>: Dapat digunakan segar, digoreng, atau dijadikan acar.</li><li><strong>Produksi Utama di Indonesia</strong>: Brebes, Nganjuk, dan daerah lain di Jawa Tengah dan Jawa Timur.</li></ul><p><strong>2. Bawang Goreng</strong><br>Bawang goreng adalah hasil olahan dari bawang merah yang diiris tipis dan digoreng hingga renyah. Berikut deskripsinya:</p><ul><li><strong>Bahan Dasar</strong>: Bawang merah segar yang telah diiris tipis.</li><li><strong>Proses Pembuatan</strong>: Melibatkan penggorengan dalam minyak hingga berwarna cokelat keemasan dengan tekstur renyah.</li><li><strong>Karakteristik</strong>: Memiliki rasa gurih dengan aroma khas bawang yang tajam. Biasanya digunakan sebagai taburan makanan.</li><li><strong>Manfaat</strong>:<ul><li><strong>Kuliner</strong>: Menambah tekstur dan rasa pada makanan seperti sup, nasi goreng, dan masakan tradisional Indonesia lainnya.</li><li><strong>Komersial</strong>: Banyak diproduksi skala industri sebagai produk UMKM.</li></ul></li><li><strong>Penyimpanan</strong>: Perlu disimpan dalam wadah kedap udara untuk menjaga kerenyahan.</li></ul>', '2024-02-02', '2024-02-02', '2024-10-17 08:41:19', '2024-12-01 10:21:39');
