INSERT INTO `tenant` VALUES (4963, 18, NULL, 'Koperasi Konsumen Amanah Mulia Bersama', 'Koperasi Konsumen Amanah Mulai Bersama', 39, 7, 'Jalan Dinar Mas J2 No. 06 Kelurahan Meteseh, Kecamatan Tembalang, Kota Semarang', NULL, '34.838.543,00', NULL, 'Sekolah, Toko Kue, LAZ, Kopmen, Biro Umroh, Lembaga Training, LKMS, Rumah Makan', NULL, '<p style=\"margin-top: 0pt; margin-bottom: 0pt; margin-left: 0in; direction: ltr; unicode-bidi: embed; word-break: normal;\">Koperasi Amanah Mulia Bersama sudah Memiliki Badan hukum Pemerintah kota semarang, Dinas perindustrian koperasi UMKM\r\nkeputusan menteri urusan koperasi dan usaha kecil dan menengah Republik\r\nIndonesia AHU-0006703.AH.01.29 Tahun 2022 Pada tanggal pendirian 17 desember&nbsp;\r\n2022. Koperasi mengalangkan usaha untuk anggota dan masyarakat dengan wadah usaha yaitu Rumah Bisnis. Koperasi sebagai Rumah Bisnis merupakan sebuah wadah kegiatan ekonomi dan bisnis bagi anggota, baik yang belum/tidak mempunyai usaha/bisnis&nbsp; maupun sudah mempunyai bisnis sebagai kolaborasi yang\r\nberbasis\r\nsymbiosis mutualisme bagi hasil bagi pelaku usaha yang\r\nberkerjasama dengan usaha Koperasi Amanah Mulia\r\nBersama (AMB).&nbsp;</p>', '2024-03-12', '2024-09-12', '2024-10-25 20:37:50', '2024-10-25 20:38:59');
INSERT INTO `tenant` VALUES (4964, 18, NULL, 'Koperasi Bina Raharja Sejahtera', 'Koperasi Bina Raharja Sejahtera', 49, 6, 'Jalan Pemuda No. 175, Kelurahan Sekayu, Kecamatan Semarang Tengah, Kota Semarang', NULL, NULL, NULL, NULL, NULL, '<p>Koperasi konsumen yang menyediakan pelayanan kredit barang, pelayanan pemenuhan sembako bulanan anggota dan penjualan produk harian.</p>', '2024-03-12', '2024-09-12', '2024-10-25 20:46:56', '2024-10-25 20:46:56');
INSERT INTO `tenant` VALUES (4965, 18, NULL, 'Koperasi Duta Masyarakat Semarang', 'Koperasi Duta Masyarakat Semarang', 39, 1, 'Jalan Potrosari II (Pasar Srondol) Kelurahan Srondol KulonKecamatan Banyumanik, Kota Semarang', NULL, NULL, 'website', NULL, NULL, '<p>Koperasi Duta Masyarakat (Dumas) Semarang merupakan sebuah koperasi yang bergerak di bidang pemberdayaan ekonomii perempuan melalui penjualan dan distribusi produk-produk UKM yang mayoritas produknya berupa kerajinan batik serta penyediaan jasa simpan-pinjam.</p>', '2024-03-12', '2024-09-12', '2024-10-25 21:14:58', '2024-10-25 21:14:58');
