INSERT INTO `tenant` VALUES (4973, 18, NULL, 'Koperasi Koppas Mekarsari', 'Koperasi Koppas Mekarsari', 49, NULL, 'Jalan Menoreh Utara XII, Kelurahan Sampangan, Kota Semarang', NULL, NULL, NULL, NULL, NULL, '<p>Koppas Mekarsari semula didirikan atas dasar para pedagang pasar yang membutuhkan modal usaha. Bentuk dan jenis usaha berupa simpan pinjam.</p>', '2024-03-12', '2024-09-12', '2024-10-26 00:57:16', '2024-10-26 00:57:43');
INSERT INTO `tenant` VALUES (4974, 18, NULL, 'Koperasi Pemasaran Pertaharjo Energi Sejahtera', 'Koperasi Pemasaran Pertaharjo Energi Sejahtera', 23, 7, 'Jalan Tambakharjo Desa Tambakharjo, Kecamatan Semarang Barat, Kota Semarang, 50149', NULL, NULL, NULL, NULL, NULL, '<p style=\"line-height: 107%; margin-top: 0pt; margin-bottom: 8pt; margin-left: 0in; direction: ltr; unicode-bidi: embed; word-break: normal;\">Koperasi Pemasaran Pertaharjo Energi Sejahtera merupakan koperasi penyedia berbagai macam olahan makanan yang siap\r\nsaji\r\nmaupun pemesanan yang beranggotakan warga Kelurahan Tambakharjo Kota Semarang. Untuk meningkatkan pelayanan dan\r\ntarget sasaran pendapatan maka Pengurus&nbsp;Koperasi Pemasaran Pertaharjo Energi Sejahtera berusaha membuat\r\nbeberapa kebijakan\r\nyang mengarah pada rencana program kerja sebagai dasar\r\npijakan dalam\r\nmenjalankan roda\r\nperekonomian koperasi.</p>', '2024-03-12', '2024-09-12', '2024-10-26 01:01:47', '2024-10-26 01:01:47');
INSERT INTO `tenant` VALUES (4975, 18, NULL, 'Koperasi Konsumen Prima Indo Sutera', 'Koperasi Konsumen Prima Indo Sutera', 23, 7, 'Jalan Tawangsari Utara No. 70, RT 09/ RW 01, Kelurahan Tanjung Mas, Kecamatan Semarang Utara, Kota Semarang', NULL, NULL, NULL, 'Oleh Oleh di kelas Menengah , Goody Bag, Kerjasama dengan BUMN ,Pameran Lokal dan Nasionl.', NULL, '<p>Koperasi\r\nRiil yang terdiri dari para UMKM Pengolah Pangan Potensi Lokal Daerah dan\r\nbertekad menjadi Produk Oleh Oleh Unggulan Daerah yang dapat meraih Pasar Lokal\r\n, Nasional dan Global.</p>', '2024-03-12', '2024-09-12', '2024-10-26 01:06:33', '2024-10-26 01:06:33');
INSERT INTO `tenant` VALUES (4976, 18, 'public/foto_profil_tenant/671be21638f97.png', 'Koperasi Semarang Rajut Mandiri Sukses', 'Koperasi Semarang Rajut Mandiri Sukses', 47, 1, 'Jalan Potrosari II, Srondol Kulon, Kecamatan Banyumanik, Kota Semarang, Jawa Tengah, 50263', NULL, NULL, NULL, NULL, NULL, '<p style=\"line-height: 27pt; margin-top: 0pt; margin-bottom: 0pt; margin-left: 0in; direction: ltr; unicode-bidi: embed; word-break: normal;\">Koperasi Semarang Rajut Mandiri Sukses\r\natau yang biasa di singkat Koperasi Semut Mas berdiri tanggal 17 Maret 2017.&nbsp;Beranggotakan para UKM Rajut di Kota\r\nSemarang.&nbsp;Koperasi\r\nSemut Mas memiliki toko serta galeri yg menyediakan bahan baku rajut serta\r\nmembantu memasarkan produk anggotanya.Untuk\r\npemasaran produk-produk anggota, Semut Mas bekerja sama dengan instansi\r\npemerintah atau swasta yaitu dengan mengikuti pameran di berbagai kegiatan</p><p style=\"line-height: 29.7pt; margin-top: 0pt; margin-bottom: 0pt; margin-left: 0in; direction: ltr; unicode-bidi: embed; word-break: normal;\"></p>\r\n\r\n<p style=\"line-height: 29.7pt; margin-top: 0pt; margin-bottom: 0pt; margin-left: 0in; direction: ltr; unicode-bidi: embed; word-break: normal;\"></p>', '2024-03-12', '2024-09-12', '2024-10-26 01:17:24', '2024-10-26 01:23:18');
