INSERT INTO `tenant` VALUES (5050, 554, 'public/foto_profil_tenant/671cb8d018675.jpg', 'PT KEKE KARYA INDO', 'Juju', 47, 1, 'Tangerang', NULL, NULL, 'Instagram', NULL, NULL, '<ul><li style=\"margin: 6.15pt 0cm 0.0001pt 79.3pt;\"><span style=\"color: rgb(35, 31, 31);\">Produk</span><span style=\"color: rgb(35, 31, 31); letter-spacing: 0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">kerajinan</span><span style=\"color: rgb(35, 31, 31); letter-spacing: 0.2pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">anyaman</span><span style=\"color: rgb(35, 31, 31); letter-spacing: 0.2pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">rumput</span><span style=\"color: rgb(35, 31, 31); letter-spacing: 0.2pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">pandan</span></li><li style=\"margin: 6.15pt 0cm 0.0001pt 79.3pt;\">Produk<span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">terbuat</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">dari</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">bahan</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">dasar</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\">\r\n</span><span style=\"color: rgb(35, 31, 31);\">yang</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">ramah</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.15pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">lingkungan,</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -3.75pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">seperti Tas anyaman dari rumput pandan. Dengan</span><span style=\"color: rgb(35, 31, 31); letter-spacing: 0.05pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">menggunakannya bukan hanya tampil modis,\r\ntapi anda</span><span style=\"color: rgb(35, 31, 31); letter-spacing: 0.05pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">juga</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -1pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">turut</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -1pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">menjaga</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -0.95pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">kelestarian</span><span style=\"color: rgb(35, 31, 31); letter-spacing: -1pt;\"> </span><span style=\"color: rgb(35, 31, 31);\">alam.</span></li></ul>', '2024-06-25', '2024-06-25', '2024-10-26 16:39:28', '2024-10-26 16:39:28');
INSERT INTO `tenant` VALUES (5051, 554, 'public/foto_profil_tenant/671cb95f3c11f.jpg', 'Saung Bakul', 'Murdani', 47, 1, 'Tangerang', NULL, NULL, 'Instagram', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-top:4.55pt;margin-right:0cm;margin-bottom:\r\n0cm;margin-left:14.9pt;margin-bottom:.0001pt\"><span lang=\"id\" style=\"color:#231F1F\">Kreasi<span style=\"letter-spacing:-.3pt\"> </span>anyaman<span style=\"letter-spacing:-.25pt\">\r\n</span>dan<span style=\"letter-spacing:-.3pt\"> </span>bambu</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:6.1pt;margin-right:24.35pt;margin-bottom:\r\n0cm;margin-left:14.9pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">Bambu<span style=\"letter-spacing:.5pt\"> </span>merupakan<span style=\"letter-spacing:.5pt\"> </span>bahan<span style=\"letter-spacing:.5pt\"> </span>utama<span style=\"letter-spacing:.5pt\"> </span>yang<span style=\"letter-spacing:.5pt\"> </span>kami<span style=\"letter-spacing:.5pt\"> </span>gunakan<span style=\"letter-spacing:-3.7pt\">\r\n</span>dalam<span style=\"letter-spacing:.4pt\"> </span>membuat<span style=\"letter-spacing:.4pt\"> </span>produk.<span style=\"letter-spacing:.45pt\"> </span>Disamping<span style=\"letter-spacing:.4pt\"> </span>mudah<span style=\"letter-spacing:.45pt\"> </span>didapat,<span style=\"letter-spacing:.05pt\"> </span>bambu<span style=\"letter-spacing:-.7pt\"> </span>juga<span style=\"letter-spacing:-.7pt\"> </span>memilik<span style=\"letter-spacing:-.65pt\">\r\n</span>harga<span style=\"letter-spacing:-.7pt\"> </span>yang<span style=\"letter-spacing:-.65pt\"> </span>relatif<span style=\"letter-spacing:-.7pt\">\r\n</span>ekonomis.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 16:41:51', '2024-10-26 16:41:51');
INSERT INTO `tenant` VALUES (5052, 554, 'public/foto_profil_tenant/671cbaf99c19a.jpg', 'CRYSANT NINE', 'Enti Roswati', 47, 1, 'Tangerang', NULL, NULL, 'Instagram', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-top:6.15pt;margin-right:35.5pt;margin-bottom:\r\n0cm;margin-left:17.0pt;margin-bottom:.0001pt;line-height:145%\"><span lang=\"id\" style=\"color:#231F1F\">Kerajinan<span style=\"letter-spacing:-1.0pt\"> </span>dari<span style=\"letter-spacing:-1.0pt\"> </span>bahan<span style=\"letter-spacing:-.95pt\">\r\n</span>daur<span style=\"letter-spacing:-1.0pt\"> </span>ulang<span style=\"letter-spacing:-.95pt\"> </span>kertas.</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:0cm;margin-right:18.65pt;margin-bottom:\r\n0cm;margin-left:17.0pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">Aneka<span style=\"letter-spacing:-.65pt\"> </span>kerajinan<span style=\"letter-spacing:-.65pt\"> </span>daur<span style=\"letter-spacing:-.65pt\"> </span>ulang<span style=\"letter-spacing:-.65pt\"> </span>kertas,<span style=\"letter-spacing:-.65pt\">\r\n</span>pemanfaatan<span style=\"letter-spacing:-.65pt\"> </span>daur<span style=\"letter-spacing:-3.75pt\"> </span>ulang<span style=\"letter-spacing:-.95pt\">\r\n</span>kertas<span style=\"letter-spacing:-.9pt\"> </span>dengan<span style=\"letter-spacing:-.95pt\"> </span>kreativitas<span style=\"letter-spacing:\r\n-.9pt\"> </span>seni<span style=\"letter-spacing:-.95pt\"> </span>tinggi.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 16:48:41', '2024-10-26 16:48:41');
INSERT INTO `tenant` VALUES (5053, 554, 'public/foto_profil_tenant/671cbb92144ca.jpg', 'PRODUSEN BINGKAI FOTO & KALIGRAFI', 'Cecep Saefullah', 47, 1, 'Tangerang', NULL, NULL, 'Facebook', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-top:6.15pt;margin-right:90.4pt;margin-bottom:\r\n0cm;margin-left:14.9pt;margin-bottom:.0001pt;line-height:145%\"><span lang=\"id\" style=\"color:#231F1F\">Kaligrafi<span style=\"letter-spacing:-.9pt\"> </span>dan<span style=\"letter-spacing:-.9pt\"> </span>bingkai<span style=\"letter-spacing:-.9pt\">\r\n</span>foto</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:0cm;margin-right:18.65pt;margin-bottom:\r\n0cm;margin-left:14.9pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">Keunikan<span style=\"letter-spacing:-.45pt\"> </span>produk<span style=\"letter-spacing:-.4pt\"> </span>yang<span style=\"letter-spacing:-.4pt\"> </span>buat<span style=\"letter-spacing:-.45pt\"> </span>adalah<span style=\"letter-spacing:-.4pt\">\r\n</span>Kaligrafi<span style=\"letter-spacing:-.4pt\"> </span>Islami<span style=\"letter-spacing:-.45pt\"> </span>yang<span style=\"letter-spacing:-3.7pt\"> </span>indah\r\ndisertai Jam, terbuat dari bahan fiber berkualitas<span style=\"letter-spacing:\r\n-3.75pt\"> </span>dan<span style=\"letter-spacing:-.65pt\"> </span>anti<span style=\"letter-spacing:-.65pt\"> </span>rayap,<span style=\"letter-spacing:-.65pt\">\r\n</span>awet<span style=\"letter-spacing:-.65pt\"> </span>dan<span style=\"letter-spacing:-.65pt\"> </span>kuat<span style=\"letter-spacing:-.65pt\"> </span>hingga<span style=\"letter-spacing:-.65pt\"> </span>bertahun-tahun.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 16:51:14', '2024-10-26 16:51:14');
INSERT INTO `tenant` VALUES (5054, 554, 'public/foto_profil_tenant/671cbcba4e7a1.jpg', 'Zafarut', 'Rohaya', 43, 2, 'Tangerang', NULL, NULL, 'Facebook', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-left:16.6pt;line-height:13.35pt;mso-line-height-rule:\r\nexactly\"><span lang=\"id\" style=\"color:#231F1F\">Minyak<span style=\"letter-spacing:\r\n-.6pt\"> </span>Omega<span style=\"letter-spacing:-.6pt\"> </span>dari<span style=\"letter-spacing:-.6pt\"> </span>biji<span style=\"letter-spacing:-.6pt\"> </span>Sacha<span style=\"letter-spacing:-.6pt\"> </span>Inchi</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:6.1pt;margin-right:23.35pt;margin-bottom:\r\n0cm;margin-left:16.6pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F;mso-font-width:95%\">Minyak Omega 3, 6, 9, dari biji sacha\r\ninchi yang berasal<span style=\"letter-spacing:.05pt\"> </span></span><span lang=\"id\" style=\"color:#231F1F\">dari Hutan Amazon sudah dikembangkan di\r\nIndonesia.<span style=\"letter-spacing:.05pt\"> </span>Kandungan Omega 3-nya 43%\r\nlebih tinggi dari ikan<span style=\"letter-spacing:.05pt\"> </span>Salmon. Karena\r\nberbahan nabati maka bisa digunakan<span style=\"letter-spacing:.05pt\"> </span>untuk\r\nmereka yang alergi makanan laut dan cocok bagi<span style=\"letter-spacing:.05pt\">\r\n</span>para vegetarian. Kandungan Omega 3, 6 dan 9 sangat<span style=\"letter-spacing:.05pt\"> </span>baik untuk kesehatan dan tumbuh kembang\r\notak anak,<span style=\"letter-spacing:.05pt\"> </span>juga<span style=\"letter-spacing:.05pt\"> </span>untuk<span style=\"letter-spacing:.05pt\"> </span>pencegahan<span style=\"letter-spacing:3.85pt\"> </span>stunting,<span style=\"letter-spacing:\r\n3.85pt\"> </span>potensi<span style=\"letter-spacing:.05pt\"> </span>pengembangan<span style=\"letter-spacing:-.3pt\"> </span>pasar<span style=\"letter-spacing:-.25pt\"> </span>sangat<span style=\"letter-spacing:-.25pt\"> </span>luas,<span style=\"letter-spacing:-.3pt\"> </span>baik<span style=\"letter-spacing:-.25pt\"> </span>di<span style=\"letter-spacing:-.25pt\"> </span>dalam<span style=\"letter-spacing:-.3pt\"> </span>dan<span style=\"letter-spacing:-.25pt\"> </span>luar<span style=\"letter-spacing:-3.7pt\"> </span>negeri.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 16:56:10', '2024-10-26 16:56:10');
INSERT INTO `tenant` VALUES (5055, 554, 'public/foto_profil_tenant/671cbd5fc4f79.jpg', 'Arbora Inc', 'Shindy Triandini Putri', 26, 1, 'Tangerang', NULL, NULL, 'Instagram', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-left:14.45pt;line-height:13.35pt;mso-line-height-rule:\r\nexactly\"><span lang=\"id\" style=\"color:#231F1F\">Natural<span style=\"letter-spacing:\r\n-.8pt\"> </span>skin<span style=\"letter-spacing:-.8pt\"> </span>care</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:6.1pt;margin-right:24.45pt;margin-bottom:\r\n0cm;margin-left:14.45pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">Produk perawatan kulit alami dengan bahan dari alam<span style=\"letter-spacing:.05pt\"> </span>dan<span style=\"letter-spacing:-.55pt\"> </span>antioksidan.<span style=\"letter-spacing:-.55pt\"> </span>Kulit<span style=\"letter-spacing:-.5pt\"> </span>adalah<span style=\"letter-spacing:-.55pt\"> </span>organ<span style=\"letter-spacing:-.5pt\"> </span>terbesar<span style=\"letter-spacing:-.55pt\"> </span>di<span style=\"letter-spacing:-.55pt\"> </span>tubuh<span style=\"letter-spacing:-.5pt\"> </span>kita<span style=\"letter-spacing:-3.75pt\"> </span>dan\r\nmenyerap apa pun yang Anda pakai. Penting untuk<span style=\"letter-spacing:\r\n.05pt\"> </span>memastikan produk perawatan kulit Anda tidak<span style=\"letter-spacing:.05pt\"> </span>mengandung bahan kimia berbahaya. Arbora\r\nInc.<span style=\"letter-spacing:.05pt\"> </span>mendukung<span style=\"letter-spacing:\r\n-.8pt\"> </span>hidup<span style=\"letter-spacing:-.75pt\"> </span>sehat<span style=\"letter-spacing:-.75pt\"> </span>dari<span style=\"letter-spacing:-.75pt\"> </span>dalam<span style=\"letter-spacing:-.8pt\"> </span>dan<span style=\"letter-spacing:-.75pt\"> </span>luar.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 16:58:55', '2024-10-26 16:58:55');
INSERT INTO `tenant` VALUES (5056, 554, 'public/foto_profil_tenant/671cbded1f18f.jpg', 'CV TRIGUNA MITRA ABADI', 'Arfan Najirun', 20, 1, 'Tangerang', NULL, NULL, 'Instagram', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-left:16.7pt;line-height:13.35pt;mso-line-height-rule:\r\nexactly\"><span lang=\"id\" style=\"color:#231F1F\">Sepatu<span style=\"letter-spacing:\r\n-.6pt\"> </span>dan<span style=\"letter-spacing:-.6pt\"> </span>Sandal</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:6.1pt;margin-right:18.65pt;margin-bottom:\r\n0cm;margin-left:16.7pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">Tantangan kami sebagai UMKM yang pertama adalah<span style=\"letter-spacing:.05pt\"> </span>bagaimana menghadirkan produk sepatu dan\r\nsandal<span style=\"letter-spacing:.05pt\"> </span>dengan<span style=\"letter-spacing:\r\n-.55pt\"> </span>design<span style=\"letter-spacing:-.55pt\"> </span>dan<span style=\"letter-spacing:-.55pt\"> </span>kualitas<span style=\"letter-spacing:-.55pt\">\r\n</span>yang<span style=\"letter-spacing:-.55pt\"> </span>terbaik,<span style=\"letter-spacing:-.55pt\"> </span>serta<span style=\"letter-spacing:-.55pt\">\r\n</span>dikenal<span style=\"letter-spacing:-.55pt\"> </span>di<span style=\"letter-spacing:-3.7pt\"> </span>dalam<span style=\"letter-spacing:-1.0pt\">\r\n</span>dan<span style=\"letter-spacing:-1.0pt\"> </span>luar<span style=\"letter-spacing:-.95pt\"> </span>negeri.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 17:01:17', '2024-10-26 17:01:17');
