INSERT INTO `tenant` VALUES (5058, 554, 'public/foto_profil_tenant/671cbf29cc163.jpg', 'AANG MAGGOT', 'Aang Amarin', 14, 2, 'Tangerang', NULL, NULL, 'Facebook', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-left:27.25pt;line-height:13.35pt;mso-line-height-rule:\r\nexactly\"><span lang=\"id\" style=\"color:#231F1F;mso-font-width:105%\">Maggot</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:6.1pt;margin-right:18.65pt;margin-bottom:\r\n0cm;margin-left:27.25pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">Tepung<span style=\"letter-spacing:.05pt\"> </span>maggot<span style=\"letter-spacing:.05pt\"> </span>adalah<span style=\"letter-spacing:.1pt\"> </span>bahan<span style=\"letter-spacing:.05pt\"> </span>baku<span style=\"letter-spacing:.1pt\"> </span>untuk<span style=\"letter-spacing:.05pt\"> </span>campuran<span style=\"letter-spacing:.05pt\">\r\n</span>pakan ikan dan unggas dengan protein yang cukup<span style=\"letter-spacing:\r\n.05pt\"> </span>tinggi,<span style=\"letter-spacing:.25pt\"> </span>maggot<span style=\"letter-spacing:.25pt\"> </span>adalah<span style=\"letter-spacing:.3pt\"> </span>mesin<span style=\"letter-spacing:.25pt\"> </span>pengurai<span style=\"letter-spacing:.3pt\">\r\n</span>sampah<span style=\"letter-spacing:.25pt\"> </span>organik</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 17:06:33', '2024-10-26 17:06:33');
INSERT INTO `tenant` VALUES (5059, 554, NULL, 'MAGG ONE', 'Nurjaya', 14, 2, 'Tangerang', NULL, NULL, 'Instagram', NULL, NULL, '<p class=\"MsoBodyText\" style=\"margin-left:17.65pt;line-height:13.35pt;mso-line-height-rule:\r\nexactly\"><span lang=\"id\" style=\"color:#231F1F\">Pakan<span style=\"letter-spacing:\r\n.2pt\"> </span>ternak<span style=\"letter-spacing:.2pt\"> </span>bahan<span style=\"letter-spacing:.25pt\"> </span>maggot</span><span lang=\"id\"><o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoBodyText\" style=\"margin-top:6.1pt;margin-right:24.35pt;margin-bottom:\r\n0cm;margin-left:17.65pt;margin-bottom:.0001pt;line-height:111%\"><span lang=\"id\" style=\"color:#231F1F\">MaggOne : larva\r\nkering dari maggot BSF yang memiliki<span style=\"letter-spacing:.05pt\"> </span>kandungan\r\nprotein tinggi, sangat baik untuk<span style=\"letter-spacing:.05pt\"> </span>pertumbuhan\r\ndan perkembangan ternak. Potensi :<span style=\"letter-spacing:.05pt\"> </span>Produksi yang sangat sustainable,\r\nmudah diciptakan,<span style=\"letter-spacing:.05pt\"> </span>sumber dari sampah\r\nyang dihasilkan oleh masyarakat.<span style=\"letter-spacing:.05pt\"> </span>Keunggulan<span style=\"letter-spacing:-.2pt\"> </span>:<span style=\"letter-spacing:.4pt\"> </span>Maggot<span style=\"letter-spacing:\r\n-.15pt\"> </span>sebagai<span style=\"letter-spacing:-.2pt\"> </span>pakan<span style=\"letter-spacing:-.15pt\"> </span>ternak<span style=\"letter-spacing:-.15pt\">\r\n</span>ikan,<span style=\"letter-spacing:-.2pt\"> </span>unggas<span style=\"letter-spacing:-3.7pt\"> </span>yang dibutuhkan oleh ternak dan dapat membantu<span style=\"letter-spacing:.05pt\"> </span>mengurangi<span style=\"letter-spacing:\r\n-1.0pt\"> </span>sampah.</span><span lang=\"id\"><o:p></o:p></span></p>', '2024-06-25', '2024-06-25', '2024-10-26 17:09:39', '2024-10-26 17:09:39');
