INSERT INTO `tenant` VALUES (5255, 85, NULL, 'Koperasi Tri Sukses Makmur', 'Anggota Koperasi', NULL, NULL, 'Ruko Alicante Blok A No.59 Kel.Medang, Kec.Pagedangan, Kab Tangerang, Banten', NULL, NULL, NULL, NULL, NULL, NULL, '2024-07-01', '2024-09-12', '2024-12-19 10:54:41', '2024-12-19 10:54:41');
INSERT INTO `tenant` VALUES (5256, 435, 'public/foto_profil_tenant/6763cddf74ca8.PNG', 'Pondok Uma Udeng Bali', 'I Kadek Sumawan', 47, 1, 'Jln Kusanegara Kusamba Klungkung', NULL, '70.000.000,00', 'Facebook, Instagram, Tiktok, Shopee', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten, Lokal Lintas Provinsi', 'Ada', '<p><br></p><p><br></p><p>Pondok Uma Udeng Bali mulai dirintis dan berdiri mulai tanggal 21 Maret 2021 yang mana tepat pada saat itu kita semua mengalami dampak pandemi covid 19. Usaha ini bergerak dibidang Busana Adat Bali khususnya busana para pria. Dalam memulai usaha ini, tentu yang menjadi latar belakang yaitu faktor keterbatasan ekonomi.&nbsp;</p><p><br></p><p>Pada saat pandemi, hampir semua kegiatan dialihkan ke sistem online. Dari sana kami berpikir untuk mencoba untuk berjualan online yang mana berjualan online tidak membutuhkan modal yang terlalu banyak.&nbsp;&nbsp;</p><p><br></p><p>Kami menekuni usaha ini karena di era tersebut sedang tren nya busana adat bali khususnya dalam tren-tren udeng anak remaja. Pada saat pertama kali, aplikasi berjualan yang kami gunakan yaitu Facebook Marketplace. Dari pengalaman berjualan di sana serta berinovasi dalam membuka toko online di berbagai aplikasi berjualan lainnya, kami memutuskan untuk membuka toko offline pada akhir tahun 2021 hingga sekarang.</p><p><br></p><p>Keunggulan produk kami yaitu selalu update terhadap tren atau style busana adat bali dan tentunya kami menggunakan kualitas kain yang terbaik dalam membuat suatu produk busana bali.</p>', '2024-03-26', '2024-11-03', '2024-12-19 14:40:15', '2024-12-19 14:40:15');
INSERT INTO `tenant` VALUES (5257, 435, 'public/foto_profil_tenant/6763cf39adf77.png', 'Alaya', 'I Wayan Antara Putra', 23, 7, 'Jl raya timuhun .banjarangkan.klungkung', NULL, '12.000.000,00', 'Facebook, Instagram', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten', 'Ada', '<p>Dari ingin menciptakan lapangan kerja sendiri dan kebab dengan rasa bumbu rempah.&nbsp;</p>', '2024-03-26', '2024-11-03', '2024-12-19 14:46:01', '2024-12-19 14:46:01');
INSERT INTO `tenant` VALUES (5258, 435, 'public/foto_profil_tenant/6763d0fcef475.jpg', 'Ngurah Gallery', 'Ngurah Hendrawan', 47, 1, 'Ds/br tanglad, nusa penida, klungkung', NULL, '20.000.000,00', 'Facebook, Instagram, Tiktok, Shopee', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten, Lokal Lintas Provinsi', 'Ada', '<p>Melanjutkan warisan budaya, yaitu tenun rang-rang khas nusa penida dengan pewarna alami</p>', '2024-03-26', '2024-11-03', '2024-12-19 14:53:32', '2024-12-19 15:51:48');
INSERT INTO `tenant` VALUES (5259, 435, 'public/foto_profil_tenant/6763d1cfe8bb2.jpeg', 'Cattleya', 'Lisa Liha Rodifah', 47, 1, 'Jalan Merak, Lingkungan Galiran, Kabupaten Klungkung, Bali 80716', NULL, '30.000.000,00', 'Instagram, Tiktok, Shopee', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten', 'Ada', '<p>Totebag Cattleya merupakan ide usaha yang timbul dari permasalahan sosial, yaitu</p><p>maraknya penggunaan plastik yang mencemari lingkungan. Dari permasalahan tersebut,</p><p>muncullah ide untuk membuat produk pengganti plastik berbahan ramah lingkungan dengan</p><p>menggunakan bahan dari alam seperti kanvas, goni dan blacu. Tujuannya untuk menciptakan</p><p>produk pengganti yang tidak menggantikan fungsi utamanya. Selain hal tersebut ide usaha</p><p>totebag ini juga dilatar belakangi dengan maraknya trend fashion zaman sekarang.</p><p><br></p><p>Keunggulan produk :</p><p>Model beragam dan tidak pasaran</p><p>Kualitas tahan lama didukung dengan jaritan rapi dan kemudahan dalam perawatan</p><p>Model bisa dipakai disegala suasana formal/informal</p><p>Ramah Lingkungan</p><p>Support pengrajin tas local</p><p>Harga minimal, gaya maksimal</p><p>Bebas custom model dan desain totebag sesuai keperluan</p>', '2024-03-26', '2024-11-03', '2024-12-19 14:56:41', '2024-12-19 14:57:03');
INSERT INTO `tenant` VALUES (5260, 435, 'public/foto_profil_tenant/6763d2f3388d1.jpg', 'RR resturahayu', 'Ni Putu Seri Periyantini', 23, 7, 'Dusun metulis, desa Dawan kaler, Klungkung', NULL, '1.500.000,00', 'Facebook, Instagram, Tiktok', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten', 'Ada', '<p>Berawal dari pandemi pemilik membuat kripik pisang dri pisang panen sendri dikebun .mencoba iseng membuat camilan kripik namun banyak yang suka terutama yang rasa coklat.</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:01:55', '2024-12-19 15:01:55');
INSERT INTO `tenant` VALUES (5261, 435, 'public/foto_profil_tenant/6763d40c7fc97.jpg', 'Bramila', 'M.Wahyu Santosa', 23, 7, 'Dusun Sangging Gg. Srikaya Desa Dawan Klod Kab. Klungkung', NULL, '15.000.000,00', 'Facebook, Instagram, Tiktok, Tokopedia', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten, Lokal Lintas Provinsi', 'Ada', '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"425\" style=\"width: 319pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"425\" style=\"height:15.75pt;width:319pt\">Bali\r\n  Ceria merupakan badan usaha berbasis UMKM yg bergerak di industri bumbu rujak\r\n  kemasan dengan brand cap Mana Lagi yg menyajikan rasa khas legendaris kota\r\n  Klungkung , yg berlokasi di Desa Dawan Klod Kab. Klungkung.&nbsp;</td></tr></tbody></table>', '2024-03-26', '2024-11-03', '2024-12-19 15:06:36', '2024-12-19 15:06:36');
INSERT INTO `tenant` VALUES (5262, 435, 'public/foto_profil_tenant/6763d829c391a.jpg', 'Dinda Dwita', 'Hari Yustejo', 23, 7, 'Jl Werkudara no 19, Klungkung', NULL, '15.000.000,00', 'Tradisional', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten', 'Ada', '<p>Usaha ini pada awalnya adalah usaha sampingan. Sampai pada masa pandemi ketika usaha yg lain pada gulung tikar ternyata usaha sampingan ini berubah menjadi usaha utama di keluarga kami. Praktis semenjak pandemi kami mulai fokus mengembangkan usaha ini mulai mengurus perijinan, legalitas dan menambah jaringan kerjasama dengan pihak lain seperti swalayan, mini market, warung makan dan restoran. Dari pengamatan kami, produk ini dapat dinikmati konsumen mulai anak anak hingga orang tua. Dengan citarasa bawang yang sangat khas dan diproduksi dengan standar kesehatan dan bahan berkualitas Sangat cocok untuk oleh oleh teman, saudara dan keluarga.&nbsp;</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:11:06', '2024-12-19 15:24:09');
INSERT INTO `tenant` VALUES (5263, 435, 'public/foto_profil_tenant/6763d65f590e2.jpeg', 'RAMARAME', 'Ni Wayan Yuliasni', 23, 7, 'Btn penasan blok A no 8 thingan Banjarangkan', NULL, '20.000.000,00', 'Facebook, Instagram', 'Lokal (Kabupaten Klungkung), Lintas Kabupaten, Lintas Provinsi', 'Ada', '<p>Rama kripik tempe berdiri ditahun 2020 tepatnya tgl 22 maret, awal buka usaha ini bener2 susah bgt, knp?. Karena untuk mempromosikan produknya sangat sulit, setiap pasar yg didatangi blm mencoba produk yang ditawarin sudah bilang gak enak, apeklah, dan juga gak laku, tapi saya gak nyerah sampai disana saja, saya terus mencoba dan mencoba lagi. Keunggulannya sih, masih dalam rasa daun keruk karena blm ada yang berinovasi tempe dengan rasa2 spt itu👏👏</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:14:29', '2024-12-19 15:16:31');
INSERT INTO `tenant` VALUES (5264, 435, 'public/foto_profil_tenant/6763d7405ba15.jpg', 'Gula Merah Dawan', 'Ni Kadek Ayu Trisnayanti', 23, 7, 'Dusun kawan, desa besan, Dawan, Klungkung', NULL, '9.000.000,00', 'Tradisional', 'Lokal (Kabupaten Klungkung), Lintas Kabupaten', 'Tidak Ada', '<p>Hingga saat ini gula merah besan klungkung yang lebih di kenal dengan gula merah dawan peminat nya semakin meningkat.</p><p>Keunggulan dari produk gula merah besan,selain gula batok,ada juga gula semut,dan gula cair.</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:20:16', '2024-12-19 15:20:16');
INSERT INTO `tenant` VALUES (5265, 435, 'public/foto_profil_tenant/6763d8111f0f2.png', 'Kemala Handmade', 'Anak Agung Istri Agung Kemala Dewi', 47, 1, 'Jalan Pandu, Gang Gatotkaca (Rumah ke 2), Dusun Bingin, Banjar Agung, Desa Kusamba, Dawan, Klungkung.', NULL, '5.000.000,00', 'Facebook, Instagram, Tiktok,', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten, Lokal Lintas Provinsi', 'Ada', '<p>Berawal dari kecintaan owner pada crafting dan keresahan teman-teman di sekitar owner yang tasnya pada bagian dalam cepat jebol (rusak) maka owner mulai tertarik untuk belajar membuat tas serta mencari kain-kain yang cocok dijadikan tas.&nbsp;</p><p>Awal berdirinya sejak 2021, mengkususkan pada produk tote bag berbahan kain, dipilih kain karena bahan baku gampang di temukan, mudah di bersihkan dan harganya relatif bersaing dengan kualitas yang premium yang ingin di hadirkan.</p><div><br></div>', '2024-03-26', '2024-11-03', '2024-12-19 15:23:45', '2024-12-19 15:23:45');
INSERT INTO `tenant` VALUES (5266, 435, 'public/foto_profil_tenant/6763d8d8947a5.jpg', 'Melati Craft', 'Cok Istri Agung Brahmani Putri', 47, 1, 'Dusun Getakan Desa Getakan Banjarangkan Klungkung', NULL, '3.000.000,00', 'Tradisional', 'Lokal (Kabupaten Klungkung)', 'Tidak Ada', '<p>Bisnis kami berakar pada cinta mendalam terhadap warisan budaya Bali, menjadi pendorong utama dalam keinginan kami untuk menghadirkan keindahan tersebut melalui industri tekstil. Melalui inovasi dan dedikasi kami terhadap kualitas, produk tas kami menjadi simbol penyelarasan yang harmonis antara tradisi dan gaya hidup kontemporer. Dengan demikian, setiap tas yang kami hasilkan menjadi penghormatan terhadap kekayaan budaya Bali, sekaligus menawarkan pengalaman unik yang menggugah rasa keindahan dan keterlibatan dengan tradisi yang berharga.</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:27:04', '2024-12-19 15:27:04');
INSERT INTO `tenant` VALUES (5267, 435, 'public/foto_profil_tenant/6763d9bbc390b.png', 'Sari Putra', 'Adi Liangga Putra', 23, 7, 'Jln untung Surapati gang beringin no 15, Klungkung', NULL, '3.000.000,00', 'Instagram', 'Lokal (Kabupaten Klungkung)', 'Ada', '<p>Usaha berdiri sejak pandemi covid 19 melanda dimana usaha ini memproduksi makanan kacang asin yg memiliki keunggulan dari rasanya yg nikmat dan gurih</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:30:51', '2024-12-19 15:30:51');
INSERT INTO `tenant` VALUES (5268, 435, 'public/foto_profil_tenant/6763da9862a92.jpeg', 'UTENAYA', 'Ni Ketut Ayu Putri Cahyani', 23, 7, 'Jl. Nandini, kacang dawa, kamasan, klungkung', NULL, '3.000.000,00', 'Facebook, Instagram, Tiktok,', 'Lokal (Kabupaten Klungkung)', 'Ada', '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"425\" style=\"width: 319pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"425\" style=\"height:15.75pt;width:319pt\">dulu\r\n  sebelum saya membuat usaha tempe karamel saya berjualan nasi bungkus&nbsp; dan lauk pauk&nbsp; karena ada wabah covid 19 usaha saya macet\r\n  terus saya mulai dengan usaha onlen yaitu tempe karamel&nbsp; makanan indonesia yg awet untuk berbulan\r\n  bulan kalo ga habis /laku dipasaran ternyata usaha saya cocok di lidah\r\n  masyarakat bahkan di bawa&nbsp; keluar negri\r\n  untuk bekal.</td></tr></tbody></table>', '2024-03-26', '2024-11-03', '2024-12-19 15:34:32', '2024-12-19 15:34:32');
INSERT INTO `tenant` VALUES (5269, 435, 'public/foto_profil_tenant/6763db531054e.JPG', 'Pendet Pastry', 'Ni Made Sri Ayuni', 23, 7, 'Jalan Ngurah Rai Gg ganesha No 1, Klungkung', NULL, '40.000.000,00', 'Facebook, Instagram, Tiktok', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten', 'Ada', '<p>ingin menonjolkan kualitas makanan khususnya bakery yang menggunakan healthy ingredients yang dapat dijangkau masyarakat kalangan menengah kebawah&nbsp;</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:37:39', '2024-12-19 15:37:39');
INSERT INTO `tenant` VALUES (5270, 435, 'public/foto_profil_tenant/6763dc8875661.PNG', 'Ngecheezy', 'Alifa Ainnur Ditha', 23, 7, 'Jl. Gunung Merapi / Lingkungan Sengguan, Kec. Klungkung, Kab. Klungkung, Bali', NULL, '2.400.000,00', 'Instagram, Tiktok', 'Lokal ( Kabupaten Klungkung )', 'Tidak Ada', '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"425\" style=\"width: 319pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl65\" width=\"425\" style=\"height:15.75pt;width:319pt\">Ngecheezy\r\n  adalah sebuah brand makanan berbahan dasar keju dengan cita rasa lokal yang\r\n  autentik. Melalui Ngecheezy, Ngecheezy ingin memberikan alternatif inovasi\r\n  baru mengenai cita rasa pasta yang memadukan kelezatan pasta dengan sentuhan\r\n  rasa khas Indonesia. Ngecheezy mengangkat rasa lokal ke dalam hidangan pasta\r\n  dengan menggunakan bahan-bahan segar dan bumbu tradisional yang penuh cita\r\n  rasa.</td></tr></tbody></table>', '2024-03-26', '2024-11-03', '2024-12-19 15:42:48', '2024-12-19 15:42:48');
INSERT INTO `tenant` VALUES (5271, 435, 'public/foto_profil_tenant/6763dd4eb9558.png', 'CV Anugrah Coconut Indonesia', 'Gde Angga Pratama Nugraha', 48, 2, 'Jln. Waturenggong, Br.Sangkanbuana, Gg Patih Nambi No.1, Semarapura Kauh, Klungkung', NULL, '250.000.000,00', 'Facebook, Instagram, Tiktok, Tokopedia, Website', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten, Lokal Lintas Provinsi', 'Ada', '<p>Perusahaan yang memproduksi minyak kelapa&nbsp;</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:46:06', '2024-12-19 15:46:06');
INSERT INTO `tenant` VALUES (5272, 435, 'public/foto_profil_tenant/6763de7e43a6c.png', 'Sinar Penida VCO', 'Gede Sinarbawa', 48, 2, 'Banjar petinggian desa kutampi Kaler Nusa penida', NULL, '2.000.000,00', 'Instagram', 'Lokal (Kabupaten Klungkung)', 'Tidak Ada', '<p>Sinar penida vco awal mula dari seorang wisatawan yang berliburan ke penida sehingga saya memiliki suatu kesempatan untuk membuat VCO dengan kualitas kelapa yang tumbuh di batu kapur Nusa penida yang memiliki ciri khas yang beda dari rasa kelapa muda yang sedikit terasa bersoda dan hasil dari vco pun memiliki citra rasa khas yang berbeda dan manfaat untuk kesehatan terbaik.</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:51:10', '2024-12-19 15:51:10');
INSERT INTO `tenant` VALUES (5273, 435, 'public/foto_profil_tenant/6763df6690ca7.jpg', 'Papilas Coffe House', 'Pande Putu Wiyoga', 23, 7, 'jl ngurah rai, no. 27, klungkung, semarapura', NULL, '30.000.000,00', 'Facebook, Instagram, Shopee', 'Lokal ( Kabupaten Klungkung ), Lokal Lintas Kabupaten', 'Ada', '<p>kami Papilas Coffee&nbsp; bergerak di bidang usaha F&amp;B, memfokuskan pada produk olahan kopi lokal bali di sekmen specialty coffee industri. Kami ada untuk memenuhi kebutuhan masyarakat setempat maupun touris mancanegara yang berkunjung di kota Klungkung. Target pasar kami adalah para pekerja dan masyarakat kalangan mnengah keatas. Peluang itu cukup baik untuk saat ini hingga 10 thn. kedepan, akan tetapi kendala akan tingginya harga bahan baku 3 thn terakhir menghantui jalannya operasional usaha kami. Persaingan mulai muncul dan kami memandang ini hal yang positif untuk membangun ekosistem lebih pesat berkembang, salahsatunya merk dagang dari luar bali sdh muncul dibeberapa lokasi. Melihat kondisi itu kami semakin mantap untuk tetap mebranding diri sebagai pengusaha lokal dengan memanfaatkan sumber daya lokal. Jenis produk pun kami mengangkat beberapa konsep minuman lokal yaitu Arak Bali yng cukup terkenal diproses dengan mencampur biji kopi kedalam prosesnya dn menghasilkan salahsatu produk unggulan kami saat ini. Visi dan Misi kami adalah menjadi salahsatu merk usaha dagang terkenal, dan membangun ekosistem bisnis yang sehat di industri kopi Bali.</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:55:02', '2024-12-19 15:55:02');
INSERT INTO `tenant` VALUES (5274, 435, 'public/foto_profil_tenant/6763e03eed64d.jpeg', 'Banana Meliah', 'I Gede Arya Nata Wijaya', 23, 7, 'Dusun sukahati, desa pesinggahan, dawan, klungkung', NULL, '1.500.000,00', 'Instagram, Tiktok, Website', 'Lokal Lintas Kabupaten', 'Ada', '<p>Bananachips adalah camilan yang terbuat dari pisang yang&nbsp;</p><p>dipotong tipis, digoreng, dan dilumuri oleh rasa manis. Produk ini awalnya diluncurkan&nbsp;</p><p>dengan varian coklat, tetapi kemudian berkembang menjadi tiga varian, yaitu coklat,&nbsp;</p><p>tiramisu, dan matcha. Sebagai camilan ringan dan lezat, Bananachips memberikan sentuhan&nbsp;</p><p>kelezatan yang dapat dinikmati oleh berbagai kalangan konsumen. Dengan setiap gigitan,&nbsp;</p><p>pelanggan tidak hanya menikmati kelezatan Bananachips, tetapi juga mengalami sejarah&nbsp;</p><p>singkat yang membanggakan tentang bagaimana sebuah keisengan keluarga bisa&nbsp;</p><p>bertransformasi menjadi produk camilan yang memikat hati banyak orang.</p>', '2024-03-26', '2024-11-03', '2024-12-19 15:57:23', '2024-12-19 15:58:38');
INSERT INTO `tenant` VALUES (5275, 435, 'public/foto_profil_tenant/6763e0db74fb8.jpg', 'Warung Men Mery', 'Gde Edi Sumartika Diana', 23, 7, 'Dusun Patus,Desa Gunaksa', NULL, NULL, 'Facebook, Instagram, Tiktok,', 'Lokal ( Kabupaten Klungkung )', 'Ada', '<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"425\" style=\"width: 319pt;\"><tbody><tr height=\"21\" style=\"height:15.75pt\">\r\n  <td height=\"21\" class=\"xl66\" width=\"425\" style=\"height:15.75pt;width:319pt\">Warung\r\n  MM, Menjual makanan siap saji baik berbentuk bungkusan maupun Kotak. Yang\r\n  sudah mendapatkan ijin sertifikat like sehat, dimana kami lebih menggunakan\r\n  bumbu tradisional tanpa isi bahan pewarna makanan.<br>\r\n    <br>\r\n    </td></tr></tbody></table>', '2024-03-26', '2024-11-03', '2024-12-19 16:01:15', '2024-12-19 16:01:15');
INSERT INTO `tenant` VALUES (5276, 255, 'public/foto_profil_tenant/6764d962910fb.jpg', 'INER ALIBRA', 'RENI ARBILA BR SEBAYANG', 47, 1, 'Punthok lemah Abang No.50,RT.01, Bangunjiwo, Kec. Kasihan, Kabupaten Bantul, Daerah Istimewa Yogyakarta 55184', NULL, '5.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Batik iner Alibra fashion collection mengembangkan batik tulis, batik cap kertas, ecoprint maupun shibori ke dalam sebuah fashion dan aksesoris lainnya yang memiliki keunikan dan daya tarik dari ciri khas dari iner AliIbra.<br>Dengan mengembangkan kebudayaan batik yang ada di Indonesia bisa membantu perekonomian pribadi dan bisa membantu dan mempekerjakan banyak orang itulah tujuan iner Alibra didirikan.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 09:41:38', '2024-12-20 09:41:38');
INSERT INTO `tenant` VALUES (5277, 255, NULL, 'MDJ.art (rebranding Kundha)', 'Agung Nugroho', 47, 1, 'Sleman - Yogyakarta', NULL, '1.000.000,00', 'Online dan Offline', 'Internasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">MDJ.ART adalah jembatan antara tradisi dan dunia modern, menyatukan pengunjung lokal dan global dalam sebuah pengalaman seni yang mendalam. Dengan prospek pertumbuhan yang kuat di bidang pariwisata budaya dan ekspor produk kerajinan, MDJ.ART siap melangkah lebih jauh, membawa seni dan budaya Jogja ke panggung dunia.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 09:57:19', '2024-12-20 09:57:19');
INSERT INTO `tenant` VALUES (5278, 255, 'public/foto_profil_tenant/6764ddc823c9f.png', 'Kalandra Craft', 'Agus Septiawan', 47, 3, 'Baturan Lor Trihanggo Gamping Sleman', NULL, '2.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Kami memiliki aneka produk berbahan manik manik<br>Seperti cincin, gelang, kalung, gantungan kunci dan gantungan Hp</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:00:24', '2024-12-20 10:00:24');
INSERT INTO `tenant` VALUES (5279, 255, 'public/foto_profil_tenant/6764de3fa9b13.png', 'Waiky craft', 'Meitia Dwi Silfiani', 47, 1, 'Gunungsaren Kidul Rt 70 Trimurti Srandakan Bantul', NULL, '3.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Produk yg kami jual adalah aneka macam Merchandise antara lain Mug, pouch,T-shirt, Gantungan kunci akrilik, Plakat, Piala.dll<br><br>kami juga menyediakan kebutuhan pernikahan antara lain Mahar, Seserahan, souvenir dan hantaran.<br><br>untuk aksesoris kami juga memproduksi berbagai model aksesoris dari manik².<br><br>kami juga bergerak di bidang kerajinan.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:02:23', '2024-12-20 10:02:23');
INSERT INTO `tenant` VALUES (5280, 255, 'public/foto_profil_tenant/6764decd01d67.jpg', 'Alfatih bakery', 'Kuswaryani', 47, 7, 'Rejodani 1 rt03/02 , sari harjo, ngaglik, sleman', NULL, '3.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Menyediakan Bluder, aneka cake &amp; roti</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:04:45', '2024-12-20 10:04:45');
INSERT INTO `tenant` VALUES (5281, 255, 'public/foto_profil_tenant/6764df6669a2c.jpg', 'Sambelqyu', 'Denie Ermawati', 23, 7, 'Wonotingal RT 1, poncosari, srandakan , bantul', NULL, NULL, NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Menyediakan aneka sambal (teri, cumi, makarel, iga sapi)</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:07:18', '2024-12-20 10:07:18');
INSERT INTO `tenant` VALUES (5282, 255, 'public/foto_profil_tenant/6764dfe39689b.jpg', 'Kenangan Mantan', 'Retyaningsih', 23, 7, 'Jln Pleret jambidan Banguntapan Bantul', NULL, '15.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Kenangan Mantan menghadirkan 3 macam menu yaitu:<br>* Roti bakar Kenangan, roti bakar ini memiliki rasa yg unik dan macam2 costum roti seperti roti pelangi , roti hitam , juga ada macam2 toping dan isian yg tidak melulu manis namun juga ada yg gurih asin isian beef dan sayur<br><br>* Bakso Mantan, bakso yang disajikan dengan versi bumbu rumahan pedas gurih manis dengan berbagai macam isian dan nama yg unik seperti : RABI GAGAL (Rasa bakso isi original), DAKU RINDU (Dalemnya keju irisan dadu) , BASILOH (bakso isi telur puyuh) , PEGATAN (Pedes gebangetan)<br><br>* Honey MANGO, adalah jus buah asli tanpa pemanis buatan disajikan dengan topping whipcream buatan sendiri diatasnya ditambah potongan buah juga parutan keju<br>Kami menyediakan 3 buah yaitu mangga , alpukat , naga</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:09:23', '2024-12-20 10:09:23');
INSERT INTO `tenant` VALUES (5283, 255, 'public/foto_profil_tenant/6764e041abed4.png', 'Ola', 'Destila Vitisfera Putri', 47, 1, 'Perumahan Cepoko Indah blok c30 Kuden Sitimulyo Piyungan', NULL, '7.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Ola menjual aneka aksesoris seperti gelang, bando, scrunchie atau ikat rambut, gantungan kunci, dll.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:10:57', '2024-12-20 10:10:57');
INSERT INTO `tenant` VALUES (5284, 255, 'public/foto_profil_tenant/6764e09d5d5f5.jpg', 'AZALEA SNACK', 'Rasminita', 23, 7, 'Malangan, Sentolo, Sentolo,Kulon Progo', NULL, '1.500.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Jinis produk camilan stik pepaya terbuat dari buah pepaya segar yg diolah secara higienis.dan menjadikan camilan yg unik.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:12:29', '2024-12-20 10:12:29');
INSERT INTO `tenant` VALUES (5285, 255, 'public/foto_profil_tenant/6764e13a7297c.jpg', 'Bakul jenang/bubur jenang', 'Putri hidayati', 23, 7, 'Karangsari Wetan RT 14 RW 36 Banguntapan', NULL, '1.500.000,00', 'Oflline', 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Aneka macam bubur/jenang tradisional. Seperti jenang gempol, jenang sumsum, jenang mutiara, jenang candil</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:14:21', '2024-12-20 10:15:06');
INSERT INTO `tenant` VALUES (5286, 255, 'public/foto_profil_tenant/6764e1ddb3a87.png', 'KeQuean', 'Viesa Rahayu', 23, 7, 'Jl. Pamularsih 34 Yk', NULL, '4.500.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Cookies, cake, puding, camilan (sus kering), frozen food</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:17:49', '2024-12-20 10:17:49');
INSERT INTO `tenant` VALUES (5287, 255, 'public/foto_profil_tenant/6764e24ad469b.png', 'Bibibi MPASI Kids Meal', 'Azri Sofiati Ghoniyyah', 23, 7, 'Klenggotan RT 06, Srimulyo, Piyungan, Bantul Yogyakarta 55792', NULL, '4.000.000,00', NULL, 'Nasional', 'Arus Kas', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Bibibi MPASI Kids Meal menyediakan bumbu basah, lemak baik, selai, kaldu, dan beragam bahan dan bumbu MPASI rumahan dengan acuan kebutuhan menu lengkap sesuai panduan IDAI dan Kemenkes untuk MPASI Si Kecil. Produk kami dapat dikonsumsi mulai dari bayi usia 6 bulan hingga besar. Tujuan Bibibi adalah menciptakan kebiasaan pola makan sehat sedari pertama kali mengenal makanan padat setelah ASI atau susu formula.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:19:38', '2024-12-20 10:19:38');
