INSERT INTO `tenant` VALUES (5292, 255, 'public/foto_profil_tenant/6764e5463e61f.jpeg', 'Banchan', 'Kristina Listya Adi', 23, 7, 'Jl. Wahid Hasyim No. 173a Ngropoh Condongcatur Depok Sleman Yogyakarta 55283', NULL, '15.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Kami menjual berbagai makanan/jajanan ala Korea seperti Kimbab, Tokpokki, Chicken Yangyeom, Bibimbab, Odeng hingga Takoyaki</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:32:22', '2024-12-20 10:32:22');
INSERT INTO `tenant` VALUES (5293, 255, 'public/foto_profil_tenant/6764e59817a52.png', 'Mie Ayam Legenda', 'Yuve Desfinisonda', 23, 7, 'Jl pleret royal mansion banguntapan', NULL, '75.000.000,00', NULL, 'Nasional', 'Laba Rugi', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Mie ayam legenda yang dimasak khas oriental dengan menghadirkan sensasi gurih asin manis khas mie ayam jakarta dengan mie yg kenyal dan teksture pipih.<br>Mie Ayam Legenda<br>100% Halal<br>Lezatnya tak pernah putus</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:33:44', '2024-12-20 10:33:44');
INSERT INTO `tenant` VALUES (5294, 255, 'public/foto_profil_tenant/6764e60c831ef.png', 'Dinggoneh', 'Veronica Deni Ambarwati', 47, 3, 'Perumahan Jatimulyo Baru Blok J nomor 4 RW 6 RT 26 kelurahan kricak kecamatan Tegalrejo Yogyakarta', NULL, '200.000,00', NULL, 'Nasional', 'Arus Kas', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Aneka produk home décor dari limbah botol kaca bekas seperti vas bunga, wadah lilin hias, lampu hias, toples wadah<br>permen, gantungan kunci<br>semua produk dilukis dengan teknik lukis dan teknik decoupage</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:35:40', '2024-12-20 10:35:40');
INSERT INTO `tenant` VALUES (5295, 255, 'public/foto_profil_tenant/6764e65d98090.jpg', 'Dapur Siska @ Jogja', 'Constantius Paulus Yudy Martono', 23, 7, 'Janti Gg. Flamboyan no. 20, Caturtunggal, Depok, Sleman', NULL, '3.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Dapur Siska @ Jogja antara lain memproduksi Sirup Jeruk Nipis dengan merek CITRUSS.<br>Ada 2 varian yaitu Sirup Jeruk Nipis gula pasir dan Sirup Jeruk Nipis gula aren.<br>Tersedia dalam 2 ukuran, yaitu 250 ml dan 500 ml</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:37:01', '2024-12-20 10:37:01');
INSERT INTO `tenant` VALUES (5296, 255, 'public/foto_profil_tenant/6764e6b1012f6.jpg', 'Merindu', 'Danny', 23, 7, 'Jembatan Merah, Gejayan', NULL, '3.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Kuliner dan Craft</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:38:25', '2024-12-20 10:38:25');
INSERT INTO `tenant` VALUES (5297, 255, 'public/foto_profil_tenant/6764e71482138.jpg', 'ABIKARA', 'Ronny Yahya', 47, 1, 'jalan sewandanan kulon kauman PA II/54 rt.033 RW.009 kel.Gunung Ketur kec.Pakualaman Yogyakarta. 55111', NULL, '2.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">ABIKARA Merupakan Brand Fashion yang memadukan T-shirt dengan kombinasi batik khas Indonesia.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:40:04', '2024-12-20 10:40:04');
INSERT INTO `tenant` VALUES (5298, 255, 'public/foto_profil_tenant/6764e772572a6.jpg', 'Kala Kreasi (Kala Batik)', 'Fenita Agustina', 47, 1, 'Jl. Ampel no 26 Karangsari wedomartani ngemplak sleman', NULL, '1.500.000,00', NULL, 'Nasional', 'Laba Rugi', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Kala Kreasi memiliki produk berupa totebag yang khas dengan menggunakan kain tie dye yang dibuat secara handmad. Selain totebag, juga ada produk lain, seperti clutch, pashmina, sarung bantal sofa, dll.</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:41:38', '2024-12-20 10:41:38');
INSERT INTO `tenant` VALUES (5299, 255, 'public/foto_profil_tenant/6764e7bd98080.jpg', 'MARBLAZE', 'ARDIAN MULYO JATI', NULL, 1, 'GEDONGKIWO MJ 1/1156 RT 62 RW 12, MANTRIJERON, YOGYAKARTA', NULL, '5.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Marblaze mengubah cara berpikir orang tentang fashion melalui inovasi dalam pewarnaan marbling. Produk tidak hanya fungsional tetapi juga memikat hati dengan keindahan. Dari sini, Marblaze menghadirkan produk fashion yang mengeksplorasi batas-batas seni melalui teknik pewarnaan marbling, yang mengapungkan warna di atas air dan mentransfernya ke media di mana produk tersebut dibuat.<br>Teknik pewarnaan marbling awalnya digunakan untuk membuat motif diatas kertas. Seiring berjalannya waktu, teknik ini mengalami perkembangan dapat digunakan sebagai sampul buku,naskah,kitab dan dekoratif kertas. Marblaze mengembangkan inovasi teknik pewarnaan marbling pada produk kulit sapi dengan mengadaptasi teknik dan alat yang ada. Teknik ini menampilkan pola abstrak seperti marmer. Pola motif yang dihasilkan tidak akan sama antara satu dengan yang lainnya, sehingga tidak ada produk akhir yang sama atau diduplikasi.<br>Setiap produk Marblaze bukan sekedar pakaian atau aksesoris, namun sebuah karya seni yang memadukan keindahan dan kreativitas manusia. Menggabungkan elemen tradisional dengan inovasi modern untuk menciptakan produk yang berbeda dan bernilai lebih dari sekedar produk fashion tetapi juga memberikan pengalaman yang menarik perhatian dan menyentuh hati.<br></span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:42:53', '2024-12-20 10:42:53');
INSERT INTO `tenant` VALUES (5300, 255, 'public/foto_profil_tenant/6764e8086e695.jpeg', 'Diari rasa', 'Maya sari', 23, 7, 'Tegal mraen rt 02/09 sendangadi mlati', NULL, '5.000.000,00', NULL, 'Nasional', 'Jurnal', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Bawang goreng , kuliner sncak box , nasi box</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:44:08', '2024-12-20 10:44:08');
INSERT INTO `tenant` VALUES (5301, 255, 'public/foto_profil_tenant/6764e8961ee64.jpg', 'minuk_craft', 'SUBARTI', 47, 3, 'Tapansari RT 01 rw01 Watusigar Ngawen Gunungkidul', NULL, '2.500.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Buket dengan berbagai macam isian (bunga,Snack,jilbab,alat masak,uang,boneka)</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:46:30', '2024-12-20 10:46:30');
INSERT INTO `tenant` VALUES (5302, 255, 'public/foto_profil_tenant/6764e8e76d933.jpg', 'Herbadeepa', 'Melisa Mawar Wati', 23, 7, 'Krapyak kulon Rt 03 no 98, Panggungharjo, Sewon, Bantul, Yogyakarta', NULL, '12.000.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Herbadeepa adalah usaha kuliner lebih khususnya minuman siap seduh seperti teh rempah dan juga berbagai jenis rempah rempah kering</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 10:47:51', '2024-12-20 10:47:51');
INSERT INTO `tenant` VALUES (5303, 255, 'public/foto_profil_tenant/6764ed2c06442.png', 'Lugu Batik', 'Susanti Rahayu Pangestuti', 23, 7, 'Tempel RT 03, Sidomulyo, Bambanglipuro, Bantul', NULL, '10.000.000,00', NULL, 'Nasional', 'Arus Kas', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Produk busana, kain motif abstrak warna alami, jasa desain busana, jahit busana</span></p>', '2024-08-01', '2024-10-29', '2024-12-20 11:00:53', '2024-12-20 11:06:04');
INSERT INTO `tenant` VALUES (5304, 1037, NULL, 'Kelompok Taruna Tani Siliwangi', 'Naufal Rif\'at, S.T.', 1, 2, 'Jl. Raya Tutugan No.177 RT.002/RW.002 Ds.Haruman Kec.Leles', NULL, '200.000.000,00', 'Internet', 'Wilayah Kabupaten Garut', NULL, NULL, '2021-04-01', '2023-03-21', '2024-12-21 10:23:46', '2024-12-21 10:23:46');
