INSERT INTO `tenant` VALUES (5306, 255, 'public/foto_profil_tenant/6768b936374f8.jpg', 'Kedai Oryza Corner', 'Sugeng Setiyoso', 23, 7, 'Semail, Bangunharjo, Sewon , Bantul', NULL, '4.500.000,00', NULL, 'Nasional', 'Pembukuan Sederhana', '<p><span data-sheets-root=\"1\" style=\"font-size: 10pt; font-family: Roboto, Arial; color: rgb(67, 67, 67);\">Produk yg dijual adalah Pempek</span></p>', '2024-08-01', '2024-10-29', '2024-12-23 08:13:26', '2024-12-23 08:13:26');
INSERT INTO `tenant` VALUES (5307, 255, 'public/foto_profil_tenant/6768b9b15b1e9.jpg', 'Sajiwa', 'Christiyanto', 23, 7, 'Babadan Wedomartani Ngemplak Sleman', NULL, NULL, NULL, NULL, '-', '<p>Menyediakan produk minuman kesehatan</p>', '2024-08-01', '2024-10-29', '2024-12-23 08:15:29', '2024-12-23 08:15:29');
INSERT INTO `tenant` VALUES (5308, 15, 'public/foto_profil_tenant/6768c80874c52.png', 'Tabrizah', 'Rezky Maulana', 46, 6, 'Jl. Telekomunikasi, Sukapura, Kec. Dayeuhkolot, Kabupaten Bandung, Jawa Barat', NULL, NULL, 'Instagram', 'Sekolah', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Calibri; font-size: 14.6667px; white-space-collapse: preserve;\">Tabrizah Foundation adalah startup yang menggabungkan pendidikan dengan layanan teknologi informasi (TI). Kami bertujuan untuk mengatasi kesenjangan literasi dan penguasaan TI di berbagai sekolah di daerah kami. Kami menawarkan solusi kustom untuk lembaga pendidikan mulai dari tingkat dasar hingga lanjutan, membantu mereka memberikan pendidikan yang komprehensif berfokus pada TI. Layanan kami mencakup bidang TI penting seperti pemrograman, jaringan, dan AI Prompt Engineer.</span></p>', '2024-02-20', '2024-09-04', '2024-12-23 09:16:40', '2024-12-23 09:51:15');
INSERT INTO `tenant` VALUES (5309, 15, 'public/foto_profil_tenant/67bd3ade724af.png', 'Nexilium', 'Titus Tunjung', 46, 6, 'Jl. Telekomunikasi, Sukapura, Kec. Dayeuhkolot, Kabupaten Bandung, Jawa Barat', NULL, '15.000,00', 'Instagram', 'Pelajar', NULL, '<div class=\"ewa-rteLine\" style=\"color: rgb(0, 0, 0); font-family: Calibri; font-size: 14.6667px; white-space-collapse: preserve;\"><div class=\"ewa-rteLine\" style=\"font-family: &quot;Aptos Narrow&quot;;\">Nexilium adalah perusahaan rintisan (startup) yang berfokus pada pengembangan teknologi untuk memudahkan kehidupan melalui solusi berbasis aplikasi. Saat ini, Nexilium berfokus di sektor pendidikan dengan produk andalannya, Helphin. Helphin merupakan platform edukasi kolaboratif yang dirancang untuk membantu siswa mengakses solusi pembelajaran yang terjangkau, sekaligus memberi kesempatan bagi mereka untuk mendapatkan penghasilan tambahan.</div><div class=\"ewa-rteLine\" style=\"font-family: &quot;Aptos Narrow&quot;;\"><br></div><div class=\"ewa-rteLine\" style=\"font-family: &quot;Aptos Narrow&quot;;\">Tujuan utama platform ini adalah menciptakan lingkungan di mana siswa dapat saling mendukung secara akademis dengan cara yang fleksibel, mudah diakses, serta sesuai dengan kebutuhan mereka. Dengan Helphin, Nexilium berupaya membantu siswa belajar lebih efektif dan memperoleh manfaat lebih selama proses belajar.</div></div>', '2024-02-20', '2024-09-04', '2024-12-23 09:50:58', '2025-02-25 10:37:02');
INSERT INTO `tenant` VALUES (5310, 659, 'public/foto_profil_tenant/6768d1341140a.jpg', 'Sambel Pecel Kediri', 'Nikmatur Sholekhah', 23, 7, 'Kediri Jawa Timur', NULL, '10.000.000,00', 'Media Sosial, Door to Door', 'Pulau Jawa, Kalimantan, dan Sumatera', 'Manual', NULL, '2024-12-01', '2024-12-31', '2024-12-23 09:55:48', '2024-12-23 09:55:48');
INSERT INTO `tenant` VALUES (5311, 15, 'public/foto_profil_tenant/6768d420e947c.png', 'Feelsbox', 'Muhammad Fathi Rabbani', 43, NULL, 'Jl. Telekomunikasi, Sukapura, Kec. Dayeuhkolot, Kabupaten Bandung, Jawa Barat', NULL, NULL, 'Instagram, Website', 'Pelajar, SMA, SMP, Mahasiswa, Universitas, Perusahaan, Startup, Kementerian, Lembaga non Pemerintah', NULL, '<div class=\"ewa-rteLine\" style=\"color: rgb(0, 0, 0); font-family: Calibri; font-size: 14.6667px; white-space-collapse: preserve;\">Membayangkan perubahan, inisiatif kami Feelsbox mencari dunia yang membuka tangannya terhadap masalah kesehatan mental. Di kalangan siswa, mematahkan stigma yang dicakup oleh kesehatan mental adalah misi kami. Dengan lokakarya yang menarik, platform kami menawarkan cara yang menarik untuk mengatasi masalah kesehatan mental dengan menghilangkan kesalahpahaman. Dengan layanan konseling yang mudah diakses dan komunitas yang ramah, Feelsbox membantu orang menceritakan kisah mereka. </div><div class=\"ewa-rteLine\" style=\"color: rgb(0, 0, 0); font-family: Calibri; font-size: 14.6667px; white-space-collapse: preserve;\">Didedikasikan untuk membantu meningkatkan harga diri orang, tim kami terdiri dari psikolog terlatih dan ahli lokakarya.</div>', '2023-10-10', '2024-11-26', '2024-12-23 10:08:16', '2025-03-10 09:23:25');
INSERT INTO `tenant` VALUES (5312, 15, 'public/foto_profil_tenant/6768d56ace302.png', 'Efika Creative', 'Nurvilio Bagus', 47, NULL, 'Jl. Telekomunikasi, Sukapura, Kec. Dayeuhkolot, Kabupaten Bandung, Jawa Barat', NULL, NULL, 'Instagram', 'MSMEs (Micro, Small, and Medium Enterprises), usaha produktif yang dimiliki oleh individu, rumah tangga, atau entitas bisnis', NULL, '<p>Bisnis Studio Desain yang berfokus pada pengerjaan Brand Identity (Logo)</p>', '2024-02-20', '2024-09-04', '2024-12-23 10:13:46', '2024-12-23 10:13:46');
INSERT INTO `tenant` VALUES (5313, 15, 'public/foto_profil_tenant/6768d73b15cdf.png', 'Learnhub', 'Fajar Bagus', 47, 6, 'Jl. Sidomulyo No 31 Bandung,West Java, Indonesia', NULL, NULL, 'Website', 'Content Creator', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Calibri; font-size: 14.6667px; white-space-collapse: preserve;\">Learnhub memberi pembuat konten pengalaman tanpa batas untuk menumbuhkan pengikut mereka, berbagi pengetahuan, dan mendapatkan penghasilan berkelanjutan dalam satu platform tunggal.</span></p>', '2024-02-20', '2024-09-04', '2024-12-23 10:21:31', '2024-12-23 10:21:31');
INSERT INTO `tenant` VALUES (5314, 15, 'public/foto_profil_tenant/6768e2f32bb63.png', 'Hidup Media', 'Hermansyah Hidayat', 43, NULL, 'Jl. Telekomunikasi, Sukapura, Kec. Dayeuhkolot, Kabupaten Bandung, Jawa Barat', NULL, NULL, NULL, 'Sekolah, Universitas, Pemerintahan, Perusahaan', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: Calibri; font-size: 14.6667px; white-space-collapse: preserve;\">Hidup Media, merupakan perusahaan dalam bidang psikologi industri dan organisasi  untuk mengoptimalkan karyawan dan menyelesaikan masalah gap generation di perusahaan. Kami memiliki layanan asessment, konseling group, dan training soft skill untuk mengkoneksikan karyawan dengan&nbsp;perusahaan</span></p>', '2024-02-20', '2024-09-04', '2024-12-23 11:11:31', '2024-12-23 11:11:31');
INSERT INTO `tenant` VALUES (5315, 1003, NULL, 'PAHALA SARI NIRA', 'DWI SETIAWAN', 23, 2, 'Desa Plosorejo Rt.04 Rw.05 Kecamatan Kademangan Kabupaten Blitar Jawa Timut', NULL, '25.000.000,00', 'Whatsapp Business, Instagram, Facebook, Google Business, Shopee', 'Internasional', 'Digital', '<p>UMKM kami bergerak di bidang produksi dan distribusi gula merah berkualitas tinggi, baik gula merah kelapa maupun gula merah tebu. Dengan mengedepankan bahan baku alami yang dipilih langsung dari petani lokal, kami memastikan setiap produk yang dihasilkan memiliki rasa otentik, warna alami, dan kualitas terbaik.</p><p>Proses produksi dilakukan secara higienis dengan standar mutu tinggi untuk memenuhi kebutuhan konsumen rumah tangga, usaha kuliner, hingga industri makanan dan minuman. Kami juga menyediakan layanan pengemasan sesuai kebutuhan, mulai dari kemasan kecil untuk ritel hingga kemasan besar untuk distribusi grosir.</p><p>Sebagai mitra terpercaya, kami berkomitmen mendukung keberlanjutan dan pemberdayaan petani lokal, serta memastikan suplai gula merah yang stabil dan kompetitif. Dengan pelayanan yang cepat, responsif, dan profesional, kami siap memenuhi kebutuhan pasar lokal maupun luar daerah.</p>', '2024-11-13', '2025-05-13', '2024-12-26 07:33:14', '2024-12-26 07:38:37');
INSERT INTO `tenant` VALUES (5316, 1003, NULL, 'NOTIAN COOKIES', 'WAHYU RIA NOVITASARI', 23, 7, 'Desa Plosorejo Rt.04 Rw.05 Kecamatan Kademangan Kabupaten Blitar Jawa Timur', NULL, '15.000.000,00', 'Whatsapp Mesengger, Instagram, Facebook', 'Internasional / Ekpor', 'Digital', '<p>UMKM kami adalah produsen kue kering premium yang mengedepankan kualitas rasa dan inovasi. Berawal dari kue kering klasik nastar, kami telah mengembangkan berbagai varian rasa dan isian untuk memenuhi selera pelanggan yang beragam. Setiap kue diproduksi dengan bahan-bahan berkualitas tinggi, tanpa pengawet, dan melalui proses yang higienis untuk menjaga kelezatan dan kesegarannya.</p><p>Dengan pengalaman dalam memenuhi permintaan pasar lokal maupun internasional, kami rutin mengirimkan produk ke berbagai negara setiap minggunya. Hal ini menjadi bukti kepercayaan konsumen akan kualitas produk kami. Selain untuk konsumsi pribadi, kue kering kami juga sangat cocok sebagai bingkisan dan hadiah spesial untuk berbagai kesempatan.</p><p>Kami terus berinovasi dalam menciptakan varian baru untuk memberikan pengalaman kuliner yang unik dan tak terlupakan. Melalui kemasan yang elegan dan layanan yang profesional, kami siap menjadi pilihan utama bagi pecinta kue kering di seluruh dunia.</p><p>Nikmati cita rasa kue kering premium kami dan jadikan setiap momen lebih istimewa!</p>', '2024-11-13', '2025-05-13', '2024-12-26 07:37:40', '2024-12-26 07:37:40');
INSERT INTO `tenant` VALUES (5317, 1003, NULL, 'TERAS REJEKI', 'TRI RAHAYU NINGSIH', 40, 7, 'Desa Plosorejo Rt.04 Rw.01 Kecamatan Kademangan Kabupaten Blitar Jawa Timur', NULL, '12.000.000,00', 'Instagram, Facebook', 'Nasional', 'Digital', '<div class=\"flex max-w-full flex-col flex-grow\"><div data-message-author-role=\"assistant\" data-message-id=\"34f81a20-88b6-4155-a52a-1bb788fdf26d\" dir=\"auto\" class=\"min-h-8 text-message flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" data-message-model-slug=\"gpt-4o\"><div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\"><div class=\"markdown prose w-full break-words dark:prose-invert light\"><p>UMKM kami bergerak di bidang jasa dan perdagangan retail, menyediakan berbagai kebutuhan masyarakat dengan beragam produk berkualitas. Dengan konsep pelayanan yang ramah, cepat, dan profesional, kami hadir sebagai solusi belanja harian yang nyaman dan terpercaya.</p><p>Kami menawarkan berbagai macam produk, mulai dari kebutuhan pokok, perlengkapan rumah tangga, hingga produk lifestyle yang selalu mengikuti tren terkini. Dengan harga yang kompetitif dan program promosi menarik, kami berkomitmen untuk memberikan nilai lebih kepada pelanggan.</p><p>Lokasi yang strategis serta suasana toko yang bersih dan tertata rapi membuat pengalaman belanja menjadi lebih menyenangkan. Selain itu, kami juga mendukung transaksi digital dan menyediakan layanan pengiriman untuk memberikan kemudahan bagi pelanggan.</p><p>Kepercayaan dan kepuasan pelanggan adalah prioritas utama kami. Dengan semangat melayani, kami terus berinovasi untuk menjadi mitra belanja terbaik bagi masyarakat.</p></div></div></div></div>', '2024-11-13', '2025-05-13', '2024-12-26 07:43:51', '2024-12-26 07:43:51');
INSERT INTO `tenant` VALUES (5318, 1003, NULL, 'DAPUR MAMA ARSEN', 'KRISDIANA WULANDARI', 23, 7, 'Dusun Gogourung Rt. 04 Rw.05 Desa Dawuhan Kecamatan Kademangan Kabupaten Blitar Jawa Timur', NULL, '5.000.000,00', 'Whatsapp Mesengger, Facebook, Tik Tok', 'Internasional / Ekpor', 'Digital', '<p>UMKM kami menyediakan berbagai produk kuliner dan minuman khas Nusantara yang cocok untuk dinikmati kapan saja. Dengan fokus pada cita rasa autentik, kami menawarkan:</p><ul><li><strong>Es Teh Segar</strong>: Minuman pelepas dahaga yang menyegarkan dengan rasa teh yang khas.</li><li><strong>Sambel Pecel</strong>: Sambal tradisional dengan rasa gurih dan pedas, dibuat dari bahan pilihan untuk melengkapi hidangan sehari-hari.</li><li><strong>Bumbu Rujak Uleg</strong>: Bumbu rujak dengan rasa asam, manis, dan pedas yang menggugah selera, ideal untuk menemani aneka buah segar.</li><li><strong>Mie Level</strong>: Hidangan mie dengan berbagai pilihan tingkat kepedasan yang bisa disesuaikan dengan selera pelanggan.</li></ul><p>Semua produk kami diolah dengan bahan berkualitas tinggi, tanpa pengawet, dan dijaga kebersihannya untuk memastikan kualitas terbaik. Kami juga melayani pesanan dalam jumlah besar untuk acara atau usaha kuliner lainnya.</p><p>Dengan harga terjangkau dan cita rasa yang memikat, UMKM kami berkomitmen menjadi pilihan utama bagi pecinta kuliner lokal. Nikmati produk kami untuk pengalaman rasa yang unik dan tak terlupakan!</p>', '2024-11-13', '2025-05-13', '2024-12-26 07:47:48', '2024-12-26 07:47:48');
INSERT INTO `tenant` VALUES (5319, 1003, NULL, 'WARUNG RIZKY', 'SRI MONAH', 23, 7, 'Dusun Plumpungrejo, Desa Plumpungrejo, Kecamatan Kademangan, Kabupaten Blitar Jawa Timur', NULL, '8.000.000,00', 'Whatsapp Mesengger', 'Kelurahan/Desa', 'Manual', '<p>UMKM kami hadir untuk menyajikan cita rasa autentik kuliner khas Nusantara yang menggugah selera. Menu andalan kami meliputi:</p><ol><li><strong>Nasi Pecel</strong>: Hidangan ikonik dengan kombinasi nasi hangat, aneka sayuran segar, dan sambal kacang khas yang nikmat.</li><li><strong>Sayur Lodeh</strong>: Masakan tradisional berkuah santan dengan rasa gurih dan aroma rempah yang kaya.</li><li>Aneka lauk pelengkap, seperti tempe goreng, tahu bacem, dan rempeyek, yang melengkapi hidangan utama.</li></ol><p>Kami menggunakan bahan-bahan segar dan berkualitas untuk menjaga cita rasa dan kelezatan setiap hidangan. Proses pengolahan dilakukan secara higienis, sehingga pelanggan dapat menikmati makanan dengan rasa lezat sekaligus sehat.</p><p>Dengan pelayanan yang ramah dan harga yang terjangkau, kami melayani kebutuhan makan sehari-hari, acara keluarga, hingga pesanan dalam jumlah besar. Nikmati sajian kuliner khas Nusantara yang selalu menggugah selera hanya di tempat kami!</p>', '2024-11-13', '2025-05-13', '2024-12-26 07:52:35', '2024-12-26 07:52:35');
INSERT INTO `tenant` VALUES (5320, 1003, NULL, 'NAFI GERABAH', 'NAFI', 50, 3, 'Dusun Precet, RT 01 RW 01, Desa Plumpungrejo, Kecamatan Kademangan, Kabupaten Blitar, Jawa Timur.', NULL, '20.000.000,00', 'Whatsapp Mesengger, Facebook', 'Provinsi', 'Digital', '<p>UMKM kami bergerak di bidang kerajinan gerabah yang menghadirkan peralatan dapur tradisional dengan sentuhan seni dan fungsi. Produk-produk kami dibuat dari bahan tanah liat berkualitas tinggi dan diolah secara teliti oleh para pengrajin berpengalaman.</p><p>Kami menawarkan berbagai macam peralatan dapur berbahan gerabah, seperti:</p><ol><li><strong>Wajan dan panci gerabah</strong> untuk memasak dengan cita rasa khas.</li><li><strong>Cobek dan ulekan</strong> yang kokoh untuk menghasilkan sambal yang sempurna.</li><li><strong>Teko dan gelas gerabah</strong> untuk pengalaman menikmati minuman dengan nuansa tradisional.</li><li>Aneka wadah dan tempat penyimpanan yang estetik dan fungsional.</li></ol><p>Produk gerabah kami tidak hanya praktis dan ramah lingkungan tetapi juga menambah estetika pada dapur Anda. Dengan menjaga keaslian teknik tradisional, kami juga mendukung inovasi desain untuk memenuhi kebutuhan modern.</p><p>Kami melayani penjualan retail maupun grosir, serta menerima pesanan khusus untuk acara atau dekorasi. Pilih gerabah kami untuk peralatan dapur yang tahan lama, unik, dan sarat dengan nilai budaya.</p>', '2024-11-13', '2025-05-13', '2024-12-26 07:58:20', '2024-12-26 07:58:20');
INSERT INTO `tenant` VALUES (5321, 1003, NULL, 'PUJI CATERING', 'PUJI RAHAYUNINGSIH', NULL, NULL, 'Desa Jimbe, RT 03 RW 04, Kecamatan Kademangan, Kabupaten Blitar, Jawa Timur.', NULL, '4.000.000,00', 'Whatsapp Mesengger', 'Kecamatan', 'Manual', '<p>UMKM kami menyediakan berbagai pilihan kuliner berupa makanan basah dan kering yang cocok untuk dinikmati di segala kesempatan. Dengan mengutamakan kualitas bahan baku dan cita rasa autentik, kami menghadirkan:</p><ol><li><strong>Makanan Basah</strong>: Beragam olahan seperti kue tradisional, aneka gorengan, dan camilan bertekstur lembut yang cocok untuk sajian sehari-hari maupun acara spesial.</li><li><strong>Makanan Kering</strong>: Camilan renyah seperti keripik, kue kering, dan aneka snack yang praktis untuk teman bersantai atau dibawa bepergian.</li></ol><p>Setiap produk dibuat dengan bahan segar dan proses produksi yang higienis, sehingga memberikan rasa yang lezat dan tahan lama. Kami juga menyediakan kemasan menarik dan rapi, menjadikannya pilihan tepat untuk oleh-oleh atau bingkisan.</p><p>Kami melayani pembelian dalam jumlah kecil maupun besar dengan harga yang kompetitif. Dengan fokus pada kepuasan pelanggan, kami siap menjadi solusi kuliner terbaik untuk semua kebutuhan Anda.</p>', '2024-11-13', '2025-05-13', '2024-12-26 08:02:47', '2024-12-26 08:02:47');
INSERT INTO `tenant` VALUES (5322, 1003, NULL, 'DONAT KENTANG', 'RIAMIN', 23, 7, 'Desa Plosorejo, RT 01 RW 08, Kecamatan Kademangan, Kabupaten Blitar, Jawa Timur.', NULL, '5.000.000,00', 'Whatsapp Business, Facebook', 'Kecamatan', 'Manual', '<p><google-sheets-html-origin style=\"color: rgb(0, 0, 0); font-size: medium;\"></google-sheets-html-origin></p><p>UMKM kami bergerak di bidang kuliner dengan spesialisasi dalam pembuatan aneka kue basah yang menggugah selera. Kami menawarkan berbagai pilihan kue tradisional dan modern yang cocok untuk segala acara, mulai dari santapan sehari-hari hingga hidangan istimewa pada momen spesial.</p><p>Beberapa produk andalan kami meliputi:</p><ol><li><strong>Kue lapis</strong> yang lembut dan berwarna menarik.</li><li><strong>Klepon</strong> dengan isian gula merah yang lumer di mulut.</li><li><strong>Onde-onde, kue putu, dan kue talam</strong> yang bercita rasa khas Nusantara.</li><li>Aneka kue basah lainnya yang selalu segar dan lezat.</li></ol><p>Kami menggunakan bahan berkualitas tinggi dan proses produksi yang higienis untuk memastikan setiap kue yang kami sajikan memiliki rasa terbaik dan aman untuk dikonsumsi. Dengan kemasan yang rapi, produk kami juga cocok untuk bingkisan atau hidangan saat acara penting.</p><p>Kami melayani pesanan untuk keperluan personal, acara keluarga, hajatan, hingga kebutuhan dalam jumlah besar dengan harga yang kompetitif. Temukan kelezatan kue basah tradisional dan modern hanya di UMKM kami!</p>', '2024-11-13', '2025-05-13', '2024-12-26 08:05:25', '2024-12-26 08:05:25');
INSERT INTO `tenant` VALUES (5323, 1003, NULL, '58 JAYA ROTI', 'SINEM RAHAYU', 39, 7, 'Dusun Ringinanom, RT 04 RW 04, Kecamatan Kademangan, Kabupaten Blitar, Jawa Timur.', NULL, '3.500.000,00', 'Whatsapp Mesengger, Facebook', 'Kecamatan', 'Manual', '<p>UMKM kami bergerak di bidang produksi dan perdagangan makanan ringan serta minuman yang cocok untuk segala usia. Dengan fokus pada kualitas dan inovasi, kami menghadirkan beragam pilihan produk untuk menemani aktivitas harian Anda, seperti:</p><ol><li><strong>Makanan Ringan</strong>: Aneka keripik, camilan tradisional, snack modern, dan produk ringan lainnya yang lezat dan praktis.</li><li><strong>Minuman Segar</strong>: Minuman kemasan seperti es teh, jus buah, hingga minuman herbal yang menyegarkan dan menyehatkan.</li></ol><p>Semua produk kami diolah dari bahan-bahan berkualitas tinggi dengan proses yang higienis untuk memastikan kepuasan pelanggan. Kami juga menawarkan kemasan menarik dan beragam ukuran, sehingga cocok untuk konsumsi pribadi maupun acara tertentu.</p><p>Selain melayani kebutuhan lokal, kami membuka peluang kerjasama untuk reseller dan distribusi. Dengan harga yang kompetitif dan rasa yang terjamin, kami siap menjadi pilihan utama untuk kebutuhan makanan ringan dan minuman Anda.</p>', '2024-11-13', '2025-05-13', '2024-12-26 08:11:12', '2024-12-26 08:11:12');
INSERT INTO `tenant` VALUES (5324, 1003, NULL, 'ARBYY SNACK', 'YUNI MUSYAROFAH', 23, 2, 'Lingkungan Sutojayan, RT 03 RW 01, Kecamatan Sutojayan, Kabupaten Blitar, Jawa Timur.', NULL, '2.000.000,00', 'Whatsapp Business, Instagram, Facebook', 'Kecamatan', 'Manual', '<p><strong>ARBYY</strong> adalah usaha kuliner yang fokus pada produksi berbagai macam olahan keripik yang enaknya gak habis-habis! Kami menghadirkan keripik dengan rasa khas yang menggugah selera, cocok untuk segala suasana, mulai dari camilan santai hingga pelengkap saat berkumpul bersama keluarga dan teman.</p><p>Produk unggulan kami meliputi:</p><ol><li><strong>Keripik Pisang</strong> dengan tekstur renyah dan rasa manis gurih yang pas.</li><li><strong>Keripik Singkong</strong> yang gurih dan kaya rasa.</li><li><strong>Keripik Pare</strong> dengan rasa unik yang menjadi favorit pencinta camilan sehat.</li><li><strong>Keripik Tempe</strong> yang renyah dengan cita rasa tradisional khas Nusantara.</li></ol><p>ARBYY menggunakan bahan-bahan segar dan berkualitas, diolah dengan teknik modern tanpa menghilangkan keaslian rasa tradisional. Dengan kemasan praktis dan higienis, produk kami tetap segar hingga dinikmati.</p><p>Kami juga menyediakan berbagai pilihan rasa, seperti manis, asin, pedas, dan bumbu rempah khas yang memanjakan lidah. Baik untuk konsumsi pribadi, oleh-oleh, maupun acara spesial, ARBYY adalah pilihan tepat untuk menikmati camilan yang tak terlupakan!</p>', '2024-11-13', '2025-05-13', '2024-12-26 08:14:28', '2024-12-26 08:14:28');
INSERT INTO `tenant` VALUES (5325, 1003, NULL, 'ENIA BATIK', 'ENI AGUSTIAH', 47, 1, 'Dusun Bendelonje, RT 03 RW 12, Desa Kendalrejo, Kecamatan Talun, Kabupaten Blitar, Jawa Timur.', NULL, '5.000.000,00', 'Whatsapp Business', 'Kelurahan/Desa', 'Manual', '<p><strong>Enia Batik</strong> adalah usaha yang memproduksi batik tulis berkualitas tinggi dengan menggunakan bahan-bahan pilihan. Kami menghadirkan kain batik yang memadukan keindahan seni tradisional dan nilai estetika yang sesuai dengan kebutuhan masa kini.</p><p>Produk kami dirancang dengan ukuran kain standar untuk orang dewasa, sehingga cocok untuk berbagai keperluan, mulai dari pakaian formal, busana kasual, hingga keperluan adat dan budaya. Setiap motif batik dibuat secara teliti oleh pengrajin berpengalaman, memastikan setiap helai kain menjadi karya seni yang unik dan penuh makna.</p><p>Dengan komitmen pada kualitas, kami menggunakan pewarna alami maupun sintetis berkualitas yang ramah lingkungan, sehingga kain batik kami nyaman dikenakan dan tahan lama. Selain itu, Enia Batik juga melayani pesanan khusus untuk desain dan motif tertentu sesuai permintaan pelanggan.</p><p><strong>Enia Batik</strong> adalah pilihan sempurna bagi Anda yang menghargai keindahan batik tulis dan ingin tampil istimewa dengan busana yang elegan dan bermakna.</p>', '2024-11-13', '2025-05-13', '2024-12-26 08:17:38', '2024-12-26 08:17:38');
INSERT INTO `tenant` VALUES (5326, 150, 'public/foto_profil_tenant/676e4ab693783.png', 'NUFOOD', 'Nunu Setyaningsih', NULL, NULL, 'Perum Amarapura Blok E4/2, Kelurahan\r\nKademangan, Kecamatan Setu, Tangerang\r\nSelatan.', NULL, '30.000.000,00', NULL, 'Nasional', NULL, '<p>Nufood Solusi Nusantara\r\nUsaha kami hadir sebagai solusi terhadap kebutuhan\r\nprotein negara kita yang masih kecil dibanding negara\r\ntetangga (Data FAO). Dan produk-produk kami\r\nmerupakan produk unik yang belum banyak diproduksi\r\noleh perusahaan besar sekalipun (Chicken Nori\r\npertama dan satu2nya di Indonesia yg diproduksi\r\nsecara massal. Demikian juga perkedel masih jarang\r\nada.</p>', '2024-02-26', '2024-02-26', '2024-12-27 13:35:34', '2024-12-27 13:36:15');
INSERT INTO `tenant` VALUES (5327, 150, 'public/foto_profil_tenant/676e4eb827328.png', 'Ngekrez Food', 'AYU FEBRINA DAMAYANTI', 23, 7, 'Perumahan citra prima serpong, blok A2 no\r\n11, muncul, setu, tangsel-banten,', NULL, '60.000.000,00', 'Instagram, Whatsapp, TikTok', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<p>Ngekrez Food\r\nNGEKREZ merupakan usaha di bidang kuliner atau makanan\r\nolahan bahan dasar ayam. Produk NGEKREZ adalah kulit ayam\r\nkrispi (chicken skin), kedai fried chicken dengan aneka varian,\r\nkedai minuman yg bernama CLAK yg menyegarkan. NGEKREZ\r\nselalu menjunjung tinggi prinsip higienis dalam proses\r\nproduksi, kandungan manfaat yg baik untuk dikonsumsi serta\r\nefisien bagi para konsumen. Harga produk NGEKREZ sangat\r\nterjangkau dan dikemas dengan baik sehingga kualitas produk\r\nterjaga.</p><p>Perumahan citra prima serpong, blok A2 no\r\n11, muncul, setu, tangsel-banten,</p>', '2024-02-26', '2024-07-02', '2024-12-27 13:52:40', '2025-10-08 11:50:18');
