INSERT INTO `tenant` VALUES (5332, 973, 'public/foto_profil_tenant/67734a988c95c.jpg', 'J-Buz', 'Ahmad isnandar', 23, 7, 'Jln Kates Dusun Al-Abror Desa Jembatan Kembar Timur', NULL, '1.000.000,00', 'Facebook ,', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Telur asin dan kopi merupakan 2 produk yang hampir banyak orang yang mencarinya tp karna telur belum banyak yg budidaya bebek maka telur asin jarang d persentasi </span></p>', NULL, NULL, '2024-12-31 08:36:24', '2025-01-02 07:58:43');
INSERT INTO `tenant` VALUES (5333, 973, 'public/foto_profil_tenant/67734b3362288.jpg', 'ARRENDI', 'Siti Arbaiyah', 23, 7, 'Jl.ade irma suryani panda 1 monjok', NULL, '15.000.000,00', 'WhatsApp, FB', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Usaha sy sudah berjalan bbrp thn ,jatuh bangun sy membangunx.akhirx dengn sy menjaga kwalitas dan kwantitas produk sy hingga sekrg msh bertahan dan diminati banyak kalangan.dr anak kecil hingga orang dewasa</span></p>', NULL, NULL, '2024-12-31 08:38:59', '2025-01-02 07:58:18');
INSERT INTO `tenant` VALUES (5334, 973, 'public/foto_profil_tenant/67734be8acee2.jpg', 'Zizi Online Shop', 'Muhammad Juriawan', 23, 7, 'Jl. Jurusan Gelora Lendang Nangka Masbagik, Lombok Timur NTB', NULL, '36.000.000,00', 'Facebook', 'Lokal ,Provinsi', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Usaha berdiri sejak tahun 2015 diawali dengan sebagai resseler dan sekarang sudah memproduksi sendiri</span></p>', NULL, NULL, '2024-12-31 08:42:00', '2025-01-02 07:57:53');
INSERT INTO `tenant` VALUES (5335, 973, 'public/foto_profil_tenant/67734cd827b36.jpeg', 'Pawon Pengsong', 'Nur Aida', 23, 7, 'Jalan Raya Pengsong Griya Perembun Asri Blok L 05 Perampuan Kec. Labuapi Lombok Barat,', NULL, '250.000.000,00', 'Facebook , instagram', 'Lokal ,Provinis, Nasional dan Internasional', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Pawon Pengsong adalah Salah satu IKM yang berlokasi Desa Peampuan Kec. Labuapi Lombok Barat. Pawon Pengsong berdiri pada tahun 2019, Membangun usaha dengan bermodal Rp. 500.000 membuat Produk Serbat Jahe dan Aneka Olahan Kopi, Pada tahun 2022 Pawon Pengsong menciptakan Inovasi Produk dengan menggunakan salah satu Potensi terbesar di NTB yaitu Rumput Laut, Adapun rumput laut ini di olah menjadi panganan berupa Biskuit Rumput laut dan aneka olahan lainnya, Biskuit Rumput laut ini merupakan panganan sehat dan merupakan salah satu produk unggulan daerah dan mempu menembus pasar Nasional maupun Interrnasional.</span></p>', NULL, NULL, '2024-12-31 08:46:00', '2025-01-02 07:56:52');
INSERT INTO `tenant` VALUES (5336, 973, 'public/foto_profil_tenant/677609602af33.jpg', 'Madu Kawah Rinjani', 'Ahmad Subhan', 23, 7, 'Kmp. Nurmujahidin desa Rumbuk kec. Sakra Lotim', NULL, NULL, 'Facebook', 'Lokal ,Provinis, Nasional', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Madu untuk kesehatan, berbagai macam manfaat untuk kesehatan tubuh. </span></p>', NULL, NULL, '2024-12-31 09:34:18', '2025-01-02 10:34:56');
INSERT INTO `tenant` VALUES (5337, 973, 'public/foto_profil_tenant/677358893cfe9.jpeg', 'Jamur Sasak', 'Wirasandi', 23, 7, 'Jl. Bungkarno Pagutan Petemon No 99 Mataram. NTB', NULL, '250.000.000,00', 'Facebook , instagram', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Usaha budidaya jamur tiram adalah salah satu usaha yang menjanjikan karena permintaan pasar yang tinggi dan proses budidaya yang relatif mudah. Jamur tiram memiliki masa panen yang singkat, sekitar 3-4 bulan sejak mulai dibudidayakan, sehingga dapat memberikan hasil yang cepat. Media tanamnya sederhana, biasanya menggunakan baglog yang terbuat dari campuran serbuk kayu, Dedak dan Kapur. Selain itu, usaha ini dapat dimulai dengan modal kecil dan lahan terbatas, sehingga cocok untuk pemula. Produk jamur tiram juga dapat diolah menjadi berbagai produk makanan, seperti keripik jamur atau jamur crispy, untuk meningkatkan nilai jual.</span></p>', NULL, NULL, '2024-12-31 09:35:53', '2025-01-02 07:55:25');
INSERT INTO `tenant` VALUES (5338, 973, 'public/foto_profil_tenant/677358df07925.jpg', 'Zia Collection', 'Paoziah', 48, 2, 'Btn.Babakan Permai Dekat Panti Asuhan Hidayaturrahman Babakan Mataram,Lombok,NTB', NULL, '18.000.000,00', 'Facebook , instagram', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Zia Collection bergerak dalam pembuatan bahan Tenun menjadi baju jadi siap pakai dan berlokasi di Babakan Permai</span></p>', NULL, NULL, '2024-12-31 09:37:19', '2025-01-02 07:54:40');
INSERT INTO `tenant` VALUES (5339, 973, 'public/foto_profil_tenant/6776097278106.jpg', 'UD Kurnia', 'Dewi andriani', 23, 7, 'Rumbuk tanah gadang 2 jln surya herlambang', NULL, '10.000.000,00', 'Facebook , instagram , WhatsApp', 'Lokal ,Provinsi', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Ud .kurnia berdiri thn 2000 tapi blm mempunyai legalitas .setlah thn 2017 ud.kurnia mulai melangkapi legalitasya seperti.NIB.PIRT.HALAL.dan sertifikat TKDN.dan semejka mempunyai legalitas ud.kurnia semakin di kenalnoleh masyarakat dan dines2 terkait sehingga bisa mengikuti berbagi pelatihan2 unruk usaha tersebut sekaligus memperomosikan produk2 yg di hasilkan dr peolahan ikan dan rumput laut yg dmana produk tersebut di antaraya.kerupuk kulit ikan.kerupuk rumput laut.abon ikan pari.minyak ikan hiu.pilus rumput laut keju .</span></p>', NULL, NULL, '2024-12-31 14:43:15', '2025-01-16 12:00:14');
