INSERT INTO `tenant` VALUES (5361, 1153, 'public/foto_profil_tenant/677f4b32e29c6.jpeg', 'Air Masak Isi Ulang SEULANGA', 'M. Gade', 40, NULL, 'Desa Turue Cut Kecamatan Mane Kabupaten Pidie', NULL, '6.000.000,00', 'Offline', 'Masyarakat sekitar', 'ada', '<p>Air Masak Isi Ulang Seulanga bersumber dari pengunungan dan melalui beberapa tahap penyaringan sebelum dan sesudah dimasak. Sehingga menghasilkan air yang bersih dan segar.</p>', '2024-04-04', '2024-05-09', '2025-01-04 19:41:43', '2025-01-09 11:06:10');
