INSERT INTO `tenant` VALUES (5378, 973, 'public/foto_profil_tenant/678883c68916a.jpg', 'PT. Lasingan Lombok Indonesia', 'Iskandar Zulqarnain B., ST.', 23, 7, 'Jalan Ade Irma Suryani, Gang Panda 1 Blok B/39 Monjok Perluasan, Kec. Selaparang, Kota Mataram, NTB 83122.', NULL, '150.000.000,00', 'website : www.Lasingan.com', 'Nasional', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">PT. Lasingan Lombok Indonesia adalah usaha mikro dalam bidang pengolahan biji kopi denagn berbagai jenis produk atau berbagai varian.</span></p>', NULL, NULL, '2025-01-09 14:43:23', '2025-01-16 10:59:45');
INSERT INTO `tenant` VALUES (5379, 973, 'public/foto_profil_tenant/678883b066a7e.jpg', 'Kopi Tujak', 'Koperasi Produsen Bumi Tani Lestari Indonesia', 23, 7, 'Dusun Sajang Daya, Desa Sajang, Kec. Sembalun, Kab. Lombok Timur, NTB.', NULL, '1.000.000.000,00', 'Instagram : www.instagram.com/kopi_tujak_sajang/', 'Internasional', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Koperasi Produsen Bumi Tani Lestari Indonesia adalah koperasi produsen yang memproduksi berbagai produk perkebunan organik, seperti: kopi, vanili, durian, coklat, cengkeh, alpukat, pisang. Produk dalam bentuk mentah atau pun olahan.</span></p>', NULL, NULL, '2025-01-09 14:45:52', '2025-01-16 10:57:36');
