INSERT INTO `tenant` VALUES (5405, 779, 'public/foto_profil_tenant/678351b63125c.jpg', 'Proton Sakinah', 'Yudi', 44, 6, 'Jl. Ahmad Yani No.15, Jonogaran, Ngantru, Kec. Trenggalek, Kabupaten Trenggalek, Jawa Timur 66311', NULL, '50.000.000,00', NULL, NULL, NULL, NULL, '2024-12-03', '2024-12-03', '2025-01-12 12:23:02', '2025-01-12 12:23:02');
INSERT INTO `tenant` VALUES (5406, 413, 'public/foto_profil_tenant/67848a52e5dfe.jpeg', 'Rabeg T\'eng', 'Heriyah', 23, 7, 'Link. Ketileng Timur RT.004 RW.001 Kota Cilegon', NULL, '100.000.000,00', 'FB, IG, WA', 'KAB/KOTA, PROVINSI, NASIONAL', 'Manual', '<p>Pandampingan dalam rangka memperoleh Izin Edar Pangan Olahan MD BPOM produk olahan Daging berbumbu dalam kemasan.</p>', '2023-11-20', '2024-08-20', '2025-01-13 10:36:50', '2025-01-13 10:36:50');
INSERT INTO `tenant` VALUES (5407, 1178, 'public/foto_profil_tenant/6784bf56604c2.png', 'DE-LIMA', 'Syamsudin', 23, 7, 'Jalan Bina warga Desa Telaga Bidadari RT 1 RW 1 Kecamatan Sungai Raya, Kab. HSS', NULL, '21.000.000,00', 'Offline / Online', 'Dalam Provinsi', 'Manual', '<p>Menyediakan camilan keluarga khas lokal, seperti kacang telor dan stik kaldu ayam.</p><p>Secara legalitas Usaha, sudah memiliki Nomor Induk Berusaha, IPRT, Sertifikat Halal dan BPOM.</p><p>Memiliki Karyawan sebanyak 3 orang</p>', '2025-01-01', '2026-12-31', '2025-01-13 14:23:02', '2025-01-14 07:05:01');
INSERT INTO `tenant` VALUES (5408, 1178, 'public/foto_profil_tenant/6784c5571b7cb.jpg', 'HAYYUN', 'Kurnia', 23, 7, 'Jalan Binawarga, Kapuh Madani, Desa Telaga Bidadari  No 86. RT 1 RW 1 Kecamatan Sungai Raya , Kab. HSS', NULL, '16.000.000,00', 'Offline / Online', 'Dalam Provinsi', 'Manual', '<p>Sebuah usaha rumahan dalam memproduksi makanan khas Kab. HSS berupa Dodol dan Wajik.</p><p>Usaha ini sudah memiliki NIB, IPRT dan Sertifikat Halal, serta juga sudah memiliki Hak Merek.</p><p>Memiliki karyawan sebanyak 5 orang&nbsp;</p>', '2025-01-01', '2026-12-31', '2025-01-13 14:48:39', '2025-01-13 14:48:39');
INSERT INTO `tenant` VALUES (5409, 812, 'public/foto_profil_tenant/678501b35cb1e.PNG', 'Oceanic Bloom', 'Shafa Salisa Nabila', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60111', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Oceanic Bloom merupakan bisnis usaha pupuk organik yang pengolahannya terbuat dari limbah ikan, sehingga dapat menghasilkan pupuk organik berkualitas tinggi yang mendukung pertanian ramah lingkungan. Proses produksi yang berbahan dasar limbah ikan dengan menggunakan bahan tambahan gula aren dan EM4 pertanian. Pupuk ini dirancang untuk meningkatkan kesuburan tanah dan menyediakan nutrisi yang diperlukan bagi pertumbuhan tanaman.</span></p>', NULL, NULL, '2025-01-13 19:06:11', '2025-01-13 19:06:11');
INSERT INTO `tenant` VALUES (5410, 812, 'public/foto_profil_tenant/678502c366540.png', 'Moojika', 'Kayana Alodia Putri A.F', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60112', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Perusahaan kami memproduksi susu biji semangka dengan merek \"Moojika\", alternatif sehat yang inovatif untuk mencegah kanker serviks. Susu ini kaya akan antioksidan, vitamin, dan mineral penting, seperti likopen yang efektif melawan radikal bebas. Kami berharap produk ini dapat memberikan edukasi tentang manfaat kesehatan biji semangka dan meningkatkan kesadaran akan pentingnya pencegahan kanker.</span></p>', NULL, NULL, '2025-01-13 19:10:43', '2025-01-13 19:10:43');
INSERT INTO `tenant` VALUES (5411, 812, 'public/foto_profil_tenant/678503add7da1.png', 'Navarch Interior', 'Ahmad Rifki Rosiano', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60134', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Ide bisnis desain interior</span></p>', NULL, NULL, '2025-01-13 19:14:37', '2025-01-13 19:14:37');
INSERT INTO `tenant` VALUES (5412, 812, 'public/foto_profil_tenant/67850562d7c34.jpg', 'OceanShip Creation', 'Adham Gus Ariandawam', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60124', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Naval Study &amp; Game adalah bisnis yang berfokus pada penyediaan materi edukatif dan sumber daya terkait perkapalan. Dengan tujuan untuk meningkatkan pengetahuan dan keterampilan di bidang perkapalan, kami menawarkan produk berkualitas yang dapat diakses oleh mahasiswa dan profesional. Selain itu, kami juga mengembangkan game edukasi yang menarik untuk membantu pengguna memahami konsep-konsep perkapalan secara interaktif, sehingga menciptakan pengalaman belajar yang menyenangkan dan efektif.</span></p>', NULL, NULL, '2025-01-13 19:21:54', '2025-01-13 19:21:54');
INSERT INTO `tenant` VALUES (5413, 812, 'public/foto_profil_tenant/678506971e8d0.jpg', 'Jyoti Body Care', 'Ristanti Akseptori', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60113', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Jyoti Body Care adalah perusahaan yang fokus membuat sabun organik berkualitas tinggi untuk perawatan kulit. Kami menggunakan bahan-bahan alami seperti minyak kelapa, madu, lidah buaya, dan kopi, yang menawarkan solusi aman dan efektif untuk mengatasi bekas luka dan eksim. Kami berkomitmen untuk menjaga lingkungan dengan menggunakan kemasan yang ramah lingkungan dan mendukung petani kopi lokal dengan membeli bahan baku langsung dari mereka. Produk kami dirancang khusus untuk kulit sensitif, menjadikannya pilihan tepat bagi mereka yang peduli dengan kesehatan kulit dan keberlanjutan. Dengan cara ini, Jyoti Body Care tidak hanya membantu merawat kulit, tetapi juga mendukung masyarakat dan lingkungan sekitar.</span></p>', NULL, NULL, '2025-01-13 19:27:03', '2025-01-13 19:27:03');
INSERT INTO `tenant` VALUES (5414, 812, 'public/foto_profil_tenant/678506c095001.jpeg', 'Resylic Creation', 'Mochammad Rizky Zakaria', NULL, NULL, '\"Jl. Teknik Kimia Kampus ITS, Keputih, Sukolilo, Surabaya 60111.\"', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Resylic Creation adalah bisnis yang didirikan oleh 10 mahasiswa Politeknik Perkapalan Negeri Surabaya. Bisnis ini berfokus pada produksi dan penjualan produk dekoratif dan fungsional berbasis resin, seperti lampu tidur, jam dinding, gantungan kunci, dan gelang. Produk unggulannya, lampu tidur dengan teknologi UV anti-nyamuk, menawarkan keunikan dari segi estetika sekaligus fungsionalitas. Resylic Creation menargetkan anak muda dan penggemar dekorasi rumah yang mencari produk unik dan personal. Dengan memanfaatkan strategi pemasaran digital di Instagram, TikTok, dan Shopee, Resylic Creation berencana memperluas jangkauan pasar​</span></p>', NULL, NULL, '2025-01-13 19:27:44', '2025-01-13 19:27:44');
INSERT INTO `tenant` VALUES (5415, 812, 'public/foto_profil_tenant/6785077152099.png', 'Odyssea', 'Adianda Rizwan Diwandono', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60114', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Odyssea merupakan bisnis clothing yang menghadirkan t-shirt bertema maritim, dengan setiap desain menceritakan sejarah maritim Indonesia. Karena melihat dari jumlah pulau yang ada di Indonesia sebanyak 17.000 dan 1.340 suku membuat Indonesia memiliki berbagai macam sejarah dan budaya. Dari keberagaman tersebut yang memotivasi kami untuk mengenalkan macam-macam sejarah dalam visual produk t-shirt, mengedukasi, serta mengenalkan kekayaan budaya yang ada di Indonesia. Sehingga Odyssea memiliki tujuan yaitu “Mengenalkan Budaya dan Sejarah Kemaritiman Indonesia Pada Masyarakat Luas”.</span></p>', NULL, NULL, '2025-01-13 19:30:41', '2025-01-13 19:30:41');
INSERT INTO `tenant` VALUES (5416, 812, 'public/foto_profil_tenant/678507f6c4147.png', 'River Blue', 'Bagas Junianta Nur Ambiyaa', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60115', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">RiverBlue merupakan usaha yang berfokus dalam memproduksi bahan pangan seperti tepung, kaldu, dan makanan ringan yang berbahan dasar dari limbah tulang ikan. Bisnis kami memanfaatkan limbah yang berupa tulang ikan bandeng. Produk yang kami kembangkan menggunakan barang-barang organik yang ramah lingkungan yang kaya akan protein dan kalsium yang dibutuhkan oleh tubuh manusia. Selain bertujuan untuk mendapatkan keuntungan, kami juga diharapkan dapat membantu mengurangi limbah dan mendukung ekonomi sirkular.</span></p>', NULL, NULL, '2025-01-13 19:32:54', '2025-01-13 19:32:54');
INSERT INTO `tenant` VALUES (5417, 812, 'public/foto_profil_tenant/678508bfc824e.png', 'Kanasai', 'Yesica Novrita Devi', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60116', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">kanasai adalah media akuaponik dengan bantuan teknologi IoT yang mempermudah dalam pembudidayaan tanaman dan ikan. dilengkapi dengan grow led yang sudah bisa dikontrol aplikasi</span></p>', NULL, NULL, '2025-01-13 19:36:15', '2025-01-13 19:36:15');
INSERT INTO `tenant` VALUES (5418, 812, 'public/foto_profil_tenant/678509588a945.JPG', 'Ti-Di Core', 'Dwi Bagas Prasetyo', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60126', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">FILAXINE (FILAMENT EXTRUDER MACHINE) guna mendukung zero waste 3d print serta recycle</span></p>', NULL, NULL, '2025-01-13 19:38:48', '2025-01-13 19:38:48');
INSERT INTO `tenant` VALUES (5419, 812, 'public/foto_profil_tenant/67850ab153e9e.jpg', 'IndoHost Families', 'Alma Lia Hakim', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60146', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">IndoHostFamilies adalah sebuah platform penyedia layanan akomodasi berbasis boarding house (kos) yang menyasar para pelajar, pekerja, dan perantau di Jakarta dan Surabaya. IndoHostFamilies tidak hanya menawarkan tempat tinggal, tetapi juga menyediakan paket makan sehat dan terkontrol, serta pengalaman “keluarga baru” bagi mereka yang merantau. Ide ini diadaptasi dari model Host Families di negara-negara seperti Selandia Baru, yang menawarkan suasana akomodasi yang lebih personal dan mendukung kontrol nutrisi serta kesejahteraan penghuni. IndoHostFamilies berpotensi untuk menjadi solusi inovatif bagi pelajar dan pekerja perantau di Indonesia yang membutuhkan lebih dari sekedar tempat tinggal. Dengan memanfaatkan konsep akomodasi yang terintegrasi dengan layanan nutrisi dan suasana kekeluargaan, IndoHostFamilies mampu menciptakan nilai tambah bagi penggunanya, sekaligus menjawab kebutuhan akan gaya hidup sehat di kalangan perantau.</span></p>', NULL, NULL, '2025-01-13 19:44:33', '2025-01-13 19:44:33');
INSERT INTO `tenant` VALUES (5420, 812, 'public/foto_profil_tenant/67850f44a4fd8.PNG', 'SafePlay Studio', 'Alvin Ardiansyah', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60127', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Board game yang menggabungkan keseruan permainan dengan pendidikan K3, di mana pemain mempelajari risiko dan praktik keselamatan sambil bermain. Setiap langkah di papan permainan melibatkan situasi dan tantangan K3 di tempat kerja, dengan solusi yang membantu pemain memahami pentingnya keselamatan</span></p>', NULL, NULL, '2025-01-13 19:49:42', '2025-01-13 20:04:04');
INSERT INTO `tenant` VALUES (5421, 812, 'public/foto_profil_tenant/67850d9970f7f.png', 'FAN K37', 'Muhammad Dani Saputra Adi', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60147', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Pavana Fan merupakan bisnis yang bergerak di bidang manufaktur, dengan membuat produk Axial Fan, Axial Fan adalah jenis kipas yang di rancang untuk menggerakkan udara atau gas melalui sumbu rotornya, membuatnya ideal untuk berbagai aplikasi industri maupun komersial</span></p>', NULL, NULL, '2025-01-13 19:56:57', '2025-01-13 19:56:57');
INSERT INTO `tenant` VALUES (5422, 812, 'public/foto_profil_tenant/67850e60555c2.png', 'Devtrainer Kit', 'Rohmad Hadi Handayani', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60148', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Kami menawarkan trenkit microcontroller yang dirancang khusus untuk meningkatkan pemahaman dan keterampilan siswa dalam bidang teknologi dan pemrograman. Setiap kit dilengkapi dengan komponen mudah digunakan, tutorial interaktif, dan proyek menarik yang mendorong kreativitas dan inovasi. Dengan fokus pada pembelajaran praktis, produk ini bertujuan untuk menjembatani kesenjangan antara teori dan praktik, mempersiapkan generasi muda untuk tantangan teknologi masa depan. Trenkit ini cocok untuk sekolah, lembaga pendidikan, dan individu yang ingin belajar dengan cara menyenangkan.</span></p>', NULL, NULL, '2025-01-13 20:00:16', '2025-01-13 20:00:16');
INSERT INTO `tenant` VALUES (5423, 812, 'public/foto_profil_tenant/67850eff57ab1.jpeg', 'SEDASA', 'Adela Mustika Rani', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60149', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">SEDASA merupakan bisnis fashion kreatif yang menghadirkan vest inovatif yang dapat diubah menjadi tas, menawarkan solusi gaya 2 in 1 yang multifungsi bagi konsumen. Produk ini menggabungkan estetika dengan kepraktisan, serta pengenalan dan pelestarian budaya lokal Tanjung Perak Surabaya sehingga dapat memberikan nilai tambah bagi mereka yang mencari efisiensi dalam penampilan dan barang bawaannya.</span></p>', NULL, NULL, '2025-01-13 20:02:55', '2025-01-13 20:02:55');
INSERT INTO `tenant` VALUES (5424, 812, 'public/foto_profil_tenant/67850fa143129.png', 'Lighthouse Box', 'Muhammad Ansori Alwi', NULL, NULL, 'Jl. Raya Taddan,\r\nKec. Camplong, Sampang, Jawa Timur 69281', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Lighthouse Box adalah solusi pencahayaan navigasi yang berkelanjutan, ramah lingkungan, dan mudah dioperasikan, dirancang untuk mendukung industri maritim dengan memastikan sinyal pencahayaan yang efektif dan efisien sepanjang jalur perairan. Dengan fokus pada kemudahan pengoperasian, daya tahan yang tinggi, dan kemampuan pemantauan jarak jauh, Lighthouse Box memberikan nilai tambah yang signifikan bagi para pelaku industri maritim. Produk ini menjadikan pencahayaan mercusuar lebih aman, efisien, dan ramah lingkungan, mendukung kelancaran navigasi laut secara optimal.</span></p>', NULL, NULL, '2025-01-13 20:05:37', '2025-01-13 20:05:37');
INSERT INTO `tenant` VALUES (5425, 812, 'public/foto_profil_tenant/67851af694894.png', 'Daslicious', 'Mades Darul Khairansyah, S.ST., M.T.', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60128', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Bisnis stik adas kami menghadirkan camilan sehat berbahan dasar adas, yang dikenal memiliki manfaat kesehatan. Dengan rasa gurih alami dan tekstur renyah, stik adas dirancang untuk memenuhi kebutuhan konsumen yang mencari makanan ringan yang lezat namun tetap sehat. Produk ini dipasarkan melalui kemitraan dengan UMKM, toko kelontong, dan platform digital, dengan fokus pada gaya hidup sehat dan konsumsi produk lokal. Kami berkomitmen untuk menawarkan camilan berkualitas yang dapat dinikmati oleh semua kalangan.</span></p>', NULL, NULL, '2025-01-13 20:05:42', '2025-01-13 20:53:58');
INSERT INTO `tenant` VALUES (5427, 812, 'public/foto_profil_tenant/6785103688573.jpg', 'SafeGuard', 'Kharisma Innayatul Zulfa', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60129', NULL, NULL, NULL, NULL, NULL, '<p>Jasa website monitoring perawatan APAR, P3K, dan Safety Patrol</p>', NULL, NULL, '2025-01-13 20:08:06', '2025-01-13 20:08:06');
INSERT INTO `tenant` VALUES (5428, 812, 'public/foto_profil_tenant/6785103ef0422.jpg', 'DoSuSa', 'Wahyu Indra Pratama', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60151', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Dodol Susu Aneka Rasa (DoSuSa) memproduksi dodol susu dengan berbagai varian rasa buah seperti buah nanas, nangka, labu, dan buah mangga. Produk ini menggabungkan resep dodol tradisional dengan teknologi modern tanpa mengurangi kualitas, cita rasa dan ciri khas dari produk dodol itu sendiri</span></p>', NULL, NULL, '2025-01-13 20:08:14', '2025-01-13 20:08:14');
INSERT INTO `tenant` VALUES (5430, 812, 'public/foto_profil_tenant/6785118b55a0e.png', 'SafetyBoost Academy', 'Ahmad Fatihul Azzam', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60130', NULL, NULL, NULL, NULL, NULL, '<p>SafetyBoost Academy merupakan perusahaan yang bergerak di bidang pendidikan berbasis teknologi. SafetyBoost Academy didirikan untuk menjawab tantangan industri dalam pendidikan dan pelatihan keselamatan kerja. Bidang usaha yang ditawarkan mencakup keselamatan dan kesehatan kerja, dengan fokus pada penyediaan materi pembelajaran terkait praktik keselamatan dan kesehatan di tempat kerja, serta pengembangan profesional untuk meningkatkan keterampilan individu dan organisasi dalam manajemen risiko dan prosedur keselamatan.</p>', NULL, NULL, '2025-01-13 20:13:47', '2025-01-13 20:13:47');
INSERT INTO `tenant` VALUES (5431, 812, 'public/foto_profil_tenant/678511b401e81.png', 'KRIBOK', 'Fristiar Dana Insani', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60152', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">KRIBOK yakni keripik yang berasal dari bahan dasar tembolok ayam yang dijadikan keripik dengan rasa-rasa yakni original jagung bakar dan pedas manis. kami membuat olahan dari tembolok dikarenakan tembolok ayam ini masih sering dibuang secara cuma-cuma dan kita memanfaatkan tembolok ayam ini menjadi inovasi keripik.</span></p>', NULL, NULL, '2025-01-13 20:14:28', '2025-01-13 20:14:28');
INSERT INTO `tenant` VALUES (5432, 812, 'public/foto_profil_tenant/6785123cc3c0e.jpeg', 'CHIWINGS POK POK', 'Salvian Setyo Prayitno', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60153', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">judul ide bisnis produk yang kami buat adalah \" Chiwings Pok Pok \" (Chicken Wings Frozen Food). Bisnis chicken wings merupakan usaha yang fokus pada penyediaan sayap ayam yang disajikan dengan berbagai varian rasa, seperti spicy, teriyaki, dan barbeque. Produk ini umumnya dijual dalam ukuran 250 gr per pack. Chicken wings sangat populer sebagai makanan cepat saji atau camilan. Sasaran utama bisnis ini adalah semua kalangan, terutama mereka yang suka mencoba makanan baru dan gemar bersosialisasi di tempat makan kasual atau melalui layanan pengiriman makanan. Pasar ini juga mencakup kelompok pekerja yang menginginkan makanan cepat dan lezat serta keluarga yang mencari opsi makan bersama yang mudah dan terjangkau.</span></p>', NULL, NULL, '2025-01-13 20:16:44', '2025-01-13 20:16:44');
INSERT INTO `tenant` VALUES (5433, 812, 'public/foto_profil_tenant/678512858a868.png', 'Safethings', 'Hariman Juni Arrahman', NULL, NULL, 'JL. Dupak Bangunrejo 3/1, Surabaya', NULL, NULL, NULL, NULL, NULL, 'Safethings adalah bisnis portable first aid kit yang dapat disesuaikan (custom) untuk memenuhi kebutuhan spesifik pelanggan. Produk ini hadir dalam dua varian: versi anti air yang tahan cuaca ekstrem dan mudah digantung, serta versi kain yang ringan dan mudah dibawa. Pelanggan dapat memilih desain, isi, ukuran, dan tambahan lainnya seperti branding atau tema warna, sehingga produk lebih personal dan relevan. Fitur utamanya mencakup kustomisasi penuh, portabilitas, dan isi kit yang lengkap untuk berbagai kebutuhan, mulai dari hiking hingga penggunaan di rumah. Dengan solusi inovatif ini, Safethings memberikan alternatif kit pertolongan pertama yang lebih personal dan praktis, menjadikannya lebih kompetitif di pasar.', NULL, NULL, '2025-01-13 20:17:57', '2025-01-13 20:17:57');
INSERT INTO `tenant` VALUES (5434, 812, 'public/foto_profil_tenant/678512b8c929c.jpg', 'De\'Capra', 'Meirinda Nur Indinasha Faras Maulida', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60154', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Kami dari kelompok 44 Wirausaha Merdeka PBLT 3.0 Politeknik Negeri Banyuwangi 2024 akan menciptakan sebuah ide bisnis yakni produk sabun susu kambing dengan penambahan ecoenzym. Produksi sabun susu akan di produksi setiap 1 bulan 4 kali yakni 75 pcs per produksi dengan berat 70 gr per satu batang sabun susu kambing, dengan begitu kami dapat memasarkan kurang lebih 300 pcs per bulan. Produk ini akan di pasarkan melalui media sosial dan toko terdekat. Produk sabun susu ini memiliki inovasi yang berbeda dengan sabun pada umumnya, serta memiliki desain packaging yang menarik, sehingga diharapkan masyarakat sekitar akan tertarik dengan produk sabun yang kami produksi.</span></p>', NULL, NULL, '2025-01-13 20:18:48', '2025-01-13 20:18:48');
INSERT INTO `tenant` VALUES (5435, 812, 'public/foto_profil_tenant/678513288a6bf.png', 'BESTI K3', 'Senna Malik Ibrahim', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60132', NULL, NULL, NULL, NULL, NULL, '<p>\" Seiring dengan berkembangnya zaman, generasi saat ini mencari cara belajar yang berbeda, lebih dinamis, praktis, dan tentunya interaktif. Seringkali ditemukan bahwa generasi saat ini cenderung merasa jenuh&nbsp;</p><p>dengan format pembelajaran terutama buku yang terkesan kuno atau konvensional.&nbsp;</p><p>Dalam menghadapi tantangan tersebut, BESTI K3 hadir dalam bentuk buku saku inovatif yang mengkreasikan berbagai topik keselamatan dan kesehatan di lingkungan kerja menjadi pengalaman yang informatif dan interaktif. Buku ini dirancang untuk membawa pembaca dalam perjalanan menyenangkan menuju tempat kerja yang lebih aman dan sehat.&nbsp;</p><p>Di dalam buku ini, pembaca tidak hanya akan menemukan teori-teori dasar tentang Keselamatan dan Kesehatan Kerja (K3), tetapi juga berbagai aktivitas menarik yang akan mengajak pembaca berinteraksi dalam&nbsp;</p><p>setiap topik K3. Setiap bab berisi materi yang dilengkapi dengan kuis, video interaktif, ilustrasi berwarna, serta studi kasus yang dirancang untuk meningkatkan keterampilan dan pemahaman pembaca terhadap isu-isu K3.\"</p>', NULL, NULL, '2025-01-13 20:20:40', '2025-01-13 20:20:40');
INSERT INTO `tenant` VALUES (5436, 812, 'public/foto_profil_tenant/67851cb0eefde.png', 'Krisapi Krenyes', 'Shofiana Maulia', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60155', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Krisapi Krenyes (Keripik Daging Sapi) merupakan camilan sehat dan lezat yang<br>terbuat dari daging sapi premium yang diolah menggunakan beragam rempah-rempah<br>terbaik sehingga menghasilkan rasa gurih dan menjadi keripik renyah. Krisapi Krenyes<br>dirancang untuk memberikan pilihan camilan bergizi tinggi, kaya akan protein, dan juga zat<br>besi, yang memiliki manfaat dalam mendukung pertumbuhan dan perkembangan tubuh,<br>terutama bagi anak-anak sebagai upaya pencegahan stunting.</span></p>', NULL, NULL, '2025-01-13 20:21:09', '2025-01-13 21:01:20');
INSERT INTO `tenant` VALUES (5437, 812, 'public/foto_profil_tenant/678513ac05b82.png', 'TwistTime', 'Adetya Hafif Pratama', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60133', NULL, NULL, NULL, NULL, NULL, '<p>\"CV Nuansa Interior merupakan bisnis yang berfokus pada pembuatan desain interior dengan produk baru yaitu  “TWIST TIME” Produk yang unik dan menarik menggunakan pipa sebagai bahan utama. Produk ini dirancang untuk memberikan sentuhan artistik dan industri dalam ruang interior. Kami menciptakan “TWIST TIME”  yang tidak hanya berfungsi sebagai jam pengingt waktu, tetapi juga sebagai elemen dekoratif yang memikat.</p><p>Produk dan Layanan :</p><p>•        Jam pipa : Kami menawarkan berbagai desain jam yang terbuat dari pipa PVC. Jam dapat disesuaikan dengan gaya dan ukuran ruangan pelanggan</p><p>•        Desain  Custom: Selain produk-produk yang telah ada, kami juga menerima pesanan khusus sesuai dengan ide atau desain yang diberikan oleh pelanggan. Ini memungkinkan pelanggan untuk memiliki desain jam yang benar-benar unik.\"</p>', NULL, NULL, '2025-01-13 20:22:52', '2025-01-13 20:22:52');
INSERT INTO `tenant` VALUES (5438, 812, 'public/foto_profil_tenant/6785149f3ac0c.png', 'Gemara', 'Agnes Veronica Sungkono', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60156', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Ide bisnis ini berfokus pada pengembangan buku cerita edukatif untuk anak SD yang mengajarkan tentang sejarah hutan mangrove dan perannya dalam mitigasi bencana banjir. Melalui cerita menarik dan ilustrasi kreatif, buku ini memperkenalkan konsep lingkungan dan bencana alam dengan cara yang mudah dipahami anak-anak. Dilengkapi dengan ilustrasi pop up, buku ini bertujuan untuk meningkatkan kesadaran lingkungan dan menumbuhkan kecintaan terhadap alam sejak usia dini.</span></p>', NULL, NULL, '2025-01-13 20:26:55', '2025-01-13 20:26:55');
INSERT INTO `tenant` VALUES (5439, 812, 'public/foto_profil_tenant/678514a4b7323.jpg', 'Cassava Nation', 'R. A. Norromadani Yuniati', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60117', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Karena melimpahnya bahan baku singkong di Indonesia, khususnya di Jawa Timur, olahan singkong saat ini menjadi salah satu komoditas yang menjanjikan seiring dengan meningkatnya permintaan pasar akan camilan sehat. Cassanavation merupakan bisnis yang bergerak dalam bidang pengolahan singkong, khususnya dalam inovasi produk. Produk kami memanfaatkan semua bagian singkong, mulai dari keripik sebring yang terbuat dari saripati, hingga es krim dari ampas singkong gunanaya untuk mengurangi limbah pangan.</span></p>', NULL, NULL, '2025-01-13 20:27:00', '2025-01-13 20:27:00');
INSERT INTO `tenant` VALUES (5440, 812, 'public/foto_profil_tenant/678514f7a25dc.jpg', 'GMAW Trolley', 'Ikhlas Syarofie', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60118', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Bisnis kami berfokus pada pembuatan produk trolley berkualitas tinggi yang dirancang khusus untuk mesin las GMAW. Trolley ini memberikan solusi praktis untuk memindahkan mesin las secara efisien dan aman di berbagai lingkungan kerja. Dengan desain yang ergonomis dan tahan lama, produk kami bertujuan untuk meningkatkan alur kerja di bengkel dan lokasi konstruksi.</span></p>', NULL, NULL, '2025-01-13 20:28:23', '2025-01-13 20:28:23');
INSERT INTO `tenant` VALUES (5441, 812, 'public/foto_profil_tenant/67851516e25c7.jpg', 'Smart Quail Cage', 'Muhammad Rizky Ramadhani', NULL, NULL, 'Jl. Raya Ngaban 9C RT 1 RW 1, Ngaban, Tanggulangin,\r\nSidoarjo', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Solusi inovatif hadir dengan kandang burung puyuh otomatis berbasis teknologi IoT, yang meliputi sistem otomatis untuk pemberian pakan, pembersihan kotoran, dan pemantauan jarak jauh. Teknologi ini memungkinkan peternak mengelola ternak secara real-time, menghemat biaya operasional, dan meningkatkan produktivitas tanpa pemeliharaan manual intensif. Kandang dirancang dengan sirkulasi udara baik, menjaga kesehatan burung dan kualitas telur. Kandang otomatis ini ideal untuk peternak skala kecil hingga menengah.</span></p>', NULL, NULL, '2025-01-13 20:28:54', '2025-01-13 20:28:54');
INSERT INTO `tenant` VALUES (5442, 812, 'public/foto_profil_tenant/6785157c6292a.png', 'CROPO', 'Deny Wibisono', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60119', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Melihat pengalaman dan keadaan sekitar ketika melakukan kegiatan OJT kami dan tim selalu kesusahan Ketika membawa perlatan uji penetran test apalagi ketika tempat inpeksi berada di daerah yang jauh,tinggi dan berpindah pindah tempat,sehingga kami memiliki solusi yang kami beri nama “CROPO” adalah tas yang diperuntukan untuk seorang yang berprofesi sebagai penguji DT dan NDT maupun sejenis nya,tas ini telah di design sedemikian rupa untuk menampung semua kebutahan alat, terkhususkan Ketika pengujian Penetran Test(PT),karena kami menyediakan slot atau tempat untuk kaleng penetran,cleaner,developer,spidol,kuas dan senter dan untuk slempangnya kami buat ikat perut karena diharapkan bisa memudahkan pengguna dalam mengambil dan meletakan peralatan, di harapkan ini akan sangat bermanfaat bagi para profesional yang membutuhkan kepraktisan dan efisiensi saat bekerja di lapangan</span></p>', NULL, NULL, '2025-01-13 20:30:36', '2025-01-13 20:30:36');
INSERT INTO `tenant` VALUES (5443, 812, 'public/foto_profil_tenant/678515dfe3163.jpg', 'Booth Trailer', 'Rizha Agustian Dwi Susanto', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60120', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Portable Booth adalah solusi inovatif untuk memfasilitasi pameran, event marketing, dan promosi produk di lokasi yang fleksibel dan praktis. Booth ini dirancang untuk mudah dipasang dan dipindahkan, menawarkan kemudahan bagi pengusaha, pemilik brand, atau event organizer untuk memperluas jangkauan mereka tanpa harus berinvestasi dalam infrastruktur permanen. Dengan meningkatnya kebutuhan akan solusi pemasaran yang fleksibel, Portable Booth hadir untuk mengisi celah di pasar dengan menawarkan kualitas tinggi, daya tahan, dan portabilitas yang unggul.</span></p>', NULL, NULL, '2025-01-13 20:32:15', '2025-01-13 20:32:15');
INSERT INTO `tenant` VALUES (5444, 812, 'public/foto_profil_tenant/67851637d7865.jpg', 'Weld Tech', 'Diva Wahyu Pratama', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60121', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Meja pengelasan semua posisi adalah produk inovatif yang dirancang untuk mendukung berbagai jenis pengelasan dalam posisi apa pun—horizontal, vertikal, overhead, dan flat. Produk ini menjawab kebutuhan industri pengelasan yang memerlukan fleksibilitas, presisi, dan efisiensi lebih tinggi, terutama dalam proses pengelasan yang kompleks.</span></p>', NULL, NULL, '2025-01-13 20:33:43', '2025-01-13 20:33:43');
INSERT INTO `tenant` VALUES (5445, 812, 'public/foto_profil_tenant/67851684da344.png', 'Marine Keychain Merchandise', 'Muhammad Amru Annas Habibie', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60122', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Marine Keychain merupakan perusahaan pembuatan dan pemasaran gantungan kunci yang inovatif, didirikan oleh sekelompok mahasiswa K12 pada Wirausaha Merdeka PBLT 3.0. Produk kami berupa gantungan kunci, yang tidak hanya sekedar gantungan kunci biasa, namun dilengkapi dengan fitur AR (Augmented Reality), yang menyuguhkan berbagai fitur informasi yang edukatif tentang kapal dan equipment penunjangnya.<br><br></span></p>', NULL, NULL, '2025-01-13 20:35:00', '2025-01-13 20:35:00');
INSERT INTO `tenant` VALUES (5446, 1178, 'public/foto_profil_tenant/6785ad2749ff2.jpg', 'MAILA', 'Maila', 23, 7, 'Telaga Bidadari Rt.001 Rw.001 Desa Telaga Bidadari \r\nKecamatan Sungai Raya', NULL, '18.960.000,00', 'Offline / Online', 'KalSel - KalTim', 'Manual', '<p>Menyediakan Produk Makanan Khas Kandangan - Banjar. Seperti Dodol, Wajik, Keu Gapit, Kacang dll.</p><p>Sudah memiliki NIB, IPRT, Sertifikat Halal, dan Hak Merek. Memiliki Karyaean sebanyak 11 orang</p>', '2025-01-01', '2026-12-31', '2025-01-14 07:17:43', '2025-01-14 07:17:43');
INSERT INTO `tenant` VALUES (5447, 1178, 'public/foto_profil_tenant/6785afdd3e7ce.jpg', 'Ri,zki Syif@', 'M. Sa\'adudinor', 23, 7, 'Kapuh Darat, Rt. 004, Rw.002 Desa Kapuh Kecamatan \r\nSimpur', NULL, '10.500.000,00', NULL, 'KalSel - KalTeng', 'Manual', '<p>Memiliki Usaha Produksi Kue Satu Sagu Assoy</p><p>Memiliki NIB, IPRT</p><p>Memiliki 6 Karyawan</p>', '2025-01-01', '2026-12-31', '2025-01-14 07:29:17', '2025-01-14 07:29:17');
