INSERT INTO `tenant` VALUES (5449, 973, 'public/foto_profil_tenant/6785c8d6791ee.jpg', 'Rumah kaos lombok', 'Lina aryati', 47, 1, 'Jl. Chairil anwar no 1 cakranegara', NULL, '100.000.000,00', 'WhatsApp, FB', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Pengadan kaos dan bordir</span></p>', NULL, NULL, '2025-01-14 09:15:50', '2025-01-14 09:15:50');
INSERT INTO `tenant` VALUES (5450, 812, 'public/foto_profil_tenant/6785d695a6a2a.JPG', 'GaBy Bag', 'Shaila Insyirah Medina', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60135', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Composter Bag merupakan produk membantu dalam pembuatan kompos</span></p>', NULL, NULL, '2025-01-14 10:14:29', '2025-01-14 10:14:29');
INSERT INTO `tenant` VALUES (5451, 812, 'public/foto_profil_tenant/6785d756b4ff8.png', 'Eco Grow Diapers', 'Mas Shobihatul Inayah', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60136', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Eco Grow Diapers berkomitmen mengubah limbah popok menjadi solusi ramah lingkungan. Popok bekas yang telah melalui proses daur ulang dan sterilisasi diolah menjadi pot tanaman dan media tanam yang kaya nutrisi. Dengan tekstur yang ringan dan kemampuan menahan kelembaban yang baik, media tanam dari limbah popok sangat ideal untuk berbagai jenis tanaman, baik hias maupun sayuran. Inovasi kami menciptakan media tanam dan pot berkualitas tinggi yang berkelanjutan serta mengurangi dampak lingkungan dari limbah popok.</span></p>', NULL, NULL, '2025-01-14 10:17:42', '2025-01-14 10:17:42');
INSERT INTO `tenant` VALUES (5452, 812, 'public/foto_profil_tenant/6785d7bc7b2a8.jpg', 'Cold Air Dehidrator', 'Rio Ferdinan Abdee Purwanto', NULL, NULL, 'Jl. Keputih Gg. II C No.34', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">pembuatan dehidrator untuk mengeringkan buah buahan.tidak seperti dehidrator yang dijual dipasaran dikarenakan dehidrator kami memiliki sistem kerja bellow zero point. dimana buah buahan yang dikeringkan nantinya kadar nutrisinya tidak hilang. dehidrator ini sangat cocok bagi rekan rekan yang bertugas sebagai tni.</span></p>', NULL, NULL, '2025-01-14 10:19:24', '2025-01-14 10:19:24');
INSERT INTO `tenant` VALUES (5453, 812, 'public/foto_profil_tenant/6785d863303be.jpg', 'Skylight', 'Wildan Eka Whisnu Wirawan', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60138', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Sebuah alat yang dimana berfungsi untuk menerangi area dalam rumah tanpa menggunakan listrik sedikitpun. Alat ini menggunakan cahaya matahari sebagai penerangan pada bagian dalam ruangan. Nantinya cahaya matahari tersebut akan di pantulkan didalam tabung yang diperkuat dengan lensa.</span></p>', NULL, NULL, '2025-01-14 10:22:11', '2025-01-14 10:22:11');
INSERT INTO `tenant` VALUES (5454, 812, 'public/foto_profil_tenant/6785d8fcc845a.png', 'Feed me Now!', 'Hosea okta christanta', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60139', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">PT Blue Wave Autotech merupakan perusahaan yang bergerak di sektor teknologi otomatisasi, dengan fokus pada pengembangan produk inovatif untuk pemeliharaan ikan hias. PT Blue Wave Autotech bertujuan untuk memberikan solusi praktis dan inovatif bagi penghobi ikan hias dan industri yang menggunakan akuarium sebagai bagian dari dekorasi.</span></p>', NULL, NULL, '2025-01-14 10:24:44', '2025-01-14 10:24:44');
INSERT INTO `tenant` VALUES (5455, 812, NULL, 'IGOR-Tech', 'Muhammad Ery Deago', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60140', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">GrowFlowTech adalah jenis wirausaha yang berfokus pada penyediaan layanan dan produk alat bantu otomatisasi yang memudahkan dalam merawat tanaman hidroponik secara praktis dan efisien menggunakan teknologi IOT . Kami berusaha memberikan solusi modern bagi siapa saja yang ingin menanam hidroponik,tanpa perlu menghabiskan banyak waktu dan tenaga dalam perawatannya. Dengan memanfaatkan teknologi terbaru, alat bantu otomatis kami memungkinkan para pengguna untuk pemantauan suhu air ,ph, nutrisi serta dapat mencampurkan cairan nutrisi pada sistem hidroponik secara automatis.</span></p>', NULL, NULL, '2025-01-14 10:26:45', '2025-01-14 10:26:45');
INSERT INTO `tenant` VALUES (5456, 812, 'public/foto_profil_tenant/6785d9eb4a6cb.jpg', 'SIMONSET', 'Abdullah Fiqru Siech', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60141', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Bisnis kami bergerak dalam pengembangan dan penerapan teknologi AIS (Automatic Identification System) untuk monitoring aset di sektor maritim. Tujuan utama kami adalah memberikan solusi inovatif yang membantu pelanggan dalam mengelola dan memantau aset kapal secara real-time, sehingga meningkatkan efisiensi operasional dan keamanan.</span></p>', NULL, NULL, '2025-01-14 10:28:43', '2025-01-14 10:28:43');
INSERT INTO `tenant` VALUES (5457, 812, 'public/foto_profil_tenant/6785da27b3ab2.png', 'BCcustom', 'Muhammad Fa\'iz', NULL, NULL, 'Perum Medayu Citra no. I-11, Medokan Ayu, Rungkut, Surabaya', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">BCcustom adalah perusahaan kreatif yang menyediakan solusi lengkap di bidang media digital dan produk custom. Kami menawarkan berbagai layanan seperti Website Development, Video Editing, Photograph, Graphic Design, Event Management, Broadcasting, Digital Course, dan Advertising. Selain itu, kami juga memproduksi produk custom seperti Apparel, Digital Print, Lifestyle merchandise, Stickers, dan Merchandise.</span></p>', NULL, NULL, '2025-01-14 10:29:43', '2025-01-14 10:29:43');
INSERT INTO `tenant` VALUES (5458, 812, 'public/foto_profil_tenant/6785dad97068f.png', 'Cooky Buddy', 'M.Rendra Cahya Putra', NULL, NULL, 'Jl. Gebang lor no.76 Sukolilo, Surabaya', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Cooky Buddy adalah produk inovatif berupa timer pintar yang terintegrasi dengan kompor gas untuk meningkatkan keamanan dan kenyamanan saat memasak. Produk ini memberikan solusi praktis bagi rumah tangga atau usaha kecil untuk mencegah masakan gosong dan mengurangi risiko kebakaran. Permintaan akan produk seperti ini tinggi, mengingat banyaknya kasus kelalaian saat memasak yang bisa berakibat fatal. Dalam tren keamanan rumah dan dapur, produk ini memiliki peluang besar untuk menjangkau konsumen yang peduli dengan keselamatan.</span></p>', NULL, NULL, '2025-01-14 10:32:41', '2025-01-14 10:32:41');
INSERT INTO `tenant` VALUES (5459, 812, 'public/foto_profil_tenant/6785db1ecb090.jpg', 'Samudra Marketing', 'Larasati Senollueni', NULL, NULL, 'Jl. Teknik Kimia, Keputih, Sukolilo, Surabaya, Sukolilo, Surabaya, Jawa Timur, 60146', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">“SAMUDRA MARKETING” merupakan pelayaran inovatif di lautan pemasaran, siap membantu bisnis<br>anda menemukan arah yang tepat menuju kesuksesan. Seperti kapal yang melintasi ombak, kami<br>menggabungkan kreativitas dan strategi untuk menjadikan setiap produk bersinar di pasar yang penuh<br>tantangan. Kami berkomitmen untuk memberikan solusi pemasaran yang inovatif, berbasis data, dan<br>terintegrasi, yang tidak hanya meningkatkan penjualan tetapi juga membangun hubungan yang kuat<br>antara klien dan konsumen mereka.</span></p>', NULL, NULL, '2025-01-14 10:33:50', '2025-01-14 10:33:50');
INSERT INTO `tenant` VALUES (5460, 812, 'public/foto_profil_tenant/6785db5b3c9b4.jpg', 'Custombot', 'Syahrul Febriansah', NULL, NULL, 'Jl. Sukolilo Makmur III No.22, Keputih, Kec. Sukolilo, Surabaya, Jawa Timur 60111', NULL, NULL, NULL, NULL, NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 11pt; font-family: Calibri, Arial;\">Custombot merupakan usaha di bidang jasa dan fabrikasi robotika untuk semua kalangan</span></p>', NULL, NULL, '2025-01-14 10:34:51', '2025-01-14 10:34:51');
INSERT INTO `tenant` VALUES (5461, 1178, 'public/foto_profil_tenant/678606d85870c.jpg', 'MADANI', 'Halidin Nor', 23, 7, 'Jl. Kapuh Darat, Rt.004, Rw.002 Desa Kapuh Kecamatan \r\nSimpur', NULL, '32.000.000,00', 'Offline / Online', 'KalSel - KalTim', 'Manual', '<p class=\"MsoBodyText\" style=\"margin-top:.4pt;margin-right:15.0pt;margin-bottom:\r\n0in;margin-left:6.7pt;margin-bottom:.0001pt;text-indent:15.8pt\"><span lang=\"id\">Usaha ini fokus pada produk Rimpi\r\nPisangRimpi pisang adalah&nbsp;makanan khas Kalimantan yang terbuat dari buah\r\npisang yang dijemur atau diasapi untuk mengurangi kadar airnya.</span></p><p class=\"MsoBodyText\" style=\"margin-top:.4pt;margin-right:15.0pt;margin-bottom:\r\n0in;margin-left:6.7pt;margin-bottom:.0001pt;text-indent:15.8pt\"><span lang=\"id\">&nbsp;Proses\r\npengeringan ini membuat rimpi awet dan dapat disimpan hingga setahun.</span></p><p class=\"MsoBodyText\" style=\"margin-top:.4pt;margin-right:15.0pt;margin-bottom:\r\n0in;margin-left:6.7pt;margin-bottom:.0001pt;text-indent:15.8pt\"><span lang=\"id\">Sudah Memiliki&nbsp; NIB, IPRT, Sertifikat Halal</span></p><p class=\"MsoBodyText\" style=\"margin-top:.4pt;margin-right:15.0pt;margin-bottom:\r\n0in;margin-left:6.7pt;margin-bottom:.0001pt;text-indent:15.8pt\"><span lang=\"id\">Memiliki 11 karyawan</span><o:p></o:p></p>', '2025-01-01', '2026-12-31', '2025-01-14 13:40:24', '2025-01-14 13:40:24');
INSERT INTO `tenant` VALUES (5462, 1178, 'public/foto_profil_tenant/678609b4557c2.jpg', 'AL – KANDAJANI', 'Suhaimi', 23, 7, 'Kapuh, Rt. 004 Rw. 002 Desa Kapuh Kecamatan Simpur', NULL, '24.000.000,00', 'Offline / Online', 'KalSel - KalTeng', 'Manual', '<p>Al-Kandajani merupakan usaha dalam produksi kuliner khas lokal banjar, seperti keu cantik manis, kue ilat sapi, dan wadai galang</p><p>Secara legalitas sudah memiliki NIB, IPRT, Sertifikat Halal dengan memiliki 10 karyawan</p>', '2025-01-01', '2026-12-31', '2025-01-14 13:52:36', '2025-01-14 13:52:36');
INSERT INTO `tenant` VALUES (5463, 1178, 'public/foto_profil_tenant/67860d21cd2f4.png', 'AHYAT', 'Lindawati', 23, 7, 'Simpur Wasah Tengah, RT 004 RW 2 Desa Wasah Tengah, Kecamatan Simpur', NULL, '18.000.000,00', 'Offline / Online', 'Dalam Provinsi', NULL, '<p>AHYAT merupakan merek usaha yang memprodukasi makanan ringan seperti&nbsp; Kue Stik Bawang dan Keripik Singkong</p><p>Sudah memiliki NIB, IPRT, Sertifikat Halal, Hak Merek dengan jumlah karyawan 5 orang</p>', '2025-01-01', '2026-12-31', '2025-01-14 14:07:13', '2025-01-14 14:07:13');
INSERT INTO `tenant` VALUES (5464, 1178, 'public/foto_profil_tenant/678610f95b102.jpg', 'KIKY', 'Zakaria', 23, 7, 'Kapuh, Rt. 002 Rw. 001 Desa Kapuh Kecamatan Simpur', NULL, '45.000.000,00', 'Offline / Online', 'Dalam Provinsi', 'Manual', '<p>KIKY merek usaha yang khusus memproduksi jenis roti : rori bakar, burger, roti isi coklat, roti manis, roti hambar, roti pizza mini,&nbsp;</p><p>Memiliki NIB, IPRT, dan sertifikat Halal</p><p>Memiliki 9 karyawan</p>', '2025-01-01', '2026-12-31', '2025-01-14 14:23:37', '2025-01-14 14:23:37');
INSERT INTO `tenant` VALUES (5465, 973, 'public/foto_profil_tenant/6787000edc441.jpg', 'UD COMTARESH BERKAH', 'MUH. NAWA KONTARESA', 23, 7, 'Jl. RAYA KEKERI 08 GEGUTU REBAN, DASAN GERIA, LINGSAR, LOMBOK BARAT. NTB', NULL, '200.000.000,00', 'Facebook , instagram', 'Nasional', NULL, '<p><br></p><p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\"> USAHA KOPI BUBUK DENGAN MERK ASYRAF COFFEE</span></p>', NULL, NULL, '2025-01-15 07:23:42', '2025-01-15 07:23:42');
INSERT INTO `tenant` VALUES (5466, 1178, 'public/foto_profil_tenant/67870f5227cb6.jpg', 'Roti Zahra', 'Muhammad Hanafi Azmi', 23, 7, 'Jl. Ps. Ahad, Kapuh, Kec. Simpur, Kabupaten Hulu Sungai Selatan, Kalimantan Selatan 71261', NULL, '30.000.000,00', 'Offline / Online', 'Dalam Provinsi', 'Manual', '<p>Roti</p>', '2025-01-01', '2026-12-31', '2025-01-15 08:28:50', '2025-01-15 08:28:50');
INSERT INTO `tenant` VALUES (5467, 1178, 'public/foto_profil_tenant/67871b1b30f87.jpg', 'RAIHANAH', 'Hilmiah', 23, 7, 'Jl Kacapuri Desa Telaga Bidadari Kecamatan Sungai Raya', NULL, '50.000.000,00', 'Offline / Online', 'KalSel - KalTim - Kalteng', 'Manual', '<p>Usaha yang melakukan produksi makanan ringan, seperti keripik singkong, kacang telor, kue bawang, kacang hijau</p><p>Sudah memiliki NIB, IPRT, Sertifikat Halal, dan memiliki 36 karyawan</p>', '2025-01-01', '2026-12-31', '2025-01-15 09:19:07', '2025-01-15 09:19:07');
INSERT INTO `tenant` VALUES (5468, 1178, 'public/foto_profil_tenant/6787208fc168c.jpg', 'Dodol Asli Madu Kasirat Raisa', 'Raisa Halwa Rizqina - Rusimah', 23, 7, 'Jalan Kahup Madani.  Desa Telaga Bidadari, Kecamatan Sungai Raya', NULL, '20.000.000,00', 'Offline / Online', 'KalSel - KalTim - Kalteng', 'Manual', '<p>Usaha ini memproduksi Makanan Olahan Khas Kandangan, seperti Dodol, Wajik, Kasirat dll</p><p>Sudah memiliki NIB, IPRT, Sertifikat Halal, dan Hak Merek</p><p>Memiliki karyawan 6 orang</p>', '2025-01-01', '2026-12-31', '2025-01-15 09:42:23', '2025-01-15 09:42:23');
INSERT INTO `tenant` VALUES (5469, 1178, 'public/foto_profil_tenant/678726d8c1c7f.jpg', 'Nabila', 'M. Noor - Rahma', 23, 7, 'Desa Telaga Bidadari, Kec. Sungai Raya', NULL, '25.000.000,00', 'Offline / Online', 'Dalam Provinsi', 'Manual', '<p>Usaha ini memproduksi Dodol Kandangan dan Aneka Kerupuk</p><p>Sudah memiliki NIB, IPRT, dan Sertifikat Halal</p><p>Memiliki 10 karyawan</p>', '2025-01-01', '2026-12-31', '2025-01-15 10:09:12', '2025-01-15 10:09:12');
INSERT INTO `tenant` VALUES (5470, 1178, 'public/foto_profil_tenant/67875c637a774.jpg', 'Kerupuk Bawang Akbar', 'Muhammad  Fadeli - Muhammad Ali Akbar', 23, 7, 'Jalan Kapuh Darat, Desa Kapuh, Kec. Simpur', NULL, '47.500.000,00', 'Offline / Online', 'KalSel - KalTeng', 'Manual', '<p>Kerupuk Bawang Akbar memiliki beberapa varian rasa, seperti rasa original, rasa balado dan daun limau purut</p><p>Usaha ini sidah memiliki NIB, IPRT, dan Sertifikat Halal</p><p>Dengan Jumlah Karyawan sebanyak 15 ornag</p>', '2025-01-01', '2026-12-31', '2025-01-15 13:57:39', '2025-01-15 13:57:39');
INSERT INTO `tenant` VALUES (5471, 973, 'public/foto_profil_tenant/678dc34502dd7.jpeg', 'SoBaNaNa', 'Herdiana', 23, 7, 'Desa Bonder Kec.Praya Barat Kab.Lombok Tengah-NTB', NULL, '1.000.000,00', 'Facebook , instagram , WhatsApp', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Pengolahan Pisang merupakan ide yang dilatarbelakangi oleh hasil riset yang dituangkan dalm usaha. Legalitas usaha sudah ada. </span></p>', NULL, NULL, '2025-01-20 10:25:35', '2025-01-20 10:30:13');
INSERT INTO `tenant` VALUES (5472, 973, 'public/foto_profil_tenant/678dd12283fd9.png', 'Teras Ita', 'Baiq Diah Fitasari', 23, 7, 'Jl. Cepung No. 5 Kr. Sukun Mataram, Lombok, NTB', NULL, '75.000.000,00', 'WhatsApp', 'Lokal', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Menjual makanan dan minuman dengan mempertimbangkan pasar lokal</span></p>', NULL, NULL, '2025-01-20 11:29:22', '2025-01-20 11:29:22');
INSERT INTO `tenant` VALUES (5473, 973, 'public/foto_profil_tenant/678dd1d68ec76.jpeg', 'Premijaje', 'Baiq Santi Rengganis', 23, 7, 'Griya Pesona Alam Blok GL No 28', NULL, '50.000.000,00', 'Instagram , Tik Tok', 'Nasional', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Premijaje berdiri pada tahun 2021 tepat pada bulan November, bamun sebelum itu sudah diawali dengan “percobaan” menjual makanan. Seiring dengan berjalannya waktu premijaje fokus mengembangkan roti sehat atay yang leboh dikenal dengan metode “sourdough”. Selain roti-roti sourdough (artisan bread) premijaje juga mengembangkan pastry seperti croissant, dll. Premijaje juga memiliki bagian “sncak box” untuk menjawab konsumen yang menginginkan jajan kotak baik dalam partai kecil dan besar. </span></p>', NULL, NULL, '2025-01-20 11:32:22', '2025-01-20 11:32:22');
INSERT INTO `tenant` VALUES (5474, 973, 'public/foto_profil_tenant/678ddab61cea2.jpg', 'Ratu Daluman', 'Fathurrahman', 23, 7, 'Jl.Gotong Royong No.262B Dasan Sari Kebun Sari Ampenan', NULL, '20.000.000,00', 'Mulut Ke Mulut', 'provinsi', NULL, '<p><span style=\"color: rgb(32, 33, 36); font-family: Roboto, Arial, sans-serif; letter-spacing: 0.2px; white-space-collapse: preserve;\">Menyediakan aneka makanan dan minuman,cri khas minuman daluman/cincau hijau</span></p>', NULL, NULL, '2025-01-20 12:10:14', '2025-01-20 12:10:14');
