INSERT INTO `tenant` VALUES (5492, 547, 'public/foto_profil_tenant/679998602e795.jpg', 'MbakBross', 'Istiani Masrukhah', 23, 7, 'Jl kertanegara RT 003 RW 010 Tumpang', NULL, '7.000.000,00', 'Campuran', 'Kabupaten', 'Manual', '<p><span id=\"docs-internal-guid-88ab0fc6-7fff-f118-c85c-eb579ff727cc\"><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">Mbak Bross adalah sebuah usaha yang bergerak di bidang produksi makanan, khususnya makanan ringan, seperti kue kering.</span></span></p>', '2024-11-01', '2025-01-30', '2025-01-29 09:54:24', '2025-01-29 10:02:20');
INSERT INTO `tenant` VALUES (5493, 547, 'public/foto_profil_tenant/679999ba095f6.jpg', 'Jamu Instans', 'Emi Yulia S', 23, 7, 'Jln meratifikasi no.43 RT 4 RW 8 dsn.kendalsari,DS.ngijo', NULL, '2.000.000,00', 'Offline', 'Kabupaten', 'Manual', '<p><span id=\"docs-internal-guid-8a830a19-7fff-3f05-a714-e46b1c24b061\"></span></p><p dir=\"ltr\" style=\"line-height:1.7999999999999998;text-align: justify;margin-top:12pt;margin-bottom:0pt;\"><span style=\"font-size:12pt;font-family:\'Times New Roman\',serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Usaha jamu instan adalah bisnis yang bergerak di bidang produksi dan penjualan minuman herbal tradisional dalam bentuk bubuk atau granul yang mudah larut dalam air. Produk ini bertujuan untuk memberikan kemudahan bagi konsumen yang ingin menikmati manfaat jamu tanpa perlu repot meracik atau merebus bahan-bahan alami secara manual.</span></p>', '2024-11-01', '2025-01-30', '2025-01-29 10:00:10', '2025-01-29 10:00:10');
INSERT INTO `tenant` VALUES (5494, 547, 'public/foto_profil_tenant/6799a5a135516.jpg', 'Dapur Cuan Cuin', 'Mega Sofiana', 23, 7, 'Mangliawan Permai A22, Kab. Malang', NULL, '500.000,00', 'Offline', 'Kabupaten', 'Manual', '<p class=\"selectable-text\" style=\"margin-left:180.0pt;text-align:justify;\r\ntext-indent:-180.0pt\">Dapur Cuan Cuin adalah usaha di bidang kuliner yang\r\nmenawarkan aneka makanan lezat dengan cita rasa khas. Berlokasi di Mangliawan\r\nPermai A22, Kabupaten Malang, usaha ini dimiliki oleh Mega Sofiana yang\r\nberkomitmen menghadirkan produk kuliner berkualitas untuk memenuhi kebutuhan\r\npasar lokal. Mengandalkan pemasaran offline dan promosi melalui Facebook, Dapur\r\nCuan Cuin mampu menjangkau pelanggan di sekitar Kabupaten Malang. Dengan metode\r\npengelolaan usaha yang sederhana dan pembukuan manual, bisnis ini menunjukkan potensi\r\nuntuk terus berkembang dan menjadi pilihan utama dalam industri kuliner di\r\nwilayahnya. Usaha ini telah memiliki Nomor Induk Berusaha (NIB) sebagai bentuk\r\nlegalitas dan profesionalitasnya.<o:p></o:p></p>', '2024-11-01', '2025-01-30', '2025-01-29 10:50:57', '2025-01-29 10:50:57');
INSERT INTO `tenant` VALUES (5495, 547, 'public/foto_profil_tenant/6799a6abefed7.jpg', 'Kedai Sobat', 'Tantri Lutfia Sari', 23, 7, 'Jl. Kartini RT. 09 RW. 06 Jeru Tumpang, Malang, Jawatimur', NULL, '10.000.000,00', 'Whatsapp, Facebook', 'Kabupaten', 'Exel', '<p class=\"selectable-text\" style=\"margin-left:180.0pt;text-align:justify;\r\ntext-indent:-180.0pt\">Kedai Sobat adalah usaha kuliner yang berfokus pada\r\npenyediaan makanan lezat dengan kualitas terbaik untuk pelanggan di wilayah\r\nKabupaten Malang. Didirikan oleh Tantri Lutfia Sari, Kedai Sobat berlokasi di\r\nJl. Kartini RT. 09 RW. 06 Jeru Tumpang, Malang, Jawa Timur. Dengan omzet\r\nbulanan mencapai Rp10.000.000, Kedai Sobat membuktikan diri sebagai pilihan\r\nkuliner yang diminati. Menggunakan metode pemasaran campuran dan memanfaatkan\r\nplatform seperti WhatsApp dan Facebook, Kedai Sobat menjangkau berbagai\r\nkalangan pelanggan. Usaha ini juga telah memiliki Nomor Induk Berusaha (NIB)\r\ndan sertifikasi halal, menjamin kepercayaan dan kenyamanan konsumen. Dengan\r\npembukuan yang terorganisir melalui Excel, Kedai Sobat terus mengembangkan\r\ninovasi kuliner dan layanan yang ramah untuk memenuhi kebutuhan pasar lokal.<span class=\"selectable-text1\"><o:p></o:p></span></p>', '2024-11-01', '2025-01-30', '2025-01-29 10:55:23', '2025-01-29 10:55:23');
INSERT INTO `tenant` VALUES (5496, 547, 'public/foto_profil_tenant/6799a7332a730.jpg', 'Cahayaku', 'Widyawati', 23, 7, 'Jl. Ronggowuni RT. 18 RW. 07 Tumpang, Malang, Jawatimur', NULL, '5.000.000,00', 'Whatsapp, Facebook', 'Kabupaten', 'Manual', '<p class=\"selectable-text\" style=\"margin-left:180.0pt;text-align:justify;\r\ntext-indent:-180.0pt\">Cahayaku adalah usaha di bidang kuliner yang berfokus\r\npada produksi dan penjualan minuman berkualitas dengan rasa yang menggugah\r\nselera. Dimiliki oleh Widyawati, usaha ini berlokasi di Jl. Ronggowuni RT. 18\r\nRW. 07 Tumpang, Malang, Jawa Timur, dan berhasil meraih omzet bulanan hingga\r\nRp5.000.000. Dengan metode pemasaran campuran yang memanfaatkan platform\r\ndigital seperti WhatsApp dan Facebook, Cahayaku menjangkau pelanggan di wilayah\r\nKabupaten Malang. Legalitas usaha ini telah terjamin dengan kepemilikan Nomor Induk\r\nBerusaha (NIB) dan sertifikasi halal, memberikan rasa aman dan nyaman bagi\r\nkonsumen. Melalui pembukuan yang terorganisir menggunakan Excel, Cahayaku terus\r\nberkembang menjadi pilihan utama dalam industri minuman lokal.<o:p></o:p></p>', '2024-11-01', '2025-01-30', '2025-01-29 10:57:39', '2025-01-29 10:57:39');
