INSERT INTO `tenant` VALUES (5643, 15, 'public/foto_profil_tenant/67ce479aba382.jpg', 'SIABDes', 'Koenta Adji Koerniawan', 49, 6, 'Bandung Techno Park (BTP), Jalan Telekomunikasi, Sukapura, Kec.Dayeuhkolot, Kabupaten Bandung, Jawa Barat 40257)', NULL, NULL, 'Website dan Sosial Media', 'Pemerintahan Desa', NULL, '<p>SIABDES 2023 is a platform for providing recording services and preparation of financial reports based on EMKM SAK (Financial Accounting Standards) standards, which can be used primarily for BUMDes and BUMDesma entities, but can also be used for Micro, Small and Medium entities, whose business types are Services and or Trade, with all kinds of business entities.</p>', '2023-10-10', '2024-11-26', '2025-03-10 08:59:54', '2025-03-10 09:32:12');
INSERT INTO `tenant` VALUES (5644, 15, 'public/foto_profil_tenant/67ce48638c08f.png', 'Link Productive', 'Gerry Anugrah Dwiputra', 46, 9, 'Ruko BBS, Jl. Bukit Baja Sejahtera No.9 Blok B3, Ciwaduk, Kec. Cilegon, Kota Cilegon, Banten 42415', NULL, NULL, 'Website dan Sosial Media', 'Mahasiswa, pelajar, pencari kerja, sekolah, universitas, perusahaan, UMKM.', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Paltform Digital untuk menciptakan Ekosistem Digital Terintegrasi untuk dapat mempertemukan mahasiswa, siswa, pencari kerja, sekolah, universitas, perusahaan, UMKM, dan pemerintah agar dapat meningkatkan produktivitas yang berwawasan hijau dari masing-masing stakeholder sehingga mampu mengurangi sampah plastik, dan daur ulang sampah, meningkatkan kualitas pendidikan SMK &amp; Universitas, mengurangi angka pengangguran, meningkatkan UMKM Naik Kelas, meningkatkan kualitas pariwisata dan meningkatkan jumlah lapangan pekerjaan, serta mencapai Green Economy.</span></p>', '2023-10-10', '2024-11-26', '2025-03-10 09:03:15', '2025-03-10 09:33:05');
INSERT INTO `tenant` VALUES (5645, 15, 'public/foto_profil_tenant/67ce494327bb5.png', 'Aglees', 'Muhammad Aziz', 46, 9, 'Jalan Nagrog, Ciporeat, Pasanggrahan, Ujung Berung, Bandung, Jawa Barat.', NULL, NULL, 'Sosial Media', 'Mahasiswa dan Pelajar', NULL, '<p>Aglees is a company engaged in the marketplace of freelancer and outsourcing services. Aglees\' business model has two users. The first user is a freelancer partner or agency. The second user is the customer or end user. The products offered by Aglees include digital service products such as design, animation, digital marketing, videography and many others.</p>', '2023-10-10', '2024-11-26', '2025-03-10 09:06:59', '2025-03-10 09:31:53');
INSERT INTO `tenant` VALUES (5647, 15, 'public/foto_profil_tenant/67ce4b32154ad.png', 'PesenKuy Indonesia', 'Kevin Ahessa', 39, 6, 'Bandung, Jawa Barat', NULL, NULL, 'Website', 'Mahasiswa', NULL, '<p>PesenKuy Indonesia merupakan platform layanan pesan antar kebutuhan sehari-hari mahasiswa di Kampus Telkom University dan kampus lainnya di Indonesia dengan fitur penjadwalan. Pelanggan dapat memesan produk seperti galon, beras, laundry, paket makan bulanan, dll hanya dengan 1 website. Pelanggan juga dapat langsung checkout di website PesenKuy.</p>', '2023-10-10', '2024-11-26', '2025-03-10 09:15:14', '2025-03-10 09:33:33');
INSERT INTO `tenant` VALUES (5648, 15, 'public/foto_profil_tenant/67ce4cc315839.png', 'Sovware Data Mandiri', 'Sriyanto', 22, 6, 'Bandung, Jawa Barat', NULL, NULL, 'Website', 'Perusahaan dan Industri', NULL, '<p><span data-sheets-root=\"1\" style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Arial;\">Edge Computing Solution for Data Collection, Data Flow and Data Integration</span></p>', '2023-10-10', '2024-11-26', '2025-03-10 09:21:55', '2025-03-10 09:34:44');
INSERT INTO `tenant` VALUES (5649, 15, 'public/foto_profil_tenant/67ce5034bdc2a.png', 'The Court', 'Alief Devara Naufal', 43, 6, 'Bandung, Jawa Barat', NULL, NULL, 'Sosial Media', 'Club Bola, Penggemar SepakBola', NULL, '<div><font face=\"Arial\"><span style=\"font-size: 13.3333px;\">The Court served as a Competition Management System and Sports-Focused social media. We redefine sports through AI-driven data collection for sports match and visualize it as interactive user experience so the fans, athletes, clubs, and competition can connect together as an ecosystem.</span></font></div>', '2024-08-23', '2024-11-26', '2025-03-10 09:31:23', '2025-03-10 09:36:36');
INSERT INTO `tenant` VALUES (5650, 1228, 'public/foto_profil_tenant/67d243f692d10.jpg', 'Kiko Editing', 'Sabira Aulia', 47, 6, 'Jalan Pepaya Raya IV Rt.005/03 No.44H Jagakarsa Jakarta Selatan 12620', NULL, '7.000,00', 'Instagram @kikoediting', 'Nasional', 'Digital', '<p><span style=\"font-size:11.0pt;line-height:107%;\r\nfont-family:&quot;Calibri&quot;,sans-serif;mso-ascii-theme-font:minor-latin;mso-fareast-font-family:\r\nCalibri;mso-fareast-theme-font:minor-latin;mso-hansi-theme-font:minor-latin;\r\nmso-bidi-font-family:&quot;Times New Roman&quot;;mso-bidi-theme-font:minor-bidi;\r\nmso-ansi-language:EN-ID;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">Kiko\r\nEditing adalah layanan desain grafis yang menawarkan solusi kreatif dalam\r\npembuatan desain digital dan editing visual. Tidak hanya berorientasi pada\r\nkeuntungan, usaha ini juga berkontribusi dalam membantu UMKM, startup, dan\r\nindividu dalam membangun branding yang kuat melalui desain berkualitas tinggi.</span></p>', '2021-01-01', '2025-01-01', '2025-03-13 09:33:26', '2025-03-13 09:33:26');
INSERT INTO `tenant` VALUES (5651, 1228, 'public/foto_profil_tenant/67d24c2b4413b.jpeg', 'PaperCycle', 'Zulfaa Zaahiyah Putri Riadi', 16, 2, 'Jalan cahaya titis Tanah Baru, Beji Depok 16426', NULL, '500.000,00', 'Whatsapp: 08128061491 Instagram: @papercycle_57 TikTok: @papercycle_57', 'Mahasiswa', 'Modal awal 500.000', '<div>Di era modern, penggunaan kertas masih sangat tinggi, baik untuk keperluan pendidikan, bisnis, maupun industri. Namun, limbah kertas menjadi salah satu penyumbang terbesar sampah global, dengan jutaan ton kertas terbuang setiap tahunnya. Selain itu, sebagian besar kertas mudah rusak jika terkena air, sehingga penggunaannya menjadi terbatas.</div><div>Di sisi lain, tren produk ramah lingkungan dan berkelanjutan semakin diminati, terutama oleh bisnis yang ingin mengurangi dampak lingkungan. Karena itu, diperlukan inovasi kertas anti air berbahan daur ulang yang tidak hanya mengurangi limbah, tetapi juga memiliki nilai tambah dalam penggunaannya.</div><div>Ecopap hadir sebagai solusi inovatif, menciptakan kertas tahan air dari bahan daur ulang yang dapat digunakan untuk berbagai kebutuhan seperti notebook, kemasan, dan label tanaman. Dengan pendekatan ini, Ecopap tidak hanya membantu mengurangi limbah kertas, tetapi juga mendukung gerakan keberlanjutan dan ekonomi sirkular.</div><div>Kriteria ini menilai tujuan mulia dari didirikannya suatu usaha. Pendirian usaha tidak hanya fokus untuk mendapatkan keuntungan namun juga memberikan dampak bagi masyarakat dan lingkungan.</div>', '2025-01-01', '2025-01-01', '2025-03-13 10:08:27', '2025-03-13 11:46:20');
INSERT INTO `tenant` VALUES (5652, 1228, 'public/foto_profil_tenant/67d25ac13b6eb.jpg', 'FH Buket', 'Muhammad Fauzan Humam Rofiq', 47, 1, 'Jl. Srengseng Sawah Gg. Sarjana Rt. 001 Rw. 009 No. 17 C Srengseng Sawah Jagakarsa Jakarta Selatan 12640', NULL, '3.000.000,00', 'Whatsapp, Instagram: @Fh.buket', 'Area Jakarta Selatan dan Depok', 'Harian dan Bulanan', 'FH BUKET dengan bangga menawarkan berbagai macam buket hadiah / kado untuk para customer yang ingin memberikan hadiah / kado kepada orang-orang terdekat atau orang yang menurutnya penting dihari tertentu atau dihari spesialnya.&nbsp; Buket dari kami juga menghadirkan kesenangan, kebahagiaan, serta dapat dinikmati, dan memastikan pengalaman yang berkesan dan memuaskan bagi anda dan orang yang diberikan buket.', '2023-05-25', '2025-01-01', '2025-03-13 11:10:41', '2025-03-13 11:46:56');
INSERT INTO `tenant` VALUES (5653, 1228, 'public/foto_profil_tenant/67d260a8d3ca9.jpg', 'Seserahan.byfloriztt', 'Titiva Afri Rizkiani', 47, 1, 'Jalan Tifa Raya 1 No 320A Abadijaya Sukmajaya Depok 16411', NULL, '3.500.000,00', 'Whatsapp: 087878034816, Instagram: @seserahan.byfloriztt', 'Online platform media social', 'Laporan', 'Seserahan by Florizt didirikan bukan hanya untuk meraih keuntungan finansial, tetapi juga untuk memberikan kontribusi nyata bagi masyarakat dan lingkungan. Kami percaya bahwa bisnis yang berkelanjutan adalah bisnis yang memberikan dampak positif bagi semua pihak. Kami membantu setiap pasangan untuk mewujudkan impian pernikahan mereka dengan sentuhanpersonal dan kreatif untuk pasangan yang tidak memiliki biaya besar dan boleh membayar setelah acara dilakukan. Melalui penciptaan momen-momen bahagia yang berkesan bagi setiap pasangan', '2016-01-01', '2025-01-01', '2025-03-13 11:35:52', '2025-03-13 11:47:21');
INSERT INTO `tenant` VALUES (5654, 134, 'public/foto_profil_tenant/67d39d9be603a.jpg', 'Zaneva Official Shop', 'Rizki', 19, 1, 'JL. RAYA CIBABAT Gg, Gg. Karya Bhakti VIII No.175, Cigugur Tengah, Kota Cimahi, Jawa Barat 40522', NULL, NULL, 'instagram, Facebook', NULL, NULL, '<p><span style=\"color: rgb(71, 71, 71); font-family: Arial, sans-serif;\">Zaneva Hijab Indonesia adalah Brand Hijab yang telah dipercaya lebih dari 100.000 Muslimah di Indonesia Menyediakan : Hijab Motif BRANDED Jahit Tepi Hijab Motif BRANDED lasercut Hijab Basic Voal Zaskia Series &amp; Rachelia</span></p>', '2025-02-11', '2025-02-20', '2025-03-14 10:07:36', '2025-03-14 10:09:46');
INSERT INTO `tenant` VALUES (5655, 134, 'public/foto_profil_tenant/67d39e5e0ae96.jpeg', 'Kawan Muslim Official Shop', 'Hasan', 19, 1, 'Perum dobokuligar, Jl. Infantri No.11 Blok D 7Jl, Pataruman, Kec. Pataruman, Kota Banjar, Jawa Barat 46323', NULL, '500.000.000,00', 'Shoope, Instagram, Tokopedia, Blibli', 'Dalam dan Luar Negeri', 'Aplikasi', 'Fashion muslim pria dewasa dan anak-anak yang mengedepankan kualitas dan juga desain yang cocok dalam kegiatan religius maupun aktifitas lainnya. Produk yang dihasilkan baju koko anak, jubah gamis anak laki-laki, jubah pria arab, peci bordir, dan celana sirwal<h2 class=\"qrShPb pXs6bb PZPZlf q8U8x aTI8gc hNKfZe\" data-dtype=\"d3ifr\" data-local-attribute=\"d3bn\" data-attrid=\"title\" data-ved=\"2ahUKEwjW0tT1yYiMAxUEoWMGHdDlEb8Q3B0oAHoECEQQAQ\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 24px; line-height: 1.34; margin-bottom: 0px; color: rgb(31, 31, 31);\"><br></h2>', '2025-02-11', '2025-02-20', '2025-03-14 10:11:26', '2025-03-14 10:11:26');
INSERT INTO `tenant` VALUES (5656, 134, 'public/foto_profil_tenant/67d3a1fb19b14.jpg', 'AUM APPAREL', 'Putu', 19, 1, 'Jl. Raya Pengosekan, Ubud, Bali', NULL, NULL, 'instagram', NULL, NULL, '<p class=\"MsoNormal\" style=\"margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n27.0pt;tab-stops:45.8pt 91.6pt 137.4pt 183.2pt 229.0pt 274.8pt 320.6pt 366.4pt 412.2pt 458.0pt 503.8pt 549.6pt 595.4pt 641.2pt 687.0pt 732.8pt;\r\nbackground:#F8F9FA\"><span lang=\"IN\" style=\"mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-bidi-font-family:Calibri;mso-bidi-theme-font:minor-latin;color:#1F1F1F;\r\nmso-ansi-language:IN\">AUM APPAREL adalah merek pakaian olahraga yang berbasis\r\ndi Bali, Indonesia, yang didirikan pada tahun 2016. AUM didirikan atas dasar\r\nkecintaan terhadap yoga. AUM mendesain berbagai kombinasi warna dan motif\r\npakaian olahraga yang memungkinkan pelanggan mengekspresikan diri mereka dengan\r\nbebas.</span><span lang=\"IN\" style=\"mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-bidi-font-family:Calibri;mso-bidi-theme-font:minor-latin;color:#1F1F1F\"> </span><span style=\"mso-fareast-font-family:&quot;Times New Roman&quot;;mso-bidi-font-family:Calibri;\r\nmso-bidi-theme-font:minor-latin;color:#1F1F1F\">Aum</span><span lang=\"IN\" style=\"mso-fareast-font-family:&quot;Times New Roman&quot;;mso-bidi-font-family:Calibri;\r\nmso-bidi-theme-font:minor-latin;color:#1F1F1F;mso-ansi-language:IN\">\r\nmenyediakan tiga kategori produk yang berbeda: atasan, bra olahraga, dan\r\nbawahan. Atasan pendek, kemeja lengan panjang, kemeja tanpa lengan, kaus\r\noblong, dan jaket termasuk dalam kategori teratas. Legging, celana pendek\r\nsepeda, dan celana pendek termasuk dalam kategori bawahan.<o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoNormal\"><o:p>&nbsp;</o:p></p>', '2025-02-11', '2025-02-20', '2025-03-14 10:26:51', '2025-03-14 10:26:51');
INSERT INTO `tenant` VALUES (5657, 134, 'public/foto_profil_tenant/67d3a3613407c.jpg', 'Jilbab Shafi Warehouse', 'Muslih Anggit Cahyo Hidayat', 19, 1, 'Jl. Solo - Purwodadi Jl. Godegan - Kragilan No.Km 18, RT.1/RW.1, Kabayanan I, Kragilan, Kec. Gemolong, Kabupaten Sragen, Jawa Tengah 57274', NULL, '2.000.000.000,00', 'Shoope, Instagram, Facebook, Lazada, Pinterest', 'Dalam dan Luar Negeri', 'Aplikasi', '<p><span style=\"color: rgb(71, 71, 71); font-family: Arial, sans-serif;\">Jilbab Shafi menjual berbagai macam model gamis, koko, jilbab, khimar, masker, dan mukena</span></p>', '2025-02-11', '2025-02-20', '2025-03-14 10:32:49', '2025-03-14 10:32:49');
INSERT INTO `tenant` VALUES (5658, 134, 'public/foto_profil_tenant/67d3a79fb5a5a.jpg', 'RZQ Active Official', 'Chandra', 19, 1, 'Jl. Trunojoyo No.23, Citarum, Kec. Bandung Wetan, Kota Bandung, Jawa Barat 40115', NULL, NULL, 'instagram, Facebook', 'Dalam Negeri, Luar Negeri', NULL, '<p><span style=\"font-weight: bold; color: rgb(118, 118, 118); font-family: Arial, sans-serif;\">1st Fashion Jersey Specialist in Indonesia</span></p>', '2025-02-11', '2025-02-20', '2025-03-14 10:48:00', '2025-03-14 10:50:55');
INSERT INTO `tenant` VALUES (5659, 134, 'public/foto_profil_tenant/67d3aad1d450f.jpg', 'Hoof Official Shop', 'Rozak', 19, 1, 'Jl. Cisaranten Kulon IX No.51, Cisaranten Kulon, Kec. Arcamanik, Kota Bandung, Jawa Barat 40286', NULL, NULL, 'instagram', NULL, NULL, '<p><span style=\"color: rgb(71, 71, 71); font-family: Arial, sans-serif;\">Kami distributor jas, coat, jaket, blazer formal dan non formal sekaligus konveksi terima pembuatan partai atau seragam</span></p>', '2025-02-11', '2025-02-20', '2025-03-14 11:04:33', '2025-03-14 11:04:33');
