INSERT INTO `tenant` VALUES (5680, 134, 'public/foto_profil_tenant/67d7906fc1815.jpeg', 'Alivia House Official', 'Febrari Surya Saputra', 19, 1, 'Tangerang - Banten', NULL, '500.000.000,00', 'Shoope, Instagram, Tokopedia, Facebook', 'Dalam dan Luar Negeri', 'Aplikasi', '<p>Pakaian olah raga</p>', '2025-02-11', '2025-02-20', '2025-03-17 10:01:03', '2025-03-17 10:01:03');
