INSERT INTO `tenant` VALUES (5721, 1226, NULL, 'SKUPIS', 'Awal Fajar Ramadhan', 23, 7, 'Bantaeng', NULL, NULL, NULL, NULL, NULL, '<p><span lang=\"ms\" style=\"font-size:12.0pt;font-family:\r\n&quot;Calibri Light&quot;,sans-serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;;mso-hansi-theme-font:major-latin;mso-bidi-theme-font:major-latin;\r\nmso-font-kerning:0pt;mso-ligatures:none;mso-ansi-language:#003E;mso-fareast-language:\r\nEN-US;mso-bidi-language:AR-SA\">Stik Banana Rasa Basreng</span></p>', NULL, NULL, '2025-04-11 14:08:38', '2025-04-11 14:08:38');
INSERT INTO `tenant` VALUES (5722, 1228, 'public/foto_profil_tenant/67f9d533ed740.jpg', 'Kleokki', 'Hatatomu Wasahua', 23, 7, 'Jl. Almunawaroh Ciganjur Jagakarsa Jakarta Selatan 12630', NULL, NULL, 'Whatsapp: +62 856-9447-9530 (Shashtya), Instagram: @kleokki_57', 'Remaja, Mahasiswa & Gen Z, dan Pekerja muda', NULL, '<p>1. Nama Usaha:</p><p>Kleokki&nbsp;</p><p>2. Jenis Usaha:</p><p>Usaha kuliner inovatif yang menggabungkan makanan tradisional Indonesia, klepon, dengan makanan khas Korea, tteokbokki, sehingga menciptakan perpaduan rasa yang unik dan anti-mainstream.&nbsp;&nbsp;</p><p>3. Konsep Produk:</p><p>Klepon Tteokbokki merupakan makanan fusion yang menyajikan tekstur kenyal khas tteokbokki dengan sentuhan rasa manis dangurih dari klepon.&nbsp;</p><p>Tteokbokki Klepon Manis → Tteokbokki goreng dengan dilumuri saus gula aren dan taburan kelapa parut, menyerupai rasa klepon tradisional.&nbsp;&nbsp;</p><p>4. Tujuan Usaha:</p><p>Tujuan kami membuat usaha ini adalah menggabungkan cita rasa khas Korea dan Indonesia dalam satu hidangan unik yang menarik perhatian pecinta kuliner. Serta&nbsp;</p><p>Mencari perhatian kepada generasi muda, foodies, dan penggemar makanan unik yang selalu mencari sensasi baru dalam dunia kuliner</p><p>5. Keunikan Produk (Unique Selling Points – USP):&nbsp;</p><p>Fusion Unik Indonesia-Korea → Kombinasi dua budaya kuliner dalam satu produk.&nbsp; &nbsp;</p><p>Bahan Lokal Berkualitas → menggunakan gula aren, dan kelapa asli Indonesia.&nbsp;&nbsp;</p><p>Tekstur Kenyal &amp; Lezat → Tteokbokki dengan sensasi lembut khas klepon.&nbsp;&nbsp;</p><p>Instagramable &amp; Modern → Visual yang menarik dengan warna golden brown serta&nbsp; hijau khas klepon dan topping kelapa.&nbsp;&nbsp;</p><p>6. Target Pasar:</p><p>📌 Pecinta makanan unik dan inovatif&nbsp;&nbsp;</p><p>📌 Penggemar makanan Korea (K-food lovers)&nbsp;&nbsp;</p><p>📌 Millennials dan Gen Z yang suka mencoba tren kuliner baru&nbsp;&nbsp;</p><p>📌 Mahasiswa dan pekerja yang membutuhkan camilan praktis.</p><p>7. Bentuk Usaha dan Saluran Distribusi:&nbsp;</p><p>- Penjualan Offline: Booth, food stall, atau gerai kecil di pusat perbelanjaan dan kampus.&nbsp;</p><p>8. Visi &amp; Misi Usaha</p><p>Visi:</p><p>Menjadi pelopor makanan fusion inovatif berbasis makanan lokal yang dapat bersaing di pasar nasional maupun internasional.&nbsp;&nbsp;</p><p>Misi:</p><p>✔ Menghadirkan produk kuliner unik yang menggabungkan cita rasa Indonesia dan Korea.&nbsp;&nbsp;</p><p>✔ Menggunakan bahan-bahan berkualitas lokal untuk mendukung petani dan UMKM dalam negeri.&nbsp;&nbsp;</p><p>✔ Menawarkan pengalaman makan yang menarik dan menyenangkan bagi konsumen.&nbsp;&nbsp;</p><p>✔ Mengembangkan bisnis dengan sistem pemasaran online dan offline yang efektif.&nbsp;&nbsp;</p><p>9. Potensi dan Prospek Usaha:</p><p>Dengan tren makanan fusion yang semakin populer, Klepon Tteokbokki memiliki potensi besar untuk berkembang di pasar kuliner. Produk ini menawarkan pengalaman rasa baru yang unik, sesuai dengan permintaan konsumen yang selalu mencari sesuatu yang inovatif dan anti-mainstream.</p>', '2025-01-01', '2025-01-01', '2025-04-12 09:51:31', '2025-04-12 09:51:31');
INSERT INTO `tenant` VALUES (5723, 1228, 'public/foto_profil_tenant/67fa0e6836816.jpg', 'Heaven Fells', 'FERY DARMANSYAH', 23, 7, 'RAWAGENI, Desa/Kelurahan Ratu Jaya, Kec. Cipayung, Kota Depok, Provinsi Jawa Barat', NULL, NULL, 'Whatsapp 089661599966', 'Mikro', NULL, '<p data-start=\"117\" data-end=\"184\" class=\"\"><strong data-start=\"117\" data-end=\"184\">Heaven Fells - Rasa Surga dalam Setiap Gigitan</strong></p><p data-start=\"186\" data-end=\"552\" class=\"\">Heaven Fells adalah industri roti dan kue yang menghadirkan cita rasa premium melalui perpaduan resep tradisional dan inovasi modern. Berdiri dengan semangat menciptakan kenikmatan yang tak terlupakan, Heaven Fells menyajikan berbagai produk roti, kue, dan pastry berkualitas tinggi yang dibuat dari bahan-bahan terbaik dan diolah dengan standar higienis yang ketat.</p><p data-start=\"554\" data-end=\"910\" class=\"\">Dengan filosofi \"Rasa Surga dalam Setiap Gigitan\", kami berkomitmen untuk selalu menjaga kualitas rasa, tekstur, dan tampilan produk demi memanjakan lidah pelanggan dari berbagai kalangan. Mulai dari roti empuk harian, kue ulang tahun yang elegan, hingga aneka jajanan manis yang menggugah selera — Heaven Fells siap menjadi bagian dari momen spesial Anda.</p><p data-start=\"912\" data-end=\"1181\" class=\"\">Dukungan tim baker profesional, pelayanan ramah, dan inovasi berkelanjutan menjadikan Heaven Fells sebagai pilihan utama dalam industri bakery lokal. Kami melayani pembelian eceran, pemesanan khusus, hingga kerja sama skala besar untuk kebutuhan kafe, hotel, dan event.</p><p>\r\n\r\n\r\n\r\n</p><p data-start=\"1183\" data-end=\"1286\" class=\"\">Temukan surga rasa Anda di Heaven Fells – karena setiap hari layak dirayakan dengan sesuatu yang manis.</p>', '2025-03-08', '2025-03-08', '2025-04-12 13:55:36', '2025-04-12 13:55:36');
INSERT INTO `tenant` VALUES (5724, 1228, 'public/foto_profil_tenant/67fa17db5648f.jpeg', 'Manjiw Drink', 'Rosa Amariah', 23, 7, 'Jl. Pengadegan Utara RT 04/RW 08, Kel. Pengadegan, Kec. Pancoran. Jaksel', NULL, NULL, 'Whatsapp, Instagram', 'Umum', NULL, '<p data-start=\"91\" data-end=\"148\" class=\"\"><strong data-start=\"91\" data-end=\"148\">Manjiw Drink – Segarnya Bikin Nagih!</strong></p><p data-start=\"150\" data-end=\"442\" class=\"\">Manjiw Drink adalah brand minuman kekinian yang menghadirkan sensasi rasa yang unik, segar, dan pastinya bikin nagih! Dengan konsep rasa yang out of the box dan tampilan yang eye-catching, Manjiw Drink hadir sebagai pilihan utama bagi para pecinta minuman segar, dari anak muda hingga dewasa.</p><p data-start=\"444\" data-end=\"787\" class=\"\">Menggunakan bahan-bahan berkualitas dan racikan khas, setiap varian Manjiw Drink dibuat dengan penuh kreativitas untuk menciptakan rasa yang <em data-start=\"585\" data-end=\"600\">manjiw banget</em> di lidah. Mulai dari minuman berbasis teh, susu, buah-buahan segar, hingga topping yang melimpah – semua dibuat untuk memanjakan selera dan memberikan pengalaman minum yang menyenangkan.</p><p data-start=\"789\" data-end=\"982\" class=\"\">Dengan suasana outlet yang fun dan kekinian, serta pelayanan ramah yang maksimal, Manjiw Drink tidak hanya menjual minuman, tapi juga membangun momen seru yang tak terlupakan bersama pelanggan.</p><p>\r\n\r\n\r\n\r\n</p><p data-start=\"984\" data-end=\"1036\" class=\"\"><strong data-start=\"984\" data-end=\"1036\">Manjiw Drink – Rasa yang Bikin Nyangkut di Hati!</strong></p>', '2021-10-08', '2025-01-01', '2025-04-12 14:35:55', '2025-04-12 14:35:55');
INSERT INTO `tenant` VALUES (5725, 1228, 'public/foto_profil_tenant/67fa1cb0e60a9.jpg', 'Gigit Kress', 'Miftahul Jannah', 23, 7, 'Jalan Madrash 2 RW 04, Desa/Kelurahan Cilandak Timur, Kec. Pasar Minggu, Kota Adm. Jakarta Selatan, Provinsi DKI Jakarta Kode Pos: 12560', NULL, NULL, 'Whatsapp, Instagram', 'Mahasiswa', NULL, '<p data-start=\"114\" data-end=\"178\" class=\"\"><strong data-start=\"114\" data-end=\"178\">Gigit Kress – Sekali Gigit, Langsung Kress!</strong></p><p data-start=\"180\" data-end=\"523\" class=\"\">Gigit Kress adalah brand makanan ringan lokal yang menghadirkan sensasi kriuk renyah dan rasa yang nendang di setiap gigitan. Terinspirasi dari camilan favorit masyarakat Indonesia, Gigit Kress hadir dengan beragam varian keripik—mulai dari singkong, kentang, pisang, hingga olahan unik lainnya—yang diolah dengan resep khas dan bumbu pilihan.</p><p data-start=\"525\" data-end=\"797\" class=\"\">Diproses secara higienis dengan teknik penggorengan modern, setiap produk Gigit Kress tidak hanya renyah maksimal, tapi juga kaya rasa. Dari rasa pedas membara, gurih keju, hingga manis-karamel, Gigit Kress punya semua yang bikin ngemil makin seru dan nggak bisa berhenti.</p><p data-start=\"799\" data-end=\"955\" class=\"\">Cocok untuk teman santai, nonton, kerja, atau sekadar pengganjal lapar di tengah hari—Gigit Kress selalu jadi pilihan tepat untuk memuaskan hasrat ngemilmu!</p><p>\r\n\r\n\r\n\r\n</p><p data-start=\"957\" data-end=\"1005\" class=\"\"><strong data-start=\"957\" data-end=\"1005\">Gigit Kress – Rasa Nendang, Renyahnya Juara!</strong></p>', '2024-06-06', '2024-06-06', '2025-04-12 14:56:32', '2025-04-12 14:56:32');
INSERT INTO `tenant` VALUES (5726, 1211, 'public/foto_profil_tenant/67fe4d210c07a.jpg', 'MTH Foods', 'Haryono', 23, 7, 'Jl Duren Tiga Selatan VII No.77 Gg Assalam RT 008  RW 002 Kel Duren Tiga Kec. Pancoran, Jakarta Selatan 12760', NULL, '124.000.000,00', 'Tiktok, Instagram, Website', 'Nasional', 'Manual', '<p>Makaroni Nampol by MTH Foods adalah usaha dibidang Kuliner berupa camilan yang dibuat dari bahan berkualitas dan diproses secara higienis dengan bumbu rahasia dari MTH Foods sehingga menghasilkan produk berkualitas dan sudah memiliki ijin edar PIRT, Sertifikat Halal, dan HKI. MTH Food memproduksi 9 variant rasa Makaroni Nampol yaitu : Original, Pedas, Balado, Keju Manis, Keju Asin, Jagung Manis, Sapi Panggang, Cokelat, Dan Rumput Laut BBQ. MTH Foods juga membuka kesempatan untuk kerjasama bisnis baik maklon maupun reseller,&nbsp;</p><p>Terima kasih, Mari bertumbuh bersama MTH Foods</p>', '2024-01-01', '2024-08-31', '2025-04-15 19:12:17', '2025-04-15 19:12:17');
INSERT INTO `tenant` VALUES (5727, 1211, 'public/foto_profil_tenant/67fe55a8c0391.jpeg', 'Syazana Craft Ecoprint', 'Nani Mulyani', 47, 1, 'Kp. Sukasari RT 21 RW 03 Desa Dayeuhkolot Kec Sagalaherang Kabupaten Subang', NULL, '450.000.000,00', 'Instagram, Tiktok, Whatsapp Grab dan Toko Offline', 'Indonesia dan Asia', 'Manual', '<p>UMKM yang bergerak dibidang usaha fashion ready to wear ramah lingkungan yang berasal dr tumbuhan untuk motif dan warnanya,limited karena dibuat handmade</p>', '2024-01-01', '2024-08-31', '2025-04-15 19:48:40', '2025-04-15 19:48:40');
