INSERT INTO `tenant` VALUES (5756, 376, 'public/foto_profil_tenant/682c08a17f161.jpeg', 'NGAH YAA TAPIS', 'SEPTRI AULIA', 47, 1, 'NEGERI RATU TENUMBANG KECAMATAN PESISIR SELATAN KABUPATEN PESISIR BARAT LAMPUNG', NULL, '5.000.000,00', 'SHOPEE, TIKTOK, FB, IG DAN BENNER', 'KABUPATEN, PROVINSI, NASIONAL', 'MANUAL, ELEKTRONIK', '<p>MENJUAL DAN MEMPRODUKSI SENDIRI BERBAGAI MACAM KERAJINAN TAPIS, SEPERTI KAIN TAPIS, PECI TAPIS, KAOS, KOTAK TISU TAPIS, CLUTH, TAS TAPIS,DLL AGAR TERBENTUKNYA SENTUHAN TRADISI&nbsp; TREND MASA KINI KHUSUNNYA TAPIS PESISIR BARAT KRUI</p>', '2023-04-25', '2023-04-25', '2025-05-20 11:15:22', '2025-05-20 11:44:17');
