INSERT INTO `tenant` VALUES (5773, 41, NULL, 'Greaclogo', '1. Fernando Situmorang 2. Nova Diana Simanjutak', 47, 6, 'Jl. Malangbong 5 No.48, RT 06/ RW 03 Antapani Wetan, Kec. Antapani, Kota Bandung, Jawa Barat 40291', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-05-27 16:11:17', '2025-05-27 16:11:17');
INSERT INTO `tenant` VALUES (5774, 491, 'public/foto_profil_tenant/683938ef2c04e.jpg', 'Manjarum', 'Pegi aulia putri', 47, 1, 'Simpang Empat Bandar Buat, RT 02/RW 07, Kel. Bandar Buat, Kec. Lubuk Kilangan, Padang, Sumatra Barat, 25231.', NULL, '5.000,00', 'tiktok dan instagram', 'nasional', NULL, '<p data-start=\"0\" data-end=\"112\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">UMKM Manjarum adalah pelaku usaha mikro kreatif yang berbasis di Kota Padang, Sumatera Barat, dengan fokus pada produk rajutan handmade berkualitas tinggi.</span> <span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Mengusung semangat kerajinan tangan lokal, Manjarum menghadirkan beragam produk seperti tas rajut, amigurumi (boneka rajut), aksesori, serta hampers dan kado spesial yang cocok untuk berbagai momen.</span></p><p data-start=\"114\" data-end=\"230\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Setiap produk Manjarum dibuat dengan penuh ketelitian dan cinta, menjadikannya unik dan bernilai tinggi.</span> <span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Dengan desain yang modis dan fungsional, produk Manjarum cocok untuk berbagai kalangan, dari anak muda hingga dewasa, yang menghargai keindahan dan keunikan produk lokal.</span></p><p>\r\n\r\n</p><p data-start=\"232\" data-end=\"350\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Manjarum aktif mempromosikan produknya melalui media sosial, khususnya Instagram di akun @tokomanjarum, di mana mereka menampilkan koleksi terbaru dan inspirasi gaya</span></p><p data-start=\"232\" data-end=\"350\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\"><br></span></p><p data-start=\"232\" data-end=\"350\"><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Dengan mengedepankan kualitas dan kreativitas, Manjarum tidak hanya memperkuat identitas budaya lokal melalui kerajinan rajut, tetapi juga berkontribusi dalam pemberdayaan ekonomi masyarakat, khususnya perempuan perajin di Padang</span></p>', '2024-11-22', '2025-03-19', '2025-05-30 11:49:51', '2025-05-30 11:49:51');
INSERT INTO `tenant` VALUES (5775, 491, 'public/foto_profil_tenant/68393a81515e7.jpeg', 'riza sulam', '2.	Rizka Evera', 47, 1, 'Jorong Pasar baru utara, Nagari aia bangih, kecamatan sungai beremas, kabupaten pasaman barat', NULL, '25.000.000,00', 'tiktok dan instagram', 'nasional', NULL, '<p><span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\"><strong data-start=\"0\" data-end=\"14\" data-is-only-node=\"\">Riza Sulam</strong> adalah sebuah usaha mikro, kecil, dan menengah (UMKM) yang bergerak di bidang kerajinan sulaman tradisional khas Minangkabau, berlokasi di Sumatera Barat.</span> <span class=\"relative -mx-px my-[-0.2rem] rounded px-px py-[0.2rem] transition-colors duration-100 ease-in-out\">Usaha ini dikenal karena memproduksi berbagai produk sulaman dengan motif dan teknik khas daerah tersebut, seperti sulaman benang emas yang sering digunakan pada baju pengantin tradisional Minangkabau</span></p>', '2024-11-22', '2025-03-19', '2025-05-30 11:56:33', '2025-05-30 11:56:33');
INSERT INTO `tenant` VALUES (5776, 491, NULL, 'pondok 888', 'Tryani Novera Sudiharto', 47, 1, 'Jl Sunda No. 99 Komplek PT KAI Sawahan Timur', NULL, '20.000.000,00', 'tiktok', 'nasional', NULL, '<p>pondok 888 adalah umkm yang bergerak dibidang kerjinan fokusnnya rajut dengan produk tas&nbsp;</p>', '2024-11-11', '2025-03-19', '2025-05-30 12:08:45', '2025-05-30 12:08:45');
INSERT INTO `tenant` VALUES (5777, 1238, 'public/foto_profil_tenant/68396a9a4e620.png', 'Rendang & Dendeng Bundo Wiwit', 'Witranita', 23, 7, 'Perumnas Bumi Teluk Jambe Blok S No. 188  Karawang, Jawa Barat', NULL, NULL, 'Instagram, Facebook', NULL, NULL, '<p>Rendang Bundo Wiwit didirikan pada tahun\r\n 2018 dengan tujuan untuk menghadirkan\r\n cita rasa kampung halaman, khususnya bagi\r\n para perantau yang merindukan\r\n kehangatan Sumatra Barat. \r\nBerbekal resep warisan nenek moyang,\r\n kami menjaga keaslian dan originalitas\r\n rendang, sehingga setiap hidangan mampu\r\n membawa kenangan indah dan rasa yang\r\n otentik dari tanah Minang</p>', '2025-06-01', '2025-08-31', '2025-05-30 15:21:46', '2025-05-30 15:52:32');
