INSERT INTO `tenant` VALUES (5784, 90, 'public/foto_profil_tenant/68411283e1b98.png', 'Yuk Fit', 'Yulia Fitri Sagita', 23, 7, 'Universitas Al - Azhar Indonesia', NULL, '3.000.000,00', 'Offline (dikantin Universitas Al Azhar Indonesia) dan online melalui sosial media, gojek, grab, shopee', 'Jakarta Selatan', 'Menggunakan sistem pencatatan keuangan yang sederhana', '<p>Yuk Fit merupakan sebuah brand usaha yang dibuat oleh alumni Universitas Al - Azhar Indonesia, yuk fit menjualkan produk minuman, berupa jus dan smooties, yang diolah dengan buah - buahan segar.</p>', '2025-01-05', '2025-12-05', '2025-06-05 10:44:03', '2025-07-08 10:30:56');
INSERT INTO `tenant` VALUES (5785, 90, 'public/foto_profil_tenant/684a849b93fde.jpg', 'Bimbel Safa', 'Nia Sipa Paujia', 46, 9, 'Bogor, Jawa Barat', NULL, '5.000.000,00', 'Instagram', 'Bogor', 'Menggunakan sistem pencatatan keuangan yang sederhana', '<p><span style=\"color: rgb(5, 5, 5); font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; font-size: 15px; text-align: center;\">Bimbel SaFa adalah lembaga pendidikan non formal yang berfokus pada bimbingan belajar untuk pra sekolah atau calistung (Baca, Tulis, Hitung) usia sekolah SD, SMP dan SMA.</span></p>', '2019-07-10', '2019-07-10', '2025-06-12 14:41:15', '2025-06-12 14:41:15');
INSERT INTO `tenant` VALUES (5786, 376, 'public/foto_profil_tenant/684f7612d4d86.jpeg', 'RUAR SAMBAL', 'MERI WIDYAWATI', 23, 7, 'PEKON RAWAS KECAMATAN PESISIR TENGAH KABUPATEN PESISIR BARAT', NULL, '3.800.000,00', 'TIKTOK, WA, FB, IG, TITIP WARUNG', 'KABUPATEN, PROVINSI, NASIONAL', 'manual', '<p>TERINSPIRASI DARI MENURUNYA USAHA PAKAIAN SEHINGGAN BERALIH KE KULINER YAITU PEMBUATAN RUAR SAMBAL DIMANA PEMINATNYA SANGAT BANYAK DAN PASARNYA CUKUP BAGUS</p>', '2025-05-27', '2025-12-31', '2025-06-16 08:40:34', '2025-06-16 08:40:34');
INSERT INTO `tenant` VALUES (5787, 342, NULL, 'FATIR', 'TITIN HUSAIN', 23, 7, 'DUSUN SATRIA DESA ISIMU SELATAN \r\nKECAMATAN TIBAWA KABUPATEN GORONTALO', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-07-04 10:15:58', '2025-07-04 10:15:58');
INSERT INTO `tenant` VALUES (5788, 342, 'public/foto_profil_tenant/68678630995c6.jpeg', 'MAMACA', 'YAYU ABDULLAH', 23, 7, 'JL. AHMAD A. WAHAB DESA BULILA\r\nKECAMATAN TELAGA KABUPATEN GORONTALO', NULL, '15.000.000,00', 'FACEBOOK, INSTAGRAM, WHATSAPP, DLL', 'SEKABUPATEN GORONTALO', 'SPREADSHEET', '<p>Berawal dari dapur sederhana, Mamaca berkembang menjadi merek UMKM yang dipercaya oleh masyarakat sekitar karena kualitas rasa, pelayanan hangat, dan komitmen terhadap kebersihan serta konsistensi rasa.</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:19:30', '2025-07-04 14:43:44');
INSERT INTO `tenant` VALUES (5789, 342, 'public/foto_profil_tenant/686cbad0703fb.jpeg', 'SOBA PADU', 'KASMUNING DAKO', 23, 7, 'JL. ADRIAN BRAHIM DESA DULAMAYO\r\nKECAMATAN BONGOMEME KABUPATEN GORONTALO', NULL, '15.000.000,00', 'FACEBOOK, WHATSAPP, TIKTOK', 'GORONTALO, MANADO, PALU, TERNATE', 'Pencatatan Manual Sederhana', '<p>Berawal dari membuat camilan khusus untuk keluarga. Melihat&nbsp; camilan ini digemari keluarga maka saya berpikir untuk&nbsp; dijual. Ketika itu mulailah saya menjual di sekolah. Waktu itu penjualan sangat laris, maka saya kembangkan dengan mengurus legalitas yg menjadi persyaratan&nbsp; di ritel-ritel modern.</p><p>Kini brand SOBA PADU sudah memiliki produk turunan berupa minyak kelapa kampung, stik kelapa muda.</p><p>Olahan produk pertanian lainnya berupa: cengkeh bubuk, kayu manis bubuk, pala bubuk dan persiapan&nbsp; beras ukuran 5 kg dan 3 kg.</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:21:15', '2025-07-08 13:29:36');
INSERT INTO `tenant` VALUES (5790, 342, 'public/foto_profil_tenant/686b6da17cedf.jpeg', 'BERKAH ABSYAR', 'PONISAH', 23, 7, 'JL. KENARI DESA TINELO \r\nKECAMATAN TILANGO KABUPATEN GORONTALO', NULL, '17.000.000,00', 'FACEBOOK, INSTAGRAM, WHATSAPP, Pameran Offline', 'LINGKUP PROVINSI DAN LUAR DAERAH', 'Pencatatan Manual Sederhana', '<p>Berkah Absyar adalah UMKM yang memproduksi rempeyek dengan bentuk bulat pertama dan satu-satunya di Gorontalo. Rempeyek bulat dibuat dari bahan dan rempah-rempah pilihan berkualitas dan halal.</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:27:15', '2025-07-07 13:48:01');
INSERT INTO `tenant` VALUES (5791, 342, 'public/foto_profil_tenant/686b6eaab732f.jpeg', 'GAPIGO', 'SALMA A. K. HABI', 23, 7, 'DESA DULAMAYO SELATAN\r\nKECAMATAN TELAGA KABUPATEN GORONTALO', NULL, '750.000,00', 'FACEBOOK', 'SEKABUPATEN GORONTALO', NULL, '<p>&nbsp;Usaha Keripik Pisang Gapigo dengan 3 Varian rasa. Original, Balado dan Aren</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:30:02', '2025-07-07 13:52:26');
INSERT INTO `tenant` VALUES (5792, 342, 'public/foto_profil_tenant/686754bc232e6.jpeg', 'NOVI COOKIES', 'NOVI DEU', 23, 7, 'DESA LUWOO\r\nKECAMATAN TELAGA KABUPATEN GORONTALO', NULL, '60.000.000,00', 'FACEBOOK, INSTAGRAM, WHATSAPP, DLL', 'SEKABUPATEN GORONTALO', NULL, '<p>Novi Cookies merupakan usaha dibidang makanan berupa kue kering, cake, roti dan kue ulang tahun.</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:38:47', '2025-07-04 15:17:31');
INSERT INTO `tenant` VALUES (5793, 342, 'public/foto_profil_tenant/686b6c4a233ed.jpeg', 'LITATA', 'YOLANDA TANGAHU', 23, 7, 'DESA TIMUATO \r\nKECAMATAN TELAGA BIRU KABUPATEN GORONTALO', NULL, '25.000.000,00', 'FACEBOOK, INSTAGRAM, WHATSAPP', 'GORONTALO', 'ADA', '<p>Keripik LiTata terbuat dari pisang tanduk pilihan diproses dengan cara di goreng lalu di taburi toping kemudian di panggang, tersedia Varian susu keju, Original, pedas manis, dan coklat</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:39:28', '2025-07-07 13:42:18');
INSERT INTO `tenant` VALUES (5794, 342, 'public/foto_profil_tenant/686790c438675.jpeg', 'MORINGA ZAFIER ORGANIK', 'AMRIANI AMRAN', 23, 7, 'DESA PILOHANYANGA\r\nKECAMATAN TELAGA KABUPATEN GORONTALO', NULL, '30.000.000,00', 'FACEBOOK, INSTAGRAM, TIKTOK', 'LINGKUP PROVINSI DAN LUAR DAERAH', 'ADA', '<p>Produksi Olahan Pangan berbahan dan varian daun kelor di antaranya teh daun kelor, sarabba kelor, kripik keju kelor, krupuk ubi kelor (versi mentah dan sudah di goreng)</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:40:15', '2025-07-04 15:28:52');
INSERT INTO `tenant` VALUES (5795, 342, 'public/foto_profil_tenant/68679289c5614.jpeg', 'HUMAYA', 'HADJARIA LAMATO', 23, 7, 'PERUM AZIZIAH DESA LUWOO\r\nKECAMATAN TELAGA KABUPATEN GORONTALO', NULL, '72.000.000,00', 'FACEBOOK, INSTAGRAM, DLL', 'SEKABUPATEN GORONTALO', NULL, '<p>Humaya berasal dari kata bahasa daerah Gorontalo artinya Contoh. Usaha ini di dirikan pada tanggal 27 September 2017 tetapi aktif dalam usaha pada masa covid_19. Akhirnya pada tahun 2019 banyak peminat/pembeli Keripik Pisang Susu Salju, Dll.</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:40:57', '2025-07-04 15:36:25');
INSERT INTO `tenant` VALUES (5796, 342, 'public/foto_profil_tenant/686b7207ba7de.jpeg', 'TIFADU', 'RATNA PAKAYA', 23, 7, 'BATUDAA KABUPATEN GORONTALO', NULL, '230.400.000,00', 'MEDIA SOSIAL ONLINE DAN OFFLINE', 'LINGKUP PROVINSI DAN LUAR DAERAH', 'Pencatatan Manual Sederhana', '<p>Tifadu memiliki berbagai macam produk unggulan, salah satunya panada tore yang memiliki beberapa varian rasa yakni rasa coklat, abon dan rasa kacang.</p><p><br></p>', '2024-07-01', '2025-06-30', '2025-07-04 10:41:30', '2025-07-07 14:06:47');
INSERT INTO `tenant` VALUES (5797, 342, 'public/foto_profil_tenant/68678a649bb10.jpeg', 'FITRAH GEMILANG', 'ZURIATI T. DENI', 23, 7, 'DESA PANGADAA KABUPATEN GORONTALO', NULL, '50.000.000,00', 'FACEBOOK, WHATSAPP, GOOGLE BISNIS', 'KABUPATEN, KOTA, DAN SULAWESI', 'KAS SEDERHANA', '<p>permen Khas Gorontalo \"Soba Fitrah Gemilang\" yngg terbuat dari bahan2 Alami.</p>', '2024-07-01', '2025-06-30', '2025-07-04 10:42:27', '2025-07-04 15:02:40');
INSERT INTO `tenant` VALUES (5798, 342, 'public/foto_profil_tenant/68678d8a60b42.jpeg', 'ARBIE BAKERY', 'RISNA MOHA', 23, 7, 'DUSUN 3 DESA YOSONEGORO\r\nKECAMATAN LIMBOTO BARAT KABUPATEN GORONTALO', NULL, '60.000.000,00', 'FACEBOOK', 'SEKABUPATEN GORONTALO', NULL, 'Kacang ovaltin adalah salah satu cookies dengan perpaduan antara kacang coklat dan susu yg melimpah membuat cemilan ini sangat cocok untuk semua kalangan.', '2024-07-01', '2025-06-30', '2025-07-04 10:43:26', '2025-07-04 15:15:06');
INSERT INTO `tenant` VALUES (5799, 431, NULL, 'PT Royzen Certivo Mandiri', 'Roy Hendrikson Sihombing', 46, 9, 'Jl. Guru No 12 A Arengka Raya Residence', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-07-06 09:48:48', '2025-07-06 09:48:48');
INSERT INTO `tenant` VALUES (5800, 90, 'public/foto_profil_tenant/686c89c7a8e5a.jpeg', 'Aneka Olahan Ikan Mang Ncun', 'Indi Kamalah', 23, 7, 'Kabupaten Bandung', NULL, '3.000.000,00', 'Instagram untuk online, bazaar untuk offlinenya', 'jakarta dan bandung', 'menggunakan pencatatan keuangan sederhana', '<p>Aneka olahan ikan mangncun merupakan produk usaha yang pada awalnya&nbsp;<span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">&nbsp;</span><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">&nbsp;menghasilkan berupa abon lele dan kembali menciptakan produk-produk baru yaitu mengolah limbah tulang ikan menjadi cemilan yang sangat digemari oleh semua kalangan, yaitu gabus duri ikan dan kulitnya diolah menjadi kerupuk kulit ikan. Dari tahun ke tahun pemasaran semakin meningkat, frozen food berupa nugget ikan, kaki naga, otak-otak, sate ikan, cuankie ikan, bakso ikan, dimsum dan produk olahan lainnya berhasil dibuat</span></p>', '2022-01-08', '2023-01-13', '2025-07-08 10:00:23', '2025-07-08 15:17:19');
INSERT INTO `tenant` VALUES (5801, 90, 'public/foto_profil_tenant/686c936b3935f.jpeg', 'Hey SOB', 'Rahmi A Kamila', 43, NULL, 'Jakarta', NULL, '15.000.000,00', 'Instagram untuk online', 'seluruh indonesia', 'Menggunakan sistem pencatatan keuangan yang sederhana', '<p>Hey SOB merupakan&nbsp;<span style=\"color: rgb(0, 0, 0); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Penyedia Layanan Konsultasi Psikologi (Online &amp; Offline)</span></p>', NULL, NULL, '2025-07-08 10:41:31', '2025-07-08 10:41:31');
INSERT INTO `tenant` VALUES (5802, 90, 'public/foto_profil_tenant/686c9ac587240.jpeg', 'Rokusouq', 'Imad', 23, 7, 'Universitas Al - Azhar Indonesia', NULL, NULL, 'Offline (dikantin Universitas Al Azhar Indonesia) dan online melalui sosial media, gojek, grab, shopee', 'Jakarta Selatan', 'menggunakan pencatatan keuangan sederhana', '<p>Rokusouq merupakan usaha yang dijalankan dibidang kuliner, rokusouq memasarkan produk kuliner roti kukus dengan berbagai macam varian rasa, dan juga rice bowl nasi jeruk ayam .</p>', '2025-04-02', '2026-04-02', '2025-07-08 11:12:53', '2025-07-08 11:12:53');
INSERT INTO `tenant` VALUES (5803, 90, 'public/foto_profil_tenant/686c9ff9d4402.jpeg', 'Kolegarasa', 'Pony Mastia Nurlaiha', 23, 7, 'Jakarta Selatan', NULL, '25.000.000,00', 'Offline di Bazaar dan online melalui sosial media, gojek, grab', 'JABODETABEK', 'menggunakan pencatatan keuangan sederhana', '<p>Kolegarasa merupakan sebuah brand dibidang Food and Beverage, untuk kulinernya terdiri dari berbagai macam jenis makanan yang dipasarkan, diantaranya ada puding dengan berbagai macam varian rasa yang unik, bungeoppang, risol, dan gimbab&nbsp;</p>', '2020-08-08', '2022-08-08', '2025-07-08 11:35:05', '2025-07-08 11:35:05');
