INSERT INTO `tenant` VALUES (5808, 530, 'public/foto_profil_tenant/68749d8c3ac63.png', 'Spezialshoes Care', 'Alya Marshanda  Kusdiyanti', 47, 1, 'Jl. Safir no. 09 Perumahan Permata Erfina, Rejoagung, Kedungwaru, Tulungagung, Jawa Timur - 66225', NULL, '3.019.000,00', 'https://www.instagram.com/spezialeather.shoescare/', NULL, NULL, NULL, '2025-07-14', '2025-07-14', '2025-07-14 12:47:54', '2025-07-14 13:02:52');
INSERT INTO `tenant` VALUES (5809, 19, 'public/foto_profil_tenant/68750a8e81056.png', 'Wasana', 'Putu Caesar Evananda Wibawa', 28, 1, 'Br. Mantring, Tampaksiring', NULL, '20.000.000,00', 'Social Media, Website', 'Indonesia, Bali, Karangasem - Amed Indonesia, Bali, Badung - Seseh Indonesia, Bali, Denpasar Indonesia, Bali, Gianyar', NULL, '<p>Wasana adalah brand kerajinan tangan asal Bali yang mengubah limbah tulang sapi, tanduk, dan kayu menjadi aksesoris serta produk fungsional bernilai tinggi. Kami mengusung prinsip sustainable craftsmanship, memadukan estetika alami dengan sentuhan seni ukir Bali.</p>', '2025-01-19', NULL, '2025-07-14 20:47:58', '2025-07-14 20:47:58');
INSERT INTO `tenant` VALUES (5810, 19, NULL, 'Yayobite', 'Maria Gratiani Hardi Saputri', 23, 7, 'Jl. Tukad Barito no 77', NULL, '1.500.000,00', 'Instagram, WA', 'Denpasar-Badung', NULL, '<p>Menjual makanan berupa brownies secara online</p>', '2025-01-19', NULL, '2025-07-14 20:52:10', '2025-07-14 20:52:10');
INSERT INTO `tenant` VALUES (5811, 19, NULL, 'uglygoose.co', 'Gede Bagus Mahaputra Ananta Wijaya', 19, 1, 'Jalan Tukad Buaji Gang Lotus No 16a', NULL, '300.000,00', 'instagran, tiktok, shopee', 'Indonesia, Bali, Denpasar', NULL, '<p>uglygoose.co bergerak di bidang usaha clothing brand untuk fashion anak-anak muda</p>', '2025-01-19', NULL, '2025-07-14 20:57:37', '2025-07-14 20:57:37');
INSERT INTO `tenant` VALUES (5812, 19, 'public/foto_profil_tenant/68750d8629bb4.png', 'Pia & Pie', 'Jihannada Tsaltsa Bila Najla', 23, 7, 'Jl Tukad Baru Barat, Pemogan, Denpasar Selatan', NULL, '4.000.000,00', 'Instagram, Tiktok, Toko offline, Gofood, Grabfood, Shopeefood', 'Indonesia, Bali, Denpasar-Badung', NULL, '<p>Pia &amp; Pie adalah usaha yang bergerak di bidang F&amp;B dan menjual produk berupa dessert dengan berbagai macam varian dan ukuran. Dan 2 model yaitu dessert sehat yang mana bahannya tidak mengandung gluten dan rendah gula, dan satunya dessert reguler seperti pada umumnya.</p>', '2025-01-19', NULL, '2025-07-14 21:00:38', '2025-07-14 21:00:38');
INSERT INTO `tenant` VALUES (5813, 19, 'public/foto_profil_tenant/6875100d9c322.png', 'Reduktor Development', 'I Gede Agus Supartana', 32, 6, 'Jl raya celuk GG legong gianyar', NULL, '2.000.000,00', 'Instagram', 'Bali', NULL, '<p>Software development for MSME&nbsp;</p>', '2025-01-19', NULL, '2025-07-14 21:11:25', '2025-07-14 21:11:25');
INSERT INTO `tenant` VALUES (5814, 19, 'public/foto_profil_tenant/687510afbf02d.png', 'Pixemo Studio', 'Paramitha Dewi Wijaya', 47, 6, 'Denpasar, Bali', NULL, NULL, 'Instagram', NULL, NULL, '<p>Pixemo Studio merupakan usaha yang baru dibentuk dan bergerak dibidang game developer dan khusus membuat game dengan style pixel.</p>', '2025-01-19', NULL, '2025-07-14 21:14:07', '2025-07-14 21:14:07');
INSERT INTO `tenant` VALUES (5815, 19, NULL, 'Hypotza', 'Rajdev Dhillon', 32, 6, 'Jl. Suli No.85, Dangin Puri Kangin, Kec. Denpasar Utara, Kota Denpasar, Bali 80234', NULL, '5.000.000,00', 'Instagram', 'Indonesia, Bali, Denpasar', NULL, '<p>Penyedia jasa business intelligence analyst</p>', '2025-01-19', NULL, '2025-07-14 21:16:30', '2025-07-14 21:16:30');
INSERT INTO `tenant` VALUES (5816, 19, NULL, 'Ketos shopgame', 'Dewa Gede Dhalem Keshananda', 47, 8, 'Asrama Sudirman no26 a, Denpasar Barat', NULL, '5.000.000,00', 'instagram dan whatsapp', 'Indonesia, dan vietnam serta malaysia', NULL, '<p>ShopGame adalah toko digital yang menjual berbagai macam akun game ready pakai dengan harga terjangkau. Menyediakan akun Mobile Legends, Free Fire, PUBG Mobile, Genshin Impact, dan game populer lainnya.</p>', '2025-01-19', '2025-01-19', '2025-07-14 21:18:39', '2025-07-14 21:18:39');
INSERT INTO `tenant` VALUES (5817, 19, 'public/foto_profil_tenant/687512500955c.png', 'Grazedu', 'Aliffa Milanisty', 46, 9, 'Jl.Yudistira Perum Puri Kuta Damai, Seminyak, Bali', NULL, '1.000.000,00', 'Instagram', 'Nasional', NULL, '<p>Platform pengembangan diri &amp; karir untuk perempuan muda mencapai potensi maksimal dalam karir profesional dan pertumbuhan pribadi melalui kelas-kelas yang hangat, inklusif dan supportif.</p>', '2025-01-19', NULL, '2025-07-14 21:21:04', '2025-07-14 21:21:04');
INSERT INTO `tenant` VALUES (5818, 19, NULL, 'Gumi Production', 'Ni Putu Sinmby Octaria Putri', 47, 6, 'Darmasaba Permai Gg. X no. 22', NULL, '15.000.000,00', 'mouth to mouth, reach out langsung dengan email via perusahaan', 'Bali: denpasar, badung, gianyar', NULL, '<p>Gumi Production lahir di tahun 2022 dari semangat kami yang besar terhadap dunia visual berawal dari film dan video musik, lalu berkembang mengikuti kebutuhan zaman. Kini, Gumi juga menghadirkan layanan pembuatan company profile, content creation, hingga pengelolaan media sosial</p>', '2025-01-19', NULL, '2025-07-14 21:23:12', '2025-07-14 21:23:12');
INSERT INTO `tenant` VALUES (5819, 19, 'public/foto_profil_tenant/68751406458f3.jpg', 'Green oil solution', 'I Putu Kevin Eka Setiawan', 22, 6, 'Batu bulan gianyar br tubuh', NULL, NULL, 'Instagram', 'Denpasar,badung,gianyar', NULL, '<p>Green Oil Solution adalah perusahaan yang bergerak di bidang teknologi ramah lingkungan dengan fokus pada penyediaan solusi inovatif dalam pengolahan limbah menjadi energi terbarukan. Kami menyediakan mesin canggih yang mampu mengubah berbagai jenis limbah organik dan plastik menjadi minyak yang dapat dimanfaatkan kembali sebagai bahan bakar alternatif. Dengan pendekatan yang berkelanjutan dan efisien, Green Oil Solution berkomitmen untuk mendukung program pengurangan limbah dan transisi energi bersih di berbagai sektor industri dan komunitas lokal.</p>', '2025-01-19', NULL, '2025-07-14 21:28:22', '2025-07-14 21:28:22');
INSERT INTO `tenant` VALUES (5820, 19, 'public/foto_profil_tenant/68751488426ab.png', 'Kahfi Education', 'Adelia A\'fa Nafasha', 46, 9, 'Jl Akasia XVIA Gg Narwastu 7C, Tanjung Bungkak Kaja, Denpasar Timur', NULL, '4.000.000,00', 'instagram, facebook, brosur', 'Denpasar, Tabanan, Badung, Gianyar', NULL, '<p>Kahfi Education merupakan sebuah platform pendidikan berbentuk bimbingan belajar. Saat ini tersedia program pendidikan agama islam seperti Baca Tulis Qur’an/Mengaji, Tahfidz dan Tahsin, serta program pengembangan diri bagi guru dan orang tua melalui webinar, workshop. Hal ini memungkinkan terbangunnya ekosistem pendidikan yang mendukung kolaborasi antara pendidik, orang tua dan siswa.&nbsp;<br><br></p>', '2025-01-19', NULL, '2025-07-14 21:30:32', '2025-07-14 21:30:32');
