INSERT INTO `tenant` VALUES (5829, 154, 'public/foto_profil_tenant/6875fdaa9ed37.jpg', 'Susu Murni Kencana', 'Diva Hadaya Pratama', 23, 7, 'Rancaekek, Bandung', NULL, '2.000.000,00', 'Instagram', NULL, NULL, '<p>Susu Murni Kencana merupakan usaha mikro yang menawarkan Susu Murni berkualitas yang langsung didapat dari peternak sapi pilihan.</p>', '2025-06-26', '2027-06-26', '2025-07-15 14:05:14', '2025-07-15 14:05:14');
INSERT INTO `tenant` VALUES (5830, 154, 'public/foto_profil_tenant/6875ffeb530d4.png', 'Toko Kosmetik Momongor', 'Dika Ratu', 26, NULL, 'Bojongsoang', NULL, '25.000.000,00', NULL, NULL, NULL, '<p>Toko Kosemetik Momongor merupakan toko retail yang menjual berbagai macam kosmetik dan skincare lokal dengan harga yang kompetitif</p>', '2025-06-26', '2027-06-26', '2025-07-15 14:14:51', '2025-07-15 14:14:51');
INSERT INTO `tenant` VALUES (5831, 154, 'public/foto_profil_tenant/687601ae9c4a8.png', 'CemilQu By Teh Adel', 'Resty Delima', 23, 7, 'Ujung Berung', NULL, '15.000.000,00', 'Instagram, Tiktok', NULL, NULL, 'CemilQu By Teh Adel menawarkan berbagai macam jajanan seperti risoles, cireng isi, cireng kuah keju, baso aci dan cemilan lainnya dengan harga yang merakyat mulai dari 4000 rupiah.', '2025-06-26', '2027-06-26', '2025-07-15 14:22:22', '2025-07-15 14:22:22');
INSERT INTO `tenant` VALUES (5832, 154, 'public/foto_profil_tenant/68760256bfdaa.png', 'BANG! Coffee and Tea', 'Indira Aulia', 23, 7, 'Bandung', NULL, NULL, 'Instagram', NULL, NULL, '<p>BANG! Coffee and Tea merupakan usaha yang menawarkan minuman botol siap saji seperti kopi, green tea dan thai tea yang dibuat dengan bahan premium namun masih dengan harga yang kompetitif</p>', '2025-06-26', '2027-06-26', '2025-07-15 14:25:10', '2025-07-15 14:25:10');
INSERT INTO `tenant` VALUES (5833, 154, 'public/foto_profil_tenant/687602e79d1d6.png', 'Konsistensi Olahan (Kono)', 'Yandi Nur Muhamad', 23, 7, 'Arcamanik', NULL, '2.000.000,00', 'Instagram', NULL, NULL, '<p>Konsistensi Olahan (Kono) menawarkan produk makanan penutup kekinian seperti cheesekut yang dimodifikasi dengan lebih sehat tanpa pemanis berlebihan. Selain itu, Kono akan terus berinovasi dalam pengembangan produk yang lebih bervariasi kedepannya.</p>', '2025-06-26', '2027-06-26', '2025-07-15 14:27:35', '2025-07-15 14:27:35');
INSERT INTO `tenant` VALUES (5834, 150, 'public/foto_profil_tenant/6879e321b9e43.png', 'Daniscookies', 'Ibu Dhany', 23, 7, 'Perumahan Ciputat Baru. Jl. Cendrawasih No 03 Blok B Rt007 Rw008 Kecamatan Ciputat Kelurahan Sawah Kota Tangerang Selatan 15413', NULL, '50.000.000,00', 'Instagram, Whatsapp, TikTok.Facebook', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<font color=\"#000000\"><span data-canva-clipboard=\"\" style=\"background-color: rgb(255, 255, 255);\"></span></font><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><span style=\"background-color: rgb(255, 255, 255);\"><font color=\"#000000\">Logo DANIS memiliki arti yang diambil dari nama founder : Ibu Dhany, Memiliki sigar merupakan itu melambangkan topi koki masak yang digunakan ibu dhany.</font></span></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><span style=\"background-color: rgb(255, 255, 255);\"><font color=\"#000000\">Nama DANIS diharapkan dapat diartikan dari DANIS &amp; IS yang artinya memiliki pelanggan yang banyak dan terdapat 4 garis dalam logo DANIS melambangkan ini terdiri 1 keluarga yang berjumlah 4 orang</font></span></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:01:05', '2025-10-08 12:08:30');
INSERT INTO `tenant` VALUES (5836, 150, 'public/foto_profil_tenant/6879e3d3bac20.png', 'S\'Kuwud', 'Nur Zahra', 23, 7, 'Jl. Mirah III Blok P1A Villa Mutiara Sawah Baru Ciputat, Tangsel', NULL, '35.000.000,00', 'Instagram Dan Whatsapp', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<font color=\"#000000\"><span data-canva-clipboard=\"\"></span></font><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">S\'Kuwud Indonesia menyediakan aneka minuman segar dengan produk unggulan minuman berbahan kelapa muda, seperti es kuwut. </font></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Kami memiliki 3 varian es kuwut, yaitu es kuwut melon, es kuwut nanas madu dan es kuwut buah naga. Selain es kuwut, ada es kelapa muda original, es kelapa susu aren, es kopi kelapa, dan minuman lainnya. Kami punya 17 varian minuman.&nbsp;</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:04:03', '2025-10-09 08:16:47');
INSERT INTO `tenant` VALUES (5837, 150, 'public/foto_profil_tenant/6879e45c976d6.png', 'Createavity', 'Raka Pratama', 23, 7, 'Jl Aru 1 BLOK PB/26 Nusa Loka Sektor 14.6', NULL, '10.000.000,00', 'Instagram Dan Whatsapp', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<span data-canva-clipboard=\"\"></span><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Resep untuk membuat Createavity cukup menantang. Dimana dari 60 resep hanya diambil 5 resep saja. </font></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Selama mencari resep, 1 hari hanya bisa minum maksimal 3 resep. </font></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Sebab lebih dari itu, Createavity bisa membuat lancar buang air besar.<br> </font><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Jadi dipastikan untuk sensitif terhadap rasa dan membayangkan untuk membuat resep selanjutnya</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:06:20', '2025-10-08 11:55:48');
INSERT INTO `tenant` VALUES (5838, 150, 'public/foto_profil_tenant/6879e516af786.png', 'KueQue', 'Indriastanto', 23, 7, 'Kp Sengkol Rt 03/01 no.65, muncul, setu, tangerang selatan', NULL, '50.000.000,00', 'Instagram Dan Whatsapp', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<span data-canva-clipboard=\"\"></span><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Nama Produk : Bolen Tangsel</font><br><font color=\"#000000\">Ukuran : 1 Box isi 6 pcs</font><br><font color=\"#000000\">Varian : Pisang Keju, Pisang Cokelat, Tape Singkong, dan Durian</font><br><font color=\"#000000\">Berat per box : 350 gram</font></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Harga : Rp. 35.000 / box</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:09:26', '2025-10-08 12:13:39');
INSERT INTO `tenant` VALUES (5839, 150, 'public/foto_profil_tenant/6879e596796f9.png', 'Snack Ngunyah', 'Kartika Bella', 23, 7, 'Jalan Keramat No.23 RT/RW 009/010, Rengas, Ciputat Timur, Tangerang selatan', NULL, '25.000.000,00', 'Instagram, Whatsapp, Shoppe', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<font color=\"#000000\"><span data-canva-clipboard=\"\"></span></font><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Lumpia krispi by Snack Ngunyah adalah camilan gurih dan renyah yang terbuat dari kulit lumpia tipis yang digulung, lalu digoreng hingga berwarna keemasan. Teksturnya yang renyah di luar dan lembut di dalam membuat lumpia krispi menjadi camilan favorit banyak orang.</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:11:34', '2025-10-09 08:19:56');
INSERT INTO `tenant` VALUES (5840, 150, 'public/foto_profil_tenant/6879e61101b7d.png', 'Laris Food', 'Kris', 23, 7, 'Parakan no. 154, Pondok benda Pamulang', NULL, '40.000.000,00', 'Instagram, Whatsapp, TikTok', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<font color=\"#000000\"><span data-canva-clipboard=\"\"></span></font><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Larisfood produsen aneka cemilan kemasan ekonomis harga all varian 10ribu dan minuman fresh lemon sereh aneka minuman milik jelly kemasan botol 350ml 12ribuan</font></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Atau bisa juga request kemasan untuk jual kembali dengan harga affordable</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:13:37', '2025-10-08 12:14:05');
INSERT INTO `tenant` VALUES (5841, 150, 'public/foto_profil_tenant/6879e6b5f3a61.png', 'Kenyees Food', 'Fenda Iriani', 23, 7, 'Jl.atmaja Gg.lasim babakan pocis No.154 kelurahan bakti jaya kec.setu tangsel', NULL, '60.000.000,00', 'Instagram Dan Whatsapp', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<font color=\"#000000\"><span data-canva-clipboard=\"\"></span></font><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">BAGOR KENYESS Bagor Premium Tanpa campuran apapun, Tanpa Pengawet dan Tanpa MSG Sehingga aman untuk di konsumsi sebagai pelengkap Makanan, Masakan atau Olahan MPASI</font></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Dengan Pengolahan yang baik Sesuai Namanya KRENYES KRENYES banget saking renyahnya,<br> </font><font color=\"#000000\">Bawang berkualitas  Selalu digoreng dengan minyak baru ( Sehingga warna selalu Kuning Gold )</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 13:16:21', '2025-10-08 12:11:55');
INSERT INTO `tenant` VALUES (5843, 150, 'public/foto_profil_tenant/6879fc3fc092d.png', 'Bakervi', 'SANTI*', NULL, NULL, 'Arinda 2 Blok F1 No. 5 Pondok Aren, Tangerang', NULL, '10.000.000,00', 'Instagram Dan Whatsapp', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<span data-canva-clipboard=\"\"></span><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><span style=\"color: rgb(255, 255, 255);\">Merupakan usaha yang dirintis oleh wanita yang hobi jajan dan bercita-cita ingin menebar kebahagian melalui cita rasa makanan yang dibuat</span></h4></div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><p><span style=\"color: rgb(255, 255, 255);\">Nikmati kelezatan Bolu Labu Bakervi, kue lembut dengan rasa manis alami dari labu kuning pilihan. Kaya serat &amp; vitamin, cocok untuk camilan sehat di rumah, teman ngopi, atau ide hampers unik!</span></p></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 14:48:15', '2025-10-08 11:51:49');
INSERT INTO `tenant` VALUES (5844, 150, 'public/foto_profil_tenant/6879fd622903c.png', 'Nafra', 'Martinah', 23, 7, 'Jl.noor abdullah no.13 rt003/13 no.13 jombang ciputat', NULL, '40.000.000,00', 'Instagram, Whatsapp, Shoppe', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', NULL, '2025-05-05', '2025-11-24', '2025-07-18 14:53:06', '2025-10-08 11:46:48');
INSERT INTO `tenant` VALUES (5845, 150, 'public/foto_profil_tenant/6879fdc749f85.png', 'Iraspantry', 'Irawati', 23, 7, 'Jalan menjangan 4 B Rt 001 Rw 003 No. 71 Pondok Ranji, Ciputat timur, Tangerang selatan Banten', NULL, '2.000.000,00', 'Instagram Dan Whatsapp', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<font color=\"#000000\"><span data-canva-clipboard=\"\"></span></font><div><div style=\"font-size: 62.6662px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Kentang Mustofa dari Iraspantry adalah lauk kering renyah khas rumahan yang dibuat dari irisan kentang tipis, digoreng garing, lalu dibalut bumbu istimewa dengan aroma daun jeruk yang harum menggoda.</font></h4></div><div style=\"font-size: 62.6662px; line-height: 1.4; direction: ltr; letter-spacing: 0em; text-align: center;\"><h4><font color=\"#000000\">Cocok untuk teman makan nasi hangat, lauk praktis anak kos, camilan sore hari, hingga pelengkap bekal yang bikin semangat.</font></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 14:54:47', '2025-10-08 12:10:31');
INSERT INTO `tenant` VALUES (5846, 150, 'public/foto_profil_tenant/6879fe333922e.png', 'Qaila', 'Banu Novita Sabti', 19, 1, 'Kp baru selatan rt 001 rw 002 pakulonan serpong Tangerang selatan', NULL, '90.000.000,00', 'Instagram, Whatsapp, Shoppe', 'Pasar Lokal, Nasional dan Internasional', 'Pembukuan Dengan Aplikasi', '<span data-canva-clipboard=\"\"></span><div><div style=\"font-size: 81.3324px; line-height: 1.4; direction: ltr; letter-spacing: 0em;\"><h4><span style=\"color: rgb(0, 0, 0);\">Qail</span><span style=\"color: rgb(0, 0, 0);\">la Muslim Wear adalah brand mukena asal Indonesia sejak 2015, dikenal dengan bahan premium, desain simpel, dan harga terjangkau.</span></h4></div></div>', '2025-05-05', '2025-11-24', '2025-07-18 14:56:35', '2025-10-09 08:14:33');
INSERT INTO `tenant` VALUES (5847, 64, 'public/foto_profil_tenant/688e1b8a27298.jpeg', 'PT Mujnah Kemiri Lombok', 'MUJNAH', 23, 7, 'PANCOR DAO, Desa/Kelurahan Aik\r\nDarek, Kec. Batukliang, Kab.\r\nLombok Tengah, Provinsi Nusa\r\nTenggara Barat\r\nKode Pos: 83553', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"178\" data-end=\"492\">Kemiri (Aleurites moluccanus) merupakan salah satu komoditas hasil pertanian Indonesia yang memiliki nilai ekonomi tinggi di pasar internasional. Biji kemiri banyak digunakan sebagai bahan baku dalam industri makanan, kosmetik, farmasi, hingga industri kimia, terutama karena kandungan minyak alaminya yang tinggi.</p><p data-start=\"494\" data-end=\"823\">Ekspor kemiri dari Indonesia umumnya meliputi dua bentuk, yaitu kemiri utuh (whole candle nut) dan kemiri kupas (shelled candle nut), baik dalam kondisi mentah maupun yang telah dikeringkan. Negara tujuan utama ekspor kemiri meliputi India, Tiongkok, Singapura, Malaysia, Belanda, dan beberapa negara di Timur Tengah serta Eropa.</p><p data-start=\"825\" data-end=\"1268\">Potensi ekspor kemiri sangat besar mengingat permintaan global terhadap bahan alami yang multifungsi terus meningkat. Dengan kualitas kemiri yang baik dan proses pascapanen yang memenuhi standar internasional, Indonesia memiliki peluang besar untuk meningkatkan volume dan nilai ekspor komoditas ini. Selain itu, pengembangan ekspor kemiri juga berdampak positif terhadap peningkatan pendapatan petani dan perekonomian daerah penghasil kemiri.</p><p>\r\n\r\n\r\n</p><p data-start=\"1270\" data-end=\"1570\">Untuk menjaga daya saing di pasar global, pelaku usaha kemiri perlu memperhatikan standar mutu, pengemasan, dan sertifikasi yang dibutuhkan oleh negara tujuan ekspor. Dukungan dari pemerintah dan lembaga terkait juga penting dalam hal pelatihan, akses pembiayaan, dan promosi perdagangan luar negeri.</p>', '2024-07-01', '2024-07-01', '2025-07-23 13:49:54', '2025-08-02 21:07:06');
INSERT INTO `tenant` VALUES (5848, 64, 'public/foto_profil_tenant/688e1c098e323.jpeg', 'PT FATIH CRAF LOMBOK', 'FATIH', 47, 2, 'Bodo Berak, Desa/Kelurahan\r\nPajangan, Kec. Kopang, Kab.\r\nLombok Tengah, Provinsi Nusa\r\nTenggara Barat\r\nKode Pos: 83553', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"124\" data-end=\"570\">Anyaman dari rotan dan bambu merupakan produk kerajinan tangan bernilai seni tinggi yang telah menjadi komoditas ekspor unggulan dari Indonesia. Produk ini dibuat secara tradisional maupun semi-modern oleh para pengrajin lokal, terutama dari daerah-daerah seperti Kalimantan, Jawa, dan Sumatera. Anyaman rotan dan bambu meliputi berbagai jenis barang seperti keranjang, tas, furnitur, tempat penyimpanan, lampu hias, hingga dekorasi rumah tangga.</p><p data-start=\"572\" data-end=\"912\">Kelebihan utama produk ini terletak pada <strong data-start=\"613\" data-end=\"655\">bahan baku alami yang ramah lingkungan</strong>, <strong data-start=\"657\" data-end=\"683\">keindahan desain etnik</strong>, dan <strong data-start=\"689\" data-end=\"710\">daya tahan tinggi</strong>. Permintaan pasar internasional, khususnya dari negara-negara di Eropa, Amerika Serikat, Jepang, dan Australia, terus meningkat karena tren gaya hidup berkelanjutan dan dekorasi rumah berbasis natural.</p><p data-start=\"914\" data-end=\"1246\">Proses ekspor produk anyaman ini umumnya melibatkan pelaku UMKM, koperasi, serta eksportir besar yang telah memenuhi standar kualitas dan sertifikasi ekspor. Pemerintah Indonesia melalui berbagai program, seperti pelatihan ekspor dan promosi dalam pameran internasional, juga aktif mendorong pertumbuhan ekspor produk kerajinan ini.</p><p>\r\n\r\n\r\n</p><p data-start=\"1248\" data-end=\"1559\">Dengan kombinasi antara <strong data-start=\"1272\" data-end=\"1303\">kreativitas pengrajin lokal</strong>, <strong data-start=\"1305\" data-end=\"1327\">dukungan kebijakan</strong>, serta <strong data-start=\"1335\" data-end=\"1374\">permintaan pasar global yang tinggi</strong>, ekspor anyaman dari rotan dan bambu menjadi salah satu bentuk nyata kontribusi sektor ekonomi kreatif dalam memperkuat perekonomian nasional dan meningkatkan kesejahteraan masyarakat.</p>', '2012-06-10', '2025-06-10', '2025-07-23 13:53:57', '2025-08-02 21:09:13');
INSERT INTO `tenant` VALUES (5849, 64, 'public/foto_profil_tenant/688e1c6e6e722.jpeg', 'BALE RATAN', 'HARTAWALUDIN', 47, 1, 'LEKOR BARAT, DESA LEKOR,\r\nKEC. JANAPRIA, KBUPATEN\r\nLOMBOK TENGAH,\r\nDesa/Kelurahan Lekor, Kec.\r\nJanapria, Kab. Lombok Tengah,\r\nProvinsi Nusa Tenggara Barat\r\nKode Pos: 83553', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"154\" data-end=\"552\">Ekspor barang dari kayu, rotan, dan gabus merupakan salah satu sektor andalan Indonesia dalam perdagangan internasional, yang mencerminkan kekayaan sumber daya alam dan keterampilan kerajinan tangan masyarakat. Produk-produk ini mencakup berbagai macam barang seperti furnitur, kerajinan dekoratif, peralatan rumah tangga, hingga bahan konstruksi yang memiliki nilai seni dan fungsionalitas tinggi.</p><p data-start=\"554\" data-end=\"782\"><strong data-start=\"554\" data-end=\"574\">Barang dari kayu</strong> biasanya diolah menjadi perabot rumah tangga seperti meja, kursi, lemari, hingga ukiran dekoratif yang banyak diminati di pasar global karena kualitas kayu tropis Indonesia seperti jati, mahoni, dan meranti.</p><p data-start=\"784\" data-end=\"1066\"><strong data-start=\"784\" data-end=\"805\">Barang dari rotan</strong> dikenal dengan keunikan dan keindahannya. Indonesia sebagai salah satu produsen rotan terbesar dunia mengekspor berbagai produk rotan mulai dari kursi, keranjang, hiasan dinding, hingga aksesoris interior yang bernilai tinggi di pasar Eropa, Amerika, dan Asia.</p><p data-start=\"1068\" data-end=\"1359\"><strong data-start=\"1068\" data-end=\"1089\">Barang dari gabus</strong> (cork) biasanya digunakan dalam pembuatan alas kaki, pelapis dinding, penutup botol, serta barang-barang kerajinan ramah lingkungan. Produk dari gabus memiliki pasar yang terus tumbuh karena meningkatnya kesadaran akan produk-produk yang berkelanjutan dan eco-friendly.</p><p>\r\n\r\n\r\n\r\n</p><p data-start=\"1361\" data-end=\"1616\">Dengan pengolahan yang mengedepankan aspek kualitas, seni, dan keberlanjutan, ekspor barang dari kayu, rotan, dan gabus tidak hanya menjadi sumber devisa negara tetapi juga membuka lapangan kerja dan mendukung pertumbuhan industri kreatif di dalam negeri.</p>', '2020-02-10', '2025-07-23', '2025-07-23 13:58:48', '2025-08-02 21:10:54');
INSERT INTO `tenant` VALUES (5850, 64, 'public/foto_profil_tenant/688e1d0ca5686.jpeg', 'CV SUPPLY SPOTS SEJAHTERA', 'Andrehea', 2, 7, 'Jalan TGH Abdul Hafidz Kuripan, Desa/Kelurahan Kuripan, Kec. Kuripan,\r\nKab. Lombok Barat, Provinsi Nusa Tenggara Barat,\r\nKode Pos: 83362', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"140\" data-end=\"663\">Ekspor perdagangan besar buah-buahan merupakan kegiatan distribusi dan penjualan buah-buahan dalam jumlah besar ke pasar luar negeri. Kegiatan ini mencakup seluruh proses mulai dari pengumpulan hasil panen dari petani lokal, pengemasan dengan standar internasional, hingga pengiriman melalui jalur laut atau udara ke negara tujuan ekspor. Buah-buahan yang diekspor biasanya terdiri dari komoditas unggulan seperti pisang, mangga, nanas, salak, jeruk, dan buah tropis lainnya yang memiliki permintaan tinggi di pasar global.</p><p>\r\n</p><p data-start=\"665\" data-end=\"1238\">Perdagangan besar dalam konteks ekspor ini dikelola oleh perusahaan-perusahaan besar atau koperasi yang telah memiliki jaringan dagang internasional, izin ekspor, dan sertifikasi keamanan pangan. Ekspor buah-buahan tidak hanya berperan penting dalam menyumbang devisa negara, tetapi juga mendorong pertumbuhan ekonomi daerah, meningkatkan pendapatan petani, serta memperkenalkan produk lokal ke pasar dunia. Keberhasilan ekspor sangat dipengaruhi oleh kualitas produk, ketersediaan pasokan, kepatuhan terhadap regulasi negara tujuan, serta efisiensi logistik dan pemasaran.</p>', '2025-03-27', '2025-07-23', '2025-07-23 14:02:43', '2025-08-02 21:13:32');
INSERT INTO `tenant` VALUES (5851, 1215, 'public/foto_profil_tenant/68809679d7160.jpeg', 'CANKIS', 'Veronica Elvi astuti zebua', 23, 7, 'jln.Duku Raya No.06 Perumahan BSP Lubuk pakam', NULL, '9.100.000,00', 'shoppe,tiktiok,instagram,facebook', 'pasar lokal', 'ada', '<p>&nbsp;Cangkis adalah kukis kacang berbahan dasar tepung terigu, minyak nabati, kacang tanah, gula, dan garam, tanpa pengawet, tanpa tambahan perasa, dan tanpa pewarna makanan,Cangkis yaitu sebagai cemilan harian yang gurih dan renyah.</p><p>Keunggulan invensi produk Cangkis, sebagai berikut:</p><p>- Resep otentik warisan sejak 1980</p><p>- Bebas bahan kimia tambahan</p><p>- Cita rasa khas Nusantara</p>', '2025-08-05', '2025-08-05', '2025-07-23 14:59:53', '2025-09-02 09:06:31');
INSERT INTO `tenant` VALUES (5852, 1215, 'public/foto_profil_tenant/6880998a35c1a.jpeg', 'REMPEYEK', 'HARIRAYANA', 23, 7, 'Tanjung morawa Desa Dagang Kerawan', NULL, '150.000,00', 'No telefon, whatsApp', 'pasar lokal', 'ada', '<p>&nbsp;Rempeyek dibuat dari bahan berkualitas, bahan pencampuran antara air tepung kacang garam air bumbu daun jeruk di adon kemudian digoreng dengan teknik khusus sehingga kuning keemasan hingga teksturnya tiris hingga tanpa mengandung banyak minyak dan siap kemas dan pemasaran</p>', '2025-08-05', '2025-08-05', '2025-07-23 15:12:58', '2025-09-02 09:11:30');
INSERT INTO `tenant` VALUES (5853, 1215, 'public/foto_profil_tenant/68809cee067cd.jpeg', 'KACANG TOJIN', 'Lasmauli Saragih', 23, 7, 'Jln.LK 1  Inpres Lubuk Pakam', NULL, '1.500.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp', 'pasar lokal', 'ada', '<p>&nbsp;Kacang&nbsp; tojinadalah camilan berbahan dasar Kacang tanah yang telah direbus bersama bumbu yang telah dihaluskan lalu digoreng hingga garing.&nbsp; &nbsp; bermanfaat sebagai camilan sehat yang praktis dinikmati kapan saja, cocok untuk teman bersantai, belajar atau bekerja. Produk ini juga membantu meningkatkan nilai jual kacang tanah lokal dengan olahan yang tahan lama dan peluang usaha bagi reseller.</p>', '2025-08-05', '2025-08-05', '2025-07-23 15:27:26', '2025-09-02 09:08:11');
INSERT INTO `tenant` VALUES (5854, 1215, 'public/foto_profil_tenant/6880a022637b7.jpeg', 'PISMEL M.A', 'ANUGRAH ELFIRA', 23, 7, 'Dusun 9 Lorong Pendowo Desa Saemtis', NULL, '30.000.000,00', 'shoppe,tiktiok,instagram,facebook,', 'Pasar Regional', 'ada', '<p>Pismel M.A dibuat dari pisang barangan pilihan yang dipetik langsung dari kebun petani lokal untuk menjaga kesegraan dan alami.Menggunakan tepung gandum yang kaya akan serat, vitamin dan mineral yang baik untuk kesehatan</p><p>dikemas dalam kemasan modern, higenis, dan praktis dengan desain menarik yang menjaga Pismel M.A tetap renyah lebih lama ,</p><p>mengajak anak anak yang tidak suka mengkonsumsi pisang, dapat mengkonsumsi pisang dengan cara yang lebih praktis dan mudah. Dan memberikan manfaat yang sangat baik untuk tubuh karena Pismel M.A di produksi dengan bahan bahan yang berkualitas.</p>', '2025-08-05', '2025-08-05', '2025-07-23 15:41:06', '2025-09-02 09:10:45');
INSERT INTO `tenant` VALUES (5855, 1215, 'public/foto_profil_tenant/6880a29bb7b53.jpeg', 'STIK DAUN KELOR', 'Ratna Sari', 23, 7, 'Jln. Dusun 6 Desa Bandar Labuhan', NULL, '30.000.000,00', 'shoppe,tiktiok,instagram,facebook, reseller', 'pasar lokal', 'ada', '<p>Stik Daun Kelor adalah camilan khas berbahan dasar tepung yang dicampur dengan daun kelor dengan tambahan bumbu lainnya. Cita rasanya yang gurih, renyah, dan memiliki sensasi \"krenyes\" menjadikannya favorit masyarakat dari berbagai kalangan usia.diolah tanpa bahan pengawet</p>', '2025-08-05', '2025-08-05', '2025-07-23 15:51:39', '2025-09-02 09:11:55');
INSERT INTO `tenant` VALUES (5856, 1215, 'public/foto_profil_tenant/6880a6678a501.jpeg', 'BBROWNS CAKE', 'Yunita Kusumawaty Nasution', 23, 7, 'Jln. Jati/Pasar IV Sei Mencirim Sunggal', NULL, '30.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'pasar lokal', 'ada', '<p>&nbsp;BBROWNS CAKE menyediakan berbagai makanan pengisi candy corner seperti cake ulang tahun, kukis hias, cake pop, cupcake, coklat loly dan berbagai macam kue lainnya yang disesuaikan dengan tema acara, Saat ini BBrowns cake sedang mengemangkan produk yang berbasis tepung selain tepung gandum (gluten free). Kami menggunakan tepung mocaf sebagai bahan dasar butter kukis kemi,Kukis gluten free sangat baik bagi penderita penyakit pencernaan, dan diet. Saat ini masyarakat Indonesia ingin sehat sehingga mengurangi konsumsi gandum dan beralih ketepung yang bebas gluten.</p>', '2025-08-05', '2025-08-05', '2025-07-23 16:07:51', '2025-09-02 09:06:02');
INSERT INTO `tenant` VALUES (5857, 1215, 'public/foto_profil_tenant/68818eca06d80.jpeg', 'RATU NILA', 'Syahrial Efendi Sitorus', 23, 7, 'Gg. Gardu No. 21 Dusun XI. Desa Purwodidi, Kecamatan Sunggal, Kab. Deli Serdang', NULL, '27.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'pasar lokal', 'ada', '<p>Produk ini dibuat dari kulit ikan yang selama ini sering dianggap limbah. Dengan diolah menjadi kerupuk,Kulit ikan nila merupakan sumber protein hewani yang tinggi serta mengandung kolagen alami,Kulit ikan nila dicuci bersih, kemudian ditiriskan hingga kering. Setelah itu, kulit dibumbui dengan campuran rempah-rempah khas, lalu digoreng dalam minyak panas hingga renyah dan matang sempurna tanpa menggunakan bahan pengawet.</p>', '2025-08-05', '2025-08-05', '2025-07-24 08:39:22', '2025-09-02 09:11:07');
INSERT INTO `tenant` VALUES (5858, 1215, 'public/foto_profil_tenant/688191a694f1a.jpeg', 'KACANG BAWANG RAHASIA', 'Siti Rohani', 23, 7, 'Tanjung Morawa –A Dusun III', NULL, '30.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller', 'Pasar Lokal', 'ada', '<p>Kacang Bawang Rahasia dibuat dari kacang berkualitas pilihan yang dipanen langsung dari kebun petani lokal dan diolah secara higienis untuk menciptakan cita rasa alami,Kacang Bawang Rahasia diciptakan untuk memanfaatkan hasil panen kacang lokal secara optimal dan menghadirkan camilan sehat, praktis, dan unik yang dapat bersaing di pasar modern</p>', '2025-08-05', '2025-08-05', '2025-07-24 08:51:34', '2025-09-02 09:07:51');
INSERT INTO `tenant` VALUES (5859, 1215, 'public/foto_profil_tenant/688193e25b4f1.jpeg', 'JAMU MUTIARA', 'Putri Undi', 23, 7, 'Jln. Bakaran Batu Dusun III Desa Tanjung Baru, Kabupaten Deli Serdang', NULL, '50.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'Pasar Lokal', 'ada', '<p>Jamu mutiara adalah minuman yang memiliki rasa yang unik karena mutiara diproses dengan cara fermentasi secara higienis dengan bahan-bahan alami serta aman dikonsumsi (tanpa bahan Kimia),Semua produk akan menggunakan 100% bahan alami pilihan, tanpa pengawet buatan, dan diproses dengan standar kebersihan tinggi. Kemasan akan didesain modern, praktis, dan mudah dibawa.</p>', '2025-08-05', '2025-08-05', '2025-07-24 09:01:06', '2025-09-02 09:07:32');
INSERT INTO `tenant` VALUES (5860, 1215, 'public/foto_profil_tenant/6881968635d44.jpeg', 'KERIPIK PEDAS MANIS', 'Julia Susi Lestari', 23, 7, 'Tanjung Sari', NULL, '12.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'Pasar Lokal', 'ada', '<p>Keripik pedas manis merupakan camilan khas yang terbuat dari ubi kayu. Pembuatannya diawali dengan membersihkan ubi dari kulitnya, lalu dikukus, dipotong tipis, dan digoreng hingga renyah sebelum akhirnya dibalut dengan sambal. Sensasi renyah dan perpaduan rasa pedas-manisnya menjadikan keripik ini favorit berbagai kalangan usia</p>', '2025-08-05', '2025-08-05', '2025-07-24 09:12:22', '2025-09-02 09:09:06');
INSERT INTO `tenant` VALUES (5861, 1215, 'public/foto_profil_tenant/688198b0d16a7.jpeg', 'PANGSIT PEDAS', 'WIna Sri Wibawa', 23, 7, 'Jln. Cempaka Dusun VII Desa Kedai Durian', NULL, '6.000.000,00', 'No telefon, whatsApp', 'Pasar Lokal', 'ada', '<p>&nbsp;Pangsit Pedas by Wina adalah usaha rumahan yang bergerak di bidang kuliner, khususnya makanan ringan berbasis olahan pangsit. Produk dijual dalam bentuk siap makan dan frozen, cocok untuk camilan atau lauk, Pangsit goreng kering dengan bumbu pedas khas, tersedia dalam berbagai tingkat kepedasan dan Ada versi siap makan dan frozen (beku)</p>', '2025-08-05', '2025-08-05', '2025-07-24 09:21:36', '2025-09-02 09:10:22');
INSERT INTO `tenant` VALUES (5862, 1215, 'public/foto_profil_tenant/68819b3c933de.jpeg', 'KENTANG MUSTOFA', 'Cholidah Fitriani', 23, 7, 'Jln.Kedai Durian Vii Delitua', NULL, '15.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'Pasar Lokal', 'ada', '<p>Sambal kentang Mustofa yang berbahan dasar kentang dengan campuran teri dan kacang tanah memiliki cita rasa khas yang gurih, renyah dengan sensasi pedas manis nya menjadikan sambal kentang Mustofa ini di sukai dari semua kalangan dari anak - anak hingga orang tua.membantu para ibu-ibu untuk menghidangkan sajian yang enak namun praktis</p>', '2025-08-05', '2025-08-05', '2025-07-24 09:32:28', '2025-09-02 09:08:42');
INSERT INTO `tenant` VALUES (5863, 1215, 'public/foto_profil_tenant/6881a0617181c.jpeg', 'GARUDA BATIK KARO', 'Sri Ninta Tarigan', 48, 1, 'Perumahan Patumbak Asri A74. Jln. Pertahanan Patumbak Dusun V. Gg. Abdurahman. Patumbak Kampung', NULL, '1.000.000,00', 'shoppe,tiktiok,instagram,facebook', 'Pasar Lokal', 'ada', '<p>1. Garuda Batik Karo atau GBK dibuat dengan mengangkat motif ornamen budaya Karo yang begitu kaya dengan nilai-nilai filosofis. Salah satu ornamen yang begitu dikenali adalah Rumah Siwaluh Jabu atau Rumah yang ditempati oleh 8 Kepala Keluarga. Untuk mempertahankan nilai-nilai filosofis disuku Karo maka ornamen-ornamen ini dituangkan dalam bentuk pakaian yang dapat digunakan sehari-hari.&nbsp;</p><p>2. Bahan yang digunakan pada pakaian ini adalah katun yang menyerap. Meskipun tebal, namun saat digunakan terasa ringan dan sejuk.</p><p>3. Sasaran pasarnya adalah anak perempuan remaja (,13thm-18thn) sampai wanita dewasa. (19tahun keatas)</p><p>4. Dikerjakan dengan menggunakan alat Batik Cap dan Printing.</p><p>5. Ada beberapa cara kerja pembuatan Batik Karo ini:</p><p>Pertama: Pemilihan kain .</p><p>Kedua: Pencetan motif Karo dengan Cap.</p><p>Ketiga: Proses pencampuran warna.</p><p>Keempat: Pengeringan&nbsp;</p><p>Kelima:</p><p>Penjahitan dengan menerapkan ukuran Free Size yg dapat digunakan dari LD 98-120</p>', '2025-08-05', '2025-08-05', '2025-07-24 09:54:25', '2025-09-02 09:06:52');
INSERT INTO `tenant` VALUES (5864, 1215, 'public/foto_profil_tenant/6881a292dd8d2.jpeg', 'MENDALI SONGKET', 'Mendalitua Hutabarat', 48, 1, 'Dusun XIV Pasar Melintang', NULL, '15.000.000,00', 'shoppe,tiktiok,instagram,facebook', 'Pasar Lokal', 'ada', 'MENDALI SONGKET ADALAH KAIN TENUN TRADISIONAL YANG DI BUAT MENGUNAKAN ALAT TENUN MANUAL / TRADISIONAL YANG MENGANKAT MOTIF KARO , LOKAL , SONGKET&nbsp; DI BUAT DENGAN MENYISIPKAN BENANG EMAS DAN SUTR APADA KAIN TENUN YANG SUDAH JADI DENGAN MENGUNAKAN ALAT KHUSUS DAN INDAHAKAN POLA-POLA RUMIT DAN INDAH DI BUAT DARI BAHAN DASAR SEPERTI DARI SUTRA , KATUN , DAN CAMPURAN KEDUA NYA BENANG EMAS DI GUNAKAN SEBAGAI BENANG HIAS UNTUK MENCIPTAKAN TAMPILAN BERKILAU . SENGKET INI DI CIPTAKAN&nbsp; MENGANDUK MAKSA FILOSOFIS&nbsp; PRODUK SONGKET YANG KAMI CIPTAKAN LEBIH SERING DI GUNAKAN DALAM ACARA ADAT DAN PERNIKAHAN', '2025-08-05', '2025-08-05', '2025-07-24 10:03:46', '2025-09-02 09:09:33');
INSERT INTO `tenant` VALUES (5865, 1215, 'public/foto_profil_tenant/6881a4ca53e39.jpeg', 'JAJANAN NEA', 'Nur Eza Aldi', 23, 7, 'Link.II Jln. Sudirman Gg. Pancasila Lubuk Pakam', NULL, '2.500.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'Pasar Lokal', 'ada', '<p>Kue Bawang Original adalah camilan khas berbahan dasar tepung yang telah dicampur dengan bahan - bahan lainnya, lalu digoreng hingga garing. Cita rasanya yang gurih, renyah, dan memiliki sensasi \"krenyes\" menjadikannya favorit masyarakat dari berbagai kalangan usia.Kue Bawang Original dapat menghadirkan varian dan rasa baru yang unik dan menarik, seperti Kue Bawang Keju, Kue Bawang Ubi Ungu, atau pedas manis, agar dapat menarik minat konsumen dari berbagai kalangan</p>', '2025-08-05', '2025-08-05', '2025-07-24 10:13:14', '2025-09-02 09:07:11');
INSERT INTO `tenant` VALUES (5866, 1215, 'public/foto_profil_tenant/68898807c4896.jpeg', 'TOGOS', 'Togos sorimatua harahap', 48, 1, 'Jl Sidomulyo psr9 Tembung GG balam', NULL, '3.000.000,00', 'No telefon, whatsApp', 'Pasar Internasional', 'ada', 'toko TOGOS adalah toko&nbsp; mempembuatan sepatu, tali pingang ,tas ,dompet topi, rompi, sandal dan kaki palsu berbahan dari kulit sinteti di kerjakan dengan tangan tangan yang terampil mengunakan mesin jait , dan peralatn yang lain masih manual perna menjangkau pasar internasional&nbsp; yaitu malaysia dan terpuruk setelah covid -19 melanda dan mencoba bangkit pasca covid-19', '2025-08-05', '2025-08-05', '2025-07-30 09:48:39', '2025-09-02 09:12:18');
INSERT INTO `tenant` VALUES (5867, 64, 'public/foto_profil_tenant/688e1f8702137.jpeg', 'KOPI PUNIK SUMBAWA', 'WIWIN SURYANI', 23, 2, 'Dusun Punik, Kec. Batulanteh, Kab. Sumbawa, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"212\" data-end=\"520\"><strong data-start=\"212\" data-end=\"234\">Kopi Punik Sumbawa</strong> adalah kopi organik premium yang tumbuh di dataran tinggi Pulau Sumbawa, Nusa Tenggara Barat, Indonesia. Ditanam secara alami tanpa menggunakan pestisida atau bahan kimia sintetis, kopi ini mencerminkan komitmen petani lokal terhadap pertanian berkelanjutan dan pelestarian lingkungan.</p><p data-start=\"522\" data-end=\"933\">Dipetik secara selektif oleh tangan-tangan berpengalaman, biji kopi Punik diolah melalui proses pasca panen yang terstandarisasi untuk menjaga cita rasa dan kualitas biji. Karakter rasa Kopi Punik dikenal dengan <strong data-start=\"734\" data-end=\"861\">aroma floral yang khas, body sedang hingga penuh, dan aftertaste yang bersih dengan sentuhan manis alami dan sedikit rempah</strong>, mencerminkan kekayaan tanah vulkanik dan iklim mikro di kawasan Punik.</p><p>\r\n\r\n</p><p data-start=\"935\" data-end=\"1263\">Sebagai produk unggulan ekspor, Kopi Punik Sumbawa telah memenuhi standar mutu internasional, cocok untuk pasar specialty coffee global. Dengan sertifikasi organik dan praktik perdagangan yang adil (fair trade), kopi ini menjadi pilihan ideal bagi konsumen dunia yang peduli terhadap kualitas, keberlanjutan, dan etika produksi.</p>', '2022-05-12', '2025-08-02', '2025-08-02 21:24:07', '2025-08-02 21:24:07');
INSERT INTO `tenant` VALUES (5868, 64, 'public/foto_profil_tenant/688e2116e0b63.jpeg', 'UD REMPAH ORGANIK LOMBOK', 'MUHIR ALI', 48, 2, 'Sakra, Kab. Lombok Timur, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"573\" data-end=\"905\">Vanili organik asal Pulau Lombok merupakan salah satu komoditas rempah unggulan Indonesia yang memiliki kualitas tinggi dan cita rasa khas tropis. Ditanam secara alami tanpa pestisida atau bahan kimia, vanili ini tumbuh di lahan subur dengan iklim tropis yang ideal, menghasilkan polong vanili yang tebal, berminyak, dan kaya aroma.</p><p>\r\n</p><p data-start=\"907\" data-end=\"1153\">Dengan proses fermentasi dan pengeringan yang dilakukan secara tradisional dan diawasi ketat, vanili Lombok menghasilkan profil rasa manis, lembut, dan kompleks, sangat cocok untuk industri makanan, minuman, kosmetik, dan farmasi di pasar global.</p>', '2013-05-10', '2025-08-02', '2025-08-02 21:30:46', '2025-08-02 21:30:46');
INSERT INTO `tenant` VALUES (5869, 64, 'public/foto_profil_tenant/688e24faa258d.jpeg', 'PT. BINTANG AGRO SENTOSA', 'MUNTASAR', 48, 7, 'Jl. Pancor Manggis, Dusun Manggong, Desa Bantu Kumbung, Kec. Lingsar, Kab. Lombok Barat, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p>Pulau Lombok, yang terletak di Provinsi Nusa Tenggara Barat, Indonesia, memiliki potensi besar dalam sektor pertanian dan perkebunan berorientasi ekspor. Dengan iklim tropis yang ideal, tanah yang subur, serta komitmen petani lokal terhadap praktik pertanian berkelanjutan, Lombok telah menghasilkan berbagai komoditas unggulan yang diminati pasar internasional.</p>', '2022-02-02', '2025-08-02', '2025-08-02 21:47:22', '2025-08-02 21:47:22');
INSERT INTO `tenant` VALUES (5870, 64, 'public/foto_profil_tenant/688e2693f352c.jpeg', 'PT. AGRO ZEE ANNUR', 'ETY SURYA NINGSIH', 48, 7, 'Jl. Suranadi I No. 52 Mekar Indah, Desa Lembuak, Kec Narmada, Kab. Lombok Barat, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p>Pulau Lombok, yang terletak di Provinsi Nusa Tenggara Barat, Indonesia, memiliki potensi besar dalam sektor pertanian dan perkebunan berorientasi ekspor. Dengan iklim tropis yang ideal, tanah yang subur, serta komitmen petani lokal terhadap praktik pertanian berkelanjutan, Lombok telah menghasilkan berbagai komoditas unggulan yang diminati pasar internasional.</p>', '2021-06-02', '2025-08-02', '2025-08-02 21:54:11', '2025-08-02 21:54:11');
INSERT INTO `tenant` VALUES (5871, 64, 'public/foto_profil_tenant/688e27d34a9a2.jpeg', 'CV. TRI UTAMI JAYA', 'NASRIN', 48, 2, 'Jl. Sakura Raya Blok G No. 9 BTN Sweta Indah, Mataram, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"160\" data-end=\"606\">Kelor (<em data-start=\"167\" data-end=\"185\">Moringa oleifera</em>) merupakan tanaman tropis yang dikenal memiliki berbagai manfaat kesehatan dan nilai ekonomi tinggi. Dalam beberapa tahun terakhir, kelor menjadi komoditas unggulan ekspor karena tingginya permintaan global, terutama dari negara-negara di Eropa, Amerika Serikat, Jepang, dan Timur Tengah. Produk kelor yang diekspor meliputi daun kering, serbuk daun, teh kelor, kapsul suplemen, minyak biji kelor, hingga bahan kosmetik.</p><p data-start=\"608\" data-end=\"951\">Indonesia, sebagai salah satu negara dengan iklim tropis yang ideal untuk pertumbuhan kelor, memiliki potensi besar dalam pengembangan dan ekspor produk kelor. Selain karena melimpahnya bahan baku, dukungan dari pemerintah dalam pengembangan UMKM dan pertanian organik juga mendorong peningkatan daya saing produk kelor di pasar internasional.</p><p data-start=\"953\" data-end=\"1243\">Ekspor kelor memerlukan standar kualitas yang tinggi, seperti sertifikasi organik, izin edar BPOM, serta uji laboratorium terkait kandungan gizi dan keamanan produk. Oleh karena itu, pelaku usaha perlu memperhatikan aspek pengolahan, pengemasan, dan pemenuhan regulasi negara tujuan ekspor.</p><p>\r\n\r\n\r\n</p><p data-start=\"1245\" data-end=\"1577\">Dengan terus meningkatnya kesadaran masyarakat global terhadap gaya hidup sehat dan konsumsi produk alami, prospek ekspor kelor diperkirakan akan terus tumbuh di masa mendatang. Kelor tidak hanya menjadi komoditas ekspor potensial, tetapi juga menjadi bagian dari strategi pembangunan ekonomi berkelanjutan berbasis pertanian lokal.</p>', '2021-02-02', '2025-08-02', '2025-08-02 21:59:31', '2025-08-02 21:59:31');
INSERT INTO `tenant` VALUES (5872, 64, 'public/foto_profil_tenant/688e2a0890846.jpeg', 'CV. SAFIR INDO RAYA', 'SAYUK WIBAWATI', 23, 7, 'Jl. Angsoka No.14, Gomong, Kec. Selaparang, Kota Mataram, Nusa Tenggara Bar. 83126', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p><strong data-start=\"2137\" data-end=\"2157\">NUTSAFIR Cookies</strong> adalah camilan sehat inovatif berbahan biji-bijian dari Lombok, NTB. Diproduksi oleh <strong data-start=\"2243\" data-end=\"2265\">CV Safir Indo Raya</strong> sejak 2012 dengan pendekatan produksi halal dan higienis. Semua produk bebas pengawet, pemanis buatan, dan pewarna, serta dikemas rapi sesuai standar BPOM. Dikenal melalui banyak penghargaan nasional seperti HALAL Award 2017 dan Jamkrindo Award 2019. Sampai akhir 2023, perusahaan telah melakukan persiapan untuk memasuki pasar internasional, termasuk partisipasi di TEI dan event SIAL Paris bersama dukungan BUMN.</p>', '2020-01-02', '2025-08-02', '2025-08-02 22:08:56', '2025-08-02 22:08:56');
INSERT INTO `tenant` VALUES (5873, 64, 'public/foto_profil_tenant/688e2b8a7183f.jpeg', 'CV. YANT SORGHUM INDONESIA', 'YANTI', 23, 7, 'Jl. Saleh Sunkar No. 14a, Dayan Peken Ampenan, Mataram, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p>Sorgum merupakan salah satu komoditas pangan dan pakan yang memiliki nilai strategis dalam perdagangan internasional. Sebagai tanaman serealia yang tahan terhadap kekeringan dan adaptif terhadap berbagai jenis lahan, sorgum menjadi alternatif penting pengganti gandum dan jagung, terutama di negara-negara yang memiliki iklim kering dan semi-kering.</p><p>Ekspor sorgum mencakup pengiriman biji sorgum utuh maupun produk turunannya ke berbagai negara, baik sebagai bahan pangan, pakan ternak, maupun bahan baku industri bioenergi. Negara-negara tujuan utama ekspor sorgum meliputi Tiongkok, Jepang, Meksiko, dan beberapa negara di Timur Tengah dan Afrika.</p><p>Dalam konteks Indonesia, meskipun masih dalam tahap pengembangan, ekspor sorgum memiliki potensi besar untuk dikembangkan. Hal ini sejalan dengan meningkatnya permintaan global terhadap produk pangan sehat, bebas gluten, dan berkelanjutan. Indonesia sebagai negara agraris memiliki peluang besar untuk menjadi salah satu pemain dalam ekspor sorgum, terutama dengan memanfaatkan lahan marginal yang tidak cocok untuk komoditas lain.</p><p>Penguatan ekspor sorgum memerlukan dukungan dari berbagai pihak, termasuk pemerintah dalam hal kebijakan ekspor, pembinaan petani, serta promosi dagang ke pasar internasional. Selain itu, pengembangan industri pengolahan sorgum di dalam negeri juga menjadi faktor penting dalam meningkatkan nilai tambah dan daya saing produk sorgum Indonesia di pasar global.</p>', '2022-07-13', '2025-08-02', '2025-08-02 22:15:22', '2025-08-02 22:15:22');
INSERT INTO `tenant` VALUES (5874, 64, 'public/foto_profil_tenant/688e2cbe223fb.jpeg', 'CV. ADING WALET ALBUNTARAN', 'RUSDI', 23, 7, 'Tegal Desa Kanteng, Kec. Praya Bara, Kab. Lombok Tengah, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"185\" data-end=\"551\"><strong data-start=\"185\" data-end=\"208\">Sarang burung walet</strong> merupakan salah satu komoditas ekspor unggulan Indonesia yang memiliki nilai ekonomi tinggi di pasar internasional, terutama di negara-negara Asia seperti Tiongkok, Hong Kong, dan Singapura. Sarang walet berasal dari air liur burung walet (genus <em data-start=\"455\" data-end=\"467\">Aerodramus</em>) yang mengeras dan biasanya dipanen dari gua alami maupun rumah-rumah walet buatan.</p><p data-start=\"553\" data-end=\"906\">Indonesia adalah <strong data-start=\"570\" data-end=\"634\">produsen dan eksportir terbesar sarang burung walet di dunia</strong>, dengan kontribusi mencapai lebih dari 80% pasokan global. Komoditas ini memiliki permintaan tinggi karena dipercaya memiliki manfaat kesehatan, seperti meningkatkan daya tahan tubuh, mempercepat pemulihan, serta sebagai bahan dalam pengobatan tradisional dan kecantikan.</p><p data-start=\"908\" data-end=\"1292\"><strong data-start=\"908\" data-end=\"925\">Proses ekspor</strong> sarang burung walet memerlukan standar mutu yang ketat, termasuk proses pembersihan, pengeringan, pengemasan, dan sertifikasi kesehatan dari karantina hewan. Negara tujuan ekspor umumnya menetapkan regulasi ketat terkait keamanan pangan dan asal-usul produk, sehingga eksportir harus mematuhi persyaratan tersebut, seperti uji laboratorium, izin edar, dan pelabelan.</p><p>\r\n\r\n\r\n</p><p data-start=\"1294\" data-end=\"1734\"><strong data-start=\"1294\" data-end=\"1333\">Tantangan dalam ekspor sarang walet</strong> mencakup fluktuasi harga internasional, regulasi yang berubah-ubah dari negara tujuan (seperti Tiongkok), serta kebutuhan untuk meningkatkan daya saing melalui inovasi pengolahan dan branding produk. Namun demikian, dengan potensi pasar yang besar dan meningkatnya kesadaran terhadap manfaat produk alami, ekspor sarang burung walet tetap menjadi peluang bisnis strategis bagi pelaku usaha Indonesia.</p>', '2020-05-02', '2025-08-02', '2025-08-02 22:20:30', '2025-08-02 22:20:30');
INSERT INTO `tenant` VALUES (5875, 64, 'public/foto_profil_tenant/688e2e0df1e70.jpeg', 'UD. DAHLIA GROUP', 'AFFAN SHAMMAKH', 4, 2, 'Old Port Street No. 3 Labuhan Lombok, Lombok Timur, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"173\" data-end=\"628\">Ekspor ikan tuna merupakan salah satu komoditas andalan sektor perikanan Indonesia yang memiliki nilai ekonomi tinggi di pasar global. Tuna dikenal sebagai produk laut premium yang banyak diminati di berbagai negara, terutama di Jepang, Amerika Serikat, Uni Eropa, dan negara-negara Asia lainnya. Indonesia sebagai negara kepulauan dengan wilayah laut yang luas memiliki potensi besar dalam produksi ikan tuna, baik dari perikanan tangkap maupun budidaya.</p><p data-start=\"630\" data-end=\"1067\">Jenis tuna yang diekspor antara lain tuna sirip kuning (<em data-start=\"686\" data-end=\"702\">Yellowfin Tuna</em>), tuna sirip biru (<em data-start=\"722\" data-end=\"736\">Bluefin Tuna</em>), dan <em data-start=\"743\" data-end=\"758\">Skipjack Tuna</em>. Produk ekspor bisa berupa tuna segar, beku, fillet, maupun dalam bentuk olahan seperti kaleng. Proses ekspor tuna melibatkan serangkaian tahapan mulai dari penangkapan, penanganan pasca tangkap, pengolahan, hingga pengemasan dan pengiriman yang harus memenuhi standar mutu dan keamanan pangan internasional.</p><p>\r\n\r\n</p><p data-start=\"1069\" data-end=\"1490\">Ekspor ikan tuna tidak hanya memberikan kontribusi terhadap pendapatan negara dan devisa, tetapi juga membuka peluang kerja bagi masyarakat pesisir, pelaku usaha perikanan, dan industri pengolahan hasil laut. Namun demikian, tantangan seperti overfishing, keberlanjutan sumber daya, dan regulasi perdagangan internasional menjadi isu penting yang harus diperhatikan agar ekspor tuna tetap berkelanjutan dan berdaya saing.</p>', '2021-07-02', '2025-08-02', '2025-08-02 22:26:05', '2025-08-02 22:26:05');
INSERT INTO `tenant` VALUES (5876, 64, 'public/foto_profil_tenant/688e2f1e9b1e1.jpeg', 'CV ANUGERAH SAHHID', 'Nurdaniah Mustika', 4, 2, 'Labuhan Lombok Pringgabaya, Kab. Lombok Timur, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"105\" data-end=\"571\">Ekspor ikan laut merupakan kegiatan perdagangan internasional yang melibatkan penjualan dan pengiriman berbagai jenis ikan hasil tangkapan dari laut ke negara lain. Indonesia, sebagai negara kepulauan dengan garis pantai terpanjang kedua di dunia, memiliki potensi besar dalam sektor perikanan laut. Produk ikan laut yang diekspor umumnya meliputi tuna, cakalang, tongkol, kerapu, kakap, dan berbagai jenis ikan hias serta produk olahan seperti fillet dan ikan beku.</p><p data-start=\"573\" data-end=\"1045\">Kegiatan ekspor ikan laut tidak hanya menjadi salah satu sumber devisa negara, tetapi juga membuka peluang kerja, mendukung pertumbuhan ekonomi pesisir, serta memperkuat posisi Indonesia dalam rantai pasok global sektor perikanan. Untuk menjaga kualitas dan daya saing produk ekspor, proses penangkapan, penanganan, pengolahan, hingga distribusi dilakukan dengan memperhatikan standar mutu internasional, termasuk aspek keberlanjutan dan ketelusuran produk (traceability).</p><p>\r\n\r\n</p><p data-start=\"1047\" data-end=\"1301\">Pemerintah, melalui Kementerian Kelautan dan Perikanan (KKP), terus mendorong peningkatan volume dan nilai ekspor ikan laut melalui berbagai kebijakan, termasuk penguatan infrastruktur perikanan, pemberdayaan nelayan, serta diplomasi pasar internasional.</p>', '2025-08-02', '2025-08-02', '2025-08-02 22:30:38', '2025-08-02 22:30:38');
INSERT INTO `tenant` VALUES (5877, 64, 'public/foto_profil_tenant/688e305f4b7d5.jpeg', 'CV. LOBSTER ORIGIN PARADISE', 'MARSYA', 4, 2, 'Raya Sengkerang Street, Ganti, Praya Timur, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"168\" data-end=\"531\">Ekspor lobster merupakan salah satu kegiatan perdagangan internasional yang memiliki nilai ekonomi tinggi, terutama bagi negara-negara penghasil komoditas laut seperti Indonesia. Lobster termasuk produk perikanan bernilai premium yang banyak diminati di pasar global, terutama di negara-negara seperti Tiongkok, Amerika Serikat, Jepang, dan beberapa negara Eropa.</p><p data-start=\"533\" data-end=\"1000\">Kegiatan ekspor lobster melibatkan berbagai tahapan mulai dari penangkapan atau budidaya, pemilihan kualitas (grading), pengemasan, hingga pengiriman menggunakan metode khusus untuk menjaga kesegaran, baik dalam bentuk hidup (live lobster) maupun beku (frozen lobster). Di Indonesia, ekspor lobster diatur secara ketat oleh pemerintah melalui Kementerian Kelautan dan Perikanan (KKP), untuk menjamin keberlanjutan sumber daya laut dan mencegah eksploitasi berlebihan.</p><p data-start=\"1002\" data-end=\"1299\">Potensi ekspor lobster sangat besar karena permintaan dunia terus meningkat. Namun, tantangan yang dihadapi antara lain adalah regulasi ekspor yang ketat, isu keberlanjutan dan konservasi, serta kebutuhan akan peningkatan teknologi budidaya dan logistik agar produk dapat bersaing di pasar global.</p><p>\r\n\r\n\r\n</p><p data-start=\"1301\" data-end=\"1478\">Dengan pengelolaan yang tepat, ekspor lobster dapat menjadi sumber devisa negara yang signifikan sekaligus mendorong pertumbuhan ekonomi pesisir dan kesejahteraan nelayan lokal.</p>', '2025-08-02', '2025-08-02', '2025-08-02 22:35:59', '2025-08-02 22:35:59');
INSERT INTO `tenant` VALUES (5878, 64, 'public/foto_profil_tenant/688e323491717.jpeg', 'PT. RAZINDO GLOBAL NUSANTARA', 'CICI', 14, 2, 'Lombok  Timur, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"149\" data-end=\"562\"><strong data-start=\"149\" data-end=\"164\">Rumput laut</strong> adalah sejenis tumbuhan laut yang termasuk dalam kelompok alga, yang tumbuh di perairan laut dangkal maupun dalam. Organisme ini memiliki struktur tubuh yang sederhana tanpa akar, batang, dan daun sejati, namun berfungsi efektif dalam proses fotosintesis. Rumput laut memainkan peran penting dalam ekosistem laut sebagai produsen primer, penyedia oksigen, dan habitat bagi berbagai organisme laut.</p><p data-start=\"564\" data-end=\"681\">Secara umum, rumput laut dibagi menjadi tiga kelompok utama berdasarkan pigmen dominan dan kandungan kimianya, yaitu:</p><ol data-start=\"682\" data-end=\"937\">\r\n<li data-start=\"682\" data-end=\"754\">\r\n<p data-start=\"685\" data-end=\"754\"><strong data-start=\"685\" data-end=\"713\">Alga Hijau (Chlorophyta)</strong> – umumnya ditemukan di perairan dangkal.</p>\r\n</li>\r\n<li data-start=\"755\" data-end=\"843\">\r\n<p data-start=\"758\" data-end=\"843\"><strong data-start=\"758\" data-end=\"787\">Alga Cokelat (Phaeophyta)</strong> – sering tumbuh di zona pasang surut hingga laut dalam.</p>\r\n</li>\r\n<li data-start=\"844\" data-end=\"937\">\r\n<p data-start=\"847\" data-end=\"937\"><strong data-start=\"847\" data-end=\"874\">Alga Merah (Rhodophyta)</strong> – memiliki kemampuan hidup di kedalaman laut yang lebih besar.</p>\r\n</li>\r\n</ol><p data-start=\"939\" data-end=\"1215\">Selain nilai ekologis, rumput laut juga memiliki <strong data-start=\"988\" data-end=\"1017\">nilai ekonomi yang tinggi</strong>. Di berbagai negara, termasuk Indonesia, rumput laut dibudidayakan untuk diolah menjadi berbagai produk seperti agar-agar, karaginan, kosmetik, pangan fungsional, serta bahan baku industri farmasi.</p><p>\r\n\r\n\r\n\r\n</p><p data-start=\"1217\" data-end=\"1539\">Rumput laut tumbuh dengan cepat dan tidak memerlukan lahan subur, sehingga menjadi alternatif komoditas pertanian laut yang ramah lingkungan dan berkelanjutan. Dengan dukungan teknologi dan pengelolaan yang tepat, potensi rumput laut dapat dikembangkan sebagai sumber daya hayati unggulan di sektor kelautan dan perikanan.</p>', '2025-08-02', '2025-08-02', '2025-08-02 22:43:48', '2025-08-02 22:43:48');
INSERT INTO `tenant` VALUES (5879, 64, 'public/foto_profil_tenant/688e338098371.jpeg', 'UD, ANA PEARLS', 'TASWIANA', 47, 1, 'Jl. Sultan Kaharudin Gang Al-Jabar No. Sekarbela, Mataram, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"183\" data-end=\"581\">Mutiara Lombok merupakan salah satu komoditas unggulan dari Provinsi Nusa Tenggara Barat (NTB), khususnya dari Pulau Lombok. Dikenal akan kualitasnya yang tinggi dan kilauannya yang alami, mutiara hasil budidaya di perairan sekitar Lombok, terutama jenis <strong data-start=\"438\" data-end=\"480\">South Sea Pearl (mutiara laut selatan)</strong>, telah berhasil menembus pasar internasional dan menjadi salah satu produk ekspor andalan Indonesia.</p><p data-start=\"583\" data-end=\"960\">Proses budidaya mutiara di Lombok dilakukan secara profesional dan berkelanjutan, dengan mempertimbangkan kelestarian lingkungan laut. Para petani mutiara di daerah ini memanfaatkan kondisi laut yang bersih dan kaya akan plankton untuk menghasilkan mutiara berkualitas premium, yang banyak diminati di pasar global seperti Jepang, Hong Kong, Australia, dan negara-negara Eropa.</p><p data-start=\"962\" data-end=\"1338\">Ekspor mutiara Lombok tidak hanya memberikan kontribusi ekonomi bagi daerah, tetapi juga membuka lapangan kerja bagi masyarakat pesisir dan meningkatkan pendapatan daerah melalui sektor perikanan dan kelautan. Pemerintah daerah bersama pelaku usaha juga aktif dalam mempromosikan mutiara Lombok melalui pameran internasional, festival budaya, dan kemitraan dagang luar negeri.</p><p>\r\n\r\n\r\n</p><p data-start=\"1340\" data-end=\"1513\">Dengan kualitas yang diakui secara global, potensi ekspor mutiara Lombok terus berkembang, menjadikannya simbol keindahan alam Indonesia yang bernilai tinggi di pasar dunia.</p>', '2025-08-02', '2025-08-02', '2025-08-02 22:49:20', '2025-08-02 22:49:20');
INSERT INTO `tenant` VALUES (5880, 64, 'public/foto_profil_tenant/688e345e67104.jpeg', 'UD. INDAH MUTIARA LOMBOK', 'INDAH PURWATI NINGSIH', 47, 1, 'Jl. Bung Karno Ruko No. 2 (Utara RS Kota Mataram), Mataram, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"183\" data-end=\"581\">Mutiara Lombok merupakan salah satu komoditas unggulan dari Provinsi Nusa Tenggara Barat (NTB), khususnya dari Pulau Lombok. Dikenal akan kualitasnya yang tinggi dan kilauannya yang alami, mutiara hasil budidaya di perairan sekitar Lombok, terutama jenis <strong data-start=\"438\" data-end=\"480\">South Sea Pearl (mutiara laut selatan)</strong>, telah berhasil menembus pasar internasional dan menjadi salah satu produk ekspor andalan Indonesia.</p><p data-start=\"583\" data-end=\"960\">Proses budidaya mutiara di Lombok dilakukan secara profesional dan berkelanjutan, dengan mempertimbangkan kelestarian lingkungan laut. Para petani mutiara di daerah ini memanfaatkan kondisi laut yang bersih dan kaya akan plankton untuk menghasilkan mutiara berkualitas premium, yang banyak diminati di pasar global seperti Jepang, Hong Kong, Australia, dan negara-negara Eropa.</p><p data-start=\"962\" data-end=\"1338\">Ekspor mutiara Lombok tidak hanya memberikan kontribusi ekonomi bagi daerah, tetapi juga membuka lapangan kerja bagi masyarakat pesisir dan meningkatkan pendapatan daerah melalui sektor perikanan dan kelautan. Pemerintah daerah bersama pelaku usaha juga aktif dalam mempromosikan mutiara Lombok melalui pameran internasional, festival budaya, dan kemitraan dagang luar negeri.</p><p>\r\n\r\n\r\n</p><p data-start=\"1340\" data-end=\"1513\">Dengan kualitas yang diakui secara global, potensi ekspor mutiara Lombok terus berkembang, menjadikannya simbol keindahan alam Indonesia yang bernilai tinggi di pasar dunia.</p>', '2025-08-02', '2025-08-02', '2025-08-02 22:53:02', '2025-08-02 22:53:02');
INSERT INTO `tenant` VALUES (5881, 64, 'public/foto_profil_tenant/688e35697ccca.jpeg', 'LAMOPS CRAFTWORKS', 'LAMOPS', 47, 1, 'Jl. Pariwisata no. 14 Meninting, Batulayar, Lombok Barat, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"203\" data-end=\"607\">Ekspor kerajinan (craft) merupakan kegiatan perdagangan internasional yang melibatkan pengiriman produk-produk kerajinan tangan dari suatu negara ke pasar luar negeri. Produk kerajinan yang diekspor umumnya mencerminkan kekayaan budaya, nilai estetika, dan keterampilan lokal yang tinggi, seperti anyaman, batik, ukiran kayu, keramik, perhiasan etnik, tekstil tradisional, serta produk dekoratif lainnya.</p><p data-start=\"609\" data-end=\"966\">Indonesia sebagai negara dengan keanekaragaman budaya yang luas memiliki potensi besar dalam industri kerajinan. Produk kerajinan Indonesia banyak diminati di pasar global karena memiliki ciri khas, keunikan desain, dan kualitas buatan tangan yang tinggi. Negara tujuan utama ekspor craft Indonesia antara lain Amerika Serikat, Eropa, Jepang, dan Australia.</p><p data-start=\"968\" data-end=\"1385\">Selain berkontribusi terhadap devisa negara, ekspor kerajinan juga berperan penting dalam membuka lapangan kerja, terutama di sektor Usaha Mikro, Kecil, dan Menengah (UMKM), serta mendorong pelestarian budaya lokal. Namun demikian, tantangan seperti standar kualitas internasional, tren desain global, dan persaingan harga dari negara lain juga harus dihadapi dengan strategi inovasi dan penguatan kapasitas produksi.</p><p>\r\n\r\n\r\n</p><p data-start=\"1387\" data-end=\"1581\">Dengan dukungan promosi, pelatihan, dan akses pasar yang memadai, ekspor kerajinan dapat terus tumbuh sebagai sektor unggulan dalam memperkenalkan identitas budaya bangsa ke dunia internasional.</p>', '2025-08-02', '2025-08-02', '2025-08-02 22:57:29', '2025-08-02 22:57:29');
INSERT INTO `tenant` VALUES (5882, 64, 'public/foto_profil_tenant/688e3676c1ea3.jpeg', 'UD. BAMBU RINJANI', 'MAHUNI', 47, 1, 'Karang Sidemen, Lombok Tengah, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"161\" data-end=\"545\">Ekspor bambu merupakan salah satu sektor potensial dalam perdagangan internasional yang berasal dari komoditas alam terbarukan. Bambu dikenal sebagai tanaman multifungsi yang memiliki nilai ekonomi tinggi, digunakan dalam berbagai industri seperti konstruksi, kerajinan tangan, mebel, tekstil, hingga bahan baku ramah lingkungan untuk produk modern seperti bioplastik dan arang aktif.</p><p data-start=\"547\" data-end=\"869\">Indonesia, sebagai salah satu negara dengan keanekaragaman hayati tertinggi di dunia, memiliki lebih dari 160 jenis bambu yang tersebar di berbagai daerah. Potensi ini menjadikan Indonesia sebagai salah satu eksportir bambu dan produk turunannya ke berbagai negara seperti Jepang, Amerika Serikat, Uni Eropa, dan Tiongkok.</p><p data-start=\"871\" data-end=\"1188\">Proses ekspor bambu mencakup beberapa tahapan, mulai dari pemanenan, pengolahan, pengawetan, hingga pengemasan dan pengiriman. Untuk memenuhi standar internasional, produk bambu ekspor harus memenuhi persyaratan kualitas, ketahanan terhadap hama, serta sertifikasi lingkungan seperti FSC (Forest Stewardship Council).</p><p>\r\n\r\n\r\n</p><p data-start=\"1190\" data-end=\"1418\">Ekspor bambu tidak hanya memberikan kontribusi terhadap devisa negara, tetapi juga mendorong pertumbuhan ekonomi pedesaan, membuka lapangan kerja, serta menjaga kelestarian lingkungan melalui praktik budidaya yang berkelanjutan.</p>', '2025-08-02', '2025-08-02', '2025-08-02 23:01:58', '2025-08-02 23:01:58');
INSERT INTO `tenant` VALUES (5883, 64, 'public/foto_profil_tenant/688ed00b5935a.jpeg', 'UD NUSA INDAH', 'AWIDI', 47, 1, 'Jl. Pramuka No 1, Desa Karang Bayan, Kec. Lingsar, Kab. Lombok Barat, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"194\" data-end=\"632\">Ekspor kerajinan rotan merupakan salah satu sektor unggulan dalam industri kreatif yang memiliki nilai ekonomi tinggi serta daya saing global. Kerajinan rotan Indonesia dikenal luas karena kualitasnya yang tinggi, desainnya yang artistik, serta keberlanjutannya yang ramah lingkungan. Produk-produk kerajinan ini mencakup berbagai bentuk seperti furnitur (meja, kursi, lemari), dekorasi rumah, keranjang, hingga aksesori interior lainnya.</p><p data-start=\"634\" data-end=\"1017\">Indonesia, sebagai salah satu produsen rotan terbesar di dunia, memiliki potensi besar dalam memenuhi permintaan pasar internasional, terutama di negara-negara Eropa, Amerika Serikat, Jepang, dan Timur Tengah. Keunggulan bahan baku rotan alami yang tumbuh subur di berbagai wilayah seperti Kalimantan, Sulawesi, dan Sumatera, memberikan nilai tambah tersendiri dalam proses produksi.</p><p>\r\n\r\n</p><p data-start=\"1019\" data-end=\"1390\">Ekspor kerajinan rotan tidak hanya berkontribusi pada peningkatan devisa negara, tetapi juga membuka peluang kerja dan meningkatkan kesejahteraan masyarakat di daerah penghasil rotan. Untuk menjaga daya saing global, pelaku industri rotan terus berinovasi dalam desain, menerapkan standar kualitas ekspor, serta memperhatikan aspek keberlanjutan dalam proses produksinya.</p>', '2025-08-03', '2025-08-03', '2025-08-03 09:57:15', '2025-08-03 09:57:15');
INSERT INTO `tenant` VALUES (5884, 64, 'public/foto_profil_tenant/688ed15806348.jpeg', 'UD HANUMAN CRAFT', 'M. PUTRA SAHBAN', 47, 1, 'Jl. DR Wahidin 54 Rembiga, Kec. Selaparang, Mataram, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"231\" data-end=\"556\"><strong data-start=\"231\" data-end=\"248\">Hanuman Craft</strong> adalah produsen dan eksportir kerajinan rotan berkualitas tinggi yang berlokasi di Indonesia, pusat kerajinan alam yang telah diakui dunia. Dengan mengusung nilai tradisional yang dipadukan dengan sentuhan desain modern, Hanuman Craft menghadirkan berbagai produk rotan yang ramah lingkungan dan fungsional.</p><p data-start=\"558\" data-end=\"880\">Fokus utama kami adalah menyediakan <strong data-start=\"594\" data-end=\"619\">produk rotan handmade</strong> seperti kursi, meja, keranjang, lampu gantung, rak, dan berbagai aksesoris rumah lainnya yang dibuat oleh pengrajin lokal berpengalaman. Setiap produk kami mencerminkan keindahan alami bahan rotan serta keterampilan tangan yang diwariskan secara turun-temurun.</p><p data-start=\"882\" data-end=\"1205\">Kami telah mengekspor ke berbagai negara di Asia, Eropa, dan Amerika, dengan tetap menjaga standar mutu internasional dan keberlanjutan bahan baku. Hanuman Craft berkomitmen untuk memberikan layanan ekspor yang profesional, mulai dari proses pemesanan, pengepakan, hingga pengiriman internasional yang aman dan tepat waktu.</p><p data-start=\"1207\" data-end=\"1236\"><strong data-start=\"1207\" data-end=\"1236\">Keunggulan Hanuman Craft:</strong></p><ul data-start=\"1237\" data-end=\"1496\">\r\n<li data-start=\"1237\" data-end=\"1298\">\r\n<p data-start=\"1239\" data-end=\"1298\">Produk handmade dari bahan rotan alami berkualitas tinggi</p>\r\n</li>\r\n<li data-start=\"1299\" data-end=\"1355\">\r\n<p data-start=\"1301\" data-end=\"1355\">Desain unik dan eksklusif yang mengikuti tren global</p>\r\n</li>\r\n<li data-start=\"1356\" data-end=\"1394\">\r\n<p data-start=\"1358\" data-end=\"1394\">Ramah lingkungan dan berkelanjutan</p>\r\n</li>\r\n<li data-start=\"1395\" data-end=\"1440\">\r\n<p data-start=\"1397\" data-end=\"1440\">Layanan ekspor profesional dan terpercaya</p>\r\n</li>\r\n<li data-start=\"1441\" data-end=\"1496\">\r\n<p data-start=\"1443\" data-end=\"1496\">Fleksibel untuk permintaan desain custom dan branding</p>\r\n</li>\r\n</ul><p>\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"1498\" data-end=\"1649\"><strong data-start=\"1498\" data-end=\"1511\">Visi kami</strong> adalah menjadi duta produk rotan Indonesia di pasar global dengan tetap memberdayakan pengrajin lokal dan menjaga kelestarian lingkungan.</p>', '2025-08-03', '2025-08-03', '2025-08-03 10:02:48', '2025-08-03 10:02:48');
INSERT INTO `tenant` VALUES (5885, 64, 'public/foto_profil_tenant/688ed232b2eae.jpeg', 'UD GOOD CRAFT', 'GILANG', 47, 1, 'Jl. Kudus 19E BTN Tanah Haji, Mataram, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"227\" data-end=\"577\"><strong data-start=\"227\" data-end=\"241\">GOOD CRAFT</strong> adalah produsen dan eksportir kerajinan rotan berkualitas tinggi yang menggabungkan keahlian tradisional dengan desain kontemporer. Berbasis di Indonesia, negara yang dikenal sebagai salah satu penghasil rotan terbaik di dunia, GOOD CRAFT menghadirkan produk-produk rotan yang ramah lingkungan, estetis, dan fungsional ke pasar global.</p><p data-start=\"579\" data-end=\"858\">Produk kami meliputi berbagai jenis furnitur rotan, seperti kursi, meja, rak, dan keranjang, hingga aksesori interior yang bernuansa etnik-modern. Setiap produk dibuat oleh pengrajin lokal berpengalaman menggunakan bahan rotan pilihan yang diproses secara etis dan berkelanjutan.</p><p data-start=\"860\" data-end=\"893\"><strong data-start=\"860\" data-end=\"893\">Keunggulan Ekspor GOOD CRAFT:</strong></p><ul data-start=\"894\" data-end=\"1483\">\r\n<li data-start=\"894\" data-end=\"1019\">\r\n<p data-start=\"896\" data-end=\"1019\"><strong data-start=\"896\" data-end=\"916\">Kualitas Ekspor:</strong> Standar mutu tinggi untuk pasar internasional, dengan kontrol kualitas ketat di setiap tahap produksi.</p>\r\n</li>\r\n<li data-start=\"1020\" data-end=\"1109\">\r\n<p data-start=\"1022\" data-end=\"1109\"><strong data-start=\"1022\" data-end=\"1043\">Desain Eksklusif:</strong> Kombinasi antara desain modern dan sentuhan etnik khas Indonesia.</p>\r\n</li>\r\n<li data-start=\"1110\" data-end=\"1243\">\r\n<p data-start=\"1112\" data-end=\"1243\"><strong data-start=\"1112\" data-end=\"1133\">Ramah Lingkungan:</strong> Menggunakan bahan baku alami yang dapat diperbarui dan proses produksi yang mendukung kelestarian lingkungan.</p>\r\n</li>\r\n<li data-start=\"1244\" data-end=\"1332\">\r\n<p data-start=\"1246\" data-end=\"1332\"><strong data-start=\"1246\" data-end=\"1269\">Kustomisasi Produk:</strong> Melayani pesanan khusus sesuai dengan permintaan pasar ekspor.</p>\r\n</li>\r\n<li data-start=\"1333\" data-end=\"1483\">\r\n<p data-start=\"1335\" data-end=\"1483\"><strong data-start=\"1335\" data-end=\"1356\">Jangkauan Global:</strong> Telah menembus pasar Asia, Eropa, Australia, dan Amerika melalui kerja sama dengan distributor dan platform e-commerce global.</p>\r\n</li>\r\n</ul><p>\r\n\r\n\r\n\r\n</p><p data-start=\"1485\" data-end=\"1654\">Dengan komitmen terhadap kualitas, keberlanjutan, dan inovasi desain, GOOD CRAFT terus memperkuat posisinya sebagai mitra tepercaya dalam industri kerajinan rotan dunia.</p>', '2025-08-03', '2025-08-03', '2025-08-03 10:06:26', '2025-08-03 10:06:26');
INSERT INTO `tenant` VALUES (5886, 64, 'public/foto_profil_tenant/688ed3ae2ffbb.jpeg', 'NYALAKOK TENUN', 'INDAH RACHMAWATI MUSTIRIN', 47, 1, 'Kembang Kerang Desa Daye, Kec. Aikmel, Kab. Lombok Timur, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"200\" data-end=\"498\"><strong data-start=\"200\" data-end=\"218\">NYALAKOK TENUN</strong> adalah merek kerajinan tekstil khas Indonesia yang mengangkat warisan budaya tenun tradisional dari Nusa Tenggara Barat, khususnya dari Sumbawa dan Bima. Kami berkomitmen untuk melestarikan kearifan lokal melalui produk tenun tangan yang autentik, eksklusif, dan bernilai tinggi.</p><p data-start=\"500\" data-end=\"808\">Produk-produk <strong data-start=\"514\" data-end=\"532\">NYALAKOK TENUN</strong> dibuat secara handmade oleh para penenun lokal, menggunakan teknik pewarnaan alami dan motif khas yang merefleksikan filosofi dan identitas budaya setempat. Setiap lembar kain tenun merupakan hasil proses panjang yang menggabungkan ketelitian, kreativitas, dan spiritualitas.</p><p data-start=\"810\" data-end=\"1121\">Melalui kegiatan ekspor, <strong data-start=\"835\" data-end=\"853\">NYALAKOK TENUN</strong> berupaya memperkenalkan keindahan dan makna tenun Indonesia ke pasar global. Produk kami mencakup kain tenun tradisional, produk fesyen (seperti selendang, syal, dan busana siap pakai), serta produk interior seperti sarung bantal dan taplak meja yang bernuansa etnik.</p><p>\r\n\r\n\r\n</p><p data-start=\"1123\" data-end=\"1382\">Kami membuka peluang kerja sama dengan mitra internasional, desainer, dan pengusaha tekstil untuk menghadirkan produk-produk tenun premium yang berkelanjutan dan etis, dengan sistem produksi yang memperhatikan kesejahteraan penenun dan kelestarian lingkungan.</p>', '2025-08-03', '2025-08-03', '2025-08-03 10:12:46', '2025-08-03 10:12:46');
INSERT INTO `tenant` VALUES (5887, 64, 'public/foto_profil_tenant/688ed487a29ab.jpeg', 'TENUN DINA', 'DINA', 47, 1, 'Jl. Lintas Ntobo RT. 02/RW.01, Kel. Ntobo, Kota Bima, NTB, Indonesia', NULL, '100.000.000,00', 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"178\" data-end=\"516\"><strong data-start=\"178\" data-end=\"192\">Tenun Dina</strong> merupakan produk tekstil tradisional yang mengusung nilai budaya lokal dengan sentuhan desain modern. Diproduksi oleh pengrajin berpengalaman di Indonesia, khususnya dari daerah yang kaya akan warisan tenun, Tenun Dina menonjolkan keindahan motif etnik yang dibuat secara manual menggunakan alat tenun bukan mesin (ATBM).</p><p data-start=\"518\" data-end=\"824\">Produk <strong data-start=\"525\" data-end=\"539\">Tenun Dina</strong> dikenal akan kualitas benang yang unggul, ketahanan warna, serta keunikan motif yang merepresentasikan identitas budaya daerah asalnya. Kami menyediakan berbagai varian tenun yang cocok digunakan untuk busana, aksesori fashion, home decor, hingga keperluan industri kreatif lainnya.</p><p data-start=\"826\" data-end=\"1140\">Dengan kapasitas produksi yang terstandarisasi dan komitmen terhadap keberlanjutan, Tenun Dina siap memenuhi permintaan pasar internasional dengan kualitas ekspor. Kami terbuka untuk kerja sama B2B (Business to Business) maupun retail internasional, dengan sistem pengemasan aman dan pengiriman yang tepat waktu.</p><p data-start=\"1142\" data-end=\"1324\"><strong data-start=\"1142\" data-end=\"1166\">Negara tujuan ekspor</strong> meliputi: Jepang, Amerika Serikat, Eropa, dan negara-negara Asia Tenggara yang memiliki minat tinggi terhadap produk tekstil etnik dan fashion berkelanjutan.</p><p data-start=\"1326\" data-end=\"1359\"><strong data-start=\"1326\" data-end=\"1359\">Keunggulan Produk Tenun Dina:</strong></p><p>\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1360\" data-end=\"1571\">\r\n<li data-start=\"1360\" data-end=\"1401\">\r\n<p data-start=\"1362\" data-end=\"1401\">100% handmade dengan kualitas premium</p>\r\n</li>\r\n<li data-start=\"1402\" data-end=\"1446\">\r\n<p data-start=\"1404\" data-end=\"1446\">Motif eksklusif dan bernilai seni tinggi</p>\r\n</li>\r\n<li data-start=\"1447\" data-end=\"1501\">\r\n<p data-start=\"1449\" data-end=\"1501\">Ramah lingkungan dan memberdayakan pengrajin lokal</p>\r\n</li>\r\n<li data-start=\"1502\" data-end=\"1571\">\r\n<p data-start=\"1504\" data-end=\"1571\">Cocok untuk pasar fashion, dekorasi interior, dan tekstil kreatif</p></li></ul>', '2025-08-03', '2025-08-03', '2025-08-03 10:16:23', '2025-08-03 10:16:23');
INSERT INTO `tenant` VALUES (5888, 64, 'public/foto_profil_tenant/688ed6a7235eb.jpeg', 'PT MORINGA ORGANIK LOMBOK', 'EDO FREZZY', 50, 2, 'DUSUN SAMBIK 1, DESA SAMBIK ELEN, KEC. BAYAN, KAB. LOMBOK UTARA, NTB, INDONESIA', NULL, NULL, 'Media Sosial', 'Internasional', 'Pelaporan Keuangan Akutan', '<p data-start=\"208\" data-end=\"271\"><strong data-start=\"208\" data-end=\"271\">Moringa Organik Lombok - Tanaman Rempah dan Herbal Unggulan</strong></p><p data-start=\"273\" data-end=\"584\">Lombok, sebagai salah satu wilayah pertanian potensial di Indonesia, dikenal dengan kekayaan alamnya yang melimpah, termasuk tanaman rempah dan herbal berkualitas tinggi. Salah satu komoditas unggulan yang kini semakin diminati di pasar global adalah <strong data-start=\"524\" data-end=\"543\">Moringa organik</strong> atau yang dikenal dengan <strong data-start=\"569\" data-end=\"583\">daun kelor</strong>.</p><p data-start=\"586\" data-end=\"944\"><strong data-start=\"586\" data-end=\"612\">Moringa Organik Lombok</strong> dibudidayakan secara alami tanpa penggunaan pestisida atau bahan kimia sintetis, menjadikannya produk <strong data-start=\"715\" data-end=\"742\">herbal ramah lingkungan</strong> yang aman dikonsumsi dan memiliki nilai gizi tinggi. Daun Moringa mengandung berbagai zat aktif seperti vitamin A, C, E, zat besi, kalsium, dan antioksidan yang sangat bermanfaat untuk kesehatan tubuh.</p><p data-start=\"946\" data-end=\"1031\">Produk Moringa dari Lombok tersedia dalam berbagai bentuk olahan ekspor, antara lain:</p><ul data-start=\"1032\" data-end=\"1223\">\r\n<li data-start=\"1032\" data-end=\"1075\">\r\n<p data-start=\"1034\" data-end=\"1075\"><strong data-start=\"1034\" data-end=\"1075\">Daun kering utuh (whole dried leaves)</strong></p>\r\n</li>\r\n<li data-start=\"1076\" data-end=\"1121\">\r\n<p data-start=\"1078\" data-end=\"1121\"><strong data-start=\"1078\" data-end=\"1121\">Serbuk/teh moringa (moringa powder/tea)</strong></p>\r\n</li>\r\n<li data-start=\"1122\" data-end=\"1156\">\r\n<p data-start=\"1124\" data-end=\"1156\"><strong data-start=\"1124\" data-end=\"1156\">Minyak moringa (moringa oil)</strong></p>\r\n</li>\r\n<li data-start=\"1157\" data-end=\"1223\">\r\n<p data-start=\"1159\" data-end=\"1223\"><strong data-start=\"1159\" data-end=\"1223\">Ekstrak herbal untuk kebutuhan industri farmasi dan kosmetik</strong></p>\r\n</li>\r\n</ul><p data-start=\"1225\" data-end=\"1465\">Didukung oleh sistem pertanian organik tersertifikasi, pengolahan pascapanen yang higienis, dan standar mutu internasional, Moringa Organik Lombok siap memenuhi permintaan ekspor dari negara-negara di Asia, Eropa, Amerika, dan Timur Tengah.</p><p data-start=\"1467\" data-end=\"1768\">Komoditas ini tidak hanya menawarkan nilai ekonomi tinggi, tetapi juga menjadi bagian dari gaya hidup sehat global yang mengutamakan produk alami dan berkelanjutan. Selain Moringa, Lombok juga memiliki potensi ekspor besar untuk tanaman herbal lainnya seperti jahe, kunyit, temulawak, dan serai wangi.</p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"1770\" data-end=\"2054\">Dengan dukungan petani lokal yang terlatih, kerjasama koperasi, serta sistem distribusi ekspor yang efisien, <strong data-start=\"1879\" data-end=\"1905\">Moringa Organik Lombok</strong> merupakan pilihan tepat bagi mitra dagang internasional yang mengutamakan kualitas, keberlanjutan, dan kemurnian produk herbal alami dari Indonesia.</p>', '2025-08-03', '2025-08-03', '2025-08-03 10:25:27', '2025-08-03 10:25:27');
INSERT INTO `tenant` VALUES (5889, 1215, 'public/foto_profil_tenant/68902234db6c2.jpeg', 'Nurikagewacraft', 'Nurika Lestari', 48, 1, 'Dusun II Desa Perdamean Kecamatan Tanjung Morawa Kabupaten Deli Serdang', NULL, '2.000.000,00', 'shoppe,tiktiok,instagram,facebook, whatsApp,reseller,', 'Pasar Lokal', 'ada', '<p>Pengguna produk Nurikagewacraft adalah mereka yang tidak hanya mencari barang, tapi juga nilai, cerita, dan keunikan. Yang dibutuhkan adalah: Produk handmade, estetik, fungsional, ramah lingkungan, dan bisa dikustomisasi - serta mendukung produk lokal dan pemberdayaan sosial yang dapat bersaing di pasar modern.</p>', '2025-08-05', '2027-08-05', '2025-08-04 10:00:04', '2025-08-04 10:00:04');
