INSERT INTO `tenant` VALUES (5897, 1186, 'public/foto_profil_tenant/68943385f0828.jpg', 'Warung kelontong MANDIRI', 'Nur Purnomowidi Astuti', 23, 7, 'Tanjungan Ngajeg RT 06 RW 26, Tirtomartani, Kecamatan Kalasan, Kabupaten Sleman, D.I Yogyakarta', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-07 12:03:01', '2025-08-07 12:03:01');
INSERT INTO `tenant` VALUES (5898, 448, 'public/foto_profil_tenant/689ae0204a9ca.jpeg', 'Nool Upcycled Bag & Wallet', 'Elizabeth Angelina Iskandar', 47, 1, 'Denpasar, Bali', NULL, '50.000.000,00', 'Instagram, Event', 'Pasar Internasional', 'Pencatatan pada google sheet', '<p>Nool Upcycled Bag &amp; Wallet adalah tenant yang gigih dan tekun, serta memiliki kreatifitas yang tinggi. Membuat bisnis yang bernilai jual tinggi dengan memanfaatkan limbah plastik dan kain perca yang menjadi permasalahan di dunia. Beberapa pendanaan dan prestasi juga sudah pernah diraih di ajang nasional, yaitu penerima pendanaan P2MW tahapan awal tahun 2023 dan tahapan bertumbuh tahun 2024. Nool juga meraih Juara 1 Bisnis Kategori Industri Kreatif pada KMI Award 2023.</p>', '2023-07-01', '2025-01-01', '2025-08-12 13:33:04', '2025-08-12 13:33:04');
INSERT INTO `tenant` VALUES (5899, 448, 'public/foto_profil_tenant/689ae1e1d7921.JPEG', 'Gaia Loop', 'Gusti Ayu Darlia Utami', 47, 1, 'Badung, Bali', NULL, '50.000.000,00', 'Instagram dan Event', 'Pasar Internasional', 'Pencatatan pada google sheet', '<p>Gaia Loop: Transformasi Limbah Botol Plastik menjadi Kreasi Fashion yang Ramah lingkungan dan Berkelanjutan, adalah salah satu tenant dengan bisnis yang bergerak pada Industri Kreatif. Tahun 2025 menjadi awal perjalanan bagi Gaia Loop dan juga menjadi tahun keberuntungan karena Gaia memperoleh pendanaan P2MW tahap awal.</p>', '2025-01-01', '2026-12-01', '2025-08-12 13:40:33', '2025-08-12 13:40:33');
