INSERT INTO `tenant` VALUES (6095, 51, 'public/foto_profil_tenant/68df288ba2dd2.jpg', 'Lin\'s cake', 'Lina Herlina', 23, 7, 'Jl. Hj Sirun RT 5 Rw 01 No 55 Kel. Ceger', NULL, '334.148.640,00', 'Instagram, Facebook, Whatsapp Binis, dan Offline', 'Lokal Jakarta Timur', 'Manual', '<p class=\"MsoNormal\" style=\"text-align:justify;text-indent:.5in;line-height:150%\"><span lang=\"EN-ID\" style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Sejak\r\nawal berdiri, Lin’s Cake lahir dari dapur kecil dengan mimpi sederhana:\r\nmenghadirkan </span><span style=\"font-size:12.0pt;line-height:150%;font-family:\r\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-US\">sajian kuliner </span><span lang=\"EN-ID\" style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">berkualitas\r\nyang dibuat dengan cinta. Perjalanan ini membawa kami menyadari bahwa bisnis\r\ntidak hanya tentang keuntungan, tetapi juga tentang bagaimana setiap langkah\r\nproduksi memberi dampak bagi lingkungan, karyawan, dan masyarakat. Dari sanalah\r\nsemangat keberlanjutan menjadi bagian penting dari cerita kami.</span><span style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\">Capaian utama kami pada tahun ini adalah penguatan\r\nposisi produk unggulan kami, Pie Susu, yang berhasil menembus pasar lokal yang\r\nlebih luas dan mendapatkan loyalitas pelanggan yang tinggi. Kami juga\r\nberinvestasi dalam peningkatan kapasitas produksi untuk memenuhi permintaan\r\nyang terus meningkat, sambil tetap menjaga kualitas premium yang menjadi ciri\r\nkhas Lin\'s Cake. </span><span lang=\"EN-ID\" style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\">Bagi kami, setiap </span><span style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\">sajian</span><span lang=\"EN-ID\" style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\"> yang </span><span style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\">diproduksi</span><span style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\"> </span><span style=\"text-indent: 0.5in; font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif;\">bukan saja nikmat tapi juga menjaga kesehatan bagi\r\nkonsumen.</span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-indent:.5in;line-height:150%\"><span lang=\"EN-ID\" style=\"font-size:12.0pt;line-height:150%;\r\nfont-family:&quot;Times New Roman&quot;,serif\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-indent:.5in;line-height:150%\"><span lang=\"EN-ID\" style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\"><o:p></o:p></span></p>', '2025-08-03', '2025-11-30', '2025-10-03 08:36:11', '2025-10-03 08:42:02');
