INSERT INTO `tenant` VALUES (6157, 1365, 'public/foto_profil_tenant/68ef1e32855f4.png', 'SAJA', 'Grace Loekman', 20, 1, 'Jl. Kayu Putih III A No.5 5, RT.5/RW.6, Pulo Gadung, Kec. Pulo Gadung, Kota Jakarta Timur, Daerah Khusus Ibukota Jakarta 13260', NULL, NULL, 'https://www.instagram.com/sajaofficial_/?hl=id', 'Internasional', NULL, '<p><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, &quot;system-ui&quot;, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Foundational luxury footwear for living life on your own terms | As featured on InStyle, Elle, Cosmopolitan, and Harper’s Bazaar.</span></p>', '2019-05-13', '2020-12-31', '2025-10-15 11:08:18', '2025-10-15 11:08:18');
INSERT INTO `tenant` VALUES (6158, 1365, 'public/foto_profil_tenant/68ef1f88e7fdd.png', 'Ekuator Indonesia', 'Alifta Kartiko', 20, 1, 'Jl. Manyar Rejo X No.01, Menur Pumpungan, Kec. Sukolilo, Surabaya, Jawa Timur 60118', NULL, NULL, 'https://ekuatorindonesia.com/en/ekuator-footwear-indonesia-leather-shoes/', NULL, NULL, '<h2 data-start=\"179\" data-end=\"236\"><span style=\"font-size: 14px;\">Ekuator Footwear adalah brand sepatu kulit lokal Indonesia yang mengusung filosofi </span><strong data-start=\"321\" data-end=\"344\" style=\"font-size: 14px;\">“True Craftmanship”</strong><span style=\"font-size: 14px;\"> dan </span><strong data-start=\"349\" data-end=\"377\" style=\"font-size: 14px;\">komitmen kualitas tinggi.&nbsp;</strong><span style=\"font-size: 14px;\">Brand ini dirancang untuk menemani perjalanan kesuksesan penggunanya, khususnya mereka yang menghargai proses, kualitas, serta desain yang tak lekang oleh waktu.</span></h2><h2 data-start=\"179\" data-end=\"236\"><span style=\"font-size: 14px;\">Mengutamakan </span><em data-start=\"665\" data-end=\"697\" style=\"font-size: 14px;\">bahan lokal berkualitas tinggi</em><span style=\"font-size: 14px;\">, seperti kulit sapi (full grain), yang tidak hanya terlihat premium tetapi juga menjamin kenyamanan dan respirabilitas.&nbsp;</span><span style=\"font-size: 14px;\">Semua produk diproduksi di Indonesia oleh pengrajin lokal berpengalaman dengan konstruksi Goodyear Welted—metode jahitan klasik yang dikenal awet dan berkualitas standar dunia.&nbsp;</span><span style=\"font-size: 14px;\">Distribusi dijalankan secara </span><strong data-start=\"1108\" data-end=\"1130\" style=\"font-size: 14px;\">direct-to-consumer</strong><span style=\"font-size: 14px;\"> (langsung ke pembeli), tanpa perantara besar sehingga memungkinkan efisiensi harga dan menjaga eksklusivitas merek.&nbsp;</span><span style=\"font-size: 14px;\">Menyediakan </span><strong data-start=\"1301\" data-end=\"1317\" style=\"font-size: 14px;\">garansi mutu</strong><span style=\"font-size: 14px;\">, kebijakan retur &amp; pertukaran 7 hari gratis, serta layanan perawatan khusus untuk sepatu kulit.&nbsp;</span><span class=\"\" data-state=\"closed\" style=\"font-size: 14px;\"><span class=\"ms-1 inline-flex max-w-full items-center relative top-[-0.094rem] animate-[show_150ms_ease-in]\" data-testid=\"webpage-citation-pill\"></span></span></h2><h3 data-start=\"1455\" data-end=\"1487\"><br></h3><p data-start=\"1489\" data-end=\"1634\">Ekuator menawarkan koleksi sepatu kulit pria dan wanita, dengan berbagai model klasik hingga modern, namun tetap mengedepankan karakter timeless:</p><ul data-start=\"1636\" data-end=\"2055\">\r\n<li data-start=\"1636\" data-end=\"1722\">\r\n<p data-start=\"1638\" data-end=\"1722\"><strong data-start=\"1638\" data-end=\"1667\">Koleksi <em data-start=\"1648\" data-end=\"1665\">Classic / Dress</em></strong> — model formal klasik seperti derby, loafer, brogue.</p></li></ul><ul data-start=\"2414\" data-end=\"2820\"><li data-start=\"2685\" data-end=\"2820\">\r\n</li>\r\n</ul>', '2019-05-15', '2020-12-31', '2025-10-15 11:14:00', '2025-10-15 14:03:13');
INSERT INTO `tenant` VALUES (6159, 1365, 'public/foto_profil_tenant/68ef20e55ae82.png', 'Brundi.id', 'Tesa Nika, S.E', NULL, NULL, 'Taman Cibaduyut Indah blok H-6, Bandung', NULL, NULL, 'https://www.instagram.com/brundi.id/?hl=id', 'Nasional', NULL, '<h6 class=\"sr-only\">ChatGPT said:</h6><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] thread-sm:[--thread-content-margin:--spacing(6)] thread-lg:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] thread-lg:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\"><div class=\"flex max-w-full flex-col grow\"><div data-message-author-role=\"assistant\" data-message-id=\"4b823a46-b97a-4466-98bf-9012da63dd4f\" dir=\"auto\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" data-message-model-slug=\"gpt-5\"><div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\"><div class=\"markdown prose dark:prose-invert w-full break-words light markdown-new-styling\"><p data-start=\"0\" data-end=\"525\" data-is-last-node=\"\" data-is-only-node=\"\"><strong data-start=\"0\" data-end=\"13\" data-is-only-node=\"\">Brundi.id</strong> adalah brand sepatu kulit lokal yang menghadirkan koleksi <strong data-start=\"72\" data-end=\"96\">urban timeless shoes</strong> dengan sentuhan motif khas dan detail elegan. Setiap pasang sepatu Brundi dibuat dengan <strong data-start=\"185\" data-end=\"207\">kulit asli pilihan</strong> dan dikerjakan secara presisi oleh pengrajin terampil, menghasilkan produk yang tidak hanya berkarakter kuat secara visual, tetapi juga nyaman dipakai sehari-hari. Dengan gaya modern yang berpadu unsur klasik, Brundi.id menyasar individu yang menghargai keanggunan, ketahanan, dan keotentikan dalam setiap langkahnya.</p></div></div></div></div></div></div>', '2020-01-15', '2020-12-15', '2025-10-15 11:19:49', '2025-10-15 11:19:49');
INSERT INTO `tenant` VALUES (6160, 1365, 'public/foto_profil_tenant/68ef47ee6991e.jpg', 'Reisen Gear', 'Viki Dzikir Anugerah', NULL, NULL, 'Zamrud 40552 No.8, Tanimulya, Kec. Ngamprah, Kabupaten Bandung Barat, Jawa Barat 40522', NULL, NULL, 'www.reisengear.com', NULL, NULL, '<p><span id=\"docs-internal-guid-18105ada-7fff-acf5-2d2d-797d99c1bbbd\"></span></p><p dir=\"ltr\" style=\"line-height:1.2;margin-left: 36pt;margin-top:0pt;margin-bottom:0pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Reisen Gear merupakan brand Indonesia yang saat ini berfokus ke produk sepatu safety dengan model yang sporty &amp; sneaker. Dengan menggunakan komponen pelindung yang telah memenuhi standar keselamatan serta kualitas pengerjaan yang baik, juga diduukung tim yang berpengalaman pada bidangnya membuat Reisen Gear siap bersaing dengan kompetitor lain. Reisen Gear akan terus ber inovasi untuk membuat produk yang unggul dan membanggakan.</span></p>', '2020-01-15', '2021-12-31', '2025-10-15 14:06:22', '2025-10-15 14:06:22');
INSERT INTO `tenant` VALUES (6161, 1365, 'public/foto_profil_tenant/68ef4f5d1354d.png', 'Sepatu Jingga Indonesia', 'Al Padri', 20, 1, 'Jakarta Barat, Jakarta', NULL, NULL, 'https://www.instagram.com/sepatujingga/', NULL, NULL, '<p><span id=\"docs-internal-guid-deb91386-7fff-a487-4130-42e944efccb6\"></span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;margin-top:0pt;margin-bottom:10pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Jingga Indonesia&nbsp; merupakan brand lokal yang menyediakan sepatu batik dan tenun untuk&nbsp; masyarakat urban. Dalam Produksinya, sepatujingga&nbsp; Menggunakan Kain Batik Cap dan Tenun ATBM&nbsp; dengan Handmade Proses&nbsp; dengan harapan agar batik handmade proses beserta para pengrajinnya ini tetap bisa terus bertahan ditengah gempuran teknologi printing</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"><br></span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Sepatujingga ingin mengajak masyarakat Indonesia khususnya kaum muda untuk tetap mengenal, mencintai dan menjaga eksistensi kain warisan nusantara, salah satunya melalui Fashion dalam bentuk Sepatu</span></p>', '2020-01-31', '2021-12-31', '2025-10-15 14:38:05', '2025-10-15 14:38:05');
INSERT INTO `tenant` VALUES (6162, 1365, 'public/foto_profil_tenant/68ef507c96a92.jpg', 'HERMANA FOOTWEAR', 'Anggraini Hermana', 20, 1, 'Purbonegaran, Yogyakarta', NULL, NULL, 'https://www.instagram.com/hermanaboots/', NULL, NULL, '<p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:10pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">HERMANA FOOTWEAR</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> merupakan sebuah Brand Sepatu Boots Kulit Handmade dari Yogyakarta yang memiliki ciri khas, yaitu memadukan antara Style dan Art dengan menghadirkan perpaduan Premium Quality Genuine Leather dengan Wastra Nusantara Tenun Lurik Asli ATBM dari ﻿pengrajin lokal Yogyakarta. ( #supportpengrajinlokal )</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:10pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">HERMANA FOOTWEAR</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> hadir dan didesain khusus untuk mengedepankan fungsi dari sepatu boots itu sendiri, mulai dari kenyamanan hingga fleksibilitas saat dipakai dalam berbagai moment dengan mode / style khas Indonesia khususnya Jogjakarta.</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:10pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Selain itu, tujuan utama dari dihadirkannya </span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">HERMANA FOOTWEAR</span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> adalah untuk mengembangkan potensi warisan budaya Bangsa Indonesia, yaitu dengan memperkenalkan produk karya anak bangsa ke kancah internasional serta menggandeng masyarakat internasional untuk turut bangga memakai produk Indonesia seperti hal nya sebagian dari masyarakat Indonesia yang bangga ketika mengenakan produk mancanegara. Kami memiliki harapan kedepan, yaitu membuat masyarakat Indonesia menjadi lebih bangga ketika memakai produk Karya Anak Bangsa.</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;margin-top:0pt;margin-bottom:10pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">HERMANA FOOTWEAR </span><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">saat ini hadir dalam 4 spesifikasi custom product, yaitu :</span></p><p><span id=\"docs-internal-guid-69c31674-7fff-e136-7386-c68d847b330a\"></span></p><ol style=\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\"><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.3800000000000001;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">RH Fashion Boots</span></p></li><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.3800000000000001;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Customized Shoefinished Boots</span></p></li><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.3800000000000001;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Cowboy and Bikers Boots</span></p></li><li dir=\"ltr\" style=\"list-style-type:decimal;font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.3800000000000001;margin-top:0pt;margin-bottom:10pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Horseback Archery Boots</span></p></li></ol>', '2020-01-15', '2021-12-15', '2025-10-15 14:42:52', '2025-10-15 14:42:52');
INSERT INTO `tenant` VALUES (6163, 1365, 'public/foto_profil_tenant/68ef51baf2010.jpeg', 'Jaksole', 'Rachmat Agung Santosa', 20, 1, 'Business Park, CIBIS, Jl. Raya Cilandak KKO, RT.13/RW.5, Cilandak Tim., Ps. Minggu, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12560', NULL, NULL, 'https://www.instagram.com/jaksole.id/?hl=en', NULL, NULL, '<p><span id=\"docs-internal-guid-78342b14-7fff-e4db-9cbe-bc2279949ef7\"></span></p><p dir=\"ltr\" style=\"line-height:1.2;margin-left: 21.3pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\"><span style=\"font-size:11pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Produk Insole dan Sandal Custom yang dibuat secara khusus perindividu dimulai dengan cara process foot scanning kaki customer, pembuatan insole custom mengunakan mesin CNC dari data hasil foot scanning, pembuatan upper sandal sesuai kebutuhan dan pemakaian bahan yang tepat dengan kualitas yang baik</span></p>', '2020-01-15', '2021-12-15', '2025-10-15 14:48:10', '2025-10-15 14:48:10');
INSERT INTO `tenant` VALUES (6164, 1365, 'public/foto_profil_tenant/68ef52c014d85.jpg', 'PANNA FOOTWEAR', 'Kamalludin', 20, 1, 'Bandung, Jawa Barat', NULL, NULL, 'https://www.instagram.com/panna.footwear/?hl=en', NULL, NULL, NULL, '2021-03-15', '2022-12-31', '2025-10-15 14:52:32', '2025-10-15 14:52:32');
INSERT INTO `tenant` VALUES (6165, 1365, 'public/foto_profil_tenant/68ef5a61575d5.png', 'Steward Margrave', 'Philby Permadi', 20, 1, 'Jl. Cibaduyut No.84, Cibaduyut, Kec. Bojongloa Kidul, Kota Bandung, Jawa Barat 40236', NULL, NULL, 'https://www.instagram.com/stewardmargrave/?hl=id', NULL, NULL, '<p><span data-huuid=\"5497239694089811791\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\">Steward Margrave adalah&nbsp;<mark class=\"QVRyCf\" style=\"background: linear-gradient(90deg, rgb(212, 228, 242) 50%, rgba(0, 0, 0, 0) 50%) 75% 0px / 200% 100% no-repeat scroll padding-box border-box rgba(0, 0, 0, 0); border-radius: 4px; padding: 0px 2px; animation: 0.75s cubic-bezier(0.05, 0.7, 0.1, 1) 0.25s 1 normal forwards running highlight-animation;\">merek sepatu kulit asli asal Bandung yang fokus memproduksi sepatu untuk riding (berkendara dengan motor)</mark>.&nbsp;</span><span data-huuid=\"5497239694089813348\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\">Sepatu ini dirancang dengan desain yang keren dan mengutamakan kenyamanan, bahkan saat digunakan dalam waktu lama saat berkendara.&nbsp;</span><span data-huuid=\"5497239694089810809\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\">Merek ini menggunakan bahan kulit sapi asli dan outsole karet untuk memberikan perlindungan maksimal, dengan insole alami yang memastikan kenyamanan.<span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"42fc46db-2e11-41b4-a0c3-a0f76e9030ad\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></span></p>', '2021-02-15', '2022-12-15', '2025-10-15 15:25:05', '2025-10-15 15:25:05');
INSERT INTO `tenant` VALUES (6166, 1365, 'public/foto_profil_tenant/68ef5ae76d83a.JPG', 'Arta Louwee', 'Aprillia Hartini Eka Wulandari', 20, 1, 'Jalan Raya Dermo No.91 Kel. Mulyoagung Kec. Dau Kab. Malang 65151', NULL, NULL, NULL, NULL, NULL, '<p><div class=\"A6K0A\" data-rpos=\"60\" style=\"color: rgb(31, 31, 31); font-family: Arial, sans-serif; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"xfX4Ac JI5uCe qB9BY yWNJXb tQtKhb\" jsdata=\"PhoHd;_;2FrvaI-WNuquseMP3NipOA59\" data-hveid=\"CE0QAA\" data-ved=\"2ahUKEwiP4t-f5KWQAxVqV2wGHVxsCgcQubsFKAB6BAhNEAA\" style=\"font-size: 14px; margin: 30px 0px;\"><div jsname=\"xQjRM\"><div class=\"JCZQSb\"><div><div><div jscontroller=\"SC7lYd\" class=\"wHYlTd Ww4FFb tF2Cxc asEBEc vt6azd\" lang=\"id\" jsaction=\"QyLbLe:OMITjf;ewaord:qsYrDe;xd28Mb:A6j43c\" data-hveid=\"CEEQAA\" data-ved=\"2ahUKEwiP4t-f5KWQAxVqV2wGHVxsCgcQFSgAegQIQRAA\" style=\"position: relative; font-family: Arial, sans-serif; font-size: 14px; line-height: 22px; margin: 0px 0px 30px; border-radius: 0px; border-width: 0px; background-color: rgb(255, 255, 255); box-shadow: none; max-width: 100%; width: inherit;\"><div class=\"N54PNb BToiNc\" data-snc=\"iV2uJb\" style=\"display: flex; flex-direction: column; justify-content: start; position: relative;\"><div class=\"kb0PBd A9Y9g jGGQ5e\" data-snf=\"x5WNvb\" data-snhf=\"0\" style=\"display: block; flex: 1 1 100%; min-width: 0px;\"><div class=\"yuRUbf\" style=\"font-weight: normal; font-size: small; line-height: 1.58;\"><div class=\"b8lM7\" style=\"display: flex; flex-direction: column-reverse;\"></div></div></div></div></div></div></div></div></div></div></div></p><div class=\"A6K0A\" data-rpos=\"59\" style=\"color: rgb(31, 31, 31); font-family: Arial, sans-serif; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"xfX4Ac JI5uCe qB9BY yWNJXb tQtKhb\" jsdata=\"PhoHd;_;2FrvaI-WNuquseMP3NipOA59\" data-hveid=\"CEwQAA\" data-ved=\"2ahUKEwiP4t-f5KWQAxVqV2wGHVxsCgcQubsFKAB6BAhMEAA\" style=\"font-size: 14px; margin: 30px 0px;\"><div jsname=\"xQjRM\"><div class=\"JCZQSb\"><div><div><div jscontroller=\"SC7lYd\" class=\"wHYlTd Ww4FFb tF2Cxc asEBEc vt6azd\" lang=\"id\" jsaction=\"QyLbLe:OMITjf;ewaord:qsYrDe;xd28Mb:A6j43c\" data-hveid=\"CDkQAA\" data-ved=\"2ahUKEwiP4t-f5KWQAxVqV2wGHVxsCgcQFSgAegQIORAA\" style=\"position: relative; font-family: Arial, sans-serif; font-size: 14px; line-height: 22px; margin: 0px 0px 30px; border-radius: 0px; border-width: 0px; background-color: rgb(255, 255, 255); box-shadow: none; max-width: 100%; width: inherit;\"><div class=\"N54PNb BToiNc\" data-snc=\"Qwk84\" style=\"display: flex; flex-direction: column; justify-content: start; position: relative;\"><div class=\"kb0PBd A9Y9g\" data-snf=\"nke7rc\" data-sncf=\"1\" style=\"display: block; flex: 1 1 100%; min-width: 0px;\"><div class=\"VwiC3b yXK7lf p4wth r025kc Hdw6tb\" style=\"font-family: Arial, sans-serif; font-size: 14px; font-weight: 400; line-height: 22px; color: rgb(71, 71, 71); word-break: break-word; display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden; -webkit-line-clamp: 2;\"><span><em style=\"font-weight: bold; font-style: normal; color: rgb(118, 118, 118);\">Arta Louwee</em><span>&nbsp;</span>sebuah artisan brand yg membuat produk sepatu boot wanita, sepatu Oxford wanita &amp; tas wanita dari bahan kulit untuk high class female.</span></div></div></div></div></div></div></div></div></div></div>', '2021-03-15', '2022-12-15', '2025-10-15 15:27:19', '2025-10-15 15:27:19');
INSERT INTO `tenant` VALUES (6167, 1365, 'public/foto_profil_tenant/68ef5c00ba009.png', 'Duffel Footwear', 'Mohamad Angga Barokah', 20, 1, 'Rancaekek, Kabupaten Bandung', NULL, NULL, NULL, NULL, NULL, '<p>DUFFEL Footwear adalah sebuah merek yang berasal dari Bandung, Indonesia. Dibentuk oleh Mohamad Angga dan Renie didasari oleh kecintaan pada dunia fashion dan Skateboarding, juga dimulai dari keresahan kami akan ketertinggalan produk fashion lokal oleh brand luar, dan stigma masyarakat akan ketertinggalan produk lokal, maka kami berusaha untuk menjadikan DUFFEL sebagai salah satu brand lokal yang dapat menyaingi produk luar baik dari segi branding dan produk yang dihasilkan, dengan harapan nantinya brand lokal akan dapat terangkat pamornya di negeri sendiri dan merubah stigma masyarakat tentang produk brand lokal itu sendiri.</p>', '2021-03-15', '2022-12-15', '2025-10-15 15:32:00', '2025-10-15 15:32:00');
INSERT INTO `tenant` VALUES (6168, 1365, 'public/foto_profil_tenant/68f050e1ed81a.png', 'HETERIX', 'Junius Sanjaya', 20, 1, 'Jl Merdeka Gg Bayan No 9, Pontianak Kota, Kalimantan Barat', NULL, NULL, 'https://www.instagram.com/heterix/?hl=id', NULL, NULL, '<p><strong data-start=\"131\" data-end=\"156\">Heterix Leather Goods</strong> adalah brand asal Pontianak yang berfokus pada pembuatan produk kulit handmade dengan desain fungsional dan tampilan minimalis. Heterix menghadirkan berbagai produk seperti sandal/sepatu, strap, keychain, charm, hingga aksesori berbahan kulit dengan kualitas tinggi dan detail presisi. Tidak hanya menjual produk yang sudah tersedia, Heterix juga membuka kesempatan custom order untuk membantu pelanggan mewujudkan ide produk kulit sesuai kebutuhan mereka.</p>', '2022-02-16', '2023-12-16', '2025-10-16 08:56:49', '2025-10-16 08:56:49');
INSERT INTO `tenant` VALUES (6169, 1365, 'public/foto_profil_tenant/68f0546e93629.png', 'UPJECT', 'Lia Nirawati', NULL, NULL, 'Dsn. Damarsi Ds. Kepuhanyar Rt. 04 Rw.01 Kec. Mojoanyar Kab. Mojokerto', NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Upject adalah brand upcycle fashion yang berfokus pada pemberdayaan limbah tekstil, terutama jeans lama pilihan, menjadi produk baru yang unik dan berkualitas. Upject mengusung konsep keberlanjutan (sustainability) dan slow fashion dalam setiap karyanya. Melalui tangan-tangan terampil, Upject mengubah celana jeans bekas menjadi tas, sepatu, dan topi yang tidak hanya memiliki nilai estetika tinggi, tetapi juga berdampak positif pada lingkungan. Setiap produk yang dihasilkan memiliki cerita dan karakteristik unik, menjadikan Upject pionir dalam gerakan fashion ramah lingkungan di Indonesia.<o:p></o:p></p>', '2022-02-16', '2023-12-16', '2025-10-16 09:11:58', '2025-10-16 09:11:58');
INSERT INTO `tenant` VALUES (6170, 1365, 'public/foto_profil_tenant/68f059d37ce6e.jpg', 'Bitka', 'Samuel Valentine S', 20, 1, 'Jl. Tanjung. Blok J2 No.20, RT.10/RW.1, Rw. Buntu, Kec. Serpong', NULL, NULL, 'https://www.bitkagallery.com/link/', NULL, NULL, '<ul jscontroller=\"M2ABbc\" jsaction=\"jZtoLb:SaHfyb\" data-hveid=\"CBMQAQ\" data-ved=\"2ahUKEwjTzsGc16eQAxXZwjgGHUCdBjQQm_YKegQIExAB\" style=\"margin-top: 10px; margin-bottom: 20px; font-size: 16px; line-height: 24px; padding-inline-start: 24px; color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif;\"><li style=\"margin-bottom: 8px; padding-left: 4px; list-style: inherit;\"><div class=\"zMgcWd dSKvsb\" data-il=\"\" style=\"border-bottom: none;\"><div data-crb-p=\"\"><div class=\"xFTqob\" style=\"flex: 1 1 0%; min-width: 0px;\"><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"2426655742241693887\">Bitka adalah merek sepatu lokal yang awalnya berasal dari Jakarta, namun sekarang berpusat di Tangerang Selatan. Bitka</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"2426655742241695754\">&nbsp;menjual berbagai jenis sepatu kets atau sneakers dan kini juga merambah ke produk pakaian lainnya.&nbsp;</span></div><div class=\"Gur8Ad\" style=\"line-height: 24px; overflow: hidden; padding-bottom: 4px; transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); display: inline;\"><span data-huuid=\"2426655742241694268\"><strong>Filosofi nama</strong>:&nbsp;</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"2426655742241697621\">Nama \"Bitka\" diambil dari singkatan Bhinneka Tunggal Ika, melambangkan berbagai langkah yang berbeda namun tetap bersatu pada satu tujuan.</span></div></div></div></div></li></ul>', '2022-02-16', '2023-12-16', '2025-10-16 09:34:59', '2025-10-16 09:34:59');
INSERT INTO `tenant` VALUES (6171, 1365, 'public/foto_profil_tenant/68f05abf120b6.png', 'Artemis Ethereal', 'Muhammad Rizki Satria Putra', NULL, NULL, 'Jln. Letkol komir kartaman No.39  Kota Tasikmalaya Kec Tawang', NULL, NULL, 'https://www.instagram.com/artemis.ethereal/', NULL, NULL, '<p><span data-huuid=\"11504886741797221755\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\">Artemis Ethereal adalah&nbsp;<mark class=\"QVRyCf\" style=\"background: linear-gradient(90deg, rgb(212, 228, 242) 50%, rgba(0, 0, 0, 0) 50%) 75% 0px / 200% 100% no-repeat scroll padding-box border-box rgba(0, 0, 0, 0); border-radius: 4px; padding: 0px 2px; animation: 0.75s cubic-bezier(0.05, 0.7, 0.1, 1) 0.25s 1 normal forwards running highlight-animation;\">merek sepatu asal Indonesia yang berfokus pada sepatu kasual (sneakers) dengan desain yang unik dan menawan.&nbsp;</mark></span><span style=\"color: rgb(0, 0, 0); font-family: -apple-system, &quot;system-ui&quot;, &quot;Segoe UI&quot;, Roboto, Helvetica, Arial, sans-serif;\">Introducing Art Through Fashion menjadi cirikhas brand ini, karena</span><span data-huuid=\"11504886741797221755\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\">&nbsp;AE</span><span data-huuid=\"11504886741797220972\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\">&nbsp;menampilkan produk sepatu dengan gaya modern dan seringkali mengambil inspirasi dari karya seni maupun budaya lokal untuk menciptakan desain yang khas.<span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"ac5d395c-fdc7-4440-a8ab-0ecbb0cf0345\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></span></p>', '2022-02-16', '2023-12-16', '2025-10-16 09:38:55', '2025-10-16 09:38:55');
INSERT INTO `tenant` VALUES (6172, 1365, 'public/foto_profil_tenant/68f05bd980ed5.png', 'Arlenne', 'Wini Intan Paramitha', 20, 1, 'Jl. Mekar Laksana No.16C, Mekarwangi, Kec. Bojongloa Kidul, Kota Bandung, Jawa Barat 40236', NULL, NULL, 'https://www.instagram.com/arlenne_official/', NULL, NULL, '<p data-start=\"129\" data-end=\"451\"><strong data-start=\"129\" data-end=\"140\">ARLENNE</strong><br data-start=\"140\" data-end=\"143\">\r\nBrand sepatu wanita asal Indonesia yang dikenal dengan konsep <em data-start=\"205\" data-end=\"224\">“pain-free heels”</em> — menghadirkan kenyamanan tanpa mengorbankan gaya. Setiap koleksi Arlenne dirancang dengan detail elegan, material premium, dan konstruksi ergonomis untuk menemani langkah percaya diri para wanita di setiap momen spesialnya.</p><p>\r\n</p><p data-start=\"453\" data-end=\"769\">Melalui desain yang feminin dan modern, Arlenne menawarkan berbagai pilihan <em data-start=\"529\" data-end=\"543\">custom heels</em>, mulai dari sepatu pesta, pernikahan, hingga koleksi harian. Dengan showroom di Bandung dan layanan pemesanan daring, Arlenne menjadi pilihan utama bagi mereka yang mencari perpaduan sempurna antara estetika dan kenyamanan.</p>', '2022-02-16', '2023-12-16', '2025-10-16 09:43:37', '2025-10-16 09:43:37');
INSERT INTO `tenant` VALUES (6173, 1365, 'public/foto_profil_tenant/68f1aa8249857.png', 'Frogo Sandal', 'Jiwha Rocky Ardila', 20, 1, 'Jl Tobong tengah 1 potrosaran baru Gang 2 No 03 RT013 RW 001 Potrobangsan Magelang Utara', NULL, NULL, NULL, NULL, NULL, '<div class=\"WaaZC\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\"><div class=\"RJPOee EIJn2\" style=\"animation: auto ease 0s 1 normal none running none !important;\"><div class=\"rPeykc uP58nb MNX06c\" data-hveid=\"CCoQAQ\" data-ved=\"2ahUKEwiexsjxl6qQAxUJ1TgGHc6ZOgoQo_EKegQIKhAB\" style=\"margin-bottom: 10px; line-height: 24px; hyphens: auto;\"><span data-huuid=\"6106377835862777476\">Frogo Sandal adalah&nbsp;<mark class=\"QVRyCf\" style=\"background: linear-gradient(90deg, rgb(212, 228, 242) 50%, rgba(0, 0, 0, 0) 50%) 75% 0px / 200% 100% no-repeat scroll padding-box border-box rgba(0, 0, 0, 0); border-radius: 4px; padding: 0px 2px; animation: 0.75s cubic-bezier(0.05, 0.7, 0.1, 1) 0.25s 1 normal forwards running highlight-animation;\">merek alas kaki lokal yang memproduksi sandal berkualitas tinggi dengan desain unik, termasuk sandal karakter kartun, sandal batik, dan sandal custom untuk berbagai kebutuhan seperti arisan atau disabilitas</mark>.&nbsp;</span><span data-huuid=\"6106377835862776703\">Selain sandal, Frogo juga menghasilkan produk lain seperti bantal dan tas, serta melayani kebutuhan merchandise promosi.&nbsp;</span><span data-huuid=\"6106377835862775930\">Merek ini berfokus pada kustomisasi, kenyamanan, dan keberlanjutan budaya Indonesia.&nbsp;</span></div><div class=\"rPeykc uP58nb MNX06c\" data-hveid=\"CCoQAQ\" data-ved=\"2ahUKEwiexsjxl6qQAxUJ1TgGHc6ZOgoQo_EKegQIKhAB\" style=\"margin-bottom: 10px; line-height: 24px; hyphens: auto;\"><span data-huuid=\"6106377835862775930\"><br></span><div class=\"Gur8Ad\" style=\"line-height: 24px; overflow: hidden; padding-bottom: 4px; transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); display: inline;\"><span data-huuid=\"6106377835862776161\"><strong>Produk Utama</strong>:&nbsp;</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862775388\">Sandal dengan desain beragam, seperti sandal karakter (kodok, rubah), sandal batik, dan sandal custom kulit.</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862775388\"><br></span></div><div class=\"Gur8Ad\" style=\"line-height: 24px; overflow: hidden; padding-bottom: 4px; transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); display: inline;\"><span data-huuid=\"6106377835862773842\"><strong>Layanan Tambahan</strong>:&nbsp;</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862777165\">Menawarkan sandal untuk kebutuhan khusus seperti sandal disabilitas yang dapat dikustomisasi tinggi dan panjangnya, serta menyediakan produk lain seperti bantal dan tas.<span style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862777165\"><span style=\"text-wrap-mode: nowrap;\"><br></span></span></div><div class=\"Gur8Ad\" style=\"line-height: 24px; overflow: hidden; padding-bottom: 4px; transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); display: inline;\"><span data-huuid=\"6106377835862775619\"><strong>Fokus Merek</strong>:&nbsp;</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862774846\">Menggabungkan kenyamanan, gaya, keceriaan, dan nilai budaya Indonesia dalam setiap produknya.<span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"eed118c0-679d-4d3c-92a1-0d1de7c797b7\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862774846\"><span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"eed118c0-679d-4d3c-92a1-0d1de7c797b7\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\"><br></span></span></span></div><div class=\"Gur8Ad\" style=\"line-height: 24px; overflow: hidden; padding-bottom: 4px; transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); display: inline;\"><span data-huuid=\"6106377835862777396\"><strong>Kustomisasi</strong>:&nbsp;</span></div><div class=\"vM0jzc\" style=\"line-height: 24px; display: inline;\"><span data-huuid=\"6106377835862776623\">Kemampuan untuk membuat sandal sesuai pesanan, termasuk untuk berbagai acara atau kebutuhan individu.<span jscontroller=\"JHnpme\" class=\"pjBG2e\" data-cid=\"e6c5eac4-2f7a-4eee-b4d7-82525e99801c\" jsaction=\"rcuQ6b:npT2md\"><span class=\"UV3uM\" style=\"text-wrap-mode: nowrap;\">&nbsp;</span></span></span></div></div></div></div><div class=\"WaaZC\" style=\"color: rgb(0, 29, 53); font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px;\"><div class=\"RJPOee EIJn2\" style=\"animation: auto ease 0s 1 normal none running none !important;\"><ul jscontroller=\"M2ABbc\" jsaction=\"jZtoLb:SaHfyb\" data-hveid=\"CCkQAQ\" data-ved=\"2ahUKEwiexsjxl6qQAxUJ1TgGHc6ZOgoQm_YKegQIKRAB\" style=\"margin-top: 10px; margin-bottom: 20px; line-height: 24px; padding-inline-start: 24px;\"><li style=\"margin-bottom: 8px; padding-left: 4px; list-style: inherit;\"><div class=\"zMgcWd dSKvsb\" data-il=\"\" style=\"border-bottom: none;\"><div data-crb-p=\"\"><div class=\"xFTqob\" style=\"flex: 1 1 0%; min-width: 0px;\"><br></div></div></div></li></ul></div></div>', '2023-04-17', '2024-12-17', '2025-10-17 09:31:30', '2025-10-17 09:31:30');
INSERT INTO `tenant` VALUES (6174, 1365, 'public/foto_profil_tenant/68f1abd2abb7c.jpg', 'Kupu Sutera', 'R Arianto Nugroho Eko P', 20, 1, 'Jl. Ahmad Yani, Gg Merpati I, Perum Patal, No. 09 Popohan, Gg. Merpati I perumahan patal No.9, Sumping Wetan, Sentul, Kec. Purwodadi, Pasuruan, Jawa Timur 65213', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(71, 71, 71); font-family: Arial, sans-serif;\">Sustainable Silk &amp; Natural Fiber Innovation. Kupu Sutera specializes in eco-friendly textiles crafted from Samia silk and natural fibers. Combining traditional techniques and modern research, we create premium fabrics, fashion, footwear, accessories, and home textiles with natural dyes and ethical production. We collaborate with local farmers, artisans, and researchers to preserve Indonesia’s rich textile heritage while promoting sustainability and community empowerment.</span></p>', '2023-04-17', '2024-12-17', '2025-10-17 09:37:06', '2025-10-17 09:37:06');
INSERT INTO `tenant` VALUES (6175, 1365, 'public/foto_profil_tenant/68f1ac99bc6ba.png', 'Eco Paliko', 'Chairunnisa Her Pamudji', 20, 1, 'Jorong Subarang Tabek, Nagari Situjuah Banda Dalam, Kec Situjuah Limo Nagari, Kabupaten Lima Puluh Kota, Sumatra Barat', NULL, NULL, NULL, NULL, NULL, '<p data-start=\"0\" data-end=\"202\"><strong data-start=\"0\" data-end=\"14\">Eco Paliko</strong> adalah salah satu <strong data-start=\"33\" data-end=\"117\">tenant inkubasi bisnis BPIPI (Balai Pengembangan Industri Persepatuan Indonesia)</strong> yang mengusung konsep <strong data-start=\"140\" data-end=\"199\" data-is-only-node=\"\">alas kaki berbasis keberlanjutan (sustainable footwear)</strong>.</p><p data-start=\"204\" data-end=\"395\">Brand ini menampilkan <strong data-start=\"226\" data-end=\"274\">model sandal tradisional asal Sumatera Barat</strong> yang dikemas secara <strong data-start=\"295\" data-end=\"310\">kontemporer</strong>, memadukan <strong data-start=\"322\" data-end=\"351\">warisan budaya (heritage)</strong> dengan <strong data-start=\"359\" data-end=\"392\">sentuhan alam dan seni modern</strong>.</p><p>\r\n\r\n</p><p data-start=\"397\" data-end=\"744\" data-is-last-node=\"\" data-is-only-node=\"\">Dengan tagline <strong data-start=\"412\" data-end=\"457\">“Contemporary art of nature and heritage”</strong>, Eco Paliko berupaya menghadirkan produk yang tidak hanya estetis, tetapi juga ramah lingkungan dan memiliki nilai budaya tinggi. Produk-produknya biasanya dibuat dengan <strong data-start=\"628\" data-end=\"646\">material alami</strong> dan desain yang <strong data-start=\"663\" data-end=\"697\">menghormati akar tradisi lokal</strong>, namun tetap cocok untuk gaya hidup masa kini.</p>', '2023-04-17', '2024-12-17', '2025-10-17 09:40:25', '2025-10-17 09:40:25');
INSERT INTO `tenant` VALUES (6176, 1365, 'public/foto_profil_tenant/68f1ae5a40ec0.png', 'Jejak Langkah', 'Astaria Eka Santi', NULL, NULL, 'Sejambu 02/05, Kesongo, Tuntang', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(71, 71, 71); font-family: Arial, sans-serif;\">Jejak langkah merupakan sebuah brand berbasis pemberdayaan masyarakat yang bergerak di industri fashion handcraft dari eceng gondok menjadi aneka kerajinan. Target pasarnya adalah orang-orang yang orientasi lifestylenya peduli dengan lingkungan. Dengan tagline “Upcycle Craft Made From Water Hyacinth” yang berarti brand ini menghasilkan produk dengan mengolah enceng gondok menjadi aneka kerajinan yang berguna dan eco-friendly.&nbsp;</span></p>', '2023-04-17', '2024-12-17', '2025-10-17 09:47:54', '2025-10-17 09:47:54');
INSERT INTO `tenant` VALUES (6177, 1365, 'public/foto_profil_tenant/68f1af2c91a69.png', 'SEVATU', 'Rifki Khairil Ulfah', 20, 1, 'Jl. Cijolang RT 01/05 Kel. Sukarindik, Kec. BungursariTasikmalaya Regency, West Java 46151', NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgb(71, 71, 71); font-family: Arial, sans-serif;\">Sevatu merupakan produsen sandal dan sepatu wanita hanmade premium di Tasikmalaya. model dibuat kekinian dengan bahan dasar premium dan berkualitas</span></p>', '2024-04-17', '2025-12-17', '2025-10-17 09:51:24', '2025-10-17 09:51:24');
INSERT INTO `tenant` VALUES (6178, 1365, 'public/foto_profil_tenant/68f1b066574c1.png', 'SOLEVENTURE (PSB Platform)', 'Shofawaty Nur Islamiyah', 20, 1, 'Kompleks Joglo Baru Blok B no.7 RT 007/06 Joglo, Kembangan', NULL, NULL, NULL, NULL, NULL, '<p><strong data-start=\"0\" data-end=\"16\" data-is-only-node=\"\">SoleVentures</strong> adalah platform dari PSB (Produsen Sepatu Bogor) &nbsp;yang berfokus pada pembuatan alas kaki berkualitas tinggi dengan standar profesional. Mengusung konsep sebagai <strong data-start=\"166\" data-end=\"204\">platform produksi sepatu Indonesia</strong>, SoleVentures melayani berbagai kebutuhan, mulai dari sepatu kasual hingga sepatu dinas (PDL), dengan perhatian pada kenyamanan, ketahanan, dan detail desain. Melalui proses produksi yang terukur dan tim berpengalaman, SoleVentures berkomitmen menghadirkan produk yang tidak hanya fungsional, tetapi juga mencerminkan dedikasi terhadap kualitas dan gaya.</p>', '2024-04-17', '2025-12-17', '2025-10-17 09:56:38', '2025-10-17 09:57:32');
INSERT INTO `tenant` VALUES (6179, 1365, 'public/foto_profil_tenant/68f1b14547eda.png', 'Dunia Industri Tangguh (Tid\'s Crochet)', 'Pradita Rahmawati', NULL, NULL, 'Jalan Berlian 3 No. 332 Perumahan Ambarawa Asri, Bawen', NULL, NULL, NULL, NULL, NULL, '<p>Dunia Industri Tangguh mengusung tema ecco-friendly dan sustainable produk dengan menggabungkan produk rajut dengan enceng gondok. Selain itu kami juga bekerjasama dengan kelompok pemberdayan perempuan dan disabilitas yang ada di Kabupaten Semarang. Merek yang ada dipasaran adalah Tids Crochet</p>', '2024-04-17', '2025-12-17', '2025-10-17 10:00:21', '2025-10-17 10:00:54');
INSERT INTO `tenant` VALUES (6180, 1365, NULL, 'z AKAWA', 'Nurul Hamama', 20, 1, 'BTN PUSKOPAD BENTENG Jl Kutilang Blok U/3 Rt 02/Rw 07 Ciampea Bogor 16620', NULL, NULL, NULL, NULL, NULL, '<p>AKAWA Shoes merupakan brand alas kaki istimewa yang diproduksi secara handmade oleh PT Gembolan Inang Creative Indonesia. Dengan bahan baku kulit grade A dan material organik, AKAWA menghadirkan sepatu yang tidak hanya nyaman dan fungsional, tetapi juga stylish. Fokus utama brand ini adalah menciptakan alas kaki khusus untuk mendukung kebutuhan ortopedi, tanpa mengorbankan estetika desain. AKAWA hadir sebagai solusi bagi mereka yang membutuhkan alas kaki medis namun tetap ingin tampil percaya diri.</p>', '2024-04-17', '2025-12-17', '2025-10-17 10:06:53', '2025-10-17 10:07:16');
INSERT INTO `tenant` VALUES (6181, 134, 'public/foto_profil_tenant/68f5934b5eb03.png', 'Koperasi Konsumen Karya Sejahtera Indonesia', 'Koperasi Konsumen Karya Sejahtera Indonesia', NULL, NULL, 'Jl. Prof Dr. G. A. Siwabessy Kampus UI Depok, Kota Depok, Jawa Barat', NULL, '3.453.290.250,00', '@kopkars.id', 'Dalam Negeri', 'Aplikasi', NULL, '2025-04-29', '2025-10-08', '2025-10-20 08:28:56', '2025-10-20 09:18:31');
INSERT INTO `tenant` VALUES (6182, 134, 'public/foto_profil_tenant/68f59958d7337.png', 'Koperasi Konsumen Dewan Masjid Indonesia Karang tengah', 'Koperasi Konsumen Dewan Masjid Indonesia Karang tengah', NULL, NULL, 'Kompleks Metro Permata Blok N 8, RT 02 RW 7, Banten Tangerang', NULL, '100.000.000,00', NULL, 'Dalam Negeri', 'Aplikasi', '<p><br></p>', '2025-04-29', '2025-10-08', '2025-10-20 09:07:20', '2025-10-20 09:07:20');
