INSERT INTO `tenant` VALUES (6340, 51, 'public/foto_profil_tenant/69318030555c5.jpg', 'Triluve', 'Ani Siti Harnisah', 23, 7, 'Jl. Gaber No. 24 RT 013/ 001 Lubang Buaya, Ciipayung Jakarta Timur', NULL, '100.000,00', 'Instagram, Whatsapp', 'DKI JAKARTA dan Sekitarnya', 'Manual', '<p>Triluv adalah Produsen dan Distributor kue kering, bolu, dan Brownies. salah satu produk yang paling laris adalah kue bangket djahe&nbsp; ( Kue Jahe )&nbsp;</p>', '2025-01-01', '2025-01-11', '2025-12-04 19:36:00', '2025-12-04 19:36:00');
